export const CARDS = {"a_hallo":{"lemma":"hallo","displayNl":"hallo","pos":"tussenwerpsel","meanings":[{"de":"hallo","ex":"Hallo, ik ben nieuw hier.","exDe":"Hallo, ich bin neu hier."},{"de":"hallo (am Telefon)","ex":"Hallo, met wie spreek ik?","exDe":"Hallo, mit wem spreche ich?"}],"usage":"Informelle Begrüßung zu jeder Tageszeit; auch als Ausruf, um Aufmerksamkeit zu erregen."},"a_benik":{"lemma":"zijn","displayNl":"zijn","pos":"werkwoord","meanings":[{"de":"sein","ex":"Ik ben Carlsson.","exDe":"Ich bin Carlsson."},{"de":"sich befinden / da sein","ex":"Waar ben je nu?","exDe":"Wo bist du jetzt?"}],"usage":"Unregelmäßiges Grund- und Hilfsverb (Kopula). Bildet zugleich das Perfekt vieler Bewegungs- und Zustandsverben.","conjugation":{"presens":{"ik":"ben","jij":"bent","hij":"is","wij":"zijn"},"imperfectum":{"ik":"was","wij":"waren"},"perfectum":{"aux":"zijn","participle":"geweest"}}},"a_heet":{"lemma":"heten","displayNl":"heten","pos":"werkwoord","meanings":[{"de":"heißen (Namen tragen)","ex":"Ik heet Carlsson.","exDe":"Ich heiße Carlsson."},{"de":"heißen / bedeuten","ex":"Wat heet dat woord in het Duits?","exDe":"Was heißt dieses Wort auf Deutsch?"}],"usage":"Wird zur Nennung des eigenen Namens benutzt: 'Ik heet ...'. Frageform: 'Hoe heet je?'.","conjugation":{"presens":{"ik":"heet","jij":"heet","hij":"heet","wij":"heten"},"imperfectum":{"ik":"heette","wij":"heetten"},"perfectum":{"aux":"hebben","participle":"geheten"}}},"a_hoeheet":{"lemma":"hoe heet je?","displayNl":"hoe heet je?","pos":"uitdrukking","meanings":[{"de":"wie heißt du?","ex":"Hoe heet je?","exDe":"Wie heißt du?"},{"de":"wie heißen Sie? (förmlich: hoe heet u?)","ex":"Hoe heet u?","exDe":"Wie heißen Sie?"}],"usage":"Standardfrage nach dem Namen. Informell mit 'je', höflich/förmlich mit 'u'. Antwort meist mit 'Ik heet ...' oder 'Ik ben ...'."},"a_aangenaam":{"lemma":"aangenaam","displayNl":"aangenaam","pos":"adjectief","meanings":[{"de":"freut mich / angenehm (bei der Vorstellung)","ex":"Aangenaam, ik ben Eni.","exDe":"Freut mich, ich bin Eni."},{"de":"angenehm / behaglich","ex":"Het is een aangename temperatuur vandaag.","exDe":"Es ist eine angenehme Temperatur heute."}],"usage":"Als Kurzformel 'Aangenaam!' beim Kennenlernen ('freut mich'). Als Adjektiv beschreibt es etwas Angenehmes; attributiv flektiert: 'een aangename sfeer'."},"a_komuit":{"lemma":"komen","displayNl":"komen","pos":"werkwoord","meanings":[{"de":"kommen","ex":"Ik kom uit Duitsland.","exDe":"Ich komme aus Deutschland."},{"de":"ankommen / eintreffen","ex":"De trein komt om acht uur.","exDe":"Der Zug kommt um acht Uhr."},{"de":"herkommen / stammen aus (komen uit)","ex":"Waar kom je vandaan?","exDe":"Woher kommst du?"}],"usage":"Unregelmäßiges Bewegungsverb, Perfekt mit 'zijn'. Herkunft wird mit 'komen uit' ausgedrückt: 'Ik kom uit ...'.","conjugation":{"presens":{"ik":"kom","jij":"komt","hij":"komt","wij":"komen"},"imperfectum":{"ik":"kwam","wij":"kwamen"},"perfectum":{"aux":"zijn","participle":"gekomen"}}},"a_nieuw":{"lemma":"nieuw","displayNl":"nieuw","pos":"adjectief","meanings":[{"de":"neu","ex":"We zijn nieuw hier.","exDe":"Wir sind neu hier."},{"de":"neu / neuartig / frisch","ex":"Ik heb een nieuwe fiets.","exDe":"Ich habe ein neues Fahrrad."}],"usage":"Adjektiv; attributiv flektiert zu 'nieuwe' (de nieuwe / het nieuwe / een nieuwe). In 'nieuw hier' bedeutet es 'neu an einem Ort, gerade angekommen'."},"wo_huis":{"lemma":"huis","displayNl":"het huis","pos":"substantief","meanings":[{"de":"das Haus (Gebäude)","ex":"Dit is ons huis.","exDe":"Das ist unser Haus."},{"de":"das Zuhause / Heim","ex":"Ik ben om zes uur weer thuis.","exDe":"Ich bin um sechs Uhr wieder zu Hause."}],"usage":"Sächliches Substantiv (het-Wort), Plural 'huizen'. Häufig in festen Wendungen wie 'naar huis' (nach Hause) und 'thuis' (zu Hause).","genus":"het","plural":"huizen","illustratable":true},"wo_kat":{"lemma":"kat","displayNl":"de kat","pos":"substantief","meanings":[{"de":"die Katze (Tier)","ex":"De kat heet Nalani.","exDe":"Die Katze heißt Nalani."},{"de":"die Katze (weibliches Tier, im Gegensatz zum Kater)","ex":"Onze kat heeft vier jongen gekregen.","exDe":"Unsere Katze hat vier Junge bekommen."}],"usage":"Alltagswort für die Hauskatze; das männliche Tier heißt 'de kater'. Betont 'de'-Wort.","genus":"de","plural":"katten","illustratable":true},"wo_wonen":{"lemma":"wonen","displayNl":"wonen","pos":"werkwoord","meanings":[{"de":"wohnen, leben (an einem Ort)","ex":"Wij wonen nu in Utrecht.","exDe":"Wir wohnen jetzt in Utrecht."},{"de":"ansässig sein, seinen Wohnsitz haben","ex":"Zij woont al tien jaar in dezelfde straat.","exDe":"Sie wohnt schon zehn Jahre in derselben Straße."}],"usage":"Regelmäßiges Verb; Hilfsverb 'hebben'. Ort wird meist mit 'in' angeschlossen (in Utrecht wonen).","conjugation":{"presens":{"ik":"woon","jij":"woont","hij":"woont","wij":"wonen"},"imperfectum":{"ik":"woonde","wij":"woonden"},"perfectum":{"aux":"hebben","participle":"gewoond"}}},"wo_kamer":{"lemma":"kamer","displayNl":"de kamer","pos":"substantief","meanings":[{"de":"das Zimmer, der Raum","ex":"Het huis heeft drie kamers.","exDe":"Das Haus hat drei Zimmer."},{"de":"die Kammer (parlamentarisch, z. B. Tweede Kamer)","ex":"De Tweede Kamer stemt vandaag over de wet.","exDe":"Die Zweite Kammer stimmt heute über das Gesetz ab."}],"usage":"'de'-Wort. In der Politik großgeschrieben 'de Kamer' (Parlamentskammer); im Alltag das Wohn-/Zimmer.","genus":"de","plural":"kamers","illustratable":true},"wo_hebik":{"lemma":"hebben","displayNl":"hebben","pos":"werkwoord","meanings":[{"de":"haben, besitzen","ex":"Ik heb een kleine studio.","exDe":"Ich habe ein kleines Studio."},{"de":"haben (als Hilfsverb für das Perfekt)","ex":"Wij hebben gisteren gewerkt.","exDe":"Wir haben gestern gearbeitet."}],"usage":"Unregelmäßiges Verb; wichtigstes Hilfsverb für das Perfekt. Roh-Eintrag 'ik heb' = Präsens 1. Person.","conjugation":{"presens":{"ik":"heb","jij":"hebt","hij":"heeft","wij":"hebben"},"imperfectum":{"ik":"had","wij":"hadden"},"perfectum":{"aux":"hebben","participle":"gehad"}}},"wo_eris":{"lemma":"er zijn","displayNl":"er is / er zijn","pos":"uitdrukking","meanings":[{"de":"es gibt (Singular: er is)","ex":"Er is geen tuin.","exDe":"Es gibt keinen Garten."},{"de":"es gibt (Plural: er zijn)","ex":"Er zijn veel planten.","exDe":"Es gibt viele Pflanzen."}],"usage":"Existenz-Konstruktion mit Platzhalter 'er'. Verb richtet sich nach dem Bezugswort: 'er is' + Singular, 'er zijn' + Plural."},"wo_geen":{"lemma":"geen","displayNl":"geen","pos":"voornaamwoord","meanings":[{"de":"kein, keine (Verneinung von 'een' / unbestimmten Mengen)","ex":"Er is geen tuin.","exDe":"Es gibt keinen Garten."},{"de":"kein einziger, gar kein","ex":"Ik heb geen tijd.","exDe":"Ich habe keine Zeit."}],"usage":"Verneint unbestimmte Substantive (statt 'een' oder ohne Artikel). Bestimmte Substantive und Verben werden dagegen mit 'niet' verneint."},"b_brood":{"lemma":"brood","displayNl":"het brood","pos":"substantief","meanings":[{"de":"das Brot (Laib)","ex":"Ik wil een vers brood.","exDe":"Ich möchte ein frisches Brot."},{"de":"das Brot (Stoff, Nahrung allgemein)","ex":"Wij eten elke ochtend brood.","exDe":"Wir essen jeden Morgen Brot."}],"usage":"'het'-Wort. Als abzählbarer Laib mit Plural 'broden'; als Nahrungsmittel unzählbar.","genus":"het","plural":"broden","illustratable":true},"b_broodje":{"lemma":"broodje","displayNl":"het broodje","pos":"substantief","meanings":[{"de":"das Brötchen, die Semmel","ex":"Mag ik twee broodjes?","exDe":"Kann ich zwei Brötchen haben?"},{"de":"das belegte Brötchen (Sandwich zum Mitnehmen)","ex":"Zij eet een broodje kaas als lunch.","exDe":"Sie isst ein Käsebrötchen zum Mittag."}],"usage":"'het'-Wort, Verkleinerungsform von 'brood'. In den Niederlanden oft ein belegtes Brötchen (broodje kaas, broodje kroket).","genus":"het","plural":"broodjes","illustratable":true},"b_graag":{"lemma":"willen","displayNl":"willen","pos":"werkwoord","meanings":[{"de":"möchten (höflich, mit graag)","ex":"Ik wil graag een broodje.","exDe":"Ich möchte gerne ein Brötchen."},{"de":"wollen","ex":"Wat wil je vanavond doen?","exDe":"Was willst du heute Abend machen?"}],"usage":"Modalverb; hoofl. Wunsch meist mit 'graag' ('ik wil graag ...' = ich möchte gerne). jij-Form 'wilt' oder umgangssprachlich 'wil'. Imperfekt auch 'wou/wouden'.","conjugation":{"presens":{"ik":"wil","jij":"wilt","hij":"wil","wij":"willen"},"imperfectum":{"ik":"wilde","wij":"wilden"},"perfectum":{"aux":"hebben","participle":"gewild"}}},"b_alstublieft":{"lemma":"alstublieft","displayNl":"alstublieft","pos":"tussenwerpsel","meanings":[{"de":"bitte (höfliche Bitte)","ex":"Een brood, alstublieft.","exDe":"Ein Brot, bitte."},{"de":"bitte sehr / hier (beim Überreichen)","ex":"Alstublieft, hier is uw wisselgeld.","exDe":"Bitte sehr, hier ist Ihr Wechselgeld."}],"usage":"Höfliche Sie-Form (aus 'als het u belieft'). Vertrauliche Du-Form: 'alsjeblieft'. Sowohl als Bitte als auch beim Überreichen benutzt."},"b_dankuwel":{"lemma":"dank u wel","displayNl":"dank u wel","pos":"uitdrukking","meanings":[{"de":"danke schön (höflich, Sie-Form)","ex":"Dank u wel voor uw hulp.","exDe":"Vielen Dank für Ihre Hilfe."}],"usage":"Höfliche Sie-Form. Vertraulich: 'dank je wel'. Kürzer: 'dank u' / 'bedankt'."},"b_hoeveel":{"lemma":"hoeveel","displayNl":"hoeveel","pos":"bijwoord","meanings":[{"de":"wie viel","ex":"Hoeveel kost het?","exDe":"Wie viel kostet es?"},{"de":"wie viele","ex":"Hoeveel broodjes wil je?","exDe":"Wie viele Brötchen möchtest du?"}],"usage":"Fragewort für Menge/Preis. Vor zählbaren wie unzählbaren Substantiven ('hoeveel appels', 'hoeveel melk')."},"b_lekker":{"lemma":"lekker","displayNl":"lekker","pos":"adjectief","meanings":[{"de":"lecker, wohlschmeckend","ex":"Dat broodje is heel lekker.","exDe":"Das Brötchen ist sehr lecker."},{"de":"angenehm, schön (Wetter, Gefühl)","ex":"Wat een lekker weer vandaag!","exDe":"Was für ein schönes Wetter heute!"},{"de":"gut, wohlig (Adverb: gut/behaglich etwas tun)","ex":"Ik heb lekker geslapen.","exDe":"Ich habe gut geschlafen."}],"usage":"Sehr häufiges Alltagswort, weit über Essen hinaus (lekker weer, lekker rustig, lekker slapen). Steigerung: lekkerder, lekkerst."},"bo_winkel":{"lemma":"winkel","displayNl":"de winkel","pos":"substantief","meanings":[{"de":"der Laden, das Geschäft","ex":"De winkel op de hoek is open.","exDe":"Der Laden an der Ecke ist geöffnet."}],"usage":"Allgemeines Wort für Geschäft; zusammengesetzt z. B. 'kledingwinkel', 'boekwinkel'. Plural 'winkels'.","genus":"de","plural":"winkels","illustratable":true},"bo_boodschappen":{"lemma":"boodschappen doen","displayNl":"boodschappen doen","pos":"uitdrukking","meanings":[{"de":"einkaufen, Besorgungen (Lebensmittel) machen","ex":"Ik ga vanmiddag boodschappen doen.","exDe":"Ich gehe heute Nachmittag einkaufen."}],"usage":"Feste Wendung für den (Lebensmittel-)Einkauf. 'de boodschappen' = die Einkäufe/Besorgungen; im Singular 'de boodschap' auch = Nachricht/Botschaft.","illustratable":true},"bo_melk":{"lemma":"melk","displayNl":"de melk","pos":"substantief","meanings":[{"de":"die Milch","ex":"We hebben nog melk nodig.","exDe":"Wir brauchen noch Milch."}],"usage":"Unzählbares Stoffsubstantiv, meist ohne Plural; für Sorten selten 'melken'. Zusammensetzungen: 'halfvolle melk', 'karnemelk'.","genus":"de","illustratable":true},"bo_kaas":{"lemma":"kaas","displayNl":"de kaas","pos":"substantief","meanings":[{"de":"der Käse","ex":"Hollandse kaas is wereldberoemd.","exDe":"Holländischer Käse ist weltberühmt."},{"de":"das Käsestück / der Käselaib (auf dem Markt)","ex":"Op de markt kocht ik een hele kaas.","exDe":"Auf dem Markt kaufte ich einen ganzen Käselaib."}],"usage":"Alltagswort; op de markt/in de winkel. 'een plakje kaas' = eine Scheibe Käse.","genus":"de","plural":"kazen","illustratable":true},"bo_kopje":{"lemma":"kopje","displayNl":"het kopje","pos":"substantief","meanings":[{"de":"das Tässchen / die kleine Tasse","ex":"Wil je een kopje thee?","exDe":"Möchtest du ein Tässchen Tee?"},{"de":"das Köpfchen / der kleine Kopf","ex":"Het poesje stak zijn kopje omhoog.","exDe":"Das Kätzchen streckte sein Köpfchen empor."}],"usage":"Verkleinerung von 'kop' (Tasse/Kopf). Meist 'een kopje koffie/thee'.","genus":"het","plural":"kopjes","illustratable":true},"bo_samen":{"lemma":"samen","displayNl":"samen","pos":"bijwoord","meanings":[{"de":"zusammen / gemeinsam","ex":"We doen het samen.","exDe":"Wir machen es zusammen."},{"de":"zusammen (Gesamtbetrag), insgesamt","ex":"Dat is samen twaalf euro.","exDe":"Das macht zusammen zwölf Euro."}],"usage":"Adverb; im Roheintrag als 'alles samen' (= alles zusammen) an der Kasse."},"bo_pinnen":{"lemma":"pinnen","displayNl":"pinnen","pos":"werkwoord","meanings":[{"de":"mit (EC-/Debit-)Karte zahlen","ex":"Kan ik hier pinnen?","exDe":"Kann ich hier mit Karte zahlen?"},{"de":"Geld am Automaten abheben","ex":"Ik moet nog even pinnen bij de geldautomaat.","exDe":"Ich muss noch schnell am Geldautomaten Geld abheben."}],"usage":"Typisch niederländisch fürs Kartenzahlen; 'pinnen' vs. 'contant betalen' (bar).","conjugation":{"presens":{"ik":"pin","jij":"pint","hij":"pint","wij":"pinnen"},"imperfectum":{"ik":"pinde","wij":"pinden"},"perfectum":{"aux":"hebben","participle":"gepind"}},"illustratable":true},"t_hoelaat":{"lemma":"hoe laat is het?","displayNl":"hoe laat is het?","pos":"uitdrukking","meanings":[{"de":"wie spät ist es?","ex":"Sorry, hoe laat is het?","exDe":"Entschuldigung, wie spät ist es?"}],"usage":"Feste Frageformel nach der Uhrzeit. Wörtlich 'wie spät ist es?'."},"t_tijd":{"lemma":"tijd","displayNl":"de tijd","pos":"substantief","meanings":[{"de":"die Zeit","ex":"Ik heb geen tijd vandaag.","exDe":"Ich habe heute keine Zeit."},{"de":"die Zeit(en), Epoche/Periode","ex":"In vroeger tijden was alles anders.","exDe":"In früheren Zeiten war alles anders."},{"de":"die Zeitform (Grammatik)","ex":"De verleden tijd van 'gaan' is 'ging'.","exDe":"Die Vergangenheitsform von 'gaan' ist 'ging'."}],"usage":"Sehr häufiges Wort; 'op tijd' = pünktlich, 'de hele tijd' = die ganze Zeit.","genus":"de","plural":"tijden"},"t_vandaag":{"lemma":"vandaag","displayNl":"vandaag","pos":"bijwoord","meanings":[{"de":"heute","ex":"Vandaag is het mooi weer.","exDe":"Heute ist schönes Wetter."},{"de":"heutzutage (in 'vandaag de dag')","ex":"Vandaag de dag heeft iedereen een smartphone.","exDe":"Heutzutage hat jeder ein Smartphone."}],"usage":"Zeitadverb; 'vandaag de dag' = heutzutage."},"t_uur":{"lemma":"uur","displayNl":"het uur","pos":"substantief","meanings":[{"de":"die Stunde (Zeitdauer)","ex":"De film duurt twee uur.","exDe":"Der Film dauert zwei Stunden."},{"de":"die Uhr(zeit), volle Stunde (bei Zeitangaben)","ex":"De trein vertrekt om drie uur.","exDe":"Der Zug fährt um drei Uhr ab."}],"usage":"Im Roheintrag 'om drie uur' = um drei Uhr. Bei Uhrzeit bleibt 'uur' unverändert (om drie uur).","genus":"het","plural":"uren","illustratable":true},"t_afspraak":{"lemma":"afspraak","displayNl":"de afspraak","pos":"substantief","meanings":[{"de":"der Termin","ex":"Ik heb morgen een afspraak bij de dokter.","exDe":"Ich habe morgen einen Termin beim Arzt."},{"de":"die Verabredung","ex":"We hebben om acht uur een afspraak in het café.","exDe":"Wir haben um acht Uhr eine Verabredung im Café."},{"de":"die Vereinbarung, die Abmachung","ex":"Een afspraak is een afspraak.","exDe":"Eine Abmachung ist eine Abmachung."}],"usage":"Alltagswort für Termin, Verabredung und Abmachung. Feste Wendung: 'een afspraak maken' = einen Termin/eine Verabredung ausmachen.","genus":"de","plural":"afspraken"},"t_kom":{"lemma":"komen","displayNl":"komen","pos":"werkwoord","meanings":[{"de":"kommen","ex":"Ik kom om drie uur.","exDe":"Ich komme um drei Uhr."},{"de":"ankommen, eintreffen","ex":"De trein komt te laat.","exDe":"Der Zug kommt zu spät."},{"de":"stammen, herkommen (uit)","ex":"Ik kom uit Duitsland.","exDe":"Ich komme aus Deutschland."}],"usage":"Sehr häufiges, unregelmäßiges Bewegungsverb. Perfekt mit 'zijn' (Bewegung/Ortsveränderung). Roheingabe 'ik kom' auf Infinitiv reduziert.","conjugation":{"presens":{"ik":"kom","jij":"komt","hij":"komt","wij":"komen"},"imperfectum":{"ik":"kwam","wij":"kwamen"},"perfectum":{"aux":"zijn","participle":"gekomen"}}},"t_telaat":{"lemma":"te laat","displayNl":"te laat","pos":"uitdrukking","meanings":[{"de":"zu spät","ex":"Ik ben nooit te laat.","exDe":"Ich bin nie zu spät."},{"de":"verspätet, mit Verspätung","ex":"Sorry, ik kom te laat.","exDe":"Entschuldigung, ich komme zu spät."}],"usage":"Feste Wendung aus 'te' + 'laat'; Gegenteil 'op tijd' (pünktlich). Kein eigenständiges Einzel-Lemma."},"w_waaris":{"lemma":"waar is...?","displayNl":"waar is...?","pos":"uitdrukking","meanings":[{"de":"wo ist...?","ex":"Waar is de platenzaak?","exDe":"Wo ist der Plattenladen?"},{"de":"wo befindet sich...?","ex":"Waar is het station?","exDe":"Wo ist der Bahnhof?"}],"usage":"Frageformel nach einem Ort; 'waar' (wo) + 'is' (ist). Für Mehrzahl 'waar zijn...?'."},"w_links":{"lemma":"links","displayNl":"links","pos":"bijwoord","meanings":[{"de":"links (Richtung)","ex":"Ga naar links.","exDe":"Geh nach links."},{"de":"linke Seite","ex":"De winkel staat aan de linkerkant, dus links.","exDe":"Der Laden ist auf der linken Seite, also links."},{"de":"links (politisch)","ex":"Die partij is links.","exDe":"Diese Partei ist links."}],"usage":"Richtungs- und Ortsadverb; Gegenteil 'rechts'. Wendung 'naar links' = nach links."},"w_rechts":{"lemma":"rechts","displayNl":"rechts","pos":"bijwoord","meanings":[{"de":"rechts (Richtung)","ex":"De winkel is rechts.","exDe":"Der Laden ist rechts."},{"de":"rechte Seite","ex":"Sla de eerste straat rechts af.","exDe":"Biege in die erste Straße rechts ab."},{"de":"rechts (politisch)","ex":"Hij stemt rechts.","exDe":"Er wählt rechts."}],"usage":"Richtungs- und Ortsadverb; Gegenteil 'links'. Wendung 'naar rechts' = nach rechts."},"w_rechtdoor":{"lemma":"rechtdoor","displayNl":"rechtdoor","pos":"bijwoord","meanings":[{"de":"geradeaus","ex":"Fiets rechtdoor.","exDe":"Fahr geradeaus."},{"de":"geradewegs, immer weiter geradeaus","ex":"Loop rechtdoor tot aan de brug.","exDe":"Geh geradeaus bis zur Brücke."}],"usage":"Richtungsadverb für Wegbeschreibungen; oft mit gaan/lopen/fietsen/rijden kombiniert."},"w_fiets":{"lemma":"fiets","displayNl":"de fiets","pos":"substantief","meanings":[{"de":"das Fahrrad","ex":"Ik ga met de fiets naar mijn werk.","exDe":"Ich fahre mit dem Rad zur Arbeit."},{"de":"das Rad (Kurzform)","ex":"Mijn fiets staat voor de deur.","exDe":"Mein Rad steht vor der Tür."}],"usage":"Alltäglichstes Verkehrsmittel in den Niederlanden. Wendung 'met de fiets' = mit dem Rad; Verb dazu 'fietsen'.","genus":"de","plural":"fietsen","illustratable":true},"w_gracht":{"lemma":"gracht","displayNl":"de gracht","pos":"substantief","meanings":[{"de":"Gracht, städtischer Kanal","ex":"De gracht in het centrum is heel mooi.","exDe":"Die Gracht im Zentrum ist sehr schön."},{"de":"Wassergraben (um eine Festung/Burg)","ex":"Rond het kasteel ligt een brede gracht.","exDe":"Um die Burg liegt ein breiter Wassergraben."}],"usage":"Typisch niederländisch für die von Häusern gesäumten Stadtkanäle in Amsterdam, Utrecht oder Delft.","genus":"de","plural":"grachten","illustratable":true},"w_moetik":{"lemma":"moet ik...?","displayNl":"moet ik...?","pos":"uitdrukking","meanings":[{"de":"muss ich...? / soll ich...?","ex":"Moet ik hier links?","exDe":"Muss ich hier links?"},{"de":"muss ich das (wirklich)? (ungläubig/widerwillig)","ex":"Moet ik dat echt doen?","exDe":"Muss ich das wirklich tun?"}],"usage":"Feste Frageformel mit Inversion (moet + ik) aus dem Modalverb 'moeten'; nach 'moet ik' folgt der Infinitiv am Satzende ('Moet ik hier afslaan?'). Typisch beim Fragen nach dem Weg oder nach einer Verpflichtung."},"p_vind":{"lemma":"vinden","displayNl":"vinden","pos":"werkwoord","meanings":[{"de":"finden, der Meinung sein","ex":"Ik vind deze plaat echt goed.","exDe":"Ich finde diese Platte wirklich gut."},{"de":"finden, etwas Verlorenes/Gesuchtes entdecken","ex":"Ik kan mijn sleutels niet vinden.","exDe":"Ich kann meine Schlüssel nicht finden."}],"usage":"Sehr häufiges Verb; für Meinungen 'ik vind (dat)...'. Unregelmäßig: Imperfekt vond/vonden, Partizip gevonden.","conjugation":{"presens":{"ik":"vind","jij":"vindt","hij":"vindt","wij":"vinden"},"imperfectum":{"ik":"vond","wij":"vonden"},"perfectum":{"aux":"hebben","participle":"gevonden"}}},"p_leuk":{"lemma":"leuk","displayNl":"leuk","pos":"adjectief","meanings":[{"de":"nett, schön, angenehm","ex":"Dat is echt leuk!","exDe":"Das ist echt schön!"},{"de":"lustig, witzig","ex":"Hij vertelde een leuke grap.","exDe":"Er erzählte einen lustigen Witz."},{"de":"sympathisch (von Personen)","ex":"Ik vind haar heel leuk.","exDe":"Ich finde sie sehr sympathisch."}],"usage":"Eines der häufigsten Alltagswörter; sehr breit für alles Positive/Angenehme. Attributiv: 'een leuk feest', 'een leuke film'."},"p_mooi":{"lemma":"mooi","displayNl":"mooi","pos":"adjectief","meanings":[{"de":"schön, hübsch","ex":"Wat een mooie track!","exDe":"Was für ein schöner Track!"},{"de":"schön, gut (als zustimmende Reaktion)","ex":"Morgen om tien uur? Mooi, tot dan.","exDe":"Morgen um zehn? Schön, bis dann."}],"usage":"Bezieht sich vor allem auf äußere/ästhetische Schönheit (Aussehen, Landschaft, Wetter), im Gegensatz zum breiteren 'leuk'."},"p_muziek":{"lemma":"muziek","displayNl":"de muziek","pos":"substantief","meanings":[{"de":"Musik","ex":"Ik hou van deze muziek.","exDe":"Ich liebe diese Musik."},{"de":"Noten, Notenblatt","ex":"De pianist speelt zonder muziek.","exDe":"Der Pianist spielt ohne Noten."}],"usage":"Meist unzählbar (kein gebräuchlicher Plural). Feste Wendungen: 'muziek maken', 'naar muziek luisteren'.","genus":"de"},"p_plaat":{"lemma":"plaat","displayNl":"de plaat","pos":"substantief","meanings":[{"de":"Schallplatte, Vinyl","ex":"Deze plaat komt uit Utrecht.","exDe":"Diese Platte kommt aus Utrecht."},{"de":"Platte, Tafel, Blech (flaches Materialstück)","ex":"Hij zaagt een plaat hout op maat.","exDe":"Er sägt eine Holzplatte auf Maß."},{"de":"Bild, Abbildung (in einem Buch)","ex":"In het boek staat een mooie plaat.","exDe":"In dem Buch ist eine schöne Abbildung."}],"usage":"Im Musikkontext die Vinyl-Schallplatte. Verkleinerung 'plaatje' bedeutet oft 'Bildchen/Foto'.","genus":"de","plural":"platen","illustratable":true},"p_draaien":{"lemma":"draaien","displayNl":"draaien","pos":"werkwoord","meanings":[{"de":"(Musik) auflegen, abspielen","ex":"De dj draait vanavond oude platen.","exDe":"Der DJ legt heute Abend alte Platten auf."},{"de":"drehen, sich drehen","ex":"Het wiel draait langzaam rond.","exDe":"Das Rad dreht sich langsam."},{"de":"laufen (Film, Betrieb)","ex":"Die film draait nu in de bioscoop.","exDe":"Der Film läuft jetzt im Kino."}],"usage":"Regelmäßiges Verb. Im Musikkontext 'platen draaien' = auflegen; auch 'aan iets draaien' = an etwas drehen.","conjugation":{"presens":{"ik":"draai","jij":"draait","hij":"draait","wij":"draaien"},"imperfectum":{"ik":"draaide","wij":"draaiden"},"perfectum":{"aux":"hebben","participle":"gedraaid"}},"illustratable":true},"p_optreden":{"lemma":"optreden","displayNl":"het optreden","pos":"substantief","meanings":[{"de":"der Auftritt (Bühne, Vorstellung)","ex":"Mijn eerste optreden is vanavond.","exDe":"Mein erster Auftritt ist heute Abend."},{"de":"das Auftreten, das Verhalten (Art sich zu geben)","ex":"Zijn rustige optreden maakt indruk.","exDe":"Sein ruhiges Auftreten macht Eindruck."}],"usage":"'het optreden' ist substantiviertes 'optreden' (auftreten); Plural 'optredens'. Meist im Sinne einer Bühnenvorstellung/Performance.","genus":"het","plural":"optredens","illustratable":true},"be_beurs":{"lemma":"beurs","displayNl":"de beurs","pos":"substantief","meanings":[{"de":"die Messe (Ausstellung, Fachmesse)","ex":"De beurs is heel druk vandaag.","exDe":"Die Messe ist heute sehr voll."},{"de":"die Börse (Handelsplatz für Aktien)","ex":"De aandelen op de beurs stijgen.","exDe":"Die Aktien an der Börse steigen."},{"de":"die Geldbörse, der Geldbeutel","ex":"Mijn geld zit in mijn beurs.","exDe":"Mein Geld ist in meiner Geldbörse."},{"de":"das Stipendium","ex":"Ze kreeg een beurs om te studeren.","exDe":"Sie bekam ein Stipendium zum Studieren."}],"usage":"Homonym mit mehreren Bedeutungen (Messe/Börse/Geldbörse/Stipendium); Plural 'beurzen'. Kontext entscheidet.","genus":"de","plural":"beurzen","illustratable":true},"be_plant":{"lemma":"plant","displayNl":"de plant","pos":"substantief","meanings":[{"de":"die Pflanze","ex":"Eni houdt van planten in huis.","exDe":"Eni liebt Pflanzen im Haus."}],"usage":"Zählbares Substantiv; Plural 'planten'. Für die Tätigkeit 'pflanzen' das Verb 'planten' benutzen.","genus":"de","plural":"planten","illustratable":true},"be_tuin":{"lemma":"tuin","displayNl":"de tuin","pos":"substantief","meanings":[{"de":"der Garten","ex":"Achter het huis ligt een kleine tuin.","exDe":"Hinter dem Haus liegt ein kleiner Garten."}],"usage":"Zählbares Substantiv; Plural 'tuinen'. 'dierentuin' = Zoo, 'moestuin' = Gemüsegarten.","genus":"de","plural":"tuinen","illustratable":true},"be_helpen":{"lemma":"helpen","displayNl":"helpen","pos":"werkwoord","meanings":[{"de":"helfen, unterstützen","ex":"Ik help je met de tassen.","exDe":"Ich helfe dir mit den Taschen."},{"de":"nützen, wirken (Wirkung zeigen)","ex":"Deze pil helpt tegen hoofdpijn.","exDe":"Diese Pille hilft gegen Kopfschmerzen."},{"de":"bedienen (im Laden)","ex":"Wordt u al geholpen?","exDe":"Werden Sie schon bedient?"}],"usage":"Unregelmäßig (stark): hielp/hielpen, Partizip 'geholpen', Hilfsverb 'hebben'. Person wird mit Dativ-ähnlich direktem Objekt konstruiert: 'iemand helpen'.","conjugation":{"presens":{"ik":"help","jij":"helpt","hij":"helpt","wij":"helpen"},"imperfectum":{"ik":"hielp","wij":"hielpen"},"perfectum":{"aux":"hebben","participle":"geholpen"}},"illustratable":true},"be_druk":{"lemma":"druk","displayNl":"druk","pos":"adjectief","meanings":[{"de":"viel los, belebt, voll (von einem Ort)","ex":"Het is heel druk in de stad.","exDe":"Es ist sehr viel los in der Stadt."},{"de":"vielbeschäftigt, viel zu tun habend","ex":"Ik heb het deze week erg druk.","exDe":"Ich habe diese Woche sehr viel zu tun."},{"de":"lebhaft, unruhig, hektisch (von einer Person)","ex":"Dat is een druk kind.","exDe":"Das ist ein lebhaftes Kind."}],"usage":"Adjektiv/Adverb; oft in 'het druk hebben' (viel zu tun haben) und 'het is druk' (es ist voll/viel los). Als Substantiv 'de druk' = der Druck (nicht dieser Eintrag)."},"be_niet":{"lemma":"niet","displayNl":"niet","pos":"bijwoord","meanings":[{"de":"nicht (Verneinung von Verben, Adjektiven, ganzen Aussagen)","ex":"Ik ben niet gestrest.","exDe":"Ich bin nicht gestresst."},{"de":"nicht (in Nachfragen: toch niet, helemaal niet)","ex":"Je komt toch wel, niet?","exDe":"Du kommst doch, oder nicht?"}],"usage":"Verneint Verben, Adjektive oder Satzteile. Vor unbestimmten Substantiven steht stattdessen 'geen'. Steht meist am Satzende bzw. nah beim verneinten Element."},"be_geen":{"lemma":"geen","displayNl":"geen","pos":"voornaamwoord","meanings":[{"de":"kein, keine (Verneinung vor unbestimmten Substantiven)","ex":"Geen stress, zegt Eni.","exDe":"Kein Stress, sagt Eni."},{"de":"nicht ein/keinerlei (nachdrücklich)","ex":"Ik heb geen tijd vandaag.","exDe":"Ich habe heute keine Zeit."}],"usage":"Negativer Artikel: verneint unbestimmte Substantive (statt 'niet een'). Beispiel-Phrase 'geen stress' auf das Kopf-Lemma 'geen' reduziert."},"on_ontbijt":{"lemma":"ontbijt","displayNl":"het ontbijt","pos":"substantief","meanings":[{"de":"das Frühstück","ex":"Het ontbijt is heerlijk.","exDe":"Das Frühstück ist köstlich."},{"de":"das Frühstücksbuffet / die Morgenmahlzeit","ex":"Het hotel heeft een uitgebreid ontbijt.","exDe":"Das Hotel hat ein reichhaltiges Frühstück."}],"usage":"Neutrum (het). Gängig: 'ontbijten' (Verb) = frühstücken.","genus":"het","plural":"ontbijten","illustratable":true},"on_koffie":{"lemma":"koffie","displayNl":"de koffie","pos":"substantief","meanings":[{"de":"der Kaffee (Getränk)","ex":"Twee koffie, alstublieft.","exDe":"Zwei Kaffee, bitte."},{"de":"der Kaffee (Bohnen/Sorte)","ex":"Deze koffie komt uit Colombia.","exDe":"Dieser Kaffee kommt aus Kolumbien."}],"usage":"de-Wort, meist unzählbar; Plural 'koffies' = mehrere Tassen Kaffee.","genus":"de","plural":"koffies","illustratable":true},"on_thee":{"lemma":"thee","displayNl":"de thee","pos":"substantief","meanings":[{"de":"der Tee (Getränk)","ex":"Ik neem een thee.","exDe":"Ich nehme einen Tee."},{"de":"der Tee (Sorte/getrocknete Blätter)","ex":"Groene thee is gezond.","exDe":"Grüner Tee ist gesund."}],"usage":"de-Wort, meist unzählbar; Plural 'theeën' selten (verschiedene Teesorten).","genus":"de","plural":"theeën","illustratable":true},"on_sap":{"lemma":"sap","displayNl":"het sap","pos":"substantief","meanings":[{"de":"der Saft (Getränk)","ex":"Vers sap, lekker!","exDe":"Frischer Saft, lecker!"},{"de":"der Pflanzensaft","ex":"Uit de stengel loopt kleverig sap.","exDe":"Aus dem Stängel läuft klebriger Saft."}],"usage":"Neutrum (het). Plural 'sappen' = verschiedene Säfte.","genus":"het","plural":"sappen","illustratable":true},"on_rekening":{"lemma":"rekening","displayNl":"de rekening","pos":"substantief","meanings":[{"de":"die Rechnung","ex":"De rekening, alstublieft.","exDe":"Die Rechnung, bitte."},{"de":"das Konto (Bankkonto)","ex":"Ik stort het geld op je rekening.","exDe":"Ich überweise das Geld auf dein Konto."},{"de":"die Berücksichtigung (in 'rekening houden met')","ex":"We moeten rekening houden met de tijd.","exDe":"Wir müssen die Zeit berücksichtigen."}],"usage":"de-Wort. Feste Wendung 'rekening houden met' = berücksichtigen.","genus":"de","plural":"rekeningen","illustratable":true},"on_euro":{"lemma":"euro","displayNl":"de euro","pos":"substantief","meanings":[{"de":"der Euro (Währung)","ex":"Dat is negen euro.","exDe":"Das sind neun Euro."}],"usage":"de-Wort. Nach Zahlen bleibt die Form 'euro' (twee euro); Plural als Gegenstand 'euro's'.","genus":"de","plural":"euro's","illustratable":true},"on_afrekenen":{"lemma":"afrekenen","displayNl":"afrekenen","pos":"werkwoord","meanings":[{"de":"zahlen / abrechnen (an der Kasse)","ex":"Mag ik afrekenen?","exDe":"Kann ich zahlen?"},{"de":"abrechnen mit jemandem / zur Rechenschaft ziehen","ex":"Hij wil afrekenen met zijn verleden.","exDe":"Er will mit seiner Vergangenheit abrechnen."}],"usage":"Trennbares Verb (af + rekenen). Hilfsverb hebben, Partizip 'afgerekend'.","conjugation":{"presens":{"ik":"reken af","jij":"rekent af","hij":"rekent af","wij":"rekenen af"},"imperfectum":{"ik":"rekende af","wij":"rekenden af"},"perfectum":{"aux":"hebben","participle":"afgerekend"}},"illustratable":true},"pl_planten":{"lemma":"plant","displayNl":"de plant","pos":"substantief","meanings":[{"de":"die Pflanze","ex":"Zoveel planten hier!","exDe":"So viele Pflanzen hier!"},{"de":"die Zimmerpflanze / Topfpflanze","ex":"Ik geef de plant water.","exDe":"Ich gieße die Pflanze."}],"usage":"de-Wort. Eingabe war Plural 'planten'; Grundform Singular 'plant'. Homonym: 'planten' auch Verb = pflanzen.","genus":"de","plural":"planten","illustratable":true},"pl_pot":{"lemma":"pot","displayNl":"de pot","pos":"substantief","meanings":[{"de":"der Topf (Blumen-/Kochtopf, Behälter)","ex":"Ik zet de plant in een grotere pot.","exDe":"Ich setze die Pflanze in einen größeren Topf."},{"de":"das (Einmach-)Glas, der Krug","ex":"Een pot jam staat in de kast.","exDe":"Ein Glas Marmelade steht im Schrank."},{"de":"der Pott / die Kasse (gemeinsamer Geldtopf, Spielpott)","ex":"We doen allemaal geld in de pot.","exDe":"Wir tun alle Geld in die Kasse."}],"usage":"Alltagswort. Konkret für Gefäße (Blumentopf, Kochtopf, Einmachglas), übertragen für einen gemeinsamen Geldtopf.","genus":"de","plural":"potten","illustratable":true},"pl_bloem":{"lemma":"bloem","displayNl":"de bloem","pos":"substantief","meanings":[{"de":"die Blume","ex":"In de tuin bloeien rode bloemen.","exDe":"Im Garten blühen rote Blumen."},{"de":"das Mehl (feines Weizenmehl)","ex":"Voor het brood heb je bloem nodig.","exDe":"Für das Brot brauchst du Mehl."}],"usage":"Homonym: meist „Blume“ (Plural bloemen), daneben „Mehl“ (dann unzählbar, kein Plural). Beide mit Artikel „de“.","genus":"de","plural":"bloemen","illustratable":true},"pl_water":{"lemma":"water geven","displayNl":"water geven","pos":"uitdrukking","meanings":[{"de":"gießen, wässern (Pflanzen mit Wasser versorgen)","ex":"Ik geef de planten elke ochtend water.","exDe":"Ich gieße die Pflanzen jeden Morgen."}],"usage":"Feste Wendung mit „geven“: iets/iemand water geven = etwas wässern. Trennbar im Satz (ik geef … water).","illustratable":true},"pl_groen":{"lemma":"groen","displayNl":"groen","pos":"adjectief","meanings":[{"de":"grün (Farbe)","ex":"De bladeren zijn fris groen.","exDe":"Die Blätter sind frisch grün."},{"de":"unerfahren, grün (hinter den Ohren)","ex":"Hij is nog groen in zijn nieuwe baan.","exDe":"Er ist in seinem neuen Job noch grün."},{"de":"ökologisch, umweltfreundlich","ex":"De partij heeft groene ideeën.","exDe":"Die Partei hat grüne Ideen."}],"usage":"Adjektiv; neben der Farbe auch „unerfahren“ und „ökologisch“. Als Substantiv „het groen“ = das Grün/die Grünfläche."},"pl_hoeveel":{"lemma":"hoeveel","displayNl":"hoeveel","pos":"bijwoord","meanings":[{"de":"wie viele, wie viel","ex":"Hoeveel planten heb je?","exDe":"Wie viele Pflanzen hast du?"}],"usage":"Fragewort nach Menge/Anzahl; steht für zählbare (wie viele) und unzählbare (wie viel) Mengen."},"ra_ramen":{"lemma":"ramen","displayNl":"de ramen","pos":"substantief","meanings":[{"de":"die Ramen (japanische Nudelsuppe)","ex":"De tonkotsu ramen is heerlijk.","exDe":"Die Tonkotsu-Ramen ist köstlich."},{"de":"die Fenster (Plural von „het raam“)","ex":"Doe de ramen open, het is warm.","exDe":"Mach die Fenster auf, es ist warm."}],"usage":"Als Gericht „de ramen“ (Nudelsuppe, unzählbar). Homonym: „de ramen“ ist auch der Plural von „het raam“ (das Fenster).","genus":"de","illustratable":true},"ra_gyoza":{"lemma":"gyoza","displayNl":"de gyoza","pos":"substantief","meanings":[{"de":"die Gyoza (japanische, gebratene Teigtaschen)","ex":"De gyoza zijn knapperig gebakken.","exDe":"Die Gyoza sind knusprig gebraten."}],"usage":"Lehnwort aus dem Japanischen für gefüllte Teigtaschen; oft im Plural serviert (gyoza's).","genus":"de","plural":"gyoza's","illustratable":true},"ra_romig":{"lemma":"romig","displayNl":"romig","pos":"adjectief","meanings":[{"de":"cremig, sahnig","ex":"De tonkotsu is lekker romig.","exDe":"Die Tonkotsu ist schön cremig."}],"usage":"Adjektiv für Konsistenz von Speisen/Getränken (Suppe, Sauce, Käse), „cremig/sahnig“."},"ra_knoflook":{"lemma":"knoflook","displayNl":"de knoflook","pos":"substantief","meanings":[{"de":"der Knoblauch","ex":"De knoflook geeft de saus een sterke smaak.","exDe":"Der Knoblauch gibt der Soße einen kräftigen Geschmack."}],"usage":"Meist als Stoffname ohne Plural gebraucht; eine einzelne Knolle = 'een teentje knoflook' (Zehe).","genus":"de","illustratable":true},"ra_honger":{"lemma":"honger hebben","displayNl":"honger hebben","pos":"uitdrukking","meanings":[{"de":"Hunger haben","ex":"Ik heb enorme honger.","exDe":"Ich habe riesigen Hunger."}],"usage":"Feste Wendung mit dem Substantiv 'honger' (de honger) + 'hebben'; Steigerung: 'honger krijgen' = Hunger bekommen.","notes":"Kern-Lemma des Substantivs: 'honger' (de). Als Wendung 'honger hebben' geführt."},"ra_kom":{"lemma":"kom","displayNl":"de kom","pos":"substantief","meanings":[{"de":"die Schüssel, die Schale","ex":"Hij at een grote kom soep.","exDe":"Er aß eine große Schüssel Suppe."},{"de":"Ortschaft, Ortskern (in 'bebouwde kom')","ex":"Binnen de bebouwde kom mag je maximaal 30 rijden.","exDe":"Innerorts darfst du höchstens 30 fahren."}],"usage":"Reduziert aus 'een lekkere kom' auf die Grundform. 'bebouwde kom' = geschlossene Ortschaft.","genus":"de","plural":"kommen","illustratable":true},"ra_smaakt":{"lemma":"smaken","displayNl":"smaken","pos":"werkwoord","meanings":[{"de":"schmecken (einen Geschmack haben)","ex":"De soep smaakt heerlijk.","exDe":"Die Suppe schmeckt herrlich."},{"de":"schmecken nach (etwas)","ex":"Het toetje smaakt naar kaneel.","exDe":"Der Nachtisch schmeckt nach Zimt."}],"usage":"Reduziert aus 'het smaakt' auf den Infinitiv. Regelmäßig; oft mit 'naar' + Geschmack.","conjugation":{"presens":{"ik":"smaak","jij":"smaakt","hij":"smaakt","wij":"smaken"},"imperfectum":{"ik":"smaakte","wij":"smaakten"},"perfectum":{"aux":"hebben","participle":"gesmaakt"}}},"te_terras":{"lemma":"terras","displayNl":"het terras","pos":"substantief","meanings":[{"de":"die (Café-)Terrasse, der Außenbereich","ex":"In de zomer zitten we graag op het terras.","exDe":"Im Sommer sitzen wir gern auf der Terrasse."},{"de":"die (Haus-/Dach-)Terrasse","ex":"Het appartement heeft een groot terras met uitzicht.","exDe":"Die Wohnung hat eine große Terrasse mit Aussicht."}],"usage":"'op het terras zitten' = auf der (Café-)Terrasse sitzen — typisch niederländische Ausgeh-Situation.","genus":"het","plural":"terrassen","illustratable":true},"te_biertje":{"lemma":"biertje","displayNl":"het biertje","pos":"substantief","meanings":[{"de":"das Bier (ein Glas/kleines, gemütliches Bier)","ex":"Zullen we een biertje drinken op het terras?","exDe":"Sollen wir ein Bier auf der Terrasse trinken?"}],"usage":"Verkleinerungsform von 'bier' (het bier); Diminutive sind immer 'het'. Umgangssprachlich für ein Glas Bier, oft auch alkoholfrei ('0.0 biertje').","genus":"het","plural":"biertjes","notes":"Grundwort: 'bier' (het). Als gebräuchliches Diminutiv 'biertje' geführt.","illustratable":true},"te_wijn":{"lemma":"mocktail","displayNl":"de mocktail","pos":"substantief","meanings":[{"de":"der alkoholfreie Cocktail, der Mocktail","ex":"Zij bestelde een fruitige mocktail zonder alcohol.","exDe":"Sie bestellte einen fruchtigen Cocktail ohne Alkohol."}],"usage":"Aus dem Englischen entlehnt; Plural auf -s. 'de mocktail'.","genus":"de","plural":"mocktails","notes":"Hinweis: input.id 'te_wijn' passt nicht zum Wort; verarbeitet wurde das gelieferte nl 'de mocktail'.","illustratable":true},"te_graag":{"lemma":"graag","displayNl":"graag","pos":"bijwoord","meanings":[{"de":"gern, gerne","ex":"Ik drink graag koffie in de ochtend.","exDe":"Ich trinke morgens gern Kaffee."},{"de":"bitte (höfliche Bekräftigung einer Bestellung/Bitte)","ex":"Een biertje, graag.","exDe":"Ein Bier, bitte."}],"usage":"Steigerung: graag – liever – het liefst (gern – lieber – am liebsten). 'Graag gedaan!' = Gern geschehen!"},"te_liever":{"lemma":"liever","displayNl":"liever","pos":"bijwoord","meanings":[{"de":"lieber (bevorzugt)","ex":"Ik drink liever thee dan koffie.","exDe":"Ich trinke lieber Tee als Kaffee."},{"de":"besser / eher (Präferenz ausdrückend)","ex":"Ik blijf liever thuis vanavond.","exDe":"Ich bleibe heute Abend lieber zu Hause."}],"usage":"Komparativ-Adverb zu 'graag'; drückt eine Vorliebe aus. Vergleich mit 'dan': 'liever ... dan ...'."},"te_proost":{"lemma":"proost","displayNl":"proost!","pos":"tussenwerpsel","meanings":[{"de":"prost! (Trinkspruch beim Anstoßen)","ex":"Proost, op Utrecht!","exDe":"Prost, auf Utrecht!"}],"usage":"Ausruf beim Anstoßen mit Gläsern. Auch als Segenswunsch nach dem Niesen (wie 'gesundheit') gebräuchlich."},"te_gezellig":{"lemma":"gezellig","displayNl":"gezellig","pos":"adjectief","meanings":[{"de":"gemütlich / behaglich (Atmosphäre)","ex":"Wat gezellig hier!","exDe":"Wie gemütlich hier!"},{"de":"gesellig / nett (von Personen und Zusammensein)","ex":"Het was een gezellige avond met vrienden.","exDe":"Es war ein netter, geselliger Abend mit Freunden."}],"usage":"Kulturell zentrales, schwer übersetzbares niederländisches Wort für Wärme, Behaglichkeit und angenehmes Beisammensein. Steckt in 'gezelligheid'."},"ma_markt":{"lemma":"markt","displayNl":"de markt","pos":"substantief","meanings":[{"de":"der Markt (Warenmarkt, Marktplatz)","ex":"De markt is op zaterdag.","exDe":"Der Markt ist am Samstag."},{"de":"der Markt (Wirtschaft, Absatzmarkt)","ex":"Er is veel vraag op de markt.","exDe":"Es gibt viel Nachfrage auf dem Markt."}],"usage":"Sowohl der Wochenmarkt/Platz als auch der wirtschaftliche Markt. Redewendung: 'iets op de markt brengen' (etwas auf den Markt bringen).","genus":"de","plural":"markten","illustratable":true},"ma_stuk":{"lemma":"stuk","displayNl":"het stuk","pos":"substantief","meanings":[{"de":"das Stück (Teil, Portion von etwas)","ex":"Een stuk kaas, graag.","exDe":"Ein Stück Käse, bitte."},{"de":"das Stück (Theater-, Musik- oder Schriftstück)","ex":"We zagen een mooi stuk in het theater.","exDe":"Wir sahen ein schönes Stück im Theater."},{"de":"Exemplar / einzelnes Objekt (beim Zählen)","ex":"Ze kosten twee euro per stuk.","exDe":"Sie kosten zwei Euro pro Stück."}],"usage":"Vielseitiges Wort. Als Adjektiv bedeutet 'stuk' auch 'kaputt' ('de fiets is stuk'). Redewendung: 'aan één stuk door' (ununterbrochen).","genus":"het","plural":"stukken"},"ma_kilo":{"lemma":"kilo","displayNl":"de kilo","pos":"substantief","meanings":[{"de":"das Kilo(gramm) (Gewichtseinheit)","ex":"Een kilo appels, alstublieft.","exDe":"Ein Kilo Äpfel, bitte."}],"usage":"Maßeinheit; nach Zahlwörtern bleibt die Form unverändert ('twee kilo', nicht 'kilo's'). Kurzform von 'kilogram'.","genus":"de","plural":"kilo's"},"ma_stroopwafel":{"lemma":"stroopwafel","displayNl":"de stroopwafel","pos":"substantief","meanings":[{"de":"die Stroopwafel (Sirupwaffel, niederländische Spezialität)","ex":"Verse stroopwafels van de markt!","exDe":"Frische Stroopwafeln vom Markt!"}],"usage":"Typisch niederländisches Gebäck: zwei dünne Waffeln mit Sirupfüllung. Beliebt frisch vom Marktstand oder auf einer heißen Tasse Tee/Kaffee zum Erweichen.","genus":"de","plural":"stroopwafels","illustratable":true},"ma_hoeveelkost":{"lemma":"hoeveel kost dat?","displayNl":"hoeveel kost dat?","pos":"uitdrukking","meanings":[{"de":"wie viel kostet das?","ex":"Hoeveel kost dat?","exDe":"Wie viel kostet das?"},{"de":"was kostet das? (Preisfrage beim Einkaufen)","ex":"Hoeveel kost deze kaas per kilo?","exDe":"Wie viel kostet dieser Käse pro Kilo?"}],"usage":"Standardfrage nach dem Preis. Varianten: 'Wat kost dat?' oder 'Hoeveel is het?'. 'hoeveel' = wie viel, 'kost' von 'kosten'."},"ma_vers":{"lemma":"vers","displayNl":"vers","pos":"adjectief","meanings":[{"de":"frisch (nicht alt, gerade erzeugt/geerntet)","ex":"Alles is vers vandaag.","exDe":"Alles ist heute frisch."},{"de":"frisch, neu (z. B. Nachrichten, Spuren)","ex":"Dat is vers nieuws.","exDe":"Das sind frische Nachrichten."}],"usage":"Attributiv gebeugt: verse (de/het-Wörter im bestimmten Gebrauch, z. B. 'verse vis'). Prädikativ ungebeugt: 'de vis is vers'."},"av_avond":{"lemma":"avond","displayNl":"de avond","pos":"substantief","meanings":[{"de":"der Abend","ex":"Het wordt al avond.","exDe":"Es wird schon Abend."},{"de":"der Abend (als Veranstaltung/gesellige Runde)","ex":"Het was een gezellige avond.","exDe":"Es war ein gemütlicher Abend."}],"usage":"Tagesgruß: 'goedenavond'. Zeitangabe: 's avonds' = am Abend, abends. 'vanavond' = heute Abend.","genus":"de","plural":"avonden","illustratable":true},"av_bank":{"lemma":"bank","displayNl":"de bank","pos":"substantief","meanings":[{"de":"das Sofa, die Couch","ex":"Onze bank is groot.","exDe":"Unser Sofa ist groß."},{"de":"die Bank (Geldinstitut)","ex":"Ik ga naar de bank om geld te halen.","exDe":"Ich gehe zur Bank, um Geld zu holen."},{"de":"die (Sitz-)Bank","ex":"We zitten op een bank in het park.","exDe":"Wir sitzen auf einer Bank im Park."}],"usage":"Homonym: 'bank' = Sofa, Geldinstitut und Sitzbank. Alle drei sind de-Wörter, Plural stets 'banken'.","genus":"de","plural":"banken","illustratable":true},"av_mijn":{"lemma":"mijn","displayNl":"mijn","pos":"voornaamwoord","meanings":[{"de":"mein, meine (besitzanzeigend)","ex":"Mijn kat slaapt.","exDe":"Meine Katze schläft."}],"usage":"Possessivpronomen, unveraenderlich vor Substantiven jeden Genus und im Plural. Betonte Form: 'mijn', unbetont oft 'm'n'."},"av_onze":{"lemma":"onze","displayNl":"onze","pos":"voornaamwoord","meanings":[{"de":"unser, unsere (besitzanzeigend)","ex":"Onze katten zijn lief.","exDe":"Unsere Katzen sind lieb."}],"usage":"Possessivpronomen 1. Person Plural. 'onze' vor de-Wörtern und Plural, aber 'ons' vor het-Wörtern im Singular (ons huis)."},"av_kijken":{"lemma":"kijken","displayNl":"kijken","pos":"werkwoord","meanings":[{"de":"schauen, gucken, sehen","ex":"We kijken YouTube.","exDe":"Wir schauen YouTube."},{"de":"anschauen, ansehen (kijken naar)","ex":"Ik kijk naar de film.","exDe":"Ich schaue den Film an."},{"de":"nachschauen, mal sehen","ex":"Ik zal even kijken of het klopt.","exDe":"Ich schaue mal eben, ob es stimmt."}],"usage":"Wird meist mit 'naar' verwendet: 'kijken naar iets' = etwas ansehen. Regelmäßiges Verb, Hilfsverb hebben.","conjugation":{"presens":{"ik":"kijk","jij":"kijkt","hij":"kijkt","wij":"kijken"},"imperfectum":{"ik":"keek","wij":"keken"},"perfectum":{"aux":"hebben","participle":"gekeken"}},"illustratable":true},"av_moe":{"lemma":"moe","displayNl":"moe","pos":"adjectief","meanings":[{"de":"müde, erschöpft","ex":"Ik ben moe.","exDe":"Ich bin müde."},{"de":"etwas leid/überdrüssig (iets moe zijn)","ex":"Ik ben het wachten moe.","exDe":"Ich bin das Warten leid."}],"usage":"Prädikativ meist 'moe'; attributiv gebeugt 'moede/moeie' (selten). Steigerung: 'moeër', 'moest'."},"av_samen":{"lemma":"samen","displayNl":"samen","pos":"bijwoord","meanings":[{"de":"zusammen, gemeinsam","ex":"Samen op de bank.","exDe":"Zusammen auf dem Sofa."},{"de":"insgesamt, zusammengerechnet","ex":"Samen kost het tien euro.","exDe":"Zusammen kostet es zehn Euro."}],"usage":"Adverb; oft in 'samen met' = zusammen mit. In Trennverben: 'samenwonen', 'samenwerken'."},"vj_verjaardag":{"lemma":"verjaardag","displayNl":"de verjaardag","pos":"substantief","meanings":[{"de":"der Geburtstag","ex":"Fijne verjaardag!","exDe":"Alles Gute zum Geburtstag!"},{"de":"der Jahrestag (jährliche Wiederkehr eines Ereignisses)","ex":"We vieren de verjaardag van de vereniging.","exDe":"Wir feiern den Jahrestag des Vereins."}],"usage":"Alltäglich. \"Fijne/Gelukkige verjaardag!\" = Glückwunsch zum Geburtstag. Man feliciteert iemand met zijn/haar verjaardag.","genus":"de","plural":"verjaardagen","illustratable":true},"vj_gefeliciteerd":{"lemma":"gefeliciteerd","displayNl":"gefeliciteerd","pos":"tussenwerpsel","meanings":[{"de":"herzlichen Glückwunsch! / Gratuliere!","ex":"Gefeliciteerd met je verjaardag!","exDe":"Herzlichen Glückwunsch zum Geburtstag!"},{"de":"Glückwunsch (allgemein, zu jedem Anlass)","ex":"Gefeliciteerd met je nieuwe baan!","exDe":"Glückwunsch zu deinem neuen Job!"}],"usage":"Feste Gratulationsformel, ursprünglich Partizip von \"feliciteren\". Anlass mit \"met\": gefeliciteerd met ... In NL gratuliert man oft auch Angehörigen des Geburtstagskindes."},"vj_taart":{"lemma":"taart","displayNl":"de taart","pos":"substantief","meanings":[{"de":"die Torte","ex":"Een stukje taart?","exDe":"Ein Stückchen Torte?"},{"de":"der Kuchen (rund, gefüllt/belegt)","ex":"Ik heb een appeltaart gebakken.","exDe":"Ich habe einen Apfelkuchen gebacken."}],"usage":"Runde, meist gefüllte oder belegte Torte/Kuchen (z. B. appeltaart, slagroomtaart). Flacher Blechkuchen ist eher \"cake\" oder \"gebak\".","genus":"de","plural":"taarten","illustratable":true},"vj_cadeau":{"lemma":"cadeau","displayNl":"het cadeau","pos":"substantief","meanings":[{"de":"das Geschenk","ex":"Een cadeau voor haar.","exDe":"Ein Geschenk für sie."},{"de":"geschenkt / gratis (prädikativ, umgangssprachlich)","ex":"Dat krijg je van mij cadeau.","exDe":"Das bekommst du von mir geschenkt."}],"usage":"Aus dem Französischen; Plural \"cadeaus\". \"Iets cadeau geven/krijgen\" = etwas verschenken/geschenkt bekommen. Synonym formeller: geschenk.","genus":"het","plural":"cadeaus","illustratable":true},"vj_want":{"lemma":"want","displayNl":"want","pos":"voegwoord","meanings":[{"de":"denn (nebenordnend, Begründung; Hauptsatz-Wortstellung folgt)","ex":"Ik ben blij, want het is feest.","exDe":"Ich bin froh, denn es ist Fest."},{"de":"die Fäustlinge / Fausthandschuhe (Substantiv, seltener)","ex":"In de winter draag ik dikke wanten.","exDe":"Im Winter trage ich dicke Fäustlinge."}],"usage":"Als Konjunktion \"want\" nebenordnend (kein Verb-Endstellung): want + Subjekt + Verb. Gegenstück \"omdat\" (unterordnend). Homonym: de want = Fausthandschuh (Plural wanten)."},"vj_omdat":{"lemma":"omdat","displayNl":"omdat","pos":"voegwoord","meanings":[{"de":"weil (unterordnend; Verb ans Satzende)","ex":"Ik lach omdat het gezellig is.","exDe":"Ich lache, weil es gemütlich ist."}],"usage":"Unterordnende Konjunktion: Verb rückt ans Satzende (omdat het gezellig is). Antwortet auf \"waarom?\". Unterschied zu \"want\" (nebenordnend, Hauptsatzstellung)."},"vj_feest":{"lemma":"feest","displayNl":"het feest","pos":"substantief","meanings":[{"de":"das Fest / die Feier / die Party","ex":"Wat een leuk feest!","exDe":"Was für eine schöne Feier!"},{"de":"das Fest / der Feiertag (Anlass)","ex":"Sinterklaas is een echt Nederlands feest.","exDe":"Sinterklaas ist ein echtes niederländisches Fest."}],"usage":"Allgemein für Feier/Party und für festliche Anlässe/Feiertage. \"Feest vieren\" = feiern. Ausdruck \"Het is feest!\".","genus":"het","plural":"feesten","illustratable":true},"am_trein":{"lemma":"trein","displayNl":"de trein","pos":"substantief","meanings":[{"de":"der Zug (Eisenbahn)","ex":"De trein naar Amsterdam.","exDe":"Der Zug nach Amsterdam."},{"de":"der Zug (als Verkehrsmittel/Fahrt)","ex":"Ik ga met de trein naar mijn werk.","exDe":"Ich fahre mit dem Zug zur Arbeit."}],"usage":"\"Met de trein reizen/gaan\" = mit dem Zug fahren. Bahnhof = station, Fahrkarte = treinkaartje. In NL typisch die gelb-blauen NS-Züge (ohne Markennennung).","genus":"de","plural":"treinen","illustratable":true},"am_station":{"lemma":"station","displayNl":"het station","pos":"substantief","meanings":[{"de":"der Bahnhof","ex":"Waar is het station?","exDe":"Wo ist der Bahnhof?"},{"de":"die Station, der Sender (Radio/TV)","ex":"Ik luister naar een Nederlands station.","exDe":"Ich höre einen niederländischen Sender."}],"usage":"Neutrum: het station, meervoud stations. Voor de spoorweghal meestal 'het station'; 'de halte' is de kleinere stop van bus of tram.","genus":"het","plural":"stations","illustratable":true},"am_spoor":{"lemma":"spoor","displayNl":"het spoor","pos":"substantief","meanings":[{"de":"das Gleis, der Bahnsteig (Nummer)","ex":"De trein vertrekt van spoor 5.","exDe":"Der Zug fährt von Gleis 5 ab."},{"de":"die Spur, die Fährte","ex":"In de sneeuw zag ik sporen van een hond.","exDe":"Im Schnee sah ich Spuren eines Hundes."},{"de":"das Anzeichen, die Spur (übertragen)","ex":"Er is geen spoor van hem te vinden.","exDe":"Von ihm ist keine Spur zu finden."}],"usage":"Neutrum: het spoor, meervoud sporen. In de station betekent het het perronnummer ('welk spoor?'); in de natuur een afdruk of fährte.","genus":"het","plural":"sporen","illustratable":true},"am_waar":{"lemma":"waar","displayNl":"waar","pos":"bijwoord","meanings":[{"de":"wo (Frageadverb)","ex":"Waar woon je?","exDe":"Wo wohnst du?"},{"de":"wohin (in 'waar ... heen/naartoe')","ex":"Waar gaan we heen?","exDe":"Wohin gehen wir?"},{"de":"wo (Relativadverb für Ort)","ex":"Het huis waar ik woon is oud.","exDe":"Das Haus, wo ich wohne, ist alt."},{"de":"wahr (Adjektiv)","ex":"Is dat verhaal waar?","exDe":"Ist diese Geschichte wahr?"}],"usage":"Als vraag- en relatiewoord voor plaats ('wo'); voor richting combineer je met 'heen' of 'naartoe' ('wohin'). Als adjectief betekent 'waar' zoveel als 'wahr'."},"am_hoelaat":{"lemma":"hoe laat","displayNl":"hoe laat","pos":"uitdrukking","meanings":[{"de":"wie spät, um wie viel Uhr, wann (nach der Uhrzeit)","ex":"Hoe laat gaat de trein?","exDe":"Wann fährt der Zug?"},{"de":"wie spät (nach der aktuellen Zeit)","ex":"Hoe laat is het?","exDe":"Wie spät ist es?"}],"usage":"Vaste vraag naar het klok-tijdstip ('um wie viel Uhr'). 'Wanneer' vraagt algemener naar dag of moment, 'hoe laat' specifiek naar het uur."},"am_kaartje":{"lemma":"kaartje","displayNl":"het kaartje","pos":"substantief","meanings":[{"de":"das Ticket, die Fahrkarte","ex":"Een kaartje naar Amsterdam, alstublieft.","exDe":"Eine Fahrkarte nach Amsterdam, bitte."},{"de":"die Eintrittskarte","ex":"Ik heb twee kaartjes voor het festival.","exDe":"Ich habe zwei Eintrittskarten für das Festival."},{"de":"das Kärtchen, die kleine Karte (Visiten-/Grußkarte)","ex":"Hij gaf me zijn kaartje.","exDe":"Er gab mir seine Visitenkarte."}],"usage":"Verkleinwoord van 'kaart', altijd het-woord: het kaartje, meervoud kaartjes. Voor reizen en toegang; het grotere 'de kaart' is o.a. landkaart of menukaart.","genus":"het","plural":"kaartjes","illustratable":true},"am_uitstappen":{"lemma":"uitstappen","displayNl":"uitstappen","pos":"werkwoord","meanings":[{"de":"aussteigen (aus Zug, Bus, Auto)","ex":"We stappen hier uit.","exDe":"Wir steigen hier aus."},{"de":"aussteigen, sich zurückziehen (übertragen, aus einem Projekt)","ex":"Hij is uit het project gestapt.","exDe":"Er ist aus dem Projekt ausgestiegen."}],"usage":"Scheidbaar werkwoord (stap ... uit); in de hoofdzin gaat 'uit' naar het einde. Tegengestelde van 'instappen'. Hulpwerkwoord is 'zijn' omdat het een verplaatsing is.","conjugation":{"presens":{"ik":"stap uit","jij":"stapt uit","hij":"stapt uit","wij":"stappen uit"},"imperfectum":{"ik":"stapte uit","wij":"stapten uit"},"perfectum":{"aux":"zijn","participle":"uitgestapt"}},"illustratable":true},"li_festival":{"lemma":"festival","displayNl":"het festival","pos":"substantief","meanings":[{"de":"das Festival, das Fest (Musik-/Kulturveranstaltung)","ex":"Het festival is dit weekend.","exDe":"Das Festival ist an diesem Wochenende."}],"usage":"Neutrum: het festival, meervoud festivals (met -s, leenwoord). Voor grote muziek- of cultuurevenementen; een kleiner particulier feest is 'het feest'.","genus":"het","plural":"festivals","illustratable":true},"li_vroeger":{"lemma":"vroeger","displayNl":"vroeger","pos":"bijwoord","meanings":[{"de":"früher, in der Vergangenheit, damals","ex":"Vroeger woonde ik in Berlijn.","exDe":"Früher wohnte ich in Berlin."},{"de":"früher, eher (zeitlich vorher, Komparativ van 'vroeg')","ex":"Vandaag ben ik vroeger opgestaan dan gisteren.","exDe":"Heute bin ich früher aufgestanden als gestern."}],"usage":"Als tijdsbijwoord 'damals/in het verleden' met imperfectum. Grammaticaal ook de vergrotende trap van 'vroeg' ('früher/eher'). Tegengestelde van 'later' of 'tegenwoordig'."},"li_gezien":{"lemma":"zien","displayNl":"zien","pos":"werkwoord","meanings":[{"de":"sehen","ex":"Ik heb de crew gezien!","exDe":"Ich habe die Crew gesehen!"},{"de":"erblicken, wahrnehmen","ex":"Zie je die boot op de gracht?","exDe":"Siehst du das Boot auf der Gracht?"},{"de":"treffen, wiedersehen (jdn.)","ex":"Ik zie je vanavond op het feest.","exDe":"Ich sehe dich heute Abend auf der Party."}],"usage":"Unregelmäßig. Perfekt mit hebben: 'ik heb gezien'. In der Roh-Vokabel als konjugierte Form geliefert, hier auf den Infinitiv reduziert.","conjugation":{"presens":{"ik":"zie","jij":"ziet","hij":"ziet","wij":"zien"},"imperfectum":{"ik":"zag","wij":"zagen"},"perfectum":{"aux":"hebben","participle":"gezien"}}},"li_gedraaid":{"lemma":"draaien","displayNl":"draaien","pos":"werkwoord","meanings":[{"de":"(Musik) auflegen, Platten drehen","ex":"We hebben samen gedraaid.","exDe":"Wir haben zusammen aufgelegt."},{"de":"drehen, sich drehen","ex":"Het wiel draait langzaam rond.","exDe":"Das Rad dreht sich langsam."},{"de":"aufdrehen, einstellen (z. B. Hahn)","ex":"Draai de kraan even dicht.","exDe":"Dreh den Hahn mal zu."}],"usage":"Regelmäßig. Perfekt mit hebben. Im DJ-Kontext 'muziek draaien' = Musik auflegen. Roh-Vokabel als konjugierte Form geliefert, hier auf Infinitiv reduziert.","conjugation":{"presens":{"ik":"draai","jij":"draait","hij":"draait","wij":"draaien"},"imperfectum":{"ik":"draaide","wij":"draaiden"},"perfectum":{"aux":"hebben","participle":"gedraaid"}}},"li_geleden":{"lemma":"geleden","displayNl":"geleden","pos":"bijwoord","meanings":[{"de":"her, vor (zeitlich zurück)","ex":"Dat is lang geleden.","exDe":"Das ist lange her."},{"de":"vor (bei Zeitangaben)","ex":"Twee jaar geleden woonde ik in Utrecht.","exDe":"Vor zwei Jahren wohnte ich in Utrecht."}],"usage":"Zeitliches Adverb, steht dem Zeitausdruck nach: 'lang geleden', 'een week geleden'. Als Ausdruck oft in 'dat is lang geleden' (schön, dich wiederzusehen)."},"li_vrienden":{"lemma":"vriend","displayNl":"de vriend","pos":"substantief","meanings":[{"de":"der Freund","ex":"Oude vrienden!","exDe":"Alte Freunde!"},{"de":"der Freund (Partner, fester Freund)","ex":"Dit is mijn vriend Bas.","exDe":"Das ist mein Freund Bas."}],"usage":"de-Wort. Plural 'vrienden'. Weibliche Form 'vriendin' (Freundin/Partnerin). Roh-Vokabel im Plural geliefert, hier auf Singular reduziert.","genus":"de","plural":"vrienden","illustratable":true},"li_gemist":{"lemma":"missen","displayNl":"missen","pos":"werkwoord","meanings":[{"de":"vermissen","ex":"Ik heb jullie gemist.","exDe":"Ich habe euch vermisst."},{"de":"verpassen (Zug, Termin)","ex":"Ik heb de trein gemist.","exDe":"Ich habe den Zug verpasst."},{"de":"entbehren, fehlen","ex":"We missen nog één speler.","exDe":"Uns fehlt noch ein Spieler."}],"usage":"Regelmäßig. Perfekt mit hebben. Roh-Vokabel als konjugierte Form geliefert, hier auf Infinitiv reduziert.","conjugation":{"presens":{"ik":"mis","jij":"mist","hij":"mist","wij":"missen"},"imperfectum":{"ik":"miste","wij":"misten"},"perfectum":{"aux":"hebben","participle":"gemist"}}},"vo_feesten":{"lemma":"feesten","displayNl":"feesten","pos":"werkwoord","meanings":[{"de":"feiern, Party machen","ex":"We gaan feesten!","exDe":"Wir werden feiern!"}],"usage":"Regelmäßig, Verb zum Substantiv 'het feest'. Perfekt mit hebben. Nicht mit dem Plural 'feesten' (die Feste) verwechseln.","conjugation":{"presens":{"ik":"feest","jij":"feest","hij":"feest","wij":"feesten"},"imperfectum":{"ik":"feestte","wij":"feestten"},"perfectum":{"aux":"hebben","participle":"gefeest"}},"illustratable":true},"vo_dansen":{"lemma":"dansen","displayNl":"dansen","pos":"werkwoord","meanings":[{"de":"tanzen","ex":"Ik ga de hele nacht dansen.","exDe":"Ich werde die ganze Nacht tanzen."}],"usage":"Regelmäßig. Perfekt mit hebben. Substantiv dazu: 'de dans' (der Tanz).","conjugation":{"presens":{"ik":"dans","jij":"danst","hij":"danst","wij":"dansen"},"imperfectum":{"ik":"danste","wij":"dansten"},"perfectum":{"aux":"hebben","participle":"gedanst"}},"illustratable":true},"vo_bas":{"lemma":"bas","displayNl":"de bas","pos":"substantief","meanings":[{"de":"der Bass (tiefer Ton, Bassklang)","ex":"De bas is zwaar!","exDe":"Der Bass ist heftig!"},{"de":"der Bass (Instrument, Bassgitarre/Kontrabass)","ex":"Hij speelt bas in de band.","exDe":"Er spielt Bass in der Band."},{"de":"der Bass (tiefe Singstimme)","ex":"Zijn stem is een diepe bas.","exDe":"Seine Stimme ist ein tiefer Bass."}],"usage":"de-Wort. Plural 'bassen'. Deckt Bassklang, Bassinstrument und Bassstimme ab.","genus":"de","plural":"bassen","illustratable":true},"vo_vooraan":{"lemma":"vooraan","displayNl":"vooraan","pos":"bijwoord","meanings":[{"de":"ganz vorne, an vorderster Stelle","ex":"We staan vooraan bij het podium.","exDe":"Wir stehen ganz vorne an der Bühne."},{"de":"vorne (zeitlich/reihenfolge: an erster Stelle)","ex":"Zijn naam staat vooraan op de lijst.","exDe":"Sein Name steht ganz vorne auf der Liste."}],"usage":"Ortsadverb; Gegenteil van 'achteraan'. Steht oft am Satzende oder nach dem Verb."},"vo_bandje":{"lemma":"bandje","displayNl":"het bandje","pos":"substantief","meanings":[{"de":"das Armband, das Bändchen (schmales Band ums Handgelenk)","ex":"Ze draagt een gekleurd bandje om haar pols.","exDe":"Sie trägt ein buntes Armband um ihr Handgelenk."},{"de":"das Träger-/Schulterband (z. B. an Kleidung, Tasche)","ex":"Het bandje van mijn tas is kapot.","exDe":"Der Trageriemen meiner Tasche ist kaputt."},{"de":"das Tonband, die Kassette (Aufnahme)","ex":"Vroeger namen we muziek op een bandje op.","exDe":"Früher nahmen wir Musik auf einer Kassette auf."},{"de":"die (kleine) Band, Musikgruppe (umgangssprachlich)","ex":"Hij speelt in een bandje.","exDe":"Er spielt in einer kleinen Band."}],"usage":"Verkleinerungsform von 'band'. Sehr polysem: konkretes Bändchen, Kleidungsträger, Tonbandaufnahme oder Musikgruppe.","genus":"het","plural":"bandjes","illustratable":true},"vo_ruilen":{"lemma":"ruilen","displayNl":"ruilen","pos":"werkwoord","meanings":[{"de":"tauschen, eintauschen","ex":"Zullen we van plaats ruilen?","exDe":"Sollen wir die Plätze tauschen?"},{"de":"umtauschen (z. B. gekaufte Ware)","ex":"Ik wil deze trui ruilen voor een grotere maat.","exDe":"Ich möchte diesen Pullover gegen eine größere Größe umtauschen."}],"usage":"Regelmäßiges Verb. Oft mit 'van' ('van plaats ruilen') oder 'voor' ('A voor B ruilen').","conjugation":{"presens":{"ik":"ruil","jij":"ruilt","hij":"ruilt","wij":"ruilen"},"imperfectum":{"ik":"ruilde","wij":"ruilden"},"perfectum":{"aux":"hebben","participle":"geruild"}}},"vo_nacht":{"lemma":"nacht","displayNl":"de nacht","pos":"substantief","meanings":[{"de":"die Nacht","ex":"Het heeft de hele nacht geregend.","exDe":"Es hat die ganze Nacht geregnet."},{"de":"die Übernachtung (in Wendungen, z. B. Hotel)","ex":"We boekten twee nachten in Amsterdam.","exDe":"Wir buchten zwei Nächte in Amsterdam."}],"usage":"Gruß 'goedenacht'. Wendung 'de hele nacht' = die ganze Nacht.","genus":"de","plural":"nachten","illustratable":true},"o_gaik":{"lemma":"gaan","displayNl":"gaan","pos":"werkwoord","meanings":[{"de":"gehen, sich fortbewegen","ex":"Ik ga naar huis.","exDe":"Ich gehe nach Hause."},{"de":"werden / im Begriff sein (Futur/Absicht, mit Infinitiv)","ex":"Ik ga vanavond draaien.","exDe":"Ich lege heute Abend auf."},{"de":"laufen, funktionieren, sich entwickeln ('hoe gaat het?')","ex":"Hoe gaat het met je?","exDe":"Wie geht es dir?"}],"usage":"Unregelmäßiges Verb; sehr häufig als Futurhilfe 'gaan + Infinitiv'. Perfekt mit 'zijn'.","conjugation":{"presens":{"ik":"ga","jij":"gaat","hij":"gaat","wij":"gaan"},"imperfectum":{"ik":"ging","wij":"gingen"},"perfectum":{"aux":"zijn","participle":"gegaan"}}},"o_vanavond":{"lemma":"vanavond","displayNl":"vanavond","pos":"bijwoord","meanings":[{"de":"heute Abend","ex":"Vanavond speel ik een set.","exDe":"Heute Abend spiele ich ein Set."}],"usage":"Zeitadverb; Reihe: vanmorgen/vanmiddag/vanavond/vannacht."},"o_spelen":{"lemma":"spelen","displayNl":"spelen","pos":"werkwoord","meanings":[{"de":"spielen (Spiel, Kinder)","ex":"De kinderen spelen in de tuin.","exDe":"Die Kinder spielen im Garten."},{"de":"(ein Instrument/Musik) spielen, musizieren","ex":"Zij speelt piano.","exDe":"Sie spielt Klavier."},{"de":"(Theater/Film) spielen, eine Rolle darstellen","ex":"Hij speelt de hoofdrol in het toneelstuk.","exDe":"Er spielt die Hauptrolle in dem Theaterstück."}],"usage":"Regelmäßiges Verb. Auch 'een wedstrijd spelen' (ein Spiel/Match spielen).","conjugation":{"presens":{"ik":"speel","jij":"speelt","hij":"speelt","wij":"spelen"},"imperfectum":{"ik":"speelde","wij":"speelden"},"perfectum":{"aux":"hebben","participle":"gespeeld"}},"illustratable":true},"o_zenuw":{"lemma":"zenuwachtig","displayNl":"zenuwachtig","pos":"adjectief","meanings":[{"de":"nervös, aufgeregt, unruhig","ex":"Ik ben een beetje zenuwachtig voor het optreden.","exDe":"Ich bin ein bisschen nervös vor dem Auftritt."},{"de":"nervlich angespannt, gereizt","ex":"Door de drukte werd hij zenuwachtig.","exDe":"Durch den Trubel wurde er nervös/gereizt."}],"usage":"Adjektiv/prädikativ; Substantiv 'de zenuw' = der Nerv. Steigerung: zenuwachtiger, zenuwachtigst."},"o_klaar":{"lemma":"klaar","displayNl":"klaar","pos":"adjectief","meanings":[{"de":"fertig, bereit","ex":"Ben je klaar om te gaan?","exDe":"Bist du bereit zu gehen?"},{"de":"fertig, abgeschlossen (erledigt)","ex":"Mijn huiswerk is klaar.","exDe":"Meine Hausaufgaben sind fertig."},{"de":"klar, deutlich (in Wendungen wie 'klaar en duidelijk')","ex":"Dat is klaar en duidelijk.","exDe":"Das ist klar und deutlich."}],"usage":"Prädikativ sehr häufig ('ik ben klaar'). 'klaar zijn met iets' = mit etwas fertig sein; 'klaar zijn om te ...' = bereit sein zu ..."},"o_gaaf":{"lemma":"gaaf","displayNl":"gaaf","pos":"adjectief","meanings":[{"de":"cool, toll, geil (umgangssprachlich, begeistert)","ex":"Wat een gaaf idee!","exDe":"Was für eine coole Idee!"},{"de":"makellos, unversehrt, glatt (von Oberflächen/Haut, formeller)","ex":"Zij heeft een gave huid.","exDe":"Sie hat eine makellose Haut."}],"usage":"Umgangssprachliches Lob, vor allem bei Jugendlichen ('zo gaaf!'). Attributiv: 'een gave film'. Die zweite Bedeutung ('makellos') ist neutraler Standardgebrauch."},"pe1_schilder":{"lemma":"schilder","displayNl":"de schilder","pos":"substantief","meanings":[{"de":"der Maler (Kunstmaler)","ex":"Vincent van Gogh is een beroemde schilder.","exDe":"Vincent van Gogh ist ein berühmter Maler."},{"de":"der Maler, Anstreicher (Handwerker)","ex":"De schilder verft de muren van ons huis.","exDe":"Der Maler streicht die Wände unseres Hauses."}],"usage":"Sowohl Kunstmaler als auch Anstreicher. Weibliche Form: 'schilderes' (selten) bzw. 'kunstschilder' für Künstlerin/Künstler.","genus":"de","plural":"schilders","illustratable":true},"pe1_schilderij":{"lemma":"schilderij","displayNl":"het schilderij","pos":"substantief","meanings":[{"de":"das Gemälde, das Bild","ex":"Het schilderij hangt aan de muur.","exDe":"Das Gemälde hängt an der Wand."}],"usage":"Neutrum: 'het schilderij'. Gemeint ist das gemalte Kunstwerk selbst (im Unterschied zu 'de verf' = die Farbe).","genus":"het","plural":"schilderijen","illustratable":true},"pe1_ster":{"lemma":"ster","displayNl":"de ster","pos":"substantief","meanings":[{"de":"der Stern (am Himmel)","ex":"Er staat een heldere ster aan de hemel.","exDe":"Ein heller Stern steht am Himmel."},{"de":"der Star, die Berühmtheit","ex":"Zij is een grote ster in Nederland.","exDe":"Sie ist ein großer Star in den Niederlanden."},{"de":"der Stern (Form/Symbol, z. B. als Auszeichnung)","ex":"Dit hotel heeft vijf sterren.","exDe":"Dieses Hotel hat fünf Sterne."}],"usage":"Plural 'sterren' (Verdopplung des r). Für den Himmelskörper, für Berühmtheiten und für das Sternsymbol/Bewertungssterne gleichermaßen.","genus":"de","plural":"sterren","illustratable":true},"pe1_verf":{"lemma":"verf","displayNl":"de verf","pos":"substantief","meanings":[{"de":"die Farbe (zum Malen/Streichen), der Anstrich","ex":"De verf op de muur is nog nat.","exDe":"Die Farbe an der Wand ist noch nass."}],"usage":"Meint das Material Farbe (Substanz), nicht die Farbnuance ('kleur'). Plural 'verven' für verschiedene Farbsorten.","genus":"de","plural":"verven","illustratable":true},"pe1_oor":{"lemma":"oor","displayNl":"het oor","pos":"substantief","meanings":[{"de":"das Ohr","ex":"Hij fluistert iets in mijn oor.","exDe":"Er flüstert mir etwas ins Ohr."},{"de":"der Henkel, das Ohr (z. B. einer Tasse)","ex":"Het oor van de kopje is afgebroken.","exDe":"Der Henkel der Tasse ist abgebrochen."}],"usage":"Neutrum: 'het oor', unregelmäßiger Plural 'oren'. Auch übertragen für den Henkel eines Gefäßes.","genus":"het","plural":"oren","illustratable":true},"pe1_verdrietig":{"lemma":"verdrietig","displayNl":"verdrietig","pos":"adjectief","meanings":[{"de":"traurig, betrübt","ex":"Ze was heel verdrietig na het afscheid.","exDe":"Sie war sehr traurig nach dem Abschied."}],"usage":"Beschreibt eine tiefere, anhaltende Traurigkeit (stärker als 'droevig' im Alltag). 'verdrietig zijn om/over iets' = über etwas traurig sein."},"pe1_beroemd":{"lemma":"beroemd","displayNl":"beroemd","pos":"adjectief","meanings":[{"de":"berühmt, bekannt","ex":"Nu is hij heel beroemd.","exDe":"Jetzt ist er sehr berühmt."},{"de":"gefeiert, renommiert (für etwas)","ex":"Nederland is beroemd om zijn kaas.","exDe":"Die Niederlande sind berühmt für ihren Käse."}],"usage":"Prädikativ und attributiv. 'beroemd om/vanwege' = berühmt für/wegen. Steigerung: beroemder, beroemdst."},"pe2_meester":{"lemma":"meester","displayNl":"de meester","pos":"substantief","meanings":[{"de":"der Meister (Könner, große Künstler/Handwerker)","ex":"Rembrandt was een grote meester.","exDe":"Rembrandt war ein großer Meister."},{"de":"der (Grundschul-)Lehrer (männlich, etwas veraltet)","ex":"De meester leest de kinderen een verhaal voor.","exDe":"Der Lehrer liest den Kindern eine Geschichte vor."},{"de":"der Herr, Gebieter","ex":"De hond luistert naar zijn meester.","exDe":"Der Hund hört auf seinen Herrn."}],"usage":"Alltäglich vor allem im Sinne 'Grundschullehrer' (weibl. Gegenstück: 'juf'). In Kunst/Handwerk: Meister, Könner.","genus":"de","plural":"meesters","illustratable":true},"pe2_licht":{"lemma":"licht","displayNl":"het licht","pos":"substantief","meanings":[{"de":"das Licht (Helligkeit, Beleuchtung)","ex":"Hij heeft mooi licht geschilderd.","exDe":"Er hat schönes Licht gemalt."},{"de":"die Lampe, das Licht (Leuchte, z. B. im Zimmer/am Fahrrad)","ex":"Doe het licht even aan.","exDe":"Mach mal das Licht an."},{"de":"die Ampel, das Verkehrslicht (meist Plural 'lichten')","ex":"Sla bij de lichten rechts af.","exDe":"Bieg an der Ampel rechts ab."}],"usage":"Als Substantiv 'het licht'. Es gibt auch das Adjektiv 'licht' (hell/leicht) - das ist ein eigenes Wort. 'het licht aan-/uitdoen' = Licht an-/ausmachen.","genus":"het","plural":"lichten","illustratable":true},"pe2_schaduw":{"lemma":"schaduw","displayNl":"de schaduw","pos":"substantief","meanings":[{"de":"der Schatten (dunkle Fläche, Schattenbild)","ex":"In het schilderij zie je veel schaduw.","exDe":"Im Gemälde sieht man viel Schatten."},{"de":"der Schatten (kühler, sonnengeschützter Ort)","ex":"We zitten liever in de schaduw van de boom.","exDe":"Wir sitzen lieber im Schatten des Baumes."}],"usage":"'in de schaduw' = im Schatten. Gegensatz: 'de zon' / 'het licht'. Plural 'schaduwen'.","genus":"de","plural":"schaduwen","illustratable":true},"pe2_eeuw":{"lemma":"eeuw","displayNl":"de eeuw","pos":"substantief","meanings":[{"de":"das Jahrhundert","ex":"Hij leefde in de zeventiende eeuw.","exDe":"Er lebte im siebzehnten Jahrhundert."},{"de":"das Zeitalter, die Ära","ex":"De Gouden Eeuw was een rijke periode.","exDe":"Das Goldene Zeitalter war eine reiche Epoche."}],"usage":"Zeiteinheit von 100 Jahren. 'in de ... eeuw' mit Ordinalzahl. 'de Gouden Eeuw' = das (niederländische) Goldene Zeitalter.","genus":"de","plural":"eeuwen"},"pe2_portret":{"lemma":"portret","displayNl":"het portret","pos":"substantief","meanings":[{"de":"das Porträt, das Bildnis (gemalt/fotografiert)","ex":"Hij heeft veel portretten gemaakt.","exDe":"Er hat viele Porträts gemacht."}],"usage":"Bildliche Darstellung einer Person. 'een portret schilderen/maken'. Plural 'portretten'.","genus":"het","plural":"portretten","illustratable":true},"pe2_gouden":{"lemma":"gouden","displayNl":"gouden","pos":"adjectief","meanings":[{"de":"golden, aus Gold","ex":"Zij draagt een gouden ring.","exDe":"Sie trägt einen goldenen Ring."},{"de":"golden, glänzend/kostbar (bildlich)","ex":"Dit was de Gouden Eeuw.","exDe":"Das war das Goldene Zeitalter."}],"usage":"Stoffadjektiv, unveränderlich ('gouden ring', 'gouden eeuw') - bekommt kein -e. Bildlich für wertvoll/glänzend."},"pe2_nachtwacht":{"lemma":"Nachtwacht","displayNl":"de Nachtwacht","pos":"substantief","meanings":[{"de":"Die Nachtwache (berühmtes Gemälde von Rembrandt)","ex":"De Nachtwacht is heel groot.","exDe":"Die Nachtwache ist sehr groß."},{"de":"die Nachtwache, der Nachtwächter (Person/Dienst nachts)","ex":"De nachtwacht liep door de donkere straten.","exDe":"Der Nachtwächter ging durch die dunklen Straßen."}],"usage":"Groß geschrieben 'de Nachtwacht' = Rembrandts Gemälde (im Rijksmuseum). Klein 'de nachtwacht' = nächtliche Wache/Wächter, Plural 'nachtwachten'.","genus":"de","plural":"nachtwachten","illustratable":true},"pe3_dagboek":{"lemma":"dagboek","displayNl":"het dagboek","pos":"substantief","meanings":[{"de":"das Tagebuch","ex":"Anne schreef elke dag in haar dagboek.","exDe":"Anne schrieb jeden Tag in ihr Tagebuch."},{"de":"das Logbuch (Aufzeichnungen)","ex":"De onderzoeker hield een dagboek van zijn experimenten bij.","exDe":"Der Forscher führte ein Logbuch über seine Experimente."}],"usage":"Neutrum (het-woord). Plural op -en: dagboeken. Vaste combinatie: een dagboek bijhouden.","genus":"het","plural":"dagboeken","illustratable":true},"pe3_oorlog":{"lemma":"oorlog","displayNl":"de oorlog","pos":"substantief","meanings":[{"de":"der Krieg","ex":"In de oorlog moesten veel mensen vluchten.","exDe":"Im Krieg mussten viele Menschen fliehen."},{"de":"der Konflikt, die Auseinandersetzung (bildlich)","ex":"Tussen de twee bedrijven woedt een echte oorlog.","exDe":"Zwischen den beiden Firmen tobt ein regelrechter Krieg."}],"usage":"de-woord. Plural: oorlogen. Vaste combinaties: oorlog voeren, in oorlog zijn met.","genus":"de","plural":"oorlogen"},"pe3_onderduiken":{"lemma":"onderduiken","displayNl":"onderduiken","pos":"werkwoord","meanings":[{"de":"untertauchen, sich verstecken (vor Verfolgung)","ex":"De familie moest tijdens de oorlog onderduiken.","exDe":"Die Familie musste im Krieg untertauchen."},{"de":"untertauchen (unter Wasser tauchen)","ex":"De eend dook onder om vis te vangen.","exDe":"Die Ente tauchte unter, um Fisch zu fangen."}],"usage":"Scheidbaar werkwoord: onder + duiken (ik duik onder). Onregelmatig, perfectum met zijn: is ondergedoken. Verleden tijd: dook/doken onder.","conjugation":{"presens":{"ik":"duik onder","jij":"duikt onder","hij":"duikt onder","wij":"duiken onder"},"imperfectum":{"ik":"dook onder","wij":"doken onder"},"perfectum":{"aux":"zijn","participle":"ondergedoken"}}},"pe3_bang":{"lemma":"bang","displayNl":"bang","pos":"adjectief","meanings":[{"de":"ängstlich, verängstigt","ex":"Het kind was bang in het donker.","exDe":"Das Kind hatte Angst im Dunkeln."},{"de":"besorgt, in Sorge (bang zijn dat)","ex":"Ik ben bang dat we te laat komen.","exDe":"Ich fürchte, dass wir zu spät kommen."}],"usage":"Predicatief en attributief: een bang jongetje. Vaste combinaties: bang zijn voor (Angst haben vor), bang zijn dat (befürchten, dass)."},"pe3_meisje":{"lemma":"meisje","displayNl":"het meisje","pos":"substantief","meanings":[{"de":"das Mädchen","ex":"Het meisje speelde in de tuin.","exDe":"Das Mädchen spielte im Garten."},{"de":"die Freundin, das Mädchen (umgangssprachlich: Partnerin)","ex":"Hij ging met zijn meisje naar de film.","exDe":"Er ging mit seiner Freundin ins Kino."}],"usage":"Neutrum (het-woord, verkleinwoord van meid/meisje). Plural op -s: meisjes.","genus":"het","plural":"meisjes","illustratable":true},"pe3_schrijven":{"lemma":"schrijven","displayNl":"schrijven","pos":"werkwoord","meanings":[{"de":"schreiben (Text verfassen, per Hand oder am Computer)","ex":"Zij wil later boeken schrijven.","exDe":"Sie will später Bücher schreiben."},{"de":"schreiben, buchstabieren (wie ein Wort geschrieben wird)","ex":"Hoe schrijf je jouw naam?","exDe":"Wie schreibt man deinen Namen?"},{"de":"jemandem schreiben (Brief/Nachricht senden)","ex":"Ik schrijf mijn oma elke week.","exDe":"Ich schreibe meiner Oma jede Woche."}],"usage":"Onregelmatig sterk werkwoord, perfectum met hebben: heeft geschreven. Verleden tijd: schreef/schreven.","conjugation":{"presens":{"ik":"schrijf","jij":"schrijft","hij":"schrijft","wij":"schrijven"},"imperfectum":{"ik":"schreef","wij":"schreven"},"perfectum":{"aux":"hebben","participle":"geschreven"}},"illustratable":true},"pe3_vrijheid":{"lemma":"vrijheid","displayNl":"de vrijheid","pos":"substantief","meanings":[{"de":"die Freiheit (Zustand des Freiseins)","ex":"Na de oorlog vierden de mensen hun vrijheid.","exDe":"Nach dem Krieg feierten die Menschen ihre Freiheit."},{"de":"die Freiheit, der Freiraum (Recht/Möglichkeit, etwas zu tun)","ex":"Op zijn werk heeft hij veel vrijheid.","exDe":"Bei seiner Arbeit hat er viel Freiheit."}],"usage":"de-woord. Plural: vrijheden. Vaste combinaties: vrijheid van meningsuiting (Meinungsfreiheit), in vrijheid stellen (freilassen).","genus":"de","plural":"vrijheden"},"pe4_voetballer":{"lemma":"voetballer","displayNl":"de voetballer","pos":"substantief","meanings":[{"de":"der Fußballer, der Fußballspieler","ex":"Cruyff was een geweldige voetballer.","exDe":"Cruyff war ein großartiger Fußballer."}],"usage":"de-woord. Plural op -s: voetballers. Vrouwelijke vorm: voetbalster.","genus":"de","plural":"voetballers","illustratable":true},"pe4_doelpunt":{"lemma":"doelpunt","displayNl":"het doelpunt","pos":"substantief","meanings":[{"de":"das Tor (Treffer im Sport)","ex":"Hij maakte een mooi doelpunt.","exDe":"Er machte ein schönes Tor."},{"de":"der Torerfolg / der Punkt (durch ein Tor)","ex":"Het beslissende doelpunt viel in de laatste minuut.","exDe":"Das entscheidende Tor fiel in der letzten Minute."}],"usage":"Der erzielte Treffer im Fußball; das Toreschießen selbst ist 'scoren'.","genus":"het","plural":"doelpunten","illustratable":true},"pe4_ploeg":{"lemma":"ploeg","displayNl":"de ploeg","pos":"substantief","meanings":[{"de":"die Mannschaft / das Team","ex":"Zijn ploeg was Ajax.","exDe":"Seine Mannschaft war Ajax."},{"de":"der (Arbeits-)Trupp / die Schicht / Kolonne","ex":"De ploeg arbeiders begon om zeven uur.","exDe":"Der Trupp Arbeiter begann um sieben Uhr."},{"de":"der Pflug (Landwirtschaft)","ex":"De boer trok een ploeg over het land.","exDe":"Der Bauer zog einen Pflug über das Land."}],"usage":"'Ploeg' = Sportmannschaft oder Arbeitstrupp; homonym auch das Ackergerät (der Pflug).","genus":"de","plural":"ploegen","illustratable":true},"pe4_winnen":{"lemma":"winnen","displayNl":"winnen","pos":"werkwoord","meanings":[{"de":"gewinnen / siegen","ex":"Ajax wilde altijd winnen.","exDe":"Ajax wollte immer gewinnen."},{"de":"gewinnen / erlangen (etwas erhalten)","ex":"Zij heeft een prijs gewonnen.","exDe":"Sie hat einen Preis gewonnen."},{"de":"gewinnen / fördern (Rohstoffe)","ex":"Ze winnen zout uit de zee.","exDe":"Sie gewinnen Salz aus dem Meer."}],"usage":"Unregelmäßig: winnen – won – gewonnen; Perfekt mit 'hebben'.","conjugation":{"presens":{"ik":"win","jij":"wint","hij":"wint","wij":"winnen"},"imperfectum":{"ik":"won","wij":"wonnen"},"perfectum":{"aux":"hebben","participle":"gewonnen"}}},"pe4_speler":{"lemma":"speler","displayNl":"de speler","pos":"substantief","meanings":[{"de":"der Spieler (Sport/Spiel)","ex":"Hij was speler nummer veertien.","exDe":"Er war Spieler Nummer vierzehn."},{"de":"der Darsteller / Akteur (auf der Bühne)","ex":"De spelers stonden op het toneel.","exDe":"Die Darsteller standen auf der Bühne."},{"de":"das Abspielgerät (z. B. cd-speler)","ex":"De cd-speler is kapot.","exDe":"Der CD-Player ist kaputt."}],"usage":"Meist Sportler; auch Bühnendarsteller oder (in Komposita) Abspielgerät.","genus":"de","plural":"spelers","illustratable":true},"pe4_trainer":{"lemma":"trainer","displayNl":"de trainer","pos":"substantief","meanings":[{"de":"der Trainer / Coach (Sport)","ex":"Later werd hij trainer.","exDe":"Später wurde er Trainer."},{"de":"der Ausbilder / Kursleiter","ex":"De trainer legde de nieuwe methode uit.","exDe":"Der Ausbilder erklärte die neue Methode."}],"usage":"Person, die eine Mannschaft oder Gruppe anleitet und trainiert.","genus":"de","plural":"trainers","illustratable":true},"pe4_snel":{"lemma":"snel","displayNl":"snel","pos":"adjectief","meanings":[{"de":"schnell (Adjektiv)","ex":"Hij was heel snel op het veld.","exDe":"Er war sehr schnell auf dem Feld."},{"de":"schnell / rasch (Adverb)","ex":"Kom snel, we zijn te laat!","exDe":"Komm schnell, wir sind zu spät!"}],"usage":"Als Adjektiv flektiert: 'de snelle speler'; auch als Adverb gebräuchlich."},"pe5_coureur":{"lemma":"coureur","displayNl":"de coureur","pos":"substantief","meanings":[{"de":"der Rennfahrer (Auto/Motorsport)","ex":"Max is een Nederlandse coureur.","exDe":"Max ist ein niederländischer Rennfahrer."},{"de":"der Radrennfahrer","ex":"De coureurs fietsten hard de berg op.","exDe":"Die Radrennfahrer fuhren schnell den Berg hinauf."}],"usage":"Berufs- oder Wettkampffahrer im Motor- oder Radsport.","genus":"de","plural":"coureurs","illustratable":true},"pe5_race":{"lemma":"race","displayNl":"de race","pos":"substantief","meanings":[{"de":"das Rennen (Wettfahrt)","ex":"Hij wint vaak de race.","exDe":"Er gewinnt oft das Rennen."},{"de":"der Wettlauf / das Wettrennen (übertragen)","ex":"Het werd een race tegen de klok.","exDe":"Es wurde ein Wettlauf gegen die Uhr."}],"usage":"Aus dem Englischen; sportlicher Geschwindigkeitswettkampf, auch bildlich.","genus":"de","plural":"races","illustratable":true},"pe5_auto":{"lemma":"auto","displayNl":"de auto","pos":"substantief","meanings":[{"de":"das Auto, der Wagen","ex":"Zijn auto is heel snel.","exDe":"Sein Auto ist sehr schnell."},{"de":"das Kraftfahrzeug (allgemein)","ex":"We gaan met de auto naar Utrecht.","exDe":"Wir fahren mit dem Auto nach Utrecht."}],"usage":"Alltagswort; verkürzt von 'automobiel'. Plural mit Apostroph: auto's.","genus":"de","plural":"auto's","illustratable":true},"pe5_kampioen":{"lemma":"kampioen","displayNl":"de kampioen","pos":"substantief","meanings":[{"de":"der Meister, der Champion (Sieger eines Wettbewerbs)","ex":"Max is kampioen geworden.","exDe":"Max ist Meister geworden."},{"de":"der Verfechter, Vorkämpfer (für eine Sache)","ex":"Zij is een kampioen van het milieu.","exDe":"Sie ist eine Verfechterin der Umwelt."}],"usage":"Titel des Wettbewerbssiegers; auch übertragen 'Vorkämpfer'. Plural: kampioenen.","genus":"de","plural":"kampioenen","illustratable":true},"pe5_wereldkampioen":{"lemma":"wereldkampioen","displayNl":"de wereldkampioen","pos":"substantief","meanings":[{"de":"der Weltmeister (Sieger einer Weltmeisterschaft)","ex":"Hij is meerdere keren wereldkampioen.","exDe":"Er ist mehrfach Weltmeister."},{"de":"der/die Weltbeste in einem Fach (übertragen)","ex":"Nederland is wereldkampioen in waterbeheer.","exDe":"Die Niederlande sind Weltmeister im Wassermanagement."}],"usage":"Zusammensetzung wereld + kampioen; höchster Titel. Plural: wereldkampioenen.","genus":"de","plural":"wereldkampioenen","illustratable":true},"pe5_circuit":{"lemma":"circuit","displayNl":"het circuit","pos":"substantief","meanings":[{"de":"die Rennstrecke, der Rennkurs","ex":"Het circuit ligt in Zandvoort.","exDe":"Die Rennstrecke liegt in Zandvoort."},{"de":"der Stromkreis, die Schaltung (Elektronik)","ex":"Er zit een fout in het elektrische circuit.","exDe":"Im elektrischen Stromkreis ist ein Fehler."},{"de":"der Kreislauf, das (geschlossene) Netzwerk","ex":"Deze film draait in het alternatieve circuit.","exDe":"Dieser Film läuft im alternativen Kreislauf."}],"usage":"Lehnwort aus dem Französischen; het-Wort. Plural: circuits.","genus":"het","plural":"circuits","illustratable":true},"pe5_jong":{"lemma":"jong","displayNl":"jong","pos":"adjectief","meanings":[{"de":"jung (von geringem Alter)","ex":"Hij was heel jong in de Formule 1.","exDe":"Er war sehr jung in der Formel 1."},{"de":"neu, frisch, jung (z. B. Käse, Wein)","ex":"Ik hou van jonge kaas.","exDe":"Ich mag jungen Käse."},{"de":"das Junge (Tierjunges; als Substantiv 'het jong')","ex":"De poes heeft vier jongen.","exDe":"Die Katze hat vier Junge."}],"usage":"Adjektiv 'jung'; substantiviert 'het jong' = Tierjunges (Plural: jongen). Steigerung: jonger, jongst."},"pe6_prins":{"lemma":"prins","displayNl":"de prins","pos":"substantief","meanings":[{"de":"der Prinz, der Fürst (adliger Titel)","ex":"Willem was een prins van Oranje.","exDe":"Willem war ein Fürst von Oranien."},{"de":"der Karnevalsprinz (Anführer des Karnevals)","ex":"De prins opende het carnaval.","exDe":"Der Karnevalsprinz eröffnete den Karneval."}],"usage":"Adelstitel; weibliche Form 'prinses'. Plural: prinsen.","genus":"de","plural":"prinsen","illustratable":true},"pe6_opstand":{"lemma":"opstand","displayNl":"de opstand","pos":"substantief","meanings":[{"de":"der Aufstand, die Erhebung, der Aufruhr","ex":"Hij leidde de opstand tegen Spanje.","exDe":"Er führte den Aufstand gegen Spanien."},{"de":"der Aufbau, die Erhebung (Fachsprache: aufgehendes Mauerwerk/Aufriss)","ex":"De opstand van de muur is nog zichtbaar.","exDe":"Der Aufbau der Mauer ist noch sichtbar."}],"usage":"Häufig 'in opstand komen' = sich erheben. Historisch: de Opstand (Achtzigjähriger Krieg). Plural: opstanden.","genus":"de","plural":"opstanden","illustratable":true},"pe6_land":{"lemma":"land","displayNl":"het land","pos":"substantief","meanings":[{"de":"das Land, der Staat, die Nation","ex":"Hij hield van zijn land.","exDe":"Er liebte sein Land."},{"de":"das Land (im Gegensatz zur Stadt), das flache Land","ex":"Wij wonen op het land.","exDe":"Wir wohnen auf dem Land."},{"de":"der Acker, das Feld, das Grundstück","ex":"De boer bewerkt zijn land.","exDe":"Der Bauer bearbeitet sein Feld."},{"de":"das Festland, das Ufer (aan land = an Land)","ex":"De zeilers gingen aan land.","exDe":"Die Segler gingen an Land."}],"usage":"het-Wort; Plural 'landen' = Länder. Wendungen: aan land, op het platteland. Feld: Plural 'landen'.","genus":"het","plural":"landen","illustratable":true},"pe6_vader":{"lemma":"vader","displayNl":"de vader","pos":"substantief","meanings":[{"de":"Vater","ex":"Mijn vader werkt in Utrecht.","exDe":"Mein Vater arbeitet in Utrecht."},{"de":"Vater, Begründer (bildlich, z. B. 'Vater des Vaterlandes')","ex":"Men noemt hem de vader des vaderlands.","exDe":"Man nennt ihn den Vater des Vaterlandes."}],"usage":"Alltagswort für den männlichen Elternteil; bildlich auch 'Begründer/Gründervater'.","genus":"de","plural":"vaders","illustratable":true},"pe6_vijand":{"lemma":"vijand","displayNl":"de vijand","pos":"substantief","meanings":[{"de":"Feind, Gegner","ex":"Spanje was de vijand.","exDe":"Spanien war der Feind."},{"de":"Feind (Person, mit der man verfeindet ist)","ex":"Hij heeft veel vijanden gemaakt.","exDe":"Er hat sich viele Feinde gemacht."}],"usage":"Bezeichnet einen Gegner im Krieg, Konflikt oder persönlichen Streit; Gegenteil von 'vriend'.","genus":"de","plural":"vijanden"},"pe6_strijden":{"lemma":"strijden","displayNl":"strijden","pos":"werkwoord","meanings":[{"de":"kämpfen, streiten (für eine Sache)","ex":"Het volk moest lang strijden.","exDe":"Das Volk musste lange kämpfen."},{"de":"ringen, sich abmühen (um etwas erreichen)","ex":"Zij strijden voor gelijke rechten.","exDe":"Sie kämpfen für gleiche Rechte."}],"usage":"Starkes Verb (strijden – streed – gestreden). Meist im Sinne von 'für/gegen etwas kämpfen', oft übertragen; gehobener als 'vechten'.","conjugation":{"presens":{"ik":"strijd","jij":"strijdt","hij":"strijdt","wij":"strijden"},"imperfectum":{"ik":"streed","wij":"streden"},"perfectum":{"aux":"hebben","participle":"gestreden"}},"illustratable":true},"pe6_vrij":{"lemma":"vrij","displayNl":"vrij","pos":"adjectief","meanings":[{"de":"frei (nicht gefangen, unabhängig)","ex":"Hij wilde een vrij land.","exDe":"Er wollte ein freies Land."},{"de":"frei, unbesetzt (verfügbar)","ex":"Is deze stoel nog vrij?","exDe":"Ist dieser Stuhl noch frei?"},{"de":"frei, dienstfrei (arbeitsfrei)","ex":"Ik ben morgen vrij.","exDe":"Ich habe morgen frei."}],"usage":"Vielseitiges Adjektiv/Adverb: politisch/persönlich frei, verfügbar/unbesetzt oder arbeitsfrei; auch adverbial 'vrij goed' = ziemlich gut."},"pe7_geleerde":{"lemma":"geleerde","displayNl":"de geleerde","pos":"substantief","meanings":[{"de":"Gelehrter, Wissenschaftler","ex":"Erasmus was een beroemde geleerde.","exDe":"Erasmus war ein berühmter Gelehrter."},{"de":"kluger, sehr gebildeter Mensch","ex":"Vraag het maar aan een geleerde.","exDe":"Frag ruhig einen Gelehrten."}],"usage":"Substantiviertes Partizip für eine sehr gebildete, wissenschaftlich tätige Person; etwas altmodisch-gehoben, oft historisch.","genus":"de","plural":"geleerden","illustratable":true},"pe7_boek":{"lemma":"boek","displayNl":"het boek","pos":"substantief","meanings":[{"de":"Buch (zum Lesen)","ex":"Hij schreef veel boeken.","exDe":"Er schrieb viele Bücher."},{"de":"Buch, Band (als Werk/Titel)","ex":"Dit boek gaat over Nederland.","exDe":"Dieses Buch handelt von den Niederlanden."}],"usage":"Alltagswort für ein gebundenes Druck- oder Lesewerk; feste Wendungen wie 'te boek staan als' (bekannt sein als).","genus":"het","plural":"boeken","illustratable":true},"pe7_wijs":{"lemma":"wijs","displayNl":"wijs","pos":"adjectief","meanings":[{"de":"weise, klug","ex":"Hij was een wijze man.","exDe":"Er war ein weiser Mann."},{"de":"klug, vernünftig (eine kluge Entscheidung)","ex":"Dat was een wijs besluit.","exDe":"Das war eine kluge Entscheidung."}],"usage":"Adjektiv für weise/klug; in festen Wendungen: 'wijs worden uit' (schlau werden aus), 'iemand wijsmaken' (jemandem etwas weismachen)."},"pe7_denken":{"lemma":"denken","displayNl":"denken","pos":"werkwoord","meanings":[{"de":"denken, glauben, meinen","ex":"Ik denk dat hij slim was.","exDe":"Ich denke, dass er klug war."},{"de":"nachdenken (denken an/über)","ex":"Ik denk vaak aan vroeger.","exDe":"Ich denke oft an früher."},{"de":"vorhaben, beabsichtigen (denken te + Infinitiv)","ex":"Wat denk je te doen?","exDe":"Was hast du vor zu tun?"}],"usage":"Unregelmäßiges Verb (denken – dacht – gedacht). 'denken aan' = denken an, 'denken over' = nachdenken über, 'denken te' = beabsichtigen.","conjugation":{"presens":{"ik":"denk","jij":"denkt","hij":"denkt","wij":"denken"},"imperfectum":{"ik":"dacht","wij":"dachten"},"perfectum":{"aux":"hebben","participle":"gedacht"}}},"pe7_kennis":{"lemma":"kennis","displayNl":"de kennis","pos":"substantief","meanings":[{"de":"das Wissen, die Kenntnis","ex":"Zijn kennis van de Nederlandse taal is groot.","exDe":"Sein Wissen über die niederländische Sprache ist groß."},{"de":"der/die Bekannte, die Bekanntschaft","ex":"Ik kwam een oude kennis tegen in de stad.","exDe":"Ich traf einen alten Bekannten in der Stadt."}],"usage":"Bedeutung \"Wissen\" ist unzählbar (kein Plural); im Sinne von \"Bekannte(r)\" zählbar mit Plural \"kennissen\".","genus":"de","plural":"kennissen"},"pe7_vrede":{"lemma":"vrede","displayNl":"de vrede","pos":"substantief","meanings":[{"de":"der Frieden","ex":"Na de oorlog kwam er eindelijk vrede.","exDe":"Nach dem Krieg kam endlich Frieden."},{"de":"die innere Ruhe, der Seelenfrieden","ex":"Zij voelde vrede in haar hart.","exDe":"Sie fühlte Frieden in ihrem Herzen."}],"usage":"Meist unzählbar; Plural \"vredes\" selten (z. B. Friedensverträge). Redewendung: \"vrede sluiten\" = Frieden schließen.","genus":"de","plural":"vredes"},"pe7_schrijver":{"lemma":"schrijver","displayNl":"de schrijver","pos":"substantief","meanings":[{"de":"der Schriftsteller, der Autor","ex":"De schrijver signeerde zijn nieuwe boek.","exDe":"Der Schriftsteller signierte sein neues Buch."},{"de":"der Verfasser (allgemein, der etwas geschrieben hat)","ex":"De schrijver van deze brief is onbekend.","exDe":"Der Verfasser dieses Briefes ist unbekannt."}],"usage":"Weibliche Form: \"schrijfster\". Plural \"schrijvers\".","genus":"de","plural":"schrijvers","illustratable":true},"pe8_microscoop":{"lemma":"microscoop","displayNl":"de microscoop","pos":"substantief","meanings":[{"de":"das Mikroskop","ex":"Onder de microscoop zag hij duizenden cellen.","exDe":"Unter dem Mikroskop sah er Tausende von Zellen."}],"usage":"Plural \"microscopen\". Feste Wendung: \"onder de microscoop\" = unter dem Mikroskop / genau untersucht.","genus":"de","plural":"microscopen","illustratable":true},"pe8_druppel":{"lemma":"druppel","displayNl":"de druppel","pos":"substantief","meanings":[{"de":"der Tropfen","ex":"Een druppel water viel op de tafel.","exDe":"Ein Tropfen Wasser fiel auf den Tisch."},{"de":"eine winzige Menge, ein bisschen","ex":"Er zat nog een druppel wijn in de fles.","exDe":"Es war noch ein Tropfen Wein in der Flasche."}],"usage":"Plural \"druppels\". Redewendung: \"de druppel die de emmer deed overlopen\" = der Tropfen, der das Fass zum Überlaufen brachte.","genus":"de","plural":"druppels","illustratable":true},"pe8_diertje":{"lemma":"diertje","displayNl":"het diertje","pos":"substantief","meanings":[{"de":"das Tierchen, das kleine Tier","ex":"Er kroop een klein diertje over het blad.","exDe":"Ein kleines Tierchen kroch über das Blatt."}],"usage":"Verkleinerungsform (Diminutiv) von \"dier\" (das Tier); daher immer \"het\". Plural \"diertjes\".","genus":"het","plural":"diertjes","illustratable":true},"pe8_lens":{"lemma":"lens","displayNl":"de lens","pos":"substantief","meanings":[{"de":"die Linse (optisch)","ex":"De lens van de microscoop vergroot het beeld.","exDe":"Die Linse des Mikroskops vergrößert das Bild."},{"de":"die Kontaktlinse","ex":"Ik draag lenzen in plaats van een bril.","exDe":"Ich trage Kontaktlinsen statt einer Brille."},{"de":"das Objektiv (Kamera)","ex":"Hij schroefde een nieuwe lens op zijn camera.","exDe":"Er schraubte ein neues Objektiv auf seine Kamera."}],"usage":"Plural \"lenzen\". Nicht verwechseln mit \"linze\" (die Linse als Hülsenfrucht).","genus":"de","plural":"lenzen","illustratable":true},"pe8_ontdekking":{"lemma":"ontdekking","displayNl":"de ontdekking","pos":"substantief","meanings":[{"de":"die Entdeckung","ex":"De ontdekking van bacteriën veranderde de wetenschap.","exDe":"Die Entdeckung von Bakterien veränderte die Wissenschaft."},{"de":"der Fund, das Aufgespürte","ex":"Deze oude brief was een verrassende ontdekking.","exDe":"Dieser alte Brief war eine überraschende Entdeckung."}],"usage":"Plural \"ontdekkingen\". Verb dazu: \"ontdekken\" (entdecken).","genus":"de","plural":"ontdekkingen"},"pe8_klein":{"lemma":"klein","displayNl":"klein","pos":"adjectief","meanings":[{"de":"klein","ex":"De dingen waren heel klein.","exDe":"Die Dinge waren sehr klein."},{"de":"gering, unbedeutend","ex":"Het is maar een klein probleem.","exDe":"Es ist nur ein kleines Problem."},{"de":"jung (von Kindern)","ex":"Ik heb een klein broertje.","exDe":"Ich habe einen kleinen Bruder."}],"usage":"Attributiv gebeugt 'kleine' (de/het bepaald en de-woorden), onverbogen 'klein' bij onbepaalde het-woorden en predicatief."},"pe8_wetenschapper":{"lemma":"wetenschapper","displayNl":"de wetenschapper","pos":"substantief","meanings":[{"de":"der Wissenschaftler / die Wissenschaftlerin","ex":"Hij was een echte wetenschapper.","exDe":"Er war ein echter Wissenschaftler."}],"usage":"Beroepsnaam; vrouwelijke vorm ook 'wetenschapster', maar 'wetenschapper' geldt genderneutraal.","genus":"de","plural":"wetenschappers","illustratable":true},"pe9_kunstenaar":{"lemma":"kunstenaar","displayNl":"de kunstenaar","pos":"substantief","meanings":[{"de":"der Künstler / die Künstlerin","ex":"De kunstenaar heet Escher.","exDe":"Der Künstler heißt Escher."}],"usage":"Vrouwelijke vorm 'kunstenares'; meervoud 'kunstenaars'.","genus":"de","plural":"kunstenaars","illustratable":true},"pe9_trap":{"lemma":"trap","displayNl":"de trap","pos":"substantief","meanings":[{"de":"die Treppe","ex":"De trap gaat omhoog en omlaag.","exDe":"Die Treppe geht hoch und runter."},{"de":"der Tritt, der Fußtritt (Stoß mit dem Fuß)","ex":"De ezel gaf hem een trap.","exDe":"Der Esel gab ihm einen Tritt."},{"de":"der Grad, die Stufe (z. B. Steigerungsstufe, Verbrennungsgrad)","ex":"Dat is de overtreffende trap.","exDe":"Das ist die höchste Steigerungsstufe."}],"usage":"Homoniem: 'trap' = Treppe én 'trap' = Tritt (van trappen). Meervoud 'trappen'.","genus":"de","plural":"trappen","illustratable":true},"pe9_tekening":{"lemma":"tekening","displayNl":"de tekening","pos":"substantief","meanings":[{"de":"die Zeichnung","ex":"De tekening is heel bijzonder.","exDe":"Die Zeichnung ist sehr besonders."},{"de":"die Musterung, Zeichnung (z. B. auf Fell oder Flügeln)","ex":"De vlinder heeft een mooie tekening op zijn vleugels.","exDe":"Der Schmetterling hat eine schöne Zeichnung auf seinen Flügeln."}],"usage":"Afgeleid van 'tekenen'; meervoud 'tekeningen'.","genus":"de","plural":"tekeningen","illustratable":true},"pe9_onmogelijk":{"lemma":"onmogelijk","displayNl":"onmogelijk","pos":"adjectief","meanings":[{"de":"unmöglich","ex":"Het is een onmogelijke figuur.","exDe":"Es ist eine unmögliche Figur."},{"de":"unmöglich, gar nicht (als Verstärkung: es geht nicht)","ex":"Ik kan onmogelijk op tijd zijn.","exDe":"Ich kann unmöglich pünktlich sein."}],"usage":"Antoniem van 'mogelijk'. Wordt zowel bijvoeglijk als bijwoordelijk gebruikt."},"pe9_vorm":{"lemma":"vorm","displayNl":"de vorm","pos":"substantief","meanings":[{"de":"die Form, die Gestalt","ex":"De vormen passen precies in elkaar.","exDe":"Die Formen passen genau ineinander."},{"de":"die Form (Art und Weise, Erscheinungsform)","ex":"Dit is een moderne vorm van kunst.","exDe":"Das ist eine moderne Form der Kunst."},{"de":"die (körperliche) Verfassung, Form","ex":"De speler is goed in vorm.","exDe":"Der Spieler ist gut in Form."},{"de":"die Backform, Gießform","ex":"Giet het beslag in de vorm.","exDe":"Gieß den Teig in die Form."}],"usage":"Meervoud 'vormen'. Vaste uitdrukking 'in vorm zijn' = gut in Form sein.","genus":"de","plural":"vormen"},"pe9_hand":{"lemma":"hand","displayNl":"de hand","pos":"substantief","meanings":[{"de":"die Hand","ex":"Op de tekening tekent de hand zichzelf.","exDe":"Auf der Zeichnung zeichnet die Hand sich selbst."},{"de":"die Handschrift","ex":"Ik herken zijn hand meteen.","exDe":"Ich erkenne seine Handschrift sofort."}],"usage":"Meervoud 'handen'. Talrijke uitdrukkingen: 'de hand geven', 'iets bij de hand hebben', 'aan de hand zijn'.","genus":"de","plural":"handen","illustratable":true},"pe9_wereld":{"lemma":"wereld","displayNl":"de wereld","pos":"substantief","meanings":[{"de":"die Welt (Erde, Erdkugel)","ex":"Het is een vreemde wereld.","exDe":"Es ist eine seltsame Welt."},{"de":"die Welt (Bereich, Sphäre)","ex":"Zij leeft in haar eigen wereld.","exDe":"Sie lebt in ihrer eigenen Welt."}],"usage":"Neutrale Alltags- und Bildungssprache.","genus":"de","plural":"werelden","illustratable":true},"pe10_podium":{"lemma":"podium","displayNl":"het podium","pos":"substantief","meanings":[{"de":"die Bühne, das Podium","ex":"Hij mag op grote podia staan.","exDe":"Er darf auf großen Bühnen stehen."},{"de":"das Siegertreppchen","ex":"De renner eindigde op het podium.","exDe":"Der Fahrer landete auf dem Podium."}],"usage":"Plural meist podia, umgangssprachlich auch podiums.","genus":"het","plural":"podia","illustratable":true},"pe10_luisteren":{"lemma":"luisteren","displayNl":"luisteren","pos":"werkwoord","meanings":[{"de":"hören, zuhören","ex":"Je kunt zijn show online luisteren.","exDe":"Man kann seine Show online hören."},{"de":"auf jemanden hören, gehorchen","ex":"Het kind wil niet naar zijn moeder luisteren.","exDe":"Das Kind will nicht auf seine Mutter hören."}],"usage":"Oft mit Präposition: luisteren naar (jemandem/etwas zuhören).","conjugation":{"presens":{"ik":"luister","jij":"luistert","hij":"luistert","wij":"luisteren"},"imperfectum":{"ik":"luisterde","wij":"luisterden"},"perfectum":{"aux":"hebben","participle":"geluisterd"}}},"pe10_publiek":{"lemma":"publiek","displayNl":"het publiek","pos":"substantief","meanings":[{"de":"das Publikum","ex":"Het publiek wil meer muziek.","exDe":"Das Publikum will mehr Musik."},{"de":"die Öffentlichkeit","ex":"Het museum is open voor het publiek.","exDe":"Das Museum ist für die Öffentlichkeit geöffnet."}],"usage":"Kollektivum, meist im Singular; als Adjektiv bedeutet publiek auch oeffentlich.","genus":"het","illustratable":true},"my1_jongen":{"lemma":"jongen","displayNl":"de jongen","pos":"substantief","meanings":[{"de":"der Junge","ex":"De jongen ziet een gat in de dijk.","exDe":"Der Junge sieht ein Loch im Deich."},{"de":"der Kerl, junger Mann (umgangssprachlich)","ex":"Hij is een aardige jongen.","exDe":"Er ist ein netter Kerl."}],"usage":"Plural jongens auch als lockere Anrede (Leute, Jungs).","genus":"de","plural":"jongens","illustratable":true},"my1_vinger":{"lemma":"vinger","displayNl":"de vinger","pos":"substantief","meanings":[{"de":"der Finger","ex":"Hij stopt zijn vinger in het gat.","exDe":"Er steckt seinen Finger in das Loch."}],"usage":"Neutral, alltäglich.","genus":"de","plural":"vingers","illustratable":true},"my1_dijk":{"lemma":"dijk","displayNl":"de dijk","pos":"substantief","meanings":[{"de":"der Deich, der Damm","ex":"De dijk beschermt het land.","exDe":"Der Deich schützt das Land."}],"usage":"Zentraler Begriff der niederländischen Wasserlandschaft.","genus":"de","plural":"dijken","illustratable":true},"my1_gat":{"lemma":"gat","displayNl":"het gat","pos":"substantief","meanings":[{"de":"das Loch","ex":"Er is een gat in de muur.","exDe":"Es ist ein Loch in der Mauer."},{"de":"die Lücke, die Öffnung","ex":"Er zit een gat in mijn agenda.","exDe":"In meinem Terminkalender ist eine Lücke."},{"de":"der Hintern, Po (umgangssprachlich)","ex":"Sta op je luie gat!","exDe":"Steh auf deinem faulen Hintern auf!"}],"usage":"Grundbedeutung Loch; umgangssprachlich auch Hintern oder abgelegenes Kaff.","genus":"het","plural":"gaten","illustratable":true},"my1_redden":{"lemma":"redden","displayNl":"redden","pos":"werkwoord","meanings":[{"de":"retten","ex":"De brandweer kon de kat redden.","exDe":"Die Feuerwehr konnte die Katze retten."},{"de":"zurechtkommen, es schaffen","ex":"Maak je geen zorgen, ik red het wel.","exDe":"Mach dir keine Sorgen, ich schaffe das schon."}],"usage":"Alltagsverb; in der Bedeutung 'zurechtkommen' oft reflexiv-ähnlich mit 'het' ('ik red het'). Hilfsverb hebben.","conjugation":{"presens":{"ik":"red","jij":"redt","hij":"redt","wij":"redden"},"imperfectum":{"ik":"redde","wij":"redden"},"perfectum":{"aux":"hebben","participle":"gered"}},"illustratable":true},"my1_verhaal":{"lemma":"verhaal","displayNl":"het verhaal","pos":"substantief","meanings":[{"de":"die Geschichte, die Erzählung","ex":"Oma vertelt elke avond een verhaal.","exDe":"Oma erzählt jeden Abend eine Geschichte."},{"de":"die Story, der Bericht (Version der Ereignisse)","ex":"Volgens zijn verhaal was het een ongeluk.","exDe":"Seiner Version nach war es ein Unfall."}],"usage":"Neutrum (het). Redewendung 'verhaal halen' = sich beschweren/Rechenschaft fordern.","genus":"het","plural":"verhalen"},"my1_verzonnen":{"lemma":"verzinnen","displayNl":"verzinnen","pos":"werkwoord","meanings":[{"de":"sich ausdenken, erfinden","ex":"Kun jij een leuk verhaal verzinnen?","exDe":"Kannst du dir eine schöne Geschichte ausdenken?"},{"de":"sich einfallen lassen (Lösung/Idee)","ex":"We moeten snel iets verzinnen.","exDe":"Wir müssen uns schnell etwas einfallen lassen."}],"usage":"Starkes Verb; die Roh-Form 'verzonnen' ist das Partizip Perfekt. Hilfsverb hebben. Ablaut i–o–o (verzinnen–verzon–verzonnen).","conjugation":{"presens":{"ik":"verzin","jij":"verzint","hij":"verzint","wij":"verzinnen"},"imperfectum":{"ik":"verzon","wij":"verzonnen"},"perfectum":{"aux":"hebben","participle":"verzonnen"}}},"my2_oranje":{"lemma":"oranje","displayNl":"oranje","pos":"adjectief","meanings":[{"de":"orange (Farbe)","ex":"De ondergaande zon kleurt de lucht oranje.","exDe":"Die untergehende Sonne färbt den Himmel orange."},{"de":"Oranje (niederländische Nationalfarbe / das Königshaus, die Nationalelf)","ex":"Tijdens het WK is het hele land oranje.","exDe":"Während der WM ist das ganze Land orange (im Oranje-Fieber)."}],"usage":"Als Adjektiv unveränderlich (het oranje shirt). Großgeschrieben 'Oranje' steht für das Königshaus und die niederländische Nationalmannschaft."},"my2_koning":{"lemma":"koning","displayNl":"de koning","pos":"substantief","meanings":[{"de":"der König","ex":"De koning woont in Den Haag.","exDe":"Der König wohnt in Den Haag."},{"de":"der König (Schachfigur, Spielkarte)","ex":"Hij zette de koning schaakmat.","exDe":"Er setzte den König schachmatt."}],"usage":"de-Wort. Niederländischer König aktuell Willem-Alexander; weibliche Form 'koningin'.","genus":"de","plural":"koningen","illustratable":true},"my2_koningin":{"lemma":"koningin","displayNl":"de koningin","pos":"substantief","meanings":[{"de":"die Königin","ex":"De koningin heet Máxima.","exDe":"Die Königin heißt Máxima."},{"de":"die Dame (Schachfigur), Königin (Spielkarte); Bienenkönigin","ex":"De koningin is het sterkste stuk op het schaakbord.","exDe":"Die Dame ist die stärkste Figur auf dem Schachbrett."}],"usage":"de-Wort, Plural koninginnen (Verdopplung des n). Auch 'Bienenkönigin' und Schachdame.","genus":"de","plural":"koninginnen","illustratable":true},"my2_kleur":{"lemma":"kleur","displayNl":"de kleur","pos":"substantief","meanings":[{"de":"die Farbe","ex":"Welke kleur vind jij het mooist?","exDe":"Welche Farbe findest du am schönsten?"},{"de":"die Gesichtsfarbe, der Teint","ex":"Na de vakantie had ze een gezonde kleur.","exDe":"Nach dem Urlaub hatte sie eine gesunde Gesichtsfarbe."}],"usage":"de-Wort, Plural kleuren. Redewendung 'kleur bekennen' = Farbe bekennen/sich klar positionieren.","genus":"de","plural":"kleuren"},"my2_vlag":{"lemma":"vlag","displayNl":"de vlag","pos":"substantief","meanings":[{"de":"die Flagge, die Fahne","ex":"De vlag is rood, wit en blauw.","exDe":"Die Flagge ist rot, weiß und blau."}],"usage":"de-Wort, Plural vlaggen. Redewendung 'de vlag uithangen' = feiern/die Fahne hissen.","genus":"de","plural":"vlaggen","illustratable":true},"my2_voetbal":{"lemma":"voetbal","displayNl":"het voetbal","pos":"substantief","meanings":[{"de":"der Fußball (Sportart, Spiel)","ex":"Voetbal is in Nederland heel populair.","exDe":"Fußball ist in den Niederlanden sehr beliebt."},{"de":"der Fußball (der Ball)","ex":"De voetbal rolde het veld op.","exDe":"Der Fußball rollte aufs Feld."}],"usage":"Als Sportart 'het voetbal' (het-Wort). Der konkrete Ball dagegen ist 'de voetbal' (de-Wort) mit Plural 'voetballen'.","genus":"het","plural":"voetballen","illustratable":true},"my3_molen":{"lemma":"molen","displayNl":"de molen","pos":"substantief","meanings":[{"de":"die (Wind-)Mühle","ex":"De molen staat aan het water.","exDe":"Die Mühle steht am Wasser."},{"de":"das Mühlwerk / die Mahlvorrichtung","ex":"De molen maalt het graan tot meel.","exDe":"Die Mühle mahlt das Korn zu Mehl."}],"usage":"Oft speziell 'windmolen' (Windmühle). Plural 'molens'.","genus":"de","plural":"molens","illustratable":true},"my3_polder":{"lemma":"polder","displayNl":"de polder","pos":"substantief","meanings":[{"de":"der Polder (eingedeichtes, entwässertes Land)","ex":"De polder ligt onder de zeespiegel.","exDe":"Der Polder liegt unter dem Meeresspiegel."}],"usage":"Typisch niederländisches Landstück, das dem Wasser abgerungen und durch Deiche geschützt ist. Plural 'polders'.","genus":"de","plural":"polders","illustratable":true},"my3_zee":{"lemma":"zee","displayNl":"de zee","pos":"substantief","meanings":[{"de":"das Meer, die See","ex":"De zee is dichtbij.","exDe":"Das Meer ist nah."},{"de":"eine große Menge, ein Meer von etwas (bildlich)","ex":"Ze had een zee van tijd.","exDe":"Sie hatte alle Zeit der Welt."}],"usage":"Plural 'zeeën'. Feste Wendungen wie 'aan zee' (am Meer) und 'een zee van tijd/ruimte' (jede Menge Zeit/Platz).","genus":"de","plural":"zeeën","illustratable":true},"my3_water":{"lemma":"water","displayNl":"het water","pos":"substantief","meanings":[{"de":"das Wasser (Flüssigkeit)","ex":"Ik drink een glas water.","exDe":"Ich trinke ein Glas Wasser."},{"de":"das Gewässer (Kanal, Fluss, See)","ex":"Het huis staat aan het water.","exDe":"Das Haus steht am Wasser."}],"usage":"Als Flüssigkeit meist ohne Plural; im Sinne von Gewässern Plural 'wateren'. Sehr häufig in Zusammensetzungen (drinkwater, oppervlaktewater).","genus":"het","plural":"wateren","illustratable":true},"my3_grond":{"lemma":"grond","displayNl":"de grond","pos":"substantief","meanings":[{"de":"der Boden, die Erde (Erdreich)","ex":"De grond is hier heel nat.","exDe":"Der Boden ist hier sehr nass."},{"de":"der Boden, der Fußboden (Untergrund unter den Füßen)","ex":"Het boek viel op de grond.","exDe":"Das Buch fiel auf den Boden."},{"de":"der Grund, der Anlass (Ursache)","ex":"Er is geen grond voor je angst.","exDe":"Es gibt keinen Grund für deine Angst."}],"usage":"Konkret Erdreich/Fußboden und abstrakt 'Grund/Anlass'. Plural 'gronden'. Wendung 'op de grond' (auf dem Boden), 'te gronde gaan' (zugrunde gehen).","genus":"de","plural":"gronden","illustratable":true},"my3_droog":{"lemma":"droog","displayNl":"droog","pos":"adjectief","meanings":[{"de":"trocken (nicht nass)","ex":"Het land is nu droog.","exDe":"Das Land ist jetzt trocken."},{"de":"trocken, nüchtern (Humor, Art)","ex":"Hij heeft een droge humor.","exDe":"Er hat einen trockenen Humor."}],"usage":"Steigerung: droog – droger – droogst. Attributiv 'het droge land'. Übertragen für nüchternen, lakonischen Humor."},"my3_bouwen":{"lemma":"bouwen","displayNl":"bouwen","pos":"werkwoord","meanings":[{"de":"bauen, errichten","ex":"Ze bouwen een sterke dijk.","exDe":"Sie bauen einen starken Deich."},{"de":"auf jemanden/etwas bauen, vertrauen (bouwen op)","ex":"Je kunt op mij bouwen.","exDe":"Du kannst auf mich bauen."}],"usage":"Regelmäßiges Verb. Mit 'op' im Sinne von vertrauen ('op iemand bouwen'). Hilfsverb 'hebben'.","conjugation":{"presens":{"ik":"bouw","jij":"bouwt","hij":"bouwt","wij":"bouwen"},"imperfectum":{"ik":"bouwde","wij":"bouwden"},"perfectum":{"aux":"hebben","participle":"gebouwd"}},"illustratable":true},"my4_tulp":{"lemma":"tulp","displayNl":"de tulp","pos":"substantief","meanings":[{"de":"die Tulpe","ex":"De tulp is een mooie voorjaarsbloem.","exDe":"Die Tulpe ist eine schöne Frühlingsblume."}],"usage":"Klassische niederländische Blume; Plural 'tulpen'. Bekannt aus den Bollenvelden.","genus":"de","plural":"tulpen","illustratable":true},"my4_bloem":{"lemma":"bloem","displayNl":"de bloem","pos":"substantief","meanings":[{"de":"die Blume, die Blüte","ex":"Ik koop een bloem voor mijn moeder.","exDe":"Ich kaufe eine Blume für meine Mutter."},{"de":"das Mehl (feines Weizenmehl)","ex":"Voor het brood heb je bloem, water en gist nodig.","exDe":"Für das Brot brauchst du Mehl, Wasser und Hefe."}],"usage":"Homonym: 'bloem' = Blume (Plural bloemen) und = Mehl (feines Auszugsmehl, kein Plural). Unterschied zu 'meel' (grobes Mehl).","genus":"de","plural":"bloemen","illustratable":true},"my4_bol":{"lemma":"bol","displayNl":"de bol","pos":"substantief","meanings":[{"de":"die Blumenzwiebel","ex":"In de herfst plant je de bollen in de grond.","exDe":"Im Herbst pflanzt man die Zwiebeln in die Erde."},{"de":"die Kugel, der runde Körper","ex":"De aarde is een bol.","exDe":"Die Erde ist eine Kugel."},{"de":"die Kugel (z. B. Eiskugel)","ex":"Ik wil graag twee bollen ijs.","exDe":"Ich hätte gern zwei Kugeln Eis."}],"usage":"Mehrdeutig: Blumenzwiebel (Tulpen), geometrische Kugel und Portion (bol ijs). Adjektiv 'bol' = gewölbt/rund.","genus":"de","plural":"bollen","illustratable":true},"my4_geld":{"lemma":"geld","displayNl":"het geld","pos":"substantief","meanings":[{"de":"das Geld","ex":"Hij heeft veel geld op de bank.","exDe":"Er hat viel Geld auf der Bank."},{"de":"die Geldmittel, die Mittel (meist Plural 'gelden')","ex":"De gemeente heeft gelden voor nieuwe scholen.","exDe":"Die Gemeinde hat Mittel für neue Schulen."}],"usage":"Meist unzählbar im Singular; Plural 'gelden' nur im Sinne von Geldmitteln/Fonds. Redewendung: 'geld verdienen'.","genus":"het","plural":"gelden","illustratable":true},"my4_duur":{"lemma":"duur","displayNl":"duur","pos":"adjectief","meanings":[{"de":"teuer","ex":"De tulp was heel duur.","exDe":"Die Tulpe war sehr teuer."},{"de":"die Dauer (als Substantiv 'de duur')","ex":"De duur van de film is twee uur.","exDe":"Die Dauer des Films beträgt zwei Stunden."}],"usage":"Als Adjektiv 'duur' = teuer (Steigerung: duurder, duurst). Homonym als Substantiv 'de duur' = Dauer (nur Singular)."},"my4_kopen":{"lemma":"kopen","displayNl":"kopen","pos":"werkwoord","meanings":[{"de":"kaufen","ex":"Ik wil een nieuwe fiets kopen.","exDe":"Ich möchte ein neues Fahrrad kaufen."}],"usage":"Unregelmäßiges Verb; Präteritum 'kocht/kochten', Partizip 'gekocht'. Gegenteil: 'verkopen'.","conjugation":{"presens":{"ik":"koop","jij":"koopt","hij":"koopt","wij":"kopen"},"imperfectum":{"ik":"kocht","wij":"kochten"},"perfectum":{"aux":"hebben","participle":"gekocht"}},"illustratable":true},"my4_prijs":{"lemma":"prijs","displayNl":"de prijs","pos":"substantief","meanings":[{"de":"der Preis (Kosten)","ex":"De prijs van de bollen was heel hoog.","exDe":"Der Preis der Zwiebeln war sehr hoch."},{"de":"der Preis, die Auszeichnung (Gewinn)","ex":"Zij won de eerste prijs in de wedstrijd.","exDe":"Sie gewann den ersten Preis im Wettbewerb."}],"usage":"Homonym: Kaufpreis und Auszeichnung/Trophäe. Plural 'prijzen'. Redewendung: 'op prijs stellen' = schätzen.","genus":"de","plural":"prijzen"},"my5_fietsen":{"lemma":"fietsen","displayNl":"fietsen","pos":"werkwoord","meanings":[{"de":"Rad fahren, mit dem Fahrrad fahren","ex":"Wij fietsen elke dag naar school.","exDe":"Wir fahren jeden Tag mit dem Rad zur Schule."}],"usage":"Regelmäßiges Verb. Perfekt mit 'hebben' (Tätigkeit) oder 'zijn' (Ortswechsel: 'Ik ben naar huis gefietst'). Nicht verwechseln mit dem Substantiv-Plural 'fietsen' = Fahrräder.","conjugation":{"presens":{"ik":"fiets","jij":"fietst","hij":"fietst","wij":"fietsen"},"imperfectum":{"ik":"fietste","wij":"fietsten"},"perfectum":{"aux":"hebben","participle":"gefietst"}},"illustratable":true},"my5_wiel":{"lemma":"wiel","displayNl":"het wiel","pos":"substantief","meanings":[{"de":"das Rad (Laufrad, z. B. am Fahrrad oder Auto)","ex":"De fiets heeft twee wielen.","exDe":"Das Fahrrad hat zwei Räder."},{"de":"das Rad, das Steuerrad / Lenkrad (allgemein rundes, drehbares Rad)","ex":"Het wiel van de kruiwagen is kapot.","exDe":"Das Rad der Schubkarre ist kaputt."},{"de":"der Kolk, das (Deichbruch-)Wasserloch (regional, durch Deichbruch entstandener Teich)","ex":"Achter de dijk ligt een diep wiel.","exDe":"Hinter dem Deich liegt ein tiefer Kolk."}],"usage":"Sächliches Substantiv (het). Plural wielen. Diminutiv: wieltje. Für das Lenkrad im Auto sagt man meist 'stuur', nicht 'wiel'.","genus":"het","plural":"wielen","illustratable":true},"my5_weg":{"lemma":"weg","displayNl":"de weg","pos":"substantief","meanings":[{"de":"der Weg, die Straße (Fahrbahn, Verkehrsweg)","ex":"Op de wegen zijn veel fietsers.","exDe":"Auf den Wegen sind viele Radfahrer."},{"de":"der Weg, die Route (Strecke von A nach B)","ex":"Weet jij de weg naar het station?","exDe":"Kennst du den Weg zum Bahnhof?"},{"de":"der Weg (übertragen: Art und Weise, Vorgehen)","ex":"We zoeken een andere weg om het op te lossen.","exDe":"Wir suchen einen anderen Weg, um es zu lösen."}],"usage":"Utrum-Substantiv (de). Plural wegen (mit langem Vokal: weg → wegen). Nicht verwechseln mit dem Adverb/Adjektiv 'weg' = fort, verschwunden ('mijn sleutels zijn weg').","genus":"de","plural":"wegen","illustratable":true},"my5_fietser":{"lemma":"fietser","displayNl":"de fietser","pos":"substantief","meanings":[{"de":"der Radfahrer, die Radfahrerin (Person, die Fahrrad fährt)","ex":"De fietser wacht voor het licht.","exDe":"Der Radfahrer wartet vor der Ampel."}],"usage":"Utrum-Substantiv (de). Plural fietsers. Weibliche Form ebenfalls 'fietser' (im Niederländischen keine gesonderte weibliche Endung nötig). Abgeleitet von 'fietsen' (Fahrrad fahren).","genus":"de","plural":"fietsers","illustratable":true},"my5_stad":{"lemma":"stad","displayNl":"de stad","pos":"substantief","meanings":[{"de":"die Stadt (größere Ortschaft)","ex":"In de steden staan veel fietsen.","exDe":"In den Städten stehen viele Fahrräder."},{"de":"die (Innen-)Stadt, das Stadtzentrum (in Wendungen wie 'naar de stad gaan')","ex":"Ik ga vanmiddag de stad in om te winkelen.","exDe":"Ich gehe heute Nachmittag in die Stadt zum Einkaufen."}],"usage":"Utrum-Substantiv (de). Unregelmäßiger Plural: steden (mit Vokalwechsel a → e). Diminutiv: stadje. Wendung 'de stad in' = in die Innenstadt gehen.","genus":"de","plural":"steden","illustratable":true},"my6_pakje":{"lemma":"pakje","displayNl":"het pakje","pos":"substantief","meanings":[{"de":"das Päckchen, das kleine Paket (Postsendung, Geschenk)","ex":"Er ligt een pakje voor de deur.","exDe":"Ein Päckchen liegt vor der Tür."},{"de":"die Schachtel, das Päckchen (kleine Verpackungseinheit, z. B. pakje sigaretten)","ex":"Hij kocht een pakje kauwgom.","exDe":"Er kaufte ein Päckchen Kaugummi."},{"de":"das Kostüm, der Anzug (kleines/schickes Kleidungsstück, umgangssprachlich)","ex":"Zij droeg een mooi pakje op het feest.","exDe":"Sie trug ein hübsches Kostüm auf dem Fest."}],"usage":"Sächliches Substantiv (het), Diminutiv von 'pak'. Plural pakjes. Im Sinterklaas-Kontext meist das eingepackte Geschenk. Als Mengenangabe: 'een pakje boter' (ein Päckchen Butter).","genus":"het","plural":"pakjes","illustratable":true},"my6_schoen":{"lemma":"schön","displayNl":"de schön","pos":"substantief","meanings":[{"de":"der Schuh (Fußbekleidung)","ex":"De kinderen zetten hun schön.","exDe":"Die Kinder stellen ihren Schuh (auf, für Sinterklaas)."},{"de":"der Schuh (Sinterklaas-Brauch: den Schuh vor dem Kamin hinstellen)","ex":"Vanavond mag ik mijn schön zetten.","exDe":"Heute Abend darf ich meinen Schuh hinstellen."}],"usage":"Utrum-Substantiv (de). Plural schönen. Diminutiv: schöntje. Redewendung 'de schön zetten' = beim Sinterklaas-Fest den Schuh aufstellen; 'iemand iets in de schönen schuiven' = jemandem etwas in die Schuhe schieben.","genus":"de","plural":"schönen","illustratable":true},"my6_pepernoot":{"lemma":"pepernoot","displayNl":"de pepernoot","pos":"substantief","meanings":[{"de":"das Pfeffernüsschen (kleines, würziges Gebäck zum Sinterklaas-Fest)","ex":"Ik eet graag pepernoten.","exDe":"Ich esse gern Pfeffernüsschen."}],"usage":"Utrum-Substantiv (de). Plural pepernoten. Typisches Gebäck rund um Sinterklaas; wird umgangssprachlich oft mit den würfelförmigen 'kruidnoten' gleichgesetzt, streng genommen ist die echte pepernoot flacher und teigiger. Meist im Plural verwendet.","genus":"de","plural":"pepernoten","illustratable":true},"my6_stoomboot":{"lemma":"stoomboot","displayNl":"de stoomboot","pos":"substantief","meanings":[{"de":"das Dampfschiff, der Dampfer (mit Dampfmaschine angetriebenes Schiff)","ex":"Sinterklaas komt met de stoomboot.","exDe":"Sinterklaas kommt mit dem Dampfschiff."}],"usage":"Utrum-Substantiv (de). Plural stoomboten. Zusammensetzung aus 'stoom' (Dampf) + 'boot' (Boot). Fester Bestandteil des Sinterklaas-Brauchtums (die Ankunft mit der stoomboot aus Spanien).","genus":"de","plural":"stoomboten","illustratable":true},"my6_vieren":{"lemma":"vieren","displayNl":"vieren","pos":"werkwoord","meanings":[{"de":"feiern","ex":"Wij vieren Sinterklaas met de hele familie.","exDe":"Wir feiern Sinterklaas mit der ganzen Familie."},{"de":"begehen (ein Fest/Jubiläum)","ex":"Ze vieren vandaag hun trouwdag.","exDe":"Sie begehen heute ihren Hochzeitstag."},{"de":"fieren, lockern, nachlassen lassen (Seil)","ex":"De matroos viert het touw langzaam.","exDe":"Der Matrose lässt das Seil langsam nach."}],"usage":"Regelmäßiges Verb. Mit 'feest', 'verjaardag', 'Sinterklaas', 'Kerst' etc. Auch nautisch 'ein Seil fieren'.","conjugation":{"presens":{"ik":"vier","jij":"viert","hij":"viert","wij":"vieren"},"imperfectum":{"ik":"vierde","wij":"vierden"},"perfectum":{"aux":"hebben","participle":"gevierd"}},"illustratable":true},"my6_geven":{"lemma":"geven","displayNl":"geven","pos":"werkwoord","meanings":[{"de":"geben, reichen","ex":"Sinterklaas geeft de kinderen cadeaus.","exDe":"Sinterklaas gibt den Kindern Geschenke."},{"de":"schenken, überreichen","ex":"Ik geef mijn moeder bloemen.","exDe":"Ich schenke meiner Mutter Blumen."},{"de":"ausmachen, stören (in 'het geeft niet')","ex":"Sorry! - Het geeft niet.","exDe":"Entschuldigung! - Das macht nichts."}],"usage":"Unregelmäßiges Verb (gaf/gaven, gegeven). Häufige Wendungen: 'een feest geven', 'les geven', 'het geeft niet'.","conjugation":{"presens":{"ik":"geef","jij":"geeft","hij":"geeft","wij":"geven"},"imperfectum":{"ik":"gaf","wij":"gaven"},"perfectum":{"aux":"hebben","participle":"gegeven"}},"illustratable":true},"my7_regel":{"lemma":"regel","displayNl":"de regel","pos":"substantief","meanings":[{"de":"die Regel, Vorschrift","ex":"Er is een duidelijke regel voor bezoekers.","exDe":"Es gibt eine klare Regel für Besucher."},{"de":"die Zeile (Text)","ex":"Lees de eerste regel van het gedicht.","exDe":"Lies die erste Zeile des Gedichts."},{"de":"die Menstruation, die Regel","ex":"Ze heeft last van haar regel.","exDe":"Sie hat Beschwerden wegen ihrer Periode."}],"usage":"Häufig 'de regels' (Vorschriften). Wendung 'in de regel' = in der Regel, meistens.","genus":"de","plural":"regels"},"my7_mogen":{"lemma":"mogen","displayNl":"mogen","pos":"werkwoord","meanings":[{"de":"dürfen","ex":"Kinderen mogen hier niet naar binnen.","exDe":"Kinder dürfen hier nicht hinein."},{"de":"mögen, gernhaben","ex":"Ik mag mijn nieuwe buurman graag.","exDe":"Ich mag meinen neuen Nachbarn gern."}],"usage":"Modalverb, im Singular unregelmäßig (ik/jij/hij mag). Perfekt selten 'gemogen'; Bedeutung 'gernhaben' oft mit 'graag'.","conjugation":{"presens":{"ik":"mag","jij":"mag","hij":"mag","wij":"mogen"},"imperfectum":{"ik":"mocht","wij":"mochten"},"perfectum":{"aux":"hebben","participle":"gemogen"}}},"my7_verboden":{"lemma":"verboden","displayNl":"verboden","pos":"adjectief","meanings":[{"de":"verboten, untersagt","ex":"Roken is hier verboden.","exDe":"Rauchen ist hier verboten."},{"de":"unerlaubt, verboten (attributiv)","ex":"Dit is verboden terrein.","exDe":"Das ist verbotenes Gelände."}],"usage":"Ursprünglich Partizip von 'verbieden'. Als Adjektiv: 'verboden toegang' = Zutritt verboten."},"my7_toestaan":{"lemma":"toestaan","displayNl":"toestaan","pos":"werkwoord","meanings":[{"de":"erlauben, gestatten","ex":"De ouders staan het bezoek toe.","exDe":"Die Eltern erlauben den Besuch."},{"de":"dulden, zulassen","ex":"De stad staat het onder strenge regels toe.","exDe":"Die Stadt duldet es unter strengen Regeln."}],"usage":"Trennbares Verb (toe + staan), unregelmäßig (stond toe, toegestaan). Oft mit Dativobjekt: 'iemand iets toestaan'.","conjugation":{"presens":{"ik":"sta toe","jij":"staat toe","hij":"staat toe","wij":"staan toe"},"imperfectum":{"ik":"stond toe","wij":"stonden toe"},"perfectum":{"aux":"hebben","participle":"toegestaan"}}},"my7_coffeeshop":{"lemma":"coffeeshop","displayNl":"de coffeeshop","pos":"substantief","meanings":[{"de":"der Coffeeshop (niederl. Cannabis-Lokal)","ex":"De coffeeshop is in het centrum van de stad.","exDe":"Der Coffeeshop ist im Zentrum der Stadt."}],"usage":"In den Niederlanden ein lizenziertes Lokal für den Verkauf von Cannabis (nicht mit einem Café zu verwechseln).","genus":"de","plural":"coffeeshops","illustratable":true},"my7_volwassen":{"lemma":"volwassen","displayNl":"volwassen","pos":"adjectief","meanings":[{"de":"erwachsen","ex":"Alleen volwassen mensen mogen naar binnen.","exDe":"Nur erwachsene Menschen dürfen hinein."},{"de":"reif, ausgereift (übertragen)","ex":"Hij heeft een volwassen kijk op het leven.","exDe":"Er hat eine reife Sicht auf das Leben."}],"usage":"Adjektiv; substantiviert 'de volwassene' = der/die Erwachsene. Gegensatz: 'jong', 'kinderlijk'."},"my7_streng":{"lemma":"streng","displayNl":"streng","pos":"adjectief","meanings":[{"de":"streng, strikt (Regeln, Person)","ex":"De regels zijn heel streng.","exDe":"Die Regeln sind sehr streng."},{"de":"hart, rau (Winter, Kälte)","ex":"Het was een strenge winter.","exDe":"Es war ein strenger Winter."}],"usage":"Adjektiv; flektiert 'strenge' vor de-/het-Wort mit Artikel."},"my8_oud":{"lemma":"oud","displayNl":"oud","pos":"adjectief","meanings":[{"de":"alt (Alter, nicht jung)","ex":"Mijn opa is heel oud.","exDe":"Mein Opa ist sehr alt."},{"de":"alt, gereift, nicht frisch (z. B. Käse)","ex":"Oude kaas is sterk van smaak.","exDe":"Alter Käse ist kräftig im Geschmack."},{"de":"ehemalig, früher","ex":"Ik zag mijn oude school terug.","exDe":"Ich sah meine alte (ehemalige) Schule wieder."}],"usage":"Adjektiv; flektiert 'oude'. Gegenteil: nieuw/jong."},"my8_geel":{"lemma":"geel","displayNl":"geel","pos":"adjectief","meanings":[{"de":"gelb","ex":"De gele kaas ligt op tafel.","exDe":"Der gelbe Käse liegt auf dem Tisch."}],"usage":"Farbadjektiv; flektiert 'gele'. Als Substantiv 'het geel' = das Gelb."},"my8_stuk":{"lemma":"stuk","displayNl":"het stuk","pos":"substantief","meanings":[{"de":"das Stück (Teil, Portion)","ex":"Ik neem een stuk kaas.","exDe":"Ich nehme ein Stück Käse."},{"de":"das Stück, der Artikel, das Schriftstück","ex":"Er staat een interessant stuk in de krant.","exDe":"In der Zeitung steht ein interessanter Artikel."},{"de":"das Theaterstück","ex":"We gaan naar een stuk in het theater.","exDe":"Wir gehen zu einem Stück im Theater."},{"de":"kaputt, entzwei (umgangssprachlich, als Adjektiv)","ex":"De televisie is stuk.","exDe":"Der Fernseher ist kaputt."}],"usage":"het-Wort, Plural 'stukken'. Als Adjektiv 'stuk' = kaputt.","genus":"het","plural":"stukken","illustratable":true},"my9_weer":{"lemma":"weer","displayNl":"het weer","pos":"substantief","meanings":[{"de":"das Wetter","ex":"Het weer is vandaag slecht.","exDe":"Das Wetter ist heute schlecht."},{"de":"wieder, erneut (als Adverb 'weer')","ex":"Hij is weer te laat.","exDe":"Er ist wieder zu spät."}],"usage":"het-Wort ohne echten Plural (Wetter). Homonym: das Adverb 'weer' = wieder.","genus":"het","illustratable":true},"my9_regen":{"lemma":"regen","displayNl":"de regen","pos":"substantief","meanings":[{"de":"der Regen","ex":"Er komt veel regen.","exDe":"Es kommt viel Regen."}],"usage":"de-Wort. Verwandtes Verb: regenen (regnen).","genus":"de","plural":"regens","illustratable":true},"my9_wind":{"lemma":"wind","displayNl":"de wind","pos":"substantief","meanings":[{"de":"der Wind","ex":"De wind is hard vandaag.","exDe":"Der Wind ist heute stark."},{"de":"der Wind, die Blähung (Darmwind)","ex":"De baby heeft last van een windje.","exDe":"Das Baby hat mit einem Blähungswind zu kämpfen."}],"usage":"de-Wort, Plural 'winden'. 'een wind laten' = einen Wind fahren lassen.","genus":"de","plural":"winden","illustratable":true},"my9_uitwaaien":{"lemma":"uitwaaien","displayNl":"uitwaaien","pos":"werkwoord","meanings":[{"de":"frische Luft schnappen, sich den Wind um die Nase wehen lassen","ex":"Wij gaan aan zee uitwaaien.","exDe":"Wir gehen am Meer frische Luft schnappen."},{"de":"ausgehen, ausgeblasen werden (Flamme, Kerze)","ex":"De kaars waaide uit door de wind.","exDe":"Die Kerze ging durch den Wind aus."}],"usage":"Trennbares Verb (uit + waaien). Im Sinne 'frische Luft schnappen' typisch mit 'zijn'.","conjugation":{"presens":{"ik":"waai uit","jij":"waait uit","hij":"waait uit","wij":"waaien uit"},"imperfectum":{"ik":"waaide uit","wij":"waaiden uit"},"perfectum":{"aux":"zijn","participle":"uitgewaaid"}},"illustratable":true},"my9_paraplu":{"lemma":"paraplu","displayNl":"de paraplu","pos":"substantief","meanings":[{"de":"der Regenschirm","ex":"Neem je paraplu mee, het gaat regenen.","exDe":"Nimm deinen Regenschirm mit, es wird regnen."}],"usage":"Alltagswort; geöffneter Schutz gegen Regen. Plural mit Apostroph-s (paraplu's).","genus":"de","plural":"paraplu's","illustratable":true},"my9_koud":{"lemma":"koud","displayNl":"koud","pos":"adjectief","meanings":[{"de":"kalt","ex":"Het is koud en nat buiten.","exDe":"Es ist kalt und nass draußen."},{"de":"kühl, herzlos (übertragen)","ex":"Ze gaf hem een koude blik.","exDe":"Sie warf ihm einen kalten Blick zu."}],"usage":"Adjektiv der Temperatur; flektiert 'koude' vor de-Wort/attributiv (de koude wind). Übertragen für gefühllos."},"my9_strand":{"lemma":"strand","displayNl":"het strand","pos":"substantief","meanings":[{"de":"der Strand","ex":"Wij lopen op het strand langs de zee.","exDe":"Wir laufen am Strand entlang des Meeres."}],"usage":"het-Wort; sandiger Küstenstreifen. 'aan het strand' = am Strand, 'naar het strand' = zum Strand.","genus":"het","plural":"stranden","illustratable":true},"my10_vrijmarkt":{"lemma":"vrijmarkt","displayNl":"de vrijmarkt","pos":"substantief","meanings":[{"de":"der Flohmarkt (bes. am Königstag)","ex":"Op de vrijmarkt verkopen we onze oude spullen.","exDe":"Auf dem Flohmarkt verkaufen wir unsere alten Sachen."}],"usage":"de-Wort; typisch niederländischer Straßen-Flohmarkt, besonders am Koningsdag, wo jeder ohne Standgebühr verkaufen darf.","genus":"de","plural":"vrijmarkten","illustratable":true},"my10_verkopen":{"lemma":"verkopen","displayNl":"verkopen","pos":"werkwoord","meanings":[{"de":"verkaufen","ex":"Ik ga mijn oude spullen verkopen.","exDe":"Ich werde meine alten Sachen verkaufen."}],"usage":"Unregelmäßig; Partizip 'verkocht' ohne ge- (untrennbares Präfix ver-). Perfekt mit hebben. Imperfekt: verkocht / verkochten.","conjugation":{"presens":{"ik":"verkoop","jij":"verkoopt","hij":"verkoopt","wij":"verkopen"},"imperfectum":{"ik":"verkocht","wij":"verkochten"},"perfectum":{"aux":"hebben","participle":"verkocht"}},"illustratable":true},"my10_spullen":{"lemma":"spullen","displayNl":"de spullen","pos":"substantief","meanings":[{"de":"die Sachen, das Zeug","ex":"Wij leggen onze spullen op een kleed.","exDe":"Wir legen unsere Sachen auf eine Decke."}],"usage":"Umgangssprachlich als Plurale tantum verwendet: unbestimmte Gegenstände/Habseligkeiten. Singular 'spul' meint eher Stoff/Zeug als Masse.","genus":"de","plural":"spullen"},"my10_straat":{"lemma":"straat","displayNl":"de straat","pos":"substantief","meanings":[{"de":"die Straße (Gasse in einer Stadt)","ex":"De hele straat is oranje versierd.","exDe":"Die ganze Straße ist orange geschmückt."},{"de":"die Meerenge (geografisch)","ex":"De Straat van Gibraltar verbindt twee zeeën.","exDe":"Die Straße von Gibraltar verbindet zwei Meere."}],"usage":"de-Wort; städtische Straße mit Häusern. 'op straat' = auf der Straße/draußen. Geografisch auch Meerenge (Straat van Gibraltar).","genus":"de","plural":"straten","illustratable":true},"ad1_oktober":{"lemma":"oktober","displayNl":"oktober","pos":"substantief","meanings":[{"de":"Oktober (der zehnte Monat)","ex":"Het ADE is in oktober.","exDe":"Das ADE ist im Oktober."}],"usage":"Monatsname, kleingeschrieben, ohne Artikel. 'in oktober' = im Oktober."},"ad1_groot":{"lemma":"groot","displayNl":"groot","pos":"adjectief","meanings":[{"de":"groß (von Größe/Ausmaß)","ex":"Het festival is heel groot.","exDe":"Das Festival ist sehr groß."},{"de":"groß / erwachsen (Person)","ex":"Mijn zoon is al groot.","exDe":"Mein Sohn ist schon groß."},{"de":"bedeutend / bekannt","ex":"Hij is een grote artiest.","exDe":"Er ist ein bedeutender Künstler."}],"usage":"Attributiv meist mit -e: 'een grote zaal'; prädikativ ohne Endung: 'de zaal is groot'. Steigerung: groter, grootst."},"ad2_idee":{"lemma":"idee","displayNl":"het idee","pos":"substantief","meanings":[{"de":"die Idee / der Einfall","ex":"Dat is een goed idee.","exDe":"Das ist eine gute Idee."},{"de":"die Vorstellung / Ahnung","ex":"Ik heb geen idee waar het is.","exDe":"Ich habe keine Ahnung, wo es ist."}],"usage":"Neutrum: 'het idee'. Plural 'ideeën' mit Trema. Redewendung: 'geen idee' = keine Ahnung.","genus":"het","plural":"ideeën"},"ad2_beginnen":{"lemma":"beginnen","displayNl":"beginnen","pos":"werkwoord","meanings":[{"de":"beginnen / anfangen","ex":"Het ADE is klein begonnen.","exDe":"Das ADE hat klein angefangen."},{"de":"anfangen mit etw. / starten","ex":"Wij beginnen om acht uur.","exDe":"Wir fangen um acht Uhr an."}],"usage":"Unregelmäßig (stark). Perfekt mit 'zijn': 'is begonnen'. Anschluss oft mit 'met' ('beginnen met iets') oder 'te' + Infinitiv ('beginnen te zingen').","conjugation":{"presens":{"ik":"begin","jij":"begint","hij":"begint","wij":"beginnen"},"imperfectum":{"ik":"begon","wij":"begonnen"},"perfectum":{"aux":"zijn","participle":"begonnen"}}},"ad2_werk":{"lemma":"werk","displayNl":"het werk","pos":"substantief","meanings":[{"de":"die Arbeit / der Job","ex":"Muziek is zijn werk.","exDe":"Musik ist seine Arbeit."},{"de":"das Werk (Kunst-, Musikwerk)","ex":"De werken van Van Gogh zijn beroemd.","exDe":"Die Werke von Van Gogh sind berühmt."},{"de":"das Werk / die Fabrik","ex":"Hij werkt in het werk aan de haven.","exDe":"Er arbeitet im Werk am Hafen."}],"usage":"Neutrum: 'het werk'. Für 'zur Arbeit gehen': 'naar het werk gaan'. Plural 'werken' meist für Kunst-/Bauwerke.","genus":"het","plural":"werken"},"ad2_ontmoeten":{"lemma":"ontmoeten","displayNl":"ontmoeten","pos":"werkwoord","meanings":[{"de":"treffen / begegnen","ex":"Wij ontmoeten veel mensen.","exDe":"Wir treffen viele Menschen."},{"de":"kennenlernen / zusammentreffen","ex":"Ik heb haar op het ADE ontmoet.","exDe":"Ich habe sie beim ADE kennengelernt."}],"usage":"Schwaches Verb, untrennbar (Vorsilbe 'ont-', kein 'ge-' im Partizip). Perfekt mit 'hebben': 'heb ontmoet'. Nicht mit 'met' verbinden: 'iemand ontmoeten'.","conjugation":{"presens":{"ik":"ontmoet","jij":"ontmoet","hij":"ontmoet","wij":"ontmoeten"},"imperfectum":{"ik":"ontmoette","wij":"ontmoetten"},"perfectum":{"aux":"hebben","participle":"ontmoet"}},"illustratable":true},"ad2_jaar":{"lemma":"jaar","displayNl":"het jaar","pos":"substantief","meanings":[{"de":"das Jahr","ex":"Het ADE begon in het jaar 1996.","exDe":"Das ADE begann im Jahr 1996."},{"de":"das Lebensjahr / Alter","ex":"Zij is twintig jaar oud.","exDe":"Sie ist zwanzig Jahre alt."}],"usage":"Neutrum: 'het jaar'. Nach Zahl im Singular bei Alter/Dauer: 'tien jaar', sonst Plural 'jaren' ('de jaren negentig').","genus":"het","plural":"jaren"},"ad3_dag":{"lemma":"dag","displayNl":"de dag","pos":"substantief","meanings":[{"de":"der Tag","ex":"Overdag zijn er lezingen.","exDe":"Tagsüber gibt es Vorträge."},{"de":"Hallo! / Tschüss! (Gruß)","ex":"Dag! Tot morgen.","exDe":"Tschüss! Bis morgen."}],"usage":"Utrum: 'de dag'. Als Gruß 'dag' sowohl zur Begrüßung als auch zum Abschied. 'overdag' = tagsüber.","genus":"de","plural":"dagen"},"ad3_leren":{"lemma":"leren","displayNl":"leren","pos":"werkwoord","meanings":[{"de":"lernen","ex":"Overdag leer je veel.","exDe":"Tagsüber lernst du viel."},{"de":"lehren / beibringen","ex":"De leraar leert ons Nederlands.","exDe":"Der Lehrer bringt uns Niederländisch bei."}],"usage":"Schwaches Verb. Perfekt mit 'hebben': 'heb geleerd'. Bedeutet je nach Kontext 'lernen' oder 'lehren'. Nicht verwechseln mit dem Adjektiv 'leren' (aus Leder).","conjugation":{"presens":{"ik":"leer","jij":"leert","hij":"leert","wij":"leren"},"imperfectum":{"ik":"leerde","wij":"leerden"},"perfectum":{"aux":"hebben","participle":"geleerd"}},"illustratable":true},"ad3_praten":{"lemma":"praten","displayNl":"praten","pos":"werkwoord","meanings":[{"de":"reden, sprechen (sich unterhalten)","ex":"De dj's praten over muziek.","exDe":"Die DJs reden über Musik."},{"de":"plaudern, sich unterhalten","ex":"We praten graag met elkaar.","exDe":"Wir unterhalten uns gern miteinander."}],"usage":"Regelmäßiges Verb. 'praten over' = reden über; 'praten met' = sprechen mit. Umgangssprachlicher als 'spreken'.","conjugation":{"presens":{"ik":"praat","jij":"praat","hij":"praat","wij":"praten"},"imperfectum":{"ik":"praatte","wij":"praatten"},"perfectum":{"aux":"hebben","participle":"gepraat"}},"illustratable":true},"ad4_hoofdstad":{"lemma":"hoofdstad","displayNl":"de hoofdstad","pos":"substantief","meanings":[{"de":"die Hauptstadt","ex":"Amsterdam is de hoofdstad van Nederland.","exDe":"Amsterdam ist die Hauptstadt der Niederlande."}],"usage":"Zusammensetzung uit 'hoofd' (Haupt) + 'stad' (Stadt). Plural mit Vokalwechsel: hoofdsteden.","genus":"de","plural":"hoofdsteden","illustratable":true},"ad4_club":{"lemma":"club","displayNl":"de club","pos":"substantief","meanings":[{"de":"der Club, das Nachtlokal","ex":"De club is elke zaterdag open.","exDe":"Der Club ist jeden Samstag geöffnet."},{"de":"der Verein, die Vereinigung","ex":"Hij zit in een voetbalclub.","exDe":"Er ist in einem Fußballverein."}],"usage":"Aus dem Englischen entlehnt, Plural 'clubs'. Bedeutung 1: Musik-/Nachtclub; Bedeutung 2: organisierter Verein.","genus":"de","plural":"clubs","illustratable":true},"ad4_open":{"lemma":"open","displayNl":"open","pos":"adjectief","meanings":[{"de":"offen, geöffnet (nicht geschlossen)","ex":"De winkel is nog open.","exDe":"Der Laden ist noch geöffnet."},{"de":"offen, aufgeschlossen (Person/Haltung)","ex":"De stad is heel open en gastvrij.","exDe":"Die Stadt ist sehr offen und gastfreundlich."},{"de":"offen, frei zugänglich","ex":"Het gesprek was heel open.","exDe":"Das Gespräch war sehr offen."}],"usage":"Unveränderliches Adjektiv, meist prädikativ ('is open'). Gegenteil: dicht/gesloten."},"ad4_komen":{"lemma":"komen","displayNl":"komen","pos":"werkwoord","meanings":[{"de":"kommen, sich hinbewegen","ex":"Veel dj's komen naar Amsterdam.","exDe":"Viele DJs kommen nach Amsterdam."},{"de":"stammen, herkommen (uit)","ex":"Ik kom uit Duitsland.","exDe":"Ich komme aus Deutschland."},{"de":"ankommen, eintreffen","ex":"De trein komt om acht uur.","exDe":"Der Zug kommt um acht Uhr an."}],"usage":"Stark/unregelmäßig: Imperfekt 'kwam/kwamen', Perfekt mit 'zijn'. 'komen uit' = herkommen aus.","conjugation":{"presens":{"ik":"kom","jij":"komt","hij":"komt","wij":"komen"},"imperfectum":{"ik":"kwam","wij":"kwamen"},"perfectum":{"aux":"zijn","participle":"gekomen"}}},"ad5_beginnen":{"lemma":"starten","displayNl":"starten","pos":"werkwoord","meanings":[{"de":"starten, anfangen, beginnen","ex":"De show start om tien uur.","exDe":"Die Show startet um zehn Uhr."},{"de":"in Gang setzen, anlassen (Motor/Gerät)","ex":"Hij start de motor.","exDe":"Er startet den Motor."}],"usage":"Regelmäßig. Intransitiv (anfangen) mit 'zijn' ('de show is gestart'); transitiv (etwas in Gang setzen) mit 'hebben' ('hij heeft de motor gestart'). Synonym: beginnen.","conjugation":{"presens":{"ik":"start","jij":"start","hij":"start","wij":"starten"},"imperfectum":{"ik":"startte","wij":"startten"},"perfectum":{"aux":"zijn","participle":"gestart"}}},"ad6_radio":{"lemma":"radio","displayNl":"de radio","pos":"substantief","meanings":[{"de":"das Radio (Gerät)","ex":"De radio staat op de kast.","exDe":"Das Radio steht auf dem Schrank."},{"de":"der Rundfunk (Medium/Sender)","ex":"Ik hoor hem op de radio.","exDe":"Ich höre ihn im Radio."}],"usage":"Plural mit Apostroph: radio's. 'op de radio' = im Radio.","genus":"de","plural":"radio's","illustratable":true},"ad6_show":{"lemma":"show","displayNl":"de show","pos":"substantief","meanings":[{"de":"die Show, das Bühnenspektakel","ex":"De show begint over vijf minuten.","exDe":"Die Show beginnt in fünf Minuten."},{"de":"die Sendung (Radio/TV-Programm)","ex":"Zijn show op de radio is heel bekend.","exDe":"Seine Radiosendung ist sehr bekannt."}],"usage":"Aus dem Englischen, Plural 'shows'. Bedeutung 1: Live-Auftritt/Spektakel; Bedeutung 2: Radio-/TV-Programm.","genus":"de","plural":"shows","illustratable":true},"ad6_uur":{"lemma":"uur","displayNl":"het uur","pos":"substantief","meanings":[{"de":"die Stunde (Zeiteinheit von 60 Minuten)","ex":"De show duurt een uur.","exDe":"Die Sendung dauert eine Stunde."},{"de":"die Uhrzeit / der Zeitpunkt","ex":"Op welk uur begint het concert?","exDe":"Zu welcher Uhrzeit beginnt das Konzert?"}],"usage":"Substantiv (het-Wort). Plural na telwoord vaak ongewijzigd: 'twee uur' (klok) vs. 'twee uren' (duur).","genus":"het","plural":"uren"},"ad6_favoriet":{"lemma":"favoriet","displayNl":"favoriet","pos":"adjectief","meanings":[{"de":"Lieblings- / bevorzugt","ex":"Armin is mijn favoriete dj.","exDe":"Armin ist mein Lieblings-DJ."},{"de":"der Favorit / die Favoritin (Person mit besten Aussichten)","ex":"Zij is de favoriet voor de eerste plaats.","exDe":"Sie ist die Favoritin für den ersten Platz."}],"usage":"Als Adjektiv verbogen: 'mijn favoriete band'. Kann auch Substantief (de favoriet, plural favorieten) sein."},"ad6_nummer":{"lemma":"nummer","displayNl":"het nummer","pos":"substantief","meanings":[{"de":"der Song / das Musikstück / die Nummer","ex":"Dit nummer is nieuw.","exDe":"Dieser Song ist neu."},{"de":"die Nummer / Zahl (z. B. Haus-, Telefonnummer)","ex":"Wat is je nummer?","exDe":"Was ist deine Nummer?"},{"de":"die Ausgabe (einer Zeitschrift)","ex":"Het nieuwe nummer van het tijdschrift ligt er.","exDe":"Die neue Ausgabe der Zeitschrift liegt da."}],"usage":"Substantiv (het-Wort), Plural op -s.","genus":"het","plural":"nummers"},"ad6_horen":{"lemma":"horen","displayNl":"horen","pos":"werkwoord","meanings":[{"de":"hören (akustisch wahrnehmen)","ex":"Ik hoor zijn show elke week.","exDe":"Ich höre seine Sendung jede Woche."},{"de":"erfahren / hören (Neuigkeiten)","ex":"Ik hoor net dat het feest niet doorgaat.","exDe":"Ich höre gerade, dass die Party ausfällt."},{"de":"gehören / dazugehören (bij horen)","ex":"Deze sok hoort bij die andere.","exDe":"Diese Socke gehört zu der anderen."}],"usage":"Regelmäßiges Verb. 't kofschip: Partizip op -d (gehoord).","conjugation":{"presens":{"ik":"hoor","jij":"hoort","hij":"hoort","wij":"horen"},"imperfectum":{"ik":"hoorde","wij":"hoorden"},"perfectum":{"aux":"hebben","participle":"gehoord"}}},"ad7_geluid":{"lemma":"geluid","displayNl":"het geluid","pos":"substantief","meanings":[{"de":"der Klang / Ton / Sound","ex":"Het geluid is heel hard.","exDe":"Der Sound ist sehr laut."},{"de":"das Geräusch","ex":"Ik hoor een vreemd geluid.","exDe":"Ich höre ein seltsames Geräusch."},{"de":"die Lautstärke (das Audio, z. B. am Gerät)","ex":"Zet het geluid zachter.","exDe":"Stell den Ton leiser."}],"usage":"Substantiv (het-Wort), Plural geluiden.","genus":"het","plural":"geluiden"},"ad7_dj":{"lemma":"dj","displayNl":"de dj","pos":"substantief","meanings":[{"de":"der DJ / die DJane (Discjockey, der/die Musik auflegt)","ex":"Er zijn veel Nederlandse dj's.","exDe":"Es gibt viele niederländische DJs."}],"usage":"Substantiv (de-Wort), Abkürzung von 'discjockey'. Plural mit Apostroph: dj's. Der Roheintrag stand im Plural; Grundform ist der Singular 'dj'.","genus":"de","plural":"dj's","illustratable":true},"ad7_hard":{"lemma":"hard","displayNl":"hard","pos":"adjectief","meanings":[{"de":"laut (Klang, Musik)","ex":"De muziek is heel hard.","exDe":"Die Musik ist sehr laut."},{"de":"hart / fest (nicht weich)","ex":"Het brood is hard geworden.","exDe":"Das Brot ist hart geworden."},{"de":"schnell (als Bijwoord)","ex":"Hij fietst heel hard.","exDe":"Er fährt sehr schnell (mit dem Rad)."}],"usage":"Adjektiv und Adverb. Im Niederländischen bedeutet 'hard' bei Geräuschen 'laut', nicht 'hart'."},"ad7_maken":{"lemma":"maken","displayNl":"maken","pos":"werkwoord","meanings":[{"de":"machen / herstellen / anfertigen","ex":"Zij maken nieuwe muziek.","exDe":"Sie machen neue Musik."},{"de":"reparieren / in Ordnung bringen","ex":"Kun je mijn fiets maken?","exDe":"Kannst du mein Fahrrad reparieren?"},{"de":"erledigen / lösen (z. B. Aufgaben)","ex":"Ik maak mijn huiswerk.","exDe":"Ich mache meine Hausaufgaben."}],"usage":"Regelmäßiges Verb. 't kofschip: Partizip op -t (gemaakt).","conjugation":{"presens":{"ik":"maak","jij":"maakt","hij":"maakt","wij":"maken"},"imperfectum":{"ik":"maakte","wij":"maakten"},"perfectum":{"aux":"hebben","participle":"gemaakt"}}},"ad7_liedjes":{"lemma":"liedje","displayNl":"het liedje","pos":"substantief","meanings":[{"de":"das Lied, das Liedchen","ex":"Ik ken zijn liedjes uit mijn hoofd.","exDe":"Ich kenne seine Lieder auswendig."},{"de":"das Ständchen, kurzes Lied","ex":"Ze zong een vrolijk liedje.","exDe":"Sie sang ein fröhliches Liedchen."}],"usage":"Verkleinerungsform von 'lied'; sehr gebräuchlich für Songs/Popsongs. Roheintrag stand im Plural 'liedjes' -> Grundform Singular 'liedje'.","genus":"het","plural":"liedjes"},"ad7_nieuw":{"lemma":"nieuw","displayNl":"nieuw","pos":"adjectief","meanings":[{"de":"neu (frisch, noch nicht gebraucht)","ex":"Dit is een nieuwe stijl.","exDe":"Das ist ein neuer Stil."},{"de":"neu (erst kürzlich da/hinzugekommen)","ex":"Er is een nieuwe collega begonnen.","exDe":"Eine neue Kollegin hat angefangen."},{"de":"aktuell, neuartig, modern","ex":"Heb je het nieuwe nummer al gehoord?","exDe":"Hast du den neuen Song schon gehört?"}],"usage":"Attributiv flektiert 'nieuwe' (de nieuwe stijl, het nieuwe huis, een nieuw huis)."},"ad7_stijl":{"lemma":"stijl","displayNl":"de stijl","pos":"substantief","meanings":[{"de":"der Stil (Art und Weise, Ausdrucksform)","ex":"Dutch House is een aparte stijl.","exDe":"Dutch House ist ein eigener Stil."},{"de":"die Stilrichtung (Kunst, Musik, Mode)","ex":"Deze kunstenaar heeft een herkenbare stijl.","exDe":"Dieser Künstler hat einen wiedererkennbaren Stil."},{"de":"der Pfosten, Ständer, senkrechter Balken","ex":"De deur hangt tussen twee houten stijlen.","exDe":"Die Tür hängt zwischen zwei hölzernen Pfosten."}],"usage":"Homonymie: abstrakt 'Stil' vs. bautechnisch 'Pfosten/Ständer'. Nicht mit 'steil' (adj.) verwechseln.","genus":"de","plural":"stijlen"},"ad8_kerk":{"lemma":"kerk","displayNl":"de kerk","pos":"substantief","meanings":[{"de":"die Kirche (Gebäude)","ex":"Paradiso is een oude kerk.","exDe":"Paradiso ist eine alte Kirche."},{"de":"die Kirche (Institution, Gemeinschaft)","ex":"Zij is actief in de kerk.","exDe":"Sie ist in der Kirche aktiv."},{"de":"der Gottesdienst (naar de kerk gaan)","ex":"Op zondag gaan ze naar de kerk.","exDe":"Sonntags gehen sie in die Kirche."}],"usage":"Sowohl Bauwerk als auch Institution/Gottesdienst; 'naar de kerk gaan' = zum Gottesdienst gehen.","genus":"de","plural":"kerken","illustratable":true},"ad8_zaal":{"lemma":"zaal","displayNl":"de zaal","pos":"substantief","meanings":[{"de":"der Saal, die Halle","ex":"De zaal is groot en mooi.","exDe":"Der Saal ist groß und schön."},{"de":"der Zuschauerraum, der Konzertsaal","ex":"De hele zaal klapte mee.","exDe":"Der ganze Saal klatschte mit."},{"de":"der Krankensaal, die Station (Krankenhaus)","ex":"De patiënt ligt op zaal drie.","exDe":"Der Patient liegt auf Saal drei."}],"usage":"Großer Raum für Publikum/Veranstaltungen; im Krankenhaus auch Mehrbettzimmer/Station.","genus":"de","plural":"zalen","illustratable":true},"ad8_plek":{"lemma":"plek","displayNl":"de plek","pos":"substantief","meanings":[{"de":"der Ort, die Stelle, der Platz","ex":"Dit is een bekende plek.","exDe":"Das ist ein bekannter Ort."},{"de":"der Sitzplatz, freier Platz","ex":"Is deze plek nog vrij?","exDe":"Ist dieser Platz noch frei?"},{"de":"der Fleck (auf Haut/Stoff)","ex":"Er zit een rode plek op zijn arm.","exDe":"Er hat einen roten Fleck am Arm."}],"usage":"Umgangssprachlicher für 'plaats'; auch 'Fleck' (Verfärbung). Kein eindeutiges Bildmotiv.","genus":"de","plural":"plekken"},"ad8_gebouw":{"lemma":"gebouw","displayNl":"het gebouw","pos":"substantief","meanings":[{"de":"das Gebäude, das Bauwerk","ex":"Het gebouw is hoog en modern.","exDe":"Das Gebäude ist hoch und modern."},{"de":"das Haus, die Räumlichkeit (Zweckbau)","ex":"De club zit in een oud gebouw.","exDe":"Der Club ist in einem alten Gebäude."}],"usage":"Allgemein für jedes errichtete Bauwerk; Plural 'gebouwen'.","genus":"het","plural":"gebouwen","illustratable":true},"ad8_bekend":{"lemma":"bekend","displayNl":"bekend","pos":"adjectief","meanings":[{"de":"bekannt, berühmt","ex":"Melkweg is een bekende club.","exDe":"Melkweg ist ein bekannter Club."},{"de":"bekannt, vertraut (jdm. geläufig)","ex":"Die naam komt me bekend voor.","exDe":"Der Name kommt mir bekannt vor."},{"de":"bekannt (informiert über etw.), 'bekend zijn met'","ex":"Ben je bekend met de regels?","exDe":"Bist du mit den Regeln vertraut?"}],"usage":"Adjektiv/Partizip; Wendungen: 'bekend voorkomen' (bekannt vorkommen), 'bekend zijn met' (vertraut sein mit), 'bekendmaken' (bekannt geben)."},"ad9_lijst":{"lemma":"lijst","displayNl":"de lijst","pos":"substantief","meanings":[{"de":"Liste, Verzeichnis","ex":"Hij staat boven aan de lijst.","exDe":"Er steht ganz oben auf der Liste."},{"de":"Rahmen (Bilder-, Tür-, Fensterrahmen)","ex":"De foto zit in een houten lijst.","exDe":"Das Foto steckt in einem Holzrahmen."}],"usage":"Alltagswort; zweite Bedeutung 'Rahmen' im Deutschen leicht zu übersehen.","genus":"de","plural":"lijsten","illustratable":true},"ad9_beste":{"lemma":"best","displayNl":"best","pos":"adjectief","meanings":[{"de":"beste(r/s) (Superlativ von 'goed', gut)","ex":"Zij is de beste dj van het festival.","exDe":"Sie ist die beste DJane des Festivals."},{"de":"lieb / geehrt (Briefanrede)","ex":"Beste Anna, hoe gaat het?","exDe":"Liebe Anna, wie geht es dir?"}],"usage":"Superlativ von 'goed'; 'de beste' = 'der/die/das Beste'. Als Anrede 'Beste ...' wie dt. 'Liebe(r) ...'."},"ad9_honderd":{"lemma":"honderd","displayNl":"honderd","pos":"telwoord","meanings":[{"de":"hundert (100)","ex":"Er zijn honderd dj's op het podium.","exDe":"Es gibt hundert DJs auf der Bühne."},{"de":"hunderte, sehr viele (umgangssprachlich übertrieben)","ex":"Ik heb honderd dingen te doen.","exDe":"Ich habe hundert Dinge zu tun."}],"usage":"Grundzahl; unveränderlich. 'honderden' = Hunderte."},"ad9_stemmen":{"lemma":"stemmen","displayNl":"stemmen","pos":"werkwoord","meanings":[{"de":"abstimmen, wählen (Wahl)","ex":"Mensen stemmen op hun favoriete dj.","exDe":"Menschen stimmen für ihren Lieblings-DJ."},{"de":"(ein Instrument) stimmen","ex":"De gitarist moet zijn gitaar stemmen.","exDe":"Der Gitarrist muss seine Gitarre stimmen."}],"usage":"Regelmäßiges Verb. 'stemmen op' = für jdn./etw. stimmen; auch Musikinstrumente stimmen.","conjugation":{"presens":{"ik":"stem","jij":"stemt","hij":"stemt","wij":"stemmen"},"imperfectum":{"ik":"stemde","wij":"stemden"},"perfectum":{"aux":"hebben","participle":"gestemd"}},"illustratable":true},"ad9_eerste":{"lemma":"eerste","displayNl":"eerste","pos":"telwoord","meanings":[{"de":"erster, erste, erstes (Ordnungszahl)","ex":"Hij is de eerste op de lijst.","exDe":"Er ist der Erste auf der Liste."},{"de":"erstklassig, prima (z. B. eerste klas)","ex":"We reizen in de eerste klas.","exDe":"Wir reisen in der ersten Klasse."}],"usage":"Ordnungszahl zu 'één'; unregelmäßig (nicht 'eenste')."},"ad10_bezoeker":{"lemma":"bezoeker","displayNl":"de bezoeker","pos":"substantief","meanings":[{"de":"Besucher, Gast","ex":"Er zijn veel bezoekers op het festival.","exDe":"Es gibt viele Besucher auf dem Festival."},{"de":"Besucher (einer Website)","ex":"De site heeft duizend bezoekers per dag.","exDe":"Die Seite hat tausend Besucher pro Tag."}],"usage":"Weibliche Form: 'bezoekster'. Auch für Website-Besucher gebräuchlich.","genus":"de","plural":"bezoekers","illustratable":true},"ad10_vinden":{"lemma":"vinden","displayNl":"vinden","pos":"werkwoord","meanings":[{"de":"finden, meinen (eine Meinung haben)","ex":"Wij vinden de muziek mooi.","exDe":"Wir finden die Musik schön."},{"de":"finden, entdecken (etw. Verlorenes wiederfinden)","ex":"Ik kan mijn sleutels niet vinden.","exDe":"Ich kann meine Schlüssel nicht finden."}],"usage":"Starkes, unregelmäßiges Verb. 'iets mooi vinden' = etw. schön finden (Meinung).","conjugation":{"presens":{"ik":"vind","jij":"vindt","hij":"vindt","wij":"vinden"},"imperfectum":{"ik":"vond","wij":"vonden"},"perfectum":{"aux":"hebben","participle":"gevonden"}}},"ad10_geweldig":{"lemma":"geweldig","displayNl":"geweldig","pos":"adjectief","meanings":[{"de":"großartig, toll, fantastisch","ex":"Het ADE is geweldig.","exDe":"Das ADE ist großartig."},{"de":"gewaltig, enorm (Grad/Ausmaß)","ex":"Er was een geweldige belangstelling.","exDe":"Es gab ein gewaltiges Interesse."}],"usage":"Häufiges Lob-/Steigerungswort; auch adverbial ('geweldig leuk' = ganz toll)."},"ad10_veel":{"lemma":"veel","displayNl":"veel","pos":"telwoord","meanings":[{"de":"viel, viele (große Menge/Anzahl)","ex":"Er komen veel mensen.","exDe":"Es kommen viele Menschen."},{"de":"viel, oft, sehr (als Adverb, mit Verb)","ex":"Hij werkt veel.","exDe":"Er arbeitet viel."}],"usage":"Onbepaald telwoord/Mengenwort. Steigerung unregelmäßig: veel – meer – meest. Vor Mengenangaben unveränderlich (veel water, veel mensen)."},"fe1_gabber":{"lemma":"gabber","displayNl":"de gabber","pos":"substantief","meanings":[{"de":"Gabber (Anhänger der niederländischen Hardcore-/Gabber-Szene)","ex":"Hij is een echte gabber.","exDe":"Er ist ein echter Gabber."},{"de":"Kumpel, Freund (Umgangssprache, bes. Amsterdamer Slang, aus dem Bargoens/Jiddisch)","ex":"Hé gabber, alles goed?","exDe":"Hey Kumpel, alles gut?"}],"usage":"Ursprünglich Amsterdamer Slang für „Kumpel“; ab den 1990ern Name der Hardcore-Techno-Subkultur und ihrer Anhänger.","genus":"de","plural":"gabbers","illustratable":true},"fe1_hardcore":{"lemma":"hardcore","displayNl":"de hardcore","pos":"substantief","meanings":[{"de":"Hardcore (harter, sehr schneller Elektro-/Techno-Musikstil, Gabber-Szene)","ex":"Ik luister naar hardcore.","exDe":"Ich höre Hardcore."},{"de":"hart, extrem, kompromisslos (umgangssprachlich, auch als Adjektiv)","ex":"Dat feest was echt hardcore.","exDe":"Die Party war echt hardcore."}],"usage":"Englisches Lehnwort. Als Substantiv der Musikstil, umgangssprachlich auch adjektivisch für „extrem/heftig“.","genus":"de"},"fe1_kaal":{"lemma":"kaal","displayNl":"kaal","pos":"adjectief","meanings":[{"de":"kahl, glatzköpfig, ohne Haare","ex":"Veel gabbers zijn kaal.","exDe":"Viele Gabber haben eine Glatze."},{"de":"kahl, ohne Bewuchs/Laub (Bäume, Landschaft)","ex":"De bomen zijn kaal in de winter.","exDe":"Die Bäume sind im Winter kahl."},{"de":"kahl, karg, leer/schmucklos (Raum, Wand)","ex":"De nieuwe kamer is nog kaal.","exDe":"Das neue Zimmer ist noch kahl."}],"usage":"Attributiv gebeugt: een kale kop, een kaal hoofd. Steigerung: kaal – kaler – kaalst."},"fe2_schedel":{"lemma":"schedel","displayNl":"de schedel","pos":"substantief","meanings":[{"de":"Schädel (Knochen des Kopfes, Anatomie)","ex":"De dokter onderzoekt de schedel.","exDe":"Der Arzt untersucht den Schädel."},{"de":"Totenkopf (als Symbol/Logo)","ex":"De schedel is het logo.","exDe":"Der Totenkopf ist das Logo."}],"usage":"Anatomisch der Kopfknochen; im übertragenen Sinn auch der Totenkopf als Zeichen.","genus":"de","plural":"schedels","illustratable":true},"fe2_logo":{"lemma":"logo","displayNl":"het logo","pos":"substantief","meanings":[{"de":"Logo, Markenzeichen, Bildzeichen","ex":"Iedereen kent dit logo.","exDe":"Jeder kennt dieses Logo."}],"usage":"Plural mit Apostroph: logo's. Verkleinerung: logootje.","genus":"het","plural":"logo's"},"fe2_geweest":{"lemma":"zijn","displayNl":"zijn","pos":"werkwoord","meanings":[{"de":"sein (Zustand/Eigenschaft)","ex":"Ik ben moe.","exDe":"Ich bin müde."},{"de":"(irgendwo) gewesen sein, sich befunden haben","ex":"Ik ben op het feest geweest.","exDe":"Ich bin auf der Party gewesen."},{"de":"es gibt / es ist da (er is, er zijn)","ex":"Er is een probleem.","exDe":"Es gibt ein Problem."}],"usage":"„geweest“ ist das Partizip Perfekt von „zijn“. Stark und unregelmäßig; wichtigstes Hilfsverb.","conjugation":{"presens":{"ik":"ben","jij":"bent","hij":"is","wij":"zijn"},"imperfectum":{"ik":"was","wij":"waren"},"perfectum":{"aux":"zijn","participle":"geweest"}}},"fe2_herinnering":{"lemma":"herinnering","displayNl":"de herinnering","pos":"substantief","meanings":[{"de":"Erinnerung (Gedächtnisinhalt)","ex":"Dat is een mooie herinnering.","exDe":"Das ist eine schöne Erinnerung."},{"de":"Andenken, Souvenir (Erinnerungsstück)","ex":"Ik kocht een herinnering aan de reis.","exDe":"Ich kaufte ein Andenken an die Reise."}],"usage":"Verwandt mit „zich herinneren“ (sich erinnern). Vaak: een herinnering aan iets.","genus":"de","plural":"herinneringen"},"fe3_house":{"lemma":"house","displayNl":"de house","pos":"substantief","meanings":[{"de":"House-Musik (elektronischer Musikstil)","ex":"House komt uit Amerika.","exDe":"House kommt aus Amerika."},{"de":"House-Party, House-Szene","ex":"Hij houdt van house en techno.","exDe":"Er mag House und Techno."}],"usage":"Engl. Lehnwort für den Musikstil; als Genrebezeichnung meist ohne Artikel gebraucht (\"house draaien\", \"naar house luisteren\"). Nicht zu verwechseln mit \"huis\" (Haus).","genus":"de"},"fe3_dj":{"lemma":"dj","displayNl":"de dj","pos":"substantief","meanings":[{"de":"der DJ, Discjockey (Person, die Musik auflegt)","ex":"De dj draait de hele nacht platen.","exDe":"Der DJ legt die ganze Nacht Platten auf."}],"usage":"Abkürzung von \"discjockey\"; kleingeschrieben, Plural mit Apostroph \"dj's\", Genitiv/Verkleinerung \"dj'tje\". De-Wort.","genus":"de","plural":"dj's","illustratable":true},"fe3_populair":{"lemma":"populair","displayNl":"populair","pos":"adjectief","meanings":[{"de":"beliebt, populär","ex":"House wordt heel populair.","exDe":"House wird sehr beliebt."},{"de":"volkstümlich, allgemein verständlich","ex":"Hij schrijft populaire boeken over wetenschap.","exDe":"Er schreibt populäre Bücher über Wissenschaft."}],"usage":"Attributiv gebeugt \"populaire\"; Steigerung \"populairder\", \"populairst\". Franz. Herkunft."},"fe4_duizend":{"lemma":"duizend","displayNl":"duizend","pos":"telwoord","meanings":[{"de":"tausend (1000)","ex":"Er komen duizend mensen.","exDe":"Es kommen tausend Menschen."},{"de":"tausende, unzählige (unbestimmt große Menge)","ex":"Ik heb je al duizend keer gebeld.","exDe":"Ich habe dich schon tausendmal angerufen."}],"usage":"Grundzahl; bleibt nach Zahlwort unverändert (\"twee duizend\"), Pluralform \"duizenden\" nur substantivisch für \"Tausende\"."},"fe4_terrein":{"lemma":"terrein","displayNl":"het terrein","pos":"substantief","meanings":[{"de":"das Gelände, Areal, Grundstück","ex":"Het terrein is heel groot.","exDe":"Das Gelände ist sehr groß."},{"de":"das Terrain, Fach-/Sachgebiet (übertragen)","ex":"Dat is niet mijn terrein.","exDe":"Das ist nicht mein Fachgebiet."}],"usage":"Het-Wort, Plural \"terreinen\". Häufig in Zusammensetzungen: \"festivalterrein\", \"bouwterrein\", \"sportterrein\".","genus":"het","plural":"terreinen","illustratable":true},"fe4_kaartjes":{"lemma":"kaartje","displayNl":"het kaartje","pos":"substantief","meanings":[{"de":"die (Eintritts-/Fahr-)Karte, das Ticket","ex":"De kaartjes zijn snel weg.","exDe":"Die Karten sind schnell weg."},{"de":"das Kärtchen, kleine Karte (Verkleinerung von \"kaart\")","ex":"Ik heb een kaartje bij het cadeau gedaan.","exDe":"Ich habe ein Kärtchen an das Geschenk gehängt."},{"de":"die Visitenkarte","ex":"Hier is mijn kaartje, bel me gerust.","exDe":"Hier ist meine Visitenkarte, ruf mich ruhig an."}],"usage":"Verkleinerungsform von \"kaart\", daher het-Wort; Roh-Eintrag stand im Plural \"kaartjes\", Grundform ist der Singular \"kaartje\". Im Verkehrs-/Veranstaltungskontext = Ticket.","genus":"het","plural":"kaartjes","illustratable":true},"fe5_wit":{"lemma":"wit","displayNl":"wit","pos":"adjectief","meanings":[{"de":"weiß","ex":"Iedereen draagt witte kleding.","exDe":"Alle tragen weiße Kleidung."},{"de":"das Weiß (Farbe, substantiviert)","ex":"Het wit van de sneeuw is verblindend.","exDe":"Das Weiß des Schnees ist blendend."},{"de":"bleich, blass (vom Gesicht)","ex":"Ze werd wit van schrik.","exDe":"Sie wurde bleich vor Schreck."}],"usage":"Attributiv gebeugt \"witte\"; substantiviert \"het wit\". Steigerung \"witter\", \"witst\"."},"fe5_kleding":{"lemma":"kleding","displayNl":"de kleding","pos":"substantief","meanings":[{"de":"die Kleidung, die Klamotten","ex":"De kleding moet wit zijn.","exDe":"Die Kleidung muss weiß sein."}],"usage":"De-Wort, überwiegend unzählbar (kein gebräuchlicher Plural). Häufig in Zusammensetzungen: \"zomerkleding\", \"werkkleding\", \"kledingstuk\" (Kleidungsstück).","genus":"de","illustratable":true},"fe6_hardstyle":{"lemma":"hardstyle","displayNl":"de hardstyle","pos":"substantief","meanings":[{"de":"der Hardstyle (harte elektronische Tanzmusikrichtung)","ex":"Ik wil naar hardstyle luisteren.","exDe":"Ich will Hardstyle hören."},{"de":"der Hardstyle-Stil (Musikgenre auf Festivals wie Defqon)","ex":"Hardstyle heeft een keihard ritme.","exDe":"Hardstyle hat einen knallharten Rhythmus."}],"usage":"Muziekgenre, meestal zonder lidwoord gebruikt: 'naar hardstyle luisteren'. Als de-woord telbaar zeldzaam.","genus":"de"},"fe6_willen":{"lemma":"willen","displayNl":"willen","pos":"werkwoord","meanings":[{"de":"wollen (den Wunsch/die Absicht haben)","ex":"Wij willen naar Defqon.","exDe":"Wir wollen zu Defqon."},{"de":"möchten / mögen (höflicher Wunsch)","ex":"Wil je iets drinken?","exDe":"Möchtest du etwas trinken?"}],"usage":"Modaal hulpwerkwoord; volgend werkwoord in de infinitief zonder 'te'. Onvoltooid verleden 'wilde' of spreektalig 'wou'.","conjugation":{"presens":{"ik":"wil","jij":"wilt","hij":"wil","wij":"willen"},"imperfectum":{"ik":"wilde","wij":"wilden"},"perfectum":{"aux":"hebben","participle":"gewild"}}},"fe6_moeten":{"lemma":"moeten","displayNl":"moeten","pos":"werkwoord","meanings":[{"de":"müssen (verpflichtet sein)","ex":"Je moet een kaartje kopen.","exDe":"Du musst eine Karte kaufen."},{"de":"sollen (nach Meinung/Rat)","ex":"Je moet die film echt zien.","exDe":"Du solltest diesen Film wirklich sehen."}],"usage":"Modaal hulpwerkwoord; volgend werkwoord in de infinitief zonder 'te'.","conjugation":{"presens":{"ik":"moet","jij":"moet","hij":"moet","wij":"moeten"},"imperfectum":{"ik":"moest","wij":"moesten"},"perfectum":{"aux":"hebben","participle":"gemoeten"}}},"fe6_springen":{"lemma":"springen","displayNl":"springen","pos":"werkwoord","meanings":[{"de":"springen (sich vom Boden abstoßen, hüpfen)","ex":"Iedereen wil springen.","exDe":"Jeder will springen."},{"de":"springen / hüpfen zu einem Ziel (mit Richtung)","ex":"Hij is over de sloot gesprongen.","exDe":"Er ist über den Graben gesprungen."}],"usage":"Hulpwerkwoord 'hebben' bij de activiteit, 'zijn' bij verplaatsing/richting ('over ... gesprongen').","conjugation":{"presens":{"ik":"spring","jij":"springt","hij":"springt","wij":"springen"},"imperfectum":{"ik":"sprong","wij":"sprongen"},"perfectum":{"aux":"hebben","participle":"gesprongen"}},"illustratable":true},"fe6_vuurwerk":{"lemma":"vuurwerk","displayNl":"het vuurwerk","pos":"substantief","meanings":[{"de":"das Feuerwerk (pyrotechnisches Schauspiel am Himmel)","ex":"Het vuurwerk is spectaculair.","exDe":"Das Feuerwerk ist spektakulär."},{"de":"das Feuerwerk / die Böller (das Material zum Abbrennen)","ex":"We kopen vuurwerk voor oud en nieuw.","exDe":"Wir kaufen Feuerwerk für Silvester."}],"usage":"Meestal ontelbaar (het vuurwerk). Meervoud 'vuurwerken' zeldzaam, voor afzonderlijke shows.","genus":"het","plural":"vuurwerken","illustratable":true},"fe7_techno":{"lemma":"techno","displayNl":"de techno","pos":"substantief","meanings":[{"de":"der Techno (elektronische Tanzmusikrichtung mit repetitivem Beat)","ex":"Vanavond luister ik naar techno.","exDe":"Heute Abend höre ich Techno."}],"usage":"Muziekgenre, meestal zonder lidwoord: 'naar techno luisteren', 'techno draaien'. Onttelbaar.","genus":"de"},"fe7_beat":{"lemma":"beat","displayNl":"de beat","pos":"substantief","meanings":[{"de":"der Beat (Grundrhythmus, Takt in der Musik)","ex":"De beat is heel strak.","exDe":"Der Beat ist sehr straff."},{"de":"der Beat / das Instrumental (produzierte Rhythmusspur)","ex":"De dj maakte een nieuwe beat.","exDe":"Der DJ machte einen neuen Beat."}],"usage":"Leenwoord uit het Engels; de-woord, meervoud 'beats'.","genus":"de","plural":"beats"},"fe7_donker":{"lemma":"donker","displayNl":"donker","pos":"adjectief","meanings":[{"de":"dunkel (wenig Licht)","ex":"In de hal is het donker.","exDe":"In der Halle ist es dunkel."},{"de":"dunkel (Farbe: tief, kräftig)","ex":"Ze draagt een donkere jas.","exDe":"Sie trägt eine dunkle Jacke."},{"de":"das Dunkel / die Dunkelheit (als het donker)","ex":"Ik ben bang in het donker.","exDe":"Ich habe Angst im Dunkeln."}],"usage":"Vooral bijvoeglijk naamwoord ('een donkere kamer'); zelfstandig gebruikt als 'het donker' = de duisternis."},"fe7_hal":{"lemma":"hal","displayNl":"de hal","pos":"substantief","meanings":[{"de":"die Halle (großer Innenraum, Veranstaltungshalle)","ex":"De hal zit helemaal vol met dansende mensen.","exDe":"Die Halle ist ganz voll mit tanzenden Menschen."},{"de":"der Flur, die Diele, der Eingangsbereich","ex":"Zet je schönen maar in de hal.","exDe":"Stell deine Schuhe ruhig in den Flur."}],"usage":"Grundform Singular; NL-Plural 'hallen'. Bedeutet je nach Kontext große (Veranstaltungs-)Halle oder den Eingangsflur/die Diele eines Hauses.","genus":"de","plural":"hallen","illustratable":true},"fe7_ritme":{"lemma":"ritme","displayNl":"het ritme","pos":"substantief","meanings":[{"de":"der Rhythmus (Takt, Schlagfolge in der Musik)","ex":"Ik voel het ritme van de muziek goed.","exDe":"Ich spüre den Rhythmus der Musik gut."},{"de":"der Rhythmus (regelmäßiger Ablauf, Tempo des Lebens)","ex":"Ik heb een vast ritme in mijn dag.","exDe":"Ich habe einen festen Rhythmus in meinem Tag."}],"usage":"Sächlich ('het ritme'); NL-Plural 'ritmes' (auch 'ritmen'). Abstrakt, sowohl musikalisch als auch für regelmäßige Abläufe.","genus":"het","plural":"ritmes"},"fe7_ondergronds":{"lemma":"ondergronds","displayNl":"ondergronds","pos":"adjectief","meanings":[{"de":"unterirdisch (unter der Erde befindlich)","ex":"De metro rijdt ondergronds door de stad.","exDe":"Die U-Bahn fährt unterirdisch durch die Stadt."},{"de":"im Untergrund, verborgen, alternativ (nicht öffentlich, Szene)","ex":"Techno is soms ondergronds en niet commercieel.","exDe":"Techno ist manchmal Underground und nicht kommerziell."}],"usage":"Adjektiv/Adverb; wörtlich 'unterirdisch', übertragen 'im Untergrund/underground' für nicht-kommerzielle, verborgene Szenen."},"fe8_illegaal":{"lemma":"illegaal","displayNl":"illegaal","pos":"adjectief","meanings":[{"de":"illegal, gesetzeswidrig, verboten","ex":"Het feest in de leegstaande fabriek is illegaal.","exDe":"Die Party in der leerstehenden Fabrik ist illegal."}],"usage":"Adjektiv/Adverb; Gegenteil 'legaal'. Beschreibt Verbotenes/Gesetzeswidriges."},"fe8_politie":{"lemma":"politie","displayNl":"de politie","pos":"substantief","meanings":[{"de":"die Polizei (Behörde, Einsatzkräfte)","ex":"De politie komt niet meteen naar het feest.","exDe":"Die Polizei kommt nicht sofort zur Party."}],"usage":"Sammelbegriff, meist ohne Plural gebraucht ('de politie'). Bezeichnet die Behörde wie auch die Beamten.","genus":"de","illustratable":true},"fe8_geheim":{"lemma":"geheim","displayNl":"geheim","pos":"adjectief","meanings":[{"de":"geheim, verborgen, vertraulich","ex":"De plek van het feest is geheim.","exDe":"Der Ort der Party ist geheim."},{"de":"das Geheimnis (als Substantiv 'het geheim')","ex":"Hij vertelt mij een groot geheim.","exDe":"Er erzählt mir ein großes Geheimnis."}],"usage":"Primär Adjektiv 'geheim' (verborgen/vertraulich); als Substantiv 'het geheim' = das Geheimnis (Plural 'geheimen')."},"fe9_boot":{"lemma":"boot","displayNl":"de boot","pos":"substantief","meanings":[{"de":"das Boot (kleineres Wasserfahrzeug)","ex":"Er varen veel boten in de gracht.","exDe":"Es fahren viele Boote in der Gracht."}],"usage":"Grundform Singular; NL-Plural 'boten' (Vokalverlängerung o→oo). Kleineres Wasserfahrzeug.","genus":"de","plural":"boten","illustratable":true},"fe9_kroon":{"lemma":"kroon","displayNl":"de kroon","pos":"substantief","meanings":[{"de":"die Krone (Kopfschmuck von König oder Königin)","ex":"Kinderen dragen papieren kronen op het feest.","exDe":"Kinder tragen Kronen aus Papier auf dem Fest."},{"de":"die Baumkrone (oberer Blätterteil eines Baumes)","ex":"De vogels zitten hoog in de kroon van de boom.","exDe":"Die Vögel sitzen hoch in der Krone des Baumes."},{"de":"die Krone (Zahnersatz, Zahnkrone)","ex":"De tandarts plaatst een kroon op mijn kies.","exDe":"Der Zahnarzt setzt eine Krone auf meinen Backenzahn."}],"usage":"Grundform Singular; NL-Plural 'kronen'. Königlicher Kopfschmuck, übertragen auch Baumkrone und Zahnkrone.","genus":"de","plural":"kronen","illustratable":true},"fe9_straten":{"lemma":"straat","displayNl":"de straat","pos":"substantief","meanings":[{"de":"die Straße","ex":"De straten zijn vol met mensen.","exDe":"Die Straßen sind voller Menschen."},{"de":"der Weg / die Gasse (Verkehrsraum)","ex":"Kijk goed uit als je de straat oversteekt.","exDe":"Pass gut auf, wenn du die Straße überquerst."}],"usage":"Plural-Eintrag 'de straten' auf Singular 'de straat' reduziert. de-Wort, Plural: straten.","genus":"de","plural":"straten","illustratable":true},"fe10_borrel":{"lemma":"borrel","displayNl":"de borrel","pos":"substantief","meanings":[{"de":"der Umtrunk / das gesellige Beisammensein bei Getränken","ex":"Na het werk gaan we samen naar de borrel.","exDe":"Nach der Arbeit gehen wir zusammen zum Umtrunk."},{"de":"der Schnaps / das Gläschen Spirituose (bes. Genever)","ex":"Opa neemt elke avond een borrel.","exDe":"Opa nimmt jeden Abend einen Schnaps."}],"usage":"de-Wort, Plural: borrels. Meint sowohl das gesellige Trinken als auch das einzelne Glas Spirituose.","genus":"de","plural":"borrels","illustratable":true},"fe10_kroeg":{"lemma":"kroeg","displayNl":"de kroeg","pos":"substantief","meanings":[{"de":"die Kneipe / der Pub","ex":"Ik ga graag naar de kroeg.","exDe":"Ich gehe gern in die Kneipe."}],"usage":"de-Wort, Plural: kroegen. Umgangssprachlich für ein einfaches, gemütliches Wirtshaus.","genus":"de","plural":"kroegen","illustratable":true},"fe10_biertje":{"lemma":"biertje","displayNl":"het biertje","pos":"substantief","meanings":[{"de":"das Bierchen / ein Glas Bier","ex":"Neem jij ook een biertje?","exDe":"Nimmst du auch ein Bierchen?"}],"usage":"Verkleinerungsform (Diminutiv) von 'bier', het-Wort, Plural: biertjes. Sehr gebräuchlich fürs entspannte Feierabendbier.","genus":"het","plural":"biertjes","illustratable":true},"fe10_proost":{"lemma":"proost","displayNl":"proost","pos":"tussenwerpsel","meanings":[{"de":"prost! / zum Wohl!","ex":"Proost, op onze vriendschap!","exDe":"Prost, auf unsere Freundschaft!"}],"usage":"Trinkspruch beim Anstoßen. Interjektion, wird nicht flektiert."},"fe10_cafe":{"lemma":"café","displayNl":"het café","pos":"substantief","meanings":[{"de":"das Café / die Kneipe (bes. 'bruin café')","ex":"Dat bruine café is heel oud.","exDe":"Diese braune Kneipe ist sehr alt."},{"de":"das Kaffeehaus / Lokal für Kaffee und Getränke","ex":"We spraken af in een gezellig café aan de gracht.","exDe":"Wir verabredeten uns in einem gemütlichen Café an der Gracht."}],"usage":"het-Wort, Plural: cafés. In den Niederlanden oft eine schankwirtschaftsähnliche Kneipe ('bruin café'), nicht nur Kaffeehaus.","genus":"het","plural":"cafés","illustratable":true},"hu1_diplomaat":{"lemma":"diplomaat","displayNl":"de diplomaat","pos":"substantief","meanings":[{"de":"der Diplomat (Vertreter im Staatsdienst)","ex":"Zijn vader was een invloedrijke diplomaat in dienst van de Oranjes.","exDe":"Sein Vater war ein einflussreicher Diplomat im Dienst der Oranier."},{"de":"der taktvolle, geschickte Mensch (übertragen)","ex":"Wat een diplomaat, hij stelt iedereen tevreden.","exDe":"Was für ein Diplomat, er stellt jeden zufrieden."}],"usage":"de-Wort, Plural: diplomaten. Auch übertragen für eine besonders taktvolle Person.","genus":"de","plural":"diplomaten","illustratable":true},"hu1_wiskunde":{"lemma":"wiskunde","displayNl":"de wiskunde","pos":"substantief","meanings":[{"de":"die Mathematik","ex":"Al vroeg toonde hij een opmerkelijke aanleg voor de wiskunde.","exDe":"Schon früh zeigte er eine bemerkenswerte Anlage für die Mathematik."},{"de":"das Schulfach Mathematik","ex":"Wiskunde is mijn lievelingsvak op school.","exDe":"Mathematik ist mein Lieblingsfach in der Schule."}],"usage":"de-Wort, Stoffname/abstrakt, in der Regel kein Plural. Bezeichnet die Wissenschaft und das Schulfach.","genus":"de"},"hu1_republiek":{"lemma":"republiek","displayNl":"de republiek","pos":"substantief","meanings":[{"de":"die Republik (Staatsform ohne Monarch)","ex":"De republiek werd bestuurd door regenten en stadhouders.","exDe":"Die Republik wurde von Regenten und Statthaltern regiert."},{"de":"das Durcheinander, das Chaos (umgangssprachlich)","ex":"Het is hier een echte republiek, niemand luistert naar elkaar.","exDe":"Hier herrscht ein echtes Chaos, niemand hört einander zu."}],"usage":"Historisch die Bezeichnung für die Republiek der Zeven Verenigde Nederlanden (1588-1795). Umgangssprachlich auch für ein ungeordnetes Durcheinander.","genus":"de","plural":"republieken"},"hu1_welvaart":{"lemma":"welvaart","displayNl":"de welvaart","pos":"substantief","meanings":[{"de":"der Wohlstand, die Prosperität","ex":"De welvaart van het land berustte grotendeels op de zeehandel.","exDe":"Der Wohlstand des Landes beruhte größtenteils auf dem Seehandel."}],"usage":"Bezeichnet materiellen Wohlstand einer Gesellschaft. Meist ohne Plural (Stoffsubstantiv). Zu unterscheiden von 'welzijn' (Wohlergehen, Wohlbefinden).","genus":"de"},"hu1_opvoeding":{"lemma":"opvoeding","displayNl":"de opvoeding","pos":"substantief","meanings":[{"de":"die Erziehung (das Großziehen von Kindern)","ex":"Zijn opvoeding was gericht op talenkennis en natuurfilosofie.","exDe":"Seine Erziehung war auf Sprachkenntnis und Naturphilosophie ausgerichtet."},{"de":"die gute Kinderstube, das anerzogene Benehmen","ex":"Hij toonde een goede opvoeding door iedereen netjes te groeten.","exDe":"Er zeigte eine gute Kinderstube, indem er alle höflich grüßte."}],"usage":"'Opvoeding' meint das Erziehen im familiären/moralischen Sinn; die schulische Ausbildung ist eher 'onderwijs' oder 'opleiding'. Plural selten.","genus":"de","plural":"opvoedingen"},"hu1_begaafdheid":{"lemma":"begaafdheid","displayNl":"de begaafdheid","pos":"substantief","meanings":[{"de":"die Begabung, das Talent, die Veranlagung","ex":"De begaafdheid van de jongen werd door zijn leermeesters geroemd.","exDe":"Die Begabung des Jungen wurde von seinen Lehrmeistern gerühmt."},{"de":"die Hochbegabung (bei 'hoogbegaafdheid')","ex":"Zijn begaafdheid viel al op de basisschool op.","exDe":"Seine (Hoch-)Begabung fiel schon in der Grundschule auf."}],"usage":"Abgeleitet von 'begaafd' (begabt). 'Hoogbegaafdheid' bezeichnet speziell die Hochbegabung.","genus":"de","plural":"begaafdheden"},"hu2_universiteit":{"lemma":"universiteit","displayNl":"de universiteit","pos":"substantief","meanings":[{"de":"die Universität, die Hochschule (Institution)","ex":"De universiteit van Leiden werd in 1575 gesticht.","exDe":"Die Universität Leiden wurde 1575 gegründet."},{"de":"das Universitätsgebäude, der Campus","ex":"Ik fiets elke ochtend naar de universiteit.","exDe":"Ich fahre jeden Morgen mit dem Rad zur Universität."}],"usage":"Kurzform umgangssprachlich 'de uni'. Genus 'de'. Für das Studium selbst sagt man 'studeren aan de universiteit'.","genus":"de","plural":"universiteiten","illustratable":true},"hu2_natuurfilosofie":{"lemma":"natuurfilosofie","displayNl":"de natuurfilosofie","pos":"substantief","meanings":[{"de":"die Naturphilosophie","ex":"De natuurfilosofie werd door Descartes ingrijpend hervormd.","exDe":"Die Naturphilosophie wurde von Descartes tiefgreifend reformiert."}],"usage":"Historischer Vorläufer der modernen Naturwissenschaften. Fachbegriff, meist ohne Plural.","genus":"de"},"hu2_wetmatigheid":{"lemma":"wetmatigheid","displayNl":"de wetmatigheid","pos":"substantief","meanings":[{"de":"die Gesetzmäßigkeit, die Regelhaftigkeit","ex":"Elke beweging wordt door een wetmatigheid beheerst.","exDe":"Jede Bewegung wird von einer Gesetzmäßigkeit beherrscht."},{"de":"das (Natur-)Gesetz, die Regel","ex":"De onderzoekers ontdekten een verrassende wetmatigheid in de data.","exDe":"Die Forscher entdeckten eine überraschende Gesetzmäßigkeit in den Daten."}],"usage":"Abgeleitet von 'wetmatig' (gesetzmäßig). Bezeichnet eine regelhafte, vorhersagbare Beziehung, besonders in den Naturwissenschaften.","genus":"de","plural":"wetmatigheden"},"hu2_methode":{"lemma":"methode","displayNl":"de methode","pos":"substantief","meanings":[{"de":"die Methode, das Verfahren, die Vorgehensweise","ex":"Zijn methode werd gekenmerkt door strenge redenering.","exDe":"Seine Methode war durch strenge Schlussfolgerung gekennzeichnet."},{"de":"das Lehrwerk, das Lehrbuch (z. B. Sprachkurs)","ex":"We werken dit jaar met een nieuwe methode Nederlands.","exDe":"Wir arbeiten dieses Jahr mit einem neuen Lehrwerk für Niederländisch."}],"usage":"Plural 'methoden' (formell) oder 'methodes' (umgangssprachlich). In der Bildungssprache bezeichnet 'een methode' oft ein komplettes Lehrwerk.","genus":"de","plural":"methoden"},"hu2_wereldbeeld":{"lemma":"wereldbeeld","displayNl":"het wereldbeeld","pos":"substantief","meanings":[{"de":"das Weltbild","ex":"Het oude wereldbeeld werd door nieuwe waarnemingen ondermijnd.","exDe":"Das alte Weltbild wurde durch neue Beobachtungen untergraben."},{"de":"die Weltanschauung, die Sicht auf die Welt","ex":"Elke cultuur draagt een eigen wereldbeeld met zich mee.","exDe":"Jede Kultur trägt ein eigenes Weltbild mit sich."}],"usage":"Abstraktes Substantiv (het-Wort); Vorstellung von der Welt und ihrer Ordnung. Häufig in wissenschaftlichem/philosophischem Kontext.","genus":"het","plural":"wereldbeelden"},"hu2_bewijs":{"lemma":"bewijs","displayNl":"het bewijs","pos":"substantief","meanings":[{"de":"der Beweis (schlüssiger Nachweis)","ex":"Zonder sluitend bewijs werd geen stelling aanvaard.","exDe":"Ohne schlüssigen Beweis wurde kein Satz akzeptiert."},{"de":"der Beleg, der Nachweis (Dokument/Bescheinigung)","ex":"Bewaar het bewijs van betaling zorgvuldig.","exDe":"Bewahre den Zahlungsbeleg sorgfältig auf."},{"de":"das Beweismittel (vor Gericht)","ex":"De rechercheur verzamelde bewijs op de plaats delict.","exDe":"Der Ermittler sammelte Beweise am Tatort."}],"usage":"het-Wort; Plural bewijzen. Sowohl abstrakt (Beweis einer These) als auch konkret (Beleg, Beweißtück). Feste Wendung: het bewijs leveren.","genus":"het","plural":"bewijzen"},"hu2_redenering":{"lemma":"redenering","displayNl":"de redenering","pos":"substantief","meanings":[{"de":"die Argumentation, die Gedankenführung","ex":"Zijn redenering werd door tijdgenoten geprezen om haar helderheid.","exDe":"Seine Argumentation wurde von Zeitgenossen für ihre Klarheit gelobt."},{"de":"die Schlussfolgerung, die Beweisführung","ex":"De redenering klopt niet, want de aanname is fout.","exDe":"Die Schlussfolgerung stimmt nicht, denn die Annahme ist falsch."}],"usage":"de-Wort; Kette von Argumenten/Schlüssen. Abstrakt, kein Bildmotiv.","genus":"de","plural":"redeneringen"},"hu2_omwenteling":{"lemma":"omwenteling","displayNl":"de omwenteling","pos":"substantief","meanings":[{"de":"der Umbruch, die Umwälzung, die Revolution","ex":"De wetenschappelijke omwenteling werd door velen met argwaan bekeken.","exDe":"Der wissenschaftliche Umbruch wurde von vielen mit Argwohn betrachtet."},{"de":"die Umdrehung, die Rotation (eine volle Drehung)","ex":"De aarde maakt in een jaar één omwenteling om de zon.","exDe":"Die Erde macht in einem Jahr eine Umdrehung um die Sonne."}],"usage":"de-Wort; Homonymie: gesellschaftlicher Umbruch UND physikalische Umdrehung. Kontext entscheidet.","genus":"de","plural":"omwentelingen"},"hu3_slingeruurwerk":{"lemma":"slingeruurwerk","displayNl":"het slingeruurwerk","pos":"substantief","meanings":[{"de":"die Pendeluhr","ex":"Het slingeruurwerk dat hij bouwde, liep ongekend nauwkeurig.","exDe":"Die Pendeluhr, die er baute, ging ungeahnt genau."}],"usage":"het-Wort; Uhr mit Pendel als Zeitgeber (historisch, Huygens). Konkret darstellbar.","genus":"het","plural":"slingeruurwerken","illustratable":true},"hu3_slingerbeweging":{"lemma":"slingerbeweging","displayNl":"de slingerbeweging","pos":"substantief","meanings":[{"de":"die Pendelbewegung, die Schwingung","ex":"De slingerbeweging waarop het uurwerk berust, is opmerkelijk regelmatig.","exDe":"Die Pendelbewegung, auf der das Uhrwerk beruht, ist bemerkenswert regelmäßig."}],"usage":"de-Wort; hin- und herschwingende Bewegung eines Pendels. Konkret als bewegtes Motiv darstellbar.","genus":"de","plural":"slingerbewegingen","illustratable":true},"hu3_lengtegraad":{"lemma":"lengtegraad","displayNl":"de lengtegraad","pos":"substantief","meanings":[{"de":"der Längengrad","ex":"De lengtegraad, die op zee moeilijk te bepalen was, vroeg om een precieze klok.","exDe":"Der Längengrad, der auf See schwer zu bestimmen war, verlangte nach einer präzisen Uhr."},{"de":"die geographische Länge","ex":"Amsterdam ligt op ongeveer vijf graden oosterlengte.","exDe":"Amsterdam liegt auf etwa fünf Grad östlicher Länge."}],"usage":"de-Wort; geografische Koordinate. Abstraktes Konzept, kein eindeutiges Einzelmotiv.","genus":"de","plural":"lengtegraden"},"hu3_zeevaart":{"lemma":"zeevaart","displayNl":"de zeevaart","pos":"substantief","meanings":[{"de":"die Seefahrt, die Schifffahrt (zur See)","ex":"De zeevaart, waarvan de Republiek afhankelijk was, eiste betrouwbare instrumenten.","exDe":"Die Seefahrt, von der die Republik abhängig war, verlangte zuverlässige Instrumente."},{"de":"die Navigation/Fahrt auf dem Meer als Tätigkeit","ex":"Hij koos voor een loopbaan in de zeevaart.","exDe":"Er entschied sich für eine Laufbahn in der Seefahrt."}],"usage":"de-Wort; meist unzählbar (kein gebräuchlicher Plural). Bezeichnet die Schifffahrt auf dem Meer. Konkret als maritimes Motiv darstellbar.","genus":"de","illustratable":true},"hu3_nauwkeurigheid":{"lemma":"nauwkeurigheid","displayNl":"de nauwkeurigheid","pos":"substantief","meanings":[{"de":"die Genauigkeit","ex":"De nauwkeurigheid die hij bereikte, was voor die tijd ongehoord.","exDe":"Die Genauigkeit, die er erreichte, war für jene Zeit unerhört."},{"de":"die Präzision","ex":"De metingen moeten met grote nauwkeurigheid worden uitgevoerd.","exDe":"Die Messungen müssen mit großer Präzision durchgeführt werden."},{"de":"die Sorgfalt, die Akkuratesse","ex":"Zij werkte met een opvallende nauwkeurigheid aan elk detail.","exDe":"Sie arbeitete mit auffallender Sorgfalt an jedem Detail."}],"usage":"Abstraktes Substantiv (Eigenschaft); mit 'grote/hoge nauwkeurigheid'.","genus":"de","plural":"nauwkeurigheden"},"hu3_tijdmeting":{"lemma":"tijdmeting","displayNl":"de tijdmeting","pos":"substantief","meanings":[{"de":"die Zeitmessung","ex":"De tijdmeting waarop de navigatie steunde, moest constant zijn.","exDe":"Die Zeitmessung, auf die sich die Navigation stützte, musste konstant sein."},{"de":"die Zeitnahme (bei Wettkampf)","ex":"Bij de wedstrijd zorgde een elektronische tijdmeting voor eerlijke uitslagen.","exDe":"Beim Wettkampf sorgte eine elektronische Zeitnahme für faire Ergebnisse."}],"usage":"Abstraktes Substantiv; Kompositum tijd + meting.","genus":"de","plural":"tijdmetingen"},"hu3_uitvinding":{"lemma":"uitvinding","displayNl":"de uitvinding","pos":"substantief","meanings":[{"de":"die Erfindung (das Erfundene)","ex":"De uitvinding waarmee hij beroemd werd, veranderde de horlogemakerij.","exDe":"Die Erfindung, mit der er berühmt wurde, veränderte die Uhrmacherei."},{"de":"die Erfindung (das Erfinden, der Vorgang)","ex":"De uitvinding van de boekdrukkunst had enorme gevolgen.","exDe":"Die Erfindung des Buchdrucks hatte enorme Folgen."},{"de":"das Erdachte, die Erdichtung","ex":"Dat verhaal is pure uitvinding, er klopt niets van.","exDe":"Diese Geschichte ist reine Erfindung, daran stimmt nichts."}],"usage":"Abstraktes Substantiv; von 'uitvinden' abgeleitet.","genus":"de","plural":"uitvindingen"},"hu3_periode":{"lemma":"periode","displayNl":"de periode","pos":"substantief","meanings":[{"de":"der Zeitraum, die Periode","ex":"In die periode reisde hij veel door Europa.","exDe":"In diesem Zeitraum reiste er viel durch Europa."},{"de":"die Schwingungsdauer (Physik)","ex":"De periode van de slinger, die van de lengte afhangt, blijft nagenoeg gelijk.","exDe":"Die Schwingungsdauer des Pendels, die von der Länge abhängt, bleibt nahezu gleich."},{"de":"die Periode, die Menstruation","ex":"Ze heeft last van buikpijn tijdens haar periode.","exDe":"Sie hat Bauchschmerzen während ihrer Periode."}],"usage":"Abstraktes Substantiv; polysem (Zeit, Physik, Medizin).","genus":"de","plural":"periodes"},"hu4_middelpuntvliedend":{"lemma":"middelpuntvliedende kracht","displayNl":"de middelpuntvliedende kracht","pos":"substantief","meanings":[{"de":"die Zentrifugalkraft","ex":"Hij toonde aan dat de middelpuntvliedende kracht met de snelheid toeneemt.","exDe":"Er zeigte, dass die Zentrifugalkraft mit der Geschwindigkeit zunimmt."}],"usage":"Physikalischer Fachbegriff (Substantivphrase); Synonym 'centrifugale kracht'.","genus":"de","plural":"middelpuntvliedende krachten"},"hu4_middelpuntzoekend":{"lemma":"middelpuntzoekende kracht","displayNl":"de middelpuntzoekende kracht","pos":"substantief","meanings":[{"de":"die Zentripetalkraft","ex":"Omdat de middelpuntzoekende kracht ontbreekt, vliegt het voorwerp weg.","exDe":"Weil die Zentripetalkraft fehlt, fliegt der Gegenstand davon."}],"usage":"Physikalischer Fachbegriff (Substantivphrase); Synonym 'centripetale kracht'.","genus":"de","plural":"middelpuntzoekende krachten"},"hu4_cirkelbeweging":{"lemma":"cirkelbeweging","displayNl":"de cirkelbeweging","pos":"substantief","meanings":[{"de":"die Kreisbewegung","ex":"Hij beschreef hoe een cirkelbeweging voortdurend van richting verandert.","exDe":"Er beschrieb, wie eine Kreisbewegung ständig die Richtung ändert."}],"usage":"Fachsprachliches Substantiv; Kompositum cirkel + beweging.","genus":"de","plural":"cirkelbewegingen"},"hu4_snelheid":{"lemma":"snelheid","displayNl":"de snelheid","pos":"substantief","meanings":[{"de":"die Geschwindigkeit","ex":"Naarmate de snelheid stijgt, wordt de kracht groter.","exDe":"Je mehr die Geschwindigkeit steigt, desto größer wird die Kraft."},{"de":"das Tempo, die Schnelligkeit","ex":"Met hoge snelheid raasde de trein voorbij.","exDe":"Mit hohem Tempo raste der Zug vorbei."}],"usage":"Abstraktes Substantiv; auch physikalisch (Vektorgröße).","genus":"de","plural":"snelheden"},"hu4_versnelling":{"lemma":"versnelling","displayNl":"de versnelling","pos":"substantief","meanings":[{"de":"die Beschleunigung","ex":"Hij berekende dat er ook bij constante snelheid een versnelling optreedt.","exDe":"Er berechnete, dass auch bei konstanter Geschwindigkeit eine Beschleunigung auftritt."},{"de":"der Gang (im Fahrzeug/Getriebe)","ex":"Op de heuvel schakelde ze naar een lagere versnelling.","exDe":"Am Hügel schaltete sie in einen niedrigeren Gang."}],"usage":"Physikalisch die Beschleunigung; im Alltag auch der Gang eines Fahrrads oder Autos.","genus":"de","plural":"versnellingen"},"hu4_baan":{"lemma":"baan","displayNl":"de baan","pos":"substantief","meanings":[{"de":"die Bahn, die Umlaufbahn","ex":"Zolang de kracht werkt, blijft het lichaam in zijn baan.","exDe":"Solange die Kraft wirkt, bleibt der Körper in seiner Bahn."},{"de":"die Stelle, der Job, die Arbeit","ex":"Na haar studie vond ze meteen een goede baan.","exDe":"Nach ihrem Studium fand sie sofort eine gute Stelle."},{"de":"die Spur, die Bahn (Sport/Straße)","ex":"De hardloper bleef netjes in zijn eigen baan.","exDe":"Der Läufer blieb ordentlich in seiner eigenen Bahn."}],"usage":"Stark polysem: Umlaufbahn (Physik), Arbeitsstelle (Alltag, sehr häufig) und Bahn/Spur im Sport oder Verkehr.","genus":"de","plural":"banen"},"hu4_massa":{"lemma":"massa","displayNl":"de massa","pos":"substantief","meanings":[{"de":"die Masse (Physik)","ex":"Hij begreep dat de kracht van de massa van het voorwerp afhangt.","exDe":"Er verstand, dass die Kraft von der Masse des Gegenstands abhängt."},{"de":"die Masse, die Menschenmenge","ex":"Een grote massa mensen verzamelde zich op het plein.","exDe":"Eine große Masse von Menschen versammelte sich auf dem Platz."}],"usage":"Physikalische Größe; umgangssprachlich auch eine große Menschenmenge oder eine formlose Menge.","genus":"de","plural":"massa's"},"hu4_traagheid":{"lemma":"traagheid","displayNl":"de traagheid","pos":"substantief","meanings":[{"de":"die Trägheit (Physik)","ex":"Doordat de traagheid werkt, streeft het lichaam naar een rechte lijn.","exDe":"Weil die Trägheit wirkt, strebt der Körper nach einer geraden Linie."},{"de":"die Langsamkeit, die Schwerfälligkeit","ex":"De traagheid van het bestuur ergerde de inwoners.","exDe":"Die Schwerfälligkeit der Verwaltung ärgerte die Einwohner."}],"usage":"Physikalisches Prinzip der Trägheit; übertragen auch allgemeine Langsamkeit oder Schwerfälligkeit.","genus":"de","plural":"traagheden"},"hu5_telescoop":{"lemma":"telescoop","displayNl":"de telescoop","pos":"substantief","meanings":[{"de":"das Teleskop, das Fernrohr","ex":"Als de telescoop scherper zou zijn, konden wij nog meer manen zien.","exDe":"Wenn das Teleskop schärfer wäre, könnten wir noch mehr Monde sehen."}],"usage":"Optisches Instrument zum Beobachten entfernter Objekte, besonders am Nachthimmel.","genus":"de","plural":"telescopen","illustratable":true},"hu5_maan":{"lemma":"maan","displayNl":"de maan","pos":"substantief","meanings":[{"de":"der Mond","ex":"Hij ontdekte een maan die om Saturnus zou draaien.","exDe":"Er entdeckte einen Mond, der um Saturn kreisen sollte."}],"usage":"Der Erdmond oder allgemein ein natürlicher Trabant, der einen Planeten umkreist.","genus":"de","plural":"manen","illustratable":true},"hu5_ring":{"lemma":"ring","displayNl":"de ring","pos":"substantief","meanings":[{"de":"der Ring (eines Planeten)","ex":"Als je nauwkeurig kijkt, zou je de ring van Saturnus kunnen onderscheiden.","exDe":"Wenn du genau hinschaust, könntest du den Ring des Saturn erkennen."},{"de":"der Ring (Schmuck)","ex":"Zij droeg een gouden ring aan haar linkerhand.","exDe":"Sie trug einen goldenen Ring an ihrer linken Hand."},{"de":"der Kreis, der Reifen","ex":"De kinderen gingen in een ring om het vuur staan.","exDe":"Die Kinder stellten sich in einem Kreis um das Feuer."}],"usage":"Ursprünglich als Phrase \"de ring van Saturnus\" (Planetenring) geliefert; Grundlemma ist \"ring\" mit weiteren Bedeutungen Schmuckring und Kreis/Reifen.","genus":"de","plural":"ringen","notes":"Roheingabe war die Phrase \"de ring van Saturnus\"; auf das Kopf-Lemma \"ring\" reduziert.","illustratable":true},"hu5_waarneming":{"lemma":"waarneming","displayNl":"de waarneming","pos":"substantief","meanings":[{"de":"die Beobachtung","ex":"Zonder geduldige waarneming zou hij niets hebben ontdekt.","exDe":"Ohne geduldige Beobachtung hätte er nichts entdeckt."},{"de":"die Wahrnehmung (Sinneseindruck)","ex":"Onze waarneming van kleuren verschilt per persoon.","exDe":"Unsere Wahrnehmung von Farben unterscheidet sich von Person zu Person."}],"usage":"Wissenschaftliche Beobachtung sowie die sinnliche Wahrnehmung; abstrakter Begriff.","genus":"de","plural":"waarnemingen"},"hu5_planeet":{"lemma":"planeet","displayNl":"de planeet","pos":"substantief","meanings":[{"de":"der Planet","ex":"Indien de planeet dichterbij stond, zou hij helderder schijnen.","exDe":"Wenn der Planet näher stünde, würde er heller scheinen."},{"de":"Himmelskörper, der um einen Stern kreist","ex":"Onze planeet draait in ongeveer 365 dagen om de zon.","exDe":"Unser Planet dreht sich in etwa 365 Tagen um die Sonne."}],"usage":"Astronomischer Fachbegriff; auch bildlich für die Erde („onze planeet\").","genus":"de","plural":"planeten","illustratable":true},"hu5_sterrenkunde":{"lemma":"sterrenkunde","displayNl":"de sterrenkunde","pos":"substantief","meanings":[{"de":"die Astronomie, die Sternkunde","ex":"De sterrenkunde zou zonder betere lenzen zijn blijven stilstaan.","exDe":"Die Astronomie wäre ohne bessere Linsen stehen geblieben."}],"usage":"Abstrakter Wissenschaftsbegriff, meist unzählbar (kein Plural).","genus":"de"},"hu5_vergroting":{"lemma":"vergroting","displayNl":"de vergroting","pos":"substantief","meanings":[{"de":"die Vergrößerung (Maßstab, Optik)","ex":"Bij een grotere vergroting zou het beeld waziger worden.","exDe":"Bei einer größeren Vergrößerung würde das Bild unschärfer werden."},{"de":"die Vergrößerung, der Abzug (vergrößerter Foto-/Bildabzug)","ex":"Ze hing een grote vergroting van de foto boven de bank.","exDe":"Sie hängte eine große Vergrößerung des Fotos über das Sofa."}],"usage":"Sowohl der Vorgang/Faktor des Vergrößerns als auch das vergrößerte Ergebnis.","genus":"de","plural":"vergrotingen"},"hu6_golftheorie":{"lemma":"golftheorie","displayNl":"de golftheorie","pos":"substantief","meanings":[{"de":"die Wellentheorie (Physik)","ex":"De door hem ontwikkelde golftheorie verklaarde de breking van licht.","exDe":"Die von ihm entwickelte Wellentheorie erklärte die Brechung des Lichts."}],"usage":"Physikalischer Fachbegriff; abstrakte wissenschaftliche Theorie.","genus":"de","plural":"golftheorieën"},"hu6_voortplanting":{"lemma":"voortplanting","displayNl":"de voortplanting","pos":"substantief","meanings":[{"de":"die Ausbreitung, die Fortpflanzung (Physik: von Wellen/Licht/Schall)","ex":"De voortplanting van licht verloopt volgens vaste wetten.","exDe":"Die Ausbreitung des Lichts verläuft nach festen Gesetzen."},{"de":"die Fortpflanzung (Biologie: Vermehrung)","ex":"De voortplanting van deze planten gebeurt via zaden.","exDe":"Die Fortpflanzung dieser Pflanzen geschieht über Samen."}],"usage":"Ursprünglicher Eintrag „voortplanting van licht\" auf das Kopf-Lemma „voortplanting\" reduziert; meist unzählbar.","genus":"de"},"hu6_breking":{"lemma":"breking","displayNl":"de breking","pos":"substantief","meanings":[{"de":"die Brechung (Optik: Richtungsänderung von Licht)","ex":"De door water veroorzaakte breking buigt de lichtstraal af.","exDe":"Die durch Wasser verursachte Brechung lenkt den Lichtstrahl ab."}],"usage":"Physikalischer Fachbegriff aus der Optik.","genus":"de","plural":"brekingen"},"hu6_golf":{"lemma":"golf","displayNl":"de golf","pos":"substantief","meanings":[{"de":"die Welle (Wasser)","ex":"Een hoge golf sloeg over de dijk heen.","exDe":"Eine hohe Welle schlug über den Deich."},{"de":"die Welle (Physik: Licht, Schall, Schwingung)","ex":"Elke uitgezonden golf plant zich in alle richtingen voort.","exDe":"Jede ausgesandte Welle pflanzt sich in alle Richtungen fort."},{"de":"die Welle (übertragen: plötzlicher Andrang, z. B. eine Hitzewelle)","ex":"Een golf van enthousiasme ging door de zaal.","exDe":"Eine Welle der Begeisterung ging durch den Saal."}],"usage":"„de golf\" = Welle (Plural golven). Nicht verwechseln mit „het golf\" = der Golfsport (golfen).","genus":"de","plural":"golven","illustratable":true},"hu6_golffront":{"lemma":"golffront","displayNl":"het golffront","pos":"substantief","meanings":[{"de":"die Wellenfront (Physik: Fläche gleicher Phase)","ex":"Het voortschrijdende golffront bestaat uit talloze elementaire golfjes.","exDe":"Die fortschreitende Wellenfront besteht aus zahllosen Elementarwellen."}],"usage":"Physikalischer Fachbegriff (Wellenoptik); Neutrum (het).","genus":"het","plural":"golffronten"},"hu6_ether":{"lemma":"ether","displayNl":"de ether","pos":"substantief","meanings":[{"de":"der Äther (hypothetisches Medium der Lichtausbreitung)","ex":"Het licht zou zich door de alles vullende ether bewegen.","exDe":"Das Licht sollte sich durch den alles füllenden Äther bewegen."},{"de":"der Äther, die Luft (dichterisch für den Himmelsraum)","ex":"De klanken verdwenen in de ether.","exDe":"Die Klänge verschwanden im Äther."},{"de":"das Äther, der Ether (chemischer Stoff)","ex":"De patiënt werd met ether verdoofd.","exDe":"Der Patient wurde mit Ether betäubt."}],"usage":"Abstrakter physikalischer bzw. chemischer Begriff; kein klares Bildmotiv.","genus":"de","plural":"ethers"},"hu6_terugkaatsing":{"lemma":"terugkaatsing","displayNl":"de terugkaatsing","pos":"substantief","meanings":[{"de":"die Reflexion, die Zurückwerfung (von Licht, Schall)","ex":"De terugkaatsing op de spiegel gehoorzaamt aan eenvoudige regels.","exDe":"Die Reflexion am Spiegel gehorcht einfachen Regeln."},{"de":"das Echo, das Zurückprallen","ex":"De terugkaatsing van de golven tegen de kade was hoorbaar.","exDe":"Das Zurückwerfen der Wellen gegen den Kai war hörbar."}],"usage":"Abstrakter physikalischer Vorgang; Funktionswort-nah, kein eindeutiges Einzelmotiv.","genus":"de","plural":"terugkaatsingen"},"hu6_lichtstraal":{"lemma":"lichtstraal","displayNl":"de lichtstraal","pos":"substantief","meanings":[{"de":"der Lichtstrahl","ex":"De gebroken lichtstraal verandert bij de overgang van richting.","exDe":"Der gebrochene Lichtstrahl ändert beim Übergang die Richtung."},{"de":"der Sonnenstrahl (durchbrechendes Licht)","ex":"Een lichtstraal viel door het raam op de tafel.","exDe":"Ein Lichtstrahl fiel durch das Fenster auf den Tisch."}],"usage":"Konkret bildlich darstellbar: ein sichtbarer Lichtstrahl.","genus":"de","plural":"lichtstralen","illustratable":true},"hu7_deeltje":{"lemma":"deeltje","displayNl":"het deeltje","pos":"substantief","meanings":[{"de":"das Teilchen (Physik)","ex":"De aanname van lichtdeeltjes verklaarde de scherpe schaduwen.","exDe":"Die Annahme von Lichtteilchen erklärte die scharfen Schatten."},{"de":"das Teilchen, das winzige Stückchen (allgemein)","ex":"Er zweefden kleine deeltjes stof in de lucht.","exDe":"Es schwebten kleine Staubteilchen in der Luft."}],"usage":"Abstrakter naturwissenschaftlicher Begriff; nicht eindeutig bildlich darstellbar.","genus":"het","plural":"deeltjes"},"hu7_tegenstelling":{"lemma":"tegenstelling","displayNl":"de tegenstelling","pos":"substantief","meanings":[{"de":"der Gegensatz, der Kontrast","ex":"De tegenstelling tussen golf en deeltje beheerste het debat.","exDe":"Der Gegensatz zwischen Welle und Teilchen beherrschte die Debatte."},{"de":"der Widerspruch, die Antithese","ex":"In tegenstelling tot zijn broer werkt hij hard.","exDe":"Im Gegensatz zu seinem Bruder arbeitet er hart."}],"usage":"Abstrakter Begriff; kein klares Bildmotiv. Häufig in der festen Wendung 'in tegenstelling tot'.","genus":"de","plural":"tegenstellingen"},"hu7_geschil":{"lemma":"geschil","displayNl":"het geschil","pos":"substantief","meanings":[{"de":"der Streit, die Streitigkeit, die Meinungsverschiedenheit","ex":"Het geschil over de aard van het licht bleef lange tijd onbeslist.","exDe":"Der Streit über die Natur des Lichts blieb lange unentschieden."},{"de":"die Auseinandersetzung, der Konflikt (auch juristisch)","ex":"De twee bedrijven legden hun geschil voor aan de rechter.","exDe":"Die beiden Firmen legten ihren Streit dem Richter vor."}],"usage":"Abstrakter Begriff (Meinungs-/Rechtsstreit); kein eindeutiges Einzelmotiv.","genus":"het","plural":"geschillen"},"hu7_verklaring":{"lemma":"verklaring","displayNl":"de verklaring","pos":"substantief","meanings":[{"de":"die Erklärung, die Erläuterung (eines Phänomens)","ex":"Beide verklaringen berustten op verschillende veronderstellingen.","exDe":"Beide Erklärungen beruhten auf verschiedenen Annahmen."},{"de":"die Aussage, die Erklärung (offizielle Äußerung, Deklaration)","ex":"De getuige legde een verklaring af bij de politie.","exDe":"Der Zeuge gab eine Aussage bei der Polizei ab."}],"usage":"Abstrakter Begriff; kein klares Bildmotiv. Feste Wendung: 'een verklaring afleggen'.","genus":"de","plural":"verklaringen"},"hu7_aanname":{"lemma":"aanname","displayNl":"de aanname","pos":"substantief","meanings":[{"de":"die Annahme, die Voraussetzung (Hypothese)","ex":"De aanname van een ether was voor de tegenstander onaanvaardbaar.","exDe":"Die Annahme eines Äthers war für den Gegner inakzeptabel."},{"de":"die Annahme, die Einstellung (von Personal); die Annahme, das Entgegennehmen","ex":"De aanname van nieuw personeel werd uitgesteld.","exDe":"Die Einstellung neuen Personals wurde verschoben."}],"usage":"Abstrakter Begriff; kein klares Bildmotiv. Plural auch 'aannamen'.","genus":"de","plural":"aannames"},"hu7_verschijnsel":{"lemma":"verschijnsel","displayNl":"het verschijnsel","pos":"substantief","meanings":[{"de":"die Erscheinung, das Phänomen","ex":"De verklaring van het verschijnsel vroeg om nauwkeurige metingen.","exDe":"Die Erklärung des Phänomens verlangte nach genauen Messungen."},{"de":"das Anzeichen, die Begleiterscheinung","ex":"Koorts is een veelvoorkomend verschijnsel bij griep.","exDe":"Fieber ist eine häufige Begleiterscheinung bei Grippe."}],"usage":"Neutrales Substantiv für ein beobachtbares Phänomen; oft wissenschaftlich.","genus":"het","plural":"verschijnselen"},"hu7_meningsverschil":{"lemma":"meningsverschil","displayNl":"het meningsverschil","pos":"substantief","meanings":[{"de":"die Meinungsverschiedenheit, der Meinungsunterschied","ex":"Het meningsverschil tussen de geleerden bleef eeuwenlang voortbestaan.","exDe":"Die Meinungsverschiedenheit zwischen den Gelehrten bestand jahrhundertelang fort."},{"de":"die Auseinandersetzung, der (milde) Streit","ex":"Na een klein meningsverschil waren ze snel weer verzoend.","exDe":"Nach einer kleinen Auseinandersetzung waren sie schnell wieder versöhnt."}],"usage":"Abstraktes Substantiv, zusammengesetzt aus mening + verschil.","genus":"het","plural":"meningsverschillen"},"hu8_academie":{"lemma":"academie","displayNl":"de academie","pos":"substantief","meanings":[{"de":"die Akademie (Gelehrtengesellschaft)","ex":"De academie subsidieerde het onderzoek naar de zwaartekracht.","exDe":"Die Akademie förderte die Forschung zur Schwerkraft."},{"de":"die Akademie, die Hochschule (Ausbildungsstätte)","ex":"Ze studeerde schilderkunst aan de academie in Den Haag.","exDe":"Sie studierte Malerei an der Akademie in Den Haag."}],"usage":"Bezeichnet sowohl die Gelehrtengesellschaft als auch die Ausbildungsstätte.","genus":"de","plural":"academies","illustratable":true},"hu8_onderzoek":{"lemma":"onderzoek","displayNl":"het onderzoek","pos":"substantief","meanings":[{"de":"die Forschung","ex":"Zijn onderzoek naar de slingerbeweging vond in Parijs veel weerklank.","exDe":"Seine Forschung zur Pendelbewegung fand in Paris großen Widerhall."},{"de":"die Untersuchung","ex":"De politie startte een onderzoek naar de diefstal.","exDe":"Die Polizei leitete eine Untersuchung des Diebstahls ein."},{"de":"die Prüfung, die (ärztliche) Untersuchung","ex":"De dokter deed een grondig onderzoek van zijn hart.","exDe":"Der Arzt machte eine gründliche Untersuchung seines Herzens."}],"usage":"Vielseitig: wissenschaftliche Forschung, polizeiliche oder ärztliche Untersuchung.","genus":"het","plural":"onderzoeken"},"hu8_zwaartekracht":{"lemma":"zwaartekracht","displayNl":"de zwaartekracht","pos":"substantief","meanings":[{"de":"die Schwerkraft, die Gravitation","ex":"Hij bestudeerde de invloed van de zwaartekracht op de slinger.","exDe":"Er studierte den Einfluss der Schwerkraft auf das Pendel."}],"usage":"Physikalischer Begriff; meist nur im Singular gebräuchlich.","genus":"de"},"hu8_experiment":{"lemma":"experiment","displayNl":"het experiment","pos":"substantief","meanings":[{"de":"das Experiment, der Versuch","ex":"Elk experiment werd zorgvuldig gedocumenteerd en herhaald.","exDe":"Jedes Experiment wurde sorgfältig dokumentiert und wiederholt."},{"de":"das Experiment (gewagter Versuch, Wagnis)","ex":"Samenwonen was voor hen een spannend experiment.","exDe":"Zusammenwohnen war für sie ein aufregendes Experiment."}],"usage":"Sowohl wissenschaftlicher Versuch als auch übertragen ein gewagtes Ausprobieren.","genus":"het","plural":"experimenten","illustratable":true},"hu8_beschermheer":{"lemma":"beschermheer","displayNl":"de beschermheer","pos":"substantief","meanings":[{"de":"der Schirmherr, der Schutzherr","ex":"De koning trad op als beschermheer van de wetenschappen.","exDe":"Der König trat als Schirmherr der Wissenschaften auf."},{"de":"der Gönner, der Förderer, der Mäzen","ex":"Een rijke beschermheer betaalde al zijn onderzoek.","exDe":"Ein reicher Gönner bezahlte seine gesamte Forschung."}],"usage":"Person, die etwas schützt oder finanziell fördert; weibliche Form: beschermvrouwe.","genus":"de","plural":"beschermheren"},"hu8_hypothese":{"lemma":"hypothese","displayNl":"de hypothese","pos":"substantief","meanings":[{"de":"die Hypothese, die Annahme","ex":"Zijn hypothese werd door herhaalde metingen bevestigd.","exDe":"Seine Hypothese wurde durch wiederholte Messungen bestätigt."},{"de":"die Vermutung, die vorläufige Erklärung","ex":"Als hypothese nam ze aan dat het water sneller zou afkoelen.","exDe":"Als Vermutung nahm sie an, dass das Wasser schneller abkühlen würde."}],"usage":"Wissenschaftliche, noch zu prüfende Annahme; Plural auch 'hypotheses'.","genus":"de","plural":"hypothesen"},"hu8_verhandeling":{"lemma":"verhandeling","displayNl":"de verhandeling","pos":"substantief","meanings":[{"de":"Abhandlung, Traktat, wissenschaftliche Arbeit","ex":"Zijn verhandeling over de slinger verscheen in het Latijn.","exDe":"Seine Abhandlung über das Pendel erschien auf Latein."},{"de":"Ausführung, Erörterung (mündlich oder schriftlich)","ex":"De hoogleraar hield een lange verhandeling over de zwaartekracht.","exDe":"Der Professor hielt eine lange Ausführung über die Schwerkraft."}],"usage":"Formeller, geschriebener wetenschappelijker Text; nicht zu verwechseln mit 'onderhandeling' (Verhandlung).","genus":"de","plural":"verhandelingen"},"hu9_heelal":{"lemma":"heelal","displayNl":"het heelal","pos":"substantief","meanings":[{"de":"das Universum, das Weltall, das All","ex":"Hij heeft betoogd dat het heelal ontelbare werelden bevat.","exDe":"Er hat argumentiert, dass das Universum unzählige Welten enthält."}],"usage":"Meist im Singular mit Artikel 'het heelal'; steht für das Weltall als Ganzes.","genus":"het","plural":"heelallen","illustratable":true},"hu9_buitenaards":{"lemma":"buitenaards","displayNl":"buitenaards","pos":"adjectief","meanings":[{"de":"außerirdisch, extraterrestrisch","ex":"Hij heeft over buitenaards leven op andere planeten geschreven.","exDe":"Er hat über außerirdisches Leben auf anderen Planeten geschrieben."}],"usage":"Adjektiv; häufig in 'buitenaards leven' (außerirdisches Leben). Roheingabe 'het buitenaardse leven' auf das Adjektiv-Lemma reduziert."},"hu9_ziekte":{"lemma":"ziekte","displayNl":"de ziekte","pos":"substantief","meanings":[{"de":"die Krankheit, das Leiden","ex":"Zijn ziekte heeft hem jarenlang aan zijn werk gehinderd.","exDe":"Seine Krankheit hat ihn jahrelang an seiner Arbeit gehindert."}],"usage":"Plural 'ziekten' (formell) oder 'ziektes' (umgangssprachlich).","genus":"de","plural":"ziekten"},"hu9_speculatie":{"lemma":"speculatie","displayNl":"de speculatie","pos":"substantief","meanings":[{"de":"die Spekulation, Vermutung, Mutmaßung","ex":"Zijn speculatie heeft menig tijdgenoot verbaasd.","exDe":"Seine Spekulation hat manchen Zeitgenossen verblüfft."},{"de":"die Spekulation (finanzielles Geschäft mit Gewinnhoffnung)","ex":"De handelaar verloor een fortuin door speculatie op de beurs.","exDe":"Der Händler verlor ein Vermögen durch Spekulation an der Börse."}],"usage":"Beide Bedeutungen gängig: gedankliche Mutmaßung und finanzielle Spekulation.","genus":"de","plural":"speculaties"},"hu9_sterrenstelsel":{"lemma":"sterrenstelsel","displayNl":"het sterrenstelsel","pos":"substantief","meanings":[{"de":"die Galaxie, das Sternsystem","ex":"Hij heeft aangenomen dat andere sterrenstelsels bewoonbaar zijn.","exDe":"Er hat angenommen, dass andere Sternsysteme bewohnbar sind."}],"usage":"Astronomischer Begriff; 'ons sterrenstelsel' = unsere Galaxie (die Milchstraße).","genus":"het","plural":"sterrenstelsels","illustratable":true},"hu9_nalatenschap":{"lemma":"nalatenschap","displayNl":"de nalatenschap","pos":"substantief","meanings":[{"de":"der Nachlass, das Erbe, die Hinterlassenschaft","ex":"Zijn Cosmotheoros is uit zijn nalatenschap gepubliceerd.","exDe":"Sein Cosmotheoros ist aus seinem Nachlass veröffentlicht worden."},{"de":"das (geistige) Vermächtnis, Erbe (übertragen)","ex":"Zijn wetenschappelijke nalatenschap inspireert nog altijd astronomen.","exDe":"Sein wissenschaftliches Vermächtnis inspiriert bis heute Astronomen."}],"usage":"Konkret der materielle Nachlass eines Verstorbenen, übertragen auch das geistige Erbe.","genus":"de","plural":"nalatenschappen"},"hu9_bewoonbaarheid":{"lemma":"bewoonbaarheid","displayNl":"de bewoonbaarheid","pos":"substantief","meanings":[{"de":"die Bewohnbarkeit","ex":"Hij heeft de bewoonbaarheid van verre planeten overwogen.","exDe":"Er hat die Bewohnbarkeit ferner Planeten erwogen."}],"usage":"Abstraktes Substantiv, in der Regel nur im Singular; abgeleitet von 'bewoonbaar' (bewohnbar).","genus":"de"},"hu10_erfenis":{"lemma":"erfenis","displayNl":"de erfenis","pos":"substantief","meanings":[{"de":"das Vermächtnis, das Erbe (übertragen: bleibende Wirkung)","ex":"Zijn wetenschappelijke erfenis reikt van de mechanica tot de optica.","exDe":"Sein wissenschaftliches Vermächtnis reicht von der Mechanik bis zur Optik."},{"de":"die Erbschaft (geerbtes Vermögen)","ex":"Na de dood van haar tante kreeg ze een grote erfenis.","exDe":"Nach dem Tod ihrer Tante bekam sie eine große Erbschaft."}],"usage":"Übertragen (kulturelles/wissenschaftliches Vermächtnis) wie konkret (geerbtes Vermögen). Verwandtes Verb: erven.","genus":"de","plural":"erfenissen"},"hu10_bijdrage":{"lemma":"bijdrage","displayNl":"de bijdrage","pos":"substantief","meanings":[{"de":"der Beitrag (Mitwirkung, Anteil an etwas)","ex":"Zijn bijdrage aan de astronomie was baanbrekend.","exDe":"Sein Beitrag zur Astronomie war bahnbrechend."},{"de":"der (finanzielle) Beitrag, die Spende","ex":"We vragen een kleine bijdrage voor de koffie.","exDe":"Wir bitten um einen kleinen Beitrag für den Kaffee."}],"usage":"Feste Verbindung: een bijdrage leveren aan iets (einen Beitrag zu etwas leisten).","genus":"de","plural":"bijdragen"},"hu10_ruimtesonde":{"lemma":"ruimtesonde","displayNl":"de ruimtesonde","pos":"substantief","meanings":[{"de":"die Raumsonde (unbemanntes Raumfahrzeug zur Erforschung des Weltraums)","ex":"De ruimtesonde landde op Titan na een reis van jaren.","exDe":"Die Raumsonde landete nach einer jahrelangen Reise auf Titan."}],"usage":"Zusammensetzung: ruimte (Weltraum) + sonde. Plural auch: ruimtesonden.","genus":"de","plural":"ruimtesondes","illustratable":true},"hu10_ruimtevaart":{"lemma":"ruimtevaart","displayNl":"de ruimtevaart","pos":"substantief","meanings":[{"de":"die Raumfahrt (Gebiet/Tätigkeit der Reise und Erforschung im Weltraum)","ex":"De moderne ruimtevaart eert hem, omdat hij Titan ontdekte.","exDe":"Die moderne Raumfahrt ehrt ihn, weil er Titan entdeckte."}],"usage":"Abstraktes Fach-/Tätigkeitsgebiet, meist ohne Plural. Zusammensetzung: ruimte + vaart (Fahrt).","genus":"de"},"hu10_natuurwetenschapper":{"lemma":"natuurwetenschapper","displayNl":"de natuurwetenschapper","pos":"substantief","meanings":[{"de":"der Naturwissenschaftler (Person, die Naturwissenschaften betreibt)","ex":"Hij was een natuurwetenschapper wiens invloed nauwelijks te overschatten is.","exDe":"Er war ein Naturwissenschaftler, dessen Einfluss kaum zu überschätzen ist."}],"usage":"Zusammensetzung: natuur (Natur) + wetenschapper (Wissenschaftler). Weibliche Form: natuurwetenschapster.","genus":"de","plural":"natuurwetenschappers","illustratable":true},"hu10_mechanica":{"lemma":"mechanica","displayNl":"de mechanica","pos":"substantief","meanings":[{"de":"die Mechanik (Teilgebiet der Physik von Kräften und Bewegung)","ex":"Hij bestudeerde de mechanica, terwijl hij ook de optica beoefende.","exDe":"Er studierte die Mechanik, während er auch die Optik betrieb."}],"usage":"Fachgebiet der Physik, singularisch (kein Plural). Nicht verwechseln mit 'het mechaniek' (Mechanismus/Werk).","genus":"de"},"hu10_invloed":{"lemma":"invloed","displayNl":"de invloed","pos":"substantief","meanings":[{"de":"der Einfluss (Wirkung auf jemanden/etwas)","ex":"Zijn invloed bleef groot, ook al werd hij overschaduwd door Newton.","exDe":"Sein Einfluss blieb groß, auch wenn er von Newton überschattet wurde."},{"de":"die Einwirkung, der (schädliche) Effekt","ex":"Onder invloed van alcohol mag je niet rijden.","exDe":"Unter dem Einfluss von Alkohol darf man nicht fahren."}],"usage":"Feste Wendungen: invloed hebben op iets (Einfluss auf etwas haben); onder invloed (unter Einfluss/betrunken).","genus":"de","plural":"invloeden"},"lo1_burgerij":{"lemma":"burgerij","displayNl":"de burgerij","pos":"substantief","meanings":[{"de":"das Bürgertum (Gesamtheit der Bürger, bürgerliche Schicht)","ex":"De ontwikkelde burgerij hechtte grote waarde aan onderwijs.","exDe":"Das gebildete Bürgertum maß der Bildung großen Wert bei."}],"usage":"Kollektivbegriff für die Bürgerschaft/das Bürgertum, meist ohne Plural.","genus":"de"},"lo1_natuurkunde":{"lemma":"natuurkunde","displayNl":"de natuurkunde","pos":"substantief","meanings":[{"de":"die Physik","ex":"De natuurkunde werd zijn levenslange roeping.","exDe":"Die Physik wurde seine lebenslange Berufung."},{"de":"Physik (Schulfach)","ex":"Op de middelbare school had ik graag natuurkunde.","exDe":"In der weiterführenden Schule mochte ich Physik gern."}],"usage":"Unzählbares Fach-/Wissenschaftssubstantiv, immer 'de natuurkunde', kein Plural.","genus":"de"},"lo1_industrialisatie":{"lemma":"industrialisatie","displayNl":"de industrialisatie","pos":"substantief","meanings":[{"de":"die Industrialisierung","ex":"De industrialisatie veranderde het aanzien van het land.","exDe":"Die Industrialisierung veränderte das Antlitz des Landes."}],"usage":"Abstraktes Prozesssubstantiv, meist ohne Plural; 'de industrialisatie'.","genus":"de"},"lo1_aanleg":{"lemma":"aanleg","displayNl":"de aanleg","pos":"substantief","meanings":[{"de":"die Begabung, die Veranlagung","ex":"Zijn wiskundige aanleg werd al vroeg zichtbaar.","exDe":"Seine mathematische Begabung wurde schon früh sichtbar."},{"de":"die Anlage, das Anlegen (von Wegen, Gärten, Leitungen)","ex":"De aanleg van de nieuwe fietsroute duurde twee jaar.","exDe":"Das Anlegen der neuen Fahrradroute dauerte zwei Jahre."},{"de":"die Anlage (angeborene Neigung, auch medizinisch)","ex":"Ze heeft een erfelijke aanleg voor die ziekte.","exDe":"Sie hat eine erbliche Veranlagung für diese Krankheit."}],"usage":"'de aanleg', überwiegend ohne Plural; verbindet die Bedeutungen 'Begabung' und 'Anlegen/Bau'.","genus":"de"},"lo2_leerstoel":{"lemma":"leerstoel","displayNl":"de leerstoel","pos":"substantief","meanings":[{"de":"der Lehrstuhl (Professur)","ex":"Hij kreeg de eerste leerstoel voor theoretische natuurkunde.","exDe":"Er erhielt den ersten Lehrstuhl für theoretische Physik."}],"usage":"Akademischer Begriff (Professur), nicht der wörtliche Stuhl; 'de leerstoel', Plural 'leerstoelen'.","genus":"de","plural":"leerstoelen"},"lo2_hoogleraar":{"lemma":"hoogleraar","displayNl":"de hoogleraar","pos":"substantief","meanings":[{"de":"der Professor / die Professorin (an einer Universität)","ex":"Op zijn vierentwintigste werd hij benoemd tot hoogleraar.","exDe":"Mit vierundzwanzig wurde er zum Professor ernannt."}],"usage":"Höchster akademischer Rang; 'de hoogleraar', Plural 'hoogleraren'. Nicht mit 'leraar' (Lehrer) verwechseln.","genus":"de","plural":"hoogleraren","illustratable":true},"lo2_promoveren":{"lemma":"promoveren","displayNl":"promoveren","pos":"werkwoord","meanings":[{"de":"promovieren, den Doktortitel erwerben","ex":"Hij promoveerde met een proefschrift over de lichtbreking.","exDe":"Er promovierte mit einer Dissertation über die Lichtbrechung."},{"de":"befördert werden, aufsteigen (auch Sport: aufsteigen)","ex":"De club promoveerde dit seizoen naar de eredivisie.","exDe":"Der Verein stieg diese Saison in die Eredivisie auf."}],"usage":"Regelmäßiges Verb auf -eren; Hilfsverb 'zijn' (hij is gepromoveerd). Bedeutet sowohl 'promovieren' als auch 'aufsteigen/befördert werden'.","conjugation":{"presens":{"ik":"promoveer","jij":"promoveert","hij":"promoveert","wij":"promoveren"},"imperfectum":{"ik":"promoveerde","wij":"promoveerden"},"perfectum":{"aux":"zijn","participle":"gepromoveerd"}}},"lo2_theorie":{"lemma":"theoretische natuurkunde","displayNl":"de theoretische natuurkunde","pos":"substantief","meanings":[{"de":"die theoretische Physik","ex":"De theoretische natuurkunde bestond nog nauwelijks als vak.","exDe":"Die theoretische Physik existierte kaum als Fach."}],"usage":"Fachbezeichnung (Adjektiv + Substantiv); Genus richtet sich nach 'natuurkunde' (de), kein Plural.","genus":"de"},"lo2_vergelijking":{"lemma":"vergelijking","displayNl":"de vergelijking","pos":"substantief","meanings":[{"de":"die Gleichung (Mathematik/Physik)","ex":"Hij leidde de vergelijkingen van Maxwell verder uit.","exDe":"Er entwickelte die Gleichungen Maxwells weiter."},{"de":"der Vergleich","ex":"In vergelijking met vroeger gaat het nu veel beter.","exDe":"Im Vergleich zu früher geht es jetzt viel besser."}],"usage":"'de vergelijking', Plural 'vergelijkingen'. Zwei Bedeutungen: mathematische Gleichung und Vergleich (oft 'in vergelijking met').","genus":"de","plural":"vergelijkingen"},"lo3_elektron":{"lemma":"elektron","displayNl":"het elektron","pos":"substantief","meanings":[{"de":"das Elektron","ex":"Het elektron is het kleinste geladen deeltje.","exDe":"Das Elektron ist das kleinste geladene Teilchen."}],"usage":"Physik: negativ geladenes Elementarteilchen der Atomhülle. Neutrum: 'het elektron'.","genus":"het","plural":"elektronen"},"lo3_elektronentheorie":{"lemma":"elektronentheorie","displayNl":"de elektronentheorie","pos":"substantief","meanings":[{"de":"die Elektronentheorie","ex":"Zijn elektronentheorie verklaarde tal van verschijnselen.","exDe":"Seine Elektronentheorie erklärte zahlreiche Phänomene."}],"usage":"Fachbegriff der Physik; abstrakt. De-Wort.","genus":"de","plural":"elektronentheorieën"},"lo3_lading":{"lemma":"lading","displayNl":"de lading","pos":"substantief","meanings":[{"de":"die Ladung (elektrisch)","ex":"De lading van het elektron is negatief.","exDe":"Die Ladung des Elektrons ist negativ."},{"de":"die Ladung, die Fracht (eines Fahrzeugs/Schiffs)","ex":"De vrachtwagen vervoert een zware lading.","exDe":"Der Lastwagen transportiert eine schwere Ladung."},{"de":"die Ladung (einer Waffe/Sprengladung)","ex":"De lading van het geweer was leeg.","exDe":"Die Ladung des Gewehrs war leer."}],"usage":"Homonymie: elektrische Ladung (Physik), Fracht/Beladung, sowie Spreng-/Munitionsladung.","genus":"de","plural":"ladingen"},"lo3_veld":{"lemma":"veld","displayNl":"het veld","pos":"substantief","meanings":[{"de":"das Feld (Physik, z. B. elektromagnetisches Feld)","ex":"Het elektromagnetische veld draagt de energie over.","exDe":"Das elektromagnetische Feld überträgt die Energie."},{"de":"das Feld, der Acker (Landwirtschaft)","ex":"De boer ploegt zijn veld in de lente.","exDe":"Der Bauer pflügt sein Feld im Frühling."},{"de":"das Spielfeld","ex":"De spelers rennen over het veld.","exDe":"Die Spieler rennen über das Spielfeld."},{"de":"das Feld, der Bereich (übertragen)","ex":"Zij is expert op het veld van de biologie.","exDe":"Sie ist Expertin auf dem Gebiet der Biologie."}],"usage":"Eintrag war Phrase 'het elektromagnetische veld' → Lemma-Kopf 'veld'. Neutrum: 'het veld', Plural 'velden'.","genus":"het","plural":"velden","illustratable":true},"lo3_trilling":{"lemma":"trilling","displayNl":"de trilling","pos":"substantief","meanings":[{"de":"die Schwingung, die Vibration","ex":"De trilling van de elektronen zendt licht uit.","exDe":"Die Schwingung der Elektronen sendet Licht aus."},{"de":"das Zittern, das Beben","ex":"Ik voelde een trilling in mijn handen.","exDe":"Ich spürte ein Zittern in meinen Händen."}],"usage":"Physik/Alltag: periodische Schwingung bzw. Zittern. De-Wort, Plural 'trillingen'. Abstrakt.","genus":"de","plural":"trillingen"},"lo3_materie":{"lemma":"materie","displayNl":"de materie","pos":"substantief","meanings":[{"de":"die Materie (Physik, Stoff)","ex":"Hij verbond de materie met het veld.","exDe":"Er verband die Materie mit dem Feld."},{"de":"die Materie, das Thema, der Stoff (übertragen)","ex":"Dit is een ingewikkelde materie voor beginners.","exDe":"Das ist eine komplizierte Materie für Anfänger."}],"usage":"Physikalisch 'Stoff/Materie' und übertragen 'Themengebiet'. De-Wort. Abstrakt.","genus":"de","plural":"materies"},"lo3_stroom":{"lemma":"stroom","displayNl":"de stroom","pos":"substantief","meanings":[{"de":"der (elektrische) Strom","ex":"De beweging van ladingen wekt een stroom op.","exDe":"Die Bewegung von Ladungen erzeugt einen Strom."},{"de":"der Strom, der Fluss, die Strömung (Wasser)","ex":"De rivier heeft een sterke stroom.","exDe":"Der Fluss hat eine starke Strömung."},{"de":"der Strom, die Menge in Bewegung (übertragen)","ex":"Een stroom van mensen liep het station uit.","exDe":"Ein Strom von Menschen verließ den Bahnhof."}],"usage":"Homonymie: elektrischer Strom, Wasserströmung/Fluss, übertragen 'Menschenstrom'. De-Wort, Plural 'stromen'.","genus":"de","plural":"stromen","illustratable":true},"lo4_lorentzkracht":{"lemma":"lorentzkracht","displayNl":"de lorentzkracht","pos":"substantief","meanings":[{"de":"die Lorentzkraft","ex":"De lorentzkracht wordt uitgeoefend op een bewegende lading.","exDe":"Die Lorentzkraft wird auf eine bewegte Ladung ausgeübt."}],"usage":"Physik-Fachbegriff (nach H. A. Lorentz); Kraft auf eine bewegte Ladung im Magnetfeld. De-Wort. Abstrakt.","genus":"de","plural":"lorentzkrachten"},"lo4_magneetveld":{"lemma":"magneetveld","displayNl":"het magneetveld","pos":"substantief","meanings":[{"de":"das Magnetfeld","ex":"In het magneetveld wordt het geladen deeltje afgebogen.","exDe":"Im Magnetfeld wird das geladene Teilchen abgelenkt."},{"de":"das magnetische Feld (Bereich der Magnetwirkung)","ex":"Rondom de spoel ontstaat een sterk magneetveld.","exDe":"Um die Spule herum entsteht ein starkes Magnetfeld."}],"usage":"Fachbegriff der Physik. Synonym/Umschreibung: 'het magnetische veld'. Grundform des Kompositums ist 'magneetveld'.","genus":"het","plural":"magneetvelden"},"lo4_kracht":{"lemma":"kracht","displayNl":"de kracht","pos":"substantief","meanings":[{"de":"die Kraft (Physik, Einwirkung)","ex":"Er wordt een kracht op het elektron uitgeoefend.","exDe":"Es wird eine Kraft auf das Elektron ausgeübt."},{"de":"die Stärke, die Körperkraft","ex":"Hij tilde de kist met al zijn kracht op.","exDe":"Er hob die Kiste mit all seiner Kraft hoch."},{"de":"die Macht, die Wirksamkeit (z. B. einer Regel/eines Gesetzes)","ex":"De nieuwe wet treedt morgen in kracht.","exDe":"Das neue Gesetz tritt morgen in Kraft."}],"usage":"Vielseitiges Substantiv: physikalische Kraft, körperliche Stärke und übertragen 'in werking/in kracht'.","genus":"de","plural":"krachten"},"lo4_afbuigen":{"lemma":"afbuigen","displayNl":"afbuigen","pos":"werkwoord","meanings":[{"de":"ablenken, abgelenkt werden (Bahn, Strahl)","ex":"Het magneetveld doet de baan van het deeltje afbuigen.","exDe":"Das Magnetfeld lenkt die Bahn des Teilchens ab."},{"de":"abbiegen, abzweigen (Weg, Straße)","ex":"De weg buigt hier scherp naar links af.","exDe":"Die Straße biegt hier scharf nach links ab."}],"usage":"Trennbares Verb (af | buigen), starke Konjugation wie 'buigen–boog–gebogen'. Bei Bewegung/Ortsveränderung auch mit 'zijn': 'de weg is naar links afgebogen'.","conjugation":{"presens":{"ik":"buig af","jij":"buigt af","hij":"buigt af","wij":"buigen af"},"imperfectum":{"ik":"boog af","wij":"bogen af"},"perfectum":{"aux":"hebben","participle":"afgebogen"}}},"lo4_richting":{"lemma":"richting","displayNl":"de richting","pos":"substantief","meanings":[{"de":"die Richtung (räumlich)","ex":"De richting van de kracht staat loodrecht op de beweging.","exDe":"Die Richtung der Kraft steht senkrecht zur Bewegung."},{"de":"die Fachrichtung, die Strömung (übertragen)","ex":"Zij koos een technische richting op de universiteit.","exDe":"Sie wählte an der Universität eine technische Fachrichtung."}],"usage":"'in de richting van' = in Richtung. Auch übertragen für Studien-/Denkrichtung.","genus":"de","plural":"richtingen"},"lo4_beweging":{"lemma":"beweging","displayNl":"de beweging","pos":"substantief","meanings":[{"de":"die Bewegung (Physik, Ortsveränderung)","ex":"Zonder beweging wordt geen lorentzkracht opgewekt.","exDe":"Ohne Bewegung wird keine Lorentzkraft erzeugt."},{"de":"die Bewegung (körperlich, Sport)","ex":"Dagelijkse beweging is goed voor je gezondheid.","exDe":"Tägliche Bewegung ist gut für deine Gesundheit."},{"de":"die Bewegung (gesellschaftlich, politisch)","ex":"De beweging streed voor gelijke rechten.","exDe":"Die Bewegung kämpfte für gleiche Rechte."}],"usage":"'in beweging' = in Bewegung. Deckt physikalische, körperliche und gesellschaftliche Bedeutung ab.","genus":"de","plural":"bewegingen"},"lo4_magneet":{"lemma":"magneet","displayNl":"de magneet","pos":"substantief","meanings":[{"de":"der Magnet","ex":"De magneet oefent invloed uit op geladen deeltjes.","exDe":"Der Magnet übt Einfluss auf geladene Teilchen aus."},{"de":"der Anziehungspunkt, der Publikumsmagnet (übertragen)","ex":"Het museum is een echte magneet voor toeristen.","exDe":"Das Museum ist ein echter Magnet für Touristen."}],"usage":"Konkret das physikalische Objekt; übertragen für etwas, das stark anzieht.","genus":"de","plural":"magneten","illustratable":true},"lo5_zeemaneffect":{"lemma":"zeeman-effect","displayNl":"het zeeman-effect","pos":"substantief","meanings":[{"de":"der Zeeman-Effekt (Aufspaltung von Spektrallinien im Magnetfeld)","ex":"Het zeeman-effect heeft de elektronentheorie bevestigd.","exDe":"Der Zeeman-Effekt hat die Elektronentheorie bestätigt."}],"usage":"Physikalischer Fachbegriff, benannt nach Pieter Zeeman; kein Plural gebräuchlich.","genus":"het"},"lo5_nobelprijs":{"lemma":"nobelprijs","displayNl":"de nobelprijs","pos":"substantief","meanings":[{"de":"der Nobelpreis","ex":"Zij hebben in 1902 samen de nobelprijs ontvangen.","exDe":"Sie haben 1902 gemeinsam den Nobelpreis erhalten."}],"usage":"Auszeichnung; oft mit Fachgebiet: 'de Nobelprijs voor de Natuurkunde'. Häufig großgeschrieben als Eigenname.","genus":"de","plural":"nobelprijzen"},"lo5_spectraallijn":{"lemma":"spectraallijn","displayNl":"de spectraallijn","pos":"substantief","meanings":[{"de":"die Spektrallinie","ex":"De spectraallijn in het magneetveld is gesplitst.","exDe":"Die Spektrallinie ist im Magnetfeld aufgespalten."},{"de":"die Spektrallinie (charakteristische Emissions-/Absorptionslinie)","ex":"Elke spectraallijn hoort bij een bepaald element.","exDe":"Jede Spektrallinie gehört zu einem bestimmten Element."}],"usage":"Fachbegriff aus der Physik/Spektroskopie; Zusammensetzung uit spectraal + lijn.","genus":"de","plural":"spectraallijnen","illustratable":true},"lo5_splitsing":{"lemma":"splitsing","displayNl":"de splitsing","pos":"substantief","meanings":[{"de":"die Aufspaltung, die Aufteilung","ex":"De splitsing van de lijnen heeft iedereen verrast.","exDe":"Die Aufspaltung der Linien hat alle überrascht."},{"de":"die Abzweigung, die Weggabelung, die Kreuzung","ex":"Bij de splitsing moet je linksaf slaan.","exDe":"An der Abzweigung musst du links abbiegen."},{"de":"die Spaltung, die Teilung (z. B. eines Unternehmens)","ex":"De splitsing van het bedrijf duurde jaren.","exDe":"Die Aufspaltung des Unternehmens dauerte Jahre."}],"usage":"Nomen zum Verb splitsen. Im Alltag meist die Weggabelung/Abzweigung, im Fachtext die Aufspaltung.","genus":"de","plural":"splitsingen","illustratable":true},"lo5_leerling":{"lemma":"leerling","displayNl":"de leerling","pos":"substantief","meanings":[{"de":"der Schüler, die Schülerin","ex":"De leerling steekt zijn hand op in de klas.","exDe":"Der Schüler hebt in der Klasse die Hand."},{"de":"der Schüler, der Lehrling (jemand, der bei einem Meister lernt)","ex":"Zijn leerling Zeeman ontdekte het verschijnsel.","exDe":"Sein Schüler Zeeman entdeckte das Phänomen."}],"usage":"Neutral für Schulkind wie auch für den Schüler eines Meisters/Gelehrten.","genus":"de","plural":"leerlingen","illustratable":true},"lo5_spectrum":{"lemma":"spectrum","displayNl":"het spectrum","pos":"substantief","meanings":[{"de":"das Spektrum (Farbband des Lichts)","ex":"In het spectrum zijn extra lijnen verschenen.","exDe":"Im Spektrum sind zusätzliche Linien erschienen."},{"de":"das Spektrum, die Bandbreite (Bereich von Möglichkeiten)","ex":"De partij bestrijkt een breed politiek spectrum.","exDe":"Die Partei deckt ein breites politisches Spektrum ab."}],"usage":"Griechisch-lateinisches Fremdwort, daher Plural spectra. Konkret (Licht) und übertragen (Bandbreite).","genus":"het","plural":"spectra","illustratable":true},"lo5_golflengte":{"lemma":"golflengte","displayNl":"de golflengte","pos":"substantief","meanings":[{"de":"die Wellenlänge","ex":"De golflengte van het uitgezonden licht is veranderd.","exDe":"Die Wellenlänge des ausgesandten Lichts hat sich verändert."},{"de":"die Wellenlänge (übertragen: die gemeinsame Verständigungsebene)","ex":"Wij zitten echt op dezelfde golflengte.","exDe":"Wir sind wirklich auf einer Wellenlänge."}],"usage":"Zusammensetzung golf + lengte. Übertragene Wendung op dezelfde golflengte zitten = sich gut verstehen.","genus":"de","plural":"golflengtes","illustratable":true},"lo6_lengtecontractie":{"lemma":"lengtecontractie","displayNl":"de lengtecontractie","pos":"substantief","meanings":[{"de":"die Längenkontraktion","ex":"De lengtecontractie verkort bewegende voorwerpen.","exDe":"Die Längenkontraktion verkürzt bewegte Körper."}],"usage":"Fachbegriff der speziellen Relativitätstheorie; abstrakt, nicht bildlich eindeutig.","genus":"de","plural":"lengtecontracties"},"lo6_lichtsnelheid":{"lemma":"lichtsnelheid","displayNl":"de lichtsnelheid","pos":"substantief","meanings":[{"de":"die Lichtgeschwindigkeit","ex":"De lichtsnelheid bleek constant te zijn.","exDe":"Die Lichtgeschwindigkeit erwies sich als konstant."},{"de":"die Lichtgeschwindigkeit (übertragen: sehr hohes Tempo)","ex":"Hij rende met de lichtsnelheid naar huis.","exDe":"Er rannte mit Lichtgeschwindigkeit nach Hause."}],"usage":"Physikalische Konstante; übertragen umgangssprachlich für extrem schnell. Abstrakter Messwert, nicht eindeutig bildlich.","genus":"de","plural":"lichtsnelheden"},"lo6_meting":{"lemma":"meting","displayNl":"de meting","pos":"substantief","meanings":[{"de":"die Messung","ex":"De meting die zij verrichtten, toonde geen etherwind.","exDe":"Die Messung, die sie durchführten, zeigte keinen Ätherwind."},{"de":"die Messung, der Messwert (Ergebnis einer Messung)","ex":"De meting wijkt af van de verwachte waarde.","exDe":"Die Messung weicht vom erwarteten Wert ab."}],"usage":"Nomen zum Verb meten. Sowohl der Vorgang als auch das Ergebnis; abstrakter Begriff.","genus":"de","plural":"metingen"},"lo6_verkorting":{"lemma":"verkorting","displayNl":"de verkorting","pos":"substantief","meanings":[{"de":"die Verkürzung","ex":"De verkorting die optreedt, geldt slechts in de bewegingsrichting.","exDe":"Die Verkürzung, die auftritt, gilt nur in Bewegungsrichtung."},{"de":"die Abkürzung (verkürzte Form eines Wortes)","ex":"\"Tv\" is een verkorting van \"televisie\".","exDe":"\"Tv\" ist eine Abkürzung von \"Fernsehen\"."}],"usage":"Nomen (de-Wort) für den Vorgang oder das Ergebnis des Kürzerwerdens; in der Physik die Längenkontraktion, im Sprachgebrauch auch eine Abkürzung.","genus":"de","plural":"verkortingen"},"lo6_voortplanting":{"lemma":"voortplanting","displayNl":"de voortplanting","pos":"substantief","meanings":[{"de":"die Ausbreitung (von Wellen/Licht/Schall)","ex":"De voortplanting van het licht, die men bestudeerde, bleef raadselachtig.","exDe":"Die Ausbreitung des Lichts, die man untersuchte, blieb rätselhaft."},{"de":"die Fortpflanzung (biologische Vermehrung)","ex":"De voortplanting van deze planten gebeurt via zaden.","exDe":"Die Fortpflanzung dieser Pflanzen erfolgt über Samen."}],"usage":"Nomen (de-Wort); in der Biologie die Fortpflanzung, in der Physik die Ausbreitung von Wellen oder Signalen.","genus":"de","plural":"voortplantingen"},"lo6_raadsel":{"lemma":"raadsel","displayNl":"het raadsel","pos":"substantief","meanings":[{"de":"das Rätsel (etwas Unerklärliches)","ex":"Het raadsel dat de meting opwierp, vroeg om een nieuwe theorie.","exDe":"Das Rätsel, das die Messung aufwarf, verlangte eine neue Theorie."},{"de":"das Rätsel (Denksportaufgabe zum Lösen)","ex":"De kinderen probeerden het raadsel op te lossen.","exDe":"Die Kinder versuchten, das Rätsel zu lösen."}],"usage":"Nomen (het-Wort) für etwas Unerklärliches oder eine Denksportaufgabe; Plural auch \"raadselen\".","genus":"het","plural":"raadsels"},"lo7_transformatie":{"lemma":"lorentztransformatie","displayNl":"de lorentztransformatie","pos":"substantief","meanings":[{"de":"die Lorentz-Transformation","ex":"Men gebruikt de lorentztransformatie omdat zij ruimte en tijd verbindt.","exDe":"Man verwendet die Lorentz-Transformation, weil sie Raum und Zeit verbindet."}],"usage":"Nomen (de-Wort), physikalischer Fachbegriff; Umrechnung von Raum- und Zeitkoordinaten zwischen bewegten Bezugssystemen.","genus":"de","plural":"lorentztransformaties"},"lo7_relativiteit":{"lemma":"relativiteitstheorie","displayNl":"de relativiteitstheorie","pos":"substantief","meanings":[{"de":"die Relativitätstheorie","ex":"Einstein bouwde de relativiteitstheorie op, terwijl hij Lorentz' formules gebruikte.","exDe":"Einstein baute die Relativitätstheorie auf, während er Lorentz' Formeln nutzte."}],"usage":"Nomen (de-Wort), physikalischer Fachbegriff; Einsteins Theorie über Raum, Zeit und Gravitation.","genus":"de","plural":"relativiteitstheorieën"},"lo7_tijdsdilatatie":{"lemma":"tijdsdilatatie","displayNl":"de tijdsdilatatie","pos":"substantief","meanings":[{"de":"die Zeitdilatation","ex":"De tijdsdilatatie ontstaat wanneer een klok zeer snel beweegt.","exDe":"Die Zeitdilatation entsteht, wenn eine Uhr sich sehr schnell bewegt."}],"usage":"Nomen (de-Wort), physikalischer Fachbegriff; die relativistische Dehnung der Zeit bei schneller Bewegung.","genus":"de","plural":"tijdsdilataties"},"lo7_referentiekader":{"lemma":"referentiekader","displayNl":"het referentiekader","pos":"substantief","meanings":[{"de":"das Bezugssystem (Physik)","ex":"Elke waarnemer beoordeelt de tijd vanuit zijn eigen referentiekader.","exDe":"Jeder Beobachter beurteilt die Zeit aus seinem eigenen Bezugssystem."},{"de":"der Bezugsrahmen (gedanklicher Rahmen)","ex":"Vanuit haar culturele referentiekader zag ze de situatie heel anders.","exDe":"Aus ihrem kulturellen Bezugsrahmen heraus sah sie die Situation ganz anders."}],"usage":"Nomen (het-Wort); in der Physik das Bezugssystem, allgemein der gedankliche Bezugsrahmen zur Einordnung von Dingen.","genus":"het","plural":"referentiekaders"},"lo7_coordinaat":{"lemma":"coördinaat","displayNl":"de coördinaat","pos":"substantief","meanings":[{"de":"die Koordinate","ex":"De formules herrekenen de coördinaten die tussen kaders verschillen.","exDe":"Die Formeln rechnen die Koordinaten um, die zwischen Systemen abweichen."}],"usage":"Nomen (de-Wort), mathematisch-physikalischer Fachbegriff; eine Zahl zur Angabe einer Position in einem Koordinatensystem.","genus":"de","plural":"coördinaten"},"lo7_waarnemer":{"lemma":"waarnemer","displayNl":"de waarnemer","pos":"substantief","meanings":[{"de":"der Beobachter","ex":"De waarnemer die beweegt, meet een andere tijd.","exDe":"Der Beobachter, der sich bewegt, misst eine andere Zeit."},{"de":"der Vertreter, der Stellvertreter (z. B. vertretender Arzt)","ex":"Tijdens de vakantie neemt een waarnemer de praktijk over.","exDe":"Während des Urlaubs übernimmt ein Vertreter die Praxis."}],"usage":"Personenbezeichnung; von het werkwoord 'waarnemen' (beobachten / vertreten).","genus":"de","plural":"waarnemers"},"lo7_gelijktijdigheid":{"lemma":"gelijktijdigheid","displayNl":"de gelijktijdigheid","pos":"substantief","meanings":[{"de":"die Gleichzeitigkeit","ex":"Men ontdekte dat de gelijktijdigheid relatief is.","exDe":"Man entdeckte, dass die Gleichzeitigkeit relativ ist."}],"usage":"Abstraktes Substantiv, oft in physikalischem/philosophischem Kontext.","genus":"de","plural":"gelijktijdigheden"},"lo7_formule":{"lemma":"formule","displayNl":"de formule","pos":"substantief","meanings":[{"de":"die Formel (mathematisch/wissenschaftlich)","ex":"Hij schreef de formules op waarmee tijd en ruimte samenhangen.","exDe":"Er schrieb die Formeln nieder, mit denen Zeit und Raum zusammenhängen."},{"de":"die feste Formel, die Formulierung (feststehender Ausdruck)","ex":"Ze begon haar brief met een beleefde formule.","exDe":"Sie begann ihren Brief mit einer höflichen Formel."},{"de":"das Konzept, das Format (Geschäftsmodell, z. B. 'winkelformule')","ex":"De keten heeft een succesvolle formule voor kleine winkels.","exDe":"Die Kette hat ein erfolgreiches Konzept für kleine Läden."}],"usage":"'de formule' voor wiskunde, taal én zakelijk concept.","genus":"de","plural":"formules"},"lo8_conferentie":{"lemma":"conferentie","displayNl":"de conferentie","pos":"substantief","meanings":[{"de":"die Konferenz, die Tagung","ex":"Hij leidde de conferentie, want niemand had meer gezag dan hij.","exDe":"Er leitete die Konferenz, denn niemand hatte mehr Autorität als er."},{"de":"die Konferenzschaltung, die (Telefon-)Konferenz","ex":"We bespraken het plan in een conferentie via de telefoon.","exDe":"Wir besprachen den Plan in einer Konferenz per Telefon."}],"usage":"Formelle Zusammenkunft; ook telefonisch/online gebruikt.","genus":"de","plural":"conferenties","illustratable":true},"lo8_voorzitter":{"lemma":"voorzitter","displayNl":"de voorzitter","pos":"substantief","meanings":[{"de":"der Vorsitzende, die/der Präsident(in) (eines Gremiums, Vereins)","ex":"Men koos hem tot voorzitter omdat hij zo bemiddelend was.","exDe":"Man wählte ihn zum Vorsitzenden, weil er so vermittelnd war."},{"de":"der Versammlungsleiter, die/der Sitzungsleiter(in)","ex":"De voorzitter opende de vergadering en gaf het woord.","exDe":"Der Vorsitzende eröffnete die Sitzung und erteilte das Wort."}],"usage":"Funktionsbezeichnung; vrouwelijk vaak 'voorzitster' of 'voorzitter'.","genus":"de","plural":"voorzitters"},"lo8_bemiddelaar":{"lemma":"bemiddelaar","displayNl":"de bemiddelaar","pos":"substantief","meanings":[{"de":"der Vermittler, der Mediator (in Konflikten)","ex":"Als bemiddelaar verzoende hij collega's, hoewel de oorlog woedde.","exDe":"Als Vermittler versöhnte er Kollegen, obwohl der Krieg tobte."},{"de":"der Vermittler, der Makler (Geschäfte, Versicherungen, Wohnungen)","ex":"Een bemiddelaar bracht koper en verkoper bij elkaar.","exDe":"Ein Vermittler brachte Käufer und Verkäufer zusammen."}],"usage":"Van 'bemiddelen'; plural ook 'bemiddelaren' mogelijk.","genus":"de","plural":"bemiddelaars"},"lo8_neutraliteit":{"lemma":"neutraliteit","displayNl":"de neutraliteit","pos":"substantief","meanings":[{"de":"die Neutralität (politisch, im Krieg)","ex":"Nederland behield zijn neutraliteit, zodat Lorentz vrij kon reizen.","exDe":"Die Niederlande wahrten ihre Neutralität, sodass Lorentz frei reisen konnte."},{"de":"die Neutralität, die Unparteilichkeit (Haltung)","ex":"De rechter bewaarde zijn neutraliteit tijdens het proces.","exDe":"Der Richter wahrte seine Neutralität während des Prozesses."}],"usage":"Abstract; doorgaans geen meervoud.","genus":"de"},"lo8_samenwerking":{"lemma":"samenwerking","displayNl":"de samenwerking","pos":"substantief","meanings":[{"de":"die Zusammenarbeit, die Kooperation","ex":"Hij bevorderde de samenwerking, ook al waren de landen vijandig.","exDe":"Er förderte die Zusammenarbeit, auch wenn die Länder verfeindet waren."}],"usage":"Van 'samenwerken'; vaak 'in samenwerking met' (in Zusammenarbeit mit).","genus":"de","plural":"samenwerkingen"},"lo8_grens":{"lemma":"grens","displayNl":"de grens","pos":"substantief","meanings":[{"de":"Grenze (Landes-/Gebietsgrenze)","ex":"Aan de grens moesten we onze paspoorten laten zien.","exDe":"An der Grenze mussten wir unsere Pässe zeigen."},{"de":"Grenze, Limit (übertragen)","ex":"Iedereen heeft zijn grenzen, ook op het werk.","exDe":"Jeder hat seine Grenzen, auch bei der Arbeit."}],"usage":"Zählbar; Landesgrenze wie auch übertragene Belastungs-/Wissensgrenze. Feste Wendungen: 'de grens overschrijden', 'grenzen stellen'.","genus":"de","plural":"grenzen","illustratable":true},"lo8_gezag":{"lemma":"gezag","displayNl":"het gezag","pos":"substantief","meanings":[{"de":"Autorität, Ansehen","ex":"De leraar had veel gezag over zijn leerlingen.","exDe":"Der Lehrer hatte viel Autorität über seine Schüler."},{"de":"Behörde, Obrigkeit","ex":"Het bevoegd gezag moet de vergunning goedkeuren.","exDe":"Die zuständige Behörde muss die Genehmigung erteilen."}],"usage":"Meist unzählbar (Autorität). In der Bedeutung 'Behörde' fest in Wendungen wie 'het bevoegd gezag', 'het openbaar gezag'.","genus":"het"},"lo9_afsluitdijk":{"lemma":"afsluitdijk","displayNl":"de afsluitdijk","pos":"substantief","meanings":[{"de":"Abschlussdeich, Absperrdamm (der ein Gewässer abschließt)","ex":"De afsluitdijk maakte van de Zuiderzee het zoete IJsselmeer.","exDe":"Der Abschlussdeich machte aus der Zuiderzee das süße IJsselmeer."}],"usage":"Gattungsname für einen absperrenden Deich; mit großem A ('de Afsluitdijk') der berühmte Damm zwischen Nordholland und Friesland.","genus":"de","plural":"afsluitdijken","illustratable":true},"lo9_getij":{"lemma":"getij","displayNl":"het getij","pos":"substantief","meanings":[{"de":"Gezeiten, Tide (Ebbe und Flut)","ex":"Het getij trekt zich twee keer per dag terug.","exDe":"Die Tide zieht sich zweimal am Tag zurück."},{"de":"Wandel der Umstände (übertragen)","ex":"Het politieke getij was gekeerd na de verkiezingen.","exDe":"Die politische Stimmung hatte sich nach der Wahl gedreht."}],"usage":"Naturphänomen Ebbe/Flut; übertragen 'het getij keert' für einen Umschwung der Lage. Plural 'getijden'.","genus":"het","plural":"getijden","illustratable":true},"lo9_waterstand":{"lemma":"waterstand","displayNl":"de waterstand","pos":"substantief","meanings":[{"de":"Wasserstand, Pegel","ex":"Door de regen steeg de waterstand in de rivier snel.","exDe":"Durch den Regen stieg der Wasserstand im Fluss schnell."}],"usage":"Höhe des Wasserspiegels; oft mit 'stijgen', 'dalen', 'meten'. Fachlich: 'de waterstand ten opzichte van NAP'.","genus":"de","plural":"waterstanden","illustratable":true},"lo9_landaanwinning":{"lemma":"landaanwinning","displayNl":"de landaanwinning","pos":"substantief","meanings":[{"de":"Landgewinnung (Gewinnen von Land aus dem Wasser)","ex":"Door landaanwinning ontstonden er nieuwe polders.","exDe":"Durch Landgewinnung entstanden neue Polder."}],"usage":"Meist unzählbar als Prozess; das Trockenlegen und Eindeichen von Land. Verwandt mit 'inpolderen', 'droogleggen'.","genus":"de","plural":"landaanwinningen","illustratable":true},"lo9_stroming":{"lemma":"stroming","displayNl":"de stroming","pos":"substantief","meanings":[{"de":"Strömung (von Wasser oder Luft)","ex":"De sterke stroming maakte het zwemmen gevaarlijk.","exDe":"Die starke Strömung machte das Schwimmen gefährlich."},{"de":"Strömung, Richtung (geistig, künstlerisch, politisch)","ex":"Het impressionisme was een belangrijke stroming in de kunst.","exDe":"Der Impressionismus war eine bedeutende Strömung in der Kunst."}],"usage":"Konkret die Bewegung von Wasser/Luft; übertragen eine geistige, künstlerische oder politische Richtung ('een politieke stroming').","genus":"de","plural":"stromingen","illustratable":true},"lo9_berekening":{"lemma":"berekening","displayNl":"de berekening","pos":"substantief","meanings":[{"de":"Berechnung, Kalkulation (Rechenvorgang/Ergebnis)","ex":"Volgens mijn berekening kost het project te veel geld.","exDe":"Nach meiner Berechnung kostet das Projekt zu viel Geld."},{"de":"Berechnung, Kalkül (kühl berechnendes Handeln)","ex":"Hij hielp haar puur uit berekening, niet uit vriendschap.","exDe":"Er half ihr rein aus Berechnung, nicht aus Freundschaft."}],"usage":"Konkreter Rechenvorgang wie auch übertragen das eigennützige Kalkül ('uit berekening handelen').","genus":"de","plural":"berekeningen"},"lo9_commissie":{"lemma":"commissie","displayNl":"de commissie","pos":"substantief","meanings":[{"de":"der Ausschuss, das Komitee, die Kommission","ex":"De ingestelde commissie werd door Lorentz geleid.","exDe":"Der eingesetzte Ausschuss wurde von Lorentz geleitet."},{"de":"die Provision (Vergütung bei einem Geschäft)","ex":"De makelaar krijgt commissie over de verkoop van het huis.","exDe":"Der Makler bekommt eine Provision auf den Verkauf des Hauses."}],"usage":"Formell/institutionell für ein Gremium; im Handel auch 'Provision'.","genus":"de","plural":"commissies"},"lo10_staatsbegrafenis":{"lemma":"staatsbegrafenis","displayNl":"de staatsbegrafenis","pos":"substantief","meanings":[{"de":"das Staatsbegräbnis, das Staatsbegängnis","ex":"Als hij minder bescheiden was geweest, zou de staatsbegrafenis hem verbaasd hebben.","exDe":"Wäre er weniger bescheiden gewesen, hätte ihn das Staatsbegräbnis verwundert."}],"usage":"Offizielles, vom Staat ausgerichtetes Begräbnis für eine bedeutende Persönlichkeit.","genus":"de","plural":"staatsbegrafenissen","illustratable":true},"lo10_grafrede":{"lemma":"grafrede","displayNl":"de grafrede","pos":"substantief","meanings":[{"de":"die Grabrede, die Trauerrede, der Nachruf","ex":"Einstein zou nooit een ontroerender grafrede hebben gehouden.","exDe":"Einstein hätte nie eine bewegendere Grabrede gehalten."}],"usage":"Rede, die am Grab bei einer Beerdigung gehalten wird; auch Plural 'grafreden'.","genus":"de","plural":"grafredes","illustratable":true},"lo10_wijze":{"lemma":"wijze","displayNl":"de wijze","pos":"substantief","meanings":[{"de":"der/die Weise, der Weise (weiser Mensch)","ex":"Men zou hem terecht een wijze van de natuurkunde kunnen noemen.","exDe":"Man könnte ihn zu Recht einen Weisen der Physik nennen."},{"de":"die Art und Weise, die Weise (Art des Vorgehens)","ex":"Op deze wijze los je het probleem het snelst op.","exDe":"Auf diese Weise löst du das Problem am schnellsten."}],"usage":"Homonym: 'der Weise' (kluger Mensch) und 'die Art und Weise' (meist in Wendungen wie 'op deze wijze'). Der artPrompt illustriert die Bedeutung 'weiser Mensch'.","genus":"de","plural":"wijzen","illustratable":true},"lo10_bescheidenheid":{"lemma":"bescheidenheid","displayNl":"de bescheidenheid","pos":"substantief","meanings":[{"de":"die Bescheidenheit, die Zurückhaltung","ex":"Zijn bescheidenheid zou tegenwoordig zeldzaam zijn.","exDe":"Seine Bescheidenheit wäre heutzutage selten."}],"usage":"Abstrakte Charaktereigenschaft; meist ohne Plural.","genus":"de"},"lo10_voorbeeld":{"lemma":"voorbeeld","displayNl":"het voorbeeld","pos":"substantief","meanings":[{"de":"das Beispiel","ex":"Kun je een voorbeeld geven van dit woord?","exDe":"Kannst du ein Beispiel für dieses Wort geben?"},{"de":"das Vorbild","ex":"Als jong onderzoeker zou men zich aan zijn voorbeeld kunnen spiegelen.","exDe":"Als junger Forscher könnte man sich an seinem Vorbild orientieren."}],"usage":"Zwei Bedeutungen je nach Kontext: 'Beispiel' (Illustration) und 'Vorbild' (nachahmenswerte Person). Häufig in 'bijvoorbeeld' = zum Beispiel.","genus":"het","plural":"voorbeelden"},"lo10_aanzien":{"lemma":"aanzien","displayNl":"het aanzien","pos":"substantief","meanings":[{"de":"das Ansehen, das Renommee, der Ruf","ex":"Zijn aanzien zou zonder zijn helderheid nooit zo groot zijn geweest.","exDe":"Sein Ansehen wäre ohne seine Klarheit nie so groß gewesen."},{"de":"der Anblick, das Äußere (das Aussehen)","ex":"Het dorp heeft door de nieuwbouw een ander aanzien gekregen.","exDe":"Das Dorf hat durch die Neubauten ein anderes Aussehen bekommen."}],"usage":"Abstraktes Substantiv 'Ansehen/Ruf'; auch 'Anblick'. Häufig in der Wendung 'ten aanzien van' (bezüglich).","genus":"het"},"lo10_erfenis":{"lemma":"erfenis","displayNl":"de erfenis","pos":"substantief","meanings":[{"de":"das Erbe, die Erbschaft (das Vererbte)","ex":"Na de dood van zijn oom ontving hij een grote erfenis.","exDe":"Nach dem Tod seines Onkels erhielt er eine große Erbschaft."},{"de":"das Vermächtnis, das Erbe (übertragen)","ex":"Zijn wetenschappelijke erfenis zou generaties blijven inspireren.","exDe":"Sein wissenschaftliches Erbe würde Generationen weiter inspirieren."}],"usage":"Konkrete Erbschaft (Geld/Besitz) und übertragen ein geistiges/kulturelles Vermächtnis. Roh-Eintrag 'de wetenschappelijke erfenis' auf das Lemma 'erfenis' reduziert.","genus":"de","plural":"erfenissen"},"ze1_noorderlicht":{"lemma":"noorderlicht","displayNl":"het noorderlicht","pos":"substantief","meanings":[{"de":"das Nordlicht, Polarlicht","ex":"Aan de donkere hemel danste het noorderlicht in groene golven.","exDe":"Am dunklen Himmel tanzte das Nordlicht in grünen Wellen."}],"usage":"Naturphaenomen (Aurora borealis); meist im Singular gebraucht.","genus":"het","plural":"noorderlichten","illustratable":true},"ze1_dominee":{"lemma":"dominee","displayNl":"de dominee","pos":"substantief","meanings":[{"de":"der (protestantische) Pfarrer, Pastor","ex":"De dominee beklom de kansel en opende de dienst.","exDe":"Der Pfarrer bestieg die Kanzel und eroeffnete den Gottesdienst."}],"usage":"Protestantischer Geistlicher; Anrede/Titel im niederlaendischen Kontext.","genus":"de","plural":"dominees","illustratable":true},"ze1_hemel":{"lemma":"hemel","displayNl":"de hemel","pos":"substantief","meanings":[{"de":"der Himmel (am Firmament, Wetterhimmel)","ex":"Aan de blauwe hemel dreef geen enkele wolk.","exDe":"Am blauen Himmel trieb keine einzige Wolke."},{"de":"der Himmel (religioes, Jenseits)","ex":"Volgens de dominee wachtte de hemel op de rechtvaardigen.","exDe":"Laut dem Pfarrer wartete der Himmel auf die Gerechten."},{"de":"der Baldachin, Betthimmel (ueber einem Bett)","ex":"Boven het antieke bed hing een zware fluwelen hemel.","exDe":"Ueber dem antiken Bett hing ein schwerer samtener Betthimmel."}],"usage":"Firmament, religioeses Jenseits, auch Betthimmel; Plural 'hemelen' meist im religioesen/gehobenen Kontext.","genus":"de","plural":"hemelen","illustratable":true},"ze1_afkomst":{"lemma":"afkomst","displayNl":"de afkomst","pos":"substantief","meanings":[{"de":"die Herkunft, Abstammung","ex":"Zijn nederige afkomst weerhield hem niet van een grote loopbaan.","exDe":"Seine bescheidene Herkunft hielt ihn nicht von einer grossen Laufbahn ab."}],"usage":"Abstrakt: soziale/geografische Herkunft, Abstammung; meist ohne Plural.","genus":"de"},"ze2_assistent":{"lemma":"assistent","displayNl":"de assistent","pos":"substantief","meanings":[{"de":"der Assistent, Gehilfe","ex":"De assistent reikte de professor de reageerbuis aan.","exDe":"Der Assistent reichte dem Professor das Reagenzglas an."}],"usage":"Person, die jemandem beruflich zuarbeitet; weibliche Form: assistente.","genus":"de","plural":"assistenten","illustratable":true},"ze2_leermeester":{"lemma":"leermeester","displayNl":"de leermeester","pos":"substantief","meanings":[{"de":"der Lehrmeister, Mentor","ex":"Lorentz was voor de jonge Zeeman een strenge maar liefdevolle leermeester.","exDe":"Lorentz war für den jungen Zeeman ein strenger, aber liebevoller Lehrmeister."}],"usage":"Person, die einen Schueler/Lehrling anleitet; oft im Sinne von Mentor.","genus":"de","plural":"leermeesters","illustratable":true},"ze2_theorie":{"lemma":"theorie","displayNl":"de theorie","pos":"substantief","meanings":[{"de":"die Theorie (wissenschaftliches Erklaerungsmodell)","ex":"De elektronentheorie werd door Lorentz zorgvuldig uitgewerkt.","exDe":"Die Elektronentheorie wurde von Lorentz sorgfaeltig ausgearbeitet."},{"de":"die Theorie (Gegensatz zur Praxis, blosse Annahme)","ex":"In theorie klopt het plan, maar in de praktijk faalt het.","exDe":"In der Theorie stimmt der Plan, aber in der Praxis scheitert er."}],"usage":"Abstrakt: wissenschaftliches Modell oder blosse Annahme; Plural 'theorieen'.","genus":"de","plural":"theorieen"},"ze2_laboratorium":{"lemma":"laboratorium","displayNl":"het laboratorium","pos":"substantief","meanings":[{"de":"das Labor, Laboratorium","ex":"In het laboratorium te Leiden werd baanbrekend onderzoek verricht.","exDe":"Im Labor in Leiden wurde bahnbrechende Forschung betrieben."}],"usage":"Raum für wissenschaftliche Versuche; Plural 'laboratoria', kurz auch 'lab'.","genus":"het","plural":"laboratoria","illustratable":true},"ze2_promotie":{"lemma":"promotie","displayNl":"de promotie","pos":"substantief","meanings":[{"de":"Promotion (Erlangung des Doktorgrades)","ex":"Zijn promotie werd met lof beoordeeld.","exDe":"Seine Promotion wurde mit Auszeichnung bewertet."},{"de":"Beförderung (im Beruf)","ex":"Na jaren hard werken kreeg zij een promotie.","exDe":"Nach Jahren harter Arbeit bekam sie eine Beförderung."},{"de":"Werbeaktion, Verkaufsförderung","ex":"De winkel had een promotie op alle zomerkleding.","exDe":"Der Laden hatte eine Werbeaktion auf alle Sommerkleidung."},{"de":"Aufstieg (Sport, in eine höhere Liga)","ex":"De club vierde de promotie naar de eredivisie.","exDe":"Der Verein feierte den Aufstieg in die erste Liga."}],"usage":"Stark polysem: je nach Kontext Doktor-Promotion, berufliche Beförderung, Werbeaktion oder sportlicher Aufstieg.","genus":"de","plural":"promoties"},"ze3_magneetveld":{"lemma":"magneetveld","displayNl":"het magneetveld","pos":"substantief","meanings":[{"de":"Magnetfeld","ex":"Het magneetveld dat hij opwekte, was buitengewoon sterk.","exDe":"Das Magnetfeld, das er erzeugte, war außergewöhnlich stark."}],"usage":"Physikalischer Fachbegriff; auch Zusammensetzungen wie 'aardmagneetveld' (Erdmagnetfeld).","genus":"het","plural":"magneetvelden"},"ze3_lichtbron":{"lemma":"lichtbron","displayNl":"de lichtbron","pos":"substantief","meanings":[{"de":"Lichtquelle","ex":"De lichtbron die hij gebruikte, bestond uit gloeiend natrium.","exDe":"Die Lichtquelle, die er verwendete, bestand aus glühendem Natrium."}],"usage":"Jede Quelle von Licht, natürlich (Sonne) oder künstlich (Lampe); auch übertragen in Technik/Optik.","genus":"de","plural":"lichtbronnen","illustratable":true},"ze3_natriumlicht":{"lemma":"natriumlicht","displayNl":"het natriumlicht","pos":"substantief","meanings":[{"de":"Natriumlicht (das charakteristische gelbe Licht von Natriumdampf)","ex":"Het natriumlicht, dat helder geel is, leende zich goed voor de proef.","exDe":"Das Natriumlicht, das hell gelb ist, eignete sich gut für den Versuch."}],"usage":"Fachbegriff aus Physik/Beleuchtung; charakteristisches monochrom-gelbes Licht, meist als Stoffbezeichnung ohne Plural.","genus":"het"},"ze3_elektromagneet":{"lemma":"elektromagneet","displayNl":"de elektromagneet","pos":"substantief","meanings":[{"de":"Elektromagnet","ex":"De elektromagneet waarmee hij werkte, woog honderden kilo's.","exDe":"Der Elektromagnet, mit dem er arbeitete, wog hunderte Kilo."}],"usage":"Technisch: Magnet, dessen Feld durch elektrischen Strom in einer Spule erzeugt wird.","genus":"de","plural":"elektromagneten","illustratable":true},"ze3_proef":{"lemma":"proef","displayNl":"de proef","pos":"substantief","meanings":[{"de":"Versuch, Experiment","ex":"De proef die hij ondernam, was hem verboden.","exDe":"Der Versuch, den er unternahm, war ihm verboten."},{"de":"Probe, Test (Prüfung der Eignung/Qualität)","ex":"We namen een proef om te zien of het recept klopte.","exDe":"Wir machten eine Probe, um zu sehen, ob das Rezept stimmte."},{"de":"Prüfung, Probestück (z. B. Meisterprüfung)","ex":"Hij legde de proef met succes af.","exDe":"Er legte die Prüfung erfolgreich ab."}],"usage":"Kern: Versuch/Experiment; auch Probe/Test und Prüfung. Redewendung 'op de proef stellen' = auf die Probe stellen.","genus":"de","plural":"proeven"},"ze3_vlam":{"lemma":"vlam","displayNl":"de vlam","pos":"substantief","meanings":[{"de":"Flamme","ex":"De vlam waarin hij het natrium bracht, kleurde fel geel.","exDe":"Die Flamme, in die er das Natrium brachte, färbte sich grell gelb."},{"de":"Flamme (bildlich: geliebte Person, Schwarm)","ex":"Zij was zijn oude vlam uit de studietijd.","exDe":"Sie war seine alte Flamme aus der Studienzeit."}],"usage":"Wörtlich das Feuer; bildlich auch 'alte Flamme' (früherer Schwarm). Redewendung 'in vlam staan/vliegen' = in Flammen stehen/aufgehen.","genus":"de","plural":"vlammen","illustratable":true},"ze3_volharding":{"lemma":"volharding","displayNl":"de volharding","pos":"substantief","meanings":[{"de":"Beharrlichkeit, Ausdauer","ex":"Het was zijn volharding die het verbod overwon.","exDe":"Es war seine Beharrlichkeit, die das Verbot überwand."},{"de":"Hartnäckigkeit, Durchhaltevermögen","ex":"Met grote volharding werkte ze aan haar doel.","exDe":"Mit großer Hartnäckigkeit arbeitete sie an ihrem Ziel."}],"usage":"Abstrakt: das Durchhalten und Festhalten an einem Ziel; zum Verb 'volharden' (beharren). Meist ohne Plural.","genus":"de"},"ze4_spectroscoop":{"lemma":"spectroscoop","displayNl":"de spectroscoop","pos":"substantief","meanings":[{"de":"das Spektroskop","ex":"Omdat hij door de spectroscoop keek, kon hij het licht ontleden.","exDe":"Weil er durch das Spektroskop schaute, konnte er das Licht zerlegen."}],"usage":"Optisches Instrument zur Zerlegung von Licht in sein Spektrum; Fachbegriff aus Physik/Chemie.","genus":"de","plural":"spectroscopen","illustratable":true},"ze4_verbreding":{"lemma":"verbreding","displayNl":"de verbreding","pos":"substantief","meanings":[{"de":"die Verbreiterung, das Breiterwerden","ex":"Aanvankelijk leek het slechts een verbreding van de lijn te zijn.","exDe":"Zunächst schien es nur eine Verbreiterung der Linie zu sein."},{"de":"die verbreiterte Stelle, der Ausbau (z. B. einer Straße)","ex":"De verbreding van de weg zorgt voor minder files.","exDe":"Die Verbreiterung der Straße sorgt für weniger Staus."}],"usage":"Nomen zu 'verbreden' (breiter machen/werden); sowohl der Vorgang als auch das Ergebnis.","genus":"de","plural":"verbredingen"},"ze4_effect":{"lemma":"effect","displayNl":"het effect","pos":"substantief","meanings":[{"de":"der Effekt, die Wirkung","ex":"Het effect dat hij ontdekte, zou naar hem worden vernoemd.","exDe":"Der Effekt, den er entdeckte, sollte nach ihm benannt werden."},{"de":"der Effet, der Drall (bei einem Ball)","ex":"Met veel effect krulde de bal om de muur heen.","exDe":"Mit viel Effet kurvte der Ball um die Mauer herum."},{"de":"das Wertpapier (meist Plural: effecten)","ex":"Hij belegde zijn spaargeld in effecten.","exDe":"Er legte sein Erspartes in Wertpapieren an."}],"usage":"Grundbedeutung Wirkung/Effekt; im Plural 'effecten' auch Wertpapiere.","genus":"het","plural":"effecten"},"ze4_component":{"lemma":"component","displayNl":"de component","pos":"substantief","meanings":[{"de":"die Komponente, der Bestandteil","ex":"Elke component die ontstond, had een iets andere golflengte.","exDe":"Jede Komponente, die entstand, hatte eine etwas andere Wellenlänge."}],"usage":"Bestandteil eines Ganzen; auch technisch (Bauteil) und in der Physik (Vektorkomponente). Meist 'de component'.","genus":"de","plural":"componenten"},"ze5_polarisatie":{"lemma":"polarisatie","displayNl":"de polarisatie","pos":"substantief","meanings":[{"de":"die Polarisation (Physik, von Licht/Wellen)","ex":"De polarisatie van het licht bevestigde Lorentz' voorspelling.","exDe":"Die Polarisation des Lichts bestätigte Lorentz' Voraussage."},{"de":"die Polarisierung, Spaltung (einer Gesellschaft/Debatte)","ex":"De toenemende polarisatie verhardt het politieke debat.","exDe":"Die zunehmende Polarisierung verhärtet die politische Debatte."}],"usage":"Fachbegriff aus der Physik; übertragen für gesellschaftliche/politische Spaltung.","genus":"de","plural":"polarisaties"},"ze5_verhouding":{"lemma":"verhouding","displayNl":"de verhouding","pos":"substantief","meanings":[{"de":"das Verhältnis, die Proportion (rechnerisch)","ex":"Men zou de verhouding tussen lading en massa kunnen berekenen.","exDe":"Man könnte das Verhältnis zwischen Ladung und Masse berechnen."},{"de":"die Beziehung, das (zwischenmenschliche) Verhältnis","ex":"Ze hebben een goede verhouding met hun buren.","exDe":"Sie haben ein gutes Verhältnis zu ihren Nachbarn."},{"de":"die Affäre, das Liebesverhältnis","ex":"Hij had jarenlang een geheime verhouding.","exDe":"Er hatte jahrelang eine heimliche Affäre."}],"usage":"Von rechnerischer Proportion über soziale Beziehung bis zur Liebesaffäre; sehr polysem.","genus":"de","plural":"verhoudingen"},"ze6_onderscheiding":{"lemma":"onderscheiding","displayNl":"de onderscheiding","pos":"substantief","meanings":[{"de":"die Auszeichnung, der Orden","ex":"De aan beiden verleende onderscheiding werd met trots ontvangen.","exDe":"Die beiden verliehene Auszeichnung wurde mit Stolz empfangen."},{"de":"die Unterscheidung, das Unterscheiden","ex":"De onderscheiding tussen feit en mening is soms lastig.","exDe":"Die Unterscheidung zwischen Tatsache und Meinung ist manchmal schwierig."}],"usage":"Konkret ein verliehener Orden/eine Ehrung; abstrakt das Unterscheiden zweier Dinge.","genus":"de","plural":"onderscheidingen"},"ze6_straling":{"lemma":"straling","displayNl":"de straling","pos":"substantief","meanings":[{"de":"die Strahlung (Physik)","ex":"De door magnetisme beïnvloede straling stond centraal in hun werk.","exDe":"Die durch Magnetismus beeinflusste Strahlung stand im Zentrum ihrer Arbeit."},{"de":"die Ausstrahlung, das Charisma","ex":"Ze heeft een warme, positieve straling.","exDe":"Sie hat eine warme, positive Ausstrahlung."}],"usage":"Physikalisch die Strahlung; übertragen die persönliche Ausstrahlung/das Charisma.","genus":"de","plural":"stralingen"},"ze6_eer":{"lemma":"eer","displayNl":"de eer","pos":"substantief","meanings":[{"de":"die Ehre","ex":"Het is een grote eer om hier te mogen spreken.","exDe":"Es ist eine große Ehre, hier sprechen zu dürfen."},{"de":"das Ansehen; der gute Ruf","ex":"Hij deed alles om de eer van zijn familie te beschermen.","exDe":"Er tat alles, um das Ansehen seiner Familie zu schützen."}],"usage":"Meist unzählbar; feste Wendungen: 'ter ere van' (zu Ehren von), 'in ere houden', 'eer bewijzen'. Nicht mit dem gleichlautenden veralteten Bindewort 'eer' (= voordat) verwechseln.","genus":"de"},"ze6_erkenning":{"lemma":"erkenning","displayNl":"de erkenning","pos":"substantief","meanings":[{"de":"die Anerkennung (Würdigung von Leistung/Verdienst)","ex":"Na jaren werk kreeg zij eindelijk de erkenning die ze verdiende.","exDe":"Nach Jahren Arbeit bekam sie endlich die Anerkennung, die sie verdiente."},{"de":"die Anerkennung (offizielle/rechtliche Anerkennung)","ex":"De erkenning van het nieuwe land liet lang op zich wachten.","exDe":"Die Anerkennung des neuen Landes ließ lange auf sich warten."}],"usage":"Abstraktes Substantiv, oft mit 'van' + Objekt; verwandtes Verb: 'erkennen'.","genus":"de","plural":"erkenningen"},"ze6_natie":{"lemma":"natie","displayNl":"de natie","pos":"substantief","meanings":[{"de":"die Nation","ex":"Nederland is een kleine maar welvarende natie.","exDe":"Die Niederlande sind eine kleine, aber wohlhabende Nation."},{"de":"das Volk; die Nationalgemeinschaft","ex":"De hele natie rouwde om het verlies.","exDe":"Die ganze Nation trauerte um den Verlust."}],"usage":"Abstrakter Kollektivbegriff; ähnlich, aber nicht identisch mit 'land' (Staat/Gebiet) und 'volk'.","genus":"de","plural":"naties"},"ze6_prestatie":{"lemma":"prestatie","displayNl":"de prestatie","pos":"substantief","meanings":[{"de":"die Leistung (erbrachtes Ergebnis)","ex":"Het winnen van de marathon was een indrukwekkende prestatie.","exDe":"Der Sieg beim Marathon war eine beeindruckende Leistung."},{"de":"die Leistung; die Performance (eines Systems/Geräts)","ex":"De prestatie van de nieuwe motor overtrof alle verwachtingen.","exDe":"Die Leistung des neuen Motors übertraf alle Erwartungen."}],"usage":"Verwandtes Verb: 'presteren'. Feste Wendung: 'een prestatie leveren'.","genus":"de","plural":"prestaties"},"ze7_spectroscopie":{"lemma":"spectroscopie","displayNl":"de spectroscopie","pos":"substantief","meanings":[{"de":"die Spektroskopie","ex":"Met spectroscopie kun je de samenstelling van sterren bepalen.","exDe":"Mit Spektroskopie kann man die Zusammensetzung von Sternen bestimmen."}],"usage":"Fachbegriff aus Physik/Chemie; praktisch unzählbar (kein üblicher Plural).","genus":"de"},"ze7_verfijning":{"lemma":"verfijning","displayNl":"de verfijning","pos":"substantief","meanings":[{"de":"die Verfeinerung (das Verbessern/Präzisieren)","ex":"De verfijning van het recept kostte hem maanden.","exDe":"Die Verfeinerung des Rezepts kostete ihn Monate."},{"de":"die Feinheit; die Raffinesse (Eleganz, feiner Geschmack)","ex":"Haar kleding straalde een zekere verfijning uit.","exDe":"Ihre Kleidung strahlte eine gewisse Raffinesse aus."}],"usage":"Verwandtes Verb: 'verfijnen'. In der ersten Bedeutung oft mit 'van' + Objekt.","genus":"de","plural":"verfijningen"},"ze7_gevoeligheid":{"lemma":"gevoeligheid","displayNl":"de gevoeligheid","pos":"substantief","meanings":[{"de":"die Empfindlichkeit (technische/messbare Sensitivität)","ex":"De gevoeligheid van de sensor bepaalt hoe kleine signalen hij oppikt.","exDe":"Die Empfindlichkeit des Sensors bestimmt, wie kleine Signale er aufnimmt."},{"de":"die Sensibilität; die Feinfühligkeit (einer Person)","ex":"Zijn grote gevoeligheid maakte hem een goede luisteraar.","exDe":"Seine große Sensibilität machte ihn zu einem guten Zuhörer."},{"de":"die Anfälligkeit; die Empfindlichkeit (für etwas)","ex":"Haar gevoeligheid voor kritiek maakte gesprekken lastig.","exDe":"Ihre Empfindlichkeit gegenüber Kritik machte Gespräche schwierig."}],"usage":"Verwandtes Adjektiv: 'gevoelig'. Bedeutung 3 oft mit 'voor' + Objekt.","genus":"de","plural":"gevoeligheden"},"ze7_verstoring":{"lemma":"verstoring","displayNl":"de verstoring","pos":"substantief","meanings":[{"de":"die Störung (Unterbrechung/Beeinträchtigung)","ex":"Een kleine verstoring in het netwerk legde alles plat.","exDe":"Eine kleine Störung im Netzwerk legte alles lahm."},{"de":"die Störung; das Aus-dem-Gleichgewicht-Bringen","ex":"De bouw veroorzaakte een verstoring van het natuurlijke evenwicht.","exDe":"Der Bau verursachte eine Störung des natürlichen Gleichgewichts."}],"usage":"Verwandtes Verb: 'verstoren'. Oft mit 'van' + Objekt.","genus":"de","plural":"verstoringen"},"ze7_meetopstelling":{"lemma":"meetopstelling","displayNl":"de meetopstelling","pos":"substantief","meanings":[{"de":"der Messaufbau, die Messanordnung","ex":"De verbetering van de meetopstelling kostte hem jaren.","exDe":"Die Verbesserung des Messaufbaus kostete ihn Jahre."},{"de":"die Versuchsanordnung (im Labor)","ex":"De meetopstelling in het laboratorium was uiterst precies afgesteld.","exDe":"Die Versuchsanordnung im Labor war äußerst präzise justiert."}],"usage":"Technischer Fachbegriff aus Physik/Labor: die konkrete Anordnung von Geräten für eine Messung. Zusammensetzung aus meten (messen) + opstelling (Aufstellung/Anordnung).","genus":"de","plural":"meetopstellingen"},"ze8_zonnevlek":{"lemma":"zonnevlek","displayNl":"de zonnevlek","pos":"substantief","meanings":[{"de":"der Sonnenfleck","ex":"De spectraalanalyse toont aan dat elke zonnevlek een sterk magneetveld bezit.","exDe":"Die Spektralanalyse zeigt, dass jeder Sonnenfleck ein starkes Magnetfeld besitzt."}],"usage":"Astronomischer Fachbegriff: dunklere, kühlere Stelle auf der Sonnenoberfläche mit starkem Magnetfeld. Zusammensetzung zon (Sonne) + vlek (Fleck).","genus":"de","plural":"zonnevlekken","illustratable":true},"ze8_astrofysica":{"lemma":"astrofysica","displayNl":"de astrofysica","pos":"substantief","meanings":[{"de":"die Astrophysik","ex":"In de astrofysica geldt het zeeman-effect als onmisbaar instrument.","exDe":"In der Astrophysik gilt der Zeeman-Effekt als unentbehrliches Instrument."}],"usage":"Wissenschaftsname, meist ohne Plural. Teilgebiet der Astronomie, das physikalische Eigenschaften von Himmelskörpern untersucht.","genus":"de"},"ze8_frequentie":{"lemma":"frequentie","displayNl":"de frequentie","pos":"substantief","meanings":[{"de":"die Frequenz (Schwingungen/Wellen pro Zeiteinheit)","ex":"Uit de verschuiving van de frequentie leidt men de veldsterkte af.","exDe":"Aus der Verschiebung der Frequenz leitet man die Feldstärke ab."},{"de":"die Häufigkeit (wie oft etwas vorkommt)","ex":"De frequentie van de treinen is in de spits veel hoger.","exDe":"Die Frequenz der Züge ist zur Hauptverkehrszeit viel höher."},{"de":"der (Funk-/Sende-)Frequenzbereich","ex":"De zender is op een nieuwe frequentie te ontvangen.","exDe":"Der Sender ist auf einer neuen Frequenz zu empfangen."}],"usage":"Fachbegriff (Physik) und allgemeinsprachlich. Physikalisch: Anzahl der Schwingungen pro Zeiteinheit; allgemein: Häufigkeit des Auftretens.","genus":"de","plural":"frequenties"},"ze8_emissie":{"lemma":"emissie","displayNl":"de emissie","pos":"substantief","meanings":[{"de":"die Emission, die Aussendung (von Licht/Strahlung)","ex":"De emissie van de zon vertoont duidelijk gesplitste lijnen.","exDe":"Die Emission der Sonne zeigt deutlich aufgespaltene Linien."},{"de":"der Ausstoß (von Abgasen/Schadstoffen)","ex":"De nieuwe fabriek moet de emissie van CO2 flink terugdringen.","exDe":"Die neue Fabrik muss den Ausstoß von CO2 deutlich verringern."},{"de":"die Emission, die Ausgabe (von Aktien/Anleihen)","ex":"De emissie van nieuwe aandelen bracht veel kapitaal binnen.","exDe":"Die Emission neuer Aktien brachte viel Kapital ein."}],"usage":"Fachbegriff mit mehreren Domänen: Physik (Aussendung von Strahlung), Umwelt (Ausstoß von Stoffen), Finanzwesen (Ausgabe von Wertpapieren).","genus":"de","plural":"emissies"},"ze8_veldsterkte":{"lemma":"veldsterkte","displayNl":"de veldsterkte","pos":"substantief","meanings":[{"de":"die Feldstärke","ex":"De veldsterkte wordt uit de mate van splitsing berekend.","exDe":"Die Feldstärke wird aus dem Maß der Aufspaltung berechnet."}],"usage":"Physikalischer Fachbegriff: Maß für die Stärke eines (elektrischen oder magnetischen) Feldes. Zusammensetzung veld (Feld) + sterkte (Stärke).","genus":"de","plural":"veldsterktes"},"ze8_hemellichaam":{"lemma":"hemellichaam","displayNl":"het hemellichaam","pos":"substantief","meanings":[{"de":"der Himmelskörper","ex":"Van geen enkel hemellichaam is directe meting mogelijk.","exDe":"Von keinem Himmelskörper ist eine direkte Messung möglich."}],"usage":"Astronomischer Sammelbegriff für jeden natürlichen Körper im All (Stern, Planet, Mond, Komet usw.). Zusammensetzung hemel (Himmel) + lichaam (Körper). Genus het.","genus":"het","plural":"hemellichamen","illustratable":true},"ze8_analyse":{"lemma":"analyse","displayNl":"de analyse","pos":"substantief","meanings":[{"de":"die Analyse, die Untersuchung","ex":"De spectroscopische analyse onthult de magnetische structuur van de kosmos.","exDe":"Die spektroskopische Analyse enthüllt die magnetische Struktur des Kosmos."},{"de":"die Auswertung, die Betrachtung (z. B. von Daten/einer Lage)","ex":"Zijn analyse van de situatie bleek volledig juist.","exDe":"Seine Analyse der Situation erwies sich als völlig richtig."},{"de":"die (chemische/medizinische) Probe-Untersuchung","ex":"De analyse van het bloedmonster duurde twee dagen.","exDe":"Die Analyse der Blutprobe dauerte zwei Tage."}],"usage":"Allgemein und fachsprachlich verwendbar: die systematische Untersuchung/Zerlegung von etwas in seine Bestandteile (Wissenschaft, Chemie, Sprache, Daten).","genus":"de","plural":"analyses"},"ze9_isolement":{"lemma":"isolement","displayNl":"het isolement","pos":"substantief","meanings":[{"de":"die Isolation, die Abgeschiedenheit","ex":"De oorlog heeft veel geleerden in isolement gedreven.","exDe":"Der Krieg hat viele Gelehrte in die Isolation getrieben."},{"de":"die Isolierung (technisch, z. B. gegen Kälte/Strom)","ex":"Het isolement van de leidingen voorkomt warmteverlies.","exDe":"Die Isolierung der Leitungen verhindert Wärmeverlust."}],"usage":"Abstraktes Neutrum; im Sinne von Vereinzelung meist 'in isolement (geraken/leven)'.","genus":"het","plural":"isolementen"},"ze9_uitwisseling":{"lemma":"uitwisseling","displayNl":"de uitwisseling","pos":"substantief","meanings":[{"de":"der Austausch (von Ideen, Waren, Informationen)","ex":"De vrije uitwisseling van ideeën is jarenlang belemmerd geweest.","exDe":"Der freie Austausch von Ideen ist jahrelang behindert gewesen."},{"de":"der (Schüler-/Studenten-)Austausch","ex":"Onze school organiseert elk jaar een uitwisseling met Duitsland.","exDe":"Unsere Schule organisiert jedes Jahr einen Austausch mit Deutschland."}],"usage":"Abstraktes de-Wort; oft 'uitwisseling van' + Substantiv.","genus":"de","plural":"uitwisselingen"},"ze9_gastonderzoeker":{"lemma":"gastonderzoeker","displayNl":"de gastonderzoeker","pos":"substantief","meanings":[{"de":"der Gastwissenschaftler, der Gastforscher","ex":"Talrijke gastonderzoekers hebben zijn laboratorium bezocht.","exDe":"Zahlreiche Gastwissenschaftler haben sein Labor besucht."}],"usage":"Personenbezeichnung; weibliche Form 'gastonderzoekster'.","genus":"de","plural":"gastonderzoekers","illustratable":true},"ze9_spanning":{"lemma":"spanning","displayNl":"de spanning","pos":"substantief","meanings":[{"de":"die Spannung (emotional, zwischenmenschlich, politisch)","ex":"De nationale spanningen hebben de wetenschap zwaar getroffen.","exDe":"Die nationalen Spannungen haben die Wissenschaft schwer getroffen."},{"de":"die (elektrische) Spannung","ex":"De spanning op dit stopcontact bedraagt 230 volt.","exDe":"Die Spannung an dieser Steckdose beträgt 230 Volt."},{"de":"die Spannung, der Nervenkitzel (Suspense)","ex":"De spanning in de laatste scène was om te snijden.","exDe":"Die Spannung in der letzten Szene war zum Schneiden."}],"usage":"de-Wort; polysem (Emotion, Physik, Suspense); Plural 'spanningen' v. a. für Konflikte.","genus":"de","plural":"spanningen"},"ze9_koninkrijk":{"lemma":"koninkrijk","displayNl":"het koninkrijk","pos":"substantief","meanings":[{"de":"das Königreich","ex":"Het koninkrijk is buiten het strijdgewoel gebleven.","exDe":"Das Königreich ist außerhalb des Kriegsgetümmels geblieben."}],"usage":"Neutrum; auch als Staatsname 'het Koninkrijk der Nederlanden'.","genus":"het","plural":"koninkrijken","illustratable":true},"ze9_wetenschap":{"lemma":"wetenschap","displayNl":"de wetenschap","pos":"substantief","meanings":[{"de":"die Wissenschaft","ex":"De wetenschap heeft onder de oorlog geleden als geen ander gebied.","exDe":"Die Wissenschaft hat unter dem Krieg gelitten wie kein anderes Gebiet."},{"de":"das Wissen, die Kenntnis (gehoben, oft 'naar mijn beste wetenschap')","ex":"Naar mijn beste wetenschap is het rapport nooit gepubliceerd.","exDe":"Nach meinem besten Wissen ist der Bericht nie veröffentlicht worden."}],"usage":"de-Wort; Plural 'wetenschappen' für einzelne Disziplinen (natuurwetenschappen).","genus":"de","plural":"wetenschappen"},"ze10_bezetting":{"lemma":"bezetting","displayNl":"de bezetting","pos":"substantief","meanings":[{"de":"die Besatzung (militärisch)","ex":"Hij stierf terwijl de bezetting het land in haar greep hield.","exDe":"Er starb, während die Besatzung das Land in ihrem Griff hielt."},{"de":"die Besetzung (Theater, Rollen, Ensemble)","ex":"De bezetting van deze opera is uitzonderlijk sterk.","exDe":"Die Besetzung dieser Oper ist außergewöhnlich stark."},{"de":"die Belegung, die Auslastung (Plätze, Betten)","ex":"De bezetting van het hotel was in juli honderd procent.","exDe":"Die Belegung des Hotels lag im Juli bei hundert Prozent."}],"usage":"de-Wort; polysem (Militär, Ensemble, Auslastung).","genus":"de","plural":"bezettingen"},"ze10_atoomfysica":{"lemma":"atoomfysica","displayNl":"de atoomfysica","pos":"substantief","meanings":[{"de":"die Atomphysik","ex":"Zowel de atoomfysica als de astrofysica maakt gebruik van zijn effect.","exDe":"Sowohl die Atomphysik als auch die Astrophysik nutzt seinen Effekt."}],"usage":"de-Wort; Fachgebiet, kein Plural (Stoffname).","genus":"de"},"ze10_grondslag":{"lemma":"grondslag","displayNl":"de grondslag","pos":"substantief","meanings":[{"de":"die Grundlage","ex":"Zijn werk vormt nog steeds de grondslag van de spectroscopie.","exDe":"Seine Arbeit bildet noch immer die Grundlage der Spektroskopie."},{"de":"das Fundament, die Basis","ex":"Wederzijds vertrouwen is de grondslag van elke samenwerking.","exDe":"Gegenseitiges Vertrauen ist das Fundament jeder Zusammenarbeit."},{"de":"der Beweggrund, die Prämisse","ex":"Op grondslag van deze cijfers nemen we een besluit.","exDe":"Auf Grundlage dieser Zahlen treffen wir eine Entscheidung."}],"usage":"Abstraktes Substantiv; oft in Wendungen wie 'op grondslag van' (auf Grundlage von) oder 'ten grondslag liggen aan' (zugrunde liegen).","genus":"de","plural":"grondslagen"},"ze10_verdrukking":{"lemma":"verdrukking","displayNl":"de verdrukking","pos":"substantief","meanings":[{"de":"die Unterdrückung","ex":"Het volk leed jarenlang onder de verdrukking van het regime.","exDe":"Das Volk litt jahrelang unter der Unterdrückung des Regimes."},{"de":"die Bedrängnis, die Not","ex":"Hij overleed in verdrukking, want de oorlog woedde nog volop.","exDe":"Er verstarb in Bedrängnis, denn der Krieg tobte noch in vollem Gange."}],"usage":"Abstraktes Substantiv; feste Wendung 'in de verdrukking komen/raken' = ins Hintertreffen geraten, unter Druck geraten.","genus":"de","plural":"verdrukkingen"},"ze10_toepassing":{"lemma":"toepassing","displayNl":"de toepassing","pos":"substantief","meanings":[{"de":"die Anwendung","ex":"De toepassing van zijn effect strekt zich uit tot de kernspintomografie.","exDe":"Die Anwendung seines Effekts erstreckt sich bis zur Kernspintomographie."},{"de":"der Einsatzbereich, das Einsatzgebiet","ex":"Deze technologie heeft veel praktische toepassingen.","exDe":"Diese Technologie hat viele praktische Einsatzgebiete."},{"de":"die Applikation (Software)","ex":"Op mijn telefoon staat een handige toepassing voor het weer.","exDe":"Auf meinem Handy ist eine praktische App fürs Wetter."}],"usage":"Abstrakt; feste Wendung 'van toepassing zijn (op)' = zutreffen / gelten (für).","genus":"de","plural":"toepassingen"},"ze10_fundament":{"lemma":"fundament","displayNl":"het fundament","pos":"substantief","meanings":[{"de":"das Fundament (eines Bauwerks)","ex":"De bouwvakkers gieten het fundament van het nieuwe huis.","exDe":"Die Bauarbeiter gießen das Fundament des neuen Hauses."},{"de":"das Fundament, die Grundlage (übertragen)","ex":"Het zeeman-effect behoort tot het fundament van de moderne fysica.","exDe":"Der Zeeman-Effekt gehört zum Fundament der modernen Physik."}],"usage":"Konkret (Bau-Fundament) und übertragen (Grundlage). Genus: het.","genus":"het","plural":"fundamenten","illustratable":true},"bk_1":{"lemma":"man","displayNl":"de man","pos":"substantief","meanings":[{"de":"der Mann","ex":"De man is aardig.","exDe":"Der Mann ist nett."},{"de":"der Ehemann, der Partner","ex":"Haar man werkt bij de gemeente.","exDe":"Ihr Mann arbeitet bei der Stadtverwaltung."},{"de":"der Kerl, jemand (unbestimmt)","ex":"Er stond een man bij de deur te wachten.","exDe":"An der Tür wartete ein Mann."}],"usage":"Alltagswort. Plural 'mannen'; in der Bedeutung 'pro Person' auch invariabel: 'met z'n tienen, tien man'.","genus":"de","plural":"mannen","illustratable":true},"bk_2":{"lemma":"vrouw","displayNl":"de vrouw","pos":"substantief","meanings":[{"de":"die Frau","ex":"De vrouw werkt hier.","exDe":"Die Frau arbeitet hier."},{"de":"die Ehefrau, die Partnerin","ex":"Zijn vrouw haalt de kinderen van school.","exDe":"Seine Frau holt die Kinder von der Schule ab."}],"usage":"Alltagswort. Plural 'vrouwen'. Diminutiv 'vrouwtje'.","genus":"de","plural":"vrouwen","illustratable":true},"bk_3":{"lemma":"kind","displayNl":"het kind","pos":"substantief","meanings":[{"de":"das Kind","ex":"Het kind speelt buiten.","exDe":"Das Kind spielt draußen."},{"de":"der Sohn / die Tochter (Nachkomme)","ex":"Ze hebben drie kinderen.","exDe":"Sie haben drei Kinder."}],"usage":"Unregelmäßiger Plural 'kinderen'. Diminutiv 'kindje'. Genus: het.","genus":"het","plural":"kinderen","illustratable":true},"bk_4":{"lemma":"moeder","displayNl":"de moeder","pos":"substantief","meanings":[{"de":"die Mutter","ex":"Mijn moeder kookt lekker.","exDe":"Meine Mutter kocht lecker."},{"de":"die Mama (liebevolle Anrede)","ex":"Moeder, mag ik nog een koekje?","exDe":"Mama, darf ich noch einen Keks?"}],"usage":"Plural 'moeders'. Diminutiv 'moedertje'. Familiäre Kurzform 'moe' / 'moes'.","genus":"de","plural":"moeders","illustratable":true},"bk_6":{"lemma":"ouder","displayNl":"de ouder","pos":"substantief","meanings":[{"de":"Elternteil","ex":"Elke ouder wil het beste voor zijn kind.","exDe":"Jeder Elternteil will das Beste für sein Kind."},{"de":"die Eltern (Plural)","ex":"Mijn ouders zijn thuis.","exDe":"Meine Eltern sind zu Hause."}],"usage":"Singular 'ouder' = ein Elternteil; im Plural 'ouders' meist im Sinne von 'die Eltern'. Nicht mit dem Adjektiv 'ouder' (älter) verwechseln.","genus":"de","plural":"ouders","illustratable":true},"bk_7":{"lemma":"zoon","displayNl":"de zoon","pos":"substantief","meanings":[{"de":"der Sohn","ex":"Hun zoon is tien jaar.","exDe":"Ihr Sohn ist zehn Jahre alt."}],"usage":"Plural 'zonen' (formeller) oder umgangssprachlich 'zoons'.","genus":"de","plural":"zonen","illustratable":true},"bk_8":{"lemma":"dochter","displayNl":"de dochter","pos":"substantief","meanings":[{"de":"die Tochter","ex":"Onze dochter gaat naar school.","exDe":"Unsere Tochter geht zur Schule."}],"usage":"Plural 'dochters'.","genus":"de","plural":"dochters","illustratable":true},"bk_9":{"lemma":"broer","displayNl":"de broer","pos":"substantief","meanings":[{"de":"der Bruder","ex":"Mijn broer is ouder.","exDe":"Mein Bruder ist älter."}],"usage":"Plural 'broers'.","genus":"de","plural":"broers","illustratable":true},"bk_10":{"lemma":"zus","displayNl":"de zus","pos":"substantief","meanings":[{"de":"die Schwester","ex":"Mijn zus heet Anna.","exDe":"Meine Schwester heißt Anna."}],"usage":"Umgangssprachlich üblich; formeller 'zuster'. Plural 'zussen'.","genus":"de","plural":"zussen","illustratable":true},"bk_11":{"lemma":"opa","displayNl":"de opa","pos":"substantief","meanings":[{"de":"der Opa, der Großvater","ex":"Opa woont in de stad.","exDe":"Opa wohnt in der Stadt."}],"usage":"Vertraulich für 'grootvader'. Plural 'opa's' (mit Apostroph-s).","genus":"de","plural":"opa's","illustratable":true},"bk_12":{"lemma":"oma","displayNl":"de oma","pos":"substantief","meanings":[{"de":"die Oma, die Großmutter","ex":"Oma bakt een taart.","exDe":"Oma backt einen Kuchen."}],"usage":"Vertraulich für 'grootmoeder'. Plural 'oma's' (mit Apostroph-s).","genus":"de","plural":"oma's","illustratable":true},"bk_13":{"lemma":"familie","displayNl":"de familie","pos":"substantief","meanings":[{"de":"die Familie (Verwandtschaft)","ex":"Mijn familie is groot.","exDe":"Meine Familie ist groß."},{"de":"die Familie (biologische Klassifikationsgruppe)","ex":"De kat behoort tot de familie van de katachtigen.","exDe":"Die Katze gehört zur Familie der Katzenartigen."}],"usage":"'familie' meint im Niederländischen oft die weitere Verwandtschaft; der engere Haushalt heißt 'gezin'. Plural 'families'.","genus":"de","plural":"families","illustratable":true},"bk_255":{"lemma":"rok","displayNl":"de rok","pos":"substantief","meanings":[{"de":"der Rock (Kleidungsstück)","ex":"De rok is te kort.","exDe":"Der Rock ist zu kurz."},{"de":"der Frack, das Rockschoß (formeller Herrenrock, formell/veraltet)","ex":"De ober droeg een zwarte rok.","exDe":"Der Kellner trug einen schwarzen Frack."}],"usage":"Alltagsnah für den Damenrock; 'rok' als Herren-Frack ist gehoben/veraltet.","genus":"de","plural":"rokken","illustratable":true},"bk_256":{"lemma":"jeans","displayNl":"de jeans","pos":"substantief","meanings":[{"de":"die Jeans, die Jeanshose","ex":"Mijn jeans is blauw.","exDe":"Meine Jeans ist blau."},{"de":"der Jeansstoff, das Jeans-Material (Denim)","ex":"Deze tas is van jeans gemaakt.","exDe":"Diese Tasche ist aus Jeans(stoff) gemacht."}],"usage":"'de jeans' ist im Singular gebräuchlich; der Plural bleibt formgleich 'jeans'.","genus":"de","plural":"jeans","illustratable":true},"bk_257":{"lemma":"T-shirt","displayNl":"het T-shirt","pos":"substantief","meanings":[{"de":"das T-Shirt","ex":"Dit T-shirt is groot.","exDe":"Dieses T-Shirt ist groß."}],"usage":"Neutrum: 'het T-shirt'; Plural mit -s.","genus":"het","plural":"T-shirts","illustratable":true},"bk_258":{"lemma":"bruin","displayNl":"bruin","pos":"adjectief","meanings":[{"de":"braun (Farbe)","ex":"De schönen zijn bruin.","exDe":"Die Schuhe sind braun."},{"de":"braun gebrannt, gebräunt (von der Sonne)","ex":"Na de vakantie was ze mooi bruin.","exDe":"Nach dem Urlaub war sie schön braun (gebräunt)."}],"usage":"Farbadjektiv; attributiv oft 'bruine' (de bruine schönen), bei het-Wort unflektiert 'bruin'."},"bk_259":{"lemma":"grijs","displayNl":"grijs","pos":"adjectief","meanings":[{"de":"grau (Farbe)","ex":"De trui is grijs.","exDe":"Der Pullover ist grau."},{"de":"grau, ergraut (Haare / alt werden)","ex":"Opa heeft grijs haar.","exDe":"Opa hat graue Haare."},{"de":"trüb, grau (Wetter/Stimmung)","ex":"Het was een grijze, regenachtige dag.","exDe":"Es war ein grauer, regnerischer Tag."}],"usage":"Farbadjektiv; attributiv 'grijze', bei het-Wort unflektiert 'grijs'."},"bk_260":{"lemma":"roze","displayNl":"roze","pos":"adjectief","meanings":[{"de":"rosa, pink (Farbe)","ex":"De jurk is roze.","exDe":"Das Kleid ist rosa."}],"usage":"Unveränderliches Farbadjektiv (endet auf -e, wird nicht flektiert): 'de roze jurk', 'het roze shirt'."},"bk_263":{"lemma":"dragen","displayNl":"dragen","pos":"werkwoord","meanings":[{"de":"tragen (Kleidung anhaben)","ex":"Ik draag een jas.","exDe":"Ich trage eine Jacke."},{"de":"tragen (etwas in den Händen/auf dem Rücken befördern)","ex":"Hij draagt de zware koffer naar boven.","exDe":"Er trägt den schweren Koffer nach oben."},{"de":"tragen, (er)tragen (Verantwortung, Kosten, Last)","ex":"Wij dragen samen de verantwoordelijkheid.","exDe":"Wir tragen gemeinsam die Verantwortung."}],"usage":"Unregelmäßig (stark): imperfectum droeg/droegen, Partizip gedragen mit 'hebben'.","conjugation":{"presens":{"ik":"draag","jij":"draagt","hij":"draagt","wij":"dragen"},"imperfectum":{"ik":"droeg","wij":"droegen"},"perfectum":{"aux":"hebben","participle":"gedragen"}},"illustratable":true},"bk_264":{"lemma":"zon","displayNl":"de zon","pos":"substantief","meanings":[{"de":"die Sonne (Himmelskörper)","ex":"De zon schijnt vandaag.","exDe":"Die Sonne scheint heute."},{"de":"der Sonnenschein, die Sonne (als Licht/Wärme)","ex":"We zitten lekker in de zon.","exDe":"Wir sitzen gemütlich in der Sonne."}],"usage":"'de zon' meist im Singular; Plural 'zonnen' nur für mehrere Gestirne.","genus":"de","plural":"zonnen","illustratable":true},"bk_268":{"lemma":"lucht","displayNl":"de lucht","pos":"substantief","meanings":[{"de":"der Himmel","ex":"Er drijven witte wolken in de lucht.","exDe":"Weiße Wolken ziehen am Himmel."},{"de":"die Luft","ex":"Ik adem de frisse lucht in.","exDe":"Ich atme die frische Luft ein."},{"de":"der Geruch, der Duft","ex":"Er hangt een vieze lucht in de keuken.","exDe":"In der Küche hängt ein übler Geruch."}],"usage":"de-Wort; Plural 'luchten' v. a. für Himmel/Wetterstimmungen. Bedeutet je nach Kontext Himmel, Luft oder (unangenehmen) Geruch.","genus":"de","plural":"luchten","illustratable":true},"bk_269":{"lemma":"wolk","displayNl":"de wolk","pos":"substantief","meanings":[{"de":"die Wolke","ex":"Een grote witte wolk drijft langzaam voorbij.","exDe":"Eine große weiße Wolke zieht langsam vorbei."},{"de":"die Wolke (Schwarm, Schwaden; z. B. Rauch, Staub)","ex":"Een wolk van stof steeg op van de weg.","exDe":"Eine Staubwolke stieg von der Straße auf."}],"usage":"de-Wort; Plural 'wolken'. Neben der Wolke am Himmel auch übertragen für Rauch-/Staubschwaden.","genus":"de","plural":"wolken","illustratable":true},"bk_271":{"lemma":"sneeuw","displayNl":"de sneeuw","pos":"substantief","meanings":[{"de":"der Schnee","ex":"De verse sneeuw is wit en koud.","exDe":"Der frische Schnee ist weiß und kalt."}],"usage":"de-Wort; Stoffbezeichnung, normalerweise ohne Plural (unzählbar).","genus":"de","illustratable":true},"bk_274":{"lemma":"vuur","displayNl":"het vuur","pos":"substantief","meanings":[{"de":"das Feuer","ex":"Het vuur in de open haard is lekker warm.","exDe":"Das Feuer im Kamin ist schön warm."},{"de":"das Feuer, die Leidenschaft (übertragen)","ex":"Ze sprak met vuur over haar plannen.","exDe":"Sie sprach mit Feuer über ihre Pläne."}],"usage":"het-Wort; Plural 'vuren'. Konkret das Feuer/die Flamme, übertragen auch Leidenschaft/Eifer.","genus":"het","plural":"vuren","illustratable":true},"bk_275":{"lemma":"aarde","displayNl":"de aarde","pos":"substantief","meanings":[{"de":"die Erde (Planet)","ex":"De aarde draait om de zon.","exDe":"Die Erde dreht sich um die Sonne."},{"de":"die Erde, der Boden (Erdreich)","ex":"De plant staat in vochtige aarde.","exDe":"Die Pflanze steht in feuchter Erde."}],"usage":"de-Wort; meist ohne Plural. Bezeichnet den Planeten Erde und das Erdreich/den Boden.","genus":"de","illustratable":true},"bk_276":{"lemma":"blad","displayNl":"het blad","pos":"substantief","meanings":[{"de":"das Blatt (Pflanze, Baum)","ex":"Een geel blad valt van de boom.","exDe":"Ein gelbes Blatt fällt vom Baum."},{"de":"das Blatt (Papier)","ex":"Schrijf je naam op dit blad.","exDe":"Schreib deinen Namen auf dieses Blatt."},{"de":"die Zeitschrift, das Magazin","ex":"Ik lees elke week een nieuw blad.","exDe":"Ich lese jede Woche eine neue Zeitschrift."},{"de":"das Tablett; die Platte (z. B. Tischplatte)","ex":"De ober bracht de glazen op een blad.","exDe":"Der Kellner brachte die Gläser auf einem Tablett."}],"usage":"het-Wort. Plural 'bladeren' für Laub/Pflanzenblätter, 'bladen' für Papierblätter, Zeitschriften und Tabletts. Bild = Pflanzenblatt.","genus":"het","plural":"bladeren","illustratable":true},"bk_277":{"lemma":"berg","displayNl":"de berg","pos":"substantief","meanings":[{"de":"der Berg","ex":"De berg is heel hoog en steil.","exDe":"Der Berg ist sehr hoch und steil."},{"de":"der Berg, der Haufen (übertragen; große Menge)","ex":"Er ligt een berg was op mijn bed.","exDe":"Auf meinem Bett liegt ein Berg Wäsche."}],"usage":"de-Wort; Plural 'bergen'. Konkret der Berg, übertragen auch ein großer Haufen/eine Menge.","genus":"de","plural":"bergen","illustratable":true},"bk_280":{"lemma":"rivier","displayNl":"de rivier","pos":"substantief","meanings":[{"de":"der Fluss","ex":"De rivier is heel breed en stroomt rustig.","exDe":"Der Fluss ist sehr breit und fließt ruhig."}],"usage":"de-Wort; Plural 'rivieren'. Großes fließendes Gewässer.","genus":"de","plural":"rivieren","illustratable":true},"bk_281":{"lemma":"meer","displayNl":"het meer","pos":"substantief","meanings":[{"de":"der See","ex":"We zwemmen in het meer.","exDe":"Wir schwimmen im See."},{"de":"mehr (als Adverb/Zahlwort in Verbindungen)","ex":"Wil je meer koffie?","exDe":"Möchtest du mehr Kaffee?"}],"usage":"Substantiv 'het meer' = stehendes Binnengewässer. Homonym: 'meer' als Adverb/Zahlwort bedeutet 'mehr' (onbepaald hoofdtelwoord), z. B. 'steeds meer'.","genus":"het","plural":"meren","illustratable":true},"bk_282":{"lemma":"bos","displayNl":"het bos","pos":"substantief","meanings":[{"de":"der Wald","ex":"We lopen in het bos.","exDe":"Wir gehen im Wald spazieren."},{"de":"der Strauß, das Bündel (z. B. Blumen)","ex":"Hij gaf haar een bos bloemen.","exDe":"Er gab ihr einen Strauß Blumen."}],"usage":"'het bos' = zusammenhaengende Baumflaeche. Zweite gaengige Bedeutung: 'een bos' als Buendel/Strauss ('een bos bloemen', 'een bos sleutels').","genus":"het","plural":"bossen","illustratable":true},"bk_283":{"lemma":"dier","displayNl":"het dier","pos":"substantief","meanings":[{"de":"das Tier","ex":"Dat dier is heel groot.","exDe":"Dieses Tier ist sehr groß."}],"usage":"'het dier' = Lebewesen, allgemeiner Oberbegriff für Tiere; Plural 'dieren' auch in Zusammensetzungen wie 'dierentuin' (Zoo).","genus":"het","plural":"dieren","illustratable":true},"bk_284":{"lemma":"vogel","displayNl":"de vogel","pos":"substantief","meanings":[{"de":"der Vogel","ex":"De vogel zingt in de boom.","exDe":"Der Vogel singt im Baum."}],"usage":"'de vogel' = gefiederter Vogel; Plural 'vogels'. Auch bildlich in Wendungen ('een vreemde vogel' = ein sonderbarer Kauz).","genus":"de","plural":"vogels","illustratable":true},"bk_285":{"lemma":"kou","displayNl":"de kou","pos":"substantief","meanings":[{"de":"die Kälte","ex":"Ik hou niet van de kou.","exDe":"Ich mag die Kälte nicht."},{"de":"die Erkältung (in 'kou vatten')","ex":"Trek een jas aan, anders vat je kou.","exDe":"Zieh eine Jacke an, sonst erkältest du dich."}],"usage":"'de kou' = niedrige Temperatur, Kaelte; meist ohne Plural. Feste Wendung 'kou vatten' = sich erkaelten. Nicht zu verwechseln mit 'koud' (Adjektiv, kalt).","genus":"de"},"bk_286":{"lemma":"warmte","displayNl":"de warmte","pos":"substantief","meanings":[{"de":"die Wärme","ex":"De warmte van de zon is fijn.","exDe":"Die Wärme der Sonne ist angenehm."},{"de":"die Herzlichkeit, Wärme (im übertragenen Sinne)","ex":"Ze ontving ons met veel warmte.","exDe":"Sie empfing uns mit viel Herzlichkeit."}],"usage":"'de warmte' = Waerme (Temperatur) und uebertragen menschliche Herzlichkeit; meist ohne Plural. Gegensatz zu 'kou'.","genus":"de"},"bk_287":{"lemma":"zomer","displayNl":"de zomer","pos":"substantief","meanings":[{"de":"der Sommer","ex":"In de zomer is het warm.","exDe":"Im Sommer ist es warm."}],"usage":"'de zomer' = warme Jahreszeit; Plural 'zomers'. Haeufig mit 'in de zomer' (im Sommer), 'deze zomer' (diesen Sommer).","genus":"de","plural":"zomers","illustratable":true},"bk_288":{"lemma":"winter","displayNl":"de winter","pos":"substantief","meanings":[{"de":"der Winter","ex":"In de winter is het koud.","exDe":"Im Winter ist es kalt."}],"usage":"'de winter' = kalte Jahreszeit; Plural 'winters'. Haeufig mit 'in de winter' (im Winter); kulturell verbunden mit Schaatsen (Schlittschuhlaufen) auf zugefrorenen Grachten.","genus":"de","plural":"winters","illustratable":true},"bk_289":{"lemma":"lente","displayNl":"de lente","pos":"substantief","meanings":[{"de":"der Frühling, das Frühjahr","ex":"In de lente bloeien de bloemen.","exDe":"Im Frühling blühen die Blumen."},{"de":"(übertragen) Frühling, Blütezeit, Aufbruch","ex":"Het was de lente van haar leven.","exDe":"Es war der Frühling ihres Lebens."}],"usage":"Jahreszeit; meist mit Artikel de. Feste Wendung: in de lente = im Frühling.","genus":"de","plural":"lentes","illustratable":true},"bk_290":{"lemma":"herfst","displayNl":"de herfst","pos":"substantief","meanings":[{"de":"der Herbst","ex":"In de herfst waait het veel.","exDe":"Im Herbst weht es viel."}],"usage":"Jahreszeit; meist mit Artikel de. Feste Wendung: in de herfst = im Herbst.","genus":"de","plural":"herfsten","illustratable":true},"bk_291":{"lemma":"nat","displayNl":"nat","pos":"adjectief","meanings":[{"de":"nass, feucht","ex":"Mijn jas is nat.","exDe":"Meine Jacke ist nass."},{"de":"regnerisch (vom Wetter)","ex":"Het was een natte zomer.","exDe":"Es war ein nasser Sommer."}],"usage":"Praedikativ (is nat) und attributiv flektiert (de natte jas, een nat kind)."},"bk_293":{"lemma":"regenen","displayNl":"regenen","pos":"werkwoord","meanings":[{"de":"regnen","ex":"Het gaat vandaag regenen.","exDe":"Es wird heute regnen."},{"de":"(uebertragen) niederprasseln, in Massen kommen","ex":"Het regende complimenten.","exDe":"Es hagelte Komplimente."}],"usage":"Unpersoenliches Wetterverb, fast nur mit het: het regent. Regelmaessig.","conjugation":{"presens":{"ik":"regen","jij":"regent","hij":"regent","wij":"regenen"},"imperfectum":{"ik":"regende","wij":"regenden"},"perfectum":{"aux":"hebben","participle":"geregend"}},"illustratable":true},"bk_294":{"lemma":"sneeuwen","displayNl":"sneeuwen","pos":"werkwoord","meanings":[{"de":"schneien","ex":"Het begint te sneeuwen.","exDe":"Es fängt an zu schneien."}],"usage":"Unpersoenliches Wetterverb, fast nur mit het: het sneeuwt. Regelmaessig.","conjugation":{"presens":{"ik":"sneeuw","jij":"sneeuwt","hij":"sneeuwt","wij":"sneeuwen"},"imperfectum":{"ik":"sneeuwde","wij":"sneeuwden"},"perfectum":{"aux":"hebben","participle":"gesneeuwd"}},"illustratable":true},"bk_295":{"lemma":"schijnen","displayNl":"schijnen","pos":"werkwoord","meanings":[{"de":"scheinen, leuchten (Sonne, Licht)","ex":"De zon gaat schijnen.","exDe":"Die Sonne wird scheinen."},{"de":"scheinen, den Anschein haben","ex":"Hij schijnt ziek te zijn.","exDe":"Er scheint krank zu sein."}],"usage":"Starkes, unregelmaessiges Verb: schijnen - scheen - geschenen. Bedeutung 2 oft unpersoenlich: het schijnt dat...","conjugation":{"presens":{"ik":"schijn","jij":"schijnt","hij":"schijnt","wij":"schijnen"},"imperfectum":{"ik":"scheen","wij":"schenen"},"perfectum":{"aux":"hebben","participle":"geschenen"}},"illustratable":true},"bk_296":{"lemma":"waaien","displayNl":"waaien","pos":"werkwoord","meanings":[{"de":"wehen, windig sein","ex":"Het gaat hard waaien.","exDe":"Es wird stark wehen."},{"de":"(im Wind) flattern, geweht werden","ex":"De vlag waait in de wind.","exDe":"Die Fahne weht im Wind."}],"usage":"Als Wetterverb unpersoenlich: het waait. Neben regelmaessigem waaide existiert die starke Form woei; Perfekt mit zijn bei Bewegung (weggewaaid).","conjugation":{"presens":{"ik":"waai","jij":"waait","hij":"waait","wij":"waaien"},"imperfectum":{"ik":"waaide","wij":"waaiden"},"perfectum":{"aux":"hebben","participle":"gewaaid"}},"illustratable":true},"bk_298":{"lemma":"steen","displayNl":"de steen","pos":"substantief","meanings":[{"de":"der Stein","ex":"Er ligt een steen op de weg.","exDe":"Ein Stein liegt auf dem Weg."},{"de":"der Ziegel(stein), Backstein","ex":"Het huis is van steen gebouwd.","exDe":"Das Haus ist aus Stein gebaut."},{"de":"der Spielstein (Brettspiel)","ex":"Hij zette zijn steen op het bord.","exDe":"Er setzte seinen Stein auf das Brett."}],"usage":"de-Wort, Plural stenen. Als Material meist ohne Artikel: van steen (aus Stein).","genus":"de","plural":"stenen","illustratable":true},"bk_299":{"lemma":"zand","displayNl":"het zand","pos":"substantief","meanings":[{"de":"der Sand","ex":"Het zand op het strand is warm.","exDe":"Der Sand am Strand ist warm."},{"de":"das Streugut / der Sand (zum Streuen)","ex":"De gemeente strooit zand op de gladde weg.","exDe":"Die Gemeinde streut Sand auf die glatte Straße."}],"usage":"Stoffnaam (Massennomen), meist ohne Plural. Idiom: 'zand erover' = Schwamm drüber.","genus":"het","illustratable":true},"bk_300":{"lemma":"hond","displayNl":"de hond","pos":"substantief","meanings":[{"de":"der Hund","ex":"De hond speelt in de tuin.","exDe":"Der Hund spielt im Garten."}],"usage":"Diminutiv: hondje. Verkleinerungs-/Schimpfwortverwendung möglich.","genus":"de","plural":"honden","illustratable":true},"bk_301":{"lemma":"poes","displayNl":"de poes","pos":"substantief","meanings":[{"de":"die Katze, das Kätzchen (Kosewort)","ex":"De poes drinkt melk.","exDe":"Die Katze trinkt Milch."},{"de":"das Miezchen / die Mieze (Kosename für eine Katze)","ex":"Kom maar, poes, hier is je eten.","exDe":"Komm her, Mieze, hier ist dein Fressen."}],"usage":"Umgangssprachliches, liebevolles Wort für 'kat'. Diminutiv: poesje.","genus":"de","plural":"poezen","illustratable":true},"bk_302":{"lemma":"konijn","displayNl":"het konijn","pos":"substantief","meanings":[{"de":"das Kaninchen","ex":"Het konijn eet een wortel.","exDe":"Das Kaninchen frisst eine Möhre."}],"usage":"Diminutiv: konijntje.","genus":"het","plural":"konijnen","illustratable":true},"bk_303":{"lemma":"paard","displayNl":"het paard","pos":"substantief","meanings":[{"de":"das Pferd","ex":"Het paard rent op het veld.","exDe":"Das Pferd rennt auf dem Feld."},{"de":"der Springer (Schachfigur)","ex":"Ik zet mijn paard op een sterk veld.","exDe":"Ich stelle meinen Springer auf ein starkes Feld."},{"de":"das Pferd / der Bock (Turngerät)","ex":"De turner springt over het paard.","exDe":"Der Turner springt über das Pferd."}],"usage":"Diminutiv: paardje. Übertragen in Schach und Turnen.","genus":"het","plural":"paarden","illustratable":true},"bk_304":{"lemma":"koe","displayNl":"de koe","pos":"substantief","meanings":[{"de":"die Kuh","ex":"De koe staat in de wei.","exDe":"Die Kuh steht auf der Weide."}],"usage":"Unregelmäßiger Plural: koeien. Diminutiv: koetje. Idiom: 'oude koeien uit de sloot halen' = alte Geschichten aufwärmen.","genus":"de","plural":"koeien","illustratable":true},"bk_305":{"lemma":"varken","displayNl":"het varken","pos":"substantief","meanings":[{"de":"das Schwein","ex":"Het varken ligt in de modder.","exDe":"Das Schwein liegt im Schlamm."}],"usage":"Diminutiv: varkentje. Idiom: 'ik zal dat varkentje wel wassen' = das erledige ich schon.","genus":"het","plural":"varkens","illustratable":true},"bk_306":{"lemma":"schaap","displayNl":"het schaap","pos":"substantief","meanings":[{"de":"das Schaf","ex":"Het schaap eet gras.","exDe":"Das Schaf frisst Gras."},{"de":"das Schäfchen (Kosewort für einen gutmütigen/naiven Menschen)","ex":"Ach, het arme schaap wist het echt niet.","exDe":"Ach, das arme Schäfchen wusste es wirklich nicht."}],"usage":"Unregelmäßiger Plural: schapen. Diminutiv: schaapje. Übertragen: gutmütiger, naiver Mensch.","genus":"het","plural":"schapen","illustratable":true},"bk_307":{"lemma":"eend","displayNl":"de eend","pos":"substantief","meanings":[{"de":"die Ente","ex":"De eend zwemt in de vijver.","exDe":"Die Ente schwimmt im Teich."},{"de":"das Entenfleisch (als Gericht)","ex":"We eten vanavond eend met sinaasappelsaus.","exDe":"Wir essen heute Abend Ente mit Orangensauce."}],"usage":"Konkretes Wassertier; im Plural 'eenden'. Auch für das Fleisch/Gericht.","genus":"de","plural":"eenden","illustratable":true},"bk_308":{"lemma":"muis","displayNl":"de muis","pos":"substantief","meanings":[{"de":"die Maus (Tier)","ex":"De muis is heel klein.","exDe":"Die Maus ist sehr klein."},{"de":"die Maus (Computer)","ex":"Ik klik met de muis op de knop.","exDe":"Ich klicke mit der Maus auf den Knopf."}],"usage":"De-Wort; Plural 'muizen'. Sowohl das Tier als auch das Computer-Eingabegeraet.","genus":"de","plural":"muizen","illustratable":true},"bk_309":{"lemma":"kikker","displayNl":"de kikker","pos":"substantief","meanings":[{"de":"der Frosch","ex":"De kikker springt in het water.","exDe":"Der Frosch springt ins Wasser."}],"usage":"De-Wort; Plural 'kikkers'. Konkretes Amphibientier.","genus":"de","plural":"kikkers","illustratable":true},"bk_310":{"lemma":"spin","displayNl":"de spin","pos":"substantief","meanings":[{"de":"die Spinne","ex":"De spin maakt een web.","exDe":"Die Spinne macht ein Netz."}],"usage":"De-Wort; Plural 'spinnen' (identisch mit dem Infinitiv des Verbs 'spinnen'). Konkretes Tier.","genus":"de","plural":"spinnen","illustratable":true},"bk_311":{"lemma":"bij","displayNl":"de bij","pos":"substantief","meanings":[{"de":"die Biene","ex":"De bij vliegt naar de bloem.","exDe":"Die Biene fliegt zur Blume."}],"usage":"De-Wort; Plural 'bijen'. Als Substantiv das Insekt; Homonym zur Praeposition/Adverb 'bij' (bei/an) und der Verbform, hier aber das Tier.","genus":"de","plural":"bijen","illustratable":true},"bk_312":{"lemma":"mier","displayNl":"de mier","pos":"substantief","meanings":[{"de":"die Ameise","ex":"De mier is heel sterk.","exDe":"Die Ameise ist sehr stark."}],"usage":"De-Wort; Plural 'mieren'. Konkretes Insekt.","genus":"de","plural":"mieren","illustratable":true},"bk_313":{"lemma":"leeuw","displayNl":"de leeuw","pos":"substantief","meanings":[{"de":"der Löwe","ex":"De leeuw is een sterk dier.","exDe":"Der Löwe ist ein starkes Tier."}],"usage":"De-Wort; Plural 'leeuwen'. Konkretes Tier; auch heraldisch als niederlaendisches Wappentier.","genus":"de","plural":"leeuwen","illustratable":true},"bk_314":{"lemma":"olifant","displayNl":"de olifant","pos":"substantief","meanings":[{"de":"der Elefant","ex":"De olifant is heel groot.","exDe":"Der Elefant ist sehr groß."}],"usage":"De-Wort; Plural 'olifanten'. Konkretes großes Tier.","genus":"de","plural":"olifanten","illustratable":true},"bk_315":{"lemma":"aap","displayNl":"de aap","pos":"substantief","meanings":[{"de":"der Affe","ex":"De aap zit in de boom.","exDe":"Der Affe sitzt im Baum."},{"de":"Dummkopf, Trottel (umgangssprachlich für eine Person)","ex":"Doe niet zo'n domme aap.","exDe":"Sei nicht so ein dummer Affe."}],"usage":"Alltagsnah; als Schimpfwort mild-scherzhaft. Redewendung: 'de aap komt uit de mouw' (die Wahrheit kommt ans Licht).","genus":"de","plural":"apen","illustratable":true},"bk_316":{"lemma":"beer","displayNl":"de beer","pos":"substantief","meanings":[{"de":"der Bär","ex":"De beer slaapt in de winter.","exDe":"Der Bär schläft im Winter."},{"de":"der Eber (männliches Schwein)","ex":"De boer heeft een grote beer in de stal.","exDe":"Der Bauer hat einen großen Eber im Stall."},{"de":"großes Hindernis ('beren op de weg zien' = schwarzmalen)","ex":"Hij ziet overal beren op de weg.","exDe":"Er sieht überall Löwen im Weg (schwarzmalt ständig)."}],"usage":"Häufigste Bedeutung: Bär (Tier). 'beren op de weg zien' = Schwierigkeiten übertrieben befürchten.","genus":"de","plural":"beren","illustratable":true},"bk_317":{"lemma":"wolf","displayNl":"de wolf","pos":"substantief","meanings":[{"de":"der Wolf","ex":"De wolf leeft in het bos.","exDe":"Der Wolf lebt im Wald."}],"usage":"Standard; Plural mit v: 'wolven'. Redewendung: 'een wolf in schaapskleren' (ein Wolf im Schafspelz).","genus":"de","plural":"wolven","illustratable":true},"bk_318":{"lemma":"vos","displayNl":"de vos","pos":"substantief","meanings":[{"de":"der Fuchs","ex":"De vos is heel slim.","exDe":"Der Fuchs ist sehr schlau."},{"de":"schlauer, listiger Mensch (übertragen)","ex":"Die man is een echte vos in zaken.","exDe":"Der Mann ist ein echter Fuchs im Geschäft."}],"usage":"Steht sprichwörtlich für Schläue: 'een slimme vos'. Plural 'vossen'.","genus":"de","plural":"vossen","illustratable":true},"bk_319":{"lemma":"staart","displayNl":"de staart","pos":"substantief","meanings":[{"de":"der Schwanz (eines Tieres)","ex":"De hond kwispelt met zijn staart.","exDe":"Der Hund wedelt mit dem Schwanz."},{"de":"das Ende, der hintere Teil (z. B. einer Reihe, Kolonne, Flugzeug)","ex":"Hij stond aan de staart van de file.","exDe":"Er stand am Ende des Staus."},{"de":"der Zopf (Frisur, 'paardenstaart' = Pferdeschwanz)","ex":"Ze draagt haar haar in een staart.","exDe":"Sie trägt ihr Haar zu einem Pferdeschwanz."}],"usage":"Grundbedeutung Tierschwanz; übertragen 'Ende/hinterer Teil'. 'paardenstaart' = Pferdeschwanz (Frisur).","genus":"de","plural":"staarten","illustratable":true},"bk_320":{"lemma":"week","displayNl":"de week","pos":"substantief","meanings":[{"de":"die Woche","ex":"De week is bijna voorbij.","exDe":"Die Woche ist fast vorbei."},{"de":"das Einweichen ('in de week zetten' = einweichen)","ex":"Ik zet de bonen in de week.","exDe":"Ich weiche die Bohnen ein."}],"usage":"Häufigste Bedeutung Zeitraum von sieben Tagen; Plural 'weken'. Nicht verwechseln mit dem Adjektiv 'week' (= weich).","genus":"de","plural":"weken"},"bk_321":{"lemma":"maand","displayNl":"de maand","pos":"substantief","meanings":[{"de":"der Monat","ex":"Volgende maand ga ik op reis.","exDe":"Nächsten Monat gehe ich auf Reise."}],"usage":"Zeitangabe; 'volgende/vorige maand' = nächster/letzter Monat. Plural 'maanden'.","genus":"de","plural":"maanden"},"bk_323":{"lemma":"minuut","displayNl":"de minuut","pos":"substantief","meanings":[{"de":"die Minute (Zeiteinheit)","ex":"Wacht een minuut, alsjeblieft.","exDe":"Warte eine Minute, bitte."},{"de":"die Minute (Winkel-/Bogenmaß, 1/60 Grad)","ex":"De hoek meet dertig graden en tien minuten.","exDe":"Der Winkel misst dreißig Grad und zehn Minuten."}],"usage":"Zeiteinheit (60 Sekunden); umgangssprachlich 'een minuutje' = einen Augenblick. Plural 'minuten'.","genus":"de","plural":"minuten"},"bk_324":{"lemma":"uur","displayNl":"het uur","pos":"substantief","meanings":[{"de":"die Stunde (Zeiteinheit)","ex":"De les duurt een uur.","exDe":"Der Unterricht dauert eine Stunde."},{"de":"die Uhr(zeit), die Stunde am Tag","ex":"Hoe laat is het? Het is drie uur.","exDe":"Wie spät ist es? Es ist drei Uhr."}],"usage":"Zeiteinheit (60 Minuten) und Angabe der vollen Stunde: 'om drie uur' = um drei Uhr. Nach der Uhrzeit fragt man mit 'Hoe laat is het?'","genus":"het","plural":"uren","illustratable":true},"bk_325":{"lemma":"ochtend","displayNl":"de ochtend","pos":"substantief","meanings":[{"de":"der Morgen, der Vormittag (Tageszeit)","ex":"In de ochtend drink ik koffie.","exDe":"Am Morgen trinke ich Kaffee."},{"de":"morgens (Zeitangabe: 's ochtends)","ex":"Ik sta om zeven uur 's ochtends op.","exDe":"Ich stehe um sieben Uhr morgens auf."}],"usage":"Neutraler Alltagsbegriff für die Tageszeit von etwa Sonnenaufgang bis Mittag. 's ochtends = morgens/vormittags. Gebräuchlicher als 'de morgen'.","genus":"de","plural":"ochtenden"},"bk_326":{"lemma":"morgen","displayNl":"de morgen","pos":"substantief","meanings":[{"de":"der Morgen (Tagesbeginn)","ex":"Op een koude morgen liep hij naar zijn werk.","exDe":"An einem kalten Morgen ging er zur Arbeit."},{"de":"der Morgen (im Gruß: Goedemorgen)","ex":"Goedemorgen, hoe gaat het?","exDe":"Guten Morgen, wie geht es?"}],"usage":"Bezeichnet als Substantiv den Morgen/Tagesbeginn, oft etwas gehobener als 'de ochtend'; steckt im Gruß 'goedemorgen'. Nicht verwechseln mit dem Adverb 'morgen' (= am nächsten Tag).","genus":"de","plural":"morgens"},"bk_327":{"lemma":"middag","displayNl":"de middag","pos":"substantief","meanings":[{"de":"der Nachmittag (Zeit von Mittag bis Abend)","ex":"Vanmiddag ga ik naar de markt.","exDe":"Heute Nachmittag gehe ich zum Markt."},{"de":"der Mittag (Tagesmitte, 12 Uhr)","ex":"We eten om twaalf uur 's middags.","exDe":"Wir essen um zwölf Uhr mittags."}],"usage":"'de middag' meint im Niederländischen meist den Nachmittag (nach 12 Uhr), nicht nur den Mittagszeitpunkt. 's middags = mittags/nachmittags, vanmiddag = heute Nachmittag.","genus":"de","plural":"middagen"},"bk_328":{"lemma":"morgen","displayNl":"morgen","pos":"bijwoord","meanings":[{"de":"morgen (am nächsten Tag)","ex":"Morgen ga ik werken.","exDe":"Morgen gehe ich arbeiten."}],"usage":"Zeitadverb für den nächsten Tag. Formgleich mit dem Substantiv 'de morgen' (= der Morgen), aber hier unveränderliches Adverb. Steigerung: 'overmorgen' = übermorgen."},"bk_329":{"lemma":"gisteren","displayNl":"gisteren","pos":"bijwoord","meanings":[{"de":"gestern (am vorigen Tag)","ex":"Gisteren was ik ziek.","exDe":"Gestern war ich krank."}],"usage":"Zeitadverb für den vorangegangenen Tag. Verwandt: 'eergisteren' = vorgestern, 'gisteravond' = gestern Abend."},"bk_330":{"lemma":"nu","displayNl":"nu","pos":"bijwoord","meanings":[{"de":"jetzt, nun (in diesem Augenblick)","ex":"Ik moet nu gaan.","exDe":"Ich muss jetzt gehen."},{"de":"nun, jetzt (als Übergangswort im Satz)","ex":"Nu je er toch bent, kun je me helpen.","exDe":"Jetzt, wo du schon da bist, kannst du mir helfen."}],"usage":"Zeitadverb für den gegenwärtigen Moment; auch als leicht verbindendes Füllwort ('nu ja', 'nu goed'). Verstärkt: 'nu meteen' = sofort."},"bk_331":{"lemma":"straks","displayNl":"straks","pos":"bijwoord","meanings":[{"de":"gleich, später (bald, in Kürze)","ex":"Ik bel je straks.","exDe":"Ich rufe dich gleich an."},{"de":"nachher, am Ende (womöglich, wenn man nicht aufpasst)","ex":"Doe je jas aan, straks word je nog ziek.","exDe":"Zieh deine Jacke an, sonst wirst du am Ende noch krank."}],"usage":"Zeitadverb für die nahe Zukunft ('gleich/nachher'); 'tot straks!' = bis gleich! Kann auch eine mögliche unerwünschte Folge andeuten (= sonst noch, am Ende)."},"bk_332":{"lemma":"later","displayNl":"later","pos":"bijwoord","meanings":[{"de":"später, nachher","ex":"We praten later verder.","exDe":"Wir reden später weiter."},{"de":"(zeitlich) danach, in der Zukunft","ex":"Later wil ik in Utrecht wonen.","exDe":"Später will ich in Utrecht wohnen."}],"usage":"Zeitadverb; zugleich Komparativ von 'laat' (spät → später).","notes":"Komparativform von 'laat'."},"bk_333":{"lemma":"vroeg","displayNl":"vroeg","pos":"adjectief","meanings":[{"de":"früh","ex":"Ik sta vroeg op.","exDe":"Ich stehe früh auf."},{"de":"frühzeitig, zeitig","ex":"We zijn vroeg vertrokken.","exDe":"Wir sind früh losgefahren."}],"usage":"Als Adjektiv und Adverb ('früh'). Homonym: 'vroeg' ist auch die Vergangenheitsform (imperfectum) von 'vragen' (fragen).","notes":"Formgleich mit imperfectum von 'vragen' (ik vroeg = ich fragte)."},"bk_334":{"lemma":"laat","displayNl":"laat","pos":"adjectief","meanings":[{"de":"spät","ex":"Het is al laat.","exDe":"Es ist schon spät."},{"de":"verspätet, spät dran","ex":"Sorry dat ik zo laat ben.","exDe":"Entschuldigung, dass ich so spät bin."}],"usage":"Adjektiv/Adverb 'spät'. Homonym: 'laat' ist auch eine Form von 'laten' (lassen).","notes":"Formgleich mit Präsens/Imperativ von 'laten' (laat = lass)."},"bk_335":{"lemma":"altijd","displayNl":"altijd","pos":"bijwoord","meanings":[{"de":"immer, stets","ex":"Ik ben altijd op tijd.","exDe":"Ich bin immer pünktlich."},{"de":"jederzeit, in jedem Fall","ex":"Je kunt altijd bellen.","exDe":"Du kannst jederzeit anrufen."}],"usage":"Häufigkeitsadverb; Gegenteil von 'nooit'."},"bk_336":{"lemma":"nooit","displayNl":"nooit","pos":"bijwoord","meanings":[{"de":"nie, niemals","ex":"Ik drink nooit koffie.","exDe":"Ich trinke nie Kaffee."},{"de":"keinesfalls, auf keinen Fall","ex":"Dat doe ik nooit meer.","exDe":"Das mache ich nie wieder."}],"usage":"Negatives Häufigkeitsadverb; Gegenteil von 'altijd'."},"bk_337":{"lemma":"soms","displayNl":"soms","pos":"bijwoord","meanings":[{"de":"manchmal, ab und zu","ex":"Soms ga ik zwemmen.","exDe":"Manchmal gehe ich schwimmen."},{"de":"etwa, zufällig (in Fragen)","ex":"Heb je soms een pen voor me?","exDe":"Hast du zufällig einen Stift für mich?"}],"usage":"Häufigkeitsadverb; in Fragen abgeschwächt im Sinne von 'etwa/zufällig'."},"bk_338":{"lemma":"vaak","displayNl":"vaak","pos":"bijwoord","meanings":[{"de":"oft, häufig","ex":"Ik ga vaak naar de markt.","exDe":"Ich gehe oft zum Markt."}],"usage":"Häufigkeitsadverb; Steigerung: vaker, vaakst / meest."},"bk_339":{"lemma":"weer","displayNl":"weer","pos":"bijwoord","meanings":[{"de":"wieder, erneut","ex":"Hij is weer ziek.","exDe":"Er ist wieder krank."},{"de":"das Wetter (als Substantiv: het weer)","ex":"Wat is het weer mooi vandaag!","exDe":"Was für schönes Wetter heute!"}],"usage":"Primär Adverb 'wieder'. Homonym: 'het weer' = das Wetter (Substantiv, genus het).","notes":"Als Substantiv 'het weer' (das Wetter) – anderes Genus/Wortart; hier als Adverb geführt."},"bk_340":{"lemma":"maandag","displayNl":"de maandag","pos":"substantief","meanings":[{"de":"der Montag","ex":"Op maandag begin ik vroeg met werken.","exDe":"Am Montag fange ich früh mit der Arbeit an."}],"usage":"Wochentag; meist ohne Artikel im Zeitadverbial: \"op maandag\" = montags, \"maandag\" = am Montag.","genus":"de","plural":"maandagen"},"bk_341":{"lemma":"dinsdag","displayNl":"de dinsdag","pos":"substantief","meanings":[{"de":"der Dienstag","ex":"Dinsdag heb ik Nederlandse les.","exDe":"Dienstag habe ich Niederländischunterricht."}],"usage":"Wochentag; \"op dinsdag\" = dienstags. Kleinschreibung im Niederländischen.","genus":"de","plural":"dinsdagen"},"bk_342":{"lemma":"woensdag","displayNl":"de woensdag","pos":"substantief","meanings":[{"de":"der Mittwoch","ex":"Woensdag ga ik sporten.","exDe":"Mittwoch gehe ich Sport machen."}],"usage":"Wochentag; Schreibweise \"woensdag\" (stumme Buchstaben). \"op woensdag\" = mittwochs.","genus":"de","plural":"woensdagen"},"bk_343":{"lemma":"donderdag","displayNl":"de donderdag","pos":"substantief","meanings":[{"de":"der Donnerstag","ex":"Donderdag werk ik niet.","exDe":"Donnerstag arbeite ich nicht."}],"usage":"Wochentag; \"op donderdag\" = donnerstags.","genus":"de","plural":"donderdagen"},"bk_344":{"lemma":"vrijdag","displayNl":"de vrijdag","pos":"substantief","meanings":[{"de":"der Freitag","ex":"Vrijdag is mijn favoriete dag.","exDe":"Freitag ist mein Lieblingstag."}],"usage":"Wochentag; \"op vrijdag\" = freitags.","genus":"de","plural":"vrijdagen"},"bk_345":{"lemma":"zaterdag","displayNl":"de zaterdag","pos":"substantief","meanings":[{"de":"der Samstag","ex":"Zaterdag slaap ik uit.","exDe":"Samstag schlafe ich aus."}],"usage":"Wochentag; \"op zaterdag\" = samstags/sonnabends.","genus":"de","plural":"zaterdagen"},"bk_346":{"lemma":"zondag","displayNl":"de zondag","pos":"substantief","meanings":[{"de":"der Sonntag","ex":"Zondag bezoek ik mijn oma.","exDe":"Sonntag besuche ich meine Oma."}],"usage":"Wochentag; \"op zondag\" = sonntags.","genus":"de","plural":"zondagen"},"bk_347":{"lemma":"weekend","displayNl":"het weekend","pos":"substantief","meanings":[{"de":"das Wochenende","ex":"Fijn weekend!","exDe":"Schönes Wochenende!"},{"de":"das Wochenende (Kurzurlaub übers Wochenende)","ex":"We gaan een weekend weg naar Zeeland.","exDe":"Wir fahren übers Wochenende nach Zeeland weg."}],"usage":"het-Wort; Plural \"weekends\" (auch \"weekenden\"). Gruß: \"Fijn/prettig weekend!\".","genus":"het","plural":"weekends"},"bk_348":{"lemma":"januari","displayNl":"januari","pos":"substantief","meanings":[{"de":"Januar","ex":"In januari is het koud.","exDe":"Im Januar ist es kalt."}],"usage":"Monatsname; meist ohne Artikel gebraucht (\"in januari\"). Kleinschreibung im Niederländischen."},"bk_349":{"lemma":"februari","displayNl":"februari","pos":"substantief","meanings":[{"de":"Februar","ex":"Februari is een korte maand.","exDe":"Februar ist ein kurzer Monat."}],"usage":"Monatsname; meist ohne Artikel (\"in februari\"). Kleinschreibung."},"bk_350":{"lemma":"maart","displayNl":"maart","pos":"substantief","meanings":[{"de":"März","ex":"In maart begint de lente.","exDe":"Im März beginnt der Frühling."}],"usage":"Monatsname; meist ohne Artikel (\"in maart\"). Kleinschreibung."},"bk_351":{"lemma":"april","displayNl":"april","pos":"substantief","meanings":[{"de":"April","ex":"In april regent het vaak.","exDe":"Im April regnet es oft."}],"usage":"Monatsname; meist ohne Artikel (\"in april\"). Kleinschreibung."},"bk_352":{"lemma":"mei","displayNl":"mei","pos":"substantief","meanings":[{"de":"Mai","ex":"In mei bloeien de bloemen.","exDe":"Im Mai blühen die Blumen."}],"usage":"Monatsname; meist ohne Artikel (\"in mei\"). Kleinschreibung; kürzester Monatsname."},"bk_353":{"lemma":"juni","displayNl":"juni","pos":"substantief","meanings":[{"de":"Juni","ex":"In juni word ik jarig.","exDe":"Im Juni habe ich Geburtstag."}],"usage":"Monatsname; meist ohne Artikel (\"in juni\"). Beim Sprechen oft \"juno\" zur Unterscheidung von juli. Kleinschreibung."},"bk_354":{"lemma":"juli","displayNl":"juli","pos":"substantief","meanings":[{"de":"Juli","ex":"In juli hebben we vakantie.","exDe":"Im Juli haben wir Ferien."}],"usage":"Monatsname; meist ohne Artikel (\"in juli\"). Beim Sprechen oft \"julei\" zur Unterscheidung von juni. Kleinschreibung."},"bk_355":{"lemma":"augustus","displayNl":"augustus","pos":"substantief","meanings":[{"de":"August","ex":"Augustus is heel warm.","exDe":"August ist sehr warm."}],"usage":"Monatsname; meist ohne Artikel (\"in augustus\"). Kleinschreibung."},"bk_356":{"lemma":"september","displayNl":"september","pos":"substantief","meanings":[{"de":"September","ex":"In september begint de school weer.","exDe":"Im September beginnt die Schule wieder."}],"usage":"Monatsname; wird klein und meist ohne Artikel gebraucht (de negende maand van het jaar)."},"bk_358":{"lemma":"november","displayNl":"november","pos":"substantief","meanings":[{"de":"November","ex":"November is vaak grijs en nat.","exDe":"November ist oft grau und nass."}],"usage":"Monatsname; klein geschrieben, meist ohne Artikel (de elfde maand van het jaar)."},"bk_359":{"lemma":"december","displayNl":"december","pos":"substantief","meanings":[{"de":"Dezember","ex":"In december vieren we kerst.","exDe":"Im Dezember feiern wir Weihnachten."}],"usage":"Monatsname; klein geschrieben, meist ohne Artikel (de twaalfde maand van het jaar)."},"bk_360":{"lemma":"half","displayNl":"half","pos":"adjectief","meanings":[{"de":"halb (Uhrzeit: halb vor der vollen Stunde)","ex":"Het is half drie.","exDe":"Es ist halb drei."},{"de":"halb, zur Hälfte","ex":"Het glas is nog maar half vol.","exDe":"Das Glas ist nur noch halb voll."}],"usage":"Bei Uhrzeiten: 'half drie' = 14:30/2:30 (halb der nächsten Stunde, wie im Deutschen). Flektiert: 'een halve appel'."},"bk_361":{"lemma":"nul","displayNl":"nul","pos":"telwoord","meanings":[{"de":"null","ex":"De temperatuur is nul graden.","exDe":"Die Temperatur ist null Grad."}],"usage":"Grundzahl 0; auch bei Spielständen ('twee-nul')."},"bk_362":{"lemma":"een","displayNl":"een","pos":"telwoord","meanings":[{"de":"eins (Grundzahl)","ex":"Ik heb maar één broer.","exDe":"Ich habe nur einen Bruder."},{"de":"ein, eine (unbestimmter Artikel)","ex":"Er staat een fiets voor de deur.","exDe":"Vor der Tür steht ein Fahrrad."}],"usage":"Als Zahlwort betont oft 'één' geschrieben (mit Akzenten) zur Abgrenzung vom unbetonten Artikel 'een' (gesprochen 'un')."},"bk_363":{"lemma":"twee","displayNl":"twee","pos":"telwoord","meanings":[{"de":"zwei","ex":"Ik drink twee koppen thee.","exDe":"Ich trinke zwei Tassen Tee."}],"usage":"Grundzahl 2."},"bk_364":{"lemma":"drie","displayNl":"drie","pos":"telwoord","meanings":[{"de":"drei","ex":"We zijn met drie personen.","exDe":"Wir sind zu dritt."}],"usage":"Grundzahl 3."},"bk_365":{"lemma":"vier","displayNl":"vier","pos":"telwoord","meanings":[{"de":"vier","ex":"De tafel heeft vier poten.","exDe":"Der Tisch hat vier Beine."}],"usage":"Grundzahl 4."},"bk_366":{"lemma":"vijf","displayNl":"vijf","pos":"telwoord","meanings":[{"de":"fünf","ex":"Ik heb vijf vingers.","exDe":"Ich habe fünf Finger."}],"usage":"Grundzahl 5."},"bk_367":{"lemma":"zes","displayNl":"zes","pos":"telwoord","meanings":[{"de":"sechs","ex":"Het is zes uur.","exDe":"Es ist sechs Uhr."}],"usage":"Grundzahl 6."},"bk_368":{"lemma":"zeven","displayNl":"zeven","pos":"telwoord","meanings":[{"de":"sieben","ex":"Een week heeft zeven dagen.","exDe":"Eine Woche hat sieben Tage."}],"usage":"Grundzahl 7."},"bk_369":{"lemma":"acht","displayNl":"acht","pos":"telwoord","meanings":[{"de":"acht","ex":"Ik begin om acht uur.","exDe":"Ich fange um acht Uhr an."},{"de":"Acht, Aufmerksamkeit (in Wendungen)","ex":"Geef acht op het verkeer.","exDe":"Achte auf den Verkehr."}],"usage":"Grundzahl 8; als Substantiv 'de acht' in festen Wendungen (acht geven, in acht nemen)."},"bk_370":{"lemma":"negen","displayNl":"negen","pos":"telwoord","meanings":[{"de":"neun","ex":"De winkel opent om negen uur.","exDe":"Der Laden öffnet um neun Uhr."}],"usage":"Grundzahl 9."},"bk_371":{"lemma":"tien","displayNl":"tien","pos":"telwoord","meanings":[{"de":"zehn","ex":"Ik heb tien euro.","exDe":"Ich habe zehn Euro."}],"usage":"Grundzahl 10."},"bk_372":{"lemma":"elf","displayNl":"elf","pos":"telwoord","meanings":[{"de":"elf","ex":"Er zijn elf spelers.","exDe":"Es gibt elf Spieler."}],"usage":"Grundzahl 11."},"bk_373":{"lemma":"twaalf","displayNl":"twaalf","pos":"telwoord","meanings":[{"de":"zwölf","ex":"Een jaar heeft twaalf maanden.","exDe":"Ein Jahr hat zwölf Monate."}],"usage":"Grundzahl 12; als Ordnungszahl 'twaalfde'."},"bk_374":{"lemma":"dertien","displayNl":"dertien","pos":"telwoord","meanings":[{"de":"dreizehn","ex":"Mijn zoon is dertien jaar.","exDe":"Mein Sohn ist dreizehn Jahre alt."}],"usage":"Grundzahl 13; Ordnungszahl 'dertiende'."},"bk_375":{"lemma":"veertien","displayNl":"veertien","pos":"telwoord","meanings":[{"de":"vierzehn","ex":"Over veertien dagen kom ik terug.","exDe":"In vierzehn Tagen komme ich zurück."}],"usage":"Grundzahl 14; 'veertien dagen' = zwei Wochen."},"bk_376":{"lemma":"vijftien","displayNl":"vijftien","pos":"telwoord","meanings":[{"de":"fünfzehn","ex":"De bus komt over vijftien minuten.","exDe":"Der Bus kommt in fünfzehn Minuten."}],"usage":"Grundzahl 15; Ordnungszahl 'vijftiende'."},"bk_377":{"lemma":"zestien","displayNl":"zestien","pos":"telwoord","meanings":[{"de":"sechzehn","ex":"Zij is zestien jaar oud.","exDe":"Sie ist sechzehn Jahre alt."}],"usage":"Grundzahl 16; Ordnungszahl 'zestiende'."},"bk_378":{"lemma":"zeventien","displayNl":"zeventien","pos":"telwoord","meanings":[{"de":"siebzehn","ex":"Hij woont op nummer zeventien.","exDe":"Er wohnt in Nummer siebzehn."}],"usage":"Grundzahl 17; Ordnungszahl 'zeventiende'."},"bk_379":{"lemma":"achttien","displayNl":"achttien","pos":"telwoord","meanings":[{"de":"achtzehn","ex":"We hebben achttien gasten.","exDe":"Wir haben achtzehn Gäste."}],"usage":"Grundzahl 18; substantiviert 'je achttiende' = 18. Geburtstag/Volljährigkeit."},"bk_380":{"lemma":"negentien","displayNl":"negentien","pos":"telwoord","meanings":[{"de":"neunzehn","ex":"We hebben negentien gasten.","exDe":"Wir haben neunzehn Gäste."}],"usage":"Grundzahl 19; Ordnungszahl 'negentiende'."},"bk_381":{"lemma":"twintig","displayNl":"twintig","pos":"telwoord","meanings":[{"de":"zwanzig","ex":"Het kost twintig euro.","exDe":"Es kostet zwanzig Euro."},{"de":"zwanzig (Uhrzeit-Minuten)","ex":"Het is tien voor half twee.","exDe":"Es ist zwanzig nach eins."}],"usage":"Grundzahl 20. In Uhrzeiten oft mit 'over'/'voor' kombiniert."},"bk_382":{"lemma":"dertig","displayNl":"dertig","pos":"telwoord","meanings":[{"de":"dreißig","ex":"De les duurt dertig minuten.","exDe":"Die Stunde dauert dreißig Minuten."}],"usage":"Grundzahl 30."},"bk_383":{"lemma":"veertig","displayNl":"veertig","pos":"telwoord","meanings":[{"de":"vierzig","ex":"Mijn vader is veertig jaar.","exDe":"Mein Vater ist vierzig Jahre alt."}],"usage":"Grundzahl 40. Beachte Schreibung 'veertig' (nicht 'viertig')."},"bk_384":{"lemma":"vijftig","displayNl":"vijftig","pos":"telwoord","meanings":[{"de":"fünfzig","ex":"Er zijn vijftig mensen hier.","exDe":"Es sind fünfzig Menschen hier."}],"usage":"Grundzahl 50."},"bk_385":{"lemma":"zestig","displayNl":"zestig","pos":"telwoord","meanings":[{"de":"sechzig","ex":"Een uur heeft zestig minuten.","exDe":"Eine Stunde hat sechzig Minuten."}],"usage":"Grundzahl 60."},"bk_386":{"lemma":"zeventig","displayNl":"zeventig","pos":"telwoord","meanings":[{"de":"siebzig","ex":"Mijn oma is zeventig jaar.","exDe":"Meine Oma ist siebzig Jahre alt."}],"usage":"Grundzahl 70."},"bk_387":{"lemma":"tachtig","displayNl":"tachtig","pos":"telwoord","meanings":[{"de":"achtzig","ex":"De auto rijdt tachtig kilometer per uur.","exDe":"Das Auto fährt achtzig Kilometer pro Stunde."}],"usage":"Grundzahl 80."},"bk_388":{"lemma":"negentig","displayNl":"negentig","pos":"telwoord","meanings":[{"de":"neunzig","ex":"Hij is bijna negentig jaar.","exDe":"Er ist fast neunzig Jahre alt."}],"usage":"Grundzahl 90."},"bk_392":{"lemma":"tweede","displayNl":"tweede","pos":"telwoord","meanings":[{"de":"zweite(r)","ex":"Neem de tweede straat links.","exDe":"Nimm die zweite Straße links."},{"de":"Zweiter (Person/Rang)","ex":"Hij werd tweede in de wedstrijd.","exDe":"Er wurde Zweiter im Wettkampf."}],"usage":"Ordnungszahl. Attributiv immer mit -e: 'de/het tweede'. Kann auch substantiviert als Rangangabe stehen."},"bk_393":{"lemma":"derde","displayNl":"derde","pos":"telwoord","meanings":[{"de":"dritte(r)","ex":"Hij woont op de derde verdieping.","exDe":"Er wohnt im dritten Stock."},{"de":"Dritter (Person/Partei)","ex":"Een derde kan bemiddelen.","exDe":"Ein Dritter kann vermitteln."}],"usage":"Ordnungszahl. Attributiv mit -e; substantiviert 'een derde' auch = ein Drittel (Bruch)."},"bk_396":{"lemma":"weinig","displayNl":"weinig","pos":"telwoord","meanings":[{"de":"wenig","ex":"Ik heb weinig tijd.","exDe":"Ich habe wenig Zeit."},{"de":"wenige","ex":"Weinig mensen kwamen opdagen.","exDe":"Wenige Leute erschienen."},{"de":"kaum, selten (als Adverb)","ex":"Hij komt hier weinig.","exDe":"Er kommt selten hierher."}],"usage":"Unbestimmtes Mengenwort. Steigerung: weinig – minder – minst. Gegenteil von 'veel'."},"bk_397":{"lemma":"meer","displayNl":"meer","pos":"telwoord","meanings":[{"de":"mehr","ex":"Ik wil meer water.","exDe":"Ich möchte mehr Wasser."},{"de":"der See (Substantiv: het meer)","ex":"We zwommen in het meer.","exDe":"Wir schwammen im See."},{"de":"nicht mehr (in 'niet meer')","ex":"Ik werk hier niet meer.","exDe":"Ich arbeite hier nicht mehr."}],"usage":"Als Mengenwort Komparativ von 'veel' (veel – meer – meest). Homonym: 'het meer' (Plural 'meren') = der See.","notes":"Homonym: het meer (See) ist konkret illustrierbar, das Lemma hier ist aber das Mengenwort 'mehr'."},"bk_398":{"lemma":"genoeg","displayNl":"genoeg","pos":"bijwoord","meanings":[{"de":"genug","ex":"Ik heb genoeg geld.","exDe":"Ich habe genug Geld."},{"de":"genügend, ausreichend","ex":"Is dit groot genoeg?","exDe":"Ist das groß genug?"}],"usage":"Steht nachgestellt beim Adjektiv ('groot genoeg') oder vor/beim Substantiv ('genoeg geld')."},"bk_399":{"lemma":"een beetje","displayNl":"een beetje","pos":"uitdrukking","meanings":[{"de":"ein bisschen","ex":"Ik spreek een beetje Nederlands.","exDe":"Ich spreche ein bisschen Niederländisch."},{"de":"ein wenig, etwas","ex":"Kun je een beetje opschuiven?","exDe":"Kannst du ein wenig rücken?"}],"usage":"Feste Wendung als abschwächendes Mengenwort/Adverb; wörtl. 'ein Bisschen' (beetje = Diminutiv von beet)."},"bk_400":{"lemma":"al","displayNl":"alle","pos":"voornaamwoord","meanings":[{"de":"alle, sämtliche","ex":"Alle winkels zijn dicht.","exDe":"Alle Läden sind geschlossen."},{"de":"alles (Plural, alle Personen)","ex":"Alle zijn welkom.","exDe":"Alle sind willkommen."}],"usage":"Unbestimmtes Pronomen, Pluralform von 'al'. Vor Substantiven im Plural: 'alle mensen'; Singular 'al de/het'."},"bk_401":{"lemma":"bijna","displayNl":"bijna","pos":"bijwoord","meanings":[{"de":"fast","ex":"Het is bijna zeven uur.","exDe":"Es ist fast sieben Uhr."},{"de":"beinahe, nahezu","ex":"Ik was bijna gevallen.","exDe":"Ich wäre beinahe gefallen."}],"usage":"Adverb der Annäherung; drückt aus, dass etwas knapp nicht erreicht/eingetreten ist."},"bk_402":{"lemma":"sport","displayNl":"de sport","pos":"substantief","meanings":[{"de":"der Sport","ex":"Sport is goed voor je gezondheid.","exDe":"Sport ist gut für deine Gesundheit."},{"de":"die Sportart","ex":"Voetbal is een populaire sport.","exDe":"Fußball ist eine populäre Sportart."},{"de":"die Sprosse (einer Leiter)","ex":"Hij zette zijn voet op de onderste sport van de ladder.","exDe":"Er setzte seinen Fuß auf die unterste Sprosse der Leiter."}],"usage":"de-Wort, Plural 'sporten'. Homonym: meint sowohl Sport/Sportart als auch die Sprosse einer Leiter.","genus":"de","plural":"sporten","illustratable":true},"bk_403":{"lemma":"voetbal","displayNl":"de voetbal","pos":"substantief","meanings":[{"de":"der Fußball (Sportart)","ex":"Wij spelen voetbal in het park.","exDe":"Wir spielen Fußball im Park."},{"de":"der Fußball (der Ball)","ex":"De voetbal rolde in de sloot.","exDe":"Der Fußball rollte in den Graben."}],"usage":"de-Wort, Plural 'voetballen'. Bezeichnet sowohl die Sportart als auch den Ball selbst.","genus":"de","plural":"voetballen","illustratable":true},"bk_404":{"lemma":"film","displayNl":"de film","pos":"substantief","meanings":[{"de":"der Film (Kino/Spielfilm)","ex":"De film begint om acht uur.","exDe":"Der Film beginnt um acht Uhr."},{"de":"der Film (fotografischer Film)","ex":"Ik moet een nieuwe film in mijn camera doen.","exDe":"Ich muss einen neuen Film in meine Kamera einlegen."}],"usage":"de-Wort, Plural 'films'. Meint den Kinofilm ebenso wie den fotografischen Film.","genus":"de","plural":"films","illustratable":true},"bk_405":{"lemma":"foto","displayNl":"de foto","pos":"substantief","meanings":[{"de":"das Foto, die Fotografie","ex":"Ik maak een foto van het strand.","exDe":"Ich mache ein Foto vom Strand."}],"usage":"de-Wort (nicht 'het'!), Plural 'foto's' mit Apostroph.","genus":"de","plural":"foto's","illustratable":true},"bk_406":{"lemma":"spel","displayNl":"het spel","pos":"substantief","meanings":[{"de":"das Spiel (Brett-/Gesellschaftsspiel)","ex":"Wij spelen een leuk spel.","exDe":"Wir spielen ein schönes Spiel."},{"de":"das Spiel, das Spielen (Handlung/Darbietung)","ex":"Het spel van de acteurs was indrukwekkend.","exDe":"Das Spiel der Schauspieler war beeindruckend."}],"usage":"het-Wort, Plural 'spellen' (Spiele) bzw. 'spelen' (bei Darbietungen/Wettkämpfen). Meint das konkrete Spiel wie auch das Spielen/die Darbietung.","genus":"het","plural":"spellen","illustratable":true},"bk_407":{"lemma":"vlucht","displayNl":"de vlucht","pos":"substantief","meanings":[{"de":"der Flug (mit dem Flugzeug)","ex":"De vlucht duurt twee uur.","exDe":"Der Flug dauert zwei Stunden."},{"de":"die Flucht (das Fliehen)","ex":"De dieven sloegen op de vlucht.","exDe":"Die Diebe ergriffen die Flucht."}],"usage":"de-Wort, Plural 'vluchten'. Homonym: der Flug (Reise per Flugzeug) und die Flucht (das Fliehen, oft 'op de vlucht').","genus":"de","plural":"vluchten","illustratable":true},"bk_408":{"lemma":"wandelen","displayNl":"wandelen","pos":"werkwoord","meanings":[{"de":"spazieren, spazieren gehen","ex":"Wij wandelen door het park.","exDe":"Wir spazieren durch den Park."},{"de":"wandern","ex":"In de zomer wandelen we in de bergen.","exDe":"Im Sommer wandern wir in den Bergen."}],"usage":"Regelmäßiges Verb, Hilfsverb 'hebben' (bei Zielangabe auch 'zijn'). Meint gemütliches Spazieren ebenso wie längeres Wandern.","conjugation":{"presens":{"ik":"wandel","jij":"wandelt","hij":"wandelt","wij":"wandelen"},"imperfectum":{"ik":"wandelde","wij":"wandelden"},"perfectum":{"aux":"hebben","participle":"gewandeld"}},"illustratable":true},"bk_409":{"lemma":"zingen","displayNl":"zingen","pos":"werkwoord","meanings":[{"de":"singen","ex":"De kinderen zingen een lied.","exDe":"Die Kinder singen ein Lied."}],"usage":"Starkes (unregelmäßiges) Verb, Hilfsverb 'hebben'. Vokalwechsel: zingen - zong - gezongen.","conjugation":{"presens":{"ik":"zing","jij":"zingt","hij":"zingt","wij":"zingen"},"imperfectum":{"ik":"zong","wij":"zongen"},"perfectum":{"aux":"hebben","participle":"gezongen"}},"illustratable":true},"bk_410":{"lemma":"hobby","displayNl":"de hobby","pos":"substantief","meanings":[{"de":"das Hobby, die Freizeitbeschäftigung","ex":"Voetbal is mijn favoriete hobby.","exDe":"Fußball ist mein Lieblingshobby."},{"de":"Steckenpferd, Lieblingsbeschäftigung","ex":"Koken is een leuke hobby.","exDe":"Kochen ist ein schönes Hobby."}],"usage":"Plural mit Apostroph-s: hobby's. Man 'heeft' een hobby.","genus":"de","plural":"hobby's"},"bk_411":{"lemma":"gitaar","displayNl":"de gitaar","pos":"substantief","meanings":[{"de":"die Gitarre","ex":"Ik speel gitaar in een band.","exDe":"Ich spiele Gitarre in einer Band."}],"usage":"'gitaar spelen' meist ohne Artikel. Plural: gitaren.","genus":"de","plural":"gitaren","illustratable":true},"bk_412":{"lemma":"bal","displayNl":"de bal","pos":"substantief","meanings":[{"de":"der Ball (Spielball)","ex":"De hond speelt met de bal.","exDe":"Der Hund spielt mit dem Ball."},{"de":"der Ball, das Tanzfest (dann: het bal, Plural: bals)","ex":"Wij gaan naar het bal.","exDe":"Wir gehen zum Ball."}],"usage":"Homonym: 'de bal' = Spielball (Pl. ballen); 'het bal' = Tanzfest (Pl. bals).","genus":"de","plural":"ballen","illustratable":true},"bk_413":{"lemma":"lied","displayNl":"het lied","pos":"substantief","meanings":[{"de":"das Lied","ex":"Dit lied is heel mooi.","exDe":"Dieses Lied ist sehr schön."},{"de":"das Gesangsstück, der Song","ex":"Zij zingt een oud Nederlands lied.","exDe":"Sie singt ein altes niederländisches Lied."}],"usage":"Unregelmäßiger Plural: liederen. Verwandt mit 'liedje' (kleines Lied).","genus":"het","plural":"liederen"},"bk_414":{"lemma":"berg","displayNl":"de berg","pos":"substantief","meanings":[{"de":"der Berg","ex":"Wij houden van de bergen.","exDe":"Wir lieben die Berge."},{"de":"ein Haufen, eine große Menge (bildlich)","ex":"Er ligt een berg was op de vloer.","exDe":"Da liegt ein Haufen Wäsche auf dem Boden."}],"usage":"Eingabe war Plural 'bergen'; Grundform Singular 'de berg'. Bildlich: 'een berg werk' = ein Haufen Arbeit.","genus":"de","plural":"bergen","illustratable":true},"bk_415":{"lemma":"tennis","displayNl":"het tennis","pos":"substantief","meanings":[{"de":"das Tennis (Sportart)","ex":"Ik speel elke week tennis.","exDe":"Ich spiele jede Woche Tennis."}],"usage":"Sportart, meist ohne Artikel gebraucht ('tennis spelen'). Kein Plural.","genus":"het","illustratable":true},"bk_416":{"lemma":"rennen","displayNl":"rennen","pos":"werkwoord","meanings":[{"de":"rennen, laufen (schnell)","ex":"De jongen rent heel snel.","exDe":"Der Junge rennt sehr schnell."},{"de":"eilen, hetzen","ex":"Ik moet rennen om de bus te halen.","exDe":"Ich muss rennen, um den Bus zu erreichen."}],"usage":"Regelmäßig. Mit Richtungsangabe/Ziel steht das Perfekt oft mit 'zijn' (bv. 'ik ben naar huis gerend').","conjugation":{"presens":{"ik":"ren","jij":"rent","hij":"rent","wij":"rennen"},"imperfectum":{"ik":"rende","wij":"renden"},"perfectum":{"aux":"hebben","participle":"gerend"}},"illustratable":true},"bk_417":{"lemma":"camera","displayNl":"de camera","pos":"substantief","meanings":[{"de":"die Kamera, der Fotoapparat","ex":"Ik neem mijn camera mee op reis.","exDe":"Ich nehme meine Kamera mit auf die Reise."},{"de":"die Videokamera / Überwachungskamera","ex":"Er hangt een camera boven de deur.","exDe":"Über der Tür hängt eine Kamera."}],"usage":"Plural mit Apostroph-s: camera's.","genus":"de","plural":"camera's","illustratable":true},"bk_418":{"lemma":"mobiel","displayNl":"de mobiel","pos":"substantief","meanings":[{"de":"das Handy, das Mobiltelefon","ex":"Mijn mobiel is bijna leeg.","exDe":"Mein Handy ist fast leer."},{"de":"das Smartphone (umgangssprachlich)","ex":"Ze kijkt de hele dag op haar mobiel.","exDe":"Sie schaut den ganzen Tag auf ihr Handy."}],"usage":"Alltagssprachlich für das Handy; formeller auch 'de mobiele telefoon' oder 'het mobieltje'. 'mobiel' ist außerdem ein Adjektiv (beweglich/mobil).","genus":"de","plural":"mobiels","illustratable":true},"bk_419":{"lemma":"internet","displayNl":"het internet","pos":"substantief","meanings":[{"de":"das Internet","ex":"Ik zoek het op internet.","exDe":"Ich suche es im Internet."},{"de":"der Internetzugang, die Online-Verbindung","ex":"We hebben thuis geen internet meer.","exDe":"Wir haben zu Hause kein Internet mehr."}],"usage":"Meist ohne Artikel im Ausdruck 'op internet' (im Internet); mit Artikel 'het internet' als Gesamtbegriff. Kein Plural.","genus":"het"},"bk_420":{"lemma":"app","displayNl":"de app","pos":"substantief","meanings":[{"de":"die App, die Anwendung (auf Handy/Computer)","ex":"Ik download een nieuwe app.","exDe":"Ich lade eine neue App herunter."}],"usage":"Kurzform von 'applicatie'. Plural 'apps'. Aus dem Englischen entlehnt.","genus":"de","plural":"apps"},"bk_421":{"lemma":"website","displayNl":"de website","pos":"substantief","meanings":[{"de":"die Webseite, die Website","ex":"De website is heel mooi.","exDe":"Die Webseite ist sehr schön."}],"usage":"Auch 'de site'; das einzelne Dokument heisst 'de webpagina'. Plural 'websites'.","genus":"de","plural":"websites"},"bk_422":{"lemma":"e-mail","displayNl":"de e-mail","pos":"substantief","meanings":[{"de":"die E-Mail (Nachricht)","ex":"Ik schrijf een e-mail.","exDe":"Ich schreibe eine E-Mail."},{"de":"die E-Mail-Adresse","ex":"Wat is jouw e-mail?","exDe":"Wie lautet deine E-Mail-Adresse?"}],"usage":"Mit Bindestrich geschrieben; das Medium auch 'de mail'. Verb: 'e-mailen'. Plural 'e-mails'.","genus":"de","plural":"e-mails"},"bk_423":{"lemma":"tv","displayNl":"de tv","pos":"substantief","meanings":[{"de":"der Fernseher, das Fernsehgerät","ex":"De tv staat in de woonkamer.","exDe":"Der Fernseher steht im Wohnzimmer."},{"de":"das Fernsehen (Medium); 'tv kijken' = fernsehen","ex":"Wij kijken tv.","exDe":"Wir schauen fern."}],"usage":"Kurzform von 'televisie'. Plural 'tv's' (Geräte). In 'tv kijken' ohne Artikel = fernsehen.","genus":"de","plural":"tv's","illustratable":true},"bk_424":{"lemma":"krant","displayNl":"de krant","pos":"substantief","meanings":[{"de":"die Zeitung","ex":"Opa leest de krant.","exDe":"Opa liest die Zeitung."}],"usage":"Auch 'het dagblad'. Plural 'kranten'.","genus":"de","plural":"kranten","illustratable":true},"bk_425":{"lemma":"bericht","displayNl":"het bericht","pos":"substantief","meanings":[{"de":"die Nachricht (z. B. per Handy/Chat)","ex":"Ik stuur een bericht.","exDe":"Ich schicke eine Nachricht."},{"de":"die Meldung, die Mitteilung (z. B. in den Medien)","ex":"Er staat een bericht over de storm in de krant.","exDe":"In der Zeitung steht eine Meldung über den Sturm."}],"usage":"Achtung: 'bericht' = Nachricht/Meldung, NICHT der deutsche 'Bericht' (das ist 'verslag'). Plural 'berichten'.","genus":"het","plural":"berichten"},"bk_426":{"lemma":"scherm","displayNl":"het scherm","pos":"substantief","meanings":[{"de":"der Bildschirm","ex":"Het scherm van mijn telefoon is gebarsten.","exDe":"Der Bildschirm meines Handys ist gesprungen."},{"de":"die Leinwand (Kino/Projektion)","ex":"De film wordt op een groot scherm getoond.","exDe":"Der Film wird auf einer großen Leinwand gezeigt."},{"de":"der Schirm / die Abschirmung, der Wandschirm","ex":"Achter het scherm kleedde de patiënt zich om.","exDe":"Hinter dem Wandschirm zog sich der Patient um."}],"usage":"Alltagswort für den Anzeigebereich von Geräten (telefoon, laptop, tv). Übertragen auch Kinoleinwand und Trenn-/Wandschirm.","genus":"het","plural":"schermen","illustratable":true},"bk_427":{"lemma":"laptop","displayNl":"de laptop","pos":"substantief","meanings":[{"de":"der Laptop, das Notebook","ex":"Mijn laptop is oud en traag.","exDe":"Mein Laptop ist alt und langsam."}],"usage":"Tragbarer Computer; Alltags-/Arbeitsvokabel. Alternativ auch draagbare computer.","genus":"de","plural":"laptops","illustratable":true},"bk_428":{"lemma":"kabel","displayNl":"de kabel","pos":"substantief","meanings":[{"de":"das Kabel (Strom-/Datenkabel)","ex":"De kabel van de oplader is te kort.","exDe":"Das Kabel des Ladegeräts ist zu kurz."},{"de":"das Tau / die Trosse (dickes Seil)","ex":"De boot lag met een dikke kabel aan de kade.","exDe":"Das Boot lag mit einer dicken Trosse an der Kaimauer."}],"usage":"Meist elektrisches Kabel; auch dickes Drahtseil/Tau. Diminutiv kabeltje.","genus":"de","plural":"kabels","illustratable":true},"bk_429":{"lemma":"sturen","displayNl":"sturen","pos":"werkwoord","meanings":[{"de":"schicken, senden","ex":"Kun je de foto naar mij sturen?","exDe":"Kannst du das Foto an mich schicken?"},{"de":"steuern, lenken","ex":"Hij stuurt de boot voorzichtig de haven in.","exDe":"Er steuert das Boot vorsichtig in den Hafen."}],"usage":"Regelmäßiges Verb. Bedeutung 1 (versenden) sehr häufig; Bedeutung 2 (lenken/steuern, auch übertragen: bijsturen).","conjugation":{"presens":{"ik":"stuur","jij":"stuurt","hij":"stuurt","wij":"sturen"},"imperfectum":{"ik":"stuurde","wij":"stuurden"},"perfectum":{"aux":"hebben","participle":"gestuurd"}}},"bk_430":{"lemma":"aanzetten","displayNl":"aanzetten","pos":"werkwoord","meanings":[{"de":"anschalten, einschalten","ex":"Ik zet de computer aan.","exDe":"Ich schalte den Computer an."},{"de":"antreiben, anregen (zu etw. bewegen: aanzetten tot)","ex":"De leraar zette ons aan tot nadenken.","exDe":"Der Lehrer regte uns zum Nachdenken an."}],"usage":"Trennbares Verb (zet ... aan). Häufigste Bedeutung: ein Gerät einschalten; übertragen aanzetten tot iets = zu etwas bewegen.","conjugation":{"presens":{"ik":"zet aan","jij":"zet aan","hij":"zet aan","wij":"zetten aan"},"imperfectum":{"ik":"zette aan","wij":"zetten aan"},"perfectum":{"aux":"hebben","participle":"aangezet"}}},"bk_431":{"lemma":"uitzetten","displayNl":"uitzetten","pos":"werkwoord","meanings":[{"de":"ausschalten, ausmachen","ex":"Zet de tv uit, alsjeblieft.","exDe":"Schalte den Fernseher aus, bitte."},{"de":"abstecken, ausstecken (eine Strecke/Route festlegen)","ex":"We zetten de route voor de wandeling uit.","exDe":"Wir stecken die Route für die Wanderung ab."},{"de":"ausweisen, abschieben (jdn. des Landes verweisen)","ex":"De man werd het land uitgezet.","exDe":"Der Mann wurde des Landes verwiesen."}],"usage":"Trennbares Verb (zet ... uit). Gegenteil von aanzetten; daneben Bedeutungen abstecken (Route) und ausweisen.","conjugation":{"presens":{"ik":"zet uit","jij":"zet uit","hij":"zet uit","wij":"zetten uit"},"imperfectum":{"ik":"zette uit","wij":"zetten uit"},"perfectum":{"aux":"hebben","participle":"uitgezet"}}},"bk_432":{"lemma":"blij","displayNl":"blij","pos":"adjectief","meanings":[{"de":"froh, fröhlich","ex":"Ik ben heel blij vandaag.","exDe":"Ich bin heute sehr froh."},{"de":"froh über etwas (blij met/om)","ex":"Ze is heel blij met haar cadeau.","exDe":"Sie freut sich sehr über ihr Geschenk."}],"usage":"Gefühlsadjektiv; blij met + Sache, blij om te + Infinitiv, blij dat + Satz. Kein Umlaut, unveränderlich blij/blije."},"bk_433":{"lemma":"gelukkig","displayNl":"gelukkig","pos":"adjectief","meanings":[{"de":"glücklich, zufrieden","ex":"Wij zijn samen gelukkig.","exDe":"Wir sind zusammen glücklich."},{"de":"glücklicherweise, zum Glück (als Adverb)","ex":"Gelukkig regende het niet.","exDe":"Zum Glück regnete es nicht."}],"usage":"Als Adjektiv 'glücklich' (tiefer/dauerhafter als blij); als Satzadverb 'glücklicherweise'."},"bk_435":{"lemma":"boos","displayNl":"boos","pos":"adjectief","meanings":[{"de":"wütend, verärgert, böse (auf jdn.)","ex":"Papa is boos op mij.","exDe":"Papa ist wütend auf mich."},{"de":"böse, arglistig (gehoben, selten)","ex":"Hij had geen boze bedoelingen.","exDe":"Er hatte keine bösen Absichten."}],"usage":"Prädikativ meist mit 'op' + Person ('boos op iemand zijn') oder 'over/om' + Sache ('boos over iets'). Attributiv gebeugt: 'een boze man'.","notes":"Steigerung: bozer, boost."},"bk_437":{"lemma":"slecht","displayNl":"slecht","pos":"adjectief","meanings":[{"de":"schlecht, minderwertig (Qualität)","ex":"Dit is een slecht boek.","exDe":"Das ist ein schlechtes Buch."},{"de":"unwohl, schlecht (Befinden)","ex":"Ik voel me slecht.","exDe":"Ich fühle mich schlecht."},{"de":"böse, schlecht (moralisch)","ex":"Hij is geen slecht mens.","exDe":"Er ist kein schlechter Mensch."}],"usage":"Attributiv gebeugt: 'een slechte dag'. Auch adverbial: 'Hij zingt slecht'. Steigerung: slechter, slechtst."},"bk_438":{"lemma":"lief","displayNl":"lief","pos":"adjectief","meanings":[{"de":"lieb, nett, freundlich","ex":"Wat ben jij lief!","exDe":"Wie lieb du bist!"},{"de":"süß, niedlich","ex":"Wat een lief hondje.","exDe":"Was für ein süßes Hündchen."}],"usage":"Attributiv gebeugt: 'een lieve vrouw'. Steigerung: liever, liefst. 'Het liefst' = am liebsten."},"bk_439":{"lemma":"lelijk","displayNl":"lelijk","pos":"adjectief","meanings":[{"de":"hässlich, unschön","ex":"Dat huis is lelijk.","exDe":"Das Haus ist hässlich."},{"de":"übel, schlimm, böse (Sturz, Wunde)","ex":"Hij maakte een lelijke val.","exDe":"Er machte einen üblen Sturz."}],"usage":"Attributiv gebeugt: 'een lelijk gebouw'. Auch adverbial: 'zich lelijk vergissen' (sich gewaltig irren). Steigerung: lelijker, lelijkst."},"bk_440":{"lemma":"vervelend","displayNl":"vervelend","pos":"adjectief","meanings":[{"de":"lästig, ärgerlich, unangenehm","ex":"Dat is echt vervelend.","exDe":"Das ist wirklich ärgerlich."},{"de":"langweilig, öde","ex":"Het was een vervelende film.","exDe":"Es war ein langweiliger Film."}],"usage":"Attributiv gebeugt: 'een vervelende situatie'. Ursprünglich Partizip von 'vervelen' (langweilen). Steigerung: vervelender, vervelendst."},"bk_441":{"lemma":"grappig","displayNl":"grappig","pos":"adjectief","meanings":[{"de":"lustig, witzig, spaßig","ex":"Hij is een grappige man.","exDe":"Er ist ein lustiger Mann."},{"de":"komisch, merkwürdig (im positiven Sinn)","ex":"Grappig genoeg werkte het toch.","exDe":"Komischerweise funktionierte es doch."}],"usage":"Attributiv gebeugt: 'een grappig verhaal'. Abgeleitet von 'grap' (Witz). Steigerung: grappiger, grappigst."},"bk_442":{"lemma":"rustig","displayNl":"rustig","pos":"adjectief","meanings":[{"de":"ruhig, still, gelassen","ex":"Blijf rustig, alles is oké.","exDe":"Bleib ruhig, alles ist okay."},{"de":"ruhig, wenig los (Ort, Zeit)","ex":"Het is rustig in de winkel vandaag.","exDe":"Im Laden ist heute wenig los."}],"usage":"Attributiv gebeugt: 'een rustige buurt'. Auch adverbial: 'rustig aan doen' (es ruhig angehen). Steigerung: rustiger, rustigst."},"bk_443":{"lemma":"dom","displayNl":"dom","pos":"adjectief","meanings":[{"de":"dumm, unintelligent","ex":"Doe niet zo dom.","exDe":"Sei nicht so dumm."},{"de":"unklug, töricht, ungeschickt (Handlung)","ex":"Dat was een domme fout.","exDe":"Das war ein dummer Fehler."}],"usage":"Attributiv gebeugt: 'een domme vraag'. Steigerung: dommer, domst.","notes":"Homonym: 'de dom' ist auch ein Substantiv (Dom, Kathedrale), z. B. 'de Dom van Utrecht' - hier aber als Adjektiv (dumm) erfasst."},"bk_444":{"lemma":"vrolijk","displayNl":"vrolijk","pos":"adjectief","meanings":[{"de":"fröhlich, heiter","ex":"Zij is altijd vrolijk.","exDe":"Sie ist immer fröhlich."},{"de":"vergnügt, gut gelaunt","ex":"Het was een vrolijk feest.","exDe":"Es war ein fröhliches Fest."}],"usage":"Gebruikelijk bijvoeglijk naamwoord; verbogen 'vrolijke' (een vrolijk kind, de vrolijke mensen)."},"bk_445":{"lemma":"verlegen","displayNl":"verlegen","pos":"adjectief","meanings":[{"de":"schüchtern, verlegen","ex":"Het jongetje is verlegen.","exDe":"Der kleine Junge ist schüchtern."},{"de":"in Verlegenheit; um etwas verlegen (verlegen om/zitten)","ex":"Ik zit verlegen om hulp.","exDe":"Ich bin um Hilfe verlegen."}],"usage":"Bijvoeglijk naamwoord; 'verlegen om iets zijn' = etwas dringend brauchen. Vorm 'verlegen' blijft ook verbogen gelijk."},"bk_446":{"lemma":"trots","displayNl":"trots","pos":"adjectief","meanings":[{"de":"stolz","ex":"Ik ben trots op jou.","exDe":"Ich bin stolz auf dich."},{"de":"der Stolz (als Substantiv, de trots)","ex":"Zijn zoon is zijn grootste trots.","exDe":"Sein Sohn ist sein größter Stolz."}],"usage":"Adjectief met vaste combinatie 'trots op'. Homoniem: ook zelfstandig naamwoord 'de trots'."},"bk_448":{"lemma":"voelen","displayNl":"voelen","pos":"werkwoord","meanings":[{"de":"sich fühlen (reflexiv, zich voelen)","ex":"Ik voel me niet lekker.","exDe":"Ich fühle mich nicht wohl."},{"de":"fühlen, empfinden","ex":"Ik voel pijn in mijn arm.","exDe":"Ich fühle Schmerzen in meinem Arm."},{"de":"(be)tasten, spüren","ex":"Voel eens hoe zacht deze stof is.","exDe":"Fühl mal, wie weich dieser Stoff ist."}],"usage":"Regelmatig werkwoord, vaak reflexief 'zich voelen'.","conjugation":{"presens":{"ik":"voel","jij":"voelt","hij":"voelt","wij":"voelen"},"imperfectum":{"ik":"voelde","wij":"voelden"},"perfectum":{"aux":"hebben","participle":"gevoeld"}}},"bk_449":{"lemma":"houden","displayNl":"houden van","pos":"werkwoord","meanings":[{"de":"lieben, mögen, gern haben (houden van)","ex":"Ik houd van muziek.","exDe":"Ich liebe Musik."},{"de":"halten, festhalten","ex":"Kun je mijn tas even vasthouden?","exDe":"Kannst du kurz meine Tasche halten?"},{"de":"behalten, aufbewahren","ex":"Je mag het boek houden.","exDe":"Du darfst das Buch behalten."},{"de":"einhalten (zich houden aan)","ex":"Wij houden ons aan de afspraak.","exDe":"Wir halten uns an die Abmachung."}],"usage":"Onregelmatig werkwoord; in de betekenis 'lieben/mögen' altijd met vast voorzetsel 'van' (houden van). 'ik houd' of spreektalig 'ik hou'.","conjugation":{"presens":{"ik":"houd","jij":"houdt","hij":"houdt","wij":"houden"},"imperfectum":{"ik":"hield","wij":"hielden"},"perfectum":{"aux":"hebben","participle":"gehouden"}}},"bk_450":{"lemma":"lachen","displayNl":"lachen","pos":"werkwoord","meanings":[{"de":"lachen","ex":"Wij lachen veel samen.","exDe":"Wir lachen viel zusammen."},{"de":"lachen über, sich lustig machen (lachen om)","ex":"Iedereen lachte om zijn grap.","exDe":"Alle lachten über seinen Witz."}],"usage":"Regelmatig werkwoord; 'lachen om iets' = über etwas lachen.","conjugation":{"presens":{"ik":"lach","jij":"lacht","hij":"lacht","wij":"lachen"},"imperfectum":{"ik":"lachte","wij":"lachten"},"perfectum":{"aux":"hebben","participle":"gelachen"}},"illustratable":true},"bk_451":{"lemma":"huilen","displayNl":"huilen","pos":"werkwoord","meanings":[{"de":"weinen","ex":"De baby begint te huilen.","exDe":"Das Baby fängt an zu weinen."},{"de":"heulen (Wind, Tier)","ex":"De wind huilt om het huis.","exDe":"Der Wind heult ums Haus."}],"usage":"Regelmatig werkwoord; ook figuurlijk voor huilende wind of dieren.","conjugation":{"presens":{"ik":"huil","jij":"huilt","hij":"huilt","wij":"huilen"},"imperfectum":{"ik":"huilde","wij":"huilden"},"perfectum":{"aux":"hebben","participle":"gehuild"}},"illustratable":true},"bk_452":{"lemma":"zijn","displayNl":"zijn","pos":"werkwoord","meanings":[{"de":"sein (Hilfs- und Vollverb)","ex":"Ik ben moe.","exDe":"Ich bin müde."},{"de":"sein / seine (Possessivpronomen; homoniem 'zijn')","ex":"Dat is zijn fiets.","exDe":"Das ist sein Fahrrad."}],"usage":"Sterk onregelmatig werkwoord; perfectum met 'zijn' (ik ben geweest). Homoniem: bezittelijk voornaamwoord 'zijn' (sein).","conjugation":{"presens":{"ik":"ben","jij":"bent","hij":"is","wij":"zijn"},"imperfectum":{"ik":"was","wij":"waren"},"perfectum":{"aux":"zijn","participle":"geweest"}}},"bk_453":{"lemma":"hebben","displayNl":"hebben","pos":"werkwoord","meanings":[{"de":"haben, besitzen","ex":"Ik heb een hond.","exDe":"Ich habe einen Hund."},{"de":"haben, empfinden (Zustand/Gefühl)","ex":"Ik heb honger.","exDe":"Ich habe Hunger."},{"de":"haben (Hilfsverb für das Perfekt)","ex":"Ik heb gegeten.","exDe":"Ich habe gegessen."}],"usage":"Sehr häufiges, unregelmäßiges Verb; zugleich Hilfsverb im Perfekt. Beachte: jij hebt, hij/zij heeft.","conjugation":{"presens":{"ik":"heb","jij":"hebt","hij":"heeft","wij":"hebben"},"imperfectum":{"ik":"had","wij":"hadden"},"perfectum":{"aux":"hebben","participle":"gehad"}}},"bk_454":{"lemma":"doen","displayNl":"doen","pos":"werkwoord","meanings":[{"de":"tun, machen","ex":"Wat doe je?","exDe":"Was machst du?"},{"de":"tun, erledigen (eine Tätigkeit ausführen)","ex":"Ik doe de afwas.","exDe":"Ich mache den Abwasch."},{"de":"sich verhalten, sich benehmen","ex":"Doe niet zo raar.","exDe":"Benimm dich nicht so komisch."}],"usage":"Unregelmäßiges Verb. Häufig in Fragen nach Tätigkeit/Beruf: Wat doe je? Partizip: gedaan.","conjugation":{"presens":{"ik":"doe","jij":"doet","hij":"doet","wij":"doen"},"imperfectum":{"ik":"deed","wij":"deden"},"perfectum":{"aux":"hebben","participle":"gedaan"}}},"bk_456":{"lemma":"zien","displayNl":"zien","pos":"werkwoord","meanings":[{"de":"sehen","ex":"Ik zie je morgen.","exDe":"Ich sehe dich morgen."},{"de":"einsehen, verstehen, erkennen","ex":"Ik zie het probleem niet.","exDe":"Ich sehe das Problem nicht."},{"de":"aussehen (er uitzien)","ex":"Je ziet er moe uit.","exDe":"Du siehst müde aus."}],"usage":"Unregelmäßiges Verb. Imperfekt: zag/zagen; Partizip: gezien. In fester Fügung: eruitzien = aussehen.","conjugation":{"presens":{"ik":"zie","jij":"ziet","hij":"ziet","wij":"zien"},"imperfectum":{"ik":"zag","wij":"zagen"},"perfectum":{"aux":"hebben","participle":"gezien"}}},"bk_458":{"lemma":"zeggen","displayNl":"zeggen","pos":"werkwoord","meanings":[{"de":"sagen","ex":"Wat zeg je?","exDe":"Was sagst du?"},{"de":"bedeuten, besagen","ex":"Dat zegt me niets.","exDe":"Das sagt mir nichts."}],"usage":"Unregelmäßiges Verb. Singular-Imperfekt: zei; Plural: zeiden. Partizip: gezegd.","conjugation":{"presens":{"ik":"zeg","jij":"zegt","hij":"zegt","wij":"zeggen"},"imperfectum":{"ik":"zei","wij":"zeiden"},"perfectum":{"aux":"hebben","participle":"gezegd"}}},"bk_460":{"lemma":"staan","displayNl":"staan","pos":"werkwoord","meanings":[{"de":"stehen","ex":"Ik sta bij de deur.","exDe":"Ich stehe an der Tür."},{"de":"stehen, geschrieben sein (in einem Text)","ex":"Het staat in de krant.","exDe":"Es steht in der Zeitung."},{"de":"stehen, passen (Kleidung)","ex":"Die jurk staat je goed.","exDe":"Das Kleid steht dir gut."}],"usage":"Unregelmäßiges Verb. Imperfekt: stond/stonden; Partizip: gestaan. Positionsverb.","conjugation":{"presens":{"ik":"sta","jij":"staat","hij":"staat","wij":"staan"},"imperfectum":{"ik":"stond","wij":"stonden"},"perfectum":{"aux":"hebben","participle":"gestaan"}},"illustratable":true},"bk_461":{"lemma":"zitten","displayNl":"zitten","pos":"werkwoord","meanings":[{"de":"sitzen","ex":"Wij zitten op de bank.","exDe":"Wir sitzen auf dem Sofa."},{"de":"sich befinden, stecken (irgendwo drin sein)","ex":"Mijn sleutel zit in mijn tas.","exDe":"Mein Schlüssel steckt in meiner Tasche."},{"de":"passen, sitzen (Kleidung am Körper)","ex":"Die broek zit lekker.","exDe":"Die Hose sitzt bequem."}],"usage":"Unregelmäßiges Verb. Imperfekt: zat/zaten; Partizip: gezeten. Positionsverb, oft auch im Sinne von 'sich befinden'.","conjugation":{"presens":{"ik":"zit","jij":"zit","hij":"zit","wij":"zitten"},"imperfectum":{"ik":"zat","wij":"zaten"},"perfectum":{"aux":"hebben","participle":"gezeten"}},"illustratable":true},"bk_462":{"lemma":"liggen","displayNl":"liggen","pos":"werkwoord","meanings":[{"de":"liegen","ex":"De kat ligt op bed.","exDe":"Die Katze liegt auf dem Bett."},{"de":"liegen, sich befinden (Lage eines Ortes)","ex":"Utrecht ligt in Nederland.","exDe":"Utrecht liegt in den Niederlanden."},{"de":"liegen an, die Ursache sein","ex":"Het ligt aan jou.","exDe":"Es liegt an dir."}],"usage":"Unregelmäßiges Verb. Imperfekt: lag/lagen; Partizip: gelegen. Positionsverb; auch für geografische Lage.","conjugation":{"presens":{"ik":"lig","jij":"ligt","hij":"ligt","wij":"liggen"},"imperfectum":{"ik":"lag","wij":"lagen"},"perfectum":{"aux":"hebben","participle":"gelegen"}},"illustratable":true},"bk_464":{"lemma":"nemen","displayNl":"nemen","pos":"werkwoord","meanings":[{"de":"nehmen","ex":"Ik neem de bus.","exDe":"Ich nehme den Bus."},{"de":"nehmen, bestellen/wählen","ex":"Ik neem een koffie.","exDe":"Ich nehme einen Kaffee."},{"de":"nehmen, ergreifen/an sich nehmen","ex":"Neem je jas mee.","exDe":"Nimm deine Jacke mit."}],"usage":"Unregelmäßiges Verb. Imperfekt: nam/namen; Partizip: genomen. Häufig für Verkehrsmittel und Bestellungen.","conjugation":{"presens":{"ik":"neem","jij":"neemt","hij":"neemt","wij":"nemen"},"imperfectum":{"ik":"nam","wij":"namen"},"perfectum":{"aux":"hebben","participle":"genomen"}}},"bk_465":{"lemma":"krijgen","displayNl":"krijgen","pos":"werkwoord","meanings":[{"de":"bekommen, erhalten","ex":"Ik krijg een cadeau voor mijn verjaardag.","exDe":"Ich bekomme ein Geschenk zu meinem Geburtstag."},{"de":"kriegen (umgangssprachlich), erwischen","ex":"Wacht, dan krijg ik je nog wel!","exDe":"Warte, dann kriege ich dich noch!"},{"de":"(eine Krankheit, ein Gefühl) bekommen","ex":"Ze krijgt vaak griep in de herfst.","exDe":"Sie bekommt im Herbst oft eine Grippe."}],"usage":"Sehr häufiges unregelmäßiges Verb für bekommen/erhalten. jij krijgt, aber bei Inversion: krijg jij.","conjugation":{"presens":{"ik":"krijg","jij":"krijgt","hij":"krijgt","wij":"krijgen"},"imperfectum":{"ik":"kreeg","wij":"kregen"},"perfectum":{"aux":"hebben","participle":"gekregen"}}},"bk_466":{"lemma":"brengen","displayNl":"brengen","pos":"werkwoord","meanings":[{"de":"bringen, hinbringen","ex":"Ik breng de boeken naar de bibliotheek.","exDe":"Ich bringe die Bücher zur Bibliothek."},{"de":"begleiten, jemanden hinbringen","ex":"Ik breng je met de fiets naar huis.","exDe":"Ich bringe dich mit dem Fahrrad nach Hause."}],"usage":"Unregelmäßig: bracht – gebracht. Gegenstück zu halen (holen).","conjugation":{"presens":{"ik":"breng","jij":"brengt","hij":"brengt","wij":"brengen"},"imperfectum":{"ik":"bracht","wij":"brachten"},"perfectum":{"aux":"hebben","participle":"gebracht"}},"illustratable":true},"bk_467":{"lemma":"halen","displayNl":"halen","pos":"werkwoord","meanings":[{"de":"holen","ex":"Ik haal even melk uit de winkel.","exDe":"Ich hole kurz Milch aus dem Laden."},{"de":"abholen","ex":"Zij haalt de kinderen van school.","exDe":"Sie holt die Kinder von der Schule ab."},{"de":"erreichen, schaffen, erwischen (Zug, Note)","ex":"Ik haal de trein van negen uur nog net.","exDe":"Ich erwische den Zug um neun gerade noch."}],"usage":"Regelmäßiges Verb. Wichtig auch idiomatisch: een cijfer halen (eine Note erreichen), de trein halen (den Zug erwischen).","conjugation":{"presens":{"ik":"haal","jij":"haalt","hij":"haalt","wij":"halen"},"imperfectum":{"ik":"haalde","wij":"haalden"},"perfectum":{"aux":"hebben","participle":"gehaald"}},"illustratable":true},"bk_468":{"lemma":"weten","displayNl":"weten","pos":"werkwoord","meanings":[{"de":"wissen","ex":"Ik weet het antwoord niet.","exDe":"Ich weiß die Antwort nicht."},{"de":"Bescheid wissen, kennen (Fakten)","ex":"Weet jij hoe laat de winkel opengaat?","exDe":"Weißt du, wann der Laden aufmacht?"}],"usage":"Unregelmäßig: wist – geweten. jij weet (Stamm endet schon auf -t, kein zweites -t). Abstraktes mentales Verb.","conjugation":{"presens":{"ik":"weet","jij":"weet","hij":"weet","wij":"weten"},"imperfectum":{"ik":"wist","wij":"wisten"},"perfectum":{"aux":"hebben","participle":"geweten"}}},"bk_470":{"lemma":"kunnen","displayNl":"kunnen","pos":"werkwoord","meanings":[{"de":"können (Fähigkeit)","ex":"Ik kan al goed zwemmen.","exDe":"Ich kann schon gut schwimmen."},{"de":"können, möglich sein","ex":"Dat kan morgen misschien.","exDe":"Das ist vielleicht morgen möglich."},{"de":"dürfen, gehen (umgangssprachlich möglich)","ex":"Kan ik hier parkeren?","exDe":"Kann ich hier parken?"}],"usage":"Modalverb, unregelmäßig: kon – gekund. jij kunt oder jij kan (beide gängig). Als Modalverb steht das Vollverb im Infinitiv.","conjugation":{"presens":{"ik":"kan","jij":"kunt","hij":"kan","wij":"kunnen"},"imperfectum":{"ik":"kon","wij":"konden"},"perfectum":{"aux":"hebben","participle":"gekund"}}},"bk_473":{"lemma":"leven","displayNl":"leven","pos":"werkwoord","meanings":[{"de":"leben, am Leben sein","ex":"Mijn opa leeft nog.","exDe":"Mein Opa lebt noch."},{"de":"leben (auf bestimmte Weise), wohnen","ex":"Wij leven samen in Utrecht.","exDe":"Wir leben zusammen in Utrecht."}],"usage":"Regelmäßig; v/f-Wechsel: leven, aber ik leef, geleefd. Abstrakt (Zustand des Lebens).","conjugation":{"presens":{"ik":"leef","jij":"leeft","hij":"leeft","wij":"leven"},"imperfectum":{"ik":"leefde","wij":"leefden"},"perfectum":{"aux":"hebben","participle":"geleefd"}}},"bk_474":{"lemma":"roepen","displayNl":"roepen","pos":"werkwoord","meanings":[{"de":"rufen","ex":"Hij roept mijn naam over het plein.","exDe":"Er ruft meinen Namen über den Platz."},{"de":"ausrufen, laut schreien","ex":"De kinderen roepen van blijdschap.","exDe":"Die Kinder schreien vor Freude."}],"usage":"Unregelmäßig (stark): riep – geroepen.","conjugation":{"presens":{"ik":"roep","jij":"roept","hij":"roept","wij":"roepen"},"imperfectum":{"ik":"riep","wij":"riepen"},"perfectum":{"aux":"hebben","participle":"geroepen"}},"illustratable":true},"bk_475":{"lemma":"vertellen","displayNl":"vertellen","pos":"werkwoord","meanings":[{"de":"erzählen","ex":"Ik vertel de kinderen een verhaal.","exDe":"Ich erzähle den Kindern eine Geschichte."},{"de":"berichten, mitteilen","ex":"Zij vertelt me wat er gebeurd is.","exDe":"Sie berichtet mir, was passiert ist."}],"usage":"Regelmäßig, untrennbares Präfix ver-: Partizip ohne ge-, also verteld.","conjugation":{"presens":{"ik":"vertel","jij":"vertelt","hij":"vertelt","wij":"vertellen"},"imperfectum":{"ik":"vertelde","wij":"vertelden"},"perfectum":{"aux":"hebben","participle":"verteld"}},"illustratable":true},"bk_476":{"lemma":"blijven","displayNl":"blijven","pos":"werkwoord","meanings":[{"de":"bleiben (an einem Ort verweilen)","ex":"Ik blijf vanavond thuis.","exDe":"Ich bleibe heute Abend zu Hause."},{"de":"bleiben (in einem Zustand verharren)","ex":"Blijf alsjeblieft rustig.","exDe":"Bleib bitte ruhig."},{"de":"übrig bleiben","ex":"Er blijft niets van de taart over.","exDe":"Vom Kuchen bleibt nichts übrig."}],"usage":"Unregelmäßiges Verb; Perfekt mit 'zijn'. Sehr häufiges Alltagswort.","conjugation":{"presens":{"ik":"blijf","jij":"blijft","hij":"blijft","wij":"blijven"},"imperfectum":{"ik":"bleef","wij":"bleven"},"perfectum":{"aux":"zijn","participle":"gebleven"}}},"bk_477":{"lemma":"gebruiken","displayNl":"gebruiken","pos":"werkwoord","meanings":[{"de":"benutzen, verwenden","ex":"Ik gebruik mijn telefoon voor alles.","exDe":"Ich benutze mein Handy für alles."},{"de":"einnehmen (Medikamente, Drogen)","ex":"Hij gebruikt elke dag medicijnen.","exDe":"Er nimmt jeden Tag Medikamente ein."},{"de":"zu sich nehmen, verzehren (Speisen)","ex":"Wilt u nog iets gebruiken?","exDe":"Möchten Sie noch etwas zu sich nehmen?"}],"usage":"Regelmäßiges Verb; das 'ge-' gehört zum Stamm, daher Partizip 'gebruikt' ohne zusätzliches Präfix. Perfekt mit 'hebben'.","conjugation":{"presens":{"ik":"gebruik","jij":"gebruikt","hij":"gebruikt","wij":"gebruiken"},"imperfectum":{"ik":"gebruikte","wij":"gebruikten"},"perfectum":{"aux":"hebben","participle":"gebruikt"}}},"bk_481":{"lemma":"lang","displayNl":"lang","pos":"adjectief","meanings":[{"de":"lang (zeitliche Dauer)","ex":"De film is erg lang.","exDe":"Der Film ist sehr lang."},{"de":"lang (räumliche Ausdehnung)","ex":"Dit is een lange straat.","exDe":"Das ist eine lange Straße."},{"de":"groß, hochgewachsen (von Personen)","ex":"Mijn broer is heel lang.","exDe":"Mein Bruder ist sehr groß."}],"usage":"Gegenteil: 'kort'. Bei Personen bedeutet 'lang' 'groß' (nicht 'groot')."},"bk_482":{"lemma":"kort","displayNl":"kort","pos":"adjectief","meanings":[{"de":"kurz (räumlich)","ex":"Het is een korte weg naar huis.","exDe":"Es ist ein kurzer Weg nach Hause."},{"de":"kurz (zeitlich)","ex":"We nemen een korte pauze.","exDe":"Wir machen eine kurze Pause."}],"usage":"Gegenteil: 'lang'. Flektiert: 'korte'."},"bk_483":{"lemma":"hoog","displayNl":"hoog","pos":"adjectief","meanings":[{"de":"hoch (Höhe, räumlich)","ex":"De berg is heel hoog.","exDe":"Der Berg ist sehr hoch."},{"de":"hoch (Zahl, Preis, Wert)","ex":"De prijs is te hoog.","exDe":"Der Preis ist zu hoch."},{"de":"hoch (Ton, Stimme)","ex":"Zij zingt met een hoge stem.","exDe":"Sie singt mit einer hohen Stimme."}],"usage":"Gegenteil: 'laag'. Flektiert wird der Vokal kurz: 'hoge'."},"bk_485":{"lemma":"langzaam","displayNl":"langzaam","pos":"adjectief","meanings":[{"de":"langsam","ex":"Hij loopt heel langzaam.","exDe":"Er läuft sehr langsam."},{"de":"allmählich, nach und nach","ex":"Het wordt langzaam beter.","exDe":"Es wird allmählich besser."}],"usage":"Gegenteil: 'snel'. Wird attributiv ('langzame') und adverbial verwendet."},"bk_486":{"lemma":"vol","displayNl":"vol","pos":"adjectief","meanings":[{"de":"voll (gefüllt)","ex":"De bus is helemaal vol.","exDe":"Der Bus ist ganz voll."},{"de":"voll, besetzt (kein Platz mehr)","ex":"Het restaurant is vanavond vol.","exDe":"Das Restaurant ist heute Abend voll."}],"usage":"Gegenteil: 'leeg'. Konstruktion 'vol met/van' = 'voll mit'."},"bk_487":{"lemma":"leeg","displayNl":"leeg","pos":"adjectief","meanings":[{"de":"leer (nichts enthaltend)","ex":"Het glas is leeg.","exDe":"Das Glas ist leer."},{"de":"leer, menschenleer (unbesetzt)","ex":"De straat is 's nachts leeg.","exDe":"Die Straße ist nachts leer."}],"usage":"Gegenteil: 'vol'. Flektiert: 'lege'."},"bk_489":{"lemma":"dicht","displayNl":"dicht","pos":"adjectief","meanings":[{"de":"geschlossen, zu","ex":"De deur is dicht.","exDe":"Die Tür ist geschlossen."},{"de":"dicht, dicht beieinander, dichtgedrängt","ex":"De bomen staan dicht bij elkaar.","exDe":"Die Bäume stehen dicht beieinander."},{"de":"nah, nahe (dicht bij)","ex":"Het station is dicht bij mijn huis.","exDe":"Der Bahnhof ist nah bei meinem Haus."}],"usage":"Adjektiv/Adverb. Gegenteil von 'open'. In 'dicht bij' = nah bei."},"bk_490":{"lemma":"fijn","displayNl":"fijn","pos":"adjectief","meanings":[{"de":"schön, angenehm","ex":"Fijn dat je er bent.","exDe":"Schön, dass du da bist."},{"de":"nett, toll (Ausruf van blijdschap)","ex":"Wat fijn om je te zien!","exDe":"Wie schön, dich zu sehen!"},{"de":"fein, dünn, feinkörnig","ex":"Dit is heel fijn zand.","exDe":"Das ist sehr feiner Sand."}],"usage":"Sehr häufiges Alltagswort für 'angenehm/schön'; 'fijne dag!' = schönen Tag!"},"bk_492":{"lemma":"dan","displayNl":"dan","pos":"bijwoord","meanings":[{"de":"dann, danach (zeitlich/folgernd)","ex":"Eerst eten, dan slapen.","exDe":"Erst essen, dann schlafen."},{"de":"als (im Vergleich, nach Komparativ)","ex":"Hij is groter dan ik.","exDe":"Er ist größer als ich."}],"usage":"Adverb 'dann' und Vergleichspartikel 'als' nach Komparativ (groter dan)."},"bk_493":{"lemma":"hier","displayNl":"hier","pos":"bijwoord","meanings":[{"de":"hier (an diesem Ort)","ex":"Ik woon hier.","exDe":"Ich wohne hier."},{"de":"hierher (Richtung, hier + Bewegung)","ex":"Kom eens hier.","exDe":"Komm mal her."}],"usage":"Ortsadverb; Gegenteil von 'daar'. In Kombinationen: hiernaast, hierheen."},"bk_494":{"lemma":"daar","displayNl":"daar","pos":"bijwoord","meanings":[{"de":"dort, da (an jenem Ort)","ex":"Het boek ligt daar.","exDe":"Das Buch liegt dort."},{"de":"da, weil (kausale Konjunktion, formell)","ex":"Daar hij ziek was, bleef hij thuis.","exDe":"Da er krank war, blieb er zu Hause."}],"usage":"Ortsadverb 'dort'; gehoben auch kausale Konjunktion 'da/weil'. Gegenteil von 'hier'."},"bk_495":{"lemma":"alleen","displayNl":"alleen","pos":"bijwoord","meanings":[{"de":"allein, ohne andere","ex":"Ik woon alleen.","exDe":"Ich wohne allein."},{"de":"nur, bloß (einschränkend)","ex":"Ik heb alleen water, geen sap.","exDe":"Ich habe nur Wasser, keinen Saft."},{"de":"allein, jedoch (einschränkende Konjunktion)","ex":"Ik wil komen, alleen ik heb geen tijd.","exDe":"Ich will kommen, allein ich habe keine Zeit."}],"usage":"Sowohl 'allein' (ohne Gesellschaft) als auch 'nur' (Einschränkung)."},"bk_496":{"lemma":"ook","displayNl":"ook","pos":"bijwoord","meanings":[{"de":"auch, ebenfalls","ex":"Ik wil ook een ijsje.","exDe":"Ich will auch ein Eis."},{"de":"denn, eigentlich (Modalpartikel, verstärkend)","ex":"Wat is dat nou ook alweer?","exDe":"Wie war das noch mal?"}],"usage":"Häufigstes Wort für 'auch'; als Partikel oft in 'dan ook', 'ook alweer'."},"bk_497":{"lemma":"nog","displayNl":"nog","pos":"bijwoord","meanings":[{"de":"noch (weiterhin, zusätzlich)","ex":"Ik heb nog tijd.","exDe":"Ich habe noch Zeit."},{"de":"noch (bis jetzt nicht, mit ontkenning)","ex":"Hij is er nog niet.","exDe":"Er ist noch nicht da."},{"de":"noch, sogar (bei Steigerung: nog groter)","ex":"Dit huis is nog groter.","exDe":"Dieses Haus ist noch größer."}],"usage":"Vielseitiges Adverb; 'nog een' = noch ein(e), 'nog niet' = noch nicht."},"bk_498":{"lemma":"al","displayNl":"al","pos":"bijwoord","meanings":[{"de":"schon, bereits","ex":"Ben je al klaar?","exDe":"Bist du schon fertig?"},{"de":"schon (verstärkend, betont Menge/Zeit)","ex":"Hij is al drie uur onderweg.","exDe":"Er ist schon drei Stunden unterwegs."}],"usage":"Adverb der Zeit; betont, dass etwas früher als erwartet geschieht. Nicht mit 'alle' (alle) verwechseln."},"bk_499":{"lemma":"misschien","displayNl":"misschien","pos":"bijwoord","meanings":[{"de":"vielleicht, möglicherweise","ex":"Misschien kom ik morgen.","exDe":"Vielleicht komme ich morgen."}],"usage":"Satzadverb, das Möglichkeit/Unsicherheit ausdrückt; steht meist am Satzanfang oder nach dem Verb."},"bk_500":{"lemma":"erg","displayNl":"erg","pos":"bijwoord","meanings":[{"de":"sehr, sehr stark","ex":"Het is erg koud.","exDe":"Es ist sehr kalt."},{"de":"schlimm, arg (als Adjektiv)","ex":"Dat is niet zo erg.","exDe":"Das ist nicht so schlimm."}],"usage":"Als Adverb Verstärker (sehr) vor Adjektiven; als Adjektiv 'schlimm'. Synonym zu 'heel', aber leicht negativer Beiklang."},"bk_501":{"lemma":"heel","displayNl":"heel","pos":"bijwoord","meanings":[{"de":"sehr (Verstärker)","ex":"Het is heel mooi.","exDe":"Es ist sehr schön."},{"de":"ganz, gesamt (als Adjektiv)","ex":"De hele dag regende het.","exDe":"Den ganzen Tag regnete es."},{"de":"heil, unversehrt (als Adjektiv)","ex":"Het glas is nog heel.","exDe":"Das Glas ist noch heil."}],"usage":"Als Adverb neutraler Verstärker (sehr); als Adjektiv 'ganz/heil' und wird dann gebeugt (hele)."},"bk_502":{"lemma":"te","displayNl":"te","pos":"bijwoord","meanings":[{"de":"zu (übermäßig, vor Adjektiv/Adverb)","ex":"De soep is te heet.","exDe":"Die Suppe ist zu heiß."},{"de":"zu (Infinitivpartikel bei 'om ... te')","ex":"Het is tijd om te gaan.","exDe":"Es ist Zeit zu gehen."}],"usage":"Vor Adjektiv/Adverb = 'zu' (übermäßig); als Infinitivpartikel in 'om te + Infinitiv'. In festen Wendungen (te voet, ten slotte) auch Präposition."},"bk_503":{"lemma":"alles","displayNl":"alles","pos":"voornaamwoord","meanings":[{"de":"alles","ex":"Alles is klaar.","exDe":"Alles ist fertig."}],"usage":"Unbestimmtes Pronomen für die Gesamtheit von Dingen; grammatisch Singular (das Verb steht im Singular)."},"bk_504":{"lemma":"niets","displayNl":"niets","pos":"voornaamwoord","meanings":[{"de":"nichts","ex":"Ik zie niets.","exDe":"Ich sehe nichts."}],"usage":"Verneinendes unbestimmtes Pronomen; Umgangssprache auch 'niks'. Gegenstück zu 'alles'."},"bk_505":{"lemma":"iets","displayNl":"iets","pos":"voornaamwoord","meanings":[{"de":"etwas, irgendetwas","ex":"Wil je iets drinken?","exDe":"Möchtest du etwas trinken?"},{"de":"ein bisschen, etwas (als Adverb)","ex":"Kun je iets harder praten?","exDe":"Kannst du etwas lauter sprechen?"}],"usage":"Unbestimmtes Pronomen 'etwas'; adverbial auch 'ein wenig'. Umgangssprachlich 'iets' > 'iets/wat'. Gegenstück zu 'niets'."},"bk_506":{"lemma":"en","displayNl":"en","pos":"voegwoord","meanings":[{"de":"und","ex":"Ik en mijn broer gaan naar school.","exDe":"Ich und mein Bruder gehen zur Schule."},{"de":"sowohl … als auch (in Aufzählungen)","ex":"We hebben brood, kaas en melk gekocht.","exDe":"Wir haben Brot, Käse und Milch gekauft."}],"usage":"Nebenordnende Konjunktion, verbindet gleichrangige Wörter oder Sätze. Nicht mit dem Zahlwort verwechseln.","notes":"Häufigstes Bindewort im Niederländischen."},"bk_507":{"lemma":"of","displayNl":"of","pos":"voegwoord","meanings":[{"de":"oder","ex":"Wil je thee of koffie?","exDe":"Möchtest du Tee oder Kaffee?"},{"de":"ob (einleitende indirekte Frage)","ex":"Ik weet niet of hij komt.","exDe":"Ich weiß nicht, ob er kommt."}],"usage":"Als 'oder' nebenordnend; als 'ob' unterordnend (Verb ans Satzende). Homonym mit zwei zentralen Funktionen."},"bk_508":{"lemma":"maar","displayNl":"maar","pos":"voegwoord","meanings":[{"de":"aber, sondern","ex":"Ik wil, maar ik kan niet.","exDe":"Ich will, aber ich kann nicht."},{"de":"nur, bloß (als Partikel/Adverb)","ex":"Het is maar een klein probleem.","exDe":"Es ist nur ein kleines Problem."},{"de":"doch, ruhig (auffordernde Partikel)","ex":"Kom maar binnen!","exDe":"Komm ruhig herein!"}],"usage":"Zentrale Gegensatz-Konjunktion; sehr häufig auch als abtönende Partikel ('nur', 'doch') im Sprechniederländisch."},"bk_509":{"lemma":"in","displayNl":"in","pos":"voorzetsel","meanings":[{"de":"in (Ort, innerhalb)","ex":"Het boek ligt in de tas.","exDe":"Das Buch liegt in der Tasche."},{"de":"in (Zeit)","ex":"In de zomer is het warm.","exDe":"Im Sommer ist es warm."}],"usage":"Präposition für Ort und Zeit. Auch als trennbares Verbpräfix (inkomen, invullen)."},"bk_510":{"lemma":"op","displayNl":"op","pos":"voorzetsel","meanings":[{"de":"auf (auf einer Oberfläche)","ex":"De kat zit op de stoel.","exDe":"Die Katze sitzt auf dem Stuhl."},{"de":"an (bei Wochentagen/Daten)","ex":"Op maandag werk ik niet.","exDe":"Am Montag arbeite ich nicht."},{"de":"alle, aufgebraucht (prädikatives Adverb)","ex":"De melk is op.","exDe":"Die Milch ist alle."}],"usage":"Häufige Ortspräposition; bei Wochentagen 'op'. Umgangssprachlich 'op zijn' = aufgebraucht/erschöpft."},"bk_511":{"lemma":"onder","displayNl":"onder","pos":"voorzetsel","meanings":[{"de":"unter (räumlich)","ex":"De bal ligt onder de tafel.","exDe":"Der Ball liegt unter dem Tisch."},{"de":"unter, inmitten (Menge/Gruppe)","ex":"Onder de gasten waren veel kinderen.","exDe":"Unter den Gästen waren viele Kinder."},{"de":"während (onder het eten)","ex":"Onder het eten praten we.","exDe":"Beim Essen reden wir."}],"usage":"Ortspräposition mit Gegenteil 'boven'. Auch temporal in Wendungen wie 'onder het eten'."},"bk_512":{"lemma":"naar","displayNl":"naar","pos":"voorzetsel","meanings":[{"de":"nach, zu (Richtung)","ex":"Ik ga naar huis.","exDe":"Ich gehe nach Hause."},{"de":"nach (gemäß, entsprechend)","ex":"Volgens de regels handelen we naar de wet.","exDe":"Gemäß den Regeln handeln wir nach dem Gesetz."},{"de":"unangenehm, übel (als Adjektiv)","ex":"Dat is een naar gevoel.","exDe":"Das ist ein unangenehmes Gefühl."}],"usage":"Richtungspräposition 'zu/nach' (Bewegung zu einem Ziel). Homonym mit dem Adjektiv 'naar' = unangenehm/übel."},"bk_513":{"lemma":"van","displayNl":"van","pos":"voorzetsel","meanings":[{"de":"von (Herkunft, Ausgangspunkt)","ex":"Dit is een cadeau van oma.","exDe":"Das ist ein Geschenk von Oma."},{"de":"von, aus (Material/Zugehörigkeit, Genitiv-Ersatz)","ex":"De deur van het huis is rood.","exDe":"Die Tür des Hauses ist rot."},{"de":"aus (Ausgangsort)","ex":"Ik kom van het station.","exDe":"Ich komme vom Bahnhof."}],"usage":"Sehr häufige Präposition; ersetzt oft den deutschen Genitiv ('de auto van mijn vader'). Kernbedeutung Herkunft/Zugehörigkeit."},"bk_514":{"lemma":"met","displayNl":"met","pos":"voorzetsel","meanings":[{"de":"mit (Begleitung, zusammen mit)","ex":"Ik ga met mijn zus naar de markt.","exDe":"Ich gehe mit meiner Schwester zum Markt."},{"de":"mit (Mittel, Verkehrsmittel, Werkzeug)","ex":"Ik ga met de bus.","exDe":"Ich fahre mit dem Bus."},{"de":"mit (versehen mit, mit Eigenschaft)","ex":"Een koffie met melk, alsjeblieft.","exDe":"Einen Kaffee mit Milch, bitte."}],"usage":"Sehr häufige Präposition; auch im Ausdruck 'met de trein/fiets' (mit dem Zug/Rad) und in Grußformeln am Telefon: 'Met Anna.'"},"bk_515":{"lemma":"bij","displayNl":"bij","pos":"voorzetsel","meanings":[{"de":"bei (in der Nähe von, an)","ex":"Ik woon bij het station.","exDe":"Ich wohne beim Bahnhof."},{"de":"bei (bei jemandem, in dessen Umgebung/Praxis)","ex":"Ik ben bij de dokter.","exDe":"Ich bin beim Arzt."},{"de":"zu (hinzu, dabei)","ex":"Wil je er brood bij?","exDe":"Möchtest du Brot dazu?"}],"usage":"Häufige Ortspräposition. Achtung: 'bij' (Präposition) ist ein Homonym des Substantivs 'de bij' (die Biene) – hier ist die Präposition gemeint. Auch trennbares Verbpräfix ('bijvoorbeeld')."},"bk_516":{"lemma":"uit","displayNl":"uit","pos":"voorzetsel","meanings":[{"de":"aus (Herkunft, Ursprungsort)","ex":"Zij komt uit Duitsland.","exDe":"Sie kommt aus Deutschland."},{"de":"aus (heraus aus, aus etwas hinaus)","ex":"Hij haalt een boek uit de tas.","exDe":"Er holt ein Buch aus der Tasche."},{"de":"aus (ausgeschaltet, vorbei) – als Adverb/Adjektiv","ex":"Het licht is uit.","exDe":"Das Licht ist aus."}],"usage":"Präposition der Herkunft ('komen uit') und Richtung; außerdem häufiges trennbares Verbpräfix ('uitgaan', 'uitzien') und Adverb ('de film is uit')."},"bk_517":{"lemma":"wie","displayNl":"wie","pos":"voornaamwoord","meanings":[{"de":"wer (Fragepronomen nach Personen)","ex":"Wie is dat?","exDe":"Wer ist das?"},{"de":"wer / derjenige, der (Relativ-/Verallgemeinerung)","ex":"Wie het weet, mag het zeggen.","exDe":"Wer es weiß, darf es sagen."}],"usage":"Fragepronomen für Personen. Nicht mit deutsch 'wie' verwechseln – niederländisch 'wie' = deutsch 'wer'. Für 'wessen' benutzt man 'van wie'."},"bk_518":{"lemma":"wat","displayNl":"wat","pos":"voornaamwoord","meanings":[{"de":"was (Fragepronomen nach Sachen)","ex":"Wat doe je?","exDe":"Was machst du?"},{"de":"etwas (unbestimmtes Pronomen)","ex":"Ik heb wat brood gekocht.","exDe":"Ich habe etwas Brot gekauft."},{"de":"was / das, was (Relativpronomen)","ex":"Alles wat je zegt, is waar.","exDe":"Alles, was du sagst, ist wahr."}],"usage":"Vielseitiges Wort: Fragepronomen, unbestimmtes 'etwas' (umgangssprachlich für 'iets') und Relativpronomen. Auch im Ausruf: 'Wat mooi!' (Wie schön!)."},"bk_519":{"lemma":"wanneer","displayNl":"wanneer","pos":"bijwoord","meanings":[{"de":"wann (Frageadverb der Zeit)","ex":"Wanneer kom je?","exDe":"Wann kommst du?"},{"de":"wenn / als (temporale Konjunktion)","ex":"Bel me wanneer je thuis bent.","exDe":"Ruf mich an, wenn du zu Hause bist."}],"usage":"Als Frageadverb 'wann?' und als Konjunktion 'wenn/als'. In der Konjunktionsfunktion oft austauschbar mit 'als'."},"bk_520":{"lemma":"waarom","displayNl":"waarom","pos":"bijwoord","meanings":[{"de":"warum, weshalb (Frageadverb nach dem Grund)","ex":"Waarom lach je?","exDe":"Warum lachst du?"},{"de":"warum / der Grund, weshalb (in indirekter Frage)","ex":"Ik weet niet waarom hij boos is.","exDe":"Ich weiß nicht, warum er böse ist."}],"usage":"Frageadverb nach dem Grund. Antwort meist mit 'omdat' (weil) oder 'want' (denn)."},"bk_521":{"lemma":"hoe","displayNl":"hoe","pos":"bijwoord","meanings":[{"de":"wie (Frageadverb nach Art und Weise)","ex":"Hoe gaat het?","exDe":"Wie geht es?"},{"de":"wie (Grad, in Verbindung mit Adjektiv/Adverb)","ex":"Hoe oud ben je?","exDe":"Wie alt bist du?"},{"de":"je … desto (in 'hoe … hoe'-Konstruktion)","ex":"Hoe meer, hoe beter.","exDe":"Je mehr, desto besser."}],"usage":"Niederländisch 'hoe' = deutsch 'wie' (Art/Weise, Grad). Nicht mit 'wie' (= wer) verwechseln. Steht in vielen festen Fragen: 'Hoe heet je?', 'Hoe laat is het?'."},"bk_522":{"lemma":"ik","displayNl":"ik","pos":"voornaamwoord","meanings":[{"de":"ich","ex":"Ik ben moe.","exDe":"Ich bin müde."}],"usage":"Personalpronomen 1. Person Singular (Subjekt). Unbetonte Form: 'k."},"bk_523":{"lemma":"jij","displayNl":"jij","pos":"voornaamwoord","meanings":[{"de":"du","ex":"Jij bent aardig.","exDe":"Du bist nett."}],"usage":"Betontes Personalpronomen 2. Person Singular (informell). Unbetonte Form: je."},"bk_524":{"lemma":"hij","displayNl":"hij","pos":"voornaamwoord","meanings":[{"de":"er","ex":"Hij werkt hard.","exDe":"Er arbeitet hart."}],"usage":"Personalpronomen 3. Person Singular maskulin (Subjekt). Unbetont oft: -ie."},"bk_525":{"lemma":"zij","displayNl":"zij","pos":"voornaamwoord","meanings":[{"de":"sie (Singular)","ex":"Zij leest een boek.","exDe":"Sie liest ein Buch."},{"de":"sie (Plural)","ex":"Zij wonen in Utrecht.","exDe":"Sie wohnen in Utrecht."}],"usage":"Betontes Personalpronomen: 3. Person Singular feminin ODER 3. Person Plural. Unbetonte Form beider: ze."},"bk_526":{"lemma":"wij","displayNl":"wij","pos":"voornaamwoord","meanings":[{"de":"wir","ex":"Wij gaan naar school.","exDe":"Wir gehen zur Schule."}],"usage":"Betontes Personalpronomen 1. Person Plural. Unbetonte Form: we."},"bk_527":{"lemma":"jullie","displayNl":"jullie","pos":"voornaamwoord","meanings":[{"de":"ihr / euch","ex":"Jullie zijn laat.","exDe":"Ihr seid spät."},{"de":"euer / eure (Possessiv)","ex":"Is dat jullie huis?","exDe":"Ist das euer Haus?"}],"usage":"2. Person Plural (informell): sowohl Personal- als auch Possessivpronomen."},"bk_528":{"lemma":"jouw","displayNl":"jouw","pos":"voornaamwoord","meanings":[{"de":"dein / deine (Possessiv)","ex":"Is dit jouw jas?","exDe":"Ist das deine Jacke?"}],"usage":"Betontes Possessivpronomen 2. Person Singular. Nicht mit 'jou' (Objektform 'dich/dir') verwechseln; unbetont: je."},"bk_529":{"lemma":"haar","displayNl":"haar","pos":"voornaamwoord","meanings":[{"de":"ihr / ihre (Possessiv)","ex":"Dat is haar fiets.","exDe":"Das ist ihr Fahrrad."},{"de":"sie / ihr (Objektform, 3. Pers. Sg. feminin)","ex":"Ik zie haar.","exDe":"Ich sehe sie."},{"de":"das Haar (Homonym, Substantiv het-woord)","ex":"Zij heeft lang haar.","exDe":"Sie hat lange Haare."}],"usage":"Mehrdeutig: Possessiv- und Objektpronomen (feminin) sowie Homonym mit dem Substantiv 'het haar' (Haar/Haare). Als Pronomen dominant."},"bk_530":{"lemma":"deze","displayNl":"deze","pos":"voornaamwoord","meanings":[{"de":"diese/dieser/dieses (nahestehend, bei de-Wörtern und im Plural)","ex":"Ik neem deze appel.","exDe":"Ich nehme diesen Apfel."},{"de":"diese (als Ersatz für ein Substantiv: dieser/diese hier)","ex":"Welke wil je? Deze.","exDe":"Welchen willst du? Diesen hier."}],"usage":"Aanwijzend voornaamwoord voor nabijheid; gebruikt bij de-woorden en meervoud ('deze man', 'deze huizen'). Voor het-woorden enkelvoud: 'dit'."},"bk_531":{"lemma":"dit","displayNl":"dit","pos":"voornaamwoord","meanings":[{"de":"dies/dieses (nahestehend, bei het-Wörtern im Singular)","ex":"Dit huis is groot.","exDe":"Dieses Haus ist groß."},{"de":"das (hier), dies (allgemein hinweisend)","ex":"Dit is lekker.","exDe":"Das ist lecker."}],"usage":"Aanwijzend voornaamwoord voor nabijheid bij het-woorden enkelvoud ('dit boek'). Als zelfstandig aanwijzend: 'dit is...'. Tegenhanger 'deze' voor de-woorden/meervoud."},"bk_532":{"lemma":"die","displayNl":"die","pos":"voornaamwoord","meanings":[{"de":"jene/jener/jenes; der/die/das da (weiter entfernt, bei de-Wörtern und im Plural)","ex":"Ik wil die schönen.","exDe":"Ich will jene Schuhe."},{"de":"der/die/das (Relativpronomen bei de-Wörtern und Plural)","ex":"De man die daar staat, is mijn vader.","exDe":"Der Mann, der dort steht, ist mein Vater."},{"de":"der/die (nachdrücklich für eine Person: der da)","ex":"Die weet het niet.","exDe":"Der weiß es nicht."}],"usage":"Aanwijzend en betrekkelijk voornaamwoord voor de-woorden en meervoud (afstand). Tegenhanger voor het-woorden enkelvoud: 'dat'."},"bk_533":{"lemma":"zo","displayNl":"zo","pos":"bijwoord","meanings":[{"de":"so, auf diese Weise","ex":"Doe het zo.","exDe":"Mach es so."},{"de":"so (Verstärkung: derart, so sehr)","ex":"Het is zo koud vandaag.","exDe":"Es ist so kalt heute."},{"de":"gleich, sofort (in Kürze)","ex":"Ik kom zo.","exDe":"Ich komme gleich."}],"usage":"Veelzijdig bijwoord: manier ('zo doe je dat'), graad ('zo mooi') en tijd ('tot zo!' = bis gleich). Vaste uitdrukking 'zo maar' = einfach so."},"bk_534":{"lemma":"hamer","displayNl":"de hamer","pos":"substantief","meanings":[{"de":"der Hammer (Werkzeug)","ex":"Ik sla de spijker met de hamer.","exDe":"Ich schlage den Nagel mit dem Hammer."}],"usage":"Gereedschap om te slaan. Ook figuurlijk: 'onder de hamer komen' = versteigert werden.","genus":"de","plural":"hamers","illustratable":true},"bk_535":{"lemma":"spijker","displayNl":"de spijker","pos":"substantief","meanings":[{"de":"der Nagel (aus Metall, zum Einschlagen)","ex":"De spijker zit vast in de muur.","exDe":"Der Nagel steckt fest in der Wand."}],"usage":"Metalen bevestigingsmiddel dat je erin slaat. Uitdrukking 'de spijker op de kop slaan' = den Nagel auf den Kopf treffen. Niet verwarren met 'nagel' (vingernagel).","genus":"de","plural":"spijkers","illustratable":true},"bk_536":{"lemma":"schroef","displayNl":"de schroef","pos":"substantief","meanings":[{"de":"die Schraube (Befestigungsmittel mit Gewinde)","ex":"Deze schroef is te kort.","exDe":"Diese Schraube ist zu kurz."},{"de":"die Schiffsschraube, der Propeller","ex":"De schroef van de boot draait snel.","exDe":"Die Schraube des Bootes dreht sich schnell."}],"usage":"Bevestigingsmiddel met schroefdraad; ook de aandrijfschroef van een schip. Werkwoord 'schroeven' = schrauben.","genus":"de","plural":"schroeven","illustratable":true},"bk_538":{"lemma":"kist","displayNl":"de kist","pos":"substantief","meanings":[{"de":"die Kiste, der Kasten (Behälter)","ex":"Het gereedschap ligt in de kist.","exDe":"Das Werkzeug liegt in der Kiste."},{"de":"der Sarg","ex":"De kist werd langzaam gedragen.","exDe":"Der Sarg wurde langsam getragen."}],"usage":"Houten of stevige bak met deksel om iets in te bewaren; ook eufemistisch voor doodskist. Verkleinvorm 'kistje' o.a. voor sigaren.","genus":"de","plural":"kisten","illustratable":true},"bk_539":{"lemma":"kapot","displayNl":"kapot","pos":"adjectief","meanings":[{"de":"kaputt, defekt","ex":"De boormachine is kapot.","exDe":"Die Bohrmaschine ist kaputt."},{"de":"völlig erschöpft, kaputt (umgangssprachlich)","ex":"Na het werk ben ik helemaal kapot.","exDe":"Nach der Arbeit bin ich völlig erschöpft."}],"usage":"Prädikativ ('is kapot') und attributiv ('een kapotte fiets'). Umgangssprachlich auch für 'erschöpft'."},"bk_540":{"lemma":"graag gedaan","displayNl":"graag gedaan","pos":"uitdrukking","meanings":[{"de":"gern geschehen, keine Ursache","ex":"Bedankt voor je hulp! – Graag gedaan.","exDe":"Danke für deine Hilfe! – Gern geschehen."}],"usage":"Höfliche Antwort auf 'bedankt'/'dank je wel'."},"bk_541":{"lemma":"tot straks","displayNl":"tot straks","pos":"uitdrukking","meanings":[{"de":"bis gleich, bis später (am selben Tag)","ex":"Ik ga even weg, tot straks.","exDe":"Ich gehe kurz weg, bis gleich."}],"usage":"Abschiedsgruß bei kurzer Trennung am selben Tag; vgl. 'tot ziens', 'tot zo'."},"bk_542":{"lemma":"hoe gaat het","displayNl":"hoe gaat het?","pos":"uitdrukking","meanings":[{"de":"wie geht es (dir/Ihnen)?","ex":"Hoi Anna, hoe gaat het?","exDe":"Hallo Anna, wie geht es dir?"},{"de":"wie läuft es? (Sachverhalt)","ex":"Hoe gaat het met je studie?","exDe":"Wie läuft es mit deinem Studium?"}],"usage":"Standard-Begrüßungsfloskel; oft erweitert 'hoe gaat het met je/u?'."},"bk_543":{"lemma":"het gaat goed","displayNl":"het gaat goed","pos":"uitdrukking","meanings":[{"de":"es geht gut, mir geht es gut","ex":"Met mij gaat het goed, dank je.","exDe":"Mir geht es gut, danke."}],"usage":"Typische Antwort auf 'hoe gaat het?'; oft mit 'met mij/hem/haar'."},"bk_544":{"lemma":"en met jou","displayNl":"en met jou?","pos":"uitdrukking","meanings":[{"de":"und dir? (Rückfrage nach dem Befinden)","ex":"Goed, dank je. En met jou?","exDe":"Gut, danke. Und dir?"}],"usage":"Rückfrage im Begrüßungsdialog; formell 'en met u?'."},"bk_545":{"lemma":"het spijt me","displayNl":"het spijt me","pos":"uitdrukking","meanings":[{"de":"es tut mir leid","ex":"Het spijt me, ik ben te laat.","exDe":"Es tut mir leid, ich bin zu spät."}],"usage":"Entschuldigung; Grundverb 'spijten' (het spijt me/hem/haar). Formeller als 'sorry'."},"bk_546":{"lemma":"geen probleem","displayNl":"geen probleem","pos":"uitdrukking","meanings":[{"de":"kein Problem","ex":"Geen probleem, ik help je.","exDe":"Kein Problem, ich helfe dir."}],"usage":"Beschwichtigung/Zustimmung; Antwort auf Entschuldigung oder Bitte."},"bk_547":{"lemma":"maakt niet uit","displayNl":"maakt niet uit","pos":"uitdrukking","meanings":[{"de":"macht nichts","ex":"Sorry! – Maakt niet uit.","exDe":"Entschuldigung! – Macht nichts."},{"de":"ist egal / spielt keine Rolle","ex":"Koffie of thee, het maakt niet uit.","exDe":"Kaffee oder Tee, das ist egal."}],"usage":"Beruhigende Floskel als Antwort auf eine Entschuldigung ('macht nichts') oder um Gleichgültigkeit auszudrücken ('ist egal'). Vollform: het maakt niet uit."},"bk_548":{"lemma":"veel plezier","displayNl":"veel plezier","pos":"uitdrukking","meanings":[{"de":"viel Spaß","ex":"Veel plezier op je feestje!","exDe":"Viel Spaß auf deiner Party!"}],"usage":"Wunsch beim Abschied vor einer angenehmen Aktivität; oft mit 'met' + Aktivität (veel plezier met het feest)."},"bk_549":{"lemma":"goede reis","displayNl":"goede reis","pos":"uitdrukking","meanings":[{"de":"gute Reise","ex":"Goede reis en tot volgende week!","exDe":"Gute Reise und bis nächste Woche!"}],"usage":"Abschiedsgruß an jemanden, der verreist; Variante: goede reis / prettige reis."},"bk_550":{"lemma":"eet smakelijk","displayNl":"eet smakelijk","pos":"uitdrukking","meanings":[{"de":"guten Appetit","ex":"Het eten is klaar, eet smakelijk!","exDe":"Das Essen ist fertig, guten Appetit!"}],"usage":"Wunsch vor dem Essen; entspricht dem deutschen 'guten Appetit'."},"bk_551":{"lemma":"slaap lekker","displayNl":"slaap lekker","pos":"uitdrukking","meanings":[{"de":"schlaf gut","ex":"Welterusten en slaap lekker.","exDe":"Gute Nacht und schlaf gut."}],"usage":"Gutenachtgruß vor dem Schlafengehen; oft zusammen mit 'welterusten'."},"bk_552":{"lemma":"fijne dag nog","displayNl":"fijne dag nog","pos":"uitdrukking","meanings":[{"de":"schönen Tag noch","ex":"Bedankt, fijne dag nog!","exDe":"Danke, schönen Tag noch!"}],"usage":"Freundlicher Abschiedsgruß tagsüber; das 'nog' entspricht dem deutschen 'noch'."},"bk_553":{"lemma":"fijn weekend","displayNl":"fijn weekend","pos":"uitdrukking","meanings":[{"de":"schönes Wochenende","ex":"Tot maandag, fijn weekend!","exDe":"Bis Montag, schönes Wochenende!"}],"usage":"Abschiedsgruß am Ende der Arbeitswoche; Variante: prettig weekend."},"bk_554":{"lemma":"ik begrijp het niet","displayNl":"ik begrijp het niet","pos":"uitdrukking","meanings":[{"de":"ich verstehe es nicht","ex":"Sorry, ik begrijp het niet.","exDe":"Entschuldigung, ich verstehe es nicht."}],"usage":"Feste Aussage, um fehlendes Verständnis zu signalisieren; Verb-Lemma dahinter ist begrijpen."},"bk_555":{"lemma":"ik weet het niet","displayNl":"ik weet het niet","pos":"uitdrukking","meanings":[{"de":"ich weiß es nicht","ex":"Waar is het station? – Ik weet het niet.","exDe":"Wo ist der Bahnhof? – Ich weiß es nicht."},{"de":"keine Ahnung","ex":"Hoe laat begint de film? Ik weet het niet.","exDe":"Wann beginnt der Film? Keine Ahnung."}],"usage":"Feste Wendung, um Unwissen auszudrücken. 'het' ist das feste Objekt; ohne 'het' ('ik weet niet') klingt es unvollständig/regional. Verbstamm: weten (weet, wist, geweten).","notes":"Redewendung; Verb-Kopf ist 'weten'."},"bk_556":{"lemma":"wacht even","displayNl":"wacht even","pos":"uitdrukking","meanings":[{"de":"warte kurz","ex":"Wacht even, ik kom eraan.","exDe":"Warte kurz, ich komme."},{"de":"einen Moment / Moment mal","ex":"Wacht even, ik moet nog iets pakken.","exDe":"Einen Moment, ich muss noch etwas holen."}],"usage":"Imperativ von 'wachten' + Abschwächungspartikel 'even' (mal/kurz). Höflich-informell. Höflicher: 'wacht u even' / 'wacht even alstublieft'.","notes":"Ausdruck; Verb-Kopf 'wachten'."},"bk_557":{"lemma":"precies","displayNl":"precies","pos":"bijwoord","meanings":[{"de":"genau (bestätigend)","ex":"Dus we gaan morgen? – Precies.","exDe":"Also gehen wir morgen? – Genau."},{"de":"genau / exakt","ex":"Het is precies twaalf uur.","exDe":"Es ist genau zwölf Uhr."},{"de":"präzise, genau (Adjektiv)","ex":"Hij is heel precies in zijn werk.","exDe":"Er ist sehr genau bei seiner Arbeit."}],"usage":"Meist als Bestätigung ('genau!') oder Adverb ('genau um…'). Als Adjektiv 'nauwkeurig/sorgfältig'. Unveränderlich in der Bestätigungsfunktion."},"bk_558":{"lemma":"wat leuk","displayNl":"wat leuk","pos":"uitdrukking","meanings":[{"de":"wie schön!","ex":"Je gaat op reis? Wat leuk!","exDe":"Du machst eine Reise? Wie schön!"},{"de":"wie toll / wie nett","ex":"Wat leuk dat je er bent!","exDe":"Wie schön, dass du da bist!"}],"usage":"Ausruf 'wat' + Adjektiv 'leuk' (nett/schön/toll). Sehr gebräuchliche positive Reaktion. Adjektiv-Grundform ist 'leuk'.","notes":"Ausruf; Adjektiv-Kopf 'leuk'."},"bk_559":{"lemma":"baas","displayNl":"de baas","pos":"substantief","meanings":[{"de":"der Chef / die Chefin, Vorgesetzte(r)","ex":"Mijn baas is streng.","exDe":"Mein Chef ist streng."},{"de":"der Herr / die Herrin (eines Tieres)","ex":"De hond luistert naar zijn baas.","exDe":"Der Hund hört auf sein Herrchen."},{"de":"Herr der Lage sein (in 'de baas zijn')","ex":"Wie is hier de baas?","exDe":"Wer hat hier das Sagen?"}],"usage":"de-Wort, Plural 'bazen'. Neutral für Vorgesetzte(n) unabhängig vom Geschlecht. Redewendung 'de baas zijn' = das Sagen haben / überlegen sein.","genus":"de","plural":"bazen","illustratable":true},"bk_560":{"lemma":"collega","displayNl":"de collega","pos":"substantief","meanings":[{"de":"der Kollege / die Kollegin","ex":"Mijn collega helpt mij vaak.","exDe":"Mein Kollege hilft mir oft."},{"de":"Berufskollege (gleiche Zunft)","ex":"Als arts waardeer ik mijn collega's.","exDe":"Als Arzt schätze ich meine Kolleginnen und Kollegen."}],"usage":"de-Wort, Plural 'collega's' (mit Apostroph, da Endung -a). Geschlechtsneutral. Betonung auf zweiter Silbe.","genus":"de","plural":"collega's","illustratable":true},"bk_561":{"lemma":"partner","displayNl":"de partner","pos":"substantief","meanings":[{"de":"der/die Partner:in (Beziehung)","ex":"Mijn partner werkt in de stad.","exDe":"Mein Partner arbeitet in der Stadt."},{"de":"Geschäftspartner:in","ex":"Zij is partner in een advocatenkantoor.","exDe":"Sie ist Partnerin in einer Anwaltskanzlei."},{"de":"Tanz-/Spielpartner:in","ex":"Ik zoek een partner voor het toernooi.","exDe":"Ich suche einen Partner für das Turnier."}],"usage":"de-Wort, Plural 'partners'. Geschlechtsneutral, sehr gebräuchlich für Lebenspartner:in (statt man/vrouw). Aussprache eher englisch.","genus":"de","plural":"partners","notes":"Abstrakter Beziehungs-/Rollenbegriff, nicht eindeutig bildlich."},"bk_562":{"lemma":"echtgenoot","displayNl":"de echtgenoot","pos":"substantief","meanings":[{"de":"der Ehemann, Gatte","ex":"Haar echtgenoot is arts.","exDe":"Ihr Ehemann ist Arzt."},{"de":"Ehepartner (formell)","ex":"De echtgenoot van de minister was ook aanwezig.","exDe":"Der Ehegatte der Ministerin war ebenfalls anwesend."}],"usage":"de-Wort, Plural 'echtgenoten'. Formell/gehoben; weibliche Form 'echtgenote'. Alltagssprachlich meist 'man'. Zusammensetzung echt + genoot.","genus":"de","plural":"echtgenoten","notes":"Formeller Rollen-/Beziehungsbegriff, nicht eindeutig darstellbar."},"bk_563":{"lemma":"echtgenote","displayNl":"de echtgenote","pos":"substantief","meanings":[{"de":"die Ehefrau","ex":"Zijn echtgenote heet Sara.","exDe":"Seine Ehefrau heißt Sara."},{"de":"die Gattin","ex":"De minister kwam met zijn echtgenote.","exDe":"Der Minister kam mit seiner Gattin."}],"usage":"Formelles Wort für die verheiratete Frau; männliche Form: echtgenoot.","genus":"de","plural":"echtgenotes"},"bk_564":{"lemma":"echtpaar","displayNl":"het echtpaar","pos":"substantief","meanings":[{"de":"das Ehepaar","ex":"Het echtpaar woont naast ons.","exDe":"Das Ehepaar wohnt neben uns."}],"usage":"Zwei miteinander verheiratete Personen; het-Wort.","genus":"het","plural":"echtparen","illustratable":true},"bk_565":{"lemma":"kleinzoon","displayNl":"de kleinzoon","pos":"substantief","meanings":[{"de":"der Enkel","ex":"Hun kleinzoon is vijf.","exDe":"Ihr Enkel ist fünf."}],"usage":"Der Sohn des eigenen Kindes; Plural auch kleinzonen.","genus":"de","plural":"kleinzoons"},"bk_566":{"lemma":"kleindochter","displayNl":"de kleindochter","pos":"substantief","meanings":[{"de":"die Enkelin","ex":"De kleindochter tekent graag.","exDe":"Die Enkelin zeichnet gern."}],"usage":"Die Tochter des eigenen Kindes.","genus":"de","plural":"kleindochters"},"bk_567":{"lemma":"kleinkind","displayNl":"het kleinkind","pos":"substantief","meanings":[{"de":"das Enkelkind","ex":"Oma bezoekt haar kleinkinderen.","exDe":"Oma besucht ihre Enkelkinder."}],"usage":"Roheintrag stand im Plural (de kleinkinderen); Grundform Singular het kleinkind.","genus":"het","plural":"kleinkinderen"},"bk_568":{"lemma":"grootouder","displayNl":"de grootouder","pos":"substantief","meanings":[{"de":"der Großelternteil (Plural: die Großeltern)","ex":"Mijn grootouders zijn oud.","exDe":"Meine Großeltern sind alt."}],"usage":"Roheintrag stand im Plural (de grootouders); Grundform Singular de grootouder. Meist im Plural gebraucht (Großeltern).","genus":"de","plural":"grootouders","illustratable":true},"bk_569":{"lemma":"tweeling","displayNl":"de tweeling","pos":"substantief","meanings":[{"de":"die Zwillinge / das Zwillingspaar","ex":"Zij hebben een tweeling.","exDe":"Sie haben Zwillinge."},{"de":"der/die Zwilling (Einzelperson eines Paares)","ex":"Hij is mijn tweeling.","exDe":"Er ist mein Zwilling."}],"usage":"Im NL bezeichnet 'een tweeling' das ganze Zwillingspaar; deutsch meist Plural Zwillinge.","genus":"de","plural":"tweelingen","illustratable":true},"bk_570":{"lemma":"buur","displayNl":"de buur","pos":"substantief","meanings":[{"de":"der Nachbar / die Nachbarin","ex":"Onze buren zijn vriendelijk.","exDe":"Unsere Nachbarn sind freundlich."}],"usage":"Roheintrag stand im Plural (de buren); Grundform Singular de buur (geschlechtsneutral). Spezifisch: buurman / buurvrouw.","genus":"de","plural":"buren"},"bk_571":{"lemma":"gast","displayNl":"de gast","pos":"substantief","meanings":[{"de":"der Gast, der Besucher","ex":"We hebben vanavond een gast te eten.","exDe":"Wir haben heute Abend einen Gast zum Essen."},{"de":"(umgangssprachlich) der Typ, der Kerl","ex":"Wie is die gast daar bij de deur?","exDe":"Wer ist der Typ da an der Tür?"}],"usage":"Alltäglich. Für den Übernachtungsgast auch 'logé'. Umgangssprachlich 'gast' = Kerl/Typ (informell).","genus":"de","plural":"gasten","illustratable":true},"bk_573":{"lemma":"klant","displayNl":"de klant","pos":"substantief","meanings":[{"de":"der Kunde, die Kundin","ex":"De klant betaalt aan de kassa.","exDe":"Der Kunde bezahlt an der Kasse."}],"usage":"Neutral für Käufer/Kundschaft im Handel und Dienstleistung. 'De klant is koning.' (Der Kunde ist König.)","genus":"de","plural":"klanten","illustratable":true},"bk_574":{"lemma":"baby-oppas","displayNl":"de baby-oppas","pos":"substantief","meanings":[{"de":"der Babysitter, die Tagesbetreuung fürs Baby","ex":"De baby-oppas komt om zeven uur.","exDe":"Der Babysitter kommt um sieben Uhr."}],"usage":"Zusammensetzung; gängiger sind einfach 'de oppas' (Betreuer) oder 'de babysit'/'de babysitter'. 'Oppassen' bezeichnet auch das Aufpassen selbst.","genus":"de","plural":"baby-oppassen","illustratable":true},"bk_576":{"lemma":"vriendschap","displayNl":"de vriendschap","pos":"substantief","meanings":[{"de":"die Freundschaft","ex":"Onze vriendschap is al jaren sterk.","exDe":"Unsere Freundschaft ist schon seit Jahren stark."}],"usage":"Abstraktes Beziehungsverhältnis zwischen Freunden. Verb: 'vriendschap sluiten' (Freundschaft schließen).","genus":"de","plural":"vriendschappen"},"bk_577":{"lemma":"liefde","displayNl":"de liefde","pos":"substantief","meanings":[{"de":"die Liebe (Gefühl)","ex":"Liefde is het belangrijkste in het leven.","exDe":"Liebe ist das Wichtigste im Leben."},{"de":"der/die Geliebte, die große Liebe","ex":"Zij was zijn grote liefde.","exDe":"Sie war seine große Liebe."}],"usage":"Abstrakt für das Gefühl; konkret auch eine geliebte Person. Plural 'liefdes'/'liefden'. 'Uit liefde' = aus Liebe.","genus":"de","plural":"liefdes"},"bk_578":{"lemma":"relatie","displayNl":"de relatie","pos":"substantief","meanings":[{"de":"die Beziehung (Partnerschaft)","ex":"Ze hebben al vijf jaar een relatie.","exDe":"Sie sind schon fünf Jahre zusammen."},{"de":"das Verhältnis, der Zusammenhang, die Verbindung","ex":"Er is een duidelijke relatie tussen roken en ziekte.","exDe":"Es gibt einen klaren Zusammenhang zwischen Rauchen und Krankheit."},{"de":"der Geschäftspartner, die Geschäftsbeziehung","ex":"We nodigen onze zakelijke relaties uit.","exDe":"Wir laden unsere Geschäftspartner ein."}],"usage":"Vielseitig: Liebesbeziehung, sachlicher Zusammenhang und geschäftliche Verbindung. Abstrakt.","genus":"de","plural":"relaties"},"bk_579":{"lemma":"bruiloft","displayNl":"de bruiloft","pos":"substantief","meanings":[{"de":"die Hochzeit, die Hochzeitsfeier","ex":"De bruiloft is in juni op het platteland.","exDe":"Die Hochzeit ist im Juni auf dem Land."}],"usage":"Bezeichnet die Hochzeitsfeier/das Fest; die Ehe selbst ist 'het huwelijk'.","genus":"de","plural":"bruiloften","illustratable":true},"bk_580":{"lemma":"huwelijk","displayNl":"het huwelijk","pos":"substantief","meanings":[{"de":"die Ehe","ex":"Hun huwelijk is al twintig jaar gelukkig.","exDe":"Ihre Ehe ist schon zwanzig Jahre glücklich."},{"de":"die Eheschließung, die Heirat, die Trauung","ex":"Het huwelijk wordt voltrokken op het gemeentehuis.","exDe":"Die Eheschließung findet im Rathaus statt."}],"usage":"'huwelijk' = die Ehe/Institution bzw. die Trauung; die Feier heißt 'bruiloft'. 'in het huwelijk treden' = heiraten.","genus":"het","plural":"huwelijken"},"bk_581":{"lemma":"buurt","displayNl":"de buurt","pos":"substantief","meanings":[{"de":"die Nachbarschaft, das Viertel","ex":"Onze buurt is rustig.","exDe":"Unsere Nachbarschaft ist ruhig."},{"de":"die Umgebung, die Nähe","ex":"Is er een supermarkt in de buurt?","exDe":"Gibt es einen Supermarkt in der Nähe?"}],"usage":"Auch in der festen Wendung 'in de buurt' = in der Nähe.","genus":"de","plural":"buurten","illustratable":true},"bk_582":{"lemma":"groep","displayNl":"de groep","pos":"substantief","meanings":[{"de":"die Gruppe","ex":"We reizen in een groep.","exDe":"Wir reisen in einer Gruppe."},{"de":"die (Schul-)Klasse, Jahrgangsstufe (Grundschule NL)","ex":"Mijn zoon zit in groep drie.","exDe":"Mein Sohn ist in der dritten Klasse."}],"usage":"In den Niederlanden bezeichnet 'groep' auch die Jahrgangsstufe der Grundschule (groep 1 bis 8).","genus":"de","plural":"groepen"},"bk_583":{"lemma":"team","displayNl":"het team","pos":"substantief","meanings":[{"de":"das Team, die Mannschaft","ex":"Ons team wint vaak.","exDe":"Unsere Mannschaft gewinnt oft."}],"usage":"Aus dem Englischen entlehnt; Plural auf -s.","genus":"het","plural":"teams"},"bk_584":{"lemma":"persoon","displayNl":"de persoon","pos":"substantief","meanings":[{"de":"die Person, der Mensch","ex":"Er is nog een persoon.","exDe":"Es ist noch eine Person da."},{"de":"die Person (Grammatik)","ex":"Het werkwoord staat in de eerste persoon.","exDe":"Das Verb steht in der ersten Person."}],"usage":"Zaehlwort für Menschen; grammatischer Fachbegriff (eerste/tweede/derde persoon).","genus":"de","plural":"personen"},"bk_585":{"lemma":"volwassene","displayNl":"de volwassene","pos":"substantief","meanings":[{"de":"der/die Erwachsene","ex":"Een volwassene betaalt meer.","exDe":"Ein Erwachsener zahlt mehr."}],"usage":"Substantiviertes Adjektiv (volwassen = erwachsen); Plural volwassenen.","genus":"de","plural":"volwassenen"},"bk_586":{"lemma":"tiener","displayNl":"de tiener","pos":"substantief","meanings":[{"de":"der Teenager, der/die Jugendliche","ex":"De tiener luistert naar muziek.","exDe":"Der Teenager hört Musik."}],"usage":"Umgangssprachlich für Jugendliche etwa zwischen 13 und 19.","genus":"de","plural":"tieners","illustratable":true},"bk_587":{"lemma":"dame","displayNl":"de dame","pos":"substantief","meanings":[{"de":"die Dame","ex":"De dame draagt een hoed.","exDe":"Die Dame trägt einen Hut."},{"de":"die Dame (Schachfigur / Damespiel)","ex":"Ze slaat mijn dame met haar toren.","exDe":"Sie schlägt meine Dame mit ihrem Turm."}],"usage":"Hoefliche Anrede 'dames en heren' = meine Damen und Herren; auch Spielbegriff.","genus":"de","plural":"dames","illustratable":true},"bk_588":{"lemma":"heer","displayNl":"de heer","pos":"substantief","meanings":[{"de":"der Herr","ex":"De heer wacht bij de deur.","exDe":"Der Herr wartet an der Tür."},{"de":"der Herr (Gott, religioes)","ex":"Wij danken de Heer.","exDe":"Wir danken dem Herrn."}],"usage":"Hoefliche Anrede 'de heer De Vries' = Herr De Vries; grossgeschrieben 'de Heer' für Gott. Plural heren.","genus":"de","plural":"heren","illustratable":true},"bk_589":{"lemma":"vreemdeling","displayNl":"de vreemdeling","pos":"substantief","meanings":[{"de":"der Fremde, die fremde/unbekannte Person","ex":"Een vreemdeling vraagt de weg.","exDe":"Ein Fremder fragt nach dem Weg."},{"de":"der Ausländer, die ausländische Person","ex":"De gemeente helpt vreemdelingen met hun papieren.","exDe":"Die Gemeinde hilft Ausländern mit ihren Papieren."}],"usage":"Person, die man nicht kennt, oder jemand aus einem anderen Land.","genus":"de","plural":"vreemdelingen"},"bk_590":{"lemma":"klasgenoot","displayNl":"de klasgenoot","pos":"substantief","meanings":[{"de":"der Mitschüler, der Klassenkamerad","ex":"Mijn klasgenoot is ziek.","exDe":"Mein Mitschüler ist krank."}],"usage":"Jemand, der in derselben Schulklasse ist.","genus":"de","plural":"klasgenoten"},"bk_591":{"lemma":"huisgenoot","displayNl":"de huisgenoot","pos":"substantief","meanings":[{"de":"der Mitbewohner, der Hausgenosse","ex":"Mijn huisgenoot kookt vandaag.","exDe":"Mein Mitbewohner kocht heute."}],"usage":"Person, mit der man zusammen in einem Haus/einer Wohnung wohnt.","genus":"de","plural":"huisgenoten"},"bk_592":{"lemma":"schoonmoeder","displayNl":"de schoonmoeder","pos":"substantief","meanings":[{"de":"die Schwiegermutter","ex":"Mijn schoonmoeder komt op bezoek.","exDe":"Meine Schwiegermutter kommt zu Besuch."}],"usage":"Die Mutter des Partners bzw. der Partnerin.","genus":"de","plural":"schoonmoeders"},"bk_593":{"lemma":"schoonvader","displayNl":"de schoonvader","pos":"substantief","meanings":[{"de":"der Schwiegervater","ex":"Mijn schoonvader is aardig.","exDe":"Mein Schwiegervater ist nett."}],"usage":"Der Vater des Partners bzw. der Partnerin.","genus":"de","plural":"schoonvaders"},"bk_594":{"lemma":"schoonzus","displayNl":"de schoonzus","pos":"substantief","meanings":[{"de":"die Schwägerin","ex":"Mijn schoonzus woont in Utrecht.","exDe":"Meine Schwägerin wohnt in Utrecht."}],"usage":"Die Schwester des Partners oder die Frau des Bruders.","genus":"de","plural":"schoonzussen"},"bk_595":{"lemma":"zwager","displayNl":"de zwager","pos":"substantief","meanings":[{"de":"der Schwager","ex":"Mijn zwager speelt tennis.","exDe":"Mein Schwager spielt Tennis."}],"usage":"Der Bruder des Partners oder der Mann der Schwester.","genus":"de","plural":"zwagers"},"bk_596":{"lemma":"stiefmoeder","displayNl":"de stiefmoeder","pos":"substantief","meanings":[{"de":"die Stiefmutter","ex":"Zijn stiefmoeder is lief.","exDe":"Seine Stiefmutter ist lieb."}],"usage":"Die neue Partnerin des Vaters, nicht die leibliche Mutter.","genus":"de","plural":"stiefmoeders"},"bk_597":{"lemma":"stiefvader","displayNl":"de stiefvader","pos":"substantief","meanings":[{"de":"der Stiefvater","ex":"Haar stiefvader werkt hard.","exDe":"Ihr Stiefvater arbeitet hart."}],"usage":"Familienbeziehung: der neue Ehemann der Mutter. Weiblich: de stiefmoeder.","genus":"de","plural":"stiefvaders","notes":"Zusammensetzung stief- + vader."},"bk_598":{"lemma":"kind","displayNl":"het kind","pos":"substantief","meanings":[{"de":"das Kind","ex":"Het kind speelt in de tuin.","exDe":"Das Kind spielt im Garten."},{"de":"das Kind (im Verhältnis zu den Eltern), Sohn/Tochter","ex":"Ze hebben drie kinderen.","exDe":"Sie haben drei Kinder."}],"usage":"Eingabe war Plural 'de kinderen' → Singular 'het kind'. Unregelmäßiger Plural: kinderen (nicht 'kinden'). Verkleinerung: het kindje.","genus":"het","plural":"kinderen","notes":"Plural kinderen ist eine der wenigen -eren-Formen im Niederländischen.","illustratable":true},"bk_599":{"lemma":"verliefd","displayNl":"verliefd","pos":"adjectief","meanings":[{"de":"verliebt","ex":"Zij is verliefd op hem.","exDe":"Sie ist in ihn verliebt."}],"usage":"Feste Präposition: verliefd OP iemand (verliebt in jemanden), nicht 'in'. Partizip-Adjektiv zu 'verlieven'."},"bk_600":{"lemma":"getrouwd","displayNl":"getrouwd","pos":"adjectief","meanings":[{"de":"verheiratet","ex":"Ze zijn al tien jaar getrouwd.","exDe":"Sie sind schon zehn Jahre verheiratet."}],"usage":"Zustands-Adjektiv/Partizip von 'trouwen'. Feste Präposition: getrouwd MET iemand (verheiratet mit jemandem). Gegenteil: gescheiden.","notes":"Zugleich Partizip Perfekt von trouwen."},"bk_601":{"lemma":"single","displayNl":"single","pos":"adjectief","meanings":[{"de":"Single, alleinstehend (unverheiratet, ohne Partner)","ex":"Hij is nog single.","exDe":"Er ist noch Single."},{"de":"die Single (einzelne Musikveröffentlichung)","ex":"De band bracht een nieuwe single uit.","exDe":"Die Band brachte eine neue Single heraus."}],"usage":"Englisches Lehnwort. Als Adjektiv (prädikativ: is single). Als Substantiv 'de single' (Plural singles) für die Musik-Bedeutung.","notes":"Homonym: Adjektiv (Beziehungsstatus) vs. Substantiv (Musik)."},"bk_602":{"lemma":"trouwen","displayNl":"trouwen","pos":"werkwoord","meanings":[{"de":"heiraten","ex":"Ze gaan volgend jaar trouwen.","exDe":"Sie werden nächstes Jahr heiraten."}],"usage":"Bewegungs-/Zustandswechselverb → Hilfsverb 'zijn' (ik ben getrouwd). Feste Präposition: trouwen MET iemand.","conjugation":{"presens":{"ik":"trouw","jij":"trouwt","hij":"trouwt","wij":"trouwen"},"imperfectum":{"ik":"trouwde","wij":"trouwden"},"perfectum":{"aux":"zijn","participle":"getrouwd"}},"illustratable":true},"bk_603":{"lemma":"kennismaken","displayNl":"kennismaken","pos":"werkwoord","meanings":[{"de":"kennenlernen, Bekanntschaft machen","ex":"Leuk om kennis te maken.","exDe":"Schön, dich kennenzulernen."},{"de":"sich mit etwas vertraut machen, etwas kennenlernen","ex":"We maken kennis met de nieuwe software.","exDe":"Wir machen uns mit der neuen Software vertraut."}],"usage":"Trennbares Verb (kennis maken): in Hauptsätzen getrennt – ik maak kennis met hem. Feste Präposition: kennismaken MET. Perfekt-Partizip: kennisgemaakt.","conjugation":{"presens":{"ik":"maak kennis","jij":"maakt kennis","hij":"maakt kennis","wij":"maken kennis"},"imperfectum":{"ik":"maakte kennis","wij":"maakten kennis"},"perfectum":{"aux":"hebben","participle":"kennisgemaakt"}},"notes":"Zusammengesetzt aus dem Substantiv 'kennis' und 'maken'.","illustratable":true},"bk_604":{"lemma":"begroeten","displayNl":"begroeten","pos":"werkwoord","meanings":[{"de":"begrüßen, willkommen heißen","ex":"We begroeten de gasten.","exDe":"Wir begrüßen die Gäste."}],"usage":"Untrennbares Verb (Präfix be-), daher Partizip ohne ge-: begroet. Regelmäßig; Stamm 'begroet' → Präteritum mit -tte.","conjugation":{"presens":{"ik":"begroet","jij":"begroet","hij":"begroet","wij":"begroeten"},"imperfectum":{"ik":"begroette","wij":"begroetten"},"perfectum":{"aux":"hebben","participle":"begroet"}},"illustratable":true},"bk_605":{"lemma":"knuffel","displayNl":"de knuffel","pos":"substantief","meanings":[{"de":"die Umarmung","ex":"Ze geeft hem een dikke knuffel.","exDe":"Sie gibt ihm eine dicke Umarmung."},{"de":"das Kuscheltier, das Plüschtier","ex":"Het kind slaapt met zijn knuffel.","exDe":"Das Kind schläft mit seinem Kuscheltier."}],"usage":"Sowohl „Umarmung“ als auch „Kuscheltier“; „een knuffel geven“ = umarmen.","genus":"de","plural":"knuffels","illustratable":true},"bk_606":{"lemma":"kus","displayNl":"de kus","pos":"substantief","meanings":[{"de":"der Kuss","ex":"Hij geeft haar een kus op de wang.","exDe":"Er gibt ihr einen Kuss auf die Wange."}],"usage":"Plural „kussen“ ist identisch mit „die Kissen“ – Kontext beachten.","genus":"de","plural":"kussen","illustratable":true},"bk_607":{"lemma":"aardig","displayNl":"aardig","pos":"adjectief","meanings":[{"de":"nett, freundlich, liebenswürdig","ex":"Zij is heel aardig voor iedereen.","exDe":"Sie ist sehr nett zu allen."},{"de":"ziemlich, ganz schön (verstärkend, umgangssprachlich)","ex":"Dat is een aardig eind lopen.","exDe":"Das ist ein ganz schönes Stück zu laufen."}],"usage":"Meist „nett“; adverbial verstärkend „ziemlich/ganz schön“."},"bk_608":{"lemma":"vriendelijk","displayNl":"vriendelijk","pos":"adjectief","meanings":[{"de":"freundlich","ex":"De ober is heel vriendelijk.","exDe":"Der Kellner ist sehr freundlich."},{"de":"nett, entgegenkommend","ex":"Bedankt voor uw vriendelijke hulp.","exDe":"Danke für Ihre freundliche Hilfe."}],"usage":"Auch in Höflichkeitsfloskeln: „met vriendelijke groet“ = mit freundlichen Grüßen."},"bk_609":{"lemma":"collega","displayNl":"de collega","pos":"substantief","meanings":[{"de":"der Kollege, die Kollegin","ex":"Mijn collega's zijn heel aardig.","exDe":"Meine Kollegen sind sehr nett."}],"usage":"Eingabe war Plural „collega's“; Grundform Singular „collega“. Plural mit Apostroph-s.","genus":"de","plural":"collega's","illustratable":true},"bk_610":{"lemma":"tong","displayNl":"de tong","pos":"substantief","meanings":[{"de":"die Zunge (Körperteil)","ex":"Steek je tong eens uit.","exDe":"Streck mal deine Zunge raus."},{"de":"die Seezunge (Speisefisch)","ex":"We eten vanavond gebakken tong.","exDe":"Wir essen heute Abend gebratene Seezunge."}],"usage":"Homonym: Körperteil „Zunge“ und der Fisch „Seezunge“.","genus":"de","plural":"tongen","illustratable":true},"bk_611":{"lemma":"lip","displayNl":"de lip","pos":"substantief","meanings":[{"de":"die Lippe","ex":"In de winter zijn mijn lippen droog.","exDe":"Im Winter sind meine Lippen trocken."}],"usage":"Meist im Plural „lippen“ für beide Lippen.","genus":"de","plural":"lippen","illustratable":true},"bk_612":{"lemma":"wang","displayNl":"de wang","pos":"substantief","meanings":[{"de":"die Wange, die Backe","ex":"Zijn wangen worden rood van de kou.","exDe":"Seine Wangen werden rot von der Kälte."}],"usage":"Substantief de-Wort; oft im Plural „wangen“.","genus":"de","plural":"wangen","illustratable":true},"bk_613":{"lemma":"kin","displayNl":"de kin","pos":"substantief","meanings":[{"de":"das Kinn","ex":"Hij heeft een baard op zijn kin.","exDe":"Er hat einen Bart am Kinn."},{"de":"das Doppelkinn (in Zusammensetzung: onderkin)","ex":"Met de jaren kreeg hij een dubbele kin.","exDe":"Mit den Jahren bekam er ein Doppelkinn."}],"usage":"Alltägliches Körperteil-Substantiv; oft mit possessivem Pronomen (zijn/haar kin).","genus":"de","plural":"kinnen","illustratable":true},"bk_614":{"lemma":"nek","displayNl":"de nek","pos":"substantief","meanings":[{"de":"der Nacken (hinterer Halsbereich)","ex":"Mijn nek is stijf.","exDe":"Mein Nacken ist steif."},{"de":"der Hals/Nacken (in Wendungen)","ex":"Hij keek over zijn schouder en draaide zijn nek.","exDe":"Er blickte über die Schulter und drehte seinen Nacken."}],"usage":"Bezeichnet vor allem den hinteren Halsbereich; haufig bei Beschwerden (stijve nek).","genus":"de","plural":"nekken","illustratable":true},"bk_615":{"lemma":"hals","displayNl":"de hals","pos":"substantief","meanings":[{"de":"der Hals (Körperteil)","ex":"Zij draagt een sjaal om haar hals.","exDe":"Sie trägt einen Schal um den Hals."},{"de":"der Hals (eines Gegenstands, z. B. Flasche, Gitarre)","ex":"Hij pakte de fles bij de hals.","exDe":"Er fasste die Flasche am Hals."}],"usage":"Bezeichnet den ganzen (vorderen) Hals als Körperteil, aber auch den schmalen Teil von Objekten.","genus":"de","plural":"halzen","illustratable":true},"bk_616":{"lemma":"keel","displayNl":"de keel","pos":"substantief","meanings":[{"de":"der Rachen / die Kehle","ex":"Mijn keel doet pijn.","exDe":"Mein Hals (Rachen) tut weh."},{"de":"der Hals (beim Sprechen/Singen, Stimme)","ex":"Hij schraapte zijn keel voordat hij begon te zingen.","exDe":"Er räusperte sich, bevor er zu singen begann."}],"usage":"Innerer Halsbereich; typisch bei Halsschmerzen (keelpijn) und beim Sprechen/Singen.","genus":"de","plural":"kelen","illustratable":true},"bk_617":{"lemma":"schouder","displayNl":"de schouder","pos":"substantief","meanings":[{"de":"die Schulter","ex":"Mijn schouder is pijnlijk.","exDe":"Meine Schulter ist schmerzhaft."},{"de":"die Schulter (übertragen, z. B. schouder ophalen = mit den Schultern zucken)","ex":"Hij haalde zijn schouders op.","exDe":"Er zuckte mit den Schultern."}],"usage":"Häufiges Körperteil; oft im Plural (schouders) und in festen Wendungen.","genus":"de","plural":"schouders","illustratable":true},"bk_618":{"lemma":"duim","displayNl":"de duim","pos":"substantief","meanings":[{"de":"der Daumen","ex":"Mijn duim doet zeer.","exDe":"Mein Daumen tut weh."},{"de":"der Daumen (Geste: duim omhoog = Daumen hoch)","ex":"Ze stak haar duim omhoog als teken van goedkeuring.","exDe":"Sie hob den Daumen als Zeichen der Zustimmung."}],"usage":"Finger der Hand; auch in Gesten und Wendungen (duim omhoog, duimen voor iemand).","genus":"de","plural":"duimen","illustratable":true},"bk_619":{"lemma":"nagel","displayNl":"de nagel","pos":"substantief","meanings":[{"de":"der (Finger-/Zehen-)Nagel","ex":"Mijn nagels zijn lang.","exDe":"Meine Nägel sind lang."},{"de":"der Nagel (aus Metall, zum Einschlagen)","ex":"Hij sloeg een nagel in de muur om de foto op te hangen.","exDe":"Er schlug einen Nagel in die Wand, um das Foto aufzuhängen."}],"usage":"Bezeichnet sowohl Finger-/Zehennägel als auch metallische Nägel; für Metallnägel ist 'spijker' gängiger.","genus":"de","plural":"nagels","illustratable":true},"bk_620":{"lemma":"borst","displayNl":"de borst","pos":"substantief","meanings":[{"de":"die Brust / der Brustkorb","ex":"Ik voel druk op mijn borst.","exDe":"Ich fühle Druck auf der Brust."},{"de":"die (weibliche) Brust","ex":"De moeder gaf haar baby borstvoeding.","exDe":"Die Mutter stillte ihr Baby an der Brust."}],"usage":"Bezeichnet den Brustkorb allgemein sowie die weibliche Brust; oft in Zusammensetzungen (borstkas, borstvoeding).","genus":"de","plural":"borsten","illustratable":true},"bk_621":{"lemma":"knie","displayNl":"de knie","pos":"substantief","meanings":[{"de":"das Knie","ex":"Mijn knie doet pijn.","exDe":"Mein Knie tut weh."},{"de":"das Knie (einer Hose, Biegung)","ex":"Er zit een gat in de knie van mijn broek.","exDe":"In meiner Hose ist ein Loch am Knie."}],"usage":"Körperteil: Gelenk zwischen Ober- und Unterschenkel. Beugt sich beim Gehen und Knien.","genus":"de","plural":"knieën","illustratable":true},"bk_622":{"lemma":"teen","displayNl":"de teen","pos":"substantief","meanings":[{"de":"der Zeh, die Zehe","ex":"Ik stootte mijn teen.","exDe":"Ich stieß mir den Zeh."},{"de":"die Zehe (z. B. Knoblauchzehe)","ex":"Doe een teen knoflook in de pan.","exDe":"Gib eine Knoblauchzehe in die Pfanne."}],"usage":"Meist der Fußzeh; als 'teen knoflook' auch eine Knoblauchzehe.","genus":"de","plural":"tenen","illustratable":true},"bk_623":{"lemma":"hart","displayNl":"het hart","pos":"substantief","meanings":[{"de":"das Herz (Organ)","ex":"Mijn hart klopt snel.","exDe":"Mein Herz schlägt schnell."},{"de":"das Herz (Zentrum, Mittelpunkt)","ex":"We wonen in het hart van de stad.","exDe":"Wir wohnen im Herzen der Stadt."},{"de":"das Herz (Gemüt, Gefühl, Mut)","ex":"Ze heeft een goed hart.","exDe":"Sie hat ein gutes Herz."}],"usage":"Organ, das das Blut pumpt; übertragen Zentrum oder Gemüt/Gefühl.","genus":"het","plural":"harten","illustratable":true},"bk_624":{"lemma":"huid","displayNl":"de huid","pos":"substantief","meanings":[{"de":"die Haut","ex":"Mijn huid is droog.","exDe":"Meine Haut ist trocken."},{"de":"das Fell, die Tierhaut (abgezogen)","ex":"De jager verkocht de huid van het dier.","exDe":"Der Jäger verkaufte die Haut des Tieres."}],"usage":"Äußere Hülle des menschlichen Körpers; bei Tieren auch das abgezogene Fell.","genus":"de","plural":"huiden","illustratable":true},"bk_625":{"lemma":"bloed","displayNl":"het bloed","pos":"substantief","meanings":[{"de":"das Blut","ex":"Er zit bloed op het verband.","exDe":"Es ist Blut auf dem Verband."}],"usage":"Rote Körperflüssigkeit; Stoffname ohne gebräuchlichen Plural.","genus":"het","illustratable":true},"bk_627":{"lemma":"gezondheid","displayNl":"de gezondheid","pos":"substantief","meanings":[{"de":"die Gesundheit","ex":"Gezondheid is belangrijk.","exDe":"Gesundheit ist wichtig."},{"de":"Gesundheit! (Zuruf, wenn jemand niest)","ex":"Hatsjie! – Gezondheid!","exDe":"Hatschi! – Gesundheit!"}],"usage":"Zustand des körperlichen Wohlbefindens; als Ausruf 'Gezondheid!' auch nach dem Niesen. Abstrakt, daher nicht bildlich darstellbar.","genus":"de"},"bk_628":{"lemma":"koorts","displayNl":"de koorts","pos":"substantief","meanings":[{"de":"das Fieber","ex":"Het kind heeft koorts.","exDe":"Das Kind hat Fieber."}],"usage":"Erhöhte Körpertemperatur bei Krankheit. Abstrakter Zustand, nicht eindeutig bildlich darstellbar.","genus":"de","plural":"koortsen"},"bk_629":{"lemma":"griep","displayNl":"de griep","pos":"substantief","meanings":[{"de":"die Grippe","ex":"Ik heb de griep.","exDe":"Ich habe die Grippe."}],"usage":"Ansteckende Viruserkrankung mit Fieber und Gliederschmerzen; meist mit Artikel 'de griep'. Abstrakter Krankheitsbegriff, nicht eindeutig bildlich darstellbar.","genus":"de"},"bk_630":{"lemma":"verkoudheid","displayNl":"de verkoudheid","pos":"substantief","meanings":[{"de":"die Erkältung","ex":"Zij heeft een verkoudheid.","exDe":"Sie hat eine Erkältung."},{"de":"der Schnupfen","ex":"Door de verkoudheid is mijn neus verstopt.","exDe":"Durch den Schnupfen ist meine Nase verstopft."}],"usage":"Die häufige, meist harmlose Atemwegsinfektion. Man 'heeft' een verkoudheid oder ist 'verkouden' (Adjektiv).","genus":"de","plural":"verkoudheden"},"bk_631":{"lemma":"keelpijn","displayNl":"de keelpijn","pos":"substantief","meanings":[{"de":"die Halsschmerzen","ex":"Ik heb keelpijn.","exDe":"Ich habe Halsschmerzen."}],"usage":"Meist unzählbar; ohne Artikel gebraucht: 'keelpijn hebben'. Bezeichnet Schmerzen im Rachen/Hals.","genus":"de"},"bk_632":{"lemma":"kiespijn","displayNl":"de kiespijn","pos":"substantief","meanings":[{"de":"die Zahnschmerzen","ex":"Hij heeft kiespijn.","exDe":"Er hat Zahnschmerzen."}],"usage":"Von 'kies' (Backenzahn); meist unzählbar, ohne Artikel: 'kiespijn hebben'. Allgemein für Zahnschmerzen.","genus":"de"},"bk_633":{"lemma":"rugpijn","displayNl":"de rugpijn","pos":"substantief","meanings":[{"de":"die Rückenschmerzen","ex":"Zij heeft vaak rugpijn.","exDe":"Sie hat oft Rückenschmerzen."}],"usage":"Von 'rug' (Rücken); meist unzählbar, ohne Artikel: 'rugpijn hebben'.","genus":"de"},"bk_634":{"lemma":"hoest","displayNl":"de hoest","pos":"substantief","meanings":[{"de":"der Husten","ex":"Ik heb een droge hoest.","exDe":"Ich habe einen trockenen Husten."}],"usage":"Das Symptom Husten als Substantiv; das zugehörige Verb ist 'hoesten'.","genus":"de"},"bk_635":{"lemma":"wond","displayNl":"de wond","pos":"substantief","meanings":[{"de":"die Wunde","ex":"De wond bloedt.","exDe":"Die Wunde blutet."},{"de":"die Verletzung","ex":"De verpleegkundige verbindt de wond.","exDe":"Die Pflegekraft verbindet die Verletzung."}],"usage":"Verletzung der Haut/des Gewebes; auch übertragen für seelische Wunden. Adjektiv 'wond' (=wund) ist davon zu trennen.","genus":"de","plural":"wonden","illustratable":true},"bk_636":{"lemma":"arts","displayNl":"de arts","pos":"substantief","meanings":[{"de":"der Arzt / die Ärztin","ex":"De arts onderzoekt de patiënt.","exDe":"Der Arzt untersucht den Patienten."},{"de":"der Mediziner","ex":"Na zes jaar studie werd zij arts.","exDe":"Nach sechs Jahren Studium wurde sie Medizinerin."}],"usage":"Allgemeine Bezeichnung für einen approbierten Mediziner (m/w). Vgl. spezifischer 'huisarts' (Hausarzt), 'tandarts' (Zahnarzt).","genus":"de","plural":"artsen","illustratable":true},"bk_637":{"lemma":"huisarts","displayNl":"de huisarts","pos":"substantief","meanings":[{"de":"der Hausarzt / die Hausärztin","ex":"Mijn huisarts is heel aardig.","exDe":"Mein Hausarzt ist sehr nett."},{"de":"der Allgemeinmediziner","ex":"Voor een verwijzing ga je eerst naar de huisarts.","exDe":"Für eine Überweisung geht man zuerst zum Allgemeinmediziner."}],"usage":"Der erste ärztliche Ansprechpartner im niederländischen Gesundheitssystem, der bei Bedarf an Fachärzte überweist. Zusammensetzung aus 'huis' + 'arts'.","genus":"de","plural":"huisartsen","illustratable":true},"bk_638":{"lemma":"patiënt","displayNl":"de patiënt","pos":"substantief","meanings":[{"de":"der Patient / die Patientin","ex":"De patiënt ligt in bed.","exDe":"Der Patient liegt im Bett."},{"de":"der/die Erkrankte (in ärztlicher Behandlung)","ex":"De dokter onderzoekt de patiënt zorgvuldig.","exDe":"Der Arzt untersucht den Patienten sorgfältig."}],"usage":"Personenbezeichnung, geschlechtsneutral verwendbar; weibliche Form auch 'patiënte'. Betonung auf der letzten Silbe, Trema auf dem i.","genus":"de","plural":"patiënten","illustratable":true},"bk_639":{"lemma":"apotheek","displayNl":"de apotheek","pos":"substantief","meanings":[{"de":"die Apotheke","ex":"Ik haal medicijnen bij de apotheek.","exDe":"Ich hole Medikamente in der Apotheke."},{"de":"die Apotheke (als Betrieb/Geschäft)","ex":"De apotheek is tot zes uur open.","exDe":"Die Apotheke hat bis sechs Uhr geöffnet."}],"usage":"Ort, an dem Medikamente abgegeben werden; die Person dahinter ist 'apotheker'. Achtung: falscher Freund zu deutsch 'Drogerie' – Alltagsartikel gibt es in NL eher in der 'drogist'.","genus":"de","plural":"apotheken","illustratable":true},"bk_640":{"lemma":"recept","displayNl":"het recept","pos":"substantief","meanings":[{"de":"das Rezept (ärztliche Verordnung)","ex":"De dokter schrijft een recept.","exDe":"Der Arzt schreibt ein Rezept."},{"de":"das Rezept (Kochanleitung)","ex":"Dit recept voor appeltaart is heel makkelijk.","exDe":"Dieses Rezept für Apfelkuchen ist ganz einfach."}],"usage":"Echtes Homonym: sowohl die ärztliche Verordnung als auch die Kochanleitung. Der Kontext entscheidet die Bedeutung.","genus":"het","plural":"recepten","illustratable":true},"bk_641":{"lemma":"medicijn","displayNl":"het medicijn","pos":"substantief","meanings":[{"de":"das Medikament, die Arznei","ex":"Neem dit medicijn drie keer per dag.","exDe":"Nimm dieses Medikament dreimal am Tag."},{"de":"die Medizin (Heilmittel allgemein)","ex":"Er is nog geen medicijn tegen deze ziekte.","exDe":"Es gibt noch kein Medikament gegen diese Krankheit."}],"usage":"Häufig im Plural 'medicijnen' für die einzunehmenden Präparate. 'de geneeskunde' meint dagegen die Medizin als Wissenschaft.","genus":"het","plural":"medicijnen","illustratable":true},"bk_642":{"lemma":"pil","displayNl":"de pil","pos":"substantief","meanings":[{"de":"die Pille, die Tablette","ex":"Ik neem elke ochtend een pil.","exDe":"Ich nehme jeden Morgen eine Pille."},{"de":"die Antibabypille (Verhütung)","ex":"Zij is aan de pil.","exDe":"Sie nimmt die Pille."}],"usage":"'aan de pil zijn' ist feste Wendung für die Verhütung mit der Antibabypille. Redensart 'een bittere pil' = eine bittere Pille (etwas Unangenehmes).","genus":"de","plural":"pillen","illustratable":true},"bk_643":{"lemma":"tablet","displayNl":"de tablet","pos":"substantief","meanings":[{"de":"die Tablette (Medikament)","ex":"Neem twee tabletten met water.","exDe":"Nimm zwei Tabletten mit Wasser."},{"de":"das Tablet (Computer)","ex":"Ik lees het nieuws op mijn tablet.","exDe":"Ich lese die Nachrichten auf meinem Tablet."}],"usage":"Bedeutungsabhängiges Genus: die Medikamenten-Tablette ist 'de tablet' (Plural 'tabletten'); der Computer ist meist 'de tablet', kann aber auch 'het tablet' sein (Plural 'tablets'). Hier medizinische Grundbedeutung.","genus":"de","plural":"tabletten","illustratable":true},"bk_644":{"lemma":"pleister","displayNl":"de pleister","pos":"substantief","meanings":[{"de":"das Pflaster (Wundpflaster)","ex":"Ik plak een pleister op de wond.","exDe":"Ich klebe ein Pflaster auf die Wunde."},{"de":"der Verputz, der Mörtel (auf Wänden)","ex":"De pleister bladdert van de muur.","exDe":"Der Putz blättert von der Wand."}],"usage":"Achtung: die Straße/der Bodenbelag heißt in NL 'stoep' bzw. 'plaveisel', nicht 'pleister'. Redensart 'een pleister op de wond' = ein Trostpflaster.","genus":"de","plural":"pleisters","illustratable":true},"bk_645":{"lemma":"ambulance","displayNl":"de ambulance","pos":"substantief","meanings":[{"de":"der Krankenwagen, der Rettungswagen","ex":"De ambulance komt snel.","exDe":"Der Krankenwagen kommt schnell."},{"de":"der Rettungsdienst (als Notfalleinsatz)","ex":"Bel snel een ambulance!","exDe":"Ruf schnell einen Krankenwagen!"}],"usage":"In den Niederlanden erreicht man den Notruf über 112. Plural mit -s: 'ambulances'.","genus":"de","plural":"ambulances","illustratable":true},"bk_646":{"lemma":"fit","displayNl":"fit","pos":"adjectief","meanings":[{"de":"fit, in guter körperlicher Verfassung","ex":"Na de vakantie ben ik weer fit.","exDe":"Nach dem Urlaub bin ich wieder fit."},{"de":"gesund, munter","ex":"Hij is voor zijn leeftijd nog erg fit.","exDe":"Er ist für sein Alter noch sehr fit."}],"usage":"Prädikatives Adjektiv, meist mit 'zijn' oder 'voelen'. Unveränderlich, keine Beugung ('een fitte man' ist möglich, aber ungewöhnlich)."},"bk_647":{"lemma":"zwak","displayNl":"zwak","pos":"adjectief","meanings":[{"de":"schwach, kraftlos (körperlich)","ex":"Na de griep voel ik me zwak.","exDe":"Nach der Grippe fühle ich mich schwach."},{"de":"schwach, gering (Signal, Kaffee, Leistung)","ex":"Het wifisignaal is hier heel zwak.","exDe":"Das WLAN-Signal ist hier sehr schwach."},{"de":"schwach, nachgiebig (Charakter)","ex":"Op dat punt is hij een beetje zwak.","exDe":"In diesem Punkt ist er ein bisschen schwach."}],"usage":"Attributiv gebeugt: 'een zwakke man', 'het zwakke kind'. Komparativ 'zwakker', Superlativ 'zwakst'."},"bk_648":{"lemma":"verkouden","displayNl":"verkouden","pos":"adjectief","meanings":[{"de":"erkältet, verschnupft","ex":"Ik ben verkouden.","exDe":"Ich bin erkältet."},{"de":"eine Erkältung habend","ex":"De kinderen zijn allemaal verkouden.","exDe":"Die Kinder sind alle erkältet."}],"usage":"Fast nur prädikativ mit 'zijn' oder 'worden' ('verkouden worden' = sich erkälten). Nicht steigerbar."},"bk_649":{"lemma":"beter","displayNl":"beter","pos":"adjectief","meanings":[{"de":"besser (Komparativ von 'goed')","ex":"Deze oplossing is veel beter.","exDe":"Diese Lösung ist viel besser."},{"de":"wieder gesund, genesen","ex":"Ik voel me al beter.","exDe":"Ich fühle mich schon besser."},{"de":"lieber, eher (ratend)","ex":"Je kunt beter een dokter bellen.","exDe":"Du rufst besser einen Arzt an."}],"usage":"Komparativform von 'goed'; Superlativ 'best'. Als Adjektiv und Adverb. 'weer beter zijn/worden' = wieder gesund werden."},"bk_650":{"lemma":"rust","displayNl":"de rust","pos":"substantief","meanings":[{"de":"die Ruhe, Erholung","ex":"De zieke heeft rust nodig.","exDe":"Der Kranke braucht Ruhe."},{"de":"die Stille, der Frieden","ex":"In het bos heerst een prettige rust.","exDe":"Im Wald herrscht eine angenehme Ruhe."},{"de":"die Pause, Halbzeit (Sport)","ex":"Bij de rust stond het 1-0.","exDe":"Zur Halbzeit stand es 1:0."}],"usage":"Meist unzählbar (Sing.). Feste Wendungen: 'rust nemen', 'tot rust komen', 'met rust laten' (in Ruhe lassen). Plural 'rusten' selten.","genus":"de","plural":"rusten"},"bk_651":{"lemma":"slaap","displayNl":"de slaap","pos":"substantief","meanings":[{"de":"der Schlaf","ex":"Slaap is goed voor je gezondheid.","exDe":"Schlaf ist gut für die Gesundheit."},{"de":"die Schläfe (Kopf)","ex":"Ze kuste hem op zijn slaap.","exDe":"Sie küsste ihn auf die Schläfe."},{"de":"die Schlaflust, das Müdigkeitsgefühl","ex":"Ik kan de slaap niet vatten.","exDe":"Ich kann nicht einschlafen."}],"usage":"In der Bedeutung 'Schlaf' unzählbar. Homonym 'slaap' = Schläfe, Plural 'slapen'. Wendung 'in slaap vallen' = einschlafen.","genus":"de","plural":"slapen","illustratable":true},"bk_652":{"lemma":"stress","displayNl":"de stress","pos":"substantief","meanings":[{"de":"der Stress, die Anspannung","ex":"Ik heb veel stress op mijn werk.","exDe":"Ich habe viel Stress bei der Arbeit."},{"de":"die Belastung, der Druck","ex":"De examens zorgen voor veel stress.","exDe":"Die Prüfungen sorgen für viel Stress."}],"usage":"Unzählbar, kein Plural. Feste Wendungen: 'stress hebben', 'onder stress staan', 'stress ervaren'.","genus":"de"},"bk_653":{"lemma":"gevoel","displayNl":"het gevoel","pos":"substantief","meanings":[{"de":"das Gefühl, die Empfindung","ex":"Ik heb een raar gevoel in mijn buik.","exDe":"Ich habe ein komisches Gefühl im Bauch."},{"de":"das Gefühl, die Emotion","ex":"Ze toont haar gevoelens niet graag.","exDe":"Sie zeigt ihre Gefühle nicht gern."},{"de":"das Gespür, der Sinn (für etwas)","ex":"Hij heeft gevoel voor humor.","exDe":"Er hat Sinn für Humor."},{"de":"der Tastsinn, das Gefühl (im Körperteil)","ex":"Door de kou had ik geen gevoel meer in mijn vingers.","exDe":"Durch die Kälte hatte ich kein Gefühl mehr in den Fingern."}],"usage":"Neutrum ('het gevoel'). Plural 'gevoelens' meist für Emotionen. Wendung 'het gevoel hebben dat...' = das Gefühl haben, dass...","genus":"het","plural":"gevoelens"},"bk_654":{"lemma":"voelen","displayNl":"zich voelen","pos":"werkwoord","meanings":[{"de":"sich fühlen (körperlich/seelisch)","ex":"Hoe voel je je vandaag?","exDe":"Wie fühlst du dich heute?"},{"de":"fühlen, spüren, tasten","ex":"Ik voel de warmte van de zon.","exDe":"Ich fühle die Wärme der Sonne."},{"de":"betasten, mit der Hand prüfen","ex":"De dokter voelt aan mijn buik.","exDe":"Der Arzt tastet meinen Bauch ab."}],"usage":"Reflexiv 'zich voelen' für das eigene Befinden (Hoe voel je je?); transitiv 'iets voelen' für Wahrnehmung/Beruehrung.","conjugation":{"presens":{"ik":"voel","jij":"voelt","hij":"voelt","wij":"voelen"},"imperfectum":{"ik":"voelde","wij":"voelden"},"perfectum":{"aux":"hebben","participle":"gevoeld"}}},"bk_655":{"lemma":"hoesten","displayNl":"hoesten","pos":"werkwoord","meanings":[{"de":"husten","ex":"Het kind moet veel hoesten.","exDe":"Das Kind muss viel husten."}],"usage":"Schwaches Verb; Stamm 'hoest', Imperfekt mit -te (hoestte). Rund um Erkaeltung/Krankheit gebraucht.","conjugation":{"presens":{"ik":"hoest","jij":"hoest","hij":"hoest","wij":"hoesten"},"imperfectum":{"ik":"hoestte","wij":"hoestten"},"perfectum":{"aux":"hebben","participle":"gehoest"}},"illustratable":true},"bk_656":{"lemma":"niezen","displayNl":"niezen","pos":"werkwoord","meanings":[{"de":"niesen","ex":"Ik moet steeds niezen.","exDe":"Ich muss ständig niesen."}],"usage":"Schwaches Verb mit stimmhaftem Stamm (z), daher Imperfekt auf -de (niesde) und Partizip geniesd.","conjugation":{"presens":{"ik":"nies","jij":"niest","hij":"niest","wij":"niezen"},"imperfectum":{"ik":"niesde","wij":"niesden"},"perfectum":{"aux":"hebben","participle":"geniesd"}},"illustratable":true},"bk_657":{"lemma":"bloeden","displayNl":"bloeden","pos":"werkwoord","meanings":[{"de":"bluten","ex":"Mijn neus bloedt.","exDe":"Meine Nase blutet."},{"de":"(figurativ) für etwas buessen/teuer bezahlen muessen","ex":"Daarvoor moet je flink bloeden.","exDe":"Dafür musst du kräftig bluten (viel bezahlen)."}],"usage":"Schwaches Verb; Stamm 'bloed', Imperfekt bloedde. Neben woertlich 'bluten' auch umgangssprachlich 'zahlen muessen'.","conjugation":{"presens":{"ik":"bloed","jij":"bloedt","hij":"bloedt","wij":"bloeden"},"imperfectum":{"ik":"bloedde","wij":"bloedden"},"perfectum":{"aux":"hebben","participle":"gebloed"}}},"bk_658":{"lemma":"rusten","displayNl":"rusten","pos":"werkwoord","meanings":[{"de":"ruhen, sich ausruhen","ex":"Je moet nu rusten.","exDe":"Du musst jetzt ruhen."},{"de":"ruhen, lasten (auf etwas aufliegen)","ex":"Het dak rust op vier pilaren.","exDe":"Das Dach ruht auf vier Säulen."}],"usage":"Schwaches Verb; Stamm 'rust', Imperfekt rustte. Haeufig reflexiv-nah 'uitrusten' (sich ausruhen).","conjugation":{"presens":{"ik":"rust","jij":"rust","hij":"rust","wij":"rusten"},"imperfectum":{"ik":"rustte","wij":"rustten"},"perfectum":{"aux":"hebben","participle":"gerust"}},"illustratable":true},"bk_659":{"lemma":"beter worden","displayNl":"beter worden","pos":"uitdrukking","meanings":[{"de":"gesund werden, genesen","ex":"Ik hoop dat je snel beter wordt.","exDe":"Ich hoffe, du wirst schnell gesund."},{"de":"besser werden, sich verbessern","ex":"Zijn Nederlands wordt steeds beter.","exDe":"Sein Niederländisch wird immer besser."}],"usage":"Feste Verbindung aus 'beter' + 'worden'; im Krankheitskontext = genesen, sonst = sich verbessern. 'worden' wird konjugiert (word/wordt/werd/geworden)."},"bk_660":{"lemma":"tandenborstel","displayNl":"de tandenborstel","pos":"substantief","meanings":[{"de":"die Zahnbürste","ex":"Waar is mijn tandenborstel?","exDe":"Wo ist meine Zahnbürste?"}],"usage":"de-Wort, Plural tandenborstels. Zusammensetzung uit 'tanden' (Zaehne) + 'borstel' (Buerste).","genus":"de","plural":"tandenborstels","illustratable":true},"bk_661":{"lemma":"tandpasta","displayNl":"de tandpasta","pos":"substantief","meanings":[{"de":"die Zahnpasta, die Zahncreme","ex":"De tandpasta is bijna op.","exDe":"Die Zahnpasta ist fast leer."}],"usage":"de-Wort, Plural tandpasta's (mit Apostroph vor der s wegen Vokalendung).","genus":"de","plural":"tandpasta's","illustratable":true},"bk_662":{"lemma":"zeep","displayNl":"de zeep","pos":"substantief","meanings":[{"de":"die Seife","ex":"Was je handen met zeep.","exDe":"Wasch deine Hände mit Seife."},{"de":"das Seifenstück","ex":"Er ligt een nieuw stuk zeep bij de wastafel.","exDe":"Am Waschbecken liegt ein neues Stück Seife."}],"usage":"Alltag/Hygiene. Ook: 'zachte zeep' (Schmierseife), 'groene zeep'.","genus":"de","plural":"zepen","illustratable":true},"bk_663":{"lemma":"shampoo","displayNl":"de shampoo","pos":"substantief","meanings":[{"de":"das Shampoo","ex":"Ik gebruik milde shampoo.","exDe":"Ich benutze mildes Shampoo."}],"usage":"Onzijdig wordt soms gehoord, standaard is 'de shampoo'.","genus":"de","plural":"shampoos","illustratable":true},"bk_664":{"lemma":"handdoek","displayNl":"de handdoek","pos":"substantief","meanings":[{"de":"das Handtuch","ex":"Geef mij een schone handdoek.","exDe":"Gib mir ein sauberes Handtuch."}],"usage":"Zusammensetzungen: 'badhanddoek', 'theedoek' (Geschirrtuch, anderes Wort).","genus":"de","plural":"handdoeken","illustratable":true},"bk_665":{"lemma":"spiegel","displayNl":"de spiegel","pos":"substantief","meanings":[{"de":"der Spiegel","ex":"Ik kijk in de spiegel.","exDe":"Ich schaue in den Spiegel."},{"de":"die spiegelnde/glatte Oberfläche","ex":"Het meer lag als een spiegel in de ochtend.","exDe":"Der See lag am Morgen wie ein Spiegel da."}],"usage":"Uitdrukking: 'iemand een spiegel voorhouden' (jdm. den Spiegel vorhalten).","genus":"de","plural":"spiegels","illustratable":true},"bk_666":{"lemma":"kam","displayNl":"de kam","pos":"substantief","meanings":[{"de":"der Kamm (zum Kämmen)","ex":"Ik kam mijn haar met een kam.","exDe":"Ich kämme mein Haar mit einem Kamm."},{"de":"der Kamm (des Hahns)","ex":"De haan heeft een rode kam.","exDe":"Der Hahn hat einen roten Kamm."},{"de":"der Bergkamm / Grat","ex":"We liepen over de kam van de heuvel.","exDe":"Wir gingen über den Kamm des Hügels."}],"usage":"Homonym: Frisierkamm, Hahnenkamm, Bergkamm.","genus":"de","plural":"kammen","illustratable":true},"bk_667":{"lemma":"toiletpapier","displayNl":"het toiletpapier","pos":"substantief","meanings":[{"de":"das Toilettenpapier","ex":"Het toiletpapier is op.","exDe":"Das Toilettenpapier ist alle."}],"usage":"Stofnaam, meestal geen meervoud; informeel ook 'wc-papier'.","genus":"het","illustratable":true},"bk_668":{"lemma":"wassen","displayNl":"zich wassen","pos":"werkwoord","meanings":[{"de":"sich waschen","ex":"Ik was me elke ochtend.","exDe":"Ich wasche mich jeden Morgen."},{"de":"waschen (etw. reinigen)","ex":"Zij wast de vaat na het eten.","exDe":"Sie wäscht das Geschirr nach dem Essen."}],"usage":"Reflexiv 'zich wassen' = sich waschen; ook transitief 'de auto/de was wassen'. Onregelmatig voltooid deelwoord 'gewassen'.","conjugation":{"presens":{"ik":"was","jij":"wast","hij":"wast","wij":"wassen"},"imperfectum":{"ik":"waste","wij":"wasten"},"perfectum":{"aux":"hebben","participle":"gewassen"}}},"bk_669":{"lemma":"douchen","displayNl":"douchen","pos":"werkwoord","meanings":[{"de":"duschen","ex":"Ik douche na het sporten.","exDe":"Ich dusche nach dem Sport."}],"usage":"Zwak werkwoord; klemtoon op 'dou'. Zelfstandig naamwoord: 'de douche'.","conjugation":{"presens":{"ik":"douche","jij":"doucht","hij":"doucht","wij":"douchen"},"imperfectum":{"ik":"douchte","wij":"douchten"},"perfectum":{"aux":"hebben","participle":"gedoucht"}}},"bk_670":{"lemma":"poetsen","displayNl":"poetsen","pos":"werkwoord","meanings":[{"de":"putzen (reinigen)","ex":"Ik poets mijn tanden twee keer per dag.","exDe":"Ich putze meine Zähne zweimal am Tag."},{"de":"polieren, blank putzen","ex":"Hij poetst zijn schönen tot ze glimmen.","exDe":"Er poliert seine Schuhe, bis sie glänzen."}],"usage":"Alltagsverb für Reinigen; oft „tanden poetsen“ (Zähne putzen), „schönen poetsen“ (Schuhe putzen).","conjugation":{"presens":{"ik":"poets","jij":"poetst","hij":"poetst","wij":"poetsen"},"imperfectum":{"ik":"poetste","wij":"poetsten"},"perfectum":{"aux":"hebben","participle":"gepoetst"}},"illustratable":true},"bk_671":{"lemma":"kammen","displayNl":"kammen","pos":"werkwoord","meanings":[{"de":"kämmen","ex":"Zij kamt haar lange haren.","exDe":"Sie kämmt ihre langen Haare."}],"usage":"Regelmäßiges Verb; „zijn/haar haar kammen“ (sich die Haare kämmen).","conjugation":{"presens":{"ik":"kam","jij":"kamt","hij":"kamt","wij":"kammen"},"imperfectum":{"ik":"kamde","wij":"kamden"},"perfectum":{"aux":"hebben","participle":"gekamd"}},"illustratable":true},"bk_672":{"lemma":"baard","displayNl":"de baard","pos":"substantief","meanings":[{"de":"der Bart","ex":"Mijn vader heeft een grijze baard.","exDe":"Mein Vater hat einen grauen Bart."}],"usage":"„een baard hebben/laten staan“ (einen Bart haben/wachsen lassen).","genus":"de","plural":"baarden","illustratable":true},"bk_673":{"lemma":"wachtkamer","displayNl":"de wachtkamer","pos":"substantief","meanings":[{"de":"das Wartezimmer","ex":"Ik zit in de wachtkamer bij de dokter.","exDe":"Ich sitze im Wartezimmer beim Arzt."}],"usage":"Ort beim Arzt/Zahnarzt/Amt; „in de wachtkamer zitten/wachten“.","genus":"de","plural":"wachtkamers","illustratable":true},"bk_674":{"lemma":"peper","displayNl":"de peper","pos":"substantief","meanings":[{"de":"der Pfeffer (Gewürz)","ex":"Ik doe peper op het vlees.","exDe":"Ich mache Pfeffer auf das Fleisch."},{"de":"die Peperoni, scharfe Schote","ex":"Deze rode peper is heel heet.","exDe":"Diese rote Peperoni ist sehr scharf."}],"usage":"Als Gewürz meist ohne Plural; „peper en zout“ (Pfeffer und Salz). Als Schote zählbar.","genus":"de","plural":"pepers","illustratable":true},"bk_675":{"lemma":"druif","displayNl":"de druif","pos":"substantief","meanings":[{"de":"die Weintraube","ex":"Deze druiven zijn zoet.","exDe":"Diese Trauben sind süß."}],"usage":"Meist im Plural „druiven“ (Weintrauben); „een tros druiven“ (eine Traube/ein Bund).","genus":"de","plural":"druiven","illustratable":true},"bk_676":{"lemma":"aardbei","displayNl":"de aardbei","pos":"substantief","meanings":[{"de":"die Erdbeere","ex":"In de zomer eten wij aardbeien.","exDe":"Im Sommer essen wir Erdbeeren."}],"usage":"„een mandje aardbeien“ (ein Körbchen Erdbeeren); saisonal im Sommer.","genus":"de","plural":"aardbeien","illustratable":true},"bk_677":{"lemma":"citroen","displayNl":"de citroen","pos":"substantief","meanings":[{"de":"die Zitrone","ex":"De citroen is zuur.","exDe":"Die Zitrone ist sauer."}],"usage":"„een schijfje citroen“ (eine Zitronenscheibe); Frucht und Saft.","genus":"de","plural":"citroenen","illustratable":true},"bk_678":{"lemma":"peer","displayNl":"de peer","pos":"substantief","meanings":[{"de":"die Birne (Obst)","ex":"Ik snijd een sappige peer.","exDe":"Ich schneide eine saftige Birne."},{"de":"die (Glüh-)Birne, die Lampe (umgangssprachlich)","ex":"De peer in de lamp is kapot.","exDe":"Die Birne in der Lampe ist kaputt."}],"usage":"Alltagswort für das Obst; 'peer' für Glühbirne ist umgangssprachlich (formeller: gloeilamp).","genus":"de","plural":"peren","illustratable":true},"bk_679":{"lemma":"wortel","displayNl":"de wortel","pos":"substantief","meanings":[{"de":"die Karotte, die Möhre","ex":"Het konijn eet een oranje wortel.","exDe":"Das Kaninchen isst eine orange Karotte."},{"de":"die Wurzel (von Pflanze, Zahn u.a.)","ex":"De wortels van de boom zijn diep.","exDe":"Die Wurzeln des Baumes sind tief."},{"de":"die Wurzel (Mathematik)","ex":"De wortel van negen is drie.","exDe":"Die Wurzel aus neun ist drei."}],"usage":"Plural auch 'wortelen'. Für Karotte auch 'peen'/'winterpeen' gebräuchlich; 'wortel' deckt Gemüse und Wurzel ab.","genus":"de","plural":"wortels","illustratable":true},"bk_680":{"lemma":"ui","displayNl":"de ui","pos":"substantief","meanings":[{"de":"die Zwiebel","ex":"Ik snijd een ui en moet huilen.","exDe":"Ich schneide eine Zwiebel und muss weinen."}],"usage":"Alltagswort. Plural 'uien'; Verkleinerung 'uitje' (auch Perlzwiebel).","genus":"de","plural":"uien","illustratable":true},"bk_681":{"lemma":"paprika","displayNl":"de paprika","pos":"substantief","meanings":[{"de":"die Paprika, die Paprikaschote (Gemüse)","ex":"De rode paprika is zoet.","exDe":"Die rote Paprika ist süß."},{"de":"das Paprikapulver, das Gewürz","ex":"Doe wat paprika op de kip.","exDe":"Gib etwas Paprika auf das Hähnchen."}],"usage":"Plural 'paprika's'. Bedeutet sowohl die Schote als auch das Gewürzpulver.","genus":"de","plural":"paprika's","illustratable":true},"bk_682":{"lemma":"komkommer","displayNl":"de komkommer","pos":"substantief","meanings":[{"de":"die Gurke, die Salatgurke","ex":"De komkommer is lang en groen.","exDe":"Die Gurke ist lang und grün."}],"usage":"Alltagswort. 'komkommertijd' = Sauregurkenzeit (nachrichtenarme Zeit).","genus":"de","plural":"komkommers","illustratable":true},"bk_683":{"lemma":"sla","displayNl":"de sla","pos":"substantief","meanings":[{"de":"der Salat (Blattgemüse, Kopfsalat)","ex":"Ik was de sla onder de kraan.","exDe":"Ich wasche den Salat unter dem Wasserhahn."},{"de":"der Salat (grünes Salatgericht)","ex":"Bij het vlees eten we groene sla.","exDe":"Zum Fleisch essen wir grünen Salat."}],"usage":"Meist unzählbar (kein gebräuchlicher Plural). Bezeichnet das Blattgemüse; 'kropsla' = Kopfsalat.","genus":"de","illustratable":true},"bk_684":{"lemma":"salade","displayNl":"de salade","pos":"substantief","meanings":[{"de":"der Salat (zubereitetes Gericht)","ex":"Wij eten een frisse salade met tomaat.","exDe":"Wir essen einen frischen Salat mit Tomate."}],"usage":"Bezeichnet das angerichtete Gericht (mit mehreren Zutaten), nicht das rohe Blattgemüse ('sla').","genus":"de","plural":"salades","illustratable":true},"bk_685":{"lemma":"maaltijd","displayNl":"de maaltijd","pos":"substantief","meanings":[{"de":"die Mahlzeit, das Essen","ex":"Dit is een gezonde maaltijd.","exDe":"Das ist eine gesunde Mahlzeit."}],"usage":"Oberbegriff für ein Essen (Frühstück, Mittag, Abendessen). Plural 'maaltijden'.","genus":"de","plural":"maaltijden","illustratable":true},"bk_686":{"lemma":"diner","displayNl":"het diner","pos":"substantief","meanings":[{"de":"das Abendessen; das Diner (festliche Hauptmahlzeit am Abend)","ex":"Het diner begint om zeven uur.","exDe":"Das Abendessen beginnt um sieben Uhr."},{"de":"das Festessen, das mehrgängige Menü","ex":"Wij organiseren een diner voor twintig gasten.","exDe":"Wir organisieren ein Diner für zwanzig Gäste."}],"usage":"Formeller/festlicher als 'avondeten'. Betonung auf der letzten Silbe (Lehnwort aus dem Französischen).","genus":"het","plural":"diners","illustratable":true},"bk_687":{"lemma":"snack","displayNl":"de snack","pos":"substantief","meanings":[{"de":"der Snack, der Imbiss, die Kleinigkeit zum Essen","ex":"Ik neem een kleine snack.","exDe":"Ich nehme einen kleinen Snack."},{"de":"der frittierte Imbiss (typisch niederländisch, z. B. Kroket, Frikandel aus dem Automaten)","ex":"Bij de snackbar bestel ik een warme snack.","exDe":"An der Imbissbude bestelle ich einen warmen Snack."}],"usage":"Englisches Lehnwort; im NL oft speziell für frittierte Imbisse (snackbar).","genus":"de","plural":"snacks","illustratable":true},"bk_688":{"lemma":"toetje","displayNl":"het toetje","pos":"substantief","meanings":[{"de":"der Nachtisch, das Dessert","ex":"Als toetje eten wij ijs.","exDe":"Als Nachtisch essen wir Eis."}],"usage":"Umgangssprachliche Verkleinerungsform; formeller: 'het dessert', 'het nagerecht'.","genus":"het","plural":"toetjes","illustratable":true},"bk_689":{"lemma":"koekje","displayNl":"het koekje","pos":"substantief","meanings":[{"de":"der Keks, das Plätzchen","ex":"Neem een koekje bij de koffie.","exDe":"Nimm einen Keks zum Kaffee."}],"usage":"Verkleinerungsform von 'koek'. In den Niederlanden traditionell ein Keks zum Kaffee.","genus":"het","plural":"koekjes","illustratable":true},"bk_690":{"lemma":"cake","displayNl":"de cake","pos":"substantief","meanings":[{"de":"der Kuchen (Rührkuchen, Kastenkuchen)","ex":"Zij bakt een cake.","exDe":"Sie backt einen Kuchen."}],"usage":"Englisches Lehnwort, bezeichnet im NL meist einen Rührkuchen/Kastenkuchen; die festliche Torte heißt 'taart'.","genus":"de","plural":"cakes","illustratable":true},"bk_691":{"lemma":"snoep","displayNl":"het snoep","pos":"substantief","meanings":[{"de":"die Süßigkeiten, die Naschereien (Sammelbegriff)","ex":"Kinderen houden van snoep.","exDe":"Kinder mögen Süßigkeiten."}],"usage":"Meist unzählbarer Sammelbegriff (het snoep). Einzelnes Bonbon: 'het snoepje'.","genus":"het","illustratable":true},"bk_692":{"lemma":"jam","displayNl":"de jam","pos":"substantief","meanings":[{"de":"die Marmelade, die Konfitüre","ex":"Ik smeer jam op mijn brood.","exDe":"Ich schmiere Marmelade auf mein Brot."}],"usage":"Ausgesprochen wie im Englischen ('dzjem'). Synonym: 'de confiture'.","genus":"de","plural":"jams","illustratable":true},"bk_693":{"lemma":"patat","displayNl":"de patat","pos":"substantief","meanings":[{"de":"die Pommes frites","ex":"Wij eten patat met mayonaise.","exDe":"Wir essen Pommes mit Mayonnaise."}],"usage":"Im Süden/Süd-NL 'patat', im Norden/Westen oft 'friet'/'frieten'. Meist unzählbar. 'patat met' = Pommes mit Mayonnaise.","genus":"de","illustratable":true},"bk_694":{"lemma":"hamburger","displayNl":"de hamburger","pos":"substantief","meanings":[{"de":"der Hamburger (Burger)","ex":"Hij eet een grote hamburger met kaas.","exDe":"Er isst einen großen Hamburger mit Käse."},{"de":"Einwohner von Hamburg (Hamburger)","ex":"Mijn buurman is een Hamburger.","exDe":"Mein Nachbar ist ein Hamburger."}],"usage":"Meist das Gericht; kann auch einen Einwohner Hamburgs bezeichnen.","genus":"de","plural":"hamburgers","illustratable":true},"bk_695":{"lemma":"saus","displayNl":"de saus","pos":"substantief","meanings":[{"de":"die Soße, die Sauce","ex":"De saus bij de pasta is heerlijk.","exDe":"Die Soße zur Pasta ist köstlich."}],"usage":"Allgemein für flüssige oder cremige Beilagen zu Speisen.","genus":"de","plural":"sauzen","illustratable":true},"bk_696":{"lemma":"ketchup","displayNl":"de ketchup","pos":"substantief","meanings":[{"de":"der Ketchup","ex":"Het kind doet ketchup op alles.","exDe":"Das Kind macht Ketchup auf alles."}],"usage":"Meist unzählbar; im Alltag als de ketchup verwendet.","genus":"de","illustratable":true},"bk_697":{"lemma":"olie","displayNl":"de olie","pos":"substantief","meanings":[{"de":"das Öl (Speiseöl)","ex":"Ik bak de groenten met een beetje olie.","exDe":"Ich brate das Gemüse mit ein bisschen Öl."},{"de":"das Öl (Erdöl, technisches Öl)","ex":"De prijs van olie stijgt.","exDe":"Der Ölpreis steigt."}],"usage":"Sowohl Speise- als auch Erd-/Schmieröl; Kontext entscheidet.","genus":"de","plural":"oliën","illustratable":true},"bk_698":{"lemma":"yoghurt","displayNl":"de yoghurt","pos":"substantief","meanings":[{"de":"der Joghurt","ex":"Ik eet yoghurt met vers fruit en muesli.","exDe":"Ich esse Joghurt mit frischem Obst und Müsli."}],"usage":"Meist unzählbar; als de yoghurt verwendet.","genus":"de","illustratable":true},"bk_699":{"lemma":"ham","displayNl":"de ham","pos":"substantief","meanings":[{"de":"der Schinken","ex":"Op mijn broodje zit een plakje ham.","exDe":"Auf meinem Brötchen liegt eine Scheibe Schinken."}],"usage":"Für gekochten oder rohen Schinken als Aufschnitt.","genus":"de","plural":"hammen","illustratable":true},"bk_700":{"lemma":"worst","displayNl":"de worst","pos":"substantief","meanings":[{"de":"die Wurst","ex":"Wij grillen worst op de barbecue.","exDe":"Wir grillen Wurst auf dem Grill."}],"usage":"Sowohl Bratwurst als auch Aufschnitt- und Rohwurst.","genus":"de","plural":"worsten","illustratable":true},"bk_701":{"lemma":"limonade","displayNl":"de limonade","pos":"substantief","meanings":[{"de":"die Limonade, das Erfrischungsgetränk (auch Fruchtsaftgetränk)","ex":"De kinderen drinken koude limonade in de tuin.","exDe":"Die Kinder trinken kalte Limonade im Garten."}],"usage":"Im Niederländischen oft süßes Fruchtsaftgetränk oder Sirupgetränk, nicht nur Zitronenlimonade.","genus":"de","plural":"limonades","illustratable":true},"bk_702":{"lemma":"kop","displayNl":"de kop","pos":"substantief","meanings":[{"de":"Tasse","ex":"Een kop thee is fijn na een lange dag.","exDe":"Eine Tasse Tee ist schön nach einem langen Tag."},{"de":"Kopf (bei Tieren; salopp beim Menschen)","ex":"De hond legde zijn kop op mijn schoot.","exDe":"Der Hund legte seinen Kopf auf meinen Schoß."},{"de":"Schlagzeile, Überschrift","ex":"De kop van de krant was groot en vet.","exDe":"Die Schlagzeile der Zeitung war groß und fett."},{"de":"Vorderseite (einer Münze), Kopf","ex":"Kop of munt?","exDe":"Kopf oder Zahl?"}],"usage":"Alltäglich für die Tasse (\"een kop koffie\"). Für den Menschenkopf ist \"hoofd\" neutral; \"kop\" ist umgangssprachlich/derb.","genus":"de","plural":"koppen","illustratable":true},"bk_703":{"lemma":"pan","displayNl":"de pan","pos":"substantief","meanings":[{"de":"Topf, Pfanne (Kochgeschirr)","ex":"De pan staat op het fornuis te koken.","exDe":"Der Topf steht auf dem Herd und kocht."},{"de":"Dachziegel (\"dakpan\")","ex":"Er waaide een pan van het dak.","exDe":"Ein Dachziegel wehte vom Dach."}],"usage":"\"Pan\" deckt im Niederländischen sowohl Topf als auch Pfanne ab; präziser: \"steelpan\" (Stielkasserolle), \"koekenpan\" (Bratpfanne).","genus":"de","plural":"pannen","illustratable":true},"bk_704":{"lemma":"oven","displayNl":"de oven","pos":"substantief","meanings":[{"de":"Ofen, Backofen","ex":"De taart staat in de oven te bakken.","exDe":"Die Torte backt im Ofen."}],"usage":"Meist der Backofen; ein Brennofen (Keramik) heißt ebenfalls \"oven\".","genus":"de","plural":"ovens","illustratable":true},"bk_705":{"lemma":"koelkast","displayNl":"de koelkast","pos":"substantief","meanings":[{"de":"Kühlschrank","ex":"De melk staat in de koelkast.","exDe":"Die Milch ist im Kühlschrank."}],"usage":"Standardwort; die Gefriertruhe/das Gefrierfach heißt \"vriezer\" bzw. \"vriesvak\".","genus":"de","plural":"koelkasten","illustratable":true},"bk_706":{"lemma":"ober","displayNl":"de ober","pos":"substantief","meanings":[{"de":"Kellner, Ober","ex":"De ober brengt het menu naar onze tafel.","exDe":"Der Kellner bringt die Speisekarte an unseren Tisch."}],"usage":"\"Ober\" ist etwas traditionell; heute oft geschlechtsneutral \"bediening\" oder \"serveerster/serveerder\".","genus":"de","plural":"obers","illustratable":true},"bk_707":{"lemma":"menu","displayNl":"het menu","pos":"substantief","meanings":[{"de":"Speisekarte","ex":"Ik lees het menu voordat ik bestel.","exDe":"Ich lese die Speisekarte, bevor ich bestelle."},{"de":"Menü, festes Gericht (mehrere Gänge)","ex":"Vanavond nemen we het driegangenmenu.","exDe":"Heute Abend nehmen wir das Drei-Gänge-Menü."},{"de":"Menü (am Computer/Bildschirm)","ex":"Klik op het menu bovenaan het scherm.","exDe":"Klick auf das Menü oben am Bildschirm."}],"usage":"Genus het; Plural mit Apostroph-s: \"menu's\". Die reine Getränkeliste ist eher \"de kaart\".","genus":"het","plural":"menu's","illustratable":true},"bk_708":{"lemma":"kaart","displayNl":"de kaart","pos":"substantief","meanings":[{"de":"Karte (Speise-/Getränkekarte)","ex":"Wat staat er op de kaart?","exDe":"Was steht auf der Karte?"},{"de":"Landkarte, Stadtplan","ex":"Op de kaart zie je alle grachten van de stad.","exDe":"Auf der Karte sieht man alle Grachten der Stadt."},{"de":"Spielkarte","ex":"Hij trok een kaart uit het spel.","exDe":"Er zog eine Karte aus dem Spiel."},{"de":"Eintrittskarte, Ticket","ex":"Ik heb twee kaarten voor het concert.","exDe":"Ich habe zwei Karten für das Konzert."},{"de":"(Post-, Chip-, Gruß-)Karte","ex":"Ik betaal met mijn kaart.","exDe":"Ich bezahle mit meiner Karte."}],"usage":"Stark polysem; Kontext klärt die Bedeutung. Die Postkarte heißt genauer \"ansichtkaart\", die Bankkarte \"pinpas/betaalkaart\".","genus":"de","plural":"kaarten","illustratable":true},"bk_710":{"lemma":"honger hebben","displayNl":"honger hebben","pos":"uitdrukking","meanings":[{"de":"Hunger haben, hungrig sein","ex":"De kinderen hebben altijd honger na school.","exDe":"Die Kinder haben nach der Schule immer Hunger."},{"de":"(übertragen) Verlangen/großes Bedürfnis nach etwas haben","ex":"Zij heeft honger naar succes.","exDe":"Sie hat Hunger nach Erfolg."}],"usage":"Feste Wendung mit \"hebben\": \"ik heb honger\" (nicht \"ik ben honger\"). Grundwort ist das Substantiv \"de honger\". Die Roh-Wortstellung (\"De kinderen honger hebben altijd\") ist falsch; korrekt: \"De kinderen hebben altijd honger.\""},"bk_711":{"lemma":"bakken","displayNl":"bakken","pos":"werkwoord","meanings":[{"de":"backen (im Ofen)","ex":"Wij bakken samen brood.","exDe":"Wir backen zusammen Brot."},{"de":"braten / in der Pfanne backen","ex":"Ik bak een ei in de pan.","exDe":"Ich brate ein Ei in der Pfanne."}],"usage":"Alltagsverb der Küche; 'brood/koekjes bakken' (backen) vs. 'een ei bakken' (braten).","conjugation":{"presens":{"ik":"bak","jij":"bakt","hij":"bakt","wij":"bakken"},"imperfectum":{"ik":"bakte","wij":"bakten"},"perfectum":{"aux":"hebben","participle":"gebakken"}},"illustratable":true},"bk_712":{"lemma":"snijden","displayNl":"snijden","pos":"werkwoord","meanings":[{"de":"schneiden (in Stücke)","ex":"Snijd de ui in stukjes.","exDe":"Schneide die Zwiebel in Stücke."},{"de":"sich schneiden (verletzen)","ex":"Pas op, snijd je niet in je vinger.","exDe":"Pass auf, schneide dich nicht in den Finger."}],"usage":"Starkes Verb: snijden – sneed – gesneden. Reflexiv 'zich snijden' = sich schneiden/verletzen.","conjugation":{"presens":{"ik":"snijd","jij":"snijdt","hij":"snijdt","wij":"snijden"},"imperfectum":{"ik":"sneed","wij":"sneden"},"perfectum":{"aux":"hebben","participle":"gesneden"}},"illustratable":true},"bk_713":{"lemma":"proeven","displayNl":"proeven","pos":"werkwoord","meanings":[{"de":"probieren / kosten (aktiv schmecken)","ex":"Wil je de soep proeven?","exDe":"Möchtest du die Suppe probieren?"},{"de":"herausschmecken / wahrnehmen","ex":"Ik proef knoflook in dit gerecht.","exDe":"Ich schmecke Knoblauch in diesem Gericht heraus."}],"usage":"Aktives Kosten/Probieren (Subjekt = Person). Unterschied zu 'smaken' (Speise schmeckt von selbst).","conjugation":{"presens":{"ik":"proef","jij":"proeft","hij":"proeft","wij":"proeven"},"imperfectum":{"ik":"proefde","wij":"proefden"},"perfectum":{"aux":"hebben","participle":"geproefd"}},"illustratable":true},"bk_714":{"lemma":"bestellen","displayNl":"bestellen","pos":"werkwoord","meanings":[{"de":"bestellen (Essen/Ware)","ex":"Wij bestellen een pizza.","exDe":"Wir bestellen eine Pizza."},{"de":"bestellen / ordern (online oder telefonisch)","ex":"Ik heb de boeken online besteld.","exDe":"Ich habe die Bücher online bestellt."}],"usage":"Regelmäßig, kein 'ge-' im Partizip (untrennbare Vorsilbe be-). Restaurant, Café, Onlinehandel.","conjugation":{"presens":{"ik":"bestel","jij":"bestelt","hij":"bestelt","wij":"bestellen"},"imperfectum":{"ik":"bestelde","wij":"bestelden"},"perfectum":{"aux":"hebben","participle":"besteld"}},"illustratable":true},"bk_715":{"lemma":"smaken","displayNl":"smaken","pos":"werkwoord","meanings":[{"de":"schmecken (einen Geschmack haben)","ex":"Het eten smaakt goed.","exDe":"Das Essen schmeckt gut."},{"de":"munden / gut schmecken (absolut)","ex":"Smakelijk eten! Laat het je smaken.","exDe":"Guten Appetit! Lass es dir schmecken."}],"usage":"Subjekt = die Speise, nicht die Person ('het eten smaakt'). Nicht mit 'proeven' (aktiv kosten) verwechseln.","conjugation":{"presens":{"ik":"smaak","jij":"smaakt","hij":"smaakt","wij":"smaken"},"imperfectum":{"ik":"smaakte","wij":"smaakten"},"perfectum":{"aux":"hebben","participle":"gesmaakt"}}},"bk_716":{"lemma":"dekken","displayNl":"dekken","pos":"werkwoord","meanings":[{"de":"decken (den Tisch)","ex":"Kun je de tafel dekken?","exDe":"Kannst du den Tisch decken?"},{"de":"(ab)decken / bedecken","ex":"Zij dekt de pan met een deksel.","exDe":"Sie deckt die Pfanne mit einem Deckel ab."},{"de":"decken (Kosten/Versicherung)","ex":"De verzekering dekt de schade.","exDe":"Die Versicherung deckt den Schaden."}],"usage":"Häufigste Wendung 'de tafel dekken' = den Tisch decken. Auch übertragen (Kosten, Risiko).","conjugation":{"presens":{"ik":"dek","jij":"dekt","hij":"dekt","wij":"dekken"},"imperfectum":{"ik":"dekte","wij":"dekten"},"perfectum":{"aux":"hebben","participle":"gedekt"}},"illustratable":true},"bk_717":{"lemma":"afwassen","displayNl":"afwassen","pos":"werkwoord","meanings":[{"de":"abwaschen / Geschirr spülen","ex":"Na het eten wassen wij af.","exDe":"Nach dem Essen waschen wir ab."}],"usage":"Trennbares Verb (af | wassen): 'ik was af', Partizip 'afgewassen'. Geschirr von Hand spülen.","conjugation":{"presens":{"ik":"was af","jij":"wast af","hij":"wast af","wij":"wassen af"},"imperfectum":{"ik":"waste af","wij":"wasten af"},"perfectum":{"aux":"hebben","participle":"afgewassen"}},"illustratable":true},"bk_718":{"lemma":"zuur","displayNl":"zuur","pos":"adjectief","meanings":[{"de":"sauer (Geschmack)","ex":"De citroen is zuur.","exDe":"Die Zitrone ist sauer."},{"de":"sauer / verärgert (umgangssprachlich)","ex":"Hij is zuur omdat hij verloren heeft.","exDe":"Er ist sauer, weil er verloren hat."},{"de":"mühsam / unangenehm (zure taak)","ex":"Dat was een zure les.","exDe":"Das war eine bittere Lektion."}],"usage":"Adjektiv; flektiert 'de zure appel'. Auch als Substantiv 'het zuur' = Säure/Sodbrennen."},"bk_719":{"lemma":"zout","displayNl":"zout","pos":"adjectief","meanings":[{"de":"salzig","ex":"De soep is te zout.","exDe":"Die Suppe ist zu salzig."},{"de":"Salz (het zout)","ex":"Doe je nog wat zout in de soep?","exDe":"Tust du noch etwas Salz in die Suppe?"}],"usage":"Als bijvoeglijk naamwoord: zout (smaak). Als het-zelfstandig naamwoord betekent 'het zout' die Substanz Salz; dann genus=het.","notes":"Homonymie: Adjektiv 'salzig' und Substantiv 'het zout' (Salz).","illustratable":true},"bk_720":{"lemma":"vies","displayNl":"vies","pos":"adjectief","meanings":[{"de":"eklig, widerlich","ex":"Dit eten is vies.","exDe":"Dieses Essen ist eklig."},{"de":"schmutzig, dreckig","ex":"Je handen zijn vies.","exDe":"Deine Haende sind schmutzig."}],"usage":"Bewertend für Geschmack/Geruch (eklig) oder für Sauberkeit (schmutzig). 'ergens vies van zijn' = sich vor etwas ekeln."},"bk_721":{"lemma":"boon","displayNl":"de boon","pos":"substantief","meanings":[{"de":"die Bohne","ex":"Wij eten groene bonen.","exDe":"Wir essen grüne Bohnen."}],"usage":"Auch 'bruine bonen' (braune Bohnen), 'koffieboon' (Kaffeebohne). Redewendung 'het zal me een boon zijn' = es ist mir egal.","genus":"de","plural":"bonen","illustratable":true},"bk_722":{"lemma":"noot","displayNl":"de noot","pos":"substantief","meanings":[{"de":"die Nuss","ex":"Ik eet graag noten.","exDe":"Ich esse gern Nuesse."},{"de":"die (Musik-)Note","ex":"Zij speelt de juiste noten.","exDe":"Sie spielt die richtigen Noten."},{"de":"die Anmerkung, Fussnote","ex":"Zie de noot onderaan de bladzijde.","exDe":"Siehe die Anmerkung unten auf der Seite."}],"usage":"Homonymie: Nuss (Frucht), Musiknote und Anmerkung/Fussnote (voetnoot). Plural jeweils 'noten'.","genus":"de","plural":"noten","illustratable":true},"bk_723":{"lemma":"pannenkoek","displayNl":"de pannenkoek","pos":"substantief","meanings":[{"de":"der Pfannkuchen (niederländische Art, dünn und groß)","ex":"Op zondag maken wij pannenkoeken.","exDe":"Sonntags machen wir Pfannkuchen."}],"usage":"Niederlaendischer Pannenkoek ist duenn und tellergross, oft mit Sirup (stroop), Speck oder Apfel. Kleine dicke Variante = poffertjes.","genus":"de","plural":"pannenkoeken","illustratable":true},"bk_724":{"lemma":"boterham","displayNl":"de boterham","pos":"substantief","meanings":[{"de":"das Butterbrot, die Scheibe Brot (belegt)","ex":"Ik neem een boterham mee.","exDe":"Ich nehme ein Butterbrot mit."}],"usage":"Eine belegte oder mit Butter bestrichene Brotscheibe; typisch für das niederlaendische Mittagessen. 'boterham met kaas' = Käsebrot.","genus":"de","plural":"boterhammen","illustratable":true},"bk_725":{"lemma":"bakje","displayNl":"het bakje","pos":"substantief","meanings":[{"de":"das Schälchen, die kleine Schale","ex":"Een bakje yoghurt, alsjeblieft.","exDe":"Ein Schaelchen Joghurt, bitte."},{"de":"das Tässchen (bakje koffie = Tasse Kaffee)","ex":"Wil je een bakje koffie?","exDe":"Moechtest du eine Tasse Kaffee?"}],"usage":"Diminutiv von 'de bak'. Sehr gebraeuchlich: 'een bakje koffie' (eine Tasse Kaffee), 'een bakje troost' (umgangssprachlich für Kaffee).","genus":"het","plural":"bakjes","illustratable":true},"bk_726":{"lemma":"kan","displayNl":"de kan","pos":"substantief","meanings":[{"de":"die Kanne, der Krug","ex":"Op tafel staat een kan water.","exDe":"Auf dem Tisch steht eine Kanne Wasser."}],"usage":"Grosses Gefaess mit Henkel und Ausguss für Wasser, Milch oder Saft. Nicht mit dem Verb 'kan' (koennen, ik kan) verwechseln.","genus":"de","plural":"kannen","notes":"Formgleich mit der Verbform 'kan' (von 'kunnen'), aber hier das Substantiv de kan.","illustratable":true},"bk_727":{"lemma":"kom","displayNl":"de kom","pos":"substantief","meanings":[{"de":"Schüssel, Schale","ex":"Ik meng het beslag in een grote kom.","exDe":"Ich mische den Teig in einer großen Schüssel."},{"de":"Napf, Schale (zum Trinken/Essen)","ex":"De kat drinkt melk uit haar kom.","exDe":"Die Katze trinkt Milch aus ihrem Napf."},{"de":"Becken, Mulde (z. B. Ortskern: bebouwde kom)","ex":"Binnen de bebouwde kom mag je maar 30.","exDe":"Innerhalb der geschlossenen Ortschaft darfst du nur 30 fahren."}],"usage":"Alltag/Küche; gebräuchlich für Schüssel/Schale. Redewendung: 'bebouwde kom' = geschlossene Ortschaft.","genus":"de","plural":"kommen","illustratable":true},"bk_728":{"lemma":"vullen","displayNl":"vullen","pos":"werkwoord","meanings":[{"de":"füllen, befüllen","ex":"Vul het glas met water.","exDe":"Fülle das Glas mit Wasser."},{"de":"ausfüllen (Zeit, Raum, Lücke)","ex":"De muziek vulde de hele zaal.","exDe":"Die Musik füllte den ganzen Saal."},{"de":"sich füllen (zich vullen)","ex":"De zaal vulde zich langzaam met mensen.","exDe":"Der Saal füllte sich langsam mit Menschen."}],"usage":"Regelmäßiges Verb; oft mit 'met' (vullen met = füllen mit). Reflexiv 'zich vullen' = sich füllen.","conjugation":{"presens":{"ik":"vul","jij":"vult","hij":"vult","wij":"vullen"},"imperfectum":{"ik":"vulde","wij":"vulden"},"perfectum":{"aux":"hebben","participle":"gevuld"}},"illustratable":true},"bk_729":{"lemma":"plafond","displayNl":"het plafond","pos":"substantief","meanings":[{"de":"Zimmerdecke, Decke (eines Raumes)","ex":"Het plafond is hoog en wit.","exDe":"Die Decke ist hoch und weiß."},{"de":"Höchstgrenze, Obergrenze (übertragen)","ex":"De prijzen bereikten hun plafond.","exDe":"Die Preise erreichten ihre Obergrenze."}],"usage":"Aus dem Französischen; Zimmerdecke. Bildlich auch 'Obergrenze/Höchstwert'.","genus":"het","plural":"plafonds","illustratable":true},"bk_730":{"lemma":"dak","displayNl":"het dak","pos":"substantief","meanings":[{"de":"Dach","ex":"Het dak van het huis is rood.","exDe":"Das Dach des Hauses ist rot."},{"de":"Obdach, schützendes Dach (übertragen)","ex":"Iedereen verdient een dak boven zijn hoofd.","exDe":"Jeder verdient ein Dach über dem Kopf."}],"usage":"Konkretes Bauteil; bildlich 'een dak boven je hoofd' = ein Dach über dem Kopf.","genus":"het","plural":"daken","illustratable":true},"bk_731":{"lemma":"gang","displayNl":"de gang","pos":"substantief","meanings":[{"de":"Flur, Korridor, Gang","ex":"De gang is smal en donker.","exDe":"Der Flur ist schmal und dunkel."},{"de":"Gang (eines Menüs)","ex":"Het diner had vijf gangen.","exDe":"Das Abendessen hatte fünf Gänge."},{"de":"Gang, Ablauf, Verlauf (aan de gang = im Gange)","ex":"De vergadering is al aan de gang.","exDe":"Die Besprechung ist schon im Gange."}],"usage":"Mehrdeutig: Flur, Menügang, Verlauf. Feste Wendung 'aan de gang' = im Gange.","genus":"de","plural":"gangen","illustratable":true},"bk_732":{"lemma":"zolder","displayNl":"de zolder","pos":"substantief","meanings":[{"de":"Dachboden, Speicher","ex":"De oude koffers staan op zolder.","exDe":"Die alten Koffer stehen auf dem Dachboden."},{"de":"Dachgeschoss, Mansarde (als Zimmer)","ex":"Onze zoon slaapt op een kamer op zolder.","exDe":"Unser Sohn schläft in einem Zimmer im Dachgeschoss."}],"usage":"Oft ortsartig ohne Artikel: 'op zolder' = auf dem Dachboden.","genus":"de","plural":"zolders","illustratable":true},"bk_733":{"lemma":"kelder","displayNl":"de kelder","pos":"substantief","meanings":[{"de":"Keller","ex":"De wijn ligt koel in de kelder.","exDe":"Der Wein liegt kühl im Keller."},{"de":"Tiefpunkt, Absturz (übertragen: in de kelder)","ex":"De verkoopcijfers zijn in de kelder beland.","exDe":"Die Verkaufszahlen sind in den Keller gerutscht."}],"usage":"Konkret der Keller; bildlich 'in de kelder' = im Keller / abgestürzt (Werte).","genus":"de","plural":"kelders","illustratable":true},"bk_734":{"lemma":"garage","displayNl":"de garage","pos":"substantief","meanings":[{"de":"Garage (für das Auto)","ex":"De auto staat in de garage.","exDe":"Das Auto steht in der Garage."},{"de":"Autowerkstatt, Kfz-Werkstatt","ex":"Ik breng mijn auto naar de garage voor een reparatie.","exDe":"Ich bringe mein Auto zur Reparatur in die Werkstatt."}],"usage":"Zwei Bedeutungen: Garage (Parken) und Kfz-Werkstatt. Französisches Lehnwort.","genus":"de","plural":"garages","illustratable":true},"bk_735":{"lemma":"balkon","displayNl":"het balkon","pos":"substantief","meanings":[{"de":"der Balkon","ex":"We eten 's zomers vaak op het balkon.","exDe":"Im Sommer essen wir oft auf dem Balkon."},{"de":"der Rang, das Obergeschoss (im Theater/Kino)","ex":"Onze plaatsen zijn op het balkon.","exDe":"Unsere Plätze sind auf dem Rang."}],"usage":"Alltagswort für den Balkon einer Wohnung; im Theater auch der obere Rang.","genus":"het","plural":"balkons","illustratable":true},"bk_736":{"lemma":"appartement","displayNl":"het appartement","pos":"substantief","meanings":[{"de":"das Apartment, die Wohnung","ex":"Ze wonen in een klein appartement in de stad.","exDe":"Sie wohnen in einer kleinen Wohnung in der Stadt."}],"usage":"Bezeichnet eine (oft moderne) Etagenwohnung; gebräuchlich neben 'flat' und 'woning'.","genus":"het","plural":"appartementen","illustratable":true},"bk_737":{"lemma":"buur","displayNl":"de buur","pos":"substantief","meanings":[{"de":"der Nachbar, die Nachbarin","ex":"Mijn buur helpt me altijd met de tuin.","exDe":"Mein Nachbar hilft mir immer mit dem Garten."},{"de":"die Nachbarn (Plural 'buren')","ex":"We hebben aardige buren.","exDe":"Wir haben nette Nachbarn."}],"usage":"'Buur' ist die neutrale Grundform; im Alltag meist 'buurman'/'buurvrouw', Plural fast immer 'buren'.","genus":"de","plural":"buren","illustratable":true},"bk_738":{"lemma":"tapijt","displayNl":"het tapijt","pos":"substantief","meanings":[{"de":"der Teppich","ex":"In de woonkamer ligt een dik, zacht tapijt.","exDe":"Im Wohnzimmer liegt ein dicker, weicher Teppich."},{"de":"der Wandteppich, die Tapisserie","ex":"Aan de muur hangt een oud tapijt met een jachttafereel.","exDe":"An der Wand hängt ein alter Wandteppich mit einer Jagdszene."}],"usage":"Meist der Bodenteppich; kann auch einen kunstvollen Wandteppich bezeichnen.","genus":"het","plural":"tapijten","illustratable":true},"bk_739":{"lemma":"gordijn","displayNl":"het gordijn","pos":"substantief","meanings":[{"de":"der Vorhang, die Gardine","ex":"Doe 's avonds de gordijnen dicht.","exDe":"Mach abends die Vorhänge zu."}],"usage":"Oft im Plural 'gordijnen' verwendet; bezeichnet Stoffvorhänge am Fenster.","genus":"het","plural":"gordijnen","illustratable":true},"bk_740":{"lemma":"kussen","displayNl":"het kussen","pos":"substantief","meanings":[{"de":"das Kissen, das Kopfkissen","ex":"Ik leg mijn hoofd op een zacht kussen.","exDe":"Ich lege meinen Kopf auf ein weiches Kissen."},{"de":"das Sofakissen, das Polster","ex":"Op de bank liggen kleurige kussens.","exDe":"Auf dem Sofa liegen bunte Kissen."}],"usage":"Substantiv 'het kussen' = Kissen/Polster; formgleich mit dem Verb 'kussen' (küssen), das hier aber nicht gemeint ist.","genus":"het","plural":"kussens","illustratable":true},"bk_741":{"lemma":"deken","displayNl":"de deken","pos":"substantief","meanings":[{"de":"die Decke, die Bettdecke, die Wolldecke","ex":"Trek de deken over je heen, het is koud.","exDe":"Zieh die Decke über dich, es ist kalt."},{"de":"der Dechant, der Dekan (kirchlich)","ex":"De deken van de kerk hield een korte toespraak.","exDe":"Der Dechant der Kirche hielt eine kurze Ansprache."}],"usage":"Im Alltag fast immer die Wolldecke/Bettdecke ('de deken'); die kirchliche Bedeutung ist selten.","genus":"de","plural":"dekens","illustratable":true},"bk_742":{"lemma":"plank","displayNl":"de plank","pos":"substantief","meanings":[{"de":"das Regal, das Wandbrett","ex":"De boeken staan netjes op de plank.","exDe":"Die Bücher stehen ordentlich im Regal."},{"de":"das Brett, die Planke, das Holzbrett","ex":"Hij zaagt een plank op maat.","exDe":"Er sägt ein Brett auf Maß."}],"usage":"'Plank' meint sowohl das Wandbrett/Regalbrett als auch ein einzelnes Holzbrett; Plural 'planken'.","genus":"de","plural":"planken","illustratable":true},"bk_743":{"lemma":"boekenkast","displayNl":"de boekenkast","pos":"substantief","meanings":[{"de":"das Bücherregal, der Bücherschrank","ex":"De boekenkast is helemaal vol met romans.","exDe":"Das Bücherregal ist ganz voll mit Romanen."}],"usage":"Alltäglich für ein Möbelstück zum Aufbewahren von Büchern; zusammengesetzt aus 'boeken' (Bücher) + 'kast' (Schrank).","genus":"de","plural":"boekenkasten","illustratable":true},"bk_744":{"lemma":"bureau","displayNl":"het bureau","pos":"substantief","meanings":[{"de":"der Schreibtisch","ex":"Ik werk elke dag aan mijn bureau.","exDe":"Ich arbeite jeden Tag an meinem Schreibtisch."},{"de":"das Büro, die Amtsstelle / Agentur","ex":"Je moet dit formulier bij het bureau afgeven.","exDe":"Du musst dieses Formular beim Büro abgeben."},{"de":"die (Polizei-)Wache","ex":"De agent nam hem mee naar het bureau.","exDe":"Der Polizist nahm ihn mit auf die Wache."}],"usage":"Häufiges Wort mit mehreren Bedeutungen: primär der Schreibtisch, außerdem eine Amts-/Agenturstelle und umgangssprachlich die Polizeiwache.","genus":"het","plural":"bureaus","illustratable":true},"bk_745":{"lemma":"vaas","displayNl":"de vaas","pos":"substantief","meanings":[{"de":"die Vase","ex":"De verse bloemen staan in een blauwe vaas.","exDe":"Die frischen Blumen stehen in einer blauen Vase."}],"usage":"Gefäß für Schnittblumen; Plural mit z: 'vazen'.","genus":"de","plural":"vazen","illustratable":true},"bk_746":{"lemma":"vriezer","displayNl":"de vriezer","pos":"substantief","meanings":[{"de":"der Gefrierschrank, die Tiefkühltruhe","ex":"Het ijs ligt al een week in de vriezer.","exDe":"Das Eis liegt schon eine Woche im Gefrierschrank."}],"usage":"Küchengerät zum Einfrieren von Lebensmitteln; auch 'diepvries' genannt.","genus":"de","plural":"vriezers","illustratable":true},"bk_747":{"lemma":"magnetron","displayNl":"de magnetron","pos":"substantief","meanings":[{"de":"die Mikrowelle, der Mikrowellenherd","ex":"Ik warm de soep op in de magnetron.","exDe":"Ich wärme die Suppe in der Mikrowelle auf."}],"usage":"Alltägliches Küchengerät zum Erwärmen von Speisen; das niederländische Wort bedeutet wörtlich 'Magnetron' (die erzeugende Röhre).","genus":"de","plural":"magnetrons","illustratable":true},"bk_748":{"lemma":"wasmachine","displayNl":"de wasmachine","pos":"substantief","meanings":[{"de":"die Waschmaschine","ex":"De wasmachine draait op zestig graden.","exDe":"Die Waschmaschine läuft auf sechzig Grad."}],"usage":"Haushaltsgerät zum Waschen von Kleidung; zusammengesetzt aus 'was' (Wäsche) + 'machine'.","genus":"de","plural":"wasmachines","illustratable":true},"bk_749":{"lemma":"vaatwasser","displayNl":"de vaatwasser","pos":"substantief","meanings":[{"de":"die Spülmaschine, der Geschirrspüler","ex":"De vuile borden staan al in de vaatwasser.","exDe":"Die schmutzigen Teller stehen schon in der Spülmaschine."}],"usage":"Haushaltsgerät zum Spülen von Geschirr; zusammengesetzt aus 'vaat' (Geschirr) + 'wasser'. Auch 'afwasmachine'.","genus":"de","plural":"vaatwassers","illustratable":true},"bk_750":{"lemma":"stofzuiger","displayNl":"de stofzuiger","pos":"substantief","meanings":[{"de":"der Staubsauger","ex":"De stofzuiger is kapot en zuigt niet meer.","exDe":"Der Staubsauger ist kaputt und saugt nicht mehr."}],"usage":"Haushaltsgerät zum Saugen von Staub; zusammengesetzt aus 'stof' (Staub) + 'zuiger' (Sauger).","genus":"de","plural":"stofzuigers","illustratable":true},"bk_751":{"lemma":"kraan","displayNl":"de kraan","pos":"substantief","meanings":[{"de":"Wasserhahn","ex":"Draai de kraan dicht, anders loopt het water door.","exDe":"Dreh den Wasserhahn zu, sonst läuft das Wasser weiter."},{"de":"Kran (Hebemaschine)","ex":"De kraan tilt de container op de vrachtwagen.","exDe":"Der Kran hebt den Container auf den Lastwagen."}],"usage":"Alltagswort: meist der Wasserhahn zu Hause; im Bau-/Hafenkontext die Hebemaschine (Kran). Der Vogel Kranich heißt 'kraanvogel'.","genus":"de","plural":"kranen","illustratable":true},"bk_752":{"lemma":"emmer","displayNl":"de emmer","pos":"substantief","meanings":[{"de":"Eimer","ex":"De emmer is vol water.","exDe":"Der Eimer ist voll Wasser."}],"usage":"Neutrales Alltagswort für einen Eimer, z. B. zum Putzen. Redensart 'het regent dat het giet' (nicht mit emmer verwechseln).","genus":"de","plural":"emmers","illustratable":true},"bk_753":{"lemma":"bezem","displayNl":"de bezem","pos":"substantief","meanings":[{"de":"Besen","ex":"Ik veeg de vloer met de bezem.","exDe":"Ich fege den Boden mit dem Besen."}],"usage":"Alltagswort für den Kehrbesen. Redensart 'nieuwe bezems vegen schoon' = neue Besen kehren gut.","genus":"de","plural":"bezems","illustratable":true},"bk_754":{"lemma":"vuilnisbak","displayNl":"de vuilnisbak","pos":"substantief","meanings":[{"de":"Mülleimer, Abfalltonne","ex":"Gooi het lege pak in de vuilnisbak.","exDe":"Wirf die leere Packung in den Mülleimer."}],"usage":"Alltagswort für Abfalleimer/-tonne im Haushalt; Synonyme 'prullenbak' (kleiner Papierkorb) und 'afvalbak'.","genus":"de","plural":"vuilnisbakken","illustratable":true},"bk_755":{"lemma":"afval","displayNl":"het afval","pos":"substantief","meanings":[{"de":"Müll, Abfall","ex":"Ik breng het afval buiten naar de container.","exDe":"Ich bringe den Müll raus zum Container."},{"de":"Abfälle, Reste (z. B. Küchenabfälle)","ex":"Groente-afval gooien we op de composthoop.","exDe":"Gemüseabfälle werfen wir auf den Komposthaufen."}],"usage":"Unzählbares Sammelwort (kein regulärer Plural). 'huishoudelijk afval' = Hausmüll, 'gescheiden afval' = getrennter Müll.","genus":"het","illustratable":true},"bk_756":{"lemma":"bel","displayNl":"de bel","pos":"substantief","meanings":[{"de":"Klingel, Glocke","ex":"De bel gaat, er staat iemand voor de deur.","exDe":"Es klingelt, jemand steht vor der Tür."},{"de":"Blase (z. B. Seifenblase, Luftblase)","ex":"De kinderen blazen bellen in de tuin.","exDe":"Die Kinder machen Seifenblasen im Garten."}],"usage":"Meist die Tür-/Fahrradklingel oder Glocke; im übertragenen Sinn 'een belletje geven' = anrufen. Zweite Bedeutung: (Seifen-)Blase, 'bellen blazen'.","genus":"de","plural":"bellen","illustratable":true},"bk_757":{"lemma":"brievenbus","displayNl":"de brievenbus","pos":"substantief","meanings":[{"de":"Briefkasten (am Haus)","ex":"De post zit in de brievenbus.","exDe":"Die Post ist im Briefkasten."},{"de":"Briefkasten (öffentlich, zum Einwerfen)","ex":"Ik doe de kaart in de brievenbus op de hoek.","exDe":"Ich werfe die Karte in den Briefkasten an der Ecke."}],"usage":"Sowohl der private Briefkastenschlitz an der Haustür als auch der öffentliche Postbriefkasten. Diminutiv 'brievenbusje'.","genus":"de","plural":"brievenbussen","illustratable":true},"bk_758":{"lemma":"verwarming","displayNl":"de verwarming","pos":"substantief","meanings":[{"de":"Heizung (Heizkörper/Anlage)","ex":"Zet de verwarming aan, het is koud.","exDe":"Mach die Heizung an, es ist kalt."},{"de":"Erwärmung (das Erwärmen)","ex":"De verwarming van de aarde is een groot probleem.","exDe":"Die Erwärmung der Erde ist ein großes Problem."}],"usage":"Meist die häusliche Heizung/der Heizkörper ('de verwarming aanzetten'); abstrakter auch das Erwärmen bzw. die Erwärmung (z. B. 'opwarming van de aarde' ist gebräuchlicher fürs Klima).","genus":"de","plural":"verwarmingen","illustratable":true},"bk_759":{"lemma":"meubel","displayNl":"het meubel","pos":"substantief","meanings":[{"de":"das Möbelstück","ex":"Dit meubel is nieuw.","exDe":"Dieses Möbelstück ist neu."},{"de":"das Möbel (meist Plural: die Möbel)","ex":"De meubels zijn nieuw.","exDe":"Die Möbel sind neu."}],"usage":"Meist im Plural 'meubels' gebraucht; Singular 'het meubel' bezeichnet ein einzelnes Möbelstück. Kollektiv auch 'het meubilair'.","genus":"het","plural":"meubels","illustratable":true},"bk_760":{"lemma":"kaars","displayNl":"de kaars","pos":"substantief","meanings":[{"de":"die Kerze","ex":"De kaars brandt.","exDe":"Die Kerze brennt."}],"usage":"Alltagswort; 'een kaars aansteken' = eine Kerze anzuenden.","genus":"de","plural":"kaarsen","illustratable":true},"bk_761":{"lemma":"wekker","displayNl":"de wekker","pos":"substantief","meanings":[{"de":"der Wecker","ex":"De wekker gaat om zeven uur.","exDe":"Der Wecker klingelt um sieben Uhr."}],"usage":"'De wekker gaat' = der Wecker klingelt; 'de wekker zetten' = den Wecker stellen.","genus":"de","plural":"wekkers","illustratable":true},"bk_762":{"lemma":"spons","displayNl":"de spons","pos":"substantief","meanings":[{"de":"der Schwamm (zum Putzen/Waschen)","ex":"De spons is nat.","exDe":"Der Schwamm ist nass."},{"de":"der Schwamm (Meerestier)","ex":"Een spons leeft in de zee.","exDe":"Ein Schwamm lebt im Meer."}],"usage":"Meist der Haushalts- oder Badeschwamm; auch das Meerestier.","genus":"de","plural":"sponzen","illustratable":true},"bk_763":{"lemma":"borstel","displayNl":"de borstel","pos":"substantief","meanings":[{"de":"die Bürste","ex":"Ik boen met een borstel.","exDe":"Ich schrubbe mit einer Bürste."}],"usage":"Allgemein Buerste (Schrubb-, Haar-, Zahn-); 'de borstel' als Werkzeug zum Reinigen.","genus":"de","plural":"borstels","illustratable":true},"bk_764":{"lemma":"eetkamer","displayNl":"de eetkamer","pos":"substantief","meanings":[{"de":"das Esszimmer","ex":"We eten in de eetkamer.","exDe":"Wir essen im Esszimmer."}],"usage":"Zusammensetzung eten + kamer; der Raum zum Essen.","genus":"de","plural":"eetkamers","illustratable":true},"bk_766":{"lemma":"mat","displayNl":"de mat","pos":"substantief","meanings":[{"de":"die Matte, die Fußmatte","ex":"Veeg je voeten op de mat.","exDe":"Wisch deine Füße auf der Matte."},{"de":"die Matte (Sport, Turnen, Yoga)","ex":"Hij legt zijn mat op de vloer van de sportzaal.","exDe":"Er legt seine Matte auf den Boden der Sporthalle."}],"usage":"'de mat' Fußmatte/Unterlage. Zu unterscheiden vom Adjektiv 'mat' (matt, glanzlos) und dem Schach-Ausdruck 'schaakmat'.","genus":"de","plural":"matten","illustratable":true},"bk_767":{"lemma":"verhuizen","displayNl":"verhuizen","pos":"werkwoord","meanings":[{"de":"umziehen (den Wohnort wechseln)","ex":"We gaan volgende week verhuizen.","exDe":"Wir ziehen nächste Woche um."},{"de":"(etwas) an einen anderen Ort bringen, verlagern","ex":"Het bedrijf verhuist zijn kantoor naar Utrecht.","exDe":"Die Firma verlegt ihr Büro nach Utrecht."}],"usage":"Bei Ortswechsel der Person mit 'zijn' (wij zijn verhuisd). Trennbar wirkend nicht - untrennbares Verb mit ver-. Wechsel z->s im Praeteritum/Partizip.","conjugation":{"presens":{"ik":"verhuis","jij":"verhuist","hij":"verhuist","wij":"verhuizen"},"imperfectum":{"ik":"verhuisde","wij":"verhuisden"},"perfectum":{"aux":"zijn","participle":"verhuisd"}},"illustratable":true},"bk_768":{"lemma":"huren","displayNl":"huren","pos":"werkwoord","meanings":[{"de":"mieten","ex":"Ik wil een kamer huren.","exDe":"Ich möchte ein Zimmer mieten."},{"de":"leihen (gegen Bezahlung), ausleihen","ex":"We huren een auto voor het weekend.","exDe":"Wir leihen ein Auto für das Wochenende."}],"usage":"Regelmäßiges Verb. huren = etwas gegen Bezahlung nutzen (Mieter-Seite); Gegenstück 'verhuren' = vermieten.","conjugation":{"presens":{"ik":"huur","jij":"huurt","hij":"huurt","wij":"huren"},"imperfectum":{"ik":"huurde","wij":"huurden"},"perfectum":{"aux":"hebben","participle":"gehuurd"}}},"bk_769":{"lemma":"schoonmaken","displayNl":"schoonmaken","pos":"werkwoord","meanings":[{"de":"putzen, sauber machen, reinigen","ex":"Ik ga de badkamer schoonmaken.","exDe":"Ich putze das Badezimmer."},{"de":"(Gemüse/Fisch) putzen, säubern","ex":"Maak de vis goed schoon voor je hem bakt.","exDe":"Mach den Fisch gut sauber, bevor du ihn brätst."}],"usage":"Trennbares Verb (schoon + maken). Im Hauptsatz trennt sich der Partikel: 'Ik maak de keuken schoon.' Partizip: schoongemaakt.","conjugation":{"presens":{"ik":"maak schoon","jij":"maakt schoon","hij":"maakt schoon","wij":"maken schoon"},"imperfectum":{"ik":"maakte schoon","wij":"maakten schoon"},"perfectum":{"aux":"hebben","participle":"schoongemaakt"}},"illustratable":true},"bk_770":{"lemma":"stofzuigen","displayNl":"stofzuigen","pos":"werkwoord","meanings":[{"de":"staubsaugen","ex":"Ik moet nog stofzuigen.","exDe":"Ich muss noch staubsaugen."}],"usage":"Meist untrennbar gebraucht: 'Ik stofzuig de kamer.' Partizip gestofzuigd. Ältere trennbare Form 'ik zuig stof' ist selten.","conjugation":{"presens":{"ik":"stofzuig","jij":"stofzuigt","hij":"stofzuigt","wij":"stofzuigen"},"imperfectum":{"ik":"stofzuigde","wij":"stofzuigden"},"perfectum":{"aux":"hebben","participle":"gestofzuigd"}},"illustratable":true},"bk_771":{"lemma":"opruimen","displayNl":"opruimen","pos":"werkwoord","meanings":[{"de":"aufräumen, wegräumen","ex":"Ruim je kamer op.","exDe":"Räum dein Zimmer auf."},{"de":"beseitigen, wegschaffen","ex":"De politie heeft de blokkade opgeruimd.","exDe":"Die Polizei hat die Blockade beseitigt."}],"usage":"Trennbares Verb (op + ruimen). Im Hauptsatz: 'Ik ruim mijn spullen op.' Partizip: opgeruimd.","conjugation":{"presens":{"ik":"ruim op","jij":"ruimt op","hij":"ruimt op","wij":"ruimen op"},"imperfectum":{"ik":"ruimde op","wij":"ruimden op"},"perfectum":{"aux":"hebben","participle":"opgeruimd"}},"illustratable":true},"bk_772":{"lemma":"vegen","displayNl":"vegen","pos":"werkwoord","meanings":[{"de":"fegen, kehren","ex":"Ik veeg de vloer.","exDe":"Ich fege den Boden."},{"de":"wischen (mit der Hand/einem Tuch)","ex":"Ze veegt de kruimels van de tafel.","exDe":"Sie wischt die Krümel vom Tisch."}],"usage":"Regelmäßiges Verb. 'de vloer vegen' = den Boden fegen; auch 'iets wegvegen' = etwas wegwischen.","conjugation":{"presens":{"ik":"veeg","jij":"veegt","hij":"veegt","wij":"vegen"},"imperfectum":{"ik":"veegde","wij":"veegden"},"perfectum":{"aux":"hebben","participle":"geveegd"}},"illustratable":true},"bk_773":{"lemma":"modern","displayNl":"modern","pos":"adjectief","meanings":[{"de":"modern, zeitgemäß","ex":"De keuken is modern.","exDe":"Die Küche ist modern."},{"de":"neumodisch, aktuell, in Mode","ex":"Dat is tegenwoordig heel modern.","exDe":"Das ist heutzutage sehr modern."}],"usage":"Adjektiv; flektiert vor de-/het-Wörtern zu 'moderne' (een moderne keuken). Steigerung: moderner, modernst.","conjugation":{"presens":{"ik":"","jij":"","hij":"","wij":""},"imperfectum":{"ik":"","wij":""},"perfectum":{"aux":"hebben","participle":""}}},"bk_774":{"lemma":"vuil","displayNl":"vuil","pos":"adjectief","meanings":[{"de":"schmutzig, dreckig","ex":"De vloer is vuil.","exDe":"Der Boden ist schmutzig."},{"de":"(als Substantiv, het vuil) der Schmutz, der Dreck, der Müll","ex":"Er lag veel vuil op straat.","exDe":"Es lag viel Müll auf der Straße."},{"de":"gemein, hinterhältig (übertragen)","ex":"Dat was een vuile streek.","exDe":"Das war ein gemeiner Streich."}],"usage":"Primär Adjektiv (flektiert: een vuile vloer). Als Substantiv 'het vuil' = Schmutz/Müll. Synonym adjektivisch: smerig.","conjugation":{"presens":{"ik":"","jij":"","hij":"","wij":""},"imperfectum":{"ik":"","wij":""},"perfectum":{"aux":"hebben","participle":""}}},"bk_775":{"lemma":"eettafel","displayNl":"de eettafel","pos":"substantief","meanings":[{"de":"der Esstisch","ex":"De eettafel is groot.","exDe":"Der Esstisch ist groß."}],"usage":"de-Wort, Plural eettafels. Zusammensetzung uit 'eten' + 'tafel'.","genus":"de","plural":"eettafels","conjugation":{"presens":{"ik":"","jij":"","hij":"","wij":""},"imperfectum":{"ik":"","wij":""},"perfectum":{"aux":"hebben","participle":""}},"illustratable":true},"bk_776":{"lemma":"kleerkast","displayNl":"de kleerkast","pos":"substantief","meanings":[{"de":"der Kleiderschrank","ex":"De kleerkast is vol.","exDe":"Der Kleiderschrank ist voll."},{"de":"der Schrank (für Kleidung)","ex":"Ze hangt haar jas in de kleerkast.","exDe":"Sie hängt ihre Jacke in den Kleiderschrank."}],"usage":"Zusammensetzung aus 'kleer-' (Kleidung) + 'kast' (Schrank). Synonym: klerenkast.","genus":"de","plural":"kleerkasten","illustratable":true},"bk_777":{"lemma":"koffer","displayNl":"de koffer","pos":"substantief","meanings":[{"de":"der Koffer (Reisegepäck)","ex":"De koffer staat op zolder.","exDe":"Der Koffer steht auf dem Dachboden."},{"de":"der Kofferraum (Auto, bes. belgisch)","ex":"Leg de tassen maar in de koffer van de auto.","exDe":"Leg die Taschen einfach in den Kofferraum des Autos."}],"usage":"'Kofferraum' in dieser Bedeutung vor allem im belgischen Niederländisch; in den Niederlanden meist 'kofferbak'.","genus":"de","plural":"koffers","illustratable":true},"bk_778":{"lemma":"postkantoor","displayNl":"het postkantoor","pos":"substantief","meanings":[{"de":"das Postamt, die Poststelle","ex":"Het postkantoor is gesloten.","exDe":"Das Postamt ist geschlossen."}],"usage":"Zusammensetzung 'post' + 'kantoor' (Büro). Neutrum wegen 'kantoor'.","genus":"het","plural":"postkantoren","illustratable":true},"bk_779":{"lemma":"supermarkt","displayNl":"de supermarkt","pos":"substantief","meanings":[{"de":"der Supermarkt","ex":"De supermarkt is de hele dag open.","exDe":"Der Supermarkt ist den ganzen Tag offen."}],"usage":"Plural auch 'supermarkts' gebräuchlich, standardsprachlich meist 'supermarkten'.","genus":"de","plural":"supermarkten","illustratable":true},"bk_780":{"lemma":"bakker","displayNl":"de bakker","pos":"substantief","meanings":[{"de":"der Bäcker (Person, Beruf)","ex":"De bakker staat elke ochtend vroeg op.","exDe":"Der Bäcker steht jeden Morgen früh auf."},{"de":"die Bäckerei (der Laden)","ex":"Bij de bakker koop ik brood.","exDe":"Beim Bäcker kaufe ich Brot."}],"usage":"'bij de bakker' meint umgangssprachlich die Bäckerei; die Bäckerei heißt auch 'bakkerij'.","genus":"de","plural":"bakkers","illustratable":true},"bk_781":{"lemma":"bibliotheek","displayNl":"de bibliotheek","pos":"substantief","meanings":[{"de":"die Bibliothek, die Bücherei","ex":"Ik leen boeken in de bibliotheek.","exDe":"Ich leihe Bücher in der Bibliothek."}],"usage":"Kurzform umgangssprachlich 'bieb'.","genus":"de","plural":"bibliotheken","illustratable":true},"bk_782":{"lemma":"museum","displayNl":"het museum","pos":"substantief","meanings":[{"de":"das Museum","ex":"Het museum is op zondag open.","exDe":"Das Museum ist am Sonntag offen."}],"usage":"Plural 'musea' (lateinisch) oder umgangssprachlich 'museums'.","genus":"het","plural":"musea","illustratable":true},"bk_783":{"lemma":"bioscoop","displayNl":"de bioscoop","pos":"substantief","meanings":[{"de":"das Kino, das Lichtspielhaus","ex":"We gaan vanavond naar de bioscoop.","exDe":"Wir gehen heute Abend ins Kino."}],"usage":"Umgangssprachliche Kurzform 'bios'.","genus":"de","plural":"bioscopen","illustratable":true},"bk_784":{"lemma":"theater","displayNl":"het theater","pos":"substantief","meanings":[{"de":"das Theater (Gebäude, Bühne)","ex":"Het theater staat in het centrum.","exDe":"Das Theater steht im Zentrum."},{"de":"das Theater, das Getue, das Aufheben (übertriebenes Verhalten)","ex":"Maak niet zo'n theater om niets.","exDe":"Mach nicht so ein Theater um nichts."}],"usage":"Neutrum: het theater; Plural theaters. Auch bildlich für übertriebenes Gehabe.","genus":"het","plural":"theaters","illustratable":true},"bk_785":{"lemma":"stadhuis","displayNl":"het stadhuis","pos":"substantief","meanings":[{"de":"das Rathaus","ex":"Het stadhuis is een mooi gebouw.","exDe":"Das Rathaus ist ein schönes Gebäude."}],"usage":"Neutrum: het stadhuis; Plural stadhuizen (Vokalwechsel ui bleibt, s→z).","genus":"het","plural":"stadhuizen","illustratable":true},"bk_787":{"lemma":"toren","displayNl":"de toren","pos":"substantief","meanings":[{"de":"der Turm","ex":"De toren is van ver te zien.","exDe":"Der Turm ist von weitem zu sehen."},{"de":"der Turm (Schachfigur)","ex":"Hij sloeg mijn toren met zijn loper.","exDe":"Er schlug meinen Turm mit seinem Läufer."}],"usage":"de-Wort; Plural torens. Auch die Schachfigur.","genus":"de","plural":"torens","illustratable":true},"bk_788":{"lemma":"wijk","displayNl":"de wijk","pos":"substantief","meanings":[{"de":"das Viertel, das Stadtviertel, der Stadtteil","ex":"Ik woon in een rustige wijk.","exDe":"Ich wohne in einem ruhigen Viertel."},{"de":"die Flucht (in der Wendung „de wijk nemen“ – fliehen)","ex":"Ze namen de wijk naar het buitenland.","exDe":"Sie flüchteten ins Ausland."}],"usage":"de-Wort; Plural wijken. Feste Wendung: de wijk nemen = fliehen.","genus":"de","plural":"wijken","illustratable":true},"bk_789":{"lemma":"dorp","displayNl":"het dorp","pos":"substantief","meanings":[{"de":"das Dorf","ex":"Mijn oma woont in een dorp.","exDe":"Meine Oma wohnt in einem Dorf."}],"usage":"Neutrum: het dorp; Plural dorpen.","genus":"het","plural":"dorpen","illustratable":true},"bk_790":{"lemma":"stoplicht","displayNl":"het stoplicht","pos":"substantief","meanings":[{"de":"die Ampel, die Verkehrsampel","ex":"Wacht bij het stoplicht.","exDe":"Warte an der Ampel."}],"usage":"Neutrum: het stoplicht; Plural stoplichten. Synonym: verkeerslicht.","genus":"het","plural":"stoplichten","illustratable":true},"bk_791":{"lemma":"verkeer","displayNl":"het verkeer","pos":"substantief","meanings":[{"de":"der Verkehr (Straßenverkehr)","ex":"Het verkeer is heel druk.","exDe":"Der Verkehr ist sehr dicht."},{"de":"der Umgang, der Verkehr (zwischenmenschlicher Kontakt)","ex":"Zij heeft veel verkeer met kunstenaars.","exDe":"Sie hat viel Umgang mit Künstlern."}],"usage":"Neutrum: het verkeer; kein gebräuchlicher Plural (unzählbar). Auch übertragen für Umgang/Kontakt.","genus":"het","illustratable":true},"bk_792":{"lemma":"verkeersbord","displayNl":"het verkeersbord","pos":"substantief","meanings":[{"de":"das Verkehrsschild, das Verkehrszeichen","ex":"Lees het verkeersbord goed.","exDe":"Lies das Verkehrsschild genau."}],"usage":"Neutrum: het verkeersbord; Plural verkeersborden. Fugen-s: verkeer + s + bord.","genus":"het","plural":"verkeersborden","illustratable":true},"bk_793":{"lemma":"zebrapad","displayNl":"het zebrapad","pos":"substantief","meanings":[{"de":"der Zebrastreifen","ex":"Steek de straat over op het zebrapad.","exDe":"Überquere die Straße am Zebrastreifen."}],"usage":"Fußgängerüberweg mit weißen Streifen; man 'steekt over op het zebrapad'.","genus":"het","plural":"zebrapaden","illustratable":true},"bk_794":{"lemma":"trottoir","displayNl":"het trottoir","pos":"substantief","meanings":[{"de":"der Gehweg, der Bürgersteig","ex":"Loop op het trottoir, niet op de weg.","exDe":"Geh auf dem Gehweg, nicht auf der Straße."}],"usage":"Gepflasterter Fußgängerweg neben der Straße; auch 'de stoep'.","genus":"het","plural":"trottoirs","illustratable":true},"bk_795":{"lemma":"fietspad","displayNl":"het fietspad","pos":"substantief","meanings":[{"de":"der Radweg","ex":"Fietsers rijden op het fietspad.","exDe":"Radfahrer fahren auf dem Radweg."}],"usage":"In den Niederlanden meist rot asphaltiert; für Fahrräder reserviert.","genus":"het","plural":"fietspaden","illustratable":true},"bk_796":{"lemma":"parkeerplaats","displayNl":"de parkeerplaats","pos":"substantief","meanings":[{"de":"der Parkplatz (Fläche zum Parken)","ex":"De parkeerplaats bij het station is vol.","exDe":"Der Parkplatz am Bahnhof ist voll."},{"de":"die Parklücke, der einzelne Stellplatz","ex":"Ik vond nog een vrije parkeerplaats.","exDe":"Ich fand noch eine freie Parklücke."}],"usage":"Bezeichnet sowohl die ganze Parkfläche als auch einen einzelnen Stellplatz.","genus":"de","plural":"parkeerplaatsen","illustratable":true},"bk_797":{"lemma":"kruising","displayNl":"de kruising","pos":"substantief","meanings":[{"de":"die Kreuzung (Straßen)","ex":"Sla bij de kruising rechtsaf.","exDe":"Biege an der Kreuzung rechts ab."},{"de":"die Kreuzung, der Mischling (von Tieren/Pflanzen)","ex":"Deze hond is een kruising tussen een labrador en een poedel.","exDe":"Dieser Hund ist eine Kreuzung aus Labrador und Pudel."}],"usage":"Örtliche Straßenkreuzung; übertragen auch biologische Kreuzung.","genus":"de","plural":"kruisingen","illustratable":true},"bk_798":{"lemma":"rotonde","displayNl":"de rotonde","pos":"substantief","meanings":[{"de":"der Kreisverkehr","ex":"Neem de tweede afslag op de rotonde.","exDe":"Nimm die zweite Ausfahrt im Kreisverkehr."}],"usage":"Kreisförmige Verkehrsführung; man 'neemt een afslag'.","genus":"de","plural":"rotondes","illustratable":true},"bk_799":{"lemma":"snelweg","displayNl":"de snelweg","pos":"substantief","meanings":[{"de":"die Autobahn","ex":"De snelweg naar Amsterdam is heel druk.","exDe":"Die Autobahn nach Amsterdam ist sehr voll."}],"usage":"Mehrspurige Fernstraße; niederländische A-Wege.","genus":"de","plural":"snelwegen","illustratable":true},"bk_800":{"lemma":"tunnel","displayNl":"de tunnel","pos":"substantief","meanings":[{"de":"der Tunnel","ex":"De trein rijdt door een tunnel.","exDe":"Der Zug fährt durch einen Tunnel."}],"usage":"Unterirdische oder unterführende Röhre für Verkehr; Plural auch 'tunnels'.","genus":"de","plural":"tunnels","illustratable":true},"bk_801":{"lemma":"perron","displayNl":"het perron","pos":"substantief","meanings":[{"de":"der Bahnsteig","ex":"De trein staat op perron drie.","exDe":"Der Zug steht auf Bahnsteig drei."},{"de":"das Gleis (als Zugangsort zum Zug)","ex":"We wachten op het perron op de trein.","exDe":"Wir warten am Bahnsteig auf den Zug."}],"usage":"Ort im Bahnhof, an dem man ein- und aussteigt; man staat/wacht op het perron.","genus":"het","plural":"perrons","illustratable":true},"bk_802":{"lemma":"ingang","displayNl":"de ingang","pos":"substantief","meanings":[{"de":"der Eingang","ex":"De ingang is aan de voorkant.","exDe":"Der Eingang ist an der Vorderseite."},{"de":"der Zutritt / das Inkrafttreten (met ingang van)","ex":"Met ingang van maandag geldt de nieuwe regel.","exDe":"Ab Montag gilt die neue Regel."}],"usage":"Konkret: Tür/Öffnung zum Hineingehen. Übertragen in 'met ingang van' = ab/mit Wirkung vom.","genus":"de","plural":"ingangen","illustratable":true},"bk_803":{"lemma":"uitgang","displayNl":"de uitgang","pos":"substantief","meanings":[{"de":"der Ausgang","ex":"Waar is de uitgang?","exDe":"Wo ist der Ausgang?"},{"de":"die Endung (grammatisch, z. B. Wortendung)","ex":"Het werkwoord heeft de uitgang -en.","exDe":"Das Verb hat die Endung -en."}],"usage":"Konkret: Tür/Öffnung zum Hinausgehen (Notausgang = nooduitgang). Grammatisch: Wortendung.","genus":"de","plural":"uitgangen","illustratable":true},"bk_805":{"lemma":"afstand","displayNl":"de afstand","pos":"substantief","meanings":[{"de":"die Entfernung / der Abstand","ex":"De afstand is niet groot.","exDe":"Die Entfernung ist nicht groß."},{"de":"der Verzicht (afstand doen van)","ex":"Hij doet afstand van zijn troon.","exDe":"Er verzichtet auf seinen Thron."}],"usage":"Räumlicher Abstand/Entfernung; 'op afstand' = aus der Ferne; 'afstand doen van' = auf etwas verzichten.","genus":"de","plural":"afstanden"},"bk_806":{"lemma":"bestemming","displayNl":"de bestemming","pos":"substantief","meanings":[{"de":"das Reiseziel / der Zielort","ex":"Wat is jouw bestemming?","exDe":"Was ist dein Reiseziel?"},{"de":"die Bestimmung / der Verwendungszweck","ex":"Dit gebouw krijgt een nieuwe bestemming.","exDe":"Dieses Gebäude bekommt eine neue Bestimmung."}],"usage":"Ort, an den man reist; auch der vorgesehene Zweck einer Sache.","genus":"de","plural":"bestemmingen"},"bk_807":{"lemma":"passagier","displayNl":"de passagier","pos":"substantief","meanings":[{"de":"der Fahrgast / der Passagier","ex":"Elke passagier heeft een kaartje.","exDe":"Jeder Fahrgast hat ein Ticket."}],"usage":"Person, die in einem Fahrzeug/Zug/Flugzeug mitfährt (nicht steuert).","genus":"de","plural":"passagiers","illustratable":true},"bk_808":{"lemma":"chauffeur","displayNl":"de chauffeur","pos":"substantief","meanings":[{"de":"der Fahrer / der Chauffeur","ex":"De chauffeur weet de weg.","exDe":"Der Fahrer kennt den Weg."}],"usage":"Person, die ein Fahrzeug (Bus, Taxi, LKW) berufsmäßig steuert.","genus":"de","plural":"chauffeurs","illustratable":true},"bk_809":{"lemma":"conducteur","displayNl":"de conducteur","pos":"substantief","meanings":[{"de":"der Schaffner / der Zugbegleiter","ex":"De conducteur controleert de kaartjes.","exDe":"Der Schaffner kontrolliert die Tickets."}],"usage":"Person im Zug, die Fahrkarten kontrolliert und den Zugbetrieb begleitet.","genus":"de","plural":"conducteurs","illustratable":true},"bk_810":{"lemma":"loket","displayNl":"het loket","pos":"substantief","meanings":[{"de":"der Schalter","ex":"Koop je kaartje bij het loket.","exDe":"Kaufe dein Ticket am Schalter."},{"de":"das Schalterfenster","ex":"Het loket is van negen tot vijf open.","exDe":"Das Schalterfenster ist von neun bis fünf geöffnet."}],"usage":"Bemannter Verkaufs-/Serviceschalter (Bahnhof, Post, Behörde) mit Fensteröffnung; auch bildlich (\"digitaal loket\" = Online-Anlaufstelle).","genus":"het","plural":"loketten","illustratable":true},"bk_811":{"lemma":"dienstregeling","displayNl":"de dienstregeling","pos":"substantief","meanings":[{"de":"der Fahrplan","ex":"Ik kijk op de dienstregeling.","exDe":"Ich schaue auf den Fahrplan."},{"de":"der Zeitplan (des öffentlichen Verkehrs)","ex":"In de zomer geldt een aangepaste dienstregeling.","exDe":"Im Sommer gilt ein angepasster Zeitplan."}],"usage":"Der gesamte Abfahrts-/Ankunftsplan eines Verkehrsbetriebs (Bahn, Bus, Fähre); nicht die einzelne Anzeigetafel.","genus":"de","plural":"dienstregelingen","illustratable":true},"bk_812":{"lemma":"vertraging","displayNl":"de vertraging","pos":"substantief","meanings":[{"de":"die Verspätung","ex":"De trein heeft tien minuten vertraging.","exDe":"Der Zug hat zehn Minuten Verspätung."},{"de":"die Verzögerung","ex":"Door de storing ontstond er veel vertraging.","exDe":"Durch die Störung entstand eine große Verzögerung."}],"usage":"Zeitlicher Rückstand gegenüber dem Plan; \"vertraging hebben\" = verspätet/verzögert sein.","genus":"de","plural":"vertragingen"},"bk_813":{"lemma":"overstap","displayNl":"de overstap","pos":"substantief","meanings":[{"de":"das Umsteigen","ex":"De overstap is in Utrecht.","exDe":"Das Umsteigen ist in Utrecht."},{"de":"der Wechsel (Umstieg)","ex":"De overstap naar een nieuwe baan viel hem zwaar.","exDe":"Der Wechsel zu einer neuen Stelle fiel ihm schwer."}],"usage":"Der Umstieg von einem Verkehrsmittel/Anschluss auf ein anderes; übertragen ein Wechsel (Job, Anbieter, System).","genus":"de","plural":"overstappen"},"bk_814":{"lemma":"overstappen","displayNl":"overstappen","pos":"werkwoord","meanings":[{"de":"umsteigen","ex":"Ik moet in Den Haag overstappen.","exDe":"Ich muss in Den Haag umsteigen."},{"de":"wechseln (zu etwas anderem übergehen)","ex":"We stappen over op groene energie.","exDe":"Wir wechseln zu grüner Energie."}],"usage":"Trennbares Verb (over + stappen); Perfekt mit zijn. Konkret: von einem Verkehrsmittel auf ein anderes; übertragen: op iets overstappen = zu etwas wechseln.","conjugation":{"presens":{"ik":"stap over","jij":"stapt over","hij":"stapt over","wij":"stappen over"},"imperfectum":{"ik":"stapte over","wij":"stapten over"},"perfectum":{"aux":"zijn","participle":"overgestapt"}},"illustratable":true},"bk_815":{"lemma":"instappen","displayNl":"instappen","pos":"werkwoord","meanings":[{"de":"einsteigen","ex":"We stappen in de bus.","exDe":"Wir steigen in den Bus ein."},{"de":"einsteigen (sich beteiligen)","ex":"Hij wilde niet in het project instappen.","exDe":"Er wollte nicht in das Projekt einsteigen."}],"usage":"Trennbares Verb (in + stappen); Perfekt mit zijn. Konkret: in ein Fahrzeug einsteigen; übertragen: bei etwas einsteigen/sich beteiligen.","conjugation":{"presens":{"ik":"stap in","jij":"stapt in","hij":"stapt in","wij":"stappen in"},"imperfectum":{"ik":"stapte in","wij":"stapten in"},"perfectum":{"aux":"zijn","participle":"ingestapt"}},"illustratable":true},"bk_816":{"lemma":"vertrekken","displayNl":"vertrekken","pos":"werkwoord","meanings":[{"de":"abfahren","ex":"De trein vertrekt om negen uur.","exDe":"Der Zug fährt um neun Uhr ab."},{"de":"aufbrechen, weggehen","ex":"We vertrekken morgenvroeg naar Spanje.","exDe":"Wir brechen morgen früh nach Spanien auf."},{"de":"verziehen (das Gesicht)","ex":"Hij vertrok geen spier.","exDe":"Er verzog keine Miene."}],"usage":"Unregelmäßiges, untrennbares Verb; Perfekt mit zijn (Bewegung). Abfahren/aufbrechen; in fester Wendung \"een spier vertrekken\" = eine Miene verziehen.","conjugation":{"presens":{"ik":"vertrek","jij":"vertrekt","hij":"vertrekt","wij":"vertrekken"},"imperfectum":{"ik":"vertrok","wij":"vertrokken"},"perfectum":{"aux":"zijn","participle":"vertrokken"}},"illustratable":true},"bk_817":{"lemma":"aankomen","displayNl":"aankomen","pos":"werkwoord","meanings":[{"de":"ankommen","ex":"We komen om drie uur aan.","exDe":"Wir kommen um drei Uhr an."},{"de":"zunehmen (an Gewicht)","ex":"In de winter kom ik altijd wat aan.","exDe":"Im Winter nehme ich immer etwas zu."},{"de":"ankommen auf, abhängen von","ex":"Het komt aan op de details.","exDe":"Es kommt auf die Details an."}],"usage":"Trennbares, unregelmäßiges Verb (aan + komen); Perfekt mit zijn. Ankommen (Ort); an Gewicht zunehmen; \"aankomen op\" = auf etwas ankommen.","conjugation":{"presens":{"ik":"kom aan","jij":"komt aan","hij":"komt aan","wij":"komen aan"},"imperfectum":{"ik":"kwam aan","wij":"kwamen aan"},"perfectum":{"aux":"zijn","participle":"aangekomen"}},"illustratable":true},"bk_818":{"lemma":"oversteken","displayNl":"oversteken","pos":"werkwoord","meanings":[{"de":"überqueren","ex":"Steek voorzichtig over bij het zebrapad.","exDe":"Überquere vorsichtig am Zebrastreifen."},{"de":"übersetzen (mit einem Boot ans andere Ufer)","ex":"We staken met de veerpont over naar de overkant.","exDe":"Wir setzten mit der Fähre ans andere Ufer über."}],"usage":"Trennbares Verb (over + steken). Bei der Bewegung des Überquerens Hilfsverb 'zijn'.","conjugation":{"presens":{"ik":"steek over","jij":"steekt over","hij":"steekt over","wij":"steken over"},"imperfectum":{"ik":"stak over","wij":"staken over"},"perfectum":{"aux":"zijn","participle":"overgestoken"}},"illustratable":true},"bk_819":{"lemma":"parkeren","displayNl":"parkeren","pos":"werkwoord","meanings":[{"de":"parken","ex":"Je mag hier niet parkeren.","exDe":"Du darfst hier nicht parken."}],"usage":"Regelmäßiges Verb, Hilfsverb 'hebben'.","conjugation":{"presens":{"ik":"parkeer","jij":"parkeert","hij":"parkeert","wij":"parkeren"},"imperfectum":{"ik":"parkeerde","wij":"parkeerden"},"perfectum":{"aux":"hebben","participle":"geparkeerd"}},"illustratable":true},"bk_820":{"lemma":"afslaan","displayNl":"afslaan","pos":"werkwoord","meanings":[{"de":"abbiegen","ex":"Sla bij de kerk links af.","exDe":"Bieg bei der Kirche links ab."},{"de":"ablehnen, ausschlagen (ein Angebot)","ex":"Hij sloeg het aanbod beleefd af.","exDe":"Er lehnte das Angebot höflich ab."},{"de":"abwürgen, absterben (Motor)","ex":"De motor sloeg bij het stoplicht af.","exDe":"Der Motor starb an der Ampel ab."}],"usage":"Trennbares Verb (af + slaan). Bei Richtungsbewegung 'zijn' (ik ben linksaf geslagen); in der Bedeutung 'ablehnen' mit 'hebben' (hij heeft het afgeslagen).","conjugation":{"presens":{"ik":"sla af","jij":"slaat af","hij":"slaat af","wij":"slaan af"},"imperfectum":{"ik":"sloeg af","wij":"sloegen af"},"perfectum":{"aux":"zijn","participle":"afgeslagen"}},"illustratable":true},"bk_821":{"lemma":"stoppen","displayNl":"stoppen","pos":"werkwoord","meanings":[{"de":"anhalten, stehen bleiben","ex":"De bus stopt hier niet.","exDe":"Der Bus hält hier nicht."},{"de":"aufhören (mit etwas)","ex":"Hij is gestopt met roken.","exDe":"Er hat mit dem Rauchen aufgehört."},{"de":"stecken, hineinstecken","ex":"Ze stopte de brief in haar tas.","exDe":"Sie steckte den Brief in ihre Tasche."}],"usage":"Regelmäßig. Beim Anhalten/Aufhören Hilfsverb 'zijn' (de bus is gestopt); in der transitiven Bedeutung 'stecken' mit 'hebben' (ze heeft de brief in haar tas gestopt).","conjugation":{"presens":{"ik":"stop","jij":"stopt","hij":"stopt","wij":"stoppen"},"imperfectum":{"ik":"stopte","wij":"stopten"},"perfectum":{"aux":"zijn","participle":"gestopt"}},"illustratable":true},"bk_822":{"lemma":"wachten","displayNl":"wachten","pos":"werkwoord","meanings":[{"de":"warten","ex":"We wachten op de tram.","exDe":"Wir warten auf die Straßenbahn."}],"usage":"Regelmäßig, Hilfsverb 'hebben'. Man wartet 'op' etwas/jemanden (wachten op).","conjugation":{"presens":{"ik":"wacht","jij":"wacht","hij":"wacht","wij":"wachten"},"imperfectum":{"ik":"wachtte","wij":"wachtten"},"perfectum":{"aux":"hebben","participle":"gewacht"}},"illustratable":true},"bk_823":{"lemma":"zoeken","displayNl":"zoeken","pos":"werkwoord","meanings":[{"de":"suchen","ex":"Ik zoek de weg naar het museum.","exDe":"Ich suche den Weg zum Museum."},{"de":"aufsuchen, nachschlagen (etwas suchen/finden wollen)","ex":"Ze zocht het woord op in het woordenboek.","exDe":"Sie suchte das Wort im Wörterbuch nach."}],"usage":"Unregelmäßig (zocht, gezocht), Hilfsverb 'hebben'. 'opzoeken' = nachschlagen/aufsuchen (trennbar).","conjugation":{"presens":{"ik":"zoek","jij":"zoekt","hij":"zoekt","wij":"zoeken"},"imperfectum":{"ik":"zocht","wij":"zochten"},"perfectum":{"aux":"hebben","participle":"gezocht"}},"illustratable":true},"bk_825":{"lemma":"reizen","displayNl":"reizen","pos":"werkwoord","meanings":[{"de":"reisen","ex":"Ik reis graag met de trein.","exDe":"Ich reise gerne mit dem Zug."}],"usage":"Regelmäßig; als Bewegungsverb Hilfsverb 'zijn' (ik ben naar Amsterdam gereisd).","conjugation":{"presens":{"ik":"reis","jij":"reist","hij":"reist","wij":"reizen"},"imperfectum":{"ik":"reisde","wij":"reisden"},"perfectum":{"aux":"zijn","participle":"gereisd"}},"illustratable":true},"bk_826":{"lemma":"reiziger","displayNl":"de reiziger","pos":"substantief","meanings":[{"de":"der Reisende, der Fahrgast","ex":"Elke reiziger heeft een koffer.","exDe":"Jeder Reisende hat einen Koffer."}],"usage":"de-Wort; Plural 'reizigers'. Weibliche Form: reizigster.","genus":"de","plural":"reizigers","illustratable":true},"bk_827":{"lemma":"rugzak","displayNl":"de rugzak","pos":"substantief","meanings":[{"de":"der Rucksack","ex":"Ik draag mijn rugzak op de fiets.","exDe":"Ich trage meinen Rucksack auf dem Fahrrad."},{"de":"der Schulranzen / die Schultasche (als Rucksack getragen)","ex":"De kinderen hebben een zware rugzak vol boeken.","exDe":"Die Kinder haben einen schweren Rucksack voller Bücher."}],"usage":"Alltagswort; auch übertragen 'een rugzak aan ervaring' (ein Rucksack voll Erfahrung).","genus":"de","plural":"rugzakken","illustratable":true},"bk_828":{"lemma":"kilometer","displayNl":"de kilometer","pos":"substantief","meanings":[{"de":"der Kilometer","ex":"Het is nog vijf kilometer.","exDe":"Es sind noch fünf Kilometer."},{"de":"der Kilometer (zurückgelegte Strecke)","ex":"Ik heb vandaag veertig kilometer gefietst.","exDe":"Ich bin heute vierzig Kilometer geradelt."}],"usage":"Nach Zahlwort meist unverändert: 'vijf kilometer' (nicht 'kilometers'), sonst Plural 'kilometers'. Abkürzung: km.","genus":"de","plural":"kilometers"},"bk_829":{"lemma":"bushalte","displayNl":"de bushalte","pos":"substantief","meanings":[{"de":"die Bushaltestelle","ex":"Ik sta bij de bushalte.","exDe":"Ich stehe an der Bushaltestelle."}],"usage":"Auch Plural 'bushalten' möglich. Vergleiche 'halte' (Haltestelle allgemein).","genus":"de","plural":"bushaltes","illustratable":true},"bk_830":{"lemma":"taxi","displayNl":"de taxi","pos":"substantief","meanings":[{"de":"das Taxi","ex":"We nemen een taxi naar huis.","exDe":"Wir nehmen ein Taxi nach Hause."}],"usage":"Plural mit Apostroph: 'taxi's'. 'een taxi nemen/bellen' = ein Taxi nehmen/rufen.","genus":"de","plural":"taxi's","illustratable":true},"bk_832":{"lemma":"veerpont","displayNl":"de veerpont","pos":"substantief","meanings":[{"de":"die Fähre (Flussfähre, Personen-/Radfähre)","ex":"De veerpont vaart elk uur.","exDe":"Die Fähre fährt jede Stunde."}],"usage":"Synonym 'de pont'. Meint die typisch niederländische kleine Fähre über Gracht/Fluss.","genus":"de","plural":"veerponten","illustratable":true},"bk_833":{"lemma":"haven","displayNl":"de haven","pos":"substantief","meanings":[{"de":"der Hafen","ex":"De boten liggen in de haven.","exDe":"Die Boote liegen im Hafen."},{"de":"der Zufluchtsort / sichere Hafen (übertragen)","ex":"Thuis is voor haar een veilige haven.","exDe":"Zu Hause ist für sie ein sicherer Hafen."}],"usage":"Konkret Schiffshafen und übertragen 'veilige haven' (sicherer Hafen).","genus":"de","plural":"havens","illustratable":true},"bk_834":{"lemma":"brommer","displayNl":"de brommer","pos":"substantief","meanings":[{"de":"das Mofa / der Motorroller (Kleinkraftrad)","ex":"Hij rijdt op een brommer.","exDe":"Er fährt mit einem Mofa."}],"usage":"Umgangssprachlich; kleines motorisiertes Zweirad bis 45 km/h. Von 'brommen' (brummen).","genus":"de","plural":"brommers","illustratable":true},"bk_835":{"lemma":"motor","displayNl":"de motor","pos":"substantief","meanings":[{"de":"das Motorrad","ex":"Hij rijdt op een zware motor.","exDe":"Er fährt ein schweres Motorrad."},{"de":"der Motor (Antrieb, Maschine)","ex":"De motor van de auto maakt veel lawaai.","exDe":"Der Motor des Autos macht viel Lärm."},{"de":"die treibende Kraft (übertragen)","ex":"Zij is de motor achter het project.","exDe":"Sie ist die treibende Kraft hinter dem Projekt."}],"usage":"Zwei Hauptbedeutungen: Motorrad und Motor/Antrieb; Plural stets 'motoren'. 'op de motor' = mit dem Motorrad.","genus":"de","plural":"motoren","illustratable":true},"bk_836":{"lemma":"vrachtwagen","displayNl":"de vrachtwagen","pos":"substantief","meanings":[{"de":"der Lastwagen, der LKW","ex":"De vrachtwagen is heel groot en zwaar.","exDe":"Der Lastwagen ist sehr groß und schwer."},{"de":"der Laster (umgangssprachlich für Transportfahrzeug)","ex":"De vrachtwagen brengt de dozen naar de winkel.","exDe":"Der Laster bringt die Kartons zum Geschäft."}],"usage":"Alltäglich für ein großes Güterfahrzeug; im Verkehr und Transport sehr gebräuchlich.","genus":"de","plural":"vrachtwagens","illustratable":true},"bk_837":{"lemma":"benzinestation","displayNl":"het benzinestation","pos":"substantief","meanings":[{"de":"die Tankstelle","ex":"We stoppen bij het benzinestation om te tanken.","exDe":"Wir halten an der Tankstelle, um zu tanken."},{"de":"die Zapfsäulen-Anlage / der Tankstellen-Shop","ex":"Bij het benzinestation kun je ook koffie kopen.","exDe":"An der Tankstelle kann man auch Kaffee kaufen."}],"usage":"Standardwort für eine Tankstelle; auch 'tankstation' ist gebräuchlich.","genus":"het","plural":"benzinestations","illustratable":true},"bk_838":{"lemma":"fontein","displayNl":"de fontein","pos":"substantief","meanings":[{"de":"der Springbrunnen, die Fontäne","ex":"Op het plein staat een grote fontein.","exDe":"Auf dem Platz steht ein großer Springbrunnen."},{"de":"der Wasserstrahl / die aufsteigende Wassersäule","ex":"De fontein spuit hoog de lucht in.","exDe":"Die Fontäne spritzt hoch in die Luft."}],"usage":"Bezeichnet sowohl den Springbrunnen als Bauwerk als auch den aufsteigenden Wasserstrahl.","genus":"de","plural":"fonteinen","illustratable":true},"bk_839":{"lemma":"taak","displayNl":"de taak","pos":"substantief","meanings":[{"de":"die Aufgabe","ex":"Dit is mijn belangrijkste taak op het werk.","exDe":"Das ist meine wichtigste Aufgabe bei der Arbeit."},{"de":"die Pflicht, das Amt","ex":"Het is de taak van de ouders om te helpen.","exDe":"Es ist die Pflicht der Eltern, zu helfen."},{"de":"die zu erledigende Sache / der To-do-Punkt","ex":"Ik heb nog een paar taken op mijn lijst.","exDe":"Ich habe noch ein paar Aufgaben auf meiner Liste."}],"usage":"Abstrakter Begriff für eine zu erledigende Aufgabe oder eine Verantwortung; Plural 'taken'.","genus":"de","plural":"taken"},"bk_840":{"lemma":"vergadering","displayNl":"de vergadering","pos":"substantief","meanings":[{"de":"die Besprechung, das Meeting","ex":"De vergadering duurt tot twaalf uur.","exDe":"Die Besprechung dauert bis zwölf Uhr."},{"de":"die Sitzung, die Versammlung","ex":"De jaarlijkse vergadering van de vereniging is vanavond.","exDe":"Die jährliche Versammlung des Vereins ist heute Abend."}],"usage":"Formelles Zusammentreffen zur Beratung; im Arbeitsleben sehr geläufig.","genus":"de","plural":"vergaderingen","illustratable":true},"bk_841":{"lemma":"vergaderen","displayNl":"vergaderen","pos":"werkwoord","meanings":[{"de":"tagen, eine Besprechung abhalten","ex":"We vergaderen elke maandag om tien uur.","exDe":"Wir haben jeden Montag um zehn Uhr eine Besprechung."},{"de":"beraten, sich versammeln","ex":"De directie vergadert over het nieuwe plan.","exDe":"Die Geschäftsleitung berät über den neuen Plan."}],"usage":"Regelmäßiges Verb; beschreibt das Abhalten einer Besprechung oder Sitzung.","conjugation":{"presens":{"ik":"vergader","jij":"vergadert","hij":"vergadert","wij":"vergaderen"},"imperfectum":{"ik":"vergaderde","wij":"vergaderden"},"perfectum":{"aux":"hebben","participle":"vergaderd"}}},"bk_842":{"lemma":"sollicitatie","displayNl":"de sollicitatie","pos":"substantief","meanings":[{"de":"die Bewerbung","ex":"Mijn sollicitatie voor de baan is klaar.","exDe":"Meine Bewerbung für die Stelle ist fertig."},{"de":"das Bewerbungsgespräch (kurz für sollicitatiegesprek)","ex":"Ik heb morgen een sollicitatie bij een bank.","exDe":"Ich habe morgen ein Bewerbungsgespräch bei einer Bank."}],"usage":"Bezeichnet die Bewerbung auf eine Stelle; kann umgangssprachlich auch das Vorstellungsgespräch meinen.","genus":"de","plural":"sollicitaties"},"bk_843":{"lemma":"solliciteren","displayNl":"solliciteren","pos":"werkwoord","meanings":[{"de":"sich bewerben","ex":"Ik solliciteer bij een grote bank.","exDe":"Ich bewerbe mich bei einer großen Bank."},{"de":"sich um eine Stelle bemühen","ex":"Zij solliciteert op de functie van manager.","exDe":"Sie bewirbt sich um die Position als Manager."}],"usage":"Verb auf -eren; wird mit 'bij' (Firma) oder 'op/naar' (Stelle) verwendet, Hilfsverb hebben.","conjugation":{"presens":{"ik":"solliciteer","jij":"solliciteert","hij":"solliciteert","wij":"solliciteren"},"imperfectum":{"ik":"solliciteerde","wij":"solliciteerden"},"perfectum":{"aux":"hebben","participle":"gesolliciteerd"}}},"bk_844":{"lemma":"cv","displayNl":"het cv","pos":"substantief","meanings":[{"de":"der Lebenslauf","ex":"Stuur je cv mee met de sollicitatie.","exDe":"Schick deinen Lebenslauf mit der Bewerbung mit."},{"de":"der Werdegang (beruflich)","ex":"Op zijn cv staat veel werkervaring.","exDe":"In seinem Lebenslauf steht viel Berufserfahrung."}],"usage":"Kürzel von 'curriculum vitae'; wird 'de-cee-vee' ausgesprochen. Plural mit Apostroph: cv's.","genus":"het","plural":"cv's"},"bk_845":{"lemma":"gesprek","displayNl":"het gesprek","pos":"substantief","meanings":[{"de":"das Gespräch, die Unterhaltung","ex":"We hadden een lang gesprek over het werk.","exDe":"Wir hatten ein langes Gespräch über die Arbeit."},{"de":"das Vorstellungsgespräch (sollicitatiegesprek)","ex":"Ik ben uitgenodigd voor een gesprek.","exDe":"Ich wurde zu einem Vorstellungsgespräch eingeladen."},{"de":"das Telefonat, der Anruf","ex":"Het gesprek werd plotseling verbroken.","exDe":"Das Telefonat wurde plötzlich unterbrochen."}],"usage":"Häufig in Zusammensetzungen: sollicitatiegesprek (Vorstellungsgespräch), telefoongesprek (Telefonat).","genus":"het","plural":"gesprekken","illustratable":true},"bk_846":{"lemma":"contract","displayNl":"het contract","pos":"substantief","meanings":[{"de":"der Vertrag","ex":"Ik teken het contract vandaag.","exDe":"Ich unterschreibe den Vertrag heute."},{"de":"der Arbeitsvertrag (arbeidscontract)","ex":"Zij heeft een vast contract gekregen.","exDe":"Sie hat einen unbefristeten Arbeitsvertrag bekommen."}],"usage":"Oft: een vast/tijdelijk contract (un-/befristeter Vertrag); een contract tekenen (einen Vertrag unterschreiben).","genus":"het","plural":"contracten","illustratable":true},"bk_847":{"lemma":"salaris","displayNl":"het salaris","pos":"substantief","meanings":[{"de":"das Gehalt","ex":"Mijn salaris is deze maand hoger.","exDe":"Mein Gehalt ist diesen Monat höher."},{"de":"der Verdienst, die Bezahlung","ex":"Ze onderhandelt over een beter salaris.","exDe":"Sie verhandelt über eine bessere Bezahlung."}],"usage":"'salaris' meint typisch das monatliche Angestelltengehalt; vgl. 'loon' (eher Lohn/Arbeiterlohn).","genus":"het","plural":"salarissen"},"bk_848":{"lemma":"loon","displayNl":"het loon","pos":"substantief","meanings":[{"de":"der Lohn","ex":"Het loon komt elke week op tijd.","exDe":"Der Lohn kommt jede Woche pünktlich."},{"de":"der Verdienst, das Entgelt","ex":"De lonen zijn dit jaar gestegen.","exDe":"Die Löhne sind dieses Jahr gestiegen."},{"de":"die Belohnung, der verdiente Lohn (übertragen)","ex":"Dat is het loon voor al haar harde werk.","exDe":"Das ist der Lohn für all ihre harte Arbeit."}],"usage":"Konkreter Lohn oft im Plural 'lonen'. Redewendung: loon naar werken (gerechter Lohn für Arbeit).","genus":"het","plural":"lonen"},"bk_849":{"lemma":"werkgever","displayNl":"de werkgever","pos":"substantief","meanings":[{"de":"der Arbeitgeber","ex":"Mijn werkgever is eerlijk en behulpzaam.","exDe":"Mein Arbeitgeber ist fair und hilfsbereit."},{"de":"die Arbeitgeberin","ex":"Zij is een goede werkgever voor haar personeel.","exDe":"Sie ist eine gute Arbeitgeberin für ihr Personal."}],"usage":"Gegenstück zu 'werknemer' (Arbeitnehmer). Gilt für Personen wie Firmen.","genus":"de","plural":"werkgevers"},"bk_850":{"lemma":"werknemer","displayNl":"de werknemer","pos":"substantief","meanings":[{"de":"der Arbeitnehmer","ex":"Elke werknemer krijgt loon voor zijn werk.","exDe":"Jeder Arbeitnehmer bekommt Lohn für seine Arbeit."},{"de":"der/die Angestellte, die Arbeitnehmerin","ex":"De werknemers staken voor betere arbeidsvoorwaarden.","exDe":"Die Angestellten streiken für bessere Arbeitsbedingungen."}],"usage":"Gegenstück zu 'werkgever' (Arbeitgeber). Formeller Oberbegriff für Beschäftigte.","genus":"de","plural":"werknemers"},"bk_851":{"lemma":"medewerker","displayNl":"de medewerker","pos":"substantief","meanings":[{"de":"der Mitarbeiter, die Mitarbeiterin","ex":"De nieuwe medewerker begint maandag.","exDe":"Der neue Mitarbeiter fängt am Montag an."},{"de":"der/die Angestellte (im Betrieb)","ex":"Alle medewerkers krijgen een training.","exDe":"Alle Angestellten bekommen eine Schulung."},{"de":"der/die Mitwirkende (an etwas)","ex":"Hij is medewerker aan het onderzoeksproject.","exDe":"Er ist Mitwirkender an dem Forschungsprojekt."}],"usage":"Alltagsnäher als 'werknemer'; oft in Zusammensetzungen wie baliemedewerker (Schaltermitarbeiter).","genus":"de","plural":"medewerkers"},"bk_852":{"lemma":"afdeling","displayNl":"de afdeling","pos":"substantief","meanings":[{"de":"die Abteilung (Firma, Behörde, Kaufhaus)","ex":"Ik werk op de afdeling verkoop.","exDe":"Ich arbeite in der Verkaufsabteilung."},{"de":"die Station (Krankenhaus)","ex":"Hij ligt op de afdeling cardiologie.","exDe":"Er liegt auf der Station für Kardiologie."},{"de":"der Bereich, der Abschnitt","ex":"De afdeling groente vind je achterin.","exDe":"Den Gemüsebereich findest du hinten."}],"usage":"Meist mit voorzetsel 'op' (op de afdeling) für Arbeit/Station.","genus":"de","plural":"afdelingen"},"bk_853":{"lemma":"vergoeding","displayNl":"de vergoeding","pos":"substantief","meanings":[{"de":"die Vergütung, die Entschädigung","ex":"Voor dit werk krijg je een kleine vergoeding.","exDe":"Für diese Arbeit bekommst du eine kleine Vergütung."},{"de":"die Erstattung (von Kosten)","ex":"Ik heb een vergoeding voor de reiskosten aangevraagd.","exDe":"Ich habe eine Erstattung der Reisekosten beantragt."}],"usage":"Oft 'een vergoeding voor iets' oder 'reiskostenvergoeding'.","genus":"de","plural":"vergoedingen"},"bk_854":{"lemma":"vakantie","displayNl":"de vakantie","pos":"substantief","meanings":[{"de":"der Urlaub","ex":"Volgende week ga ik met vakantie naar Spanje.","exDe":"Nächste Woche fahre ich in den Urlaub nach Spanien."},{"de":"die Ferien (Schule)","ex":"De kinderen hebben nu zomervakantie.","exDe":"Die Kinder haben jetzt Sommerferien."}],"usage":"'met vakantie gaan' = in Urlaub fahren; 'vakantie opnemen' = Urlaub nehmen.","genus":"de","plural":"vakanties","illustratable":true},"bk_855":{"lemma":"verlof","displayNl":"het verlof","pos":"substantief","meanings":[{"de":"der (Sonder-)Urlaub, die Freistellung (von der Arbeit)","ex":"Zij is met verlof na de geboorte van haar kind.","exDe":"Sie ist in Elternzeit nach der Geburt ihres Kindes."},{"de":"die Erlaubnis, die Genehmigung (formell)","ex":"Hij kreeg verlof om eerder te vertrekken.","exDe":"Er bekam die Erlaubnis, früher zu gehen."}],"usage":"Genus KORRIGIERT: het verlof (nicht 'de'). 'met verlof zijn' = beurlaubt/freigestellt sein; 'verlof aanvragen' = Urlaub beantragen.","genus":"het","plural":"verloven"},"bk_856":{"lemma":"overuur","displayNl":"het overuur","pos":"substantief","meanings":[{"de":"die Überstunde","ex":"Deze maand heb ik veel overuren gemaakt.","exDe":"Diesen Monat habe ich viele Überstunden gemacht."}],"usage":"Fast immer im Plural 'overuren'; feste Wendung 'overuren maken' = Überstunden machen. Singular 'overuur' existiert, ist aber selten.","genus":"het","plural":"overuren"},"bk_857":{"lemma":"rooster","displayNl":"het rooster","pos":"substantief","meanings":[{"de":"der Dienstplan, der Stundenplan","ex":"Het rooster voor volgende week hangt aan de muur.","exDe":"Der Dienstplan für nächste Woche hängt an der Wand."},{"de":"das Gitter, der Rost (z. B. Gitterrost)","ex":"Leg de worst op het rooster van de barbecue.","exDe":"Leg die Wurst auf den Rost des Grills."}],"usage":"Zwei getrennte Bedeutungen: Zeitplan und Gitter/Rost.","genus":"het","plural":"roosters","illustratable":true},"bk_858":{"lemma":"dienst","displayNl":"de dienst","pos":"substantief","meanings":[{"de":"die Schicht (Arbeit)","ex":"Ik heb vanavond een late dienst.","exDe":"Ich habe heute Abend eine späte Schicht."},{"de":"der Dienst, die Dienstleistung","ex":"Dit bedrijf levert goede diensten.","exDe":"Dieses Unternehmen bietet gute Dienstleistungen."},{"de":"der Gottesdienst","ex":"De dienst in de kerk begint om tien uur.","exDe":"Der Gottesdienst in der Kirche beginnt um zehn Uhr."},{"de":"das Amt, die Behörde","ex":"Hij werkt bij de gemeentelijke dienst.","exDe":"Er arbeitet beim städtischen Amt."}],"usage":"Vielseitig: Schicht, Dienstleistung, Gottesdienst, Behörde. Wendung 'dienst hebben' = Dienst/Schicht haben.","genus":"de","plural":"diensten"},"bk_860":{"lemma":"werkplek","displayNl":"de werkplek","pos":"substantief","meanings":[{"de":"der Arbeitsplatz","ex":"Mijn werkplek is altijd netjes opgeruimd.","exDe":"Mein Arbeitsplatz ist immer ordentlich aufgeräumt."}],"usage":"Konkreter Arbeitsplatz (Ort/Schreibtisch); der Betrieb als Ganzes ist eher 'werk' oder 'werkgever'.","genus":"de","plural":"werkplekken","illustratable":true},"bk_861":{"lemma":"printer","displayNl":"de printer","pos":"substantief","meanings":[{"de":"der Drucker","ex":"De printer is kapot.","exDe":"Der Drucker ist kaputt."}],"usage":"Gerät zum Ausdrucken von Dokumenten; alltäglich im Büro und zu Hause.","genus":"de","plural":"printers","illustratable":true},"bk_862":{"lemma":"printen","displayNl":"printen","pos":"werkwoord","meanings":[{"de":"drucken, ausdrucken","ex":"Ik print het rapport.","exDe":"Ich drucke den Bericht."}],"usage":"Regelmäßiges Verb; etwas per Drucker auf Papier ausgeben. Umgangssprachlich neben 'afdrukken'.","conjugation":{"presens":{"ik":"print","jij":"print","hij":"print","wij":"printen"},"imperfectum":{"ik":"printte","wij":"printten"},"perfectum":{"aux":"hebben","participle":"geprint"}},"illustratable":true},"bk_863":{"lemma":"rapport","displayNl":"het rapport","pos":"substantief","meanings":[{"de":"der Bericht, der Report","ex":"Het rapport is klaar.","exDe":"Der Bericht ist fertig."},{"de":"das (Schul-)Zeugnis","ex":"Mijn dochter kreeg vandaag haar rapport.","exDe":"Meine Tochter bekam heute ihr Zeugnis."}],"usage":"Schriftliche Darstellung von Ergebnissen; in der Schule auch das Zeugnis mit Noten.","genus":"het","plural":"rapporten","illustratable":true},"bk_864":{"lemma":"document","displayNl":"het document","pos":"substantief","meanings":[{"de":"das Dokument, die Urkunde","ex":"Open het document.","exDe":"Öffne das Dokument."}],"usage":"Schriftstück oder Datei mit Inhalt; sowohl auf Papier als auch digital.","genus":"het","plural":"documenten","illustratable":true},"bk_865":{"lemma":"map","displayNl":"de map","pos":"substantief","meanings":[{"de":"der Ordner, die Mappe (zum Abheften)","ex":"Leg het in de map.","exDe":"Leg es in den Ordner."},{"de":"der Ordner, das Verzeichnis (am Computer)","ex":"Het bestand staat in de verkeerde map.","exDe":"Die Datei liegt im falschen Ordner."}],"usage":"Behälter zum Ordnen von Papieren; im Computer der Ordner/das Verzeichnis. Nicht 'Landkarte' (das ist 'kaart').","genus":"de","plural":"mappen","illustratable":true},"bk_866":{"lemma":"bestand","displayNl":"het bestand","pos":"substantief","meanings":[{"de":"die Datei","ex":"Ik stuur het bestand.","exDe":"Ich schicke die Datei."},{"de":"der Bestand (Menge, z. B. an Bäumen/Tieren)","ex":"Het bomenbestand in de stad groeit.","exDe":"Der Baumbestand in der Stadt wächst."}],"usage":"Meist digitale Datei; daneben auch 'Bestand' im Sinne eines Vorrats oder einer Population.","genus":"het","plural":"bestanden"},"bk_867":{"lemma":"opslaan","displayNl":"opslaan","pos":"werkwoord","meanings":[{"de":"speichern (Daten)","ex":"Vergeet niet op te slaan.","exDe":"Vergiss nicht zu speichern."},{"de":"aufbewahren, lagern, einlagern","ex":"We slaan de dozen op in de kelder.","exDe":"Wir lagern die Kartons im Keller ein."}],"usage":"Trennbares Verb (op + slaan). Zentral im Computer-Kontext für 'speichern', daneben 'lagern/aufbewahren'.","conjugation":{"presens":{"ik":"sla op","jij":"slaat op","hij":"slaat op","wij":"slaan op"},"imperfectum":{"ik":"sloeg op","wij":"sloegen op"},"perfectum":{"aux":"hebben","participle":"opgeslagen"}}},"bk_868":{"lemma":"versturen","displayNl":"versturen","pos":"werkwoord","meanings":[{"de":"senden, verschicken, abschicken","ex":"Ik verstuur de mail nu.","exDe":"Ich sende die Mail jetzt."}],"usage":"Etwas (Brief, Mail, Paket) auf den Weg bringen; Partizip 'verstuurd'.","conjugation":{"presens":{"ik":"verstuur","jij":"verstuurt","hij":"verstuurt","wij":"versturen"},"imperfectum":{"ik":"verstuurde","wij":"verstuurden"},"perfectum":{"aux":"hebben","participle":"verstuurd"}}},"bk_869":{"lemma":"agenda","displayNl":"de agenda","pos":"substantief","meanings":[{"de":"der Terminkalender, das Terminplanerbuch","ex":"Het staat in mijn agenda.","exDe":"Es steht in meinem Kalender."},{"de":"die Tagesordnung, die Agenda","ex":"Dit punt staat niet op de agenda.","exDe":"Dieser Punkt steht nicht auf der Tagesordnung."}],"usage":"Alltäglich für den persönlichen Terminplaner (Papier oder App); im übertragenen Sinn auch Tagesordnung einer Besprechung.","genus":"de","plural":"agenda's","illustratable":true},"bk_870":{"lemma":"plannen","displayNl":"plannen","pos":"werkwoord","meanings":[{"de":"planen, verabreden, terminieren","ex":"We plannen een afspraak voor volgende week.","exDe":"Wir planen einen Termin für nächste Woche."},{"de":"(zeitlich) einplanen, ansetzen","ex":"De vergadering is op vrijdag gepland.","exDe":"Die Besprechung ist für Freitag angesetzt."}],"usage":"Regelmäßiges Verb; typisch für das Festlegen von Terminen und Vorhaben. Nicht mit dem Substantiv 'de plannen' (Plural von 'plan') verwechseln.","conjugation":{"presens":{"ik":"plan","jij":"plant","hij":"plant","wij":"plannen"},"imperfectum":{"ik":"plande","wij":"planden"},"perfectum":{"aux":"hebben","participle":"gepland"}}},"bk_871":{"lemma":"regelen","displayNl":"regelen","pos":"werkwoord","meanings":[{"de":"regeln, erledigen, in Ordnung bringen","ex":"Ik regel het vandaag.","exDe":"Ich regle das heute."},{"de":"organisieren, arrangieren, besorgen","ex":"Kun jij de kaartjes regelen?","exDe":"Kannst du die Tickets besorgen?"}],"usage":"Sehr gebräuchliches Alltagsverb für 'etwas erledigen/organisieren'; regelmäßig konjugiert.","conjugation":{"presens":{"ik":"regel","jij":"regelt","hij":"regelt","wij":"regelen"},"imperfectum":{"ik":"regelde","wij":"regelden"},"perfectum":{"aux":"hebben","participle":"geregeld"}}},"bk_872":{"lemma":"organiseren","displayNl":"organiseren","pos":"werkwoord","meanings":[{"de":"organisieren, veranstalten","ex":"Zij organiseert de dag.","exDe":"Sie organisiert den Tag."},{"de":"ordnen, einrichten, arrangieren","ex":"Ik moet mijn bureau beter organiseren.","exDe":"Ich muss meinen Schreibtisch besser ordnen."}],"usage":"Regelmäßiges Verb auf -eren; Partizip ohne 'ge-' Präfix am Wortanfang, aber mit 'ge-' insgesamt: georganiseerd.","conjugation":{"presens":{"ik":"organiseer","jij":"organiseert","hij":"organiseert","wij":"organiseren"},"imperfectum":{"ik":"organiseerde","wij":"organiseerden"},"perfectum":{"aux":"hebben","participle":"georganiseerd"}}},"bk_873":{"lemma":"opleiding","displayNl":"de opleiding","pos":"substantief","meanings":[{"de":"die Ausbildung, der Ausbildungsgang","ex":"Ik volg een opleiding tot verpleegkundige.","exDe":"Ich mache eine Ausbildung zur Krankenpflegerin."},{"de":"die (Aus-)Bildung, der Studiengang","ex":"Welke opleiding heb je gedaan?","exDe":"Welchen Bildungsgang hast du absolviert?"}],"usage":"Oberbegriff für formale Ausbildungs- und Studiengänge; man 'volgt' oder 'doet' een opleiding.","genus":"de","plural":"opleidingen"},"bk_874":{"lemma":"cursus","displayNl":"de cursus","pos":"substantief","meanings":[{"de":"der Kurs, der Lehrgang","ex":"De cursus begint maandag.","exDe":"Der Kurs beginnt am Montag."},{"de":"das Kursmaterial, das Lehrheft (belgisches Niederländisch)","ex":"Ik heb mijn cursus thuis laten liggen.","exDe":"Ich habe mein Kursheft zu Hause liegen lassen."}],"usage":"Ein zeitlich begrenzter Lehrgang; man 'volgt' een cursus. In Belgien auch das Skript/Lehrheft.","genus":"de","plural":"cursussen","illustratable":true},"bk_875":{"lemma":"ervaring","displayNl":"de ervaring","pos":"substantief","meanings":[{"de":"die Erfahrung (angesammeltes Können/Wissen)","ex":"Ik heb veel ervaring in de zorg.","exDe":"Ich habe viel Erfahrung in der Pflege."},{"de":"das Erlebnis, die (einzelne) Erfahrung","ex":"Dat was een bijzondere ervaring.","exDe":"Das war ein besonderes Erlebnis."}],"usage":"Im Singular oft unzählbar (Berufserfahrung); im Plural 'ervaringen' für einzelne Erlebnisse.","genus":"de","plural":"ervaringen"},"bk_876":{"lemma":"vaardigheid","displayNl":"de vaardigheid","pos":"substantief","meanings":[{"de":"die Fähigkeit, die Fertigkeit","ex":"Dit is een nuttige vaardigheid.","exDe":"Das ist eine nützliche Fähigkeit."},{"de":"das Geschick, die Gewandtheit","ex":"Hij hanteert het gereedschap met grote vaardigheid.","exDe":"Er handhabt das Werkzeug mit großem Geschick."}],"usage":"Bezeichnet erlernbares Können; Plural 'vaardigheden' häufig für Kompetenzen (z. B. sociale vaardigheden).","genus":"de","plural":"vaardigheden"},"bk_877":{"lemma":"functie","displayNl":"de functie","pos":"substantief","meanings":[{"de":"die Position, die Stelle, das Amt","ex":"Zij heeft een nieuwe functie bij de bank.","exDe":"Sie hat eine neue Position bei der Bank."},{"de":"die Funktion, die Aufgabe, der Zweck","ex":"Deze knop heeft een belangrijke functie.","exDe":"Dieser Knopf hat eine wichtige Funktion."}],"usage":"Häufiges A2-Wort. Bedeutung 1 = berufliche Stelle/Position; Bedeutung 2 = technische/mathematische Funktion oder allgemeiner Zweck.","genus":"de","plural":"functies","notes":"Abstraktes Nomen, nicht bildlich eindeutig."},"bk_878":{"lemma":"manager","displayNl":"de manager","pos":"substantief","meanings":[{"de":"der Manager, die Führungskraft, der/die Vorgesetzte","ex":"De manager van ons team is streng maar eerlijk.","exDe":"Der Manager unseres Teams ist streng, aber fair."}],"usage":"Aus dem Englischen entlehnt, Plural auf -s. Weibliche Form oft ebenfalls 'manager'; gängig auch 'managerin'.","genus":"de","plural":"managers","notes":"Bürorolle ohne eindeutiges Bildmotiv (visuell kaum von directeur zu unterscheiden)."},"bk_879":{"lemma":"directeur","displayNl":"de directeur","pos":"substantief","meanings":[{"de":"der Direktor, der Geschäftsführer, der Leiter","ex":"De directeur houdt een praatje voor het personeel.","exDe":"Der Direktor hält eine kurze Rede für das Personal."},{"de":"der Schulleiter, der Rektor","ex":"De directeur van de school ontvangt de nieuwe leerlingen.","exDe":"Der Schulleiter der Schule empfängt die neuen Schüler."}],"usage":"Betonung auf letzter Silbe (directéúr). Plural auch 'directeurs'. Weibliche Form: 'directrice'.","genus":"de","plural":"directeuren","illustratable":true},"bk_880":{"lemma":"secretaresse","displayNl":"de secretaresse","pos":"substantief","meanings":[{"de":"die Sekretärin, die Assistentin","ex":"De secretaresse neemt de telefoon op en verbindt me door.","exDe":"Die Sekretärin geht ans Telefon und verbindet mich weiter."}],"usage":"Weibliche Form. Männlich/neutral: 'secretaris' (auch für Amtsträger). Betonung auf 'res' (secretarésse).","genus":"de","plural":"secretaresses","illustratable":true},"bk_881":{"lemma":"verkoper","displayNl":"de verkoper","pos":"substantief","meanings":[{"de":"der Verkäufer, der Ladenverkäufer","ex":"De verkoper helpt de klant met de juiste maat.","exDe":"Der Verkäufer hilft dem Kunden mit der richtigen Größe."},{"de":"der Verkäufer (Anbieter/Veräußerer bei einem Verkauf)","ex":"De verkoper van het huis vraagt een hoge prijs.","exDe":"Der Verkäufer des Hauses verlangt einen hohen Preis."}],"usage":"Weibliche Form: 'verkoopster' oder 'verkoper'. Plural 'verkopers'.","genus":"de","plural":"verkopers","illustratable":true},"bk_882":{"lemma":"ingenieur","displayNl":"de ingenieur","pos":"substantief","meanings":[{"de":"der Ingenieur","ex":"Hij is ingenieur en ontwerpt bruggen.","exDe":"Er ist Ingenieur und entwirft Brücken."}],"usage":"Aus dem Französischen, Betonung auf letzter Silbe. Bei Berufsangabe ohne Artikel: 'Hij is ingenieur.'","genus":"de","plural":"ingenieurs","illustratable":true},"bk_883":{"lemma":"monteur","displayNl":"de monteur","pos":"substantief","meanings":[{"de":"der Mechaniker, der Monteur, der Automechaniker","ex":"De monteur maakt de auto in de garage.","exDe":"Der Mechaniker repariert das Auto in der Werkstatt."}],"usage":"Betonung auf letzter Silbe (montéúr). Auch für Installateure/Techniker verschiedener Fachrichtungen.","genus":"de","plural":"monteurs","illustratable":true},"bk_884":{"lemma":"kapper","displayNl":"de kapper","pos":"substantief","meanings":[{"de":"der Friseur, der Frisör","ex":"De kapper knipt mijn haar heel kort.","exDe":"Der Friseur schneidet mir die Haare ganz kurz."},{"de":"der Friseursalon, das Frisörgeschäft (Ort)","ex":"Ik ga vanmiddag naar de kapper.","exDe":"Ich gehe heute Nachmittag zum Friseur."}],"usage":"Bezeichnet sowohl die Person als auch den Salon ('naar de kapper gaan'). Weibliche Form: 'kapster'.","genus":"de","plural":"kappers","illustratable":true},"bk_886":{"lemma":"timmerman","displayNl":"de timmerman","pos":"substantief","meanings":[{"de":"der Tischler, der Zimmermann","ex":"De timmerman maakt een kast van eikenhout.","exDe":"Der Tischler baut einen Schrank aus Eichenholz."},{"de":"der Schreiner (Handwerker, der mit Holz arbeitet)","ex":"We hebben een timmerman nodig voor de nieuwe trap.","exDe":"Wir brauchen einen Schreiner für die neue Treppe."}],"usage":"Nebenform des Plurals: timmermannen. Berufsbezeichnung für einen Holzhandwerker.","genus":"de","plural":"timmerlieden","illustratable":true},"bk_887":{"lemma":"loodgieter","displayNl":"de loodgieter","pos":"substantief","meanings":[{"de":"der Klempner, der Installateur","ex":"De loodgieter komt morgen de kraan repareren.","exDe":"Der Klempner kommt morgen den Wasserhahn reparieren."},{"de":"der Sanitaerinstallateur (für Wasser- und Abflussleitungen)","ex":"De loodgieter vervangt de lekkende buis.","exDe":"Der Installateur ersetzt das leckende Rohr."}],"usage":"Handwerker für Wasserleitungen, Abfluesse und Sanitaeranlagen.","genus":"de","plural":"loodgieters","illustratable":true},"bk_888":{"lemma":"advocaat","displayNl":"de advocaat","pos":"substantief","meanings":[{"de":"der Anwalt, die Anwaeltin, der Rechtsanwalt","ex":"Zij is advocaat bij een groot kantoor.","exDe":"Sie ist Anwaeltin in einer grossen Kanzlei."},{"de":"der Advocaat (niederlaendischer cremiger Eierlikoer)","ex":"Bij de verjaardag dronken we advocaat met slagroom.","exDe":"Beim Geburtstag tranken wir Advocaat mit Schlagsahne."}],"usage":"Homonym: Beruf (Jurist) und ein cremiger niederlaendischer Eierlikoer. Plural für den Beruf: advocaten.","genus":"de","plural":"advocaten","illustratable":true},"bk_889":{"lemma":"boekhouder","displayNl":"de boekhouder","pos":"substantief","meanings":[{"de":"der Buchhalter, die Buchhalterin","ex":"De boekhouder telt het geld en controleert de rekeningen.","exDe":"Der Buchhalter zaehlt das Geld und prueft die Rechnungen."},{"de":"der Rechnungsfuehrer (verantwortlich für die Finanzverwaltung)","ex":"Onze boekhouder verzorgt de belastingaangifte.","exDe":"Unser Rechnungsfuehrer erledigt die Steuererklaerung."}],"usage":"Berufsbezeichnung für jemanden, der die Finanzen und Buecher eines Betriebs fuehrt.","genus":"de","plural":"boekhouders","illustratable":true},"bk_890":{"lemma":"kassa","displayNl":"de kassa","pos":"substantief","meanings":[{"de":"die Kasse (Zahlstelle im Geschaeft)","ex":"Betaal alsjeblieft bij de kassa.","exDe":"Bitte bezahl an der Kasse."},{"de":"die Registrierkasse (Geraet)","ex":"De kassa piept bij elk product.","exDe":"Die Registrierkasse piept bei jedem Produkt."}],"usage":"Bezeichnet die Zahlstelle im Laden und das Kassengeraet selbst. Plural mit Apostroph: kassa's.","genus":"de","plural":"kassa's","illustratable":true},"bk_891":{"lemma":"fabriek","displayNl":"de fabriek","pos":"substantief","meanings":[{"de":"die Fabrik, das Werk","ex":"Hij werkt in een grote fabriek buiten de stad.","exDe":"Er arbeitet in einer grossen Fabrik ausserhalb der Stadt."},{"de":"der Produktionsbetrieb (Ort industrieller Herstellung)","ex":"De fabriek maakt duizenden fietsen per week.","exDe":"Der Produktionsbetrieb stellt Tausende Fahrräder pro Woche her."}],"usage":"Ort industrieller Produktion. Plural: fabrieken.","genus":"de","plural":"fabrieken","illustratable":true},"bk_892":{"lemma":"machine","displayNl":"de machine","pos":"substantief","meanings":[{"de":"die Maschine (technisches Geraet)","ex":"De machine in de fabriek staat stil.","exDe":"Die Maschine in der Fabrik steht still."},{"de":"das Geraet, der Apparat (Waschmaschine, Kaffeemaschine u. Ae.)","ex":"Zet je vuile kleren in de machine.","exDe":"Steck deine schmutzige Waesche in die Maschine."}],"usage":"Allgemein technisches Geraet; im Alltag oft kurz für Wasch- oder Kaffeemaschine. Plural: machines.","genus":"de","plural":"machines","illustratable":true},"bk_893":{"lemma":"gereedschap","displayNl":"het gereedschap","pos":"substantief","meanings":[{"de":"das Werkzeug","ex":"Ik heb gereedschap nodig om de kast te maken.","exDe":"Ich brauche Werkzeug, um den Schrank zu bauen."},{"de":"das Handwerkszeug, die Geraetschaft (Gesamtheit der Arbeitsgeraete)","ex":"Berg je gereedschap netjes op in de kist.","exDe":"Raeume dein Handwerkszeug ordentlich in den Kasten."}],"usage":"Meist als Kollektivum (unzaehlbar) gebraucht; Plural gereedschappen bezeichnet verschiedene Werkzeugarten.","genus":"het","plural":"gereedschappen","illustratable":true},"bk_1049":{"lemma":"vijver","displayNl":"de vijver","pos":"substantief","meanings":[{"de":"der Teich","ex":"In de vijver zwemmen vissen.","exDe":"Im Teich schwimmen Fische."},{"de":"das (Zier-)Wasserbecken, der Weiher","ex":"In de tuin ligt een kleine vijver met waterlelies.","exDe":"Im Garten liegt ein kleiner Teich mit Seerosen."}],"usage":"Stehendes, meist künstlich angelegtes Gewässer (Garten, Park). Größeres Naturgewässer eher 'meer' oder 'plas'.","genus":"de","plural":"vijvers","illustratable":true},"bk_1050":{"lemma":"sloot","displayNl":"de sloot","pos":"substantief","meanings":[{"de":"der Graben, der Wassergraben","ex":"Langs het veld ligt een sloot.","exDe":"Am Feld entlang liegt ein Graben."},{"de":"(umgangssprachlich) eine große Menge (z. B. Geld)","ex":"Dat heeft een sloot geld gekost.","exDe":"Das hat einen Haufen Geld gekostet."}],"usage":"Schmaler, wassergefüllter Entwässerungsgraben, typisch für die niederländische Polderlandschaft. Übertragen 'een sloot ...' = sehr viel.","genus":"de","plural":"sloten","illustratable":true},"bk_1051":{"lemma":"modder","displayNl":"de modder","pos":"substantief","meanings":[{"de":"der Schlamm, der Matsch","ex":"Mijn schönen zitten vol modder.","exDe":"Meine Schuhe sind voller Schlamm."}],"usage":"Unzählbares Stoffwort, kein regulärer Plural. Nasse, weiche Mischung aus Erde und Wasser.","genus":"de","illustratable":true},"bk_1052":{"lemma":"klei","displayNl":"de klei","pos":"substantief","meanings":[{"de":"der Lehm, der Ton","ex":"De grond hier bestaat uit klei.","exDe":"Der Boden hier besteht aus Lehm."},{"de":"der Ton (Werkstoff zum Formen/Töpfern)","ex":"De kinderen kneden figuurtjes van klei.","exDe":"Die Kinder kneten Figürchen aus Ton."}],"usage":"Unzählbares Stoffwort, kein regulärer Plural. Feinkörniger, formbarer Boden bzw. Töpferwerkstoff.","genus":"de","illustratable":true},"bk_1053":{"lemma":"rots","displayNl":"de rots","pos":"substantief","meanings":[{"de":"der Fels, der Felsen","ex":"De vogel zit op een rots.","exDe":"Der Vogel sitzt auf einem Felsen."},{"de":"(bildlich) verlässlicher Halt, 'Fels in der Brandung'","ex":"Ze is een rots in de branding voor haar gezin.","exDe":"Sie ist ein Fels in der Brandung für ihre Familie."}],"usage":"Große, feste Gesteinsformation. Übertragen für jemanden, der Halt und Ruhe gibt.","genus":"de","plural":"rotsen","illustratable":true},"bk_1054":{"lemma":"metaal","displayNl":"het metaal","pos":"substantief","meanings":[{"de":"das Metall","ex":"Deze brug is van metaal.","exDe":"Diese Brücke ist aus Metall."}],"usage":"Werkstoff bzw. chemisches Material. Plural 'metalen' für verschiedene Metallsorten.","genus":"het","plural":"metalen","illustratable":true},"bk_1055":{"lemma":"hout","displayNl":"het hout","pos":"substantief","meanings":[{"de":"das Holz","ex":"De tafel is van hout.","exDe":"Der Tisch ist aus Holz."}],"usage":"Unzählbares Stoffwort für das Material Holz; kein regulärer Plural (Sorten: 'houtsoorten'). Nicht mit dem Adjektiv 'houten' (hölzern) verwechseln.","genus":"het","illustratable":true},"bk_1056":{"lemma":"ijzer","displayNl":"het ijzer","pos":"substantief","meanings":[{"de":"das Eisen (Metall/Werkstoff)","ex":"Het hek is van ijzer.","exDe":"Der Zaun ist aus Eisen."},{"de":"das Eisen (Gerät, z. B. Schlittschuhkufe, Golfschläger)","ex":"Hij bindt de ijzers onder zijn schaatsen.","exDe":"Er schnallt sich die Kufen unter die Schlittschuhe."}],"usage":"Als Werkstoff unzählbar; im Sinne von Gerät/Kufe zählbar mit Plural 'ijzers'. Redewendung: 'het ijzer smeden als het heet is'.","genus":"het","plural":"ijzers","illustratable":true},"bk_1057":{"lemma":"goud","displayNl":"het goud","pos":"substantief","meanings":[{"de":"das Gold (Edelmetall)","ex":"De ring is van goud.","exDe":"Der Ring ist aus Gold."},{"de":"das Gold, die Goldmedaille (erster Platz)","ex":"Ze won goud op de Olympische Spelen.","exDe":"Sie gewann Gold bei den Olympischen Spielen."}],"usage":"Stoffnamen/Massenname, meist ohne Plural; 'van goud' = aus Gold.","genus":"het","illustratable":true},"bk_1058":{"lemma":"zilver","displayNl":"het zilver","pos":"substantief","meanings":[{"de":"das Silber (Edelmetall)","ex":"De lepel is van zilver.","exDe":"Der Löffel ist aus Silber."},{"de":"das Silber, das Tafelsilber (Besteck/Geschirr)","ex":"Ze poetste het zilver voor het feest.","exDe":"Sie polierte das Silber für die Feier."},{"de":"das Silber, die Silbermedaille (zweiter Platz)","ex":"Hij behaalde zilver in de finale.","exDe":"Er holte Silber im Finale."}],"usage":"Stoffnamen/Massenname, meist ohne Plural; 'van zilver' = aus Silber.","genus":"het","illustratable":true},"bk_1059":{"lemma":"natuur","displayNl":"de natuur","pos":"substantief","meanings":[{"de":"die Natur (natürliche Umwelt)","ex":"Ik hou van de natuur.","exDe":"Ich liebe die Natur."},{"de":"die Natur, das Wesen, die Veranlagung (Charakter)","ex":"Hij is van nature een rustig mens.","exDe":"Er ist von Natur aus ein ruhiger Mensch."}],"usage":"In der Bedeutung 'natürliche Umwelt' meist ohne Plural; feste Wendung 'van nature' = von Natur aus.","genus":"de","illustratable":true},"bk_1060":{"lemma":"landschap","displayNl":"het landschap","pos":"substantief","meanings":[{"de":"die Landschaft (Gegend, Ausblick)","ex":"Het landschap is prachtig.","exDe":"Die Landschaft ist wunderschön."},{"de":"das Landschaftsbild, die Landschaftsmalerei (Gemäldegenre)","ex":"In het museum hangen veel oude landschappen.","exDe":"Im Museum hängen viele alte Landschaftsbilder."}],"usage":"Plural 'landschappen'; verwandt mit 'natuur', aber betont den sichtbaren Ausblick/die Gegend.","genus":"het","plural":"landschappen","illustratable":true},"bk_1061":{"lemma":"milieu","displayNl":"het milieu","pos":"substantief","meanings":[{"de":"die Umwelt (natürliche Lebensumwelt)","ex":"We moeten het milieu beschermen.","exDe":"Wir müssen die Umwelt schützen."},{"de":"das Milieu, das soziale Umfeld","ex":"Ze komt uit een arbeidersmilieu.","exDe":"Sie kommt aus einem Arbeitermilieu."}],"usage":"In der ökologischen Bedeutung meist ohne Plural mit Artikel 'het milieu'; Plural 'milieus' eher im sozialen Sinn.","genus":"het","plural":"milieus"},"bk_1062":{"lemma":"klimaat","displayNl":"het klimaat","pos":"substantief","meanings":[{"de":"das Klima (Wetterverhältnisse über lange Zeit)","ex":"Het klimaat verandert langzaam.","exDe":"Das Klima verändert sich langsam."},{"de":"das Klima, die Stimmung, die Atmosphäre (übertragen)","ex":"Er heerst een gespannen politiek klimaat.","exDe":"Es herrscht ein angespanntes politisches Klima."}],"usage":"Plural 'klimaten'; abstrakter Begriff, nicht mit dem konkreten 'weer' (Wetter) zu verwechseln.","genus":"het","plural":"klimaten"},"bk_1063":{"lemma":"vervuiling","displayNl":"de vervuiling","pos":"substantief","meanings":[{"de":"die Verschmutzung, die Umweltverschmutzung","ex":"De vervuiling van de lucht is een probleem.","exDe":"Die Luftverschmutzung ist ein Problem."}],"usage":"Abstraktes Nomen zum Verb 'vervuilen'; Plural 'vervuilingen' selten; oft in Zusammensetzungen wie 'luchtvervuiling'.","genus":"de","plural":"vervuilingen"},"bk_1064":{"lemma":"zonne-energie","displayNl":"de zonne-energie","pos":"substantief","meanings":[{"de":"die Solarenergie, die Sonnenenergie","ex":"We gebruiken zonne-energie thuis.","exDe":"Wir nutzen zu Hause Solarenergie."}],"usage":"Massenname, ohne Plural; Bindestrich-Schreibung wegen der Vokalfolge 'e-e'.","genus":"de","illustratable":true},"bk_1065":{"lemma":"weerbericht","displayNl":"het weerbericht","pos":"substantief","meanings":[{"de":"der Wetterbericht, die Wettervorhersage","ex":"Ik kijk elke dag naar het weerbericht.","exDe":"Ich schaue mir jeden Tag den Wetterbericht an."},{"de":"die Wettermeldung (im Radio/Fernsehen)","ex":"Volgens het weerbericht gaat het morgen regenen.","exDe":"Laut Wetterbericht regnet es morgen."}],"usage":"Sächliches Substantiv, Plural 'weerberichten'. Oft mit 'naar het weerbericht kijken/luisteren'.","genus":"het","plural":"weerberichten","illustratable":true},"bk_1066":{"lemma":"bewolkt","displayNl":"bewolkt","pos":"adjectief","meanings":[{"de":"bewölkt, bedeckt","ex":"Vandaag is het bewolkt en grijs.","exDe":"Heute ist es bewölkt und grau."},{"de":"wolkig, mit Wolken bedeckt (Himmel)","ex":"De hemel was de hele dag zwaar bewolkt.","exDe":"Der Himmel war den ganzen Tag stark bewölkt."}],"usage":"Adjektiv, meist unveränderlich im Wetterkontext ('het is bewolkt').","illustratable":true},"bk_1067":{"lemma":"zonnig","displayNl":"zonnig","pos":"adjectief","meanings":[{"de":"sonnig","ex":"Morgen wordt het zonnig en warm.","exDe":"Morgen wird es sonnig und warm."},{"de":"heiter, fröhlich, sonnig (Wesen)","ex":"Ze heeft een zonnig karakter.","exDe":"Sie hat ein sonniges Gemüt."}],"usage":"Adjektiv; wörtlich (Wetter) und übertragen (Charakter/Stimmung).","illustratable":true},"bk_1068":{"lemma":"winderig","displayNl":"winderig","pos":"adjectief","meanings":[{"de":"windig","ex":"Aan zee is het vaak winderig.","exDe":"Am Meer ist es oft windig."},{"de":"stürmisch, böig (Wetter)","ex":"Het was een grijze, winderige dag.","exDe":"Es war ein grauer, windiger Tag."}],"usage":"Adjektiv, überwiegend im Wetterkontext.","illustratable":true},"bk_1069":{"lemma":"mistig","displayNl":"mistig","pos":"adjectief","meanings":[{"de":"neblig, dunstig","ex":"In de herfst is het vaak mistig.","exDe":"Im Herbst ist es oft neblig."},{"de":"unklar, verschwommen, nebulös (übertragen)","ex":"Zijn uitleg bleef nogal mistig.","exDe":"Seine Erklärung blieb ziemlich nebulös."}],"usage":"Adjektiv; wörtlich (Nebel) und übertragen (unklar).","illustratable":true},"bk_1070":{"lemma":"helder","displayNl":"helder","pos":"adjectief","meanings":[{"de":"klar (Himmel, Wasser, Luft)","ex":"De lucht is vanavond helder.","exDe":"Der Himmel ist heute Abend klar."},{"de":"hell, leuchtend","ex":"In de gang brandt een helder licht.","exDe":"Im Flur brennt ein helles Licht."},{"de":"klar, deutlich, verständlich","ex":"Zij gaf een heldere uitleg.","exDe":"Sie gab eine klare Erklärung."},{"de":"klar (im Kopf), wach","ex":"Na een kop koffie was ze weer helder.","exDe":"Nach einer Tasse Kaffee war sie wieder klar im Kopf."}],"usage":"Adjektiv mit breiter Polysemie: klar/hell (Sinne) und klar/verständlich (Denken)."},"bk_1071":{"lemma":"vochtig","displayNl":"vochtig","pos":"adjectief","meanings":[{"de":"feucht","ex":"De lucht is warm en vochtig.","exDe":"Die Luft ist warm und feucht."},{"de":"klamm, nass (Untergrund, Tuch)","ex":"Veeg het af met een vochtige doek.","exDe":"Wisch es mit einem feuchten Tuch ab."}],"usage":"Adjektiv; beschreibt Feuchtigkeit von Luft, Boden oder Oberflächen."},"bk_1072":{"lemma":"fris","displayNl":"fris","pos":"adjectief","meanings":[{"de":"frisch, kühl (Wetter, Luft)","ex":"De ochtend is lekker fris.","exDe":"Der Morgen ist angenehm frisch."},{"de":"frisch, erfrischt, ausgeruht","ex":"Na een goede nachtrust voel ik me weer fris.","exDe":"Nach einer guten Nachtruhe fühle ich mich wieder frisch."},{"de":"frisch, neu, unverbraucht","ex":"Er staan frisse bloemen op tafel.","exDe":"Es stehen frische Blumen auf dem Tisch."}],"usage":"Adjektiv; Wetter (kühl), Zustand (erfrischt) und Frische (neu). Vergleich: frisser, frist."},"bk_1073":{"lemma":"heet","displayNl":"heet","pos":"adjectief","meanings":[{"de":"heiß","ex":"In de zomer is het soms heet.","exDe":"Im Sommer ist es manchmal heiß."},{"de":"scharf (Essen)","ex":"Deze soep is te heet gekruid.","exDe":"Diese Suppe ist zu scharf gewürzt."}],"usage":"Prädikativ und attributiv: 'het is heet', 'hete koffie'. Vergleich: heter, heetst."},"bk_1074":{"lemma":"diep","displayNl":"diep","pos":"adjectief","meanings":[{"de":"tief (räumlich)","ex":"Het meer is heel diep.","exDe":"Der See ist sehr tief."},{"de":"tief, intensiv (Gefühl, Farbe, Ton)","ex":"Ze voelde een diepe droefheid.","exDe":"Sie fühlte eine tiefe Traurigkeit."}],"usage":"Attributiv 'een diep meer', adverbial 'diep ademhalen'. Steigerung: dieper, diepst."},"bk_1075":{"lemma":"groeien","displayNl":"groeien","pos":"werkwoord","meanings":[{"de":"wachsen (Pflanzen, Lebewesen)","ex":"De planten groeien snel.","exDe":"Die Pflanzen wachsen schnell."},{"de":"anwachsen, zunehmen","ex":"De stad groeit elk jaar.","exDe":"Die Stadt wächst jedes Jahr."}],"usage":"Intransitiv, Perfekt mit 'zijn'. Onafscheidbar. Häufig 'groeien naar/uit'.","conjugation":{"presens":{"ik":"groei","jij":"groeit","hij":"groeit","wij":"groeien"},"imperfectum":{"ik":"groeide","wij":"groeiden"},"perfectum":{"aux":"zijn","participle":"gegroeid"}},"illustratable":true},"bk_1076":{"lemma":"bloeien","displayNl":"bloeien","pos":"werkwoord","meanings":[{"de":"blühen","ex":"De rozen bloeien in juni.","exDe":"Die Rosen blühen im Juni."},{"de":"florieren, gedeihen (übertragen)","ex":"De handel bloeide in die tijd.","exDe":"Der Handel florierte in jener Zeit."}],"usage":"Intransitiv, Perfekt meist mit 'hebben'. Onafscheidbar.","conjugation":{"presens":{"ik":"bloei","jij":"bloeit","hij":"bloeit","wij":"bloeien"},"imperfectum":{"ik":"bloeide","wij":"bloeiden"},"perfectum":{"aux":"hebben","participle":"gebloeid"}},"illustratable":true},"bk_1077":{"lemma":"stromen","displayNl":"stromen","pos":"werkwoord","meanings":[{"de":"fließen, strömen","ex":"De rivier stroomt naar de zee.","exDe":"Der Fluss fließt zum Meer."},{"de":"in Strömen kommen/gehen (Menschen)","ex":"De mensen stroomden het stadion in.","exDe":"Die Menschen strömten ins Stadion."}],"usage":"Intransitiv; Perfekt mit 'zijn' bei Richtung/Ortsveränderung, mit 'hebben' ohne Bewegungsziel. Onafscheidbar.","conjugation":{"presens":{"ik":"stroom","jij":"stroomt","hij":"stroomt","wij":"stromen"},"imperfectum":{"ik":"stroomde","wij":"stroomden"},"perfectum":{"aux":"zijn","participle":"gestroomd"}},"illustratable":true},"bk_1078":{"lemma":"vriezen","displayNl":"vriezen","pos":"werkwoord","meanings":[{"de":"frieren, gefrieren (Wetter)","ex":"Vannacht gaat het vriezen.","exDe":"Heute Nacht wird es frieren."},{"de":"einfrieren, zu Eis werden","ex":"Het water in de sloot is bevroren.","exDe":"Das Wasser im Graben ist gefroren."}],"usage":"Meist unpersönlich 'het vriest'. Stark: Imperfekt 'vroor', Partizip 'gevroren'. Perfekt mit 'hebben' beim Wetter.","conjugation":{"presens":{"ik":"vries","jij":"vriest","hij":"vriest","wij":"vriezen"},"imperfectum":{"ik":"vroor","wij":"vroren"},"perfectum":{"aux":"hebben","participle":"gevroren"}},"illustratable":true},"bk_1079":{"lemma":"smelten","displayNl":"smelten","pos":"werkwoord","meanings":[{"de":"schmelzen, tauen","ex":"De sneeuw begint te smelten.","exDe":"Der Schnee fängt an zu schmelzen."},{"de":"einschmelzen (Metall, Butter - transitiv)","ex":"De smid smolt het oude ijzer.","exDe":"Der Schmied schmolz das alte Eisen ein."}],"usage":"Stark: Imperfekt 'smolt', Partizip 'gesmolten'. Intransitiv Perfekt mit 'zijn', transitiv mit 'hebben'.","conjugation":{"presens":{"ik":"smelt","jij":"smelt","hij":"smelt","wij":"smelten"},"imperfectum":{"ik":"smolt","wij":"smolten"},"perfectum":{"aux":"zijn","participle":"gesmolten"}},"illustratable":true},"bk_1080":{"lemma":"beschermen","displayNl":"beschermen","pos":"werkwoord","meanings":[{"de":"schützen, beschützen","ex":"We moeten de natuur beschermen.","exDe":"Wir müssen die Natur schützen."},{"de":"verteidigen, bewahren","ex":"Deze jas beschermt je tegen de regen.","exDe":"Diese Jacke schützt dich vor dem Regen."}],"usage":"Transitiv, Perfekt mit 'hebben'. Untrennbar (be-), Partizip ohne 'ge-': 'beschermd'. Häufig 'beschermen tegen'.","conjugation":{"presens":{"ik":"bescherm","jij":"beschermt","hij":"beschermt","wij":"beschermen"},"imperfectum":{"ik":"beschermde","wij":"beschermden"},"perfectum":{"aux":"hebben","participle":"beschermd"}}},"bk_1081":{"lemma":"ondergrond","displayNl":"de ondergrond","pos":"substantief","meanings":[{"de":"der Untergrund, der Boden (Beschaffenheit)","ex":"De ondergrond is hier nat en zacht.","exDe":"Der Untergrund ist hier nass und weich."},{"de":"der Hintergrund, die Grundierung (einer Fläche/eines Bildes)","ex":"Verf eerst de ondergrond wit.","exDe":"Streiche zuerst den Untergrund weiß."}],"usage":"Meint die Boden- oder Untergrund-Beschaffenheit; übertragen auch Grundierung/Basisschicht.","genus":"de","plural":"ondergronden"},"bk_1082":{"lemma":"tak","displayNl":"de tak","pos":"substantief","meanings":[{"de":"der Ast, der Zweig","ex":"Een vogel zit op de tak.","exDe":"Ein Vogel sitzt auf dem Ast."},{"de":"der Zweig, die Sparte (Branche/Abteilung)","ex":"Hij werkt in een andere tak van het bedrijf.","exDe":"Er arbeitet in einem anderen Zweig des Unternehmens."}],"usage":"Konkret der Ast eines Baumes; übertragen ein Zweig/eine Sparte.","genus":"de","plural":"takken","illustratable":true},"bk_1083":{"lemma":"zaad","displayNl":"het zaad","pos":"substantief","meanings":[{"de":"der Samen, das Saatkorn","ex":"Ik stop het zaad in de grond.","exDe":"Ich stecke den Samen in die Erde."},{"de":"das Saatgut, die Samen (kollektiv)","ex":"We kopen zaad voor de moestuin.","exDe":"Wir kaufen Saatgut für den Gemüsegarten."}],"usage":"Pflanzensamen; kollektiv auch Saatgut.","genus":"het","plural":"zaden","illustratable":true},"bk_1084":{"lemma":"vleugel","displayNl":"de vleugel","pos":"substantief","meanings":[{"de":"der Flügel (eines Vogels/Insekts/Flugzeugs)","ex":"De vogel heeft twee vleugels.","exDe":"Der Vogel hat zwei Flügel."},{"de":"der Flügel (Konzertflügel, Klavier)","ex":"Zij speelt op een grote zwarte vleugel.","exDe":"Sie spielt auf einem großen schwarzen Flügel."},{"de":"der Flügel (Gebäudeteil oder politische Richtung)","ex":"Het museum bouwt een nieuwe vleugel.","exDe":"Das Museum baut einen neuen Flügel."}],"usage":"Vogelflügel; auch Konzertflügel sowie Gebäude-/Partei-Flügel.","genus":"de","plural":"vleugels","illustratable":true},"bk_1085":{"lemma":"veer","displayNl":"de veer","pos":"substantief","meanings":[{"de":"die Feder (eines Vogels)","ex":"Er ligt een veer op de grond.","exDe":"Auf dem Boden liegt eine Feder."},{"de":"die Feder (mechanisch, Spiralfeder)","ex":"De veer van de pen is kapot.","exDe":"Die Feder des Kugelschreibers ist kaputt."},{"de":"die Fähre (het veer)","ex":"We nemen het veer naar de overkant.","exDe":"Wir nehmen die Fähre zum anderen Ufer."}],"usage":"Meist die Vogelfeder oder eine mechanische Feder; als het veer auch die Fähre (Homonym mit anderem Genus).","genus":"de","plural":"veren","illustratable":true},"bk_1086":{"lemma":"poot","displayNl":"de poot","pos":"substantief","meanings":[{"de":"die Pfote, das Bein (eines Tieres)","ex":"De kat likt haar poot.","exDe":"Die Katze leckt ihre Pfote."},{"de":"das Bein (eines Möbelstücks)","ex":"Een poot van de tafel is los.","exDe":"Ein Bein des Tisches ist locker."}],"usage":"Tierbein/Pfote; auch das Bein von Möbeln.","genus":"de","plural":"poten","illustratable":true},"bk_1087":{"lemma":"snavel","displayNl":"de snavel","pos":"substantief","meanings":[{"de":"der Schnabel","ex":"De vogel eet met zijn snavel.","exDe":"Der Vogel frisst mit dem Schnabel."}],"usage":"Der Schnabel eines Vogels.","genus":"de","plural":"snavels","illustratable":true},"bk_1088":{"lemma":"kattenbak","displayNl":"de kattenbak","pos":"substantief","meanings":[{"de":"die Katzentoilette, das Katzenklo","ex":"De poes gebruikt de kattenbak.","exDe":"Die Katze benutzt die Katzentoilette."}],"usage":"Behälter mit Streu als Katzentoilette.","genus":"de","plural":"kattenbakken","illustratable":true},"bk_1089":{"lemma":"geit","displayNl":"de geit","pos":"substantief","meanings":[{"de":"die Ziege","ex":"De geit eet bijna alles.","exDe":"Die Ziege frisst fast alles."},{"de":"(umgangssprachlich, abwertend) dumme/zickige Frau","ex":"Wat een oude geit, zei hij boos.","exDe":"Was für eine alte Ziege, sagte er wütend."}],"usage":"Nutztier; Diminutiv 'geitje'. Übertragen abwertend für eine Frau.","genus":"de","plural":"geiten","illustratable":true},"bk_1090":{"lemma":"haan","displayNl":"de haan","pos":"substantief","meanings":[{"de":"der Hahn (Tier)","ex":"De haan kraait vroeg in de ochtend.","exDe":"Der Hahn kräht früh am Morgen."},{"de":"der Hahn (an einem Gewehr), Abzugshahn","ex":"Hij spande de haan van het geweer.","exDe":"Er spannte den Hahn des Gewehrs."}],"usage":"Männliches Huhn. Redewendung 'de haan zijn' = der Hahn im Korb sein. Auch mechanischer Hahn einer Feuerwaffe.","genus":"de","plural":"hanen","illustratable":true},"bk_1091":{"lemma":"kuiken","displayNl":"het kuiken","pos":"substantief","meanings":[{"de":"das Küken","ex":"Het kuiken loopt achter de kip aan.","exDe":"Das Küken läuft hinter dem Huhn her."}],"usage":"Junges Huhn. Diminutiv-Form auf '-ken', gehört zu 'kuiken' selbst.","genus":"het","plural":"kuikens","illustratable":true},"bk_1092":{"lemma":"lam","displayNl":"het lam","pos":"substantief","meanings":[{"de":"das Lamm","ex":"Het lam drinkt bij het schaap.","exDe":"Das Lamm trinkt beim Schaf."},{"de":"(übertragen) sanftmütiger, wehrloser Mensch","ex":"Zo mak als een lam volgde hij haar.","exDe":"Sanft wie ein Lamm folgte er ihr."}],"usage":"Junges Schaf; Plural 'lammeren'. Das gleichlautende Adjektiv 'lam' (gelähmt) ist ein eigenes Lemma.","genus":"het","plural":"lammeren","illustratable":true},"bk_1093":{"lemma":"kalf","displayNl":"het kalf","pos":"substantief","meanings":[{"de":"das Kalb","ex":"Het kalf staat naast de koe.","exDe":"Das Kalb steht neben der Kuh."}],"usage":"Junges Rind; unregelmäßiger Plural 'kalveren' (auch 'kalfjes' als Diminutiv).","genus":"het","plural":"kalveren","illustratable":true},"bk_1094":{"lemma":"veulen","displayNl":"het veulen","pos":"substantief","meanings":[{"de":"das Fohlen","ex":"Het veulen rent over het veld.","exDe":"Das Fohlen rennt über das Feld."}],"usage":"Junges Pferd; Plural 'veulens'. Es gibt auch das gleichlautende Verb 'veulen' (fohlen), hier aber das Substantiv.","genus":"het","plural":"veulens","illustratable":true},"bk_1095":{"lemma":"puppy","displayNl":"de puppy","pos":"substantief","meanings":[{"de":"der Welpe, junger Hund","ex":"De puppy is nog heel klein.","exDe":"Der Welpe ist noch sehr klein."}],"usage":"Aus dem Englischen entlehnt; Plural mit Apostroph 'puppy's', Diminutiv 'puppy'tje'.","genus":"de","plural":"puppy's","illustratable":true},"bk_1096":{"lemma":"ezel","displayNl":"de ezel","pos":"substantief","meanings":[{"de":"der Esel (Tier)","ex":"De ezel draagt een zware zak.","exDe":"Der Esel trägt einen schweren Sack."},{"de":"(übertragen) Dummkopf, sturer Mensch","ex":"Wat ben ik toch een ezel, ik ben mijn sleutels vergeten.","exDe":"Was bin ich doch für ein Esel, ich habe meine Schlüssel vergessen."},{"de":"die Staffelei (des Malers)","ex":"De schilder zette zijn doek op de ezel.","exDe":"Der Maler stellte seine Leinwand auf die Staffelei."}],"usage":"Nutztier; übertragen Schimpfwort für einen Dummkopf; außerdem 'schildersezel' = Staffelei.","genus":"de","plural":"ezels","illustratable":true},"bk_1097":{"lemma":"konijnenhok","displayNl":"het konijnenhok","pos":"substantief","meanings":[{"de":"der Kaninchenstall, der Kaninchenkäfig","ex":"Het konijn zit in het hok.","exDe":"Das Kaninchen sitzt im Stall."},{"de":"das Kaninchengehege (im Garten)","ex":"Papa timmert een nieuw konijnenhok in de tuin.","exDe":"Papa zimmert einen neuen Kaninchenstall im Garten."}],"usage":"Zusammensetzung uit konijn + hok; hok = kleiner Stall/Verschlag für Kleintiere.","genus":"het","plural":"konijnenhokken","illustratable":true},"bk_1098":{"lemma":"stal","displayNl":"de stal","pos":"substantief","meanings":[{"de":"der Stall (für Vieh, Pferde, Kühe)","ex":"De koeien staan in de stal.","exDe":"Die Kühe stehen im Stall."},{"de":"der Rennstall / das Team (übertragen, z. B. Radsport)","ex":"Die renner rijdt voor een sterke stal.","exDe":"Der Fahrer fährt für einen starken Rennstall."}],"usage":"Für größere Nutztiere; kleine Tiere → hok. Übertragen ook = Team/Marke.","genus":"de","plural":"stallen","illustratable":true},"bk_1099":{"lemma":"wei","displayNl":"de wei","pos":"substantief","meanings":[{"de":"die Weide, die Wiese (für Vieh)","ex":"De schapen lopen in de wei.","exDe":"Die Schafe laufen auf der Weide."},{"de":"die Molke (Milchflüssigkeit)","ex":"Van wei maakt men kaas.","exDe":"Aus Molke macht man Käse."}],"usage":"Weide-Bedeutung ook langvorm 'weide'; homoniem 'wei' = Molke.","genus":"de","plural":"weien","illustratable":true},"bk_1100":{"lemma":"tijger","displayNl":"de tijger","pos":"substantief","meanings":[{"de":"der Tiger","ex":"De tijger heeft strepen.","exDe":"Der Tiger hat Streifen."}],"usage":"Regelmäßiger de-Plural op -s.","genus":"de","plural":"tijgers","illustratable":true},"bk_1101":{"lemma":"giraf","displayNl":"de giraf","pos":"substantief","meanings":[{"de":"die Giraffe","ex":"De giraf heeft een lange nek.","exDe":"Die Giraffe hat einen langen Hals."}],"usage":"Auch Schreibweise 'giraffe'; Plural giraffen.","genus":"de","plural":"giraffen","illustratable":true},"bk_1102":{"lemma":"zebra","displayNl":"de zebra","pos":"substantief","meanings":[{"de":"das Zebra","ex":"De zebra is zwart en wit.","exDe":"Das Zebra ist schwarz und weiß."},{"de":"der Zebrastreifen (kurz für zebrapad)","ex":"Steek over op de zebra.","exDe":"Überquere die Straße am Zebrastreifen."}],"usage":"Plural mit Apostroph zebra's; umgangssprachlich ook = Zebrastreifen.","genus":"de","plural":"zebra's","illustratable":true},"bk_1103":{"lemma":"slang","displayNl":"de slang","pos":"substantief","meanings":[{"de":"die Schlange (Tier)","ex":"De slang ligt in het gras.","exDe":"Die Schlange liegt im Gras."},{"de":"der Schlauch (Gummi-/Wasserschlauch)","ex":"Hij spuit de auto schoon met de slang.","exDe":"Er spritzt das Auto mit dem Schlauch sauber."}],"usage":"Homonym: dier én slang/Schlauch; anders als DE keine 'Warteschlange' → das ist 'rij'.","genus":"de","plural":"slangen","illustratable":true},"bk_1104":{"lemma":"haai","displayNl":"de haai","pos":"substantief","meanings":[{"de":"der Hai","ex":"De haai zwemt in de zee.","exDe":"Der Hai schwimmt im Meer."}],"usage":"Plural haaien; übertragen 'haai' ook = gerissener Geschäftemacher.","genus":"de","plural":"haaien","illustratable":true},"bk_1105":{"lemma":"walvis","displayNl":"de walvis","pos":"substantief","meanings":[{"de":"der Wal","ex":"De walvis is heel groot.","exDe":"Der Wal ist sehr groß."}],"usage":"Meeressäugetier; größtes Tier der Erde.","genus":"de","plural":"walvissen","illustratable":true},"bk_1106":{"lemma":"dolfijn","displayNl":"de dolfijn","pos":"substantief","meanings":[{"de":"der Delfin","ex":"De dolfijn springt uit het water.","exDe":"Der Delfin springt aus dem Wasser."}],"usage":"Verspieltes Meeressäugetier.","genus":"de","plural":"dolfijnen","illustratable":true},"bk_1107":{"lemma":"zeehond","displayNl":"de zeehond","pos":"substantief","meanings":[{"de":"der Seehund","ex":"De zeehond ligt op het strand.","exDe":"Der Seehund liegt am Strand."}],"usage":"Robbe der Nordseeküste; im Wattenmeer häufig.","genus":"de","plural":"zeehonden","illustratable":true},"bk_1108":{"lemma":"krab","displayNl":"de krab","pos":"substantief","meanings":[{"de":"die Krabbe","ex":"De krab loopt over het zand.","exDe":"Die Krabbe läuft über den Sand."}],"usage":"Krebstier mit Scheren; am Strand und im Watt.","genus":"de","plural":"krabben","illustratable":true},"bk_1109":{"lemma":"schildpad","displayNl":"de schildpad","pos":"substantief","meanings":[{"de":"die Schildkröte","ex":"De schildpad loopt heel langzaam.","exDe":"Die Schildkröte läuft sehr langsam."}],"usage":"Reptil mit Panzer; Land- oder Wasserschildkröte.","genus":"de","plural":"schildpadden","illustratable":true},"bk_1110":{"lemma":"pinguïn","displayNl":"de pinguïn","pos":"substantief","meanings":[{"de":"der Pinguin","ex":"De pinguïn leeft in de kou.","exDe":"Der Pinguin lebt in der Kälte."}],"usage":"Flugunfähiger Seevogel der kalten Regionen.","genus":"de","plural":"pinguïns","illustratable":true},"bk_1111":{"lemma":"uil","displayNl":"de uil","pos":"substantief","meanings":[{"de":"die Eule","ex":"De uil jaagt in de nacht.","exDe":"Die Eule jagt in der Nacht."}],"usage":"Nachtaktiver Greifvogel.","genus":"de","plural":"uilen","illustratable":true},"bk_1112":{"lemma":"duif","displayNl":"de duif","pos":"substantief","meanings":[{"de":"die Taube","ex":"De duif zit op het dak.","exDe":"Die Taube sitzt auf dem Dach."}],"usage":"Häufiger Stadtvogel.","genus":"de","plural":"duiven","illustratable":true},"bk_1113":{"lemma":"zwaan","displayNl":"de zwaan","pos":"substantief","meanings":[{"de":"der Schwan","ex":"De zwaan glijdt sierlijk over de gracht.","exDe":"Der Schwan gleitet anmutig über die Gracht."},{"de":"der Schwan (elegante, anmutige Person - übertragen)","ex":"Ze danste als een zwaan over het podium.","exDe":"Sie tanzte wie ein Schwan über die Bühne."}],"usage":"Grote witte watervogel met lange nek; meervoud 'zwanen'.","genus":"de","plural":"zwanen","illustratable":true},"bk_1114":{"lemma":"gans","displayNl":"de gans","pos":"substantief","meanings":[{"de":"die Gans (Tier)","ex":"De gans waggelt naar het water.","exDe":"Die Gans watschelt zum Wasser."},{"de":"die Gans (dumme Person, abwertend)","ex":"Wat een domme gans is dat toch.","exDe":"Was für eine dumme Gans das doch ist."}],"usage":"Watervogel, groter dan een eend; meervoud 'ganzen'.","genus":"de","plural":"ganzen","illustratable":true},"bk_1115":{"lemma":"meeuw","displayNl":"de meeuw","pos":"substantief","meanings":[{"de":"die Möwe","ex":"De meeuw vliegt krijsend boven de haven.","exDe":"Die Möwe fliegt kreischend über dem Hafen."}],"usage":"Zeevogel; meervoud 'meeuwen'.","genus":"de","plural":"meeuwen","illustratable":true},"bk_1116":{"lemma":"vlinder","displayNl":"de vlinder","pos":"substantief","meanings":[{"de":"der Schmetterling","ex":"De vlinder zit op een bloem in de tuin.","exDe":"Der Schmetterling sitzt auf einer Blume im Garten."},{"de":"der Schmetterling (Schwimmstil, 'vlinderslag')","ex":"Zij zwemt de vlinder heel snel.","exDe":"Sie schwimmt den Schmetterling sehr schnell."}],"usage":"Insect met grote gekleurde vleugels; meervoud 'vlinders'.","genus":"de","plural":"vlinders","illustratable":true},"bk_1117":{"lemma":"wesp","displayNl":"de wesp","pos":"substantief","meanings":[{"de":"die Wespe","ex":"De wesp vliegt om mijn glas limonade.","exDe":"Die Wespe fliegt um mein Glas Limonade."}],"usage":"Geel-zwart gestreept insect dat kan steken; meervoud 'wespen'.","genus":"de","plural":"wespen","illustratable":true},"bk_1118":{"lemma":"vlieg","displayNl":"de vlieg","pos":"substantief","meanings":[{"de":"die Fliege (Insekt)","ex":"Er zit een vlieg op het raam.","exDe":"Eine Fliege sitzt am Fenster."},{"de":"die Fliege (Schleife/Krawattenschleife)","ex":"Hij draagt een zwarte vlieg bij zijn pak.","exDe":"Er traegt eine schwarze Fliege zu seinem Anzug."}],"usage":"Klein zoemend insect; meervoud 'vliegen'. Ook: strikje bij een kostuum.","genus":"de","plural":"vliegen","illustratable":true},"bk_1119":{"lemma":"mug","displayNl":"de mug","pos":"substantief","meanings":[{"de":"die Mücke","ex":"De mug steekt mij in mijn arm.","exDe":"Die Mücke sticht mich in den Arm."}],"usage":"Klein stekend insect, vooral 's avonds bij water; meervoud 'muggen'.","genus":"de","plural":"muggen","illustratable":true},"bk_1120":{"lemma":"kever","displayNl":"de kever","pos":"substantief","meanings":[{"de":"der Käfer","ex":"De kever loopt langzaam over het blad.","exDe":"Der Käfer läuft langsam über das Blatt."}],"usage":"Insect met harde dekschilden; meervoud 'kevers'.","genus":"de","plural":"kevers","illustratable":true},"bk_1121":{"lemma":"worm","displayNl":"de worm","pos":"substantief","meanings":[{"de":"der Wurm (Regenwurm)","ex":"De worm zit in de grond.","exDe":"Der Wurm ist in der Erde."},{"de":"der Wurm (Schädling, z. B. im Apfel)","ex":"Er zit een worm in de appel.","exDe":"Es ist ein Wurm im Apfel."}],"usage":"Regenwurm/Wurm allgemein; 'de regenworm' speziell für den Regenwurm.","genus":"de","plural":"wormen","illustratable":true},"bk_1122":{"lemma":"slak","displayNl":"de slak","pos":"substantief","meanings":[{"de":"die Schnecke (mit Haus)","ex":"De slak beweegt heel langzaam.","exDe":"Die Schnecke bewegt sich sehr langsam."},{"de":"die Nacktschnecke","ex":"Er kruipt een slak over het blad.","exDe":"Eine Nacktschnecke kriecht über das Blatt."}],"usage":"Umfasst Gehäuse- und Nacktschnecke; 'huisjesslak' = Gehäuseschnecke, 'naaktslak' = Nacktschnecke.","genus":"de","plural":"slakken","illustratable":true},"bk_1123":{"lemma":"egel","displayNl":"de egel","pos":"substantief","meanings":[{"de":"der Igel","ex":"De egel heeft veel stekels.","exDe":"Der Igel hat viele Stacheln."}],"usage":"Das stachelige nachtaktive Säugetier.","genus":"de","plural":"egels","illustratable":true},"bk_1124":{"lemma":"hert","displayNl":"het hert","pos":"substantief","meanings":[{"de":"der Hirsch / das Reh (Rothirsch, Cerviden)","ex":"Het hert staat in het bos.","exDe":"Der Hirsch steht im Wald."}],"usage":"Sammelbegriff für Hirsch/Reh; 'het edelhert' = Rothirsch, 'de ree' = Reh.","genus":"het","plural":"herten","illustratable":true},"bk_1125":{"lemma":"konijnenhol","displayNl":"het konijnenhol","pos":"substantief","meanings":[{"de":"der Kaninchenbau","ex":"Het konijn kruipt in zijn hol.","exDe":"Das Kaninchen kriecht in seinen Bau."}],"usage":"Zusammensetzung aus 'konijn' + 'hol' (Höhle/Bau); der unterirdische Bau eines Kaninchens.","genus":"het","plural":"konijnenholen","illustratable":true},"bk_1126":{"lemma":"eekhoorn","displayNl":"de eekhoorn","pos":"substantief","meanings":[{"de":"das Eichhörnchen","ex":"De eekhoorn eet een noot.","exDe":"Das Eichhörnchen isst eine Nuss."}],"usage":"Plural auch 'eekhoorns'; das baumbewohnende Nagetier mit buschigem Schwanz.","genus":"de","plural":"eekhoorns","illustratable":true},"bk_1127":{"lemma":"mol","displayNl":"de mol","pos":"substantief","meanings":[{"de":"der Maulwurf","ex":"De mol graaft in de tuin.","exDe":"Der Maulwurf gräbt im Garten."},{"de":"das Mol (chemische Stoffmengeneinheit)","ex":"Eén mol water weegt ongeveer achttien gram.","exDe":"Ein Mol Wasser wiegt etwa achtzehn Gramm."},{"de":"der Verräter / Spitzel (Maulwurf im übertragenen Sinn, auch die TV-Show)","ex":"Wie is de mol in de groep?","exDe":"Wer ist der Maulwurf in der Gruppe?"}],"usage":"Häufigste Bedeutung das grabende Tier; daneben chemische Einheit und übertragen 'Verräter/Spitzel'.","genus":"de","plural":"mollen","illustratable":true},"bk_1128":{"lemma":"vleermuis","displayNl":"de vleermuis","pos":"substantief","meanings":[{"de":"die Fledermaus","ex":"De vleermuis vliegt in de nacht.","exDe":"Die Fledermaus fliegt in der Nacht."}],"usage":"Zusammensetzung 'vleer' (Flügel) + 'muis' (Maus); das einzige fliegende Säugetier.","genus":"de","plural":"vleermuizen","illustratable":true},"bk_1129":{"lemma":"kabouterboom","displayNl":"de kabouterboom","pos":"substantief","meanings":[{"de":"Zwergbaum, kleiner (Zier-)Baum","ex":"In de tuin staat een kleine kabouterboom.","exDe":"Im Garten steht ein kleiner Zwergbaum."},{"de":"märchenhafter Zwergen-/Wichtelbaum (bildhaft)","ex":"De kabouter woont onder een kabouterboom.","exDe":"Der Wichtel wohnt unter einem Zwergenbaum."}],"usage":"Zusammensetzung aus 'kabouter' (Wichtel/Zwerg) und 'boom' (Baum); umgangssprachlich für einen sehr kleinen, oft zierlichen Baum.","genus":"de","plural":"kabouterbomen","illustratable":true},"bk_1130":{"lemma":"stam","displayNl":"de stam","pos":"substantief","meanings":[{"de":"Stamm (eines Baumes)","ex":"De stam van de eik is heel dik.","exDe":"Der Stamm der Eiche ist sehr dick."},{"de":"Stamm, Volksstamm (Gruppe von Menschen)","ex":"De stam leefde diep in het bos.","exDe":"Der Stamm lebte tief im Wald."},{"de":"Wortstamm (Grammatik)","ex":"De stam van het werkwoord is 'werk'.","exDe":"Der Stamm des Verbs ist 'werk'."}],"usage":"Grundbedeutung Baumstamm; uebertragen auch Volksstamm sowie in der Grammatik der Wortstamm.","genus":"de","plural":"stammen","illustratable":true},"bk_1131":{"lemma":"blad","displayNl":"het blad","pos":"substantief","meanings":[{"de":"Blatt (eines Baumes/einer Pflanze)","ex":"In de herfst vallen de bladeren van de boom.","exDe":"Im Herbst fallen die Blätter vom Baum."},{"de":"Blatt (Papier), Seite","ex":"Ze schreef iets op een leeg blad.","exDe":"Sie schrieb etwas auf ein leeres Blatt."},{"de":"Tablett, Servierbrett","ex":"De ober bracht de koffie op een blad.","exDe":"Der Kellner brachte den Kaffee auf einem Tablett."},{"de":"Zeitung, Zeitschrift (Blatt)","ex":"Dit blad verschijnt elke week.","exDe":"Dieses Blatt erscheint jede Woche."}],"usage":"Eingabe stand im Plural (de bladeren) und wurde auf den Singular 'het blad' reduziert. Plural für Baumblaetter: bladeren; für Seiten/Tabletts: bladen.","genus":"het","plural":"bladeren","illustratable":true},"bk_1132":{"lemma":"roos","displayNl":"de roos","pos":"substantief","meanings":[{"de":"Rose (Blume)","ex":"De roos ruikt heel lekker.","exDe":"Die Rose riecht sehr gut."},{"de":"das Schwarze, Zentrum der Zielscheibe","ex":"Zijn pijl raakte precies in de roos.","exDe":"Sein Pfeil traf genau ins Schwarze."},{"de":"(Kopf-)Schuppen","ex":"Deze shampoo helpt tegen roos.","exDe":"Dieses Shampoo hilft gegen Schuppen."}],"usage":"Haeufigste Bedeutung Blume; ausserdem 'in de roos' = ins Schwarze/Zentrum treffen, sowie 'roos' als Kopfschuppen.","genus":"de","plural":"rozen","illustratable":true},"bk_1134":{"lemma":"zonnebloem","displayNl":"de zonnebloem","pos":"substantief","meanings":[{"de":"Sonnenblume","ex":"De zonnebloem is heel groot en geel.","exDe":"Die Sonnenblume ist sehr gross und gelb."}],"usage":"Zusammensetzung aus 'zon' (Sonne) und 'bloem' (Blume).","genus":"de","plural":"zonnebloemen","illustratable":true},"bk_1135":{"lemma":"madeliefje","displayNl":"het madeliefje","pos":"substantief","meanings":[{"de":"Gaensebluemchen","ex":"In het gras staat een madeliefje.","exDe":"Im Gras steht ein Gaensebluemchen."}],"usage":"Verkleinerungsform (-je), daher Genus 'het'; die uebliche Grundform des Wortes ist das Diminutiv 'madeliefje'.","genus":"het","plural":"madeliefjes","illustratable":true},"bk_1136":{"lemma":"paardenbloem","displayNl":"de paardenbloem","pos":"substantief","meanings":[{"de":"Loewenzahn","ex":"De paardenbloem is fel geel.","exDe":"Der Loewenzahn ist knallgelb."},{"de":"Pusteblume (verbluehter Loewenzahn mit Samenschirmchen)","ex":"Ze blies de zaadjes van de paardenbloem weg.","exDe":"Sie blies die Samen der Pusteblume weg."}],"usage":"Zusammensetzung aus 'paard' (Pferd) und 'bloem' (Blume); bezeichnet die gelbe Bluete wie auch die verbluehte Pusteblume.","genus":"de","plural":"paardenbloemen","illustratable":true},"bk_1137":{"lemma":"eik","displayNl":"de eik","pos":"substantief","meanings":[{"de":"Eiche (Baum)","ex":"De eik wordt heel oud.","exDe":"Die Eiche wird sehr alt."},{"de":"Eichenholz (als Material, oft 'eiken')","ex":"De tafel is van eiken gemaakt.","exDe":"Der Tisch ist aus Eichenholz gemacht."}],"usage":"Bezeichnet den Baum; als Adjektiv/Material meist 'eiken' (aus Eichenholz).","genus":"de","plural":"eiken","illustratable":true},"bk_1138":{"lemma":"den","displayNl":"de den","pos":"substantief","meanings":[{"de":"Kiefer (Nadelbaum)","ex":"De den blijft in de winter groen.","exDe":"Die Kiefer bleibt im Winter grün."},{"de":"Föhre","ex":"In het bos groeien veel hoge dennen.","exDe":"Im Wald wachsen viele hohe Kiefern."}],"usage":"Nadelbaum mit langen Nadeln; im Alltag oft für Kiefer/Föhre. Verwandt mit 'dennenboom' (auch für Weihnachtsbaum).","genus":"de","plural":"dennen","illustratable":true},"bk_1139":{"lemma":"struik","displayNl":"de struik","pos":"substantief","meanings":[{"de":"Strauch, Busch","ex":"Achter het huis staat een struik.","exDe":"Hinter dem Haus steht ein Strauch."},{"de":"Busch (z. B. Beerenstrauch)","ex":"De struik zit vol rode bessen.","exDe":"Der Strauch ist voller roter Beeren."}],"usage":"Verholzte Pflanze ohne durchgehenden Stamm, niedriger als ein Baum. Vergleiche 'boom' (Baum).","genus":"de","plural":"struiken","illustratable":true},"bk_1140":{"lemma":"vacht","displayNl":"de vacht","pos":"substantief","meanings":[{"de":"Fell (eines Tieres)","ex":"De kat heeft een zachte vacht.","exDe":"Die Katze hat ein weiches Fell."},{"de":"Pelz, Vlies","ex":"De hond schudt zijn natte vacht droog.","exDe":"Der Hund schüttelt sein nasses Fell trocken."}],"usage":"Behaarte Haut/Pelz eines Tieres; für Menschen nicht gebräuchlich (dort 'haar').","genus":"de","plural":"vachten","illustratable":true},"bk_1141":{"lemma":"hoorn","displayNl":"de hoorn","pos":"substantief","meanings":[{"de":"Horn (eines Tieres)","ex":"De koe heeft twee horens.","exDe":"Die Kuh hat zwei Hörner."},{"de":"Horn (Blasinstrument)","ex":"Hij speelt hoorn in het orkest.","exDe":"Er spielt Horn im Orchester."},{"de":"Hörer (Telefon)","ex":"Ze nam de hoorn van de haak.","exDe":"Sie nahm den Hörer ab."}],"usage":"Plural 'horens' bei Tierhörnern, 'hoorns' meist bei Instrumenten. Für den Telefonhörer heute veraltet, aber in Redewendungen präsent.","genus":"de","plural":"horens","illustratable":true},"bk_1142":{"lemma":"klauw","displayNl":"de klauw","pos":"substantief","meanings":[{"de":"Kralle, Klaue","ex":"De kat heeft scherpe klauwen.","exDe":"Die Katze hat scharfe Krallen."},{"de":"Klaue, Fang (Raubvogel)","ex":"De adelaar greep de muis met zijn klauwen.","exDe":"Der Adler griff die Maus mit seinen Klauen."}],"usage":"Scharfe, gekrümmte Kralle von Katzen, Raubvögeln oder Raubtieren. Bei Menschen bildlich für grobe Hände.","genus":"de","plural":"klauwen","illustratable":true},"bk_1143":{"lemma":"nest","displayNl":"het nest","pos":"substantief","meanings":[{"de":"Nest (Vogelnest)","ex":"De vogel bouwt een nest.","exDe":"Der Vogel baut ein Nest."},{"de":"Nest, Behausung (übertragen)","ex":"De jonge vogels zitten nog in het nest.","exDe":"Die Jungvögel sitzen noch im Nest."}],"usage":"Von Tieren gebaute Brutstätte, meist aus Zweigen und Halmen. Übertragen auch für Zuhause/Wurf.","genus":"het","plural":"nesten","illustratable":true},"bk_1144":{"lemma":"kudde","displayNl":"de kudde","pos":"substantief","meanings":[{"de":"Herde","ex":"Een kudde koeien loopt over de weg.","exDe":"Eine Herde Kühe läuft über die Straße."},{"de":"Herde, Schar (übertragen)","ex":"De herder drijft zijn kudde schapen bijeen.","exDe":"Der Hirte treibt seine Schafherde zusammen."}],"usage":"Gruppe von Weidetieren (Kühe, Schafe). Plural auch 'kudden'. Übertragen für eine folgsame Menschenmenge.","genus":"de","plural":"kuddes","illustratable":true},"bk_1145":{"lemma":"dierentuin","displayNl":"de dierentuin","pos":"substantief","meanings":[{"de":"Zoo, Tierpark","ex":"Wij gaan naar de dierentuin.","exDe":"Wir gehen in den Zoo."},{"de":"Tiergarten","ex":"In de dierentuin zagen we olifanten en giraffen.","exDe":"Im Zoo sahen wir Elefanten und Giraffen."}],"usage":"Zusammengesetzt aus 'dieren' (Tiere) + 'tuin' (Garten). Öffentliche Anlage mit gehaltenen Tieren.","genus":"de","plural":"dierentuinen","illustratable":true},"bk_1146":{"lemma":"huisdier","displayNl":"het huisdier","pos":"substantief","meanings":[{"de":"das Haustier","ex":"Een hond is een populair huisdier.","exDe":"Ein Hund ist ein beliebtes Haustier."},{"de":"das Heimtier (im Haus gehaltenes Tier)","ex":"Ons huisdier is een kleine cavia.","exDe":"Unser Haustier ist ein kleines Meerschweinchen."}],"usage":"Sammelbegriff für zu Hause gehaltene Tiere (hond, kat, konijn, cavia). Neutrum: het huisdier, Plural huisdieren.","genus":"het","plural":"huisdieren","illustratable":true},"bk_1147":{"lemma":"blaffen","displayNl":"blaffen","pos":"werkwoord","meanings":[{"de":"bellen","ex":"De hond begint hard te blaffen.","exDe":"Der Hund fängt an, laut zu bellen."},{"de":"anblaffen, jemanden anschnauzen (figurativ)","ex":"Hij blafte tegen zijn collega.","exDe":"Er fuhr seinen Kollegen an."}],"usage":"Regelmäßiges Verb (’t kofschip → -te/-t). Wörtlich vom Hund, figurativ = jemanden barsch anfahren.","conjugation":{"presens":{"ik":"blaf","jij":"blaft","hij":"blaft","wij":"blaffen"},"imperfectum":{"ik":"blafte","wij":"blaften"},"perfectum":{"aux":"hebben","participle":"geblaft"}},"illustratable":true},"bk_1148":{"lemma":"miauwen","displayNl":"miauwen","pos":"werkwoord","meanings":[{"de":"miauen","ex":"De poes miauwt om eten.","exDe":"Die Katze miaut nach Essen."}],"usage":"Regelmäßiges Verb (Stamm auf -w → -de/-d). Lautmalerisch für den Katzenlaut.","conjugation":{"presens":{"ik":"miauw","jij":"miauwt","hij":"miauwt","wij":"miauwen"},"imperfectum":{"ik":"miauwde","wij":"miauwden"},"perfectum":{"aux":"hebben","participle":"gemiauwd"}},"illustratable":true},"bk_1149":{"lemma":"vliegen","displayNl":"vliegen","pos":"werkwoord","meanings":[{"de":"fliegen (durch die Luft)","ex":"De vogels vliegen naar het zuiden.","exDe":"Die Vögel fliegen nach Süden."},{"de":"rasen, sehr schnell vergehen/sich bewegen","ex":"De tijd vliegt voorbij.","exDe":"Die Zeit vergeht wie im Flug."}],"usage":"Unregelmäßig (vliegen–vloog–gevlogen). Bei Bewegung/Richtung mit zijn (is gevlogen); bei reiner Tätigkeit auch mit hebben.","conjugation":{"presens":{"ik":"vlieg","jij":"vliegt","hij":"vliegt","wij":"vliegen"},"imperfectum":{"ik":"vloog","wij":"vlogen"},"perfectum":{"aux":"zijn","participle":"gevlogen"}},"illustratable":true},"bk_1150":{"lemma":"zwemmen","displayNl":"zwemmen","pos":"werkwoord","meanings":[{"de":"schwimmen","ex":"De vissen zwemmen in de vijver.","exDe":"Die Fische schwimmen im Teich."},{"de":"baden/schwimmen gehen (Freizeit)","ex":"In de zomer gaan we vaak zwemmen.","exDe":"Im Sommer gehen wir oft schwimmen."}],"usage":"Unregelmäßig (zwemmen–zwom–gezwommen). Als Tätigkeit mit hebben; bei Bewegung zu einem Ziel mit zijn (naar de overkant gezwommen).","conjugation":{"presens":{"ik":"zwem","jij":"zwemt","hij":"zwemt","wij":"zwemmen"},"imperfectum":{"ik":"zwom","wij":"zwommen"},"perfectum":{"aux":"hebben","participle":"gezwommen"}},"illustratable":true},"bk_1151":{"lemma":"kruipen","displayNl":"kruipen","pos":"werkwoord","meanings":[{"de":"kriechen","ex":"De slang kruipt over de grond.","exDe":"Die Schlange kriecht über den Boden."},{"de":"krabbeln (auf allen vieren, z. B. Baby)","ex":"De baby kruipt door de kamer.","exDe":"Das Baby krabbelt durch das Zimmer."}],"usage":"Unregelmäßig (kruipen–kroop–gekropen). Bei Bewegung/Richtung mit zijn; als reine Tätigkeit auch mit hebben.","conjugation":{"presens":{"ik":"kruip","jij":"kruipt","hij":"kruipt","wij":"kruipen"},"imperfectum":{"ik":"kroop","wij":"kropen"},"perfectum":{"aux":"zijn","participle":"gekropen"}},"illustratable":true},"bk_1152":{"lemma":"seconde","displayNl":"de seconde","pos":"substantief","meanings":[{"de":"die Sekunde (Zeiteinheit)","ex":"Het duurt maar een seconde.","exDe":"Es dauert nur eine Sekunde."},{"de":"der Augenblick, der Moment (kurze Weile)","ex":"Wacht een seconde, ik kom eraan.","exDe":"Warte einen Moment, ich komme."}],"usage":"de-Wort, Plural seconden (auch secondes). Zeiteinheit; umgangssprachlich auch für einen sehr kurzen Moment.","genus":"de","plural":"seconden"},"bk_1153":{"lemma":"overmorgen","displayNl":"overmorgen","pos":"bijwoord","meanings":[{"de":"übermorgen","ex":"Overmorgen komt mijn zus.","exDe":"Übermorgen kommt meine Schwester."}],"usage":"Zeitadverb: der Tag nach morgen. Unveränderlich."},"bk_1154":{"lemma":"eergisteren","displayNl":"eergisteren","pos":"bijwoord","meanings":[{"de":"vorgestern","ex":"Eergisteren regende het de hele dag.","exDe":"Vorgestern hat es den ganzen Tag geregnet."}],"usage":"Zeitadverb; bezeichnet den Tag vor gestern."},"bk_1155":{"lemma":"meestal","displayNl":"meestal","pos":"bijwoord","meanings":[{"de":"meistens","ex":"Ik werk meestal thuis.","exDe":"Ich arbeite meistens zu Hause."},{"de":"in der Regel / gewöhnlich","ex":"Meestal eten we om zes uur.","exDe":"Gewöhnlich essen wir um sechs Uhr."}],"usage":"Häufigkeitsadverb; drückt aus, dass etwas in den meisten Fällen zutrifft."},"bk_1156":{"lemma":"opnieuw","displayNl":"opnieuw","pos":"bijwoord","meanings":[{"de":"erneut / nochmals","ex":"Probeer het opnieuw.","exDe":"Versuche es nochmals."},{"de":"von vorn / noch einmal von Anfang an","ex":"We moeten helemaal opnieuw beginnen.","exDe":"Wir müssen ganz von vorn beginnen."}],"usage":"Adverb; kennzeichnet die Wiederholung einer Handlung."},"bk_1157":{"lemma":"meteen","displayNl":"meteen","pos":"bijwoord","meanings":[{"de":"sofort / gleich","ex":"Ik kom meteen.","exDe":"Ich komme sofort."},{"de":"gleichzeitig / zugleich","ex":"Dan is dat ook meteen geregeld.","exDe":"Dann ist das auch gleich erledigt."}],"usage":"Zeitadverb; bedeutet ohne Verzögerung, unmittelbar."},"bk_1158":{"lemma":"eindelijk","displayNl":"eindelijk","pos":"bijwoord","meanings":[{"de":"endlich","ex":"Eindelijk is het weekend.","exDe":"Endlich ist Wochenende."},{"de":"schließlich / letztendlich","ex":"Na lang wachten kwam de bus eindelijk.","exDe":"Nach langem Warten kam der Bus schließlich."}],"usage":"Adverb; drückt Erleichterung aus, dass etwas Erwartetes nun eintritt."},"bk_1159":{"lemma":"werkdag","displayNl":"de werkdag","pos":"substantief","meanings":[{"de":"der Werktag / Arbeitstag","ex":"Maandag is een gewone werkdag.","exDe":"Montag ist ein normaler Werktag."},{"de":"die tägliche Arbeitszeit / der Arbeitstag (Dauer)","ex":"Mijn werkdag begint om negen uur.","exDe":"Mein Arbeitstag beginnt um neun Uhr."}],"usage":"Substantiv; ein Tag, an dem gearbeitet wird, im Gegensatz zum Wochenende oder Feiertag.","genus":"de","plural":"werkdagen"},"bk_1160":{"lemma":"feestdag","displayNl":"de feestdag","pos":"substantief","meanings":[{"de":"der Feiertag","ex":"Morgen is het een feestdag, dus we zijn vrij.","exDe":"Morgen ist ein Feiertag, deshalb haben wir frei."}],"usage":"Substantiv; ein offizieller oder festlicher Tag, an dem meist nicht gearbeitet wird.","genus":"de","plural":"feestdagen"},"bk_1161":{"lemma":"seizoen","displayNl":"het seizoen","pos":"substantief","meanings":[{"de":"die Jahreszeit","ex":"De herfst is mijn favoriete seizoen.","exDe":"Der Herbst ist meine Lieblingsjahreszeit."},{"de":"die Saison (z. B. Sport, Serie, Ernte)","ex":"Het nieuwe seizoen van de competitie begint volgende week.","exDe":"Die neue Saison der Liga beginnt nächste Woche."}],"usage":"Substantiv; ein Abschnitt des Jahres (Frühling, Sommer, Herbst, Winter) oder eine wiederkehrende Zeitspanne.","genus":"het","plural":"seizoenen","illustratable":true},"bk_1162":{"lemma":"datum","displayNl":"de datum","pos":"substantief","meanings":[{"de":"das Datum","ex":"Wat is de datum van vandaag?","exDe":"Welches Datum ist heute?"},{"de":"der Termin / Zeitpunkt","ex":"We prikken een datum voor de vergadering.","exDe":"Wir legen einen Termin für die Besprechung fest."}],"usage":"Substantiv, de-Wort. Plural meist 'data'; die Nebenform 'datums' ist ebenfalls gebräuchlich. Nicht mit 'data' (= Daten) im Sinne von Informationen verwechseln.","genus":"de","plural":"data"},"bk_1163":{"lemma":"kalender","displayNl":"de kalender","pos":"substantief","meanings":[{"de":"der Kalender","ex":"Ik schrijf de afspraak in de kalender.","exDe":"Ich schreibe den Termin in den Kalender."},{"de":"der Wandkalender / Abreißkalender","ex":"Aan de muur hangt een kalender met foto's.","exDe":"An der Wand hängt ein Kalender mit Fotos."}],"usage":"Substantiv, de-Wort, Plural 'kalenders'. Bezeichnet sowohl das Zeitsystem als auch das gedruckte Objekt.","genus":"de","plural":"kalenders","illustratable":true},"bk_1164":{"lemma":"kwartier","displayNl":"het kwartier","pos":"substantief","meanings":[{"de":"die Viertelstunde","ex":"Ik wacht al een kwartier op de bus.","exDe":"Ich warte schon eine Viertelstunde auf den Bus."},{"de":"das Quartier / Stadtviertel (gehoben, selten)","ex":"Het hoofdkwartier van het bedrijf staat in Amsterdam.","exDe":"Der Hauptsitz des Unternehmens steht in Amsterdam."}],"usage":"Substantiv, het-Wort. Alltagsbedeutung fast immer 'Viertelstunde'. In Zusammensetzungen wie 'hoofdkwartier' bedeutet es 'Quartier/Sitz'.","genus":"het","plural":"kwartieren"},"bk_1165":{"lemma":"half uur","displayNl":"het half uur","pos":"substantief","meanings":[{"de":"die halbe Stunde","ex":"De les duurt maar een half uur.","exDe":"Der Unterricht dauert nur eine halbe Stunde."}],"usage":"Feste Verbindung um 'het uur'; genus richtet sich nach 'uur' (het). Wird meist mit unbestimmtem Artikel gebraucht: 'een half uur'. Plural 'halve uren'.","genus":"het","plural":"halve uren"},"bk_1166":{"lemma":"kwart over","displayNl":"kwart over","pos":"uitdrukking","meanings":[{"de":"Viertel nach","ex":"Het is kwart over vier.","exDe":"Es ist Viertel nach vier."}],"usage":"Feste Uhrzeit-Wendung ohne eigenen Artikel. Struktur: 'kwart over' + volle Stunde. Gegenstueck: 'kwart voor'."},"bk_1167":{"lemma":"kwart voor","displayNl":"kwart voor","pos":"uitdrukking","meanings":[{"de":"Viertel vor","ex":"Het is kwart voor negen.","exDe":"Es ist Viertel vor neun."}],"usage":"Feste Uhrzeit-Wendung ohne eigenen Artikel. Struktur: 'kwart voor' + kommende volle Stunde. Gegenstueck: 'kwart over'."},"bk_1168":{"lemma":"over","displayNl":"over","pos":"voorzetsel","meanings":[{"de":"nach (bei Uhrzeitangaben)","ex":"Het is tien over acht.","exDe":"Es ist zehn nach acht."},{"de":"über (Thema / darüber)","ex":"We praten over het weer.","exDe":"Wir reden über das Wetter."},{"de":"über / hinüber (räumlich, quer)","ex":"De brug gaat over de gracht.","exDe":"Die Brücke führt über die Gracht."},{"de":"vorbei / übrig (als Adverb)","ex":"De pijn is nu over.","exDe":"Der Schmerz ist jetzt vorbei."}],"usage":"Vielseitiges Funktionswort: Präposition (räumlich 'über', thematisch 'über'), bei Uhrzeiten 'nach', und als Adverb 'vorbei/übrig'. Bedeutung stark kontextabhängig."},"bk_1169":{"lemma":"voor","displayNl":"voor","pos":"voorzetsel","meanings":[{"de":"vor (bei Uhrzeitangaben)","ex":"Het is vijf voor twaalf.","exDe":"Es ist fünf vor zwölf."},{"de":"für (zugunsten / bestimmt für)","ex":"Dit cadeau is voor jou.","exDe":"Dieses Geschenk ist für dich."},{"de":"vor (räumlich / zeitlich davor)","ex":"De auto staat voor het huis.","exDe":"Das Auto steht vor dem Haus."}],"usage":"Häufiges Funktionswort mit mehreren Bedeutungen: 'für' (Zweck/Empfänger), 'vor' (räumlich und zeitlich) und bei Uhrzeiten 'vor'. Als Konjunktion 'voordat' im Sinne von 'bevor' abgegrenzt."},"bk_1170":{"lemma":"moment","displayNl":"het moment","pos":"substantief","meanings":[{"de":"der Moment, der Augenblick","ex":"Wacht een moment, ik kom eraan.","exDe":"Warte einen Moment, ich komme."},{"de":"der Zeitpunkt","ex":"Op dat moment ging de telefoon.","exDe":"In dem Zeitpunkt klingelte das Telefon."}],"usage":"Alltäglich für einen kurzen Augenblick; 'een moment' = einen Moment (bitte warten).","genus":"het","plural":"momenten"},"bk_1171":{"lemma":"miljoen","displayNl":"het miljoen","pos":"substantief","meanings":[{"de":"die Million","ex":"Hij wint een miljoen euro.","exDe":"Er gewinnt eine Million Euro."},{"de":"eine Unmenge, unzählige (bildlich)","ex":"Er zijn miljoenen sterren aan de hemel.","exDe":"Es gibt Millionen Sterne am Himmel."}],"usage":"Als Zahlwort nach Grundzahl oft ohne Plural-s: 'twee miljoen mensen'; sonst Plural 'miljoenen'.","genus":"het","plural":"miljoenen"},"bk_1172":{"lemma":"vierde","displayNl":"vierde","pos":"telwoord","meanings":[{"de":"vierte(r/s)","ex":"Dit is mijn vierde kopje koffie.","exDe":"Das ist meine vierte Tasse Kaffee."},{"de":"das Viertel (Bruch: een vierde)","ex":"Een vierde van de klas was ziek.","exDe":"Ein Viertel der Klasse war krank."}],"usage":"Ordnungszahl zu 'vier'; steht mit Artikel/Possessiv ('de vierde', 'mijn vierde')."},"bk_1173":{"lemma":"vijfde","displayNl":"vijfde","pos":"telwoord","meanings":[{"de":"fünfte(r/s)","ex":"We wonen op de vijfde etage.","exDe":"Wir wohnen in der fünften Etage."},{"de":"das Fünftel (Bruch: een vijfde)","ex":"Een vijfde van het geld is voor jou.","exDe":"Ein Fünftel des Geldes ist für dich."}],"usage":"Ordnungszahl zu 'vijf'; steht mit Artikel/Possessiv."},"bk_1174":{"lemma":"laatste","displayNl":"laatste","pos":"adjectief","meanings":[{"de":"letzte(r/s)","ex":"Dit is de laatste bus.","exDe":"Das ist der letzte Bus."},{"de":"neueste(r/s), jüngste(r/s)","ex":"Heb je het laatste nieuws gehoord?","exDe":"Hast du die neuesten Nachrichten gehört?"}],"usage":"Superlativ-artiges Adjektiv; steht mit Artikel ('de/het laatste'). Gegenteil: 'eerste'."},"bk_1175":{"lemma":"minder","displayNl":"minder","pos":"bijwoord","meanings":[{"de":"weniger","ex":"Eet minder suiker.","exDe":"Iss weniger Zucker."},{"de":"geringer, schlechter, minderwertig","ex":"De kwaliteit is dit jaar minder.","exDe":"Die Qualität ist dieses Jahr geringer."}],"usage":"Komparativ zu 'weinig'/'weinig veel'; Gegenteil 'meer'. Als Adverb und Adjektiv gebräuchlich."},"bk_1176":{"lemma":"te veel","displayNl":"te veel","pos":"uitdrukking","meanings":[{"de":"zu viel","ex":"Dat is te veel werk.","exDe":"Das ist zu viel Arbeit."},{"de":"überzählig, einer zu viel","ex":"Er is een stoel te veel.","exDe":"Es ist ein Stuhl zu viel."}],"usage":"'te' + 'veel' = übermäßig viel; getrennt geschrieben. Gegenteil: 'te weinig'."},"bk_1177":{"lemma":"sommige","displayNl":"sommige","pos":"voornaamwoord","meanings":[{"de":"einige, manche","ex":"Sommige mensen houden van thee.","exDe":"Manche Menschen mögen Tee."}],"usage":"Unbestimmtes Pronomen/Determinativ vor Pluralnomen ('sommige mensen'); Singular selten 'sommig'. Vgl. 'enkele'."},"bk_1178":{"lemma":"helft","displayNl":"de helft","pos":"substantief","meanings":[{"de":"die Hälfte","ex":"Ik eet de helft van de appel.","exDe":"Ich esse die Hälfte des Apfels."},{"de":"Halbzeit (Sport)","ex":"In de tweede helft scoorde hij twee keer.","exDe":"In der zweiten Halbzeit traf er zweimal."}],"usage":"Meist mit 'van' (de helft van iets). Im Sport = Spielhälfte/Halbzeit.","genus":"de","plural":"helften"},"bk_1179":{"lemma":"paar","displayNl":"het paar","pos":"substantief","meanings":[{"de":"das Paar (zwei zusammengehörige Dinge)","ex":"Ik koop een paar schönen.","exDe":"Ich kaufe ein Paar Schuhe."},{"de":"das Paar (zwei Menschen, Beziehung)","ex":"Ze zijn een gelukkig paar.","exDe":"Sie sind ein glückliches Paar."},{"de":"ein paar, einige (in 'een paar')","ex":"Ik blijf nog een paar dagen.","exDe":"Ich bleibe noch ein paar Tage."}],"usage":"'een paar' + Plural = einige/ein paar. Als zählbares Substantiv (het paar) = das Paar.","genus":"het","plural":"paren","illustratable":true},"bk_1180":{"lemma":"centimeter","displayNl":"de centimeter","pos":"substantief","meanings":[{"de":"der Zentimeter (Längenmaß)","ex":"Het is dertig centimeter lang.","exDe":"Es ist dreißig Zentimeter lang."},{"de":"das Maßband (umgangssprachlich)","ex":"Pak even de centimeter om het te meten.","exDe":"Hol mal das Maßband, um es zu messen."}],"usage":"Nach Zahlwörtern bleibt die Form oft 'centimeter' (dertig centimeter). Abkürzung: cm.","genus":"de","plural":"centimeters"},"bk_1181":{"lemma":"liter","displayNl":"de liter","pos":"substantief","meanings":[{"de":"der Liter (Hohlmaß)","ex":"Ik koop een liter melk.","exDe":"Ich kaufe einen Liter Milch."}],"usage":"Nach Zahlwörtern meist unverändert 'liter' (twee liter water). Abkürzung: l.","genus":"de","plural":"liters"},"bk_1182":{"lemma":"kilo","displayNl":"de kilo","pos":"substantief","meanings":[{"de":"das Kilo, Kilogramm (Gewicht)","ex":"Ik wil een kilo appels.","exDe":"Ich möchte ein Kilo Äpfel."}],"usage":"Kurzform von 'kilogram'. Nach Zahlwörtern unverändert 'kilo' (drie kilo). Abkürzung: kg.","genus":"de","plural":"kilo's"},"bk_1183":{"lemma":"gram","displayNl":"het gram","pos":"substantief","meanings":[{"de":"das Gramm (Gewicht)","ex":"Geef me honderd gram kaas.","exDe":"Geben Sie mir hundert Gramm Käse."}],"usage":"Nach Zahlwörtern unverändert 'gram' (honderd gram). Abkürzung: g.","genus":"het","plural":"grammen"},"bk_1184":{"lemma":"keer","displayNl":"de keer","pos":"substantief","meanings":[{"de":"das Mal (Anzahl/Wiederholung)","ex":"Ik ben er drie keer geweest.","exDe":"Ich war dreimal dort."},{"de":"mal (Multiplikation)","ex":"Drie keer vier is twaalf.","exDe":"Drei mal vier ist zwölf."}],"usage":"Zählwort für Häufigkeit: 'een keer' (einmal), 'twee keer' (zweimal). Auch in Rechnungen (keer = mal).","genus":"de","plural":"keren"},"bk_1185":{"lemma":"de eerste keer","displayNl":"de eerste keer","pos":"uitdrukking","meanings":[{"de":"das erste Mal","ex":"Dit is de eerste keer dat ik hier ben.","exDe":"Das ist das erste Mal, dass ich hier bin."}],"usage":"Feste Fügung 'de eerste keer' (das erste Mal); parallel gebildet z. B. 'de tweede/laatste keer'."},"bk_1186":{"lemma":"per uur","displayNl":"per uur","pos":"uitdrukking","meanings":[{"de":"pro Stunde","ex":"Ik verdien tien euro per uur.","exDe":"Ich verdiene zehn Euro pro Stunde."},{"de":"je Stunde (Tempo/Rate)","ex":"De auto rijdt honderd kilometer per uur.","exDe":"Das Auto fährt hundert Kilometer pro Stunde."}],"usage":"Feste Wendung mit 'per' + Zeiteinheit; drückt eine Rate pro Stunde aus (Lohn, Geschwindigkeit, Menge)."},"bk_1187":{"lemma":"per dag","displayNl":"per dag","pos":"uitdrukking","meanings":[{"de":"pro Tag","ex":"Ik drink twee liter water per dag.","exDe":"Ich trinke zwei Liter Wasser pro Tag."},{"de":"am Tag / täglich","ex":"De winkel verkoopt honderd broden per dag.","exDe":"Der Laden verkauft hundert Brote pro Tag."}],"usage":"Feste Wendung mit 'per' + Zeiteinheit; gibt eine Menge oder Häufigkeit pro Tag an."},"bk_1188":{"lemma":"ongeveer","displayNl":"ongeveer","pos":"bijwoord","meanings":[{"de":"ungefähr / etwa","ex":"Het duurt ongeveer een uur.","exDe":"Es dauert ungefähr eine Stunde."},{"de":"circa / rund (bei Zahlen)","ex":"Er waren ongeveer vijftig mensen.","exDe":"Es waren ungefähr fünfzig Menschen."}],"usage":"Bijwoord vor Zahlen-, Zeit- oder Mengenangaben; signalisiert eine Schätzung. Synonyme: 'circa', 'zo'n', 'ongeveer'."},"bk_1189":{"lemma":"gids","displayNl":"de gids","pos":"substantief","meanings":[{"de":"der Reiseführer / Fremdenführer (Person)","ex":"De gids vertelt veel over de stad.","exDe":"Der Reiseführer erzählt viel über die Stadt."},{"de":"der Reiseführer / Führer (Buch, Nachschlagewerk)","ex":"Ik koop een gids van Amsterdam.","exDe":"Ich kaufe einen Reiseführer von Amsterdam."}],"usage":"'de gids' meint sowohl die begleitende Person als auch das gedruckte Führerbuch; aus dem Kontext ableitbar.","genus":"de","plural":"gidsen","illustratable":true},"bk_1190":{"lemma":"zwembroek","displayNl":"de zwembroek","pos":"substantief","meanings":[{"de":"die Badehose","ex":"Ik vergeet mijn zwembroek niet.","exDe":"Ich vergesse meine Badehose nicht."}],"usage":"'de zwembroek' bezeichnet die Herren-/Kinder-Badehose; Damen-Badebekleidung heißt 'het badpak' oder 'de bikini'.","genus":"de","plural":"zwembroeken","illustratable":true},"bk_1191":{"lemma":"zwembad","displayNl":"het zwembad","pos":"substantief","meanings":[{"de":"das Schwimmbad / der Swimmingpool","ex":"Het hotel heeft een groot zwembad.","exDe":"Das Hotel hat einen großen Swimmingpool."},{"de":"das Schwimmbad (öffentliche Badeanstalt)","ex":"In de zomer gaan we vaak naar het zwembad.","exDe":"Im Sommer gehen wir oft ins Schwimmbad."}],"usage":"'het zwembad' meint sowohl das private Pool-Becken als auch die öffentliche Schwimmbad-Anlage.","genus":"het","plural":"zwembaden","illustratable":true},"bk_1192":{"lemma":"camping","displayNl":"de camping","pos":"substantief","meanings":[{"de":"der Campingplatz","ex":"Wij slapen op de camping.","exDe":"Wir schlafen auf dem Campingplatz."}],"usage":"'de camping' bezeichnet den Ort (Campingplatz). Die Tätigkeit 'Camping/Zelten' heißt 'kamperen'.","genus":"de","plural":"campings","illustratable":true},"bk_1193":{"lemma":"tent","displayNl":"de tent","pos":"substantief","meanings":[{"de":"das Zelt","ex":"Wij zetten de tent op.","exDe":"Wir bauen das Zelt auf."},{"de":"das (Fest-)Zelt / der Stand (Markt, Veranstaltung)","ex":"Op de kermis staat een grote tent.","exDe":"Auf dem Jahrmarkt steht ein großes Festzelt."},{"de":"der Laden / die Bude (umgangssprachlich für Lokal)","ex":"Dat is een leuke tent om iets te drinken.","exDe":"Das ist ein nettes Lokal, um etwas zu trinken."}],"usage":"Grundbedeutung 'Zelt'; übertragen auch Festzelt/Marktstand und umgangssprachlich ein Lokal oder Laden.","genus":"de","plural":"tenten","illustratable":true},"bk_1194":{"lemma":"paspoort","displayNl":"het paspoort","pos":"substantief","meanings":[{"de":"der Reisepass","ex":"Ik laat mijn paspoort bij de controle zien.","exDe":"Ich zeige meinen Reisepass bei der Kontrolle."},{"de":"der Ausweis (als Reisedokument)","ex":"Zonder geldig paspoort mag je niet reizen.","exDe":"Ohne gültigen Reisepass darf man nicht reisen."}],"usage":"Neutrum (het). Plural: paspoorten. Reisedokument; nicht mit 'identiteitskaart' verwechseln.","genus":"het","plural":"paspoorten","illustratable":true},"bk_1195":{"lemma":"ticket","displayNl":"het ticket","pos":"substantief","meanings":[{"de":"das Ticket, die Fahrkarte / Flugkarte","ex":"Ik koop een ticket online.","exDe":"Ich kaufe ein Ticket online."},{"de":"die Eintrittskarte","ex":"Heb je al een ticket voor het concert?","exDe":"Hast du schon ein Ticket für das Konzert?"}],"usage":"Neutrum (het). Plural: tickets. Auch 'kaartje' gebräuchlich; 'ticket' oft für Flug/Event.","genus":"het","plural":"tickets","illustratable":true},"bk_1196":{"lemma":"luchthaven","displayNl":"de luchthaven","pos":"substantief","meanings":[{"de":"der Flughafen","ex":"Wij zijn twee uur voor de vlucht op de luchthaven.","exDe":"Wir sind zwei Stunden vor dem Flug am Flughafen."}],"usage":"Utrum (de). Plural: luchthavens. Synonym 'vliegveld' (het), oft kleiner/informeller.","genus":"de","plural":"luchthavens","illustratable":true},"bk_1197":{"lemma":"bagage","displayNl":"de bagage","pos":"substantief","meanings":[{"de":"das Gepäck","ex":"Mijn bagage is te zwaar.","exDe":"Mein Gepäck ist zu schwer."},{"de":"das Reisegepäck (Koffer und Taschen zusammen)","ex":"Je kunt je bagage hier inchecken.","exDe":"Du kannst dein Gepäck hier einchecken."}],"usage":"Utrum (de). Unzählbar, kein regulärer Plural. Sammelbegriff für Koffer und Taschen.","genus":"de","illustratable":true},"bk_1198":{"lemma":"receptie","displayNl":"de receptie","pos":"substantief","meanings":[{"de":"die Rezeption, der Empfang","ex":"De sleutel ligt bij de receptie.","exDe":"Der Schlüssel liegt an der Rezeption."},{"de":"der Empfang / die Feier (gesellschaftlicher Empfang)","ex":"Na de bruiloft is er een receptie.","exDe":"Nach der Hochzeit gibt es einen Empfang."}],"usage":"Utrum (de). Plural: recepties. Doppelbedeutung: Hotel-Empfangstresen und festlicher Empfang.","genus":"de","plural":"recepties","illustratable":true},"bk_1199":{"lemma":"boeken","displayNl":"boeken","pos":"werkwoord","meanings":[{"de":"buchen (Reise, Hotel, Termin)","ex":"Wij boeken een hotel aan zee.","exDe":"Wir buchen ein Hotel am Meer."},{"de":"verbuchen, erzielen (z. B. Erfolg, Gewinn)","ex":"Het team boekt goede resultaten.","exDe":"Das Team verbucht gute Ergebnisse."}],"usage":"Regelmäßiges schwaches Verb, Hilfsverb hebben. Achtung: Form 'boeken' ist auch Plural von 'het boek' (Bücher).","conjugation":{"presens":{"ik":"boek","jij":"boekt","hij":"boekt","wij":"boeken"},"imperfectum":{"ik":"boekte","wij":"boekten"},"perfectum":{"aux":"hebben","participle":"geboekt"}}},"bk_1200":{"lemma":"reservering","displayNl":"de reservering","pos":"substantief","meanings":[{"de":"die Reservierung, die Buchung","ex":"Ik heb een reservering voor twee nachten.","exDe":"Ich habe eine Reservierung für zwei Nächte."},{"de":"die reservierte Buchung (Restaurant/Tisch)","ex":"We hebben een reservering op naam van Jansen.","exDe":"Wir haben eine Reservierung auf den Namen Jansen."}],"usage":"Utrum (de). Plural: reserveringen. Verb dazu: 'reserveren'. Synonym teils 'boeking'.","genus":"de","plural":"reserveringen"},"bk_1201":{"lemma":"overnachten","displayNl":"overnachten","pos":"werkwoord","meanings":[{"de":"übernachten","ex":"Wij overnachten in een klein hotel.","exDe":"Wir übernachten in einem kleinen Hotel."},{"de":"die Nacht verbringen (unterwegs)","ex":"We overnachten onderweg bij vrienden.","exDe":"Wir übernachten unterwegs bei Freunden."}],"usage":"Untrennbares schwaches Verb, Hilfsverb hebben. Partizip 'overnacht' (ohne ge-).","conjugation":{"presens":{"ik":"overnacht","jij":"overnacht","hij":"overnacht","wij":"overnachten"},"imperfectum":{"ik":"overnachtte","wij":"overnachtten"},"perfectum":{"aux":"hebben","participle":"overnacht"}},"illustratable":true},"bk_1202":{"lemma":"bezoeken","displayNl":"bezoeken","pos":"werkwoord","meanings":[{"de":"besuchen (einen Ort, ein Museum, eine Kirche)","ex":"Wij bezoeken de oude kerk in het centrum.","exDe":"Wir besuchen die alte Kirche im Zentrum."},{"de":"besuchen (eine Person aufsuchen)","ex":"Morgen bezoek ik mijn oma in het ziekenhuis.","exDe":"Morgen besuche ich meine Oma im Krankenhaus."},{"de":"aufsuchen, heimsuchen (z. B. eine Website, eine Veranstaltung)","ex":"Duizenden mensen bezoeken elk jaar dit festival.","exDe":"Tausende Menschen besuchen jedes Jahr dieses Festival."}],"usage":"Unregelmäßiges Imperfekt (bezocht/bezochten) und Partizip (bezocht). Objekt ist meist der besuchte Ort oder die Person.","conjugation":{"presens":{"ik":"bezoek","jij":"bezoekt","hij":"bezoekt","wij":"bezoeken"},"imperfectum":{"ik":"bezocht","wij":"bezochten"},"perfectum":{"aux":"hebben","participle":"bezocht"}},"illustratable":true},"bk_1203":{"lemma":"fietstocht","displayNl":"de fietstocht","pos":"substantief","meanings":[{"de":"die Radtour, die Fahrradtour","ex":"Wij maken een fietstocht door het bos.","exDe":"Wir machen eine Radtour durch den Wald."},{"de":"der Radausflug (organisierte Tour)","ex":"De fietstocht langs de molens duurt drie uur.","exDe":"Der Radausflug entlang der Mühlen dauert drei Stunden."}],"usage":"Zusammensetzung aus fiets (Fahrrad) + tocht (Tour). Häufig mit 'maken': een fietstocht maken.","genus":"de","plural":"fietstochten","illustratable":true},"bk_1204":{"lemma":"skiën","displayNl":"skiën","pos":"werkwoord","meanings":[{"de":"Ski fahren, Ski laufen","ex":"In de winter gaan wij skiën in Oostenrijk.","exDe":"Im Winter gehen wir in Österreich Ski fahren."}],"usage":"Trema in skiën/geskied trennt die Vokale für getrennte Aussprache. Meist mit 'gaan': gaan skiën.","conjugation":{"presens":{"ik":"ski","jij":"skiet","hij":"skiet","wij":"skiën"},"imperfectum":{"ik":"skiede","wij":"skieden"},"perfectum":{"aux":"hebben","participle":"geskied"}},"illustratable":true},"bk_1205":{"lemma":"ski","displayNl":"de ski","pos":"substantief","meanings":[{"de":"der Ski","ex":"Mijn ski's zijn nieuw en glimmen.","exDe":"Meine Ski sind neu und glänzen."}],"usage":"Plural mit Apostroph: ski's. Als Sportgerät meist im Plural gebraucht.","genus":"de","plural":"ski's","illustratable":true},"bk_1206":{"lemma":"schaatsen","displayNl":"schaatsen","pos":"werkwoord","meanings":[{"de":"Schlittschuh laufen, eislaufen","ex":"In de winter gaan wij schaatsen op het kanaal.","exDe":"Im Winter gehen wir auf dem Kanal Schlittschuh laufen."}],"usage":"Regelmäßiges Verb. In den Niederlanden traditionsreich (Elfstedentocht). Das gleichnamige Substantiv de schaats bezeichnet den Schlittschuh.","conjugation":{"presens":{"ik":"schaats","jij":"schaatst","hij":"schaatst","wij":"schaatsen"},"imperfectum":{"ik":"schaatste","wij":"schaatsten"},"perfectum":{"aux":"hebben","participle":"geschaatst"}},"illustratable":true},"bk_1207":{"lemma":"wedstrijd","displayNl":"de wedstrijd","pos":"substantief","meanings":[{"de":"das Spiel, die Partie (Sport)","ex":"De wedstrijd begint om drie uur.","exDe":"Das Spiel beginnt um drei Uhr."},{"de":"der Wettkampf, der Wettbewerb","ex":"Hij won de wedstrijd na een spannende finale.","exDe":"Er gewann den Wettkampf nach einem spannenden Finale."}],"usage":"Häufig im Sportkontext (voetbalwedstrijd). Kann auch allgemeinen Wettbewerb bezeichnen.","genus":"de","plural":"wedstrijden","illustratable":true},"bk_1209":{"lemma":"verliezen","displayNl":"verliezen","pos":"werkwoord","meanings":[{"de":"verlieren (ein Spiel, einen Wettkampf)","ex":"Ons team verliest de wedstrijd met 2-1.","exDe":"Unsere Mannschaft verliert das Spiel mit 2:1."},{"de":"verlieren (einen Gegenstand einbüßen)","ex":"Ik ben mijn sleutels verloren in het park.","exDe":"Ich habe meine Schlüssel im Park verloren."},{"de":"verlieren (einen geliebten Menschen durch den Tod)","ex":"Zij heeft vorig jaar haar vader verloren.","exDe":"Sie hat letztes Jahr ihren Vater verloren."}],"usage":"Stark unregelmäßig: verloor/verloren, Partizip verloren. Reflexiv zich verliezen = sich verlieren.","conjugation":{"presens":{"ik":"verlies","jij":"verliest","hij":"verliest","wij":"verliezen"},"imperfectum":{"ik":"verloor","wij":"verloren"},"perfectum":{"aux":"hebben","participle":"verloren"}}},"bk_1211":{"lemma":"trainen","displayNl":"trainen","pos":"werkwoord","meanings":[{"de":"trainieren (Sport, körperlich üben)","ex":"Ik train twee keer per week in de sportschool.","exDe":"Ich trainiere zweimal pro Woche im Fitnessstudio."},{"de":"trainieren, schulen (jemanden oder etwas ausbilden)","ex":"De coach traint het jeugdteam elke zaterdag.","exDe":"Der Trainer trainiert die Jugendmannschaft jeden Samstag."}],"usage":"Regelmäßiges Verb. Sowohl intransitiv (selbst trainieren) als auch transitiv (jemanden trainieren).","conjugation":{"presens":{"ik":"train","jij":"traint","hij":"traint","wij":"trainen"},"imperfectum":{"ik":"trainde","wij":"trainden"},"perfectum":{"aux":"hebben","participle":"getraind"}},"illustratable":true},"bk_1212":{"lemma":"training","displayNl":"de training","pos":"substantief","meanings":[{"de":"das Training (sportliche Übungseinheit)","ex":"De training is om zeven uur.","exDe":"Das Training ist um sieben Uhr."},{"de":"die Schulung, die Ausbildung, der Lehrgang","ex":"Hij volgt een training voor zijn nieuwe baan.","exDe":"Er macht eine Schulung für seinen neuen Job."}],"usage":"Alltagswort für Sport-Übungseinheiten und für berufliche Schulungen/Kurse.","genus":"de","plural":"trainingen","illustratable":true},"bk_1213":{"lemma":"sportschool","displayNl":"de sportschool","pos":"substantief","meanings":[{"de":"das Fitnessstudio","ex":"Ik ga naar de sportschool.","exDe":"Ich gehe ins Fitnessstudio."}],"usage":"Gebraeuchliches Wort für ein Fitnessstudio; auch für eine Sport- oder Kampfsportschule.","genus":"de","plural":"sportscholen","illustratable":true},"bk_1214":{"lemma":"hardlopen","displayNl":"hardlopen","pos":"werkwoord","meanings":[{"de":"joggen, laufen, rennen (zum Sport)","ex":"Ik ga elke ochtend hardlopen.","exDe":"Ich gehe jeden Morgen joggen."}],"usage":"Trennbares Verb (hard + lopen) für Ausdauerlaufen als Sport; im Satz getrennt: ik loop elke dag hard.","conjugation":{"presens":{"ik":"loop hard","jij":"loopt hard","hij":"loopt hard","wij":"lopen hard"},"imperfectum":{"ik":"liep hard","wij":"liepen hard"},"perfectum":{"aux":"hebben","participle":"hardgelopen"}},"illustratable":true},"bk_1215":{"lemma":"concert","displayNl":"het concert","pos":"substantief","meanings":[{"de":"das Konzert (Musikveranstaltung)","ex":"Wij gaan naar een concert.","exDe":"Wir gehen zu einem Konzert."}],"usage":"Musikveranstaltung; man geht naar een concert.","genus":"het","plural":"concerten","illustratable":true},"bk_1216":{"lemma":"schilderij","displayNl":"het schilderij","pos":"substantief","meanings":[{"de":"das Gemaelde, das Bild (gemalt)","ex":"Dit schilderij is heel oud.","exDe":"Dieses Gemaelde ist sehr alt."}],"usage":"Trotz haeufigem Irrtum ist es HET schilderij (Neutrum). Bezeichnet ein gemaltes Bild.","genus":"het","plural":"schilderijen","notes":"Eingabe nannte 'de schilderij'; korrekt ist het schilderij (Neutrum).","illustratable":true},"bk_1217":{"lemma":"kunst","displayNl":"de kunst","pos":"substantief","meanings":[{"de":"die Kunst (Malerei, Musik, kuenstlerisches Schaffen)","ex":"Ik houd van moderne kunst.","exDe":"Ich mag moderne Kunst."},{"de":"das Kunststueck, die Fertigkeit (etwas Schwieriges/Kniff)","ex":"Dat is geen kunst, dat kan iedereen.","exDe":"Das ist keine Kunst, das kann jeder."}],"usage":"Meist unzaehlbar für Kunst als Bereich; in Redewendungen auch 'Kunststueck/Kniff'. Plural kunsten in 'schone kunsten'.","genus":"de","plural":"kunsten"},"bk_1218":{"lemma":"piano","displayNl":"de piano","pos":"substantief","meanings":[{"de":"das Klavier","ex":"Zij speelt piano sinds haar zesde.","exDe":"Sie spielt Klavier seit ihrem sechsten Lebensjahr."}],"usage":"Das Tasteninstrument; piano spelen = Klavier spielen. Plural mit Apostroph: piano's.","genus":"de","plural":"piano's","illustratable":true},"bk_1219":{"lemma":"instrument","displayNl":"het instrument","pos":"substantief","meanings":[{"de":"das Instrument (Musikinstrument)","ex":"Welk instrument speel jij?","exDe":"Welches Instrument spielst du?"},{"de":"das Werkzeug, das Geraet (Mess- oder Fachinstrument)","ex":"De chirurg legt zijn instrumenten klaar.","exDe":"Der Chirurg legt seine Instrumente bereit."}],"usage":"Neben Musikinstrument auch allgemein technisches Werkzeug/Messgeraet.","genus":"het","plural":"instrumenten","illustratable":true},"bk_1220":{"lemma":"schaken","displayNl":"het schaken","pos":"substantief","meanings":[{"de":"das Schach, das Schachspielen","ex":"Wij spelen graag een potje schaken.","exDe":"Wir spielen gerne eine Partie Schach."},{"de":"das Schachspielen (als Freizeitbeschäftigung)","ex":"Schaken is een spel van strategie en geduld.","exDe":"Schach ist ein Spiel der Strategie und Geduld."}],"usage":"Substantivierter Infinitiv (het schaken) für das Spiel/die Tätigkeit; das Spiel selbst heißt auch het schaakspel. Als Verb 'schaken' = Schach spielen.","genus":"het","notes":"Kein üblicher Plural. Homonym 'schaken' (entführen/rauben) ist veraltet und wird hier ausgelassen.","illustratable":true},"bk_1221":{"lemma":"kaart","displayNl":"de kaart","pos":"substantief","meanings":[{"de":"die Spielkarte","ex":"Wij spelen kaarten in de avond.","exDe":"Wir spielen abends Karten."},{"de":"die Landkarte, der Stadtplan","ex":"Ik zoek de weg op de kaart.","exDe":"Ich suche den Weg auf der Karte."},{"de":"die Karte, das Ticket (Fahr-/Eintrittskarte)","ex":"Heb je al een kaart voor de trein gekocht?","exDe":"Hast du schon eine Karte für den Zug gekauft?"},{"de":"die Speisekarte","ex":"De ober brengt de kaart.","exDe":"Der Kellner bringt die Speisekarte."},{"de":"die (Ansichts-/Bank-)Karte","ex":"Ik betaal met mijn kaart.","exDe":"Ich zahle mit meiner Karte."}],"usage":"Sehr polysem: Spielkarte, Land-/Stadtplan, Ticket, Speisekarte, Bank-/Ansichtskarte. Kontext entscheidet.","genus":"de","plural":"kaarten","illustratable":true},"bk_1222":{"lemma":"puzzel","displayNl":"de puzzel","pos":"substantief","meanings":[{"de":"das Puzzle","ex":"Ik maak een grote puzzel.","exDe":"Ich mache ein großes Puzzle."},{"de":"das Rätsel, die knifflige Aufgabe","ex":"Dat probleem is een echte puzzel.","exDe":"Dieses Problem ist ein echtes Rätsel."}],"usage":"Konkretes Legepuzzle sowie übertragen ein Rätsel/kniffliges Problem.","genus":"de","plural":"puzzels","illustratable":true},"bk_1223":{"lemma":"vrije tijd","displayNl":"de vrije tijd","pos":"substantief","meanings":[{"de":"die Freizeit","ex":"In mijn vrije tijd sport ik graag.","exDe":"In meiner Freizeit treibe ich gerne Sport."}],"usage":"Feste Wortverbindung (Adjektiv + de tijd); unzählbar, kein Plural. Meist mit 'in mijn/je/... vrije tijd'.","genus":"de","notes":"Abstrakter Begriff, daher nicht illustrierbar."},"bk_1224":{"lemma":"smartphone","displayNl":"de smartphone","pos":"substantief","meanings":[{"de":"das Smartphone","ex":"Bijna iedereen heeft een smartphone.","exDe":"Fast jeder hat ein Smartphone."}],"usage":"Lehnwort aus dem Englischen; Plural auf -s.","genus":"de","plural":"smartphones","illustratable":true},"bk_1225":{"lemma":"toetsenbord","displayNl":"het toetsenbord","pos":"substantief","meanings":[{"de":"die Tastatur (Computer)","ex":"Het toetsenbord is kapot.","exDe":"Die Tastatur ist kaputt."},{"de":"das Keyboard, die Klaviatur (Musikinstrument)","ex":"Zij oefent iedere dag op haar toetsenbord.","exDe":"Sie übt jeden Tag an ihrem Keyboard."}],"usage":"Computertastatur sowie die Tasten-/Klaviatur eines Musikinstruments.","genus":"het","plural":"toetsenborden","illustratable":true},"bk_1226":{"lemma":"oplader","displayNl":"de oplader","pos":"substantief","meanings":[{"de":"das Ladegerät, das Ladekabel","ex":"Ik ben mijn oplader vergeten.","exDe":"Ich habe mein Ladegerät vergessen."}],"usage":"Gerät oder Kabel zum Aufladen von Akkus/Geräten; Plural auf -s.","genus":"de","plural":"opladers","illustratable":true},"bk_1227":{"lemma":"batterij","displayNl":"de batterij","pos":"substantief","meanings":[{"de":"die Batterie, der Akku","ex":"De batterij is leeg.","exDe":"Die Batterie ist leer."},{"de":"die Batterie, eine große Menge/Reihe (übertragen)","ex":"Op tafel stond een hele batterij flessen.","exDe":"Auf dem Tisch stand eine ganze Batterie Flaschen."}],"usage":"Vor allem Strom-Batterie/Akku; übertragen auch eine große Reihe/Menge von Dingen.","genus":"de","plural":"batterijen","notes":"Militärische Bedeutung (Artilleriebatterie) hier als selten ausgelassen.","illustratable":true},"bk_1228":{"lemma":"accu","displayNl":"de accu","pos":"substantief","meanings":[{"de":"der Akku, die (wiederaufladbare) Batterie","ex":"Mijn accu is bijna op.","exDe":"Mein Akku ist fast leer."},{"de":"die Autobatterie","ex":"De accu van de auto is leeg, hij start niet.","exDe":"Die Autobatterie ist leer, das Auto springt nicht an."}],"usage":"Wiederaufladbarer Stromspeicher (Handy, Auto). Wegwerf-Batterie = 'de batterij'. Plural mit Apostroph: accu's.","genus":"de","plural":"accu's","illustratable":true},"bk_1229":{"lemma":"wachtwoord","displayNl":"het wachtwoord","pos":"substantief","meanings":[{"de":"das Passwort, das Kennwort","ex":"Ik ben mijn wachtwoord vergeten.","exDe":"Ich habe mein Passwort vergessen."}],"usage":"Geheime Zeichenfolge zum Einloggen. Zusammensetzung: wacht + woord.","genus":"het","plural":"wachtwoorden"},"bk_1230":{"lemma":"gebruiker","displayNl":"de gebruiker","pos":"substantief","meanings":[{"de":"der Benutzer, der Nutzer, der Anwender","ex":"De gebruiker moet inloggen.","exDe":"Der Benutzer muss sich einloggen."},{"de":"der Konsument, der Drogenkonsument","ex":"De gebruiker van harddrugs krijgt hulp.","exDe":"Der Konsument harter Drogen bekommt Hilfe."}],"usage":"Von 'gebruiken' (benutzen). Weibliche Form: gebruikster. Im Kontext Sucht = Konsument.","genus":"de","plural":"gebruikers"},"bk_1231":{"lemma":"account","displayNl":"het account","pos":"substantief","meanings":[{"de":"das Konto, der Account (online, digital)","ex":"Ik maak een nieuw account aan.","exDe":"Ich erstelle ein neues Konto."},{"de":"das (Benutzer-)Konto, der Zugang","ex":"Zij logt in op haar account.","exDe":"Sie loggt sich in ihr Konto ein."}],"usage":"Englisches Lehnwort, hier het-Wort (auch 'de account' kommt vor). Bankkonto separat = 'de rekening'.","genus":"het","plural":"accounts"},"bk_1232":{"lemma":"profiel","displayNl":"het profiel","pos":"substantief","meanings":[{"de":"das Profil (Online-, Nutzerprofil)","ex":"Zijn profiel staat online.","exDe":"Sein Profil ist online."},{"de":"das Profil, die Seitenansicht (eines Gesichts)","ex":"Op de foto zie je haar en profiel.","exDe":"Auf dem Foto sieht man sie im Profil."},{"de":"das Profil (Reifen-, Sohlenprofil)","ex":"Het profiel van de band is versleten.","exDe":"Das Profil des Reifens ist abgefahren."}],"usage":"Mehrdeutig: Online-Profil, Seitenansicht, Reifenprofil. Aussprache /proˈfil/.","genus":"het","plural":"profielen"},"bk_1233":{"lemma":"link","displayNl":"de link","pos":"substantief","meanings":[{"de":"der Link, der Verweis (Hyperlink)","ex":"Klik op de link.","exDe":"Klick auf den Link."},{"de":"die Verbindung, der Zusammenhang","ex":"Er is een duidelijke link tussen roken en ziekte.","exDe":"Es gibt einen klaren Zusammenhang zwischen Rauchen und Krankheit."}],"usage":"Substantiv 'de link' = Hyperlink/Verbindung. Nicht verwechseln mit Adjektiv 'link' (heikel, gerissen) oder 'links' (links/linke Seite).","genus":"de","plural":"links"},"bk_1234":{"lemma":"pagina","displayNl":"de pagina","pos":"substantief","meanings":[{"de":"die Seite (Webseite, Internetseite)","ex":"De pagina laadt langzaam.","exDe":"Die Seite lädt langsam."},{"de":"die Seite (eines Buches, Blattes)","ex":"Sla de pagina om.","exDe":"Blättere die Seite um."}],"usage":"Buch- wie Webseite. Plural mit Apostroph: pagina's. Abgekuerzt 'pag.' oder 'p.'.","genus":"de","plural":"pagina's"},"bk_1235":{"lemma":"netwerk","displayNl":"het netwerk","pos":"substantief","meanings":[{"de":"das Netzwerk (Computer-, Datennetz)","ex":"Het netwerk is heel snel.","exDe":"Das Netzwerk ist sehr schnell."},{"de":"das Netzwerk, das Kontaktnetz (von Personen)","ex":"Zij heeft een groot professioneel netwerk.","exDe":"Sie hat ein grosses berufliches Netzwerk."}],"usage":"Technisches Datennetz und soziales/berufliches Kontaktnetz. Verb: 'netwerken' (Kontakte knuepfen).","genus":"het","plural":"netwerken"},"bk_1236":{"lemma":"verbinding","displayNl":"de verbinding","pos":"substantief","meanings":[{"de":"die Verbindung (Telefon/Internet/Signal)","ex":"De verbinding is slecht.","exDe":"Die Verbindung ist schlecht."},{"de":"die Verbindung (Verkehr, Anschluss)","ex":"Er is een goede verbinding met de trein.","exDe":"Es gibt eine gute Verbindung mit dem Zug."},{"de":"der Zusammenhang, die Beziehung","ex":"Ik zie geen verbinding tussen die twee dingen.","exDe":"Ich sehe keinen Zusammenhang zwischen diesen zwei Dingen."}],"usage":"Alltagswort für technische Verbindung (Netz/Telefon) und Verkehrsverbindung.","genus":"de","plural":"verbindingen"},"bk_1237":{"lemma":"signaal","displayNl":"het signaal","pos":"substantief","meanings":[{"de":"das Signal (Empfang, Funk)","ex":"Hier heb ik geen signaal.","exDe":"Hier habe ich kein Signal."},{"de":"das Signal, das Zeichen","ex":"Dat is een duidelijk signaal.","exDe":"Das ist ein deutliches Signal."}],"usage":"Vom Handyempfang bis zum übertragenen Zeichen/Hinweis.","genus":"het","plural":"signalen"},"bk_1238":{"lemma":"zender","displayNl":"de zender","pos":"substantief","meanings":[{"de":"der Sender (TV-/Radiosender)","ex":"Welke zender kijk je?","exDe":"Welchen Sender schaust du?"},{"de":"der Sender (Sendemast, Sendegerät)","ex":"De zender op de heuvel is heel hoog.","exDe":"Der Sendemast auf dem Hügel ist sehr hoch."}],"usage":"Meist TV-/Radiosender; kann auch das sendende Gerät/den Sendemast meinen.","genus":"de","plural":"zenders"},"bk_1239":{"lemma":"kanaal","displayNl":"het kanaal","pos":"substantief","meanings":[{"de":"der Kanal (TV-/Fernsehkanal)","ex":"Dit kanaal is heel populair.","exDe":"Dieser Kanal ist sehr beliebt."},{"de":"der Kanal (Wasserweg, Gracht)","ex":"De boot vaart door het kanaal.","exDe":"Das Boot fährt durch den Kanal."},{"de":"das Kanal / der Ärmelkanal","ex":"Het Kanaal ligt tussen Engeland en Frankrijk.","exDe":"Der Ärmelkanal liegt zwischen England und Frankreich."}],"usage":"Sowohl Fernsehkanal als auch schiffbarer Wasserweg; met hoofdletter 'het Kanaal' = Ärmelkanal.","genus":"het","plural":"kanalen","illustratable":true},"bk_1240":{"lemma":"programma","displayNl":"het programma","pos":"substantief","meanings":[{"de":"die Sendung, das Programm (TV/Radio)","ex":"Dit programma is heel grappig.","exDe":"Diese Sendung ist sehr lustig."},{"de":"das Programm (Ablauf, Veranstaltungsplan)","ex":"Wat staat er op het programma vandaag?","exDe":"Was steht heute auf dem Programm?"},{"de":"das Programm (Software, Computerprogramm)","ex":"Ik moet dit programma nog installeren.","exDe":"Ich muss dieses Programm noch installieren."}],"usage":"TV-Sendung, Veranstaltungsablauf oder Computerprogramm.","genus":"het","plural":"programma's"},"bk_1241":{"lemma":"aflevering","displayNl":"de aflevering","pos":"substantief","meanings":[{"de":"die Folge, die Episode","ex":"Ik kijk de laatste aflevering.","exDe":"Ich schaue die letzte Folge."},{"de":"die Lieferung, die Auslieferung","ex":"De aflevering van het pakket is morgen.","exDe":"Die Lieferung des Pakets ist morgen."}],"usage":"Meist Serien-Folge; formeller auch Auslieferung/Lieferung.","genus":"de","plural":"afleveringen"},"bk_1242":{"lemma":"serie","displayNl":"de serie","pos":"substantief","meanings":[{"de":"die Serie (Fernsehserie)","ex":"Deze serie is heel spannend.","exDe":"Diese Serie ist sehr spannend."},{"de":"die Serie, die Reihe (Folge gleichartiger Dinge)","ex":"Hij won een hele serie wedstrijden.","exDe":"Er gewann eine ganze Serie von Spielen."}],"usage":"TV-Serie oder allgemein eine Reihe/Folge gleichartiger Dinge.","genus":"de","plural":"series"},"bk_1243":{"lemma":"nieuws","displayNl":"het nieuws","pos":"substantief","meanings":[{"de":"die Nachrichten (Nachrichtensendung)","ex":"Ik kijk elke avond het nieuws.","exDe":"Ich schaue jeden Abend die Nachrichten."},{"de":"die Neuigkeit, die Neuigkeiten","ex":"Heb je al het laatste nieuws gehoord?","exDe":"Hast du schon die neuesten Neuigkeiten gehört?"}],"usage":"Unzählbar (kein Plural): Nachrichten(sendung) und Neuigkeiten allgemein.","genus":"het"},"bk_1244":{"lemma":"artikel","displayNl":"het artikel","pos":"substantief","meanings":[{"de":"der Artikel (Text/Beitrag)","ex":"Ik lees een artikel over sport.","exDe":"Ich lese einen Artikel über Sport."},{"de":"der Artikel, die Ware (Produkt)","ex":"Dit artikel is uitverkocht.","exDe":"Dieser Artikel ist ausverkauft."},{"de":"der Artikel (Grammatik: Geschlechtswort)","ex":"'De' en 'het' zijn lidwoorden, geen artikelen in de klassieke zin.","exDe":"'De' und 'het' sind Artikel im grammatischen Sinne."}],"usage":"Sehr breit: Text/Beitrag, Ware im Laden und grammatischer Artikel. Kontext entscheidet.","genus":"het","plural":"artikelen"},"bk_1245":{"lemma":"tijdschrift","displayNl":"het tijdschrift","pos":"substantief","meanings":[{"de":"die Zeitschrift, das Magazin","ex":"Ze koopt elke week een tijdschrift.","exDe":"Sie kauft jede Woche eine Zeitschrift."}],"usage":"Periodisch erscheinendes Heft (Magazin), anders als 'krant' (Zeitung).","genus":"het","plural":"tijdschriften","illustratable":true},"bk_1246":{"lemma":"video","displayNl":"de video","pos":"substantief","meanings":[{"de":"das Video (Filmclip)","ex":"Hij deelt een grappige video.","exDe":"Er teilt ein lustiges Video."}],"usage":"Bewegtbild-Clip; Plural 'video's' mit Apostroph.","genus":"de","plural":"video's"},"bk_1248":{"lemma":"koptelefoon","displayNl":"de koptelefoon","pos":"substantief","meanings":[{"de":"der Kopfhörer","ex":"Ik draag een koptelefoon in de trein.","exDe":"Ich trage im Zug einen Kopfhörer."}],"usage":"Over-Ear/On-Ear-Kopfhörer; kleine Ohrstöpsel heißen 'oordopjes'.","genus":"de","plural":"koptelefoons","illustratable":true},"bk_1249":{"lemma":"speaker","displayNl":"de speaker","pos":"substantief","meanings":[{"de":"der Lautsprecher, die Box","ex":"De speaker is heel goed.","exDe":"Der Lautsprecher ist sehr gut."},{"de":"der Sprecher, der Redner (bei einer Veranstaltung)","ex":"De speaker opende de conferentie.","exDe":"Der Redner eröffnete die Konferenz."}],"usage":"Anglizismus: meist Lautsprecher/Box, in Veranstaltungskontext auch Redner/Ansager.","genus":"de","plural":"speakers","illustratable":true},"bk_1250":{"lemma":"sturen","displayNl":"sturen","pos":"werkwoord","meanings":[{"de":"senden, schicken","ex":"Ik ga hem een bericht sturen.","exDe":"Ich schicke ihm eine Nachricht."},{"de":"steuern, lenken","ex":"Zij kan een boot goed sturen.","exDe":"Sie kann ein Boot gut steuern."}],"usage":"Roheintrag 'het bericht sturen' auf Infinitiv 'sturen' reduziert. Regelmäßig, Hilfsverb hebben. Bedeutet schicken/senden und steuern/lenken.","conjugation":{"presens":{"ik":"stuur","jij":"stuurt","hij":"stuurt","wij":"sturen"},"imperfectum":{"ik":"stuurde","wij":"stuurden"},"perfectum":{"aux":"hebben","participle":"gestuurd"}}},"bk_1251":{"lemma":"downloaden","displayNl":"downloaden","pos":"werkwoord","meanings":[{"de":"herunterladen, downloaden","ex":"Ik ga de app downloaden.","exDe":"Ich lade die App herunter."}],"usage":"Anglizismus, regelmäßig konjugiert, Hilfsverb hebben; Partizip 'gedownload'.","conjugation":{"presens":{"ik":"download","jij":"downloadt","hij":"downloadt","wij":"downloaden"},"imperfectum":{"ik":"downloadde","wij":"downloadden"},"perfectum":{"aux":"hebben","participle":"gedownload"}}},"bk_1252":{"lemma":"installeren","displayNl":"installeren","pos":"werkwoord","meanings":[{"de":"installieren, einrichten","ex":"Je moet het programma installeren.","exDe":"Du musst das Programm installieren."}],"usage":"Regelmäßig, Hilfsverb hebben; Partizip 'geïnstalleerd' mit Trema auf dem i.","conjugation":{"presens":{"ik":"installeer","jij":"installeert","hij":"installeert","wij":"installeren"},"imperfectum":{"ik":"installeerde","wij":"installeerden"},"perfectum":{"aux":"hebben","participle":"geïnstalleerd"}}},"bk_1253":{"lemma":"klikken","displayNl":"klikken","pos":"werkwoord","meanings":[{"de":"klicken (mit der Maus)","ex":"Klik op de rode knop.","exDe":"Klick auf den roten Knopf."},{"de":"harmonieren, sich sofort gut verstehen (es funkt)","ex":"Het klikt meteen tussen ons.","exDe":"Es funkt sofort zwischen uns."},{"de":"klicken, einrasten (Geräusch)","ex":"De deur klikt in het slot.","exDe":"Die Tür rastet mit einem Klicken ins Schloss."}],"usage":"Regelmäßiges Verb; im Computer-/Internetkontext meist mit voorzetsel: klikken op iets.","conjugation":{"presens":{"ik":"klik","jij":"klikt","hij":"klikt","wij":"klikken"},"imperfectum":{"ik":"klikte","wij":"klikten"},"perfectum":{"aux":"hebben","participle":"geklikt"}},"illustratable":true},"bk_1254":{"lemma":"typen","displayNl":"typen","pos":"werkwoord","meanings":[{"de":"tippen, auf der Tastatur schreiben","ex":"Ik typ heel snel.","exDe":"Ich tippe sehr schnell."}],"usage":"Regelmäßiges Verb; die ik-Form wird auch 'ik type' geschrieben.","conjugation":{"presens":{"ik":"typ","jij":"typt","hij":"typt","wij":"typen"},"imperfectum":{"ik":"typte","wij":"typten"},"perfectum":{"aux":"hebben","participle":"getypt"}},"illustratable":true},"bk_1255":{"lemma":"inloggen","displayNl":"inloggen","pos":"werkwoord","meanings":[{"de":"sich einloggen, sich anmelden (am System)","ex":"Ik kan niet inloggen.","exDe":"Ich kann mich nicht einloggen."}],"usage":"Trennbares Verb (in + loggen); die Vorsilbe rückt ans Satzende: 'ik log in'.","conjugation":{"presens":{"ik":"log in","jij":"logt in","hij":"logt in","wij":"loggen in"},"imperfectum":{"ik":"logde in","wij":"logden in"},"perfectum":{"aux":"hebben","participle":"ingelogd"}}},"bk_1256":{"lemma":"uitloggen","displayNl":"uitloggen","pos":"werkwoord","meanings":[{"de":"sich ausloggen, sich abmelden","ex":"Vergeet niet uit te loggen.","exDe":"Vergiss nicht, dich auszuloggen."}],"usage":"Trennbares Verb (uit + loggen); im te-Infinitiv 'uit te loggen'.","conjugation":{"presens":{"ik":"log uit","jij":"logt uit","hij":"logt uit","wij":"loggen uit"},"imperfectum":{"ik":"logde uit","wij":"logden uit"},"perfectum":{"aux":"hebben","participle":"uitgelogd"}}},"bk_1257":{"lemma":"aanmelden","displayNl":"aanmelden","pos":"werkwoord","meanings":[{"de":"sich anmelden, sich registrieren","ex":"Je moet je eerst aanmelden.","exDe":"Du musst dich zuerst anmelden."},{"de":"(jemanden/etwas) anmelden, für etwas eintragen","ex":"Ik meld mijn zoon aan voor de cursus.","exDe":"Ich melde meinen Sohn für den Kurs an."}],"usage":"Trennbares Verb (aan + melden); reflexiv 'zich aanmelden' (ik meld me aan).","conjugation":{"presens":{"ik":"meld aan","jij":"meldt aan","hij":"meldt aan","wij":"melden aan"},"imperfectum":{"ik":"meldde aan","wij":"meldden aan"},"perfectum":{"aux":"hebben","participle":"aangemeld"}}},"bk_1258":{"lemma":"delen","displayNl":"delen","pos":"werkwoord","meanings":[{"de":"teilen, gemeinsam nutzen / weitergeben","ex":"Wil je de foto delen?","exDe":"Willst du das Foto teilen?"},{"de":"teilen, dividieren (Mathematik)","ex":"Tien gedeeld door twee is vijf.","exDe":"Zehn geteilt durch zwei ist fünf."},{"de":"aufteilen, sich etwas teilen","ex":"We delen de kosten.","exDe":"Wir teilen uns die Kosten."}],"usage":"Regelmäßiges Verb; 'delen door' = dividieren durch, 'iets delen met' = etwas teilen mit.","conjugation":{"presens":{"ik":"deel","jij":"deelt","hij":"deelt","wij":"delen"},"imperfectum":{"ik":"deelde","wij":"deelden"},"perfectum":{"aux":"hebben","participle":"gedeeld"}}},"bk_1259":{"lemma":"chatten","displayNl":"chatten","pos":"werkwoord","meanings":[{"de":"chatten, online plaudern","ex":"Wij chatten elke dag.","exDe":"Wir chatten jeden Tag."}],"usage":"Regelmäßiges Verb (Anglizismus); Stamm endet auf -t, daher jij/hij 'chat' ohne zweites t.","conjugation":{"presens":{"ik":"chat","jij":"chat","hij":"chat","wij":"chatten"},"imperfectum":{"ik":"chatte","wij":"chatten"},"perfectum":{"aux":"hebben","participle":"gechat"}}},"bk_1260":{"lemma":"appen","displayNl":"appen","pos":"werkwoord","meanings":[{"de":"eine (WhatsApp-)Nachricht schicken, jemandem schreiben","ex":"Ik app je vanavond.","exDe":"Ich schreibe dir heute Abend."}],"usage":"Regelmäßiges Verb (umgangssprachlich, von 'app'); oft mit Dativobjekt: iemand appen.","conjugation":{"presens":{"ik":"app","jij":"appt","hij":"appt","wij":"appen"},"imperfectum":{"ik":"appte","wij":"appten"},"perfectum":{"aux":"hebben","participle":"geappt"}}},"bk_1261":{"lemma":"streamen","displayNl":"streamen","pos":"werkwoord","meanings":[{"de":"streamen (Medien über das Internet abspielen)","ex":"Wij streamen elke avond een serie.","exDe":"Wir streamen jeden Abend eine Serie."}],"usage":"Leenwoord uit het Engels; wordt zwak vervoegd. Gebruikelijk voor films, series en muziek via internet.","conjugation":{"presens":{"ik":"stream","jij":"streamt","hij":"streamt","wij":"streamen"},"imperfectum":{"ik":"streamde","wij":"streamden"},"perfectum":{"aux":"hebben","participle":"gestreamd"}}},"bk_1262":{"lemma":"opladen","displayNl":"opladen","pos":"werkwoord","meanings":[{"de":"aufladen (Akku, Handy, Batterie elektrisch laden)","ex":"Ik moet mijn telefoon opladen.","exDe":"Ich muss mein Handy aufladen."},{"de":"aufladen / verladen (etwas auf ein Fahrzeug laden)","ex":"De mannen laden de dozen op de vrachtwagen op.","exDe":"Die Männer laden die Kisten auf den Lastwagen."}],"usage":"Scheidbaar werkwoord (op + laden): 'Ik laad mijn telefoon op'. Voltooid deelwoord 'opgeladen'.","conjugation":{"presens":{"ik":"laad op","jij":"laadt op","hij":"laadt op","wij":"laden op"},"imperfectum":{"ik":"laadde op","wij":"laadden op"},"perfectum":{"aux":"hebben","participle":"opgeladen"}},"illustratable":true},"bk_1263":{"lemma":"uitzenden","displayNl":"uitzenden","pos":"werkwoord","meanings":[{"de":"senden / ausstrahlen (im Radio oder Fernsehen)","ex":"Ze zenden de wedstrijd live uit.","exDe":"Sie übertragen das Spiel live."},{"de":"aussenden / entsenden (Personen oder Signale ausschicken)","ex":"De organisatie zendt vrijwilligers uit naar het buitenland.","exDe":"Die Organisation entsendet Freiwillige ins Ausland."}],"usage":"Scheidbaar en onregelmatig werkwoord (zenden - zond - gezonden): 'Ze zenden het programma uit'.","conjugation":{"presens":{"ik":"zend uit","jij":"zendt uit","hij":"zendt uit","wij":"zenden uit"},"imperfectum":{"ik":"zond uit","wij":"zonden uit"},"perfectum":{"aux":"hebben","participle":"uitgezonden"}}},"bk_1264":{"lemma":"zoekmachine","displayNl":"de zoekmachine","pos":"substantief","meanings":[{"de":"die Suchmaschine (Programm zum Suchen im Internet)","ex":"Ik gebruik een zoekmachine om informatie te vinden.","exDe":"Ich benutze eine Suchmaschine, um Informationen zu finden."}],"usage":"De-woord, meervoud 'zoekmachines'. Samenstelling van 'zoeken' en 'machine'.","genus":"de","plural":"zoekmachines"},"bk_1265":{"lemma":"browser","displayNl":"de browser","pos":"substantief","meanings":[{"de":"der Browser (Programm zum Anzeigen von Webseiten)","ex":"Open de browser even.","exDe":"Öffne kurz den Browser."}],"usage":"Leenwoord uit het Engels, de-woord, meervoud 'browsers'.","genus":"de","plural":"browsers"},"bk_1266":{"lemma":"wifi","displayNl":"de wifi","pos":"substantief","meanings":[{"de":"das WLAN (drahtloses Internet)","ex":"Is hier gratis wifi?","exDe":"Gibt es hier kostenloses WLAN?"}],"usage":"Meestal de-woord ('de wifi'); als niet-telbaar begrip zonder meervoud. Ook gespeld als 'wifi' of 'wi-fi'. Let op: het Duitse woord is 'das WLAN'.","genus":"de"},"bk_1267":{"lemma":"code","displayNl":"de code","pos":"substantief","meanings":[{"de":"der Code / die Zahlenkombination (z. B. PIN, Zugangscode)","ex":"Voer de code in.","exDe":"Gib den Code ein."},{"de":"der Quellcode (Programmierung)","ex":"De programmeur schrijft nieuwe code.","exDe":"Der Programmierer schreibt neuen Code."},{"de":"der Kodex / das Regelwerk","ex":"Het bedrijf heeft een strenge code voor werknemers.","exDe":"Das Unternehmen hat einen strengen Kodex für Mitarbeiter."}],"usage":"De-woord, meervoud 'codes'. Meerdere betekenissen afhankelijk van context (toegangscode, programmeercode, gedragscode).","genus":"de","plural":"codes"},"bk_1268":{"lemma":"update","displayNl":"de update","pos":"substantief","meanings":[{"de":"das Update / die Aktualisierung (neuere Version von Software)","ex":"Er is een nieuwe update.","exDe":"Es gibt ein neues Update."},{"de":"das Update / die aktuelle Information (Stand der Dinge)","ex":"Kun je me een update geven over het project?","exDe":"Kannst du mir ein Update zum Projekt geben?"}],"usage":"Leenwoord uit het Engels, de-woord, meervoud 'updates'.","genus":"de","plural":"updates"},"bk_1269":{"lemma":"versie","displayNl":"de versie","pos":"substantief","meanings":[{"de":"die Version, die Ausgabe (Software, Dokument)","ex":"Dit is de nieuwste versie van de app.","exDe":"Das ist die neueste Version der App."},{"de":"die Fassung, die Variante (einer Geschichte, eines Ereignisses)","ex":"Zij vertelde haar eigen versie van het verhaal.","exDe":"Sie erzählte ihre eigene Fassung der Geschichte."}],"usage":"Neutraal, alledaags en zeer gangbaar in technische en algemene context (software, teksten, verhalen).","genus":"de","plural":"versies"},"bk_1270":{"lemma":"instelling","displayNl":"de instelling","pos":"substantief","meanings":[{"de":"die Einstellung (eines Geräts, Programms)","ex":"Ik verander een instelling op mijn telefoon.","exDe":"Ich ändere eine Einstellung auf meinem Handy."},{"de":"die Einrichtung, die Institution","ex":"Zij werkt bij een medische instelling.","exDe":"Sie arbeitet bei einer medizinischen Einrichtung."},{"de":"die Einstellung, die Haltung (innere Disposition)","ex":"Hij heeft een positieve instelling.","exDe":"Er hat eine positive Einstellung."}],"usage":"Gangbaar; betekenis blijkt uit de context (techniek, houding of organisatie).","genus":"de","plural":"instellingen"},"bk_1271":{"lemma":"melding","displayNl":"de melding","pos":"substantief","meanings":[{"de":"die Benachrichtigung, die Meldung (auf einem Gerät)","ex":"Ik krijg een melding op mijn scherm.","exDe":"Ich bekomme eine Benachrichtigung auf meinem Bildschirm."},{"de":"die Meldung, die Anzeige (etwas offiziell mitteilen/melden)","ex":"Hij deed een melding bij de politie.","exDe":"Er erstattete eine Meldung bei der Polizei."}],"usage":"Alledaags, vooral rond apps, telefoons en officiële meldingen.","genus":"de","plural":"meldingen"},"bk_1272":{"lemma":"abonnement","displayNl":"het abonnement","pos":"substantief","meanings":[{"de":"das Abonnement, das Abo","ex":"Ik heb een abonnement voor films en series.","exDe":"Ich habe ein Abo für Filme und Serien."},{"de":"die Zeitkarte, das Zeitticket (Nahverkehr)","ex":"Met mijn abonnement reis ik gratis met de bus.","exDe":"Mit meiner Zeitkarte fahre ich kostenlos mit dem Bus."}],"usage":"Zeer gangbaar (streamingdiensten, openbaar vervoer, kranten, sportschool).","genus":"het","plural":"abonnementen"},"bk_1273":{"lemma":"gebruikersnaam","displayNl":"de gebruikersnaam","pos":"substantief","meanings":[{"de":"der Benutzername","ex":"Wat is je gebruikersnaam?","exDe":"Was ist dein Benutzername?"}],"usage":"Standaardvorm is 'gebruikersnaam' (met -s-); de invoer 'gebruiksnaam' is een veelvoorkomende schrijffout en gecorrigeerd.","genus":"de","plural":"gebruikersnamen","notes":"Eingabe 'gebruiksnaam' orthografisch korrigiert zu 'gebruikersnaam'."},"bk_1274":{"lemma":"smart-tv","displayNl":"de smart-tv","pos":"substantief","meanings":[{"de":"der Smart-TV, der Smart-Fernseher","ex":"Wij hebben een nieuwe smart-tv in de woonkamer.","exDe":"Wir haben einen neuen Smart-TV im Wohnzimmer."}],"usage":"Alledaags leenwoord; meervoud met apostrof-s ('smart-tv's').","genus":"de","plural":"smart-tv's","illustratable":true},"bk_1275":{"lemma":"afstandsbediening","displayNl":"de afstandsbediening","pos":"substantief","meanings":[{"de":"die Fernbedienung","ex":"Waar is de afstandsbediening van de tv?","exDe":"Wo ist die Fernbedienung des Fernsehers?"}],"usage":"Alledaags huishoudwoord.","genus":"de","plural":"afstandsbedieningen","illustratable":true},"bk_1276":{"lemma":"stekker","displayNl":"de stekker","pos":"substantief","meanings":[{"de":"der Stecker, der Netzstecker","ex":"Doe de stekker in het stopcontact.","exDe":"Steck den Stecker in die Steckdose."}],"usage":"Alledaags; ook figuurlijk 'de stekker eruit trekken' (iets stopzetten).","genus":"de","plural":"stekkers","illustratable":true},"bk_1277":{"lemma":"apparatuur","displayNl":"de apparatuur","pos":"substantief","meanings":[{"de":"die Ausrüstung, die (technischen) Geräte (als Gesamtheit)","ex":"De apparatuur in de studio is heel duur.","exDe":"Die Ausrüstung im Studio ist sehr teuer."},{"de":"die Anlage, die Apparatur (technische Geräte für einen Zweck)","ex":"De medische apparatuur werd zorgvuldig gecontroleerd.","exDe":"Die medizinische Apparatur wurde sorgfältig überprüft."}],"usage":"Sammelbegriff (Massennomen) für Geräte/Ausrüstung; meist ohne Plural. Einzelnes Gerät = het apparaat.","genus":"de","illustratable":true},"bk_1278":{"lemma":"apparaat","displayNl":"het apparaat","pos":"substantief","meanings":[{"de":"das Gerät, der Apparat (technisches Einzelgerät)","ex":"Dit apparaat is makkelijk te gebruiken.","exDe":"Dieses Gerät ist leicht zu benutzen."},{"de":"der Apparat (Behörden-, Partei- oder Verwaltungsapparat)","ex":"Het ambtelijke apparaat werkt vaak traag.","exDe":"Der Behördenapparat arbeitet oft langsam."}],"usage":"Einzelnes technisches Gerät (het-Wort). Für Geräte als Gesamtheit: de apparatuur.","genus":"het","plural":"apparaten","illustratable":true},"bk_1279":{"lemma":"beeld","displayNl":"het beeld","pos":"substantief","meanings":[{"de":"das Bild (auf Bildschirm/Foto), die Aufnahme","ex":"Het beeld op de tv is scherp.","exDe":"Das Bild im Fernsehen ist scharf."},{"de":"die Statue, die Skulptur, das Standbild","ex":"Op het plein staat een groot bronzen beeld.","exDe":"Auf dem Platz steht eine große bronzene Statue."},{"de":"die Vorstellung, das (geistige) Bild, das Image","ex":"Ik heb een duidelijk beeld van de situatie.","exDe":"Ich habe eine klare Vorstellung von der Situation."}],"usage":"het-Wort, Plural beelden. Zahlreiche Bedeutungen: Bild/Aufnahme, Statue, Vorstellung/Image.","genus":"het","plural":"beelden","illustratable":true},"bk_1280":{"lemma":"kopie","displayNl":"de kopie","pos":"substantief","meanings":[{"de":"die Kopie, die Vervielfältigung (Duplikat eines Dokuments)","ex":"Maak een kopie van het bestand.","exDe":"Mach eine Kopie der Datei."},{"de":"die Abschrift, die Reproduktion, das Duplikat","ex":"Dit schilderij is slechts een kopie van het origineel.","exDe":"Dieses Gemälde ist nur eine Kopie des Originals."}],"usage":"de-Wort, Plural kopieën (mit Trema). Duplikat gegenüber het origineel.","genus":"de","plural":"kopieën"},"bk_1281":{"lemma":"reactie","displayNl":"de reactie","pos":"substantief","meanings":[{"de":"die Reaktion (Antwortverhalten auf etwas)","ex":"Zijn reactie was heel rustig.","exDe":"Seine Reaktion war sehr ruhig."},{"de":"der Kommentar (unter einem Beitrag/Video)","ex":"Hij schrijft een reactie onder de video.","exDe":"Er schreibt einen Kommentar unter das Video."},{"de":"die chemische Reaktion","ex":"Bij deze reactie ontstaat warmte.","exDe":"Bei dieser Reaktion entsteht Wärme."}],"usage":"de-Wort, Plural reacties. Bedeutet Reaktion, Online-Kommentar und chemische Reaktion.","genus":"de","plural":"reacties"},"bk_1282":{"lemma":"digitaal","displayNl":"digitaal","pos":"adjectief","meanings":[{"de":"digital (in Datenform, elektronisch)","ex":"Alles is nu digitaal.","exDe":"Alles ist jetzt digital."},{"de":"digital (adverbial: auf digitalem Weg)","ex":"Je kunt de kaartjes digitaal kopen.","exDe":"Du kannst die Tickets digital kaufen."}],"usage":"Adjektiv/Adverb; Gegensatz analoog. Attributiv flektiert: het digitale bestand."},"bk_1283":{"lemma":"draadloos","displayNl":"draadloos","pos":"adjectief","meanings":[{"de":"drahtlos, kabellos (ohne Kabelverbindung)","ex":"De koptelefoon is draadloos.","exDe":"Der Kopfhörer ist kabellos."}],"usage":"Adjektiv/Adverb; attributiv flektiert: een draadloze verbinding. Von draad (Draht) + -loos."},"bk_1284":{"lemma":"jaloers","displayNl":"jaloers","pos":"adjectief","meanings":[{"de":"eifersüchtig","ex":"Hij is jaloers op zijn broer.","exDe":"Er ist eifersüchtig auf seinen Bruder."},{"de":"neidisch (auf etwas/jemanden)","ex":"Ze is jaloers op mijn nieuwe fiets.","exDe":"Sie ist neidisch auf mein neues Fahrrad."}],"usage":"Adjektiv; feste Präposition: jaloers op (eifersüchtig/neidisch auf). Attributiv: een jaloerse blik."},"bk_1285":{"lemma":"verbaasd","displayNl":"verbaasd","pos":"adjectief","meanings":[{"de":"erstaunt","ex":"Zij was verbaasd over het nieuws.","exDe":"Sie war erstaunt über die Nachricht."},{"de":"verwundert","ex":"Ik keek hem verbaasd aan.","exDe":"Ich sah ihn verwundert an."}],"usage":"Prädikativ meist mit 'over' (verbaasd over iets). Attributiv: een verbaasde blik."},"bk_1286":{"lemma":"verrast","displayNl":"verrast","pos":"adjectief","meanings":[{"de":"überrascht","ex":"Ik ben echt verrast!","exDe":"Ich bin wirklich überrascht!"},{"de":"überrumpelt","ex":"De dief werd op heterdaad verrast.","exDe":"Der Dieb wurde auf frischer Tat überrumpelt."}],"usage":"Prädikativ oft mit 'door' (verrast door iets/iemand). Partizip von 'verrassen'."},"bk_1287":{"lemma":"teleurgesteld","displayNl":"teleurgesteld","pos":"adjectief","meanings":[{"de":"enttäuscht","ex":"Hij is teleurgesteld in mij.","exDe":"Er ist von mir enttäuscht."}],"usage":"Über Personen mit 'in' (teleurgesteld in iemand), über Sachen mit 'over' (teleurgesteld over iets)."},"bk_1288":{"lemma":"tevreden","displayNl":"tevreden","pos":"adjectief","meanings":[{"de":"zufrieden","ex":"De baas is tevreden over het werk.","exDe":"Der Chef ist mit der Arbeit zufrieden."},{"de":"genügsam, zufrieden (Wesen)","ex":"Zij is een tevreden mens.","exDe":"Sie ist ein zufriedener Mensch."}],"usage":"Prädikativ mit 'over' (tevreden over iets) oder 'met' (tevreden met iets)."},"bk_1289":{"lemma":"ontevreden","displayNl":"ontevreden","pos":"adjectief","meanings":[{"de":"unzufrieden","ex":"De klant is ontevreden.","exDe":"Der Kunde ist unzufrieden."}],"usage":"Gegenteil von 'tevreden'; mit 'over' oder 'met'."},"bk_1290":{"lemma":"eenzaam","displayNl":"eenzaam","pos":"adjectief","meanings":[{"de":"einsam","ex":"Hij voelt zich vaak eenzaam.","exDe":"Er fühlt sich oft einsam."},{"de":"abgelegen, verlassen (Ort)","ex":"Het huis staat op een eenzame plek.","exDe":"Das Haus steht an einem abgelegenen Ort."}],"usage":"Über Menschen (Gefühl) und über Orte (abgelegen). Substantiv: eenzaamheid."},"bk_1291":{"lemma":"gespannen","displayNl":"gespannen","pos":"adjectief","meanings":[{"de":"angespannt, nervös","ex":"Ze is gespannen voor het gesprek.","exDe":"Sie ist angespannt vor dem Gespräch."},{"de":"gespannt (straff gezogen)","ex":"Het touw stond strak gespannen.","exDe":"Das Seil war straff gespannt."},{"de":"gespannt (angespannte Lage/Beziehung)","ex":"De sfeer was gespannen.","exDe":"Die Stimmung war angespannt."}],"usage":"Partizip von 'spannen'; als Adjektiv sowohl über Gefühle als auch physisch (straff)."},"bk_1292":{"lemma":"kalm","displayNl":"kalm","pos":"adjectief","meanings":[{"de":"ruhig, gelassen","ex":"Zij bleef heel kalm.","exDe":"Sie blieb ganz gelassen."},{"de":"still, ruhig (See/Wetter)","ex":"De zee was kalm.","exDe":"Das Meer war ruhig."}],"usage":"Über Menschen (gelassen) und über Natur (windstill). Adverb: 'blijf kalm!' = bleib ruhig!"},"bk_1293":{"lemma":"geduldig","displayNl":"geduldig","pos":"adjectief","meanings":[{"de":"geduldig","ex":"De leraar is heel geduldig met de kinderen.","exDe":"Der Lehrer ist sehr geduldig mit den Kindern."},{"de":"nachsichtig, ruhig abwartend","ex":"Wees geduldig, het komt allemaal goed.","exDe":"Sei geduldig, es wird alles gut."}],"usage":"Eigenschaftswort; attributiv flektiert 'de geduldige leraar'. Steigerung geduldiger, geduldigst."},"bk_1294":{"lemma":"ongeduldig","displayNl":"ongeduldig","pos":"adjectief","meanings":[{"de":"ungeduldig","ex":"Kinderen zijn vaak ongeduldig als ze moeten wachten.","exDe":"Kinder sind oft ungeduldig, wenn sie warten müssen."},{"de":"unruhig, drängend","ex":"Hij tikte ongeduldig met zijn vingers op tafel.","exDe":"Er trommelte ungeduldig mit den Fingern auf den Tisch."}],"usage":"Verneinung von 'geduldig' mit Präfix on-. Attributiv 'het ongeduldige kind'."},"bk_1295":{"lemma":"eerlijk","displayNl":"eerlijk","pos":"adjectief","meanings":[{"de":"ehrlich, aufrichtig","ex":"Wees altijd eerlijk tegen mij.","exDe":"Sei immer ehrlich zu mir."},{"de":"fair, gerecht","ex":"Dat is een eerlijke verdeling van het werk.","exDe":"Das ist eine faire Aufteilung der Arbeit."},{"de":"offen gesagt (als Adverb: eerlijk gezegd)","ex":"Eerlijk gezegd vind ik het niet leuk.","exDe":"Ehrlich gesagt finde ich es nicht schön."}],"usage":"Adjektiv/Adverb. Feste Wendung 'eerlijk gezegd' = ehrlich gesagt. Steigerung eerlijker, eerlijkst."},"bk_1296":{"lemma":"oneerlijk","displayNl":"oneerlijk","pos":"adjectief","meanings":[{"de":"unfair, ungerecht","ex":"Dat is oneerlijk, hij krijgt meer dan ik!","exDe":"Das ist unfair, er bekommt mehr als ich!"},{"de":"unehrlich, unaufrichtig","ex":"Het is oneerlijk om te liegen.","exDe":"Es ist unehrlich zu lügen."}],"usage":"Verneinung von 'eerlijk' mit Präfix on-. Attributiv 'een oneerlijke deal'."},"bk_1297":{"lemma":"onvriendelijk","displayNl":"onvriendelijk","pos":"adjectief","meanings":[{"de":"unfreundlich","ex":"De verkoper was heel onvriendelijk tegen ons.","exDe":"Der Verkäufer war sehr unfreundlich zu uns."},{"de":"unwirtlich, unangenehm (z. B. Wetter, Umgebung)","ex":"Het was koud en onvriendelijk weer.","exDe":"Es war kaltes und ungemütliches Wetter."}],"usage":"Verneinung von 'vriendelijk' mit Präfix on-. Attributiv 'een onvriendelijke blik'."},"bk_1298":{"lemma":"brutaal","displayNl":"brutaal","pos":"adjectief","meanings":[{"de":"frech, dreist","ex":"Dat kind is heel brutaal tegen zijn moeder.","exDe":"Das Kind ist sehr frech zu seiner Mutter."},{"de":"unverschämt, kühn","ex":"Hij gaf een brutaal antwoord.","exDe":"Er gab eine unverschämte Antwort."}],"usage":"Achtung: 'brutaal' bedeutet NICHT 'brutal' (nl. 'wreed/gewelddadig'). Attributiv 'een brutale opmerking'.","notes":"Falscher Freund: nl. brutaal = dt. frech, nicht 'brutal'."},"bk_1299":{"lemma":"lui","displayNl":"lui","pos":"adjectief","meanings":[{"de":"faul, träge","ex":"In het weekend ben ik graag lui.","exDe":"Am Wochenende bin ich gerne faul."},{"de":"bequem, trge (Person die nichts tun mag)","ex":"Doe niet zo lui, help even mee!","exDe":"Sei nicht so faul, hilf mal mit!"}],"usage":"Adjektiv; attributiv 'een luie kat'. Homonym: 'lui' auch veraltet/umgangssprachlich 'Leute' (die lui), hier aber Eigenschaft."},"bk_1300":{"lemma":"ijverig","displayNl":"ijverig","pos":"adjectief","meanings":[{"de":"fleißig, eifrig","ex":"Zij is een ijverige student.","exDe":"Sie ist eine fleißige Studentin."},{"de":"strebsam, emsig","ex":"De kinderen werkten ijverig aan hun opdracht.","exDe":"Die Kinder arbeiteten eifrig an ihrer Aufgabe."}],"usage":"Adjektiv/Adverb; attributiv 'een ijverige leerling'. Steigerung ijveriger, ijverigst."},"bk_1301":{"lemma":"zelfverzekerd","displayNl":"zelfverzekerd","pos":"adjectief","meanings":[{"de":"selbstbewusst, selbstsicher","ex":"Hij is heel zelfverzekerd.","exDe":"Er ist sehr selbstbewusst."},{"de":"souverän, selbstsicher auftretend","ex":"Ze gaf een zelfverzekerde presentatie.","exDe":"Sie hielt eine selbstsichere Präsentation."}],"usage":"Beschreibt eine Person mit Selbstvertrauen. Steigerung: zelfverzekerder, meest zelfverzekerd."},"bk_1302":{"lemma":"onzeker","displayNl":"onzeker","pos":"adjectief","meanings":[{"de":"unsicher (von einer Person)","ex":"Ik ben onzeker over mijn keuze.","exDe":"Ich bin unsicher über meine Wahl."},{"de":"ungewiss, unsicher (von einer Situation/Zukunft)","ex":"De toekomst is onzeker.","exDe":"Die Zukunft ist ungewiss."}],"usage":"Gegenteil von 'zeker'. Für Personen (mangelndes Selbstvertrauen) und für ungewisse Sachverhalte."},"bk_1303":{"lemma":"vrijgevig","displayNl":"vrijgevig","pos":"adjectief","meanings":[{"de":"großzügig, freigebig","ex":"Mijn oma is heel vrijgevig.","exDe":"Meine Oma ist sehr großzügig."}],"usage":"Beschreibt jemanden, der gerne gibt/schenkt. Gegenteil: gierig."},"bk_1304":{"lemma":"gierig","displayNl":"gierig","pos":"adjectief","meanings":[{"de":"geizig, knauserig","ex":"Hij is te gierig om te betalen.","exDe":"Er ist zu geizig, um zu zahlen."}],"usage":"Achtung falscher Freund: nl. 'gierig' = dt. 'geizig' (nicht 'gierig'). Gegenteil: vrijgevig."},"bk_1305":{"lemma":"nieuwsgierig","displayNl":"nieuwsgierig","pos":"adjectief","meanings":[{"de":"neugierig, wissbegierig","ex":"Katten zijn erg nieuwsgierig.","exDe":"Katzen sind sehr neugierig."}],"usage":"Wörtlich 'begierig auf Neuigkeiten'. Für Personen und Tiere."},"bk_1306":{"lemma":"voorzichtig","displayNl":"voorzichtig","pos":"adjectief","meanings":[{"de":"vorsichtig, behutsam","ex":"Wees voorzichtig op de weg.","exDe":"Sei vorsichtig auf der Straße."},{"de":"behutsam, vorsichtig (adverbial: sachte)","ex":"Hij zette het glas voorzichtig neer.","exDe":"Er stellte das Glas behutsam ab."}],"usage":"Adjektiv und Adverb. Aufforderung: 'Wees voorzichtig!' = 'Sei vorsichtig!'."},"bk_1307":{"lemma":"serieus","displayNl":"serieus","pos":"adjectief","meanings":[{"de":"ernst, ernsthaft","ex":"Ben je serieus?","exDe":"Bist du ernsthaft?"},{"de":"seriös, ernst zu nehmen","ex":"Dat is een serieus probleem.","exDe":"Das ist ein ernstes Problem."}],"usage":"Beschreibt Personen (ernsthaft) wie auch Sachen (seriös/ernst). 'iets serieus nemen' = etwas ernst nehmen."},"bk_1308":{"lemma":"saai","displayNl":"saai","pos":"adjectief","meanings":[{"de":"langweilig, fad","ex":"De film was heel saai.","exDe":"Der Film war sehr langweilig."}],"usage":"Für Personen, Dinge und Situationen, die keine Abwechslung bieten. Gegenteil: spannend, leuk."},"bk_1309":{"lemma":"interessant","displayNl":"interessant","pos":"adjectief","meanings":[{"de":"interessant, spannend","ex":"Dat is een interessant boek.","exDe":"Das ist ein interessantes Buch."},{"de":"attraktiv, vorteilhaft (z. B. Angebot, Preis)","ex":"Ze deden ons een interessant aanbod.","exDe":"Sie machten uns ein attraktives Angebot."}],"usage":"Attributiv wird meist eine -e-Endung angehängt (een interessante film), außer bei het-Wörtern im unbestimmten Singular (een interessant boek)."},"bk_1311":{"lemma":"verschrikkelijk","displayNl":"verschrikkelijk","pos":"adjectief","meanings":[{"de":"schrecklich, furchtbar, entsetzlich","ex":"Het weer is verschrikkelijk.","exDe":"Das Wetter ist schrecklich."},{"de":"furchtbar, sehr (verstärkend, als Adverb)","ex":"Ik ben verschrikkelijk moe.","exDe":"Ich bin furchtbar müde."}],"usage":"Auch als verstärkendes Adverb gebräuchlich (verschrikkelijk duur = schrecklich teuer)."},"bk_1312":{"lemma":"prima","displayNl":"prima","pos":"adjectief","meanings":[{"de":"prima, ausgezeichnet, erstklassig","ex":"Dat is prima voor mij.","exDe":"Das ist prima für mich."},{"de":"in Ordnung, einverstanden (als Zustimmung)","ex":"Prima, dan doen we het zo.","exDe":"In Ordnung, dann machen wir es so."}],"usage":"Unveränderlich, bekommt keine -e-Endung: een prima idee, een prima oplossing."},"bk_1313":{"lemma":"vreemd","displayNl":"vreemd","pos":"adjectief","meanings":[{"de":"seltsam, merkwürdig, komisch","ex":"Dat is een vreemd verhaal.","exDe":"Das ist eine seltsame Geschichte."},{"de":"fremd, unbekannt","ex":"Hij is hier een vreemde.","exDe":"Er ist hier ein Fremder."},{"de":"ausländisch, fremd (Sprachen, Länder)","ex":"Ze spreekt drie vreemde talen.","exDe":"Sie spricht drei Fremdsprachen."}],"usage":"Attributiv meist mit -e (een vreemde man); substantiviert 'een vreemde' = ein Fremder."},"bk_1314":{"lemma":"normaal","displayNl":"normaal","pos":"adjectief","meanings":[{"de":"normal, gewöhnlich, üblich","ex":"Dat is heel normaal.","exDe":"Das ist ganz normal."},{"de":"normalerweise, gewöhnlich (als Adverb, oft 'normaal gesproken')","ex":"Normaal gesproken werk ik thuis.","exDe":"Normalerweise arbeite ich zu Hause."}],"usage":"Als Adverb häufig in der Wendung 'normaal gesproken' (normalerweise)."},"bk_1315":{"lemma":"bezorgd","displayNl":"bezorgd","pos":"adjectief","meanings":[{"de":"besorgt, beunruhigt","ex":"Mijn moeder is bezorgd om mij.","exDe":"Meine Mutter ist besorgt um mich."}],"usage":"Wird mit 'om' oder 'over' verbunden (bezorgd om iemand, bezorgd over iets). Formgleich mit dem Partizip von 'bezorgen' (zustellen)."},"bk_1316":{"lemma":"opgelucht","displayNl":"opgelucht","pos":"adjectief","meanings":[{"de":"erleichtert","ex":"Ik ben opgelucht dat het voorbij is.","exDe":"Ich bin erleichtert, dass es vorbei ist."}],"usage":"Oft mit 'zich opgelucht voelen' (sich erleichtert fühlen); Partizip von 'opluchten'."},"bk_1317":{"lemma":"enthousiast","displayNl":"enthousiast","pos":"adjectief","meanings":[{"de":"begeistert, enthusiastisch","ex":"De kinderen zijn enthousiast.","exDe":"Die Kinder sind begeistert."},{"de":"Enthusiast, begeisterter Anhänger (als Substantiv, de-Wort)","ex":"Hij is een echte enthousiast.","exDe":"Er ist ein echter Enthusiast."}],"usage":"Meist Adjektiv (enthousiast over/voor iets = begeistert von etwas); als Substantiv 'de enthousiast', Plural 'enthousiasten'."},"bk_1318":{"lemma":"dankbaar","displayNl":"dankbaar","pos":"adjectief","meanings":[{"de":"dankbar (erfüllt von Dank)","ex":"Ik ben je heel dankbaar voor je hulp.","exDe":"Ich bin dir sehr dankbar für deine Hilfe."},{"de":"dankbar (lohnend, ergiebig)","ex":"Dat is een dankbaar onderwerp om over te schrijven.","exDe":"Das ist ein dankbares Thema, um darüber zu schreiben."}],"usage":"Prädikativ meist mit 'zijn' + Person (jou/je dankbaar) und 'voor' für den Anlass."},"bk_1319":{"lemma":"geïrriteerd","displayNl":"geïrriteerd","pos":"adjectief","meanings":[{"de":"genervt, gereizt, verärgert","ex":"Ik ben geïrriteerd door het lawaai.","exDe":"Ich bin vom Lärm genervt."},{"de":"gereizt (medizinisch: entzündet, wund)","ex":"Mijn huid is geïrriteerd door de zon.","exDe":"Meine Haut ist von der Sonne gereizt."}],"usage":"Partizip als Adjektiv; Auslöser mit 'door'. Achtung Trema: geïrriteerd."},"bk_1320":{"lemma":"vriendschappelijk","displayNl":"vriendschappelijk","pos":"adjectief","meanings":[{"de":"freundschaftlich","ex":"Het gesprek verliep in een vriendschappelijke sfeer.","exDe":"Das Gespräch verlief in einer freundschaftlichen Atmosphäre."},{"de":"freundschaftlich (Sport: Freundschafts-, ohne Wertung)","ex":"Ze speelden een vriendschappelijke wedstrijd.","exDe":"Sie spielten ein Freundschaftsspiel."}],"usage":"Beschreibt Beziehungen/Umgang; nicht mit 'vriendelijk' (=höflich, nett) verwechseln."},"bk_1321":{"lemma":"sympathiek","displayNl":"sympathiek","pos":"adjectief","meanings":[{"de":"sympathisch, ansprechend","ex":"Zij is een sympathieke vrouw.","exDe":"Sie ist eine sympathische Frau."},{"de":"ansprechend, gefällig (Idee, Vorschlag)","ex":"Dat is een sympathiek voorstel.","exDe":"Das ist ein sympathischer Vorschlag."}],"usage":"Falscher Freund-Warnung: 'sympathiek' = sympathisch, nicht 'mitfühlend' (das wäre 'meelevend')."},"bk_1322":{"lemma":"eigenwijs","displayNl":"eigenwijs","pos":"adjectief","meanings":[{"de":"eigensinnig, stur, dickköpfig","ex":"Hij is een eigenwijs kind.","exDe":"Er ist ein eigensinniges Kind."},{"de":"eigenwillig, unkonventionell (positiv: eigener Kopf)","ex":"Ze heeft een eigenwijze, eigen stijl.","exDe":"Sie hat einen eigenwilligen, ganz eigenen Stil."}],"usage":"Kann tadelnd (stur) oder anerkennend (eigenständig) gemeint sein, je nach Kontext."},"bk_1323":{"lemma":"netjes","displayNl":"netjes","pos":"adjectief","meanings":[{"de":"ordentlich, sauber, gepflegt","ex":"Zij is altijd netjes gekleed.","exDe":"Sie ist immer ordentlich gekleidet."},{"de":"anständig, gehörig, korrekt (Benehmen)","ex":"Gedraag je netjes bij oma.","exDe":"Benimm dich anständig bei Oma."},{"de":"ordentlich, ganz schön (verstärkend, umgangssprachlich)","ex":"Dat is een netje bedrag.","exDe":"Das ist ein ordentlicher Betrag."}],"usage":"Sowohl attributiv/prädikativ (adjektivisch) als auch adverbial ('netjes werken'). Verstärkend für 'anständig viel'."},"bk_1324":{"lemma":"slordig","displayNl":"slordig","pos":"adjectief","meanings":[{"de":"unordentlich, schlampig (Ordnung)","ex":"Zijn kamer is heel slordig.","exDe":"Sein Zimmer ist sehr unordentlich."},{"de":"nachlässig, schludrig (Arbeit, Sorgfalt)","ex":"Ze maakt slordige fouten in haar werk.","exDe":"Sie macht nachlässige Fehler in ihrer Arbeit."}],"usage":"Adjektivisch und adverbial ('slordig werken'). Gegenteil von 'netjes'/'zorgvuldig'."},"bk_1325":{"lemma":"emotie","displayNl":"de emotie","pos":"substantief","meanings":[{"de":"die Emotion, das Gefühl","ex":"Zij toont haar emoties niet.","exDe":"Sie zeigt ihre Emotionen nicht."},{"de":"die Rührung, Gefühlsregung (emotionaler Aufruhr)","ex":"Zijn stem trilde van emotie.","exDe":"Seine Stimme zitterte vor Rührung."}],"usage":"de-Wort; Plural 'emoties'. Achtung Trema entfällt (emotie, nicht geïrriteerd-Muster).","genus":"de","plural":"emoties"},"bk_1326":{"lemma":"stemming","displayNl":"de stemming","pos":"substantief","meanings":[{"de":"die Stimmung, die Laune","ex":"De stemming is vandaag goed.","exDe":"Die Stimmung ist heute gut."},{"de":"die Stimmung, die Atmosphäre","ex":"Er hing een gezellige stemming in het café.","exDe":"Im Café herrschte eine gemütliche Stimmung."},{"de":"die Abstimmung, die Wahl","ex":"De stemming over de wet is morgen.","exDe":"Die Abstimmung über das Gesetz ist morgen."}],"usage":"Abstraktes Substantiv (de-Wort). Für Gefühlslage einer Person oder Atmosphäre eines Ortes; ebenso für das Abstimmen (Wahl).","genus":"de","plural":"stemmingen"},"bk_1327":{"lemma":"humeur","displayNl":"het humeur","pos":"substantief","meanings":[{"de":"die Laune, die Stimmung","ex":"Hij heeft een slecht humeur.","exDe":"Er hat schlechte Laune."},{"de":"die Gemütslage, das Temperament","ex":"Zij is altijd in een goed humeur.","exDe":"Sie ist immer gut gelaunt."}],"usage":"Abstraktes het-Wort für die momentane Gemütsverfassung. Feste Wendung: in een goed/slecht humeur zijn.","genus":"het","plural":"humeuren"},"bk_1328":{"lemma":"angst","displayNl":"de angst","pos":"substantief","meanings":[{"de":"die Angst, die Furcht","ex":"Zij heeft angst voor spinnen.","exDe":"Sie hat Angst vor Spinnen."},{"de":"die Beklemmung, das Bangen","ex":"In doodsangst rende hij naar buiten.","exDe":"In Todesangst rannte er nach draußen."}],"usage":"Abstraktes de-Wort. Konstruktion: angst hebben/voelen voor iets. Nicht mit dem Adverb 'bang' (ängstlich) verwechseln.","genus":"de","plural":"angsten"},"bk_1329":{"lemma":"vreugde","displayNl":"de vreugde","pos":"substantief","meanings":[{"de":"die Freude","ex":"Wat een vreugde om je te zien!","exDe":"Was für eine Freude, dich zu sehen!"},{"de":"das Vergnügen, die Wonne","ex":"De kinderen sprongen van vreugde.","exDe":"Die Kinder sprangen vor Freude."}],"usage":"Abstraktes de-Wort, gehobener als 'blijdschap'. Wendung: van vreugde (vor Freude).","genus":"de","plural":"vreugden"},"bk_1330":{"lemma":"karakter","displayNl":"het karakter","pos":"substantief","meanings":[{"de":"der Charakter, das Wesen","ex":"Zij heeft een sterk karakter.","exDe":"Sie hat einen starken Charakter."},{"de":"die Eigenart, das Gepräge","ex":"De wijk heeft een landelijk karakter.","exDe":"Das Viertel hat einen ländlichen Charakter."},{"de":"das Schriftzeichen","ex":"Chinees heeft duizenden karakters.","exDe":"Chinesisch hat Tausende von Schriftzeichen."}],"usage":"Abstraktes het-Wort für Persönlichkeit oder Eigenart; in der Bedeutung Schriftzeichen konkreter, aber typografisch, daher nicht bildlich eindeutig.","genus":"het","plural":"karakters"},"bk_1331":{"lemma":"hoop","displayNl":"de hoop","pos":"substantief","meanings":[{"de":"die Hoffnung","ex":"Ik heb nog hoop.","exDe":"Ich habe noch Hoffnung."},{"de":"der Haufen, der Stapel","ex":"Er ligt een hoop bladeren in de tuin.","exDe":"Im Garten liegt ein Haufen Blätter."},{"de":"eine Menge, viel (umgangssprachlich)","ex":"Dat kost een hoop geld.","exDe":"Das kostet eine Menge Geld."}],"usage":"De-Wort mit Homonymie: 1) Hoffnung (kein üblicher Plural), 2) Haufen/Menge (Plural hopen). Wendung: hoop hebben/houden.","genus":"de","plural":"hopen"},"bk_1332":{"lemma":"geluk","displayNl":"het geluk","pos":"substantief","meanings":[{"de":"das Glück, das Wohlbefinden","ex":"Geluk kun je niet kopen.","exDe":"Glück kann man nicht kaufen."},{"de":"das Glück, der glückliche Zufall","ex":"Ik wens je veel geluk.","exDe":"Ich wünsche dir viel Glück."}],"usage":"Abstraktes het-Wort, meist ohne Plural. Wendung: geluk hebben (Glück haben); bij geluk (zufällig).","genus":"het"},"bk_1333":{"lemma":"twijfel","displayNl":"de twijfel","pos":"substantief","meanings":[{"de":"der Zweifel","ex":"Ik heb geen twijfel meer.","exDe":"Ich habe keinen Zweifel mehr."},{"de":"die Ungewissheit, das Bedenken","ex":"Zonder twijfel is dit de beste keuze.","exDe":"Ohne Zweifel ist das die beste Wahl."}],"usage":"Abstraktes de-Wort. Feste Wendung: zonder twijfel (ohne Zweifel); in twijfel trekken (in Zweifel ziehen).","genus":"de","plural":"twijfels"},"bk_1334":{"lemma":"moed","displayNl":"de moed","pos":"substantief","meanings":[{"de":"der Mut","ex":"Hij heeft veel moed.","exDe":"Er hat viel Mut."},{"de":"die Courage, der Wagemut","ex":"Ze vatte moed en sprong.","exDe":"Sie fasste Mut und sprang."}],"usage":"Abstraktes, meist unzählbares Substantiv (kein Plural). Häufig in festen Wendungen: 'moed hebben', 'moed vatten', 'de moed verliezen'.","genus":"de"},"bk_1335":{"lemma":"hopen","displayNl":"hopen","pos":"werkwoord","meanings":[{"de":"hoffen","ex":"Ik hoop op mooi weer.","exDe":"Ich hoffe auf schönes Wetter."},{"de":"hoffen (dass)","ex":"We hopen dat je komt.","exDe":"Wir hoffen, dass du kommst."}],"usage":"Regelmäßiges Verb. Konstruktion 'hopen op' + Objekt oder 'hopen dat' + Nebensatz.","conjugation":{"presens":{"ik":"hoop","jij":"hoopt","hij":"hoopt","wij":"hopen"},"imperfectum":{"ik":"hoopte","wij":"hoopten"},"perfectum":{"aux":"hebben","participle":"gehoopt"}}},"bk_1336":{"lemma":"geloven","displayNl":"geloven","pos":"werkwoord","meanings":[{"de":"glauben (jemandem/etwas Glauben schenken)","ex":"Ik geloof je niet.","exDe":"Ich glaube dir nicht."},{"de":"glauben, meinen (annehmen)","ex":"Ik geloof dat het gaat regenen.","exDe":"Ich glaube, dass es regnen wird."},{"de":"glauben, religiös glauben (an)","ex":"Zij gelooft in God.","exDe":"Sie glaubt an Gott."}],"usage":"Regelmäßiges Verb. 'geloven in' = an etwas glauben; 'iemand geloven' = jemandem glauben.","conjugation":{"presens":{"ik":"geloof","jij":"gelooft","hij":"gelooft","wij":"geloven"},"imperfectum":{"ik":"geloofde","wij":"geloofden"},"perfectum":{"aux":"hebben","participle":"geloofd"}}},"bk_1337":{"lemma":"missen","displayNl":"missen","pos":"werkwoord","meanings":[{"de":"vermissen","ex":"Ik mis mijn familie.","exDe":"Ich vermisse meine Familie."},{"de":"verpassen (Bus, Zug, Termin)","ex":"Ik heb de trein gemist.","exDe":"Ich habe den Zug verpasst."},{"de":"fehlen, entbehren","ex":"Er missen twee stukken.","exDe":"Es fehlen zwei Teile."}],"usage":"Regelmäßiges Verb. Bedeutet sowohl 'vermissen' als auch 'verpassen'; Kontext entscheidet.","conjugation":{"presens":{"ik":"mis","jij":"mist","hij":"mist","wij":"missen"},"imperfectum":{"ik":"miste","wij":"misten"},"perfectum":{"aux":"hebben","participle":"gemist"}}},"bk_1338":{"lemma":"twijfelen","displayNl":"twijfelen","pos":"werkwoord","meanings":[{"de":"zweifeln","ex":"Ik twijfel over mijn keuze.","exDe":"Ich zweifle an meiner Wahl."},{"de":"unschlüssig sein, zögern","ex":"Ze twijfelde tussen twee jurken.","exDe":"Sie war unschlüssig zwischen zwei Kleidern."}],"usage":"Regelmäßiges Verb. Konstruktion 'twijfelen over/aan' etwas; 'twijfelen tussen' zwei Optionen.","conjugation":{"presens":{"ik":"twijfel","jij":"twijfelt","hij":"twijfelt","wij":"twijfelen"},"imperfectum":{"ik":"twijfelde","wij":"twijfelden"},"perfectum":{"aux":"hebben","participle":"getwijfeld"}}},"bk_1339":{"lemma":"het eens zijn","displayNl":"het eens zijn","pos":"uitdrukking","meanings":[{"de":"einverstanden sein, einer Meinung sein","ex":"Ik ben het met je eens.","exDe":"Ich bin mit dir einverstanden."},{"de":"sich einig sein","ex":"We zijn het helemaal eens.","exDe":"Wir sind uns völlig einig."}],"usage":"Feste Wendung mit 'zijn' + 'het ... eens'. Person mit 'met' anschließen: 'het eens zijn met iemand'. Gegenteil: 'het oneens zijn'."},"bk_1340":{"lemma":"kwaad","displayNl":"kwaad","pos":"adjectief","meanings":[{"de":"böse, zornig, wütend","ex":"Hij werd heel kwaad.","exDe":"Er wurde sehr zornig."},{"de":"böse, schlecht, boshaft","ex":"Een kwade tong verspreidt roddels.","exDe":"Eine böse Zunge verbreitet Klatsch."},{"de":"das Böse, der Schaden (als Substantiv: het kwaad)","ex":"Hij heeft geen kwaad in de zin.","exDe":"Er hat nichts Böses im Sinn."}],"usage":"Meist Adjektiv 'wütend/zornig' (kwaad worden = wütend werden). Auch substantiviert 'het kwaad' = das Böse/Übel."},"bk_1341":{"lemma":"opstaan","displayNl":"opstaan","pos":"werkwoord","meanings":[{"de":"aufstehen (aus dem Bett, sich erheben)","ex":"Ik sta vroeg op.","exDe":"Ich stehe früh auf."},{"de":"sich erheben, aufbegehren (gegen etwas)","ex":"Het volk stond op tegen de koning.","exDe":"Das Volk erhob sich gegen den König."}],"usage":"Trennbares Verb (op + staan): 'Ik sta op'. Perfekt mit 'zijn': 'Ik ben opgestaan'. Partikel 'op' rueckt im Hauptsatz ans Satzende.","conjugation":{"presens":{"ik":"sta op","jij":"staat op","hij":"staat op","wij":"staan op"},"imperfectum":{"ik":"stond op","wij":"stonden op"},"perfectum":{"aux":"zijn","participle":"opgestaan"}},"illustratable":true},"bk_1342":{"lemma":"vallen","displayNl":"vallen","pos":"werkwoord","meanings":[{"de":"fallen, hinfallen","ex":"Pas op, je valt!","exDe":"Pass auf, du fällst!"},{"de":"hereinbrechen (Abend/Nacht/Dunkelheit)","ex":"De avond valt langzaam over de stad.","exDe":"Der Abend bricht langsam über die Stadt herein."},{"de":"fallen, umkommen (im Kampf)","ex":"Veel soldaten zijn in de oorlog gevallen.","exDe":"Viele Soldaten sind im Krieg gefallen."}],"usage":"Unregelmäßig. Perfekt mit 'zijn'. Häufig mit 'over/van/op'. Feste Wendung 'in slaap vallen' (einschlafen).","conjugation":{"presens":{"ik":"val","jij":"valt","hij":"valt","wij":"vallen"},"imperfectum":{"ik":"viel","wij":"vielen"},"perfectum":{"aux":"zijn","participle":"gevallen"}},"illustratable":true},"bk_1344":{"lemma":"gooien","displayNl":"gooien","pos":"werkwoord","meanings":[{"de":"werfen","ex":"Gooi de bal naar mij.","exDe":"Wirf mir den Ball zu."},{"de":"schmeißen, achtlos wegwerfen","ex":"Hij gooide de wikkel op de grond.","exDe":"Er schmiss das Papier auf den Boden."}],"usage":"Regelmäßig. Perfekt mit 'hebben'. Oft mit 'naar' (in Richtung) oder 'weg' ('weggooien' = wegwerfen).","conjugation":{"presens":{"ik":"gooi","jij":"gooit","hij":"gooit","wij":"gooien"},"imperfectum":{"ik":"gooide","wij":"gooiden"},"perfectum":{"aux":"hebben","participle":"gegooid"}},"illustratable":true},"bk_1345":{"lemma":"vangen","displayNl":"vangen","pos":"werkwoord","meanings":[{"de":"fangen, auffangen","ex":"Ik vang de bal.","exDe":"Ich fange den Ball."},{"de":"einfangen, fangen (Tier/Person)","ex":"De politie heeft de dief gevangen.","exDe":"Die Polizei hat den Dieb gefangen."}],"usage":"Unregelmäßig (ving – gevangen). Perfekt mit 'hebben'. 'opvangen' = auffangen/betreuen.","conjugation":{"presens":{"ik":"vang","jij":"vangt","hij":"vangt","wij":"vangen"},"imperfectum":{"ik":"ving","wij":"vingen"},"perfectum":{"aux":"hebben","participle":"gevangen"}},"illustratable":true},"bk_1346":{"lemma":"pakken","displayNl":"pakken","pos":"werkwoord","meanings":[{"de":"nehmen, greifen","ex":"Ik pak mijn jas.","exDe":"Ich nehme meine Jacke."},{"de":"nehmen (Verkehrsmittel)","ex":"We pakken de trein naar Utrecht.","exDe":"Wir nehmen den Zug nach Utrecht."},{"de":"packen, ergreifen, festhalten","ex":"Hij pakte haar stevig bij de hand.","exDe":"Er ergriff fest ihre Hand."}],"usage":"Regelmäßig. Perfekt mit 'hebben'. Umgangssprachlich für 'nehmen'. 'inpakken' = einpacken, 'uitpakken' = auspacken.","conjugation":{"presens":{"ik":"pak","jij":"pakt","hij":"pakt","wij":"pakken"},"imperfectum":{"ik":"pakte","wij":"pakten"},"perfectum":{"aux":"hebben","participle":"gepakt"}},"illustratable":true},"bk_1347":{"lemma":"zetten","displayNl":"zetten","pos":"werkwoord","meanings":[{"de":"stellen, setzen (aufrecht hinstellen)","ex":"Ik zet de kopjes op tafel.","exDe":"Ich stelle die Tassen auf den Tisch."},{"de":"aufsetzen, kochen (Kaffee/Tee)","ex":"Zal ik even koffie zetten?","exDe":"Soll ich schnell Kaffee kochen?"}],"usage":"Regelmäßig. Perfekt mit 'hebben'. 'zetten' = etwas aufrecht hinstellen (vgl. 'leggen' = flach hinlegen). Feste Wendung 'koffie zetten'.","conjugation":{"presens":{"ik":"zet","jij":"zet","hij":"zet","wij":"zetten"},"imperfectum":{"ik":"zette","wij":"zetten"},"perfectum":{"aux":"hebben","participle":"gezet"}},"illustratable":true},"bk_1348":{"lemma":"leggen","displayNl":"leggen","pos":"werkwoord","meanings":[{"de":"legen (flach hinlegen)","ex":"Ik leg het boek op tafel.","exDe":"Ich lege das Buch auf den Tisch."},{"de":"legen (Eier)","ex":"De kip legt elke dag een ei.","exDe":"Das Huhn legt jeden Tag ein Ei."}],"usage":"Regelmäßig (legde – gelegd). Perfekt mit 'hebben'. 'leggen' = flach hinlegen (vgl. 'zetten' = aufrecht hinstellen). 'neerleggen' = niederlegen/ablegen.","conjugation":{"presens":{"ik":"leg","jij":"legt","hij":"legt","wij":"leggen"},"imperfectum":{"ik":"legde","wij":"legden"},"perfectum":{"aux":"hebben","participle":"gelegd"}},"illustratable":true},"bk_1349":{"lemma":"hangen","displayNl":"hangen","pos":"werkwoord","meanings":[{"de":"hängen (an etw. befestigt sein)","ex":"De jas hangt aan de kapstok.","exDe":"Die Jacke hängt an der Garderobe."},{"de":"aufhängen, hängen (etw. irgendwohin)","ex":"Ik hang de schilderijen aan de muur.","exDe":"Ich hänge die Bilder an die Wand."},{"de":"abhängen, herumhängen (umgangssprachlich)","ex":"De jongeren hangen op het plein.","exDe":"Die Jugendlichen hängen auf dem Platz herum."}],"usage":"Unregelmäßig (hing – gehangen). Perfekt mit 'hebben'. Sowohl intransitiv (hängen) als auch transitiv (aufhängen). 'ophangen' = aufhängen/auflegen (Telefon).","conjugation":{"presens":{"ik":"hang","jij":"hangt","hij":"hangt","wij":"hangen"},"imperfectum":{"ik":"hing","wij":"hingen"},"perfectum":{"aux":"hebben","participle":"gehangen"}},"illustratable":true},"bk_1350":{"lemma":"ontvangen","displayNl":"ontvangen","pos":"werkwoord","meanings":[{"de":"erhalten, bekommen","ex":"Ik ontvang veel mail.","exDe":"Ich erhalte viele E-Mails."},{"de":"empfangen, in Empfang nehmen (Gäste/Besuch)","ex":"Zij ontvangen graag gasten thuis.","exDe":"Sie empfangen gerne Gäste zu Hause."}],"usage":"Unregelmäßig, unbetontes Präfix 'ont-': Partizip OHNE 'ge-' (ontvangen). Perfekt mit 'hebben'.","conjugation":{"presens":{"ik":"ontvang","jij":"ontvangt","hij":"ontvangt","wij":"ontvangen"},"imperfectum":{"ik":"ontving","wij":"ontvingen"},"perfectum":{"aux":"hebben","participle":"ontvangen"}}},"bk_1351":{"lemma":"openmaken","displayNl":"openmaken","pos":"werkwoord","meanings":[{"de":"öffnen, aufmachen","ex":"Ik maak het pakje open.","exDe":"Ich mache das Päckchen auf."},{"de":"aufmachen (Flasche, Brief)","ex":"Kun je deze fles even openmaken?","exDe":"Kannst du diese Flasche kurz aufmachen?"}],"usage":"Trennbares Verb (maak ... open). Fokus auf das Öffnen von etwas Verschlossenem (Paket, Flasche, Brief). Synonym: openen.","conjugation":{"presens":{"ik":"maak open","jij":"maakt open","hij":"maakt open","wij":"maken open"},"imperfectum":{"ik":"maakte open","wij":"maakten open"},"perfectum":{"aux":"hebben","participle":"opengemaakt"}},"illustratable":true},"bk_1352":{"lemma":"dichtdoen","displayNl":"dichtdoen","pos":"werkwoord","meanings":[{"de":"zumachen, schließen","ex":"Doe de deur dicht.","exDe":"Mach die Tür zu."},{"de":"zumachen (Augen, Fenster)","ex":"Ik doe mijn ogen dicht.","exDe":"Ich mache meine Augen zu."}],"usage":"Trennbares Verb (doe ... dicht). Umgangssprachlich für schließen/zumachen von Türen, Fenstern, Augen. Formeller: sluiten.","conjugation":{"presens":{"ik":"doe dicht","jij":"doet dicht","hij":"doet dicht","wij":"doen dicht"},"imperfectum":{"ik":"deed dicht","wij":"deden dicht"},"perfectum":{"aux":"hebben","participle":"dichtgedaan"}},"illustratable":true},"bk_1353":{"lemma":"aandoen","displayNl":"aandoen","pos":"werkwoord","meanings":[{"de":"anmachen, einschalten","ex":"Ik doe het licht aan.","exDe":"Ich mache das Licht an."},{"de":"anziehen (Kleidung)","ex":"Doe je jas aan, het is koud.","exDe":"Zieh deine Jacke an, es ist kalt."},{"de":"anlaufen, ansteuern (Ort)","ex":"De boot doet ook Rotterdam aan.","exDe":"Das Boot läuft auch Rotterdam an."}],"usage":"Trennbares Verb (doe ... aan). Grundbedeutung anmachen/einschalten (Licht, Gerät); sehr häufig auch Kleidung anziehen (jas aandoen).","conjugation":{"presens":{"ik":"doe aan","jij":"doet aan","hij":"doet aan","wij":"doen aan"},"imperfectum":{"ik":"deed aan","wij":"deden aan"},"perfectum":{"aux":"hebben","participle":"aangedaan"}},"notes":"Trennbares Verb; Grundbedeutung anmachen/einschalten, sehr häufig auch Kleidung anziehen.","illustratable":true},"bk_1354":{"lemma":"uitdoen","displayNl":"uitdoen","pos":"werkwoord","meanings":[{"de":"ausmachen, ausschalten","ex":"Doe de televisie uit.","exDe":"Mach den Fernseher aus."},{"de":"ausziehen (Kleidung)","ex":"Ik doe mijn schönen uit.","exDe":"Ich ziehe meine Schuhe aus."}],"usage":"Trennbares Verb (doe ... uit). Gegenteil von aandoen: ausmachen/ausschalten (Licht, Gerät); ebenso häufig Kleidung ausziehen (jas uitdoen).","conjugation":{"presens":{"ik":"doe uit","jij":"doet uit","hij":"doet uit","wij":"doen uit"},"imperfectum":{"ik":"deed uit","wij":"deden uit"},"perfectum":{"aux":"hebben","participle":"uitgedaan"}},"notes":"Trennbares Verb; Grundbedeutung ausmachen/ausschalten, ebenso häufig Kleidung ausziehen.","illustratable":true},"bk_1355":{"lemma":"verven","displayNl":"verven","pos":"werkwoord","meanings":[{"de":"streichen (Wand, Zaun)","ex":"Wij verven de muur wit.","exDe":"Wir streichen die Wand weiß."},{"de":"färben (Haare, Stoff)","ex":"Zij verft haar haar rood.","exDe":"Sie färbt ihre Haare rot."}],"usage":"Regelmäßiges Verb. Etwas mit Farbe streichen (Wand, Zaun) oder färben (Haare, Stoff). Künstlerisch malen = schilderen, nicht verven.","conjugation":{"presens":{"ik":"verf","jij":"verft","hij":"verft","wij":"verven"},"imperfectum":{"ik":"verfde","wij":"verfden"},"perfectum":{"aux":"hebben","participle":"geverfd"}},"notes":"verven = mit Farbe streichen/färben; malen als Kunst = schilderen.","illustratable":true},"bk_1357":{"lemma":"proberen","displayNl":"proberen","pos":"werkwoord","meanings":[{"de":"versuchen, probieren","ex":"Ik probeer het nog een keer.","exDe":"Ich versuche es noch einmal."},{"de":"probieren, kosten (Essen)","ex":"Wil je de kaas even proberen?","exDe":"Möchtest du den Käse kurz probieren?"},{"de":"ausprobieren, anprobieren","ex":"Ik wil deze schönen graag proberen.","exDe":"Ich möchte diese Schuhe gern anprobieren."}],"usage":"Regelmäßiges Verb. Etwas versuchen (probeer te ...), aber auch kosten/anprobieren. Häufig mit te + Infinitiv: ik probeer te slapen.","conjugation":{"presens":{"ik":"probeer","jij":"probeert","hij":"probeert","wij":"proberen"},"imperfectum":{"ik":"probeerde","wij":"probeerden"},"perfectum":{"aux":"hebben","participle":"geprobeerd"}}},"bk_1358":{"lemma":"volgen","displayNl":"volgen","pos":"werkwoord","meanings":[{"de":"folgen, hinterhergehen","ex":"De hond volgt zijn baas overal.","exDe":"Der Hund folgt seinem Herrchen überall hin."},{"de":"besuchen, belegen (Kurs)","ex":"Ik volg een cursus Nederlands.","exDe":"Ich mache einen Niederländisch-Kurs."},{"de":"verfolgen, mitverfolgen (Nachrichten)","ex":"Zij volgt het nieuws elke dag.","exDe":"Sie verfolgt jeden Tag die Nachrichten."},{"de":"folgen, nachvollziehen (verstehen)","ex":"Sorry, ik kan je niet helemaal volgen.","exDe":"Entschuldigung, ich kann dir nicht ganz folgen."}],"usage":"Regelmäßiges Verb. Jemandem/etwas folgen; einen Kurs belegen (een cursus volgen); Nachrichten verfolgen; jemanden gedanklich nachvollziehen.","conjugation":{"presens":{"ik":"volg","jij":"volgt","hij":"volgt","wij":"volgen"},"imperfectum":{"ik":"volgde","wij":"volgden"},"perfectum":{"aux":"hebben","participle":"gevolgd"}}},"bk_1359":{"lemma":"kiezen","displayNl":"kiezen","pos":"werkwoord","meanings":[{"de":"wählen, auswählen","ex":"Ik kies de rode jas.","exDe":"Ich wähle die rote Jacke."},{"de":"sich entscheiden (für)","ex":"Wij kiezen voor de trein.","exDe":"Wir entscheiden uns für den Zug."},{"de":"wählen (Wahl, Politik)","ex":"Morgen kiest Nederland een nieuwe regering.","exDe":"Morgen wählt die Niederlande eine neue Regierung."}],"usage":"Unregelmäßiges Verb (koos, gekozen). Auswählen; sich entscheiden (kiezen voor); wählen bei Wahlen.","conjugation":{"presens":{"ik":"kies","jij":"kiest","hij":"kiest","wij":"kiezen"},"imperfectum":{"ik":"koos","wij":"kozen"},"perfectum":{"aux":"hebben","participle":"gekozen"}}},"bk_1360":{"lemma":"veranderen","displayNl":"veranderen","pos":"werkwoord","meanings":[{"de":"(sich) ändern, verändern","ex":"Ik verander van plan.","exDe":"Ich ändere meinen Plan."},{"de":"sich wandeln, anders werden","ex":"De situatie is veranderd.","exDe":"Die Situation hat sich verändert."}],"usage":"Transitiv mit hebben (iets veranderen), bei Zustandswechsel oft mit zijn (De situatie is veranderd). Konstruktion: veranderen van + Substantiv.","conjugation":{"presens":{"ik":"verander","jij":"verandert","hij":"verandert","wij":"veranderen"},"imperfectum":{"ik":"veranderde","wij":"veranderden"},"perfectum":{"aux":"hebben","participle":"veranderd"}}},"bk_1361":{"lemma":"gebeuren","displayNl":"gebeuren","pos":"werkwoord","meanings":[{"de":"passieren, geschehen","ex":"Wat is er gebeurd?","exDe":"Was ist passiert?"}],"usage":"Fast nur unpersönlich in der 3. Person: het gebeurt, er gebeurt iets. Perfekt immer mit zijn.","conjugation":{"presens":{"ik":"gebeur","jij":"gebeurt","hij":"gebeurt","wij":"gebeuren"},"imperfectum":{"ik":"gebeurde","wij":"gebeurden"},"perfectum":{"aux":"zijn","participle":"gebeurd"}}},"bk_1362":{"lemma":"lukken","displayNl":"lukken","pos":"werkwoord","meanings":[{"de":"gelingen, klappen","ex":"Het lukt me niet.","exDe":"Es klappt bei mir nicht."}],"usage":"Unpersönlich mit het; die betroffene Person steht im Dativ-Objekt (het lukt me/je/hem). Perfekt mit zijn.","conjugation":{"presens":{"ik":"luk","jij":"lukt","hij":"lukt","wij":"lukken"},"imperfectum":{"ik":"lukte","wij":"lukten"},"perfectum":{"aux":"zijn","participle":"gelukt"}}},"bk_1363":{"lemma":"durven","displayNl":"durven","pos":"werkwoord","meanings":[{"de":"sich trauen, wagen","ex":"Ik durf het niet.","exDe":"Ich traue mich nicht."}],"usage":"Halbmodalverb: folgender Infinitiv meist ohne te (Ik durf niet te springen ist auch möglich). Ältere starke Imperfektform dorst gilt heute als gehoben.","conjugation":{"presens":{"ik":"durf","jij":"durft","hij":"durft","wij":"durven"},"imperfectum":{"ik":"durfde","wij":"durfden"},"perfectum":{"aux":"hebben","participle":"gedurfd"}}},"bk_1364":{"lemma":"hoeven","displayNl":"hoeven","pos":"werkwoord","meanings":[{"de":"brauchen (in Verneinung: nicht müssen)","ex":"Je hoeft niet te komen.","exDe":"Du brauchst nicht zu kommen."}],"usage":"Fast nur in verneintem/eingeschränktem Kontext (niet, geen, alleen) als Gegenstück zu moeten; folgender Infinitiv mit te. Perfekt selten, dann Ersatzinfinitiv: heb niet hoeven komen.","conjugation":{"presens":{"ik":"hoef","jij":"hoeft","hij":"hoeft","wij":"hoeven"},"imperfectum":{"ik":"hoefde","wij":"hoefden"},"perfectum":{"aux":"hebben","participle":"gehoeven"}}},"bk_1365":{"lemma":"lijken","displayNl":"lijken","pos":"werkwoord","meanings":[{"de":"scheinen, den Anschein haben","ex":"Het lijkt me leuk.","exDe":"Das scheint mir nett zu sein."},{"de":"ähneln, gleichen (lijken op)","ex":"Zij lijkt op haar moeder.","exDe":"Sie ähnelt ihrer Mutter."}],"usage":"Starkes Verb (leek/geleken). In der Bedeutung ähneln mit Präposition op. Oft unpersönlich: het lijkt erop dat ...","conjugation":{"presens":{"ik":"lijk","jij":"lijkt","hij":"lijkt","wij":"lijken"},"imperfectum":{"ik":"leek","wij":"leken"},"perfectum":{"aux":"hebben","participle":"geleken"}}},"bk_1366":{"lemma":"wennen","displayNl":"wennen","pos":"werkwoord","meanings":[{"de":"sich gewöhnen (an)","ex":"Ik moet nog wennen.","exDe":"Ich muss mich noch gewöhnen."}],"usage":"Objekt mit Präposition aan (wennen aan iets). Zustand meist als gewend zijn aan; Perfekt mit zijn.","conjugation":{"presens":{"ik":"wen","jij":"went","hij":"went","wij":"wennen"},"imperfectum":{"ik":"wende","wij":"wenden"},"perfectum":{"aux":"zijn","participle":"gewend"}}},"bk_1367":{"lemma":"laag","displayNl":"laag","pos":"adjectief","meanings":[{"de":"niedrig, tief (Höhe)","ex":"De tafel is laag.","exDe":"Der Tisch ist niedrig."},{"de":"leise, gering (Lautstärke, Menge)","ex":"Zet de muziek wat lager.","exDe":"Mach die Musik etwas leiser."},{"de":"gemein, niederträchtig","ex":"Dat is een lage streek.","exDe":"Das ist eine gemeine Masche."}],"usage":"Attributiv flektiert: een lage tafel. Steigerung: laag, lager, laagst. Nicht mit dem gleichlautenden Substantiv de laag (Schicht) verwechseln."},"bk_1368":{"lemma":"gek","displayNl":"gek","pos":"adjectief","meanings":[{"de":"verrückt","ex":"Dat is een gek idee.","exDe":"Das ist eine verrückte Idee."},{"de":"komisch, seltsam","ex":"Wat een gek geluid.","exDe":"Was für ein komisches Geräusch."},{"de":"versessen (gek op)","ex":"Ik ben gek op chocolade.","exDe":"Ich bin versessen auf Schokolade."}],"usage":"Auch als Substantiv 'de gek' (der Narr). Konstruktion 'gek op iets/iemand zijn' = etwas/jemanden sehr mögen."},"bk_1369":{"lemma":"belangrijk","displayNl":"belangrijk","pos":"adjectief","meanings":[{"de":"wichtig","ex":"Dit is heel belangrijk.","exDe":"Das ist sehr wichtig."},{"de":"bedeutend, bedeutsam","ex":"Hij is een belangrijk persoon in het bedrijf.","exDe":"Er ist eine bedeutende Person in der Firma."}],"usage":"Steigerung: belangrijker, belangrijkst. Häufig 'het belangrijkste' = das Wichtigste."},"bk_1370":{"lemma":"verkeerd","displayNl":"verkeerd","pos":"adjectief","meanings":[{"de":"falsch, verkehrt","ex":"Ik ben de verkeerde kant op gegaan.","exDe":"Ich bin in die verkehrte Richtung gegangen."},{"de":"verkehrt, unrichtig (Antwort)","ex":"Dat is het verkeerde antwoord.","exDe":"Das ist die falsche Antwort."}],"usage":"Gegenteil von 'goed'/'juist'. Adverbial 'iets verkeerd doen' = etwas falsch machen."},"bk_1371":{"lemma":"licht","displayNl":"licht","pos":"adjectief","meanings":[{"de":"hell","ex":"De kamer is licht.","exDe":"Das Zimmer ist hell."},{"de":"leicht (an Gewicht)","ex":"De tas is heel licht.","exDe":"Die Tasche ist sehr leicht."},{"de":"leicht, gering (Grad)","ex":"Ze heeft een lichte verkoudheid.","exDe":"Sie hat eine leichte Erkältung."}],"usage":"Homonym zum Substantiv 'het licht' (das Licht). Als Adjektiv Gegenteil von 'donker' (hell) bzw. 'zwaar' (leicht)."},"bk_1372":{"lemma":"zwaar","displayNl":"zwaar","pos":"adjectief","meanings":[{"de":"schwer (Gewicht)","ex":"De koffer is zwaar.","exDe":"Der Koffer ist schwer."},{"de":"schwer, schwierig, anstrengend","ex":"Het was een zware dag.","exDe":"Es war ein schwerer Tag."},{"de":"stark, heftig (Sturm, Kaffee)","ex":"Er komt een zware storm aan.","exDe":"Ein heftiger Sturm zieht auf."}],"usage":"Gegenteil von 'licht'. Steigerung: zwaarder, zwaarst."},"bk_1373":{"lemma":"dik","displayNl":"dik","pos":"adjectief","meanings":[{"de":"dick (Umfang, Schicht)","ex":"Het is een dik boek.","exDe":"Es ist ein dickes Buch."},{"de":"dick, korpulent","ex":"De kat is een beetje te dik.","exDe":"Die Katze ist etwas zu dick."},{"de":"eng (befreundet)","ex":"Ze zijn dikke vrienden.","exDe":"Sie sind dicke Freunde."}],"usage":"Gegenteil von 'dun' (dünn) bzw. 'mager' (dünn/schlank). Steigerung: dikker, dikst."},"bk_1374":{"lemma":"dun","displayNl":"dun","pos":"adjectief","meanings":[{"de":"dünn (Dicke)","ex":"De muur is dun.","exDe":"Die Wand ist dünn."},{"de":"dünn, mager (Person)","ex":"Hij is lang en dun.","exDe":"Er ist groß und dünn."},{"de":"dünn, flüssig (Konsistenz)","ex":"De soep is te dun.","exDe":"Die Suppe ist zu dünn."}],"usage":"Gegenteil von 'dik'. Steigerung: dunner, dunst."},"bk_1375":{"lemma":"breed","displayNl":"breed","pos":"adjectief","meanings":[{"de":"breit","ex":"De straat is breed.","exDe":"Die Straße ist breit."},{"de":"breit, umfassend (übertragen)","ex":"Het onderwerp is heel breed.","exDe":"Das Thema ist sehr breit gefächert."}],"usage":"Gegenteil von 'smal' (schmal). Steigerung: breder, breedst. Redewendung 'breed lachen' = breit grinsen."},"bk_1376":{"lemma":"zacht","displayNl":"zacht","pos":"adjectief","meanings":[{"de":"weich","ex":"Het kussen is heerlijk zacht.","exDe":"Das Kissen ist herrlich weich."},{"de":"sanft, zart","ex":"Ze streelde de kat met een zachte hand.","exDe":"Sie streichelte die Katze mit sanfter Hand."},{"de":"leise","ex":"Hij praat heel zacht.","exDe":"Er spricht sehr leise."}],"usage":"Adjektiv/Adverb; attributiv oft flektiert: 'een zacht kussen', 'een zachte stem'."},"bk_1378":{"lemma":"toen","displayNl":"toen","pos":"bijwoord","meanings":[{"de":"damals","ex":"Toen was ik nog een kind.","exDe":"Damals war ich noch ein Kind."},{"de":"als (temporale Konjunktion, Vergangenheit)","ex":"Toen ik binnenkwam, ging de telefoon.","exDe":"Als ich hereinkam, klingelte das Telefon."}],"usage":"Als Adverb 'damals'; als unterordnende Konjunktion 'als' nur für einmalige Ereignisse in der Vergangenheit (Verb ans Satzende)."},"bk_1379":{"lemma":"ergens","displayNl":"ergens","pos":"bijwoord","meanings":[{"de":"irgendwo","ex":"Mijn sleutel ligt hier ergens.","exDe":"Mein Schlüssel liegt hier irgendwo."},{"de":"irgendwohin","ex":"Zullen we ergens naartoe gaan?","exDe":"Sollen wir irgendwohin gehen?"},{"de":"irgendwie, in gewisser Weise","ex":"Ergens heeft hij wel gelijk.","exDe":"Irgendwie hat er ja recht."}],"usage":"Unbestimmtes Adverb des Ortes; auch abgeschwächt ('irgendwie') und in Verbindungen wie 'ergens om geven'."},"bk_1380":{"lemma":"overal","displayNl":"overal","pos":"bijwoord","meanings":[{"de":"überall","ex":"Na het feest lag er overal rommel.","exDe":"Nach der Party lag überall Müll."},{"de":"überallhin","ex":"Ik neem mijn telefoon overal mee naartoe.","exDe":"Ich nehme mein Handy überallhin mit."}],"usage":"Adverb des Ortes; für Richtung mit 'naartoe': 'overal naartoe'."},"bk_1381":{"lemma":"binnen","displayNl":"binnen","pos":"bijwoord","meanings":[{"de":"drinnen, herein","ex":"Blijf binnen, het regent.","exDe":"Bleib drinnen, es regnet."},{"de":"innerhalb (zeitlich/räumlich)","ex":"Ik ben binnen een uur terug.","exDe":"Ich bin innerhalb einer Stunde zurück."}],"usage":"Als Adverb 'drinnen'; als Präposition 'innerhalb' ('binnen een week'). Gegenteil: 'buiten'."},"bk_1382":{"lemma":"buiten","displayNl":"buiten","pos":"bijwoord","meanings":[{"de":"draußen, hinaus","ex":"De kinderen spelen buiten.","exDe":"Die Kinder spielen draußen."},{"de":"außerhalb","ex":"Zij wonen buiten de stad.","exDe":"Sie wohnen außerhalb der Stadt."},{"de":"außer, abgesehen von","ex":"Buiten jou kent niemand het verhaal.","exDe":"Außer dir kennt niemand die Geschichte."}],"usage":"Als Adverb 'draußen'; als Präposition 'außerhalb/außer'. Gegenteil: 'binnen'."},"bk_1383":{"lemma":"boven","displayNl":"boven","pos":"bijwoord","meanings":[{"de":"oben, nach oben","ex":"Mijn slaapkamer is boven.","exDe":"Mein Schlafzimmer ist oben."},{"de":"über, oberhalb von","ex":"De lamp hangt boven de tafel.","exDe":"Die Lampe hängt über dem Tisch."}],"usage":"Als Adverb 'oben'; als Präposition 'über/oberhalb'. Gegenteil: 'beneden/onder'."},"bk_1384":{"lemma":"beneden","displayNl":"beneden","pos":"bijwoord","meanings":[{"de":"unten, nach unten","ex":"De keuken is beneden.","exDe":"Die Küche ist unten."},{"de":"unterhalb von, unter","ex":"De temperatuur zakt beneden nul.","exDe":"Die Temperatur sinkt unter null."}],"usage":"Als Adverb 'unten'; als Präposition 'unterhalb/unter'. Gegenteil: 'boven'."},"bk_1385":{"lemma":"zeker","displayNl":"zeker","pos":"adjectief","meanings":[{"de":"sicher, gewiss","ex":"Ik weet het heel zeker.","exDe":"Ich weiß es ganz sicher."},{"de":"bestimmt, wohl (Vermutung)","ex":"Hij is zeker ziek, want hij belde af.","exDe":"Er ist bestimmt krank, denn er hat abgesagt."},{"de":"ein gewisser, ein bestimmter","ex":"Een zekere meneer Jansen belde voor je.","exDe":"Ein gewisser Herr Jansen rief für dich an."}],"usage":"Adjektiv und Adverb; als Modalpartikel ('zeker weten' = ganz sicher). Steigerung: zekerder, zekerst.","notes":"Vielseitig: von 'gewiss/sicher' bis zur Vermutung 'wohl'."},"bk_1386":{"lemma":"natuurlijk","displayNl":"natuurlijk","pos":"bijwoord","meanings":[{"de":"natürlich, selbstverständlich","ex":"Natuurlijk help ik je.","exDe":"Natürlich helfe ich dir."},{"de":"natürlich, in der Natur vorkommend","ex":"Dit is een volledig natuurlijk product.","exDe":"Das ist ein völlig natürliches Produkt."}],"usage":"Meist als Adverb ('selbstverständlich'); als Adjektiv ('natürlich, naturbezogen') gebeugt: een natuurlijke bron."},"bk_1387":{"lemma":"gewoon","displayNl":"gewoon","pos":"adjectief","meanings":[{"de":"einfach, bloß (Partikel)","ex":"Doe het gewoon.","exDe":"Mach es einfach."},{"de":"gewöhnlich, normal, alltäglich","ex":"Het is een heel gewone dag.","exDe":"Es ist ein ganz gewöhnlicher Tag."},{"de":"einfach, richtiggehend (Verstärkung)","ex":"Dat is gewoon niet waar.","exDe":"Das ist einfach nicht wahr."}],"usage":"Adjektiv (gebeugt: een gewone dag) und häufige Modalpartikel. Steigerung: gewoner, gewoonst."},"bk_1388":{"lemma":"even","displayNl":"even","pos":"bijwoord","meanings":[{"de":"kurz, mal, eben","ex":"Wacht even.","exDe":"Warte kurz."},{"de":"genauso, gleich (even ... als)","ex":"Zij is even groot als ik.","exDe":"Sie ist genauso groß wie ich."},{"de":"gerade (Zahl, Gegenteil von ungerade)","ex":"Vier is een even getal.","exDe":"Vier ist eine gerade Zahl."}],"usage":"Als abschwächende Partikel ('mal') sehr häufig; im Vergleich 'even ... als'; als Zahladjektiv 'even/oneven'."},"bk_1389":{"lemma":"iedereen","displayNl":"iedereen","pos":"voornaamwoord","meanings":[{"de":"jeder, alle, jedermann","ex":"Iedereen is er.","exDe":"Alle sind da."}],"usage":"Unbestimmtes Pronomen, immer Singular konstruiert (iedereen is/heeft)."},"bk_1390":{"lemma":"niemand","displayNl":"niemand","pos":"voornaamwoord","meanings":[{"de":"niemand, keiner","ex":"Er is niemand thuis.","exDe":"Es ist niemand zu Hause."}],"usage":"Verneinendes unbestimmtes Pronomen; Singular konstruiert."},"bk_1391":{"lemma":"iemand","displayNl":"iemand","pos":"voornaamwoord","meanings":[{"de":"jemand","ex":"Er staat iemand voor de deur.","exDe":"Jemand steht vor der Tür."},{"de":"irgendjemand (in Fragen/Bedingungen)","ex":"Is er iemand die kan helpen?","exDe":"Ist da irgendjemand, der helfen kann?"}],"usage":"Unbestimmtes Pronomen; Singular konstruiert."},"bk_1392":{"lemma":"elk","displayNl":"elk","pos":"voornaamwoord","meanings":[{"de":"jeder, jede, jedes","ex":"Elke dag loop ik.","exDe":"Jeden Tag laufe ich."},{"de":"jeglicher, ein jeder","ex":"Elk kind krijgt een cadeau.","exDe":"Jedes Kind bekommt ein Geschenk."}],"usage":"Bestimmendes Pronomen: 'elk' bei het-Wörtern (elk huis), 'elke' bei de-Wörtern und Plural-Sinn (elke dag). Grundform 'elk'.","notes":"Eingabe 'elke' ist die de-Wort-/gebeugte Form; Lemma = elk."},"bk_1393":{"lemma":"allebei","displayNl":"allebei","pos":"voornaamwoord","meanings":[{"de":"beide","ex":"We komen allebei.","exDe":"Wir kommen beide."},{"de":"alle beide (beide zusammen)","ex":"Ze zijn allebei ziek.","exDe":"Sie sind beide krank."}],"usage":"Unbetontes Indefinitpronomen für zwei Personen/Dinge; steht meist nach dem Verb. Betonte Variante: 'alle twee'."},"bk_1394":{"lemma":"dus","displayNl":"dus","pos":"bijwoord","meanings":[{"de":"also, folglich","ex":"Het regent, dus ik blijf binnen.","exDe":"Es regnet, also bleibe ich drinnen."},{"de":"also (Schlussfolgerung/Nachfrage)","ex":"Dus jij komt niet?","exDe":"Also kommst du nicht?"}],"usage":"Folgerndes Adverb; leitet die Konsequenz ein. Als Konnektor loest es keine Inversion aus, wenn es vor dem Subjekt steht."},"bk_1395":{"lemma":"als","displayNl":"als","pos":"voegwoord","meanings":[{"de":"wenn (konditional)","ex":"Als het mooi is, gaan we fietsen.","exDe":"Wenn es schön ist, fahren wir Rad."},{"de":"wenn, sobald (temporal, wiederholt/zukuenftig)","ex":"Als ik thuiskom, bel ik je.","exDe":"Wenn ich nach Hause komme, rufe ich dich an."},{"de":"als, wie (Vergleich/Funktion)","ex":"Hij werkt als kok.","exDe":"Er arbeitet als Koch."},{"de":"wie (bei Gleichheit, 'zo ... als')","ex":"Ze is zo groot als ik.","exDe":"Sie ist so gross wie ich."}],"usage":"Unterordnende Konjunktion (Verb ans Satzende) für Bedingung und Zeit; ausserdem Vergleichs-/Funktionswort. Temporale Vergangenheit einmalig: 'toen'."},"bk_1396":{"lemma":"dat","displayNl":"dat","pos":"voegwoord","meanings":[{"de":"dass (Konjunktion)","ex":"Ik denk dat het regent.","exDe":"Ich denke, dass es regnet."},{"de":"das, jenes (Demonstrativpronomen, het-Wort)","ex":"Dat is mijn boek.","exDe":"Das ist mein Buch."},{"de":"das (Relativpronomen zu het-Woertern)","ex":"Het huis dat we kopen is oud.","exDe":"Das Haus, das wir kaufen, ist alt."}],"usage":"Mehrdeutig: unterordnende Konjunktion (Verb ans Satzende), Demonstrativ- und Relativpronomen für saechliche (het-)Woerter. Bei de-Woertern steht 'die'."},"bk_1397":{"lemma":"naast","displayNl":"naast","pos":"voorzetsel","meanings":[{"de":"neben (raeumlich)","ex":"Ik zit naast Anna.","exDe":"Ich sitze neben Anna."},{"de":"neben, ausser (zusaetzlich zu)","ex":"Naast werk heeft hij veel hobby's.","exDe":"Neben der Arbeit hat er viele Hobbys."}],"usage":"Praeposition der Position; auch uebertragen 'zusaetzlich zu'."},"bk_1398":{"lemma":"tussen","displayNl":"tussen","pos":"voorzetsel","meanings":[{"de":"zwischen (raeumlich)","ex":"De winkel is tussen twee huizen.","exDe":"Der Laden ist zwischen zwei Häusern."},{"de":"zwischen (zeitlich)","ex":"Ik bel je tussen twee en drie.","exDe":"Ich rufe dich zwischen zwei und drei an."}],"usage":"Praeposition für Position/Zeit im Bereich zweier Punkte. Richtung 'zwischen ... hindurch': 'tussendoor'."},"bk_1399":{"lemma":"achter","displayNl":"achter","pos":"voorzetsel","meanings":[{"de":"hinter (raeumlich)","ex":"De tuin is achter het huis.","exDe":"Der Garten ist hinter dem Haus."},{"de":"hinten, dahinter (Adverb)","ex":"Hij loopt achter.","exDe":"Er geht hinterher / liegt zurueck."}],"usage":"Ueberwiegend Praeposition der Position; auch Adverb ('hinten', 'im Rueckstand'). Gegenteil: 'voor'."},"bk_1400":{"lemma":"zonder","displayNl":"zonder","pos":"voorzetsel","meanings":[{"de":"ohne","ex":"Koffie zonder suiker.","exDe":"Kaffee ohne Zucker."},{"de":"ohne zu (+ te-Infinitiv)","ex":"Hij vertrok zonder iets te zeggen.","exDe":"Er ging, ohne etwas zu sagen."}],"usage":"Praeposition der Abwesenheit; mit 'te'-Infinitiv als 'ohne zu'. Gegenteil: 'met'."},"bk_1401":{"lemma":"tot","displayNl":"tot","pos":"voorzetsel","meanings":[{"de":"bis (zeitlich)","ex":"De winkel is open tot zes uur.","exDe":"Der Laden ist bis sechs Uhr geöffnet."},{"de":"bis (räumlich, bis zu einem Punkt)","ex":"We lopen tot het einde van de straat.","exDe":"Wir gehen bis zum Ende der Straße."},{"de":"zu (bei Verwandlung/Ernennung), z. B. tot iets maken","ex":"Ze werd tot voorzitter gekozen.","exDe":"Sie wurde zur Vorsitzenden gewählt."}],"usage":"Präposition. Zeitlich/räumlich 'bis'; 'tot en met' = 'bis einschließlich'. Nicht mit 'naar' (Richtung) verwechseln."},"bk_1402":{"lemma":"door","displayNl":"door","pos":"voorzetsel","meanings":[{"de":"durch (hindurch)","ex":"We lopen door het park.","exDe":"Wir gehen durch den Park."},{"de":"von (Urheber im Passiv), durch","ex":"Het boek is door een Nederlander geschreven.","exDe":"Das Buch wurde von einem Niederländer geschrieben."},{"de":"wegen, aufgrund von","ex":"Door de regen bleven we thuis.","exDe":"Wegen des Regens blieben wir zu Hause."},{"de":"weiter (Adverb/Partikel), z. B. doorgaan","ex":"Ga maar door met je verhaal.","exDe":"Mach nur weiter mit deiner Geschichte."}],"usage":"Meist Präposition ('durch', Passiv-Urheber, kausal); auch trennbares Partikel ('weiter', 'durch-'). 'door de week' = 'unter der Woche'."},"bk_1403":{"lemma":"aan","displayNl":"aan","pos":"voorzetsel","meanings":[{"de":"an (Ort, hängend/anliegend)","ex":"De foto hangt aan de muur.","exDe":"Das Foto hängt an der Wand."},{"de":"an (Empfänger), z. B. geben an","ex":"Ik geef het boek aan mijn broer.","exDe":"Ich gebe das Buch meinem Bruder."},{"de":"an (eingeschaltet, Adverb/Partikel)","ex":"Het licht is aan.","exDe":"Das Licht ist an."},{"de":"am (bei einer Tätigkeit), aan het + Infinitiv","ex":"Ik ben aan het koken.","exDe":"Ich bin am Kochen."}],"usage":"Präposition 'an' (Ort/Empfänger); Partikel 'an/ein' (aanzetten); Verlaufsform 'aan het + Infinitiv'. 'aan zee' = 'am Meer'."},"bk_1404":{"lemma":"welke","displayNl":"welke","pos":"voornaamwoord","meanings":[{"de":"welche/welcher/welches (Frage, vor de-Wörtern & Plural)","ex":"Welke kleur wil je?","exDe":"Welche Farbe willst du?"},{"de":"welche (Relativpronomen, gehoben/formal)","ex":"De film welke ik zag, was mooi.","exDe":"Der Film, den ich sah, war schön."}],"usage":"Frage-/Relativpronomen. Vor het-Wörtern im Singular: 'welk' (welk boek). Plural und de-Wörter: 'welke'."},"bk_1405":{"lemma":"waarheen","displayNl":"waarheen","pos":"bijwoord","meanings":[{"de":"wohin","ex":"Waarheen ga je?","exDe":"Wohin gehst du?"},{"de":"wohin (in Relativsätzen), z. B. der Ort, wohin","ex":"De stad waarheen we reizen is Utrecht.","exDe":"Die Stadt, wohin wir reisen, ist Utrecht."}],"usage":"Frageadverb der Richtung; oft auch getrennt 'waar ... heen' (Waar ga je heen?). Alternative: 'waarnaartoe'."},"bk_1406":{"lemma":"ons","displayNl":"ons","pos":"voornaamwoord","meanings":[{"de":"unser/unsere (Possessiv, vor het-Wörtern)","ex":"Dit is ons huis.","exDe":"Das ist unser Haus."},{"de":"uns (Objektpronomen, 1. Person Plural)","ex":"Ze heeft ons geholpen.","exDe":"Sie hat uns geholfen."}],"usage":"Possessiv 'ons' nur vor het-Wörtern; vor de-Wörtern/Plural 'onze' (onze auto, onze kinderen). Als Objektpronomen = 'uns'."},"bk_1407":{"lemma":"wel","displayNl":"wel","pos":"bijwoord","meanings":[{"de":"doch, schon (bejahende/betonende Partikel, Gegenteil von niet)","ex":"Ik heb geen tijd, maar ik kom wel.","exDe":"Ich habe keine Zeit, aber ich komme trotzdem."},{"de":"wohl, vermutlich (abschwächend)","ex":"Dat zal wel goed zijn.","exDe":"Das wird wohl gut sein."},{"de":"gut, wohl (in festen Wendungen), z. B. het gaat wel","ex":"Hoe gaat het? Het gaat wel.","exDe":"Wie geht's? Es geht so."}],"usage":"Modalpartikel: bejahender Kontrast zu 'niet'; abschwächendes 'wohl'. 'wel eens' = 'schon mal'; 'niet ... maar wel' = 'nicht ..., sondern'."},"bk_1408":{"lemma":"toch","displayNl":"toch","pos":"bijwoord","meanings":[{"de":"trotzdem, dennoch","ex":"Het regent, ik ga toch.","exDe":"Es regnet, ich gehe trotzdem."},{"de":"doch (bestätigungsheischend, am Satzende)","ex":"Je komt toch?","exDe":"Du kommst doch, oder?"},{"de":"doch, ja (nachdrückliche Partikel)","ex":"Dat weet je toch!","exDe":"Das weißt du doch!"}],"usage":"Adverb/Modalpartikel: 'trotzdem'; am Satzende bestätigungsheischend ('..., oder?'); nachdrückliches 'doch'."},"bk_1409":{"lemma":"echt","displayNl":"echt","pos":"bijwoord","meanings":[{"de":"wirklich, echt (verstärkend)","ex":"Dat is echt leuk.","exDe":"Das ist wirklich schön."},{"de":"echt, authentisch, unverfälscht","ex":"Is dit echt goud?","exDe":"Ist das echtes Gold?"}],"usage":"Sehr häufiges Verstärkungswort in der gesprochenen Sprache; als Adjektiv attributiv 'een echte vriend'."},"bk_1410":{"lemma":"helemaal","displayNl":"helemaal","pos":"bijwoord","meanings":[{"de":"ganz, völlig, komplett","ex":"Het is helemaal klaar.","exDe":"Es ist ganz fertig."},{"de":"den ganzen Weg, bis ganz nach","ex":"Hij komt helemaal uit Amerika.","exDe":"Er kommt den ganzen Weg aus Amerika."},{"de":"überhaupt (in Verneinung: helemaal niet/niets)","ex":"Ik snap er helemaal niets van.","exDe":"Ich verstehe überhaupt nichts davon."}],"usage":"'helemaal niet' = überhaupt nicht; 'helemaal' verstärkt oft Orts- oder Vollständigkeitsangaben."},"bk_1411":{"lemma":"daarom","displayNl":"daarom","pos":"bijwoord","meanings":[{"de":"deshalb, darum, deswegen","ex":"Ik ben ziek, daarom blijf ik thuis.","exDe":"Ich bin krank, deshalb bleibe ich zu Hause."}],"usage":"Konjunktionales Adverb; im Hauptsatz mit Inversion (daarom + Verb + Subjekt). Als kurze Antwort 'Daarom!' = 'Darum!'"},"bk_1412":{"lemma":"hetzelfde","displayNl":"hetzelfde","pos":"voornaamwoord","meanings":[{"de":"dasselbe, das Gleiche","ex":"Wij willen hetzelfde.","exDe":"Wir wollen dasselbe."},{"de":"(bijvoeglijk) derselbe/dieselbe/dasselbe","ex":"We wonen in hetzelfde huis.","exDe":"Wir wohnen im selben Haus."}],"usage":"Bei de-woorden: 'dezelfde' (dezelfde man), bei het-woorden und selbstständig: 'hetzelfde'. 'Het is mij hetzelfde' = es ist mir gleich."},"bk_1413":{"lemma":"wet","displayNl":"de wet","pos":"substantief","meanings":[{"de":"das Gesetz","ex":"De wet geldt voor iedereen.","exDe":"Das Gesetz gilt für alle."},{"de":"Naturgesetz, feste Regelmäßigkeit","ex":"De wet van de zwaartekracht.","exDe":"Das Gesetz der Schwerkraft."}],"usage":"'volgens de wet' = laut Gesetz; 'een wet aannemen' = ein Gesetz verabschieden.","genus":"de","plural":"wetten"},"bk_1414":{"lemma":"rechter","displayNl":"de rechter","pos":"substantief","meanings":[{"de":"der Richter / die Richterin","ex":"De rechter luistert naar beide partijen.","exDe":"Der Richter hört beiden Parteien zu."}],"usage":"Nicht verwechseln mit dem Adjektiv 'rechter' (rechte Seite, 'de rechterhand'). Als Beruf: 'voor de rechter verschijnen' = vor Gericht erscheinen.","genus":"de","plural":"rechters","illustratable":true},"bk_1415":{"lemma":"straf","displayNl":"de straf","pos":"substantief","meanings":[{"de":"die Strafe, Bestrafung","ex":"Hij krijgt een zware straf.","exDe":"Er bekommt eine schwere Strafe."}],"usage":"'straf krijgen' = bestraft werden; 'voor straf' = zur Strafe. Vom Verb 'straffen' (bestrafen) abgeleitet.","genus":"de","plural":"straffen"},"bk_1416":{"lemma":"recht","displayNl":"het recht","pos":"substantief","meanings":[{"de":"das Recht (Anspruch)","ex":"Iedereen heeft recht op een advocaat.","exDe":"Jeder hat ein Recht auf einen Anwalt."},{"de":"das Recht, die Rechtswissenschaft (Studienfach/Rechtsordnung)","ex":"Zij studeert recht in Utrecht.","exDe":"Sie studiert Jura in Utrecht."}],"usage":"'recht hebben op iets' = ein Recht auf etwas haben; Plural 'rechten' oft = Jurastudium ('rechten studeren'). Nicht verwechseln mit Adjektiv/Adverb 'recht' = gerade.","genus":"het","plural":"rechten"},"bk_1417":{"lemma":"gevangenis","displayNl":"de gevangenis","pos":"substantief","meanings":[{"de":"das Gefängnis","ex":"Hij zit twee jaar in de gevangenis.","exDe":"Er sitzt zwei Jahre im Gefängnis."},{"de":"die Haft","ex":"Na de gevangenis begon hij een nieuw leven.","exDe":"Nach der Haft begann er ein neues Leben."}],"usage":"Ort der Freiheitsstrafe; auch 'de bak' (umgangssprachlich).","genus":"de","plural":"gevangenissen","illustratable":true},"bk_1418":{"lemma":"agent","displayNl":"de agent","pos":"substantief","meanings":[{"de":"der Polizist / die Polizistin","ex":"De agent controleert mijn papieren.","exDe":"Der Polizist kontrolliert meine Papiere."},{"de":"der Agent / der Vertreter","ex":"Zijn agent regelt alle contracten.","exDe":"Sein Agent regelt alle Verträge."},{"de":"der (Geheim-)Agent","ex":"De agent werkte undercover.","exDe":"Der Agent arbeitete verdeckt."}],"usage":"Meist Polizist (politieagent); daneben Vertreter/Makler und Geheimagent.","genus":"de","plural":"agenten","illustratable":true},"bk_1419":{"lemma":"handtekening","displayNl":"de handtekening","pos":"substantief","meanings":[{"de":"die Unterschrift","ex":"Uw handtekening staat onderaan.","exDe":"Ihre Unterschrift steht unten."},{"de":"das Autogramm","ex":"De speler gaf een handtekening aan een fan.","exDe":"Der Spieler gab einem Fan ein Autogramm."}],"usage":"Namenszug zur Bestätigung; auch Autogramm eines Prominenten.","genus":"de","plural":"handtekeningen","illustratable":true},"bk_1422":{"lemma":"burger","displayNl":"de burger","pos":"substantief","meanings":[{"de":"der Bürger / die Bürgerin","ex":"Elke burger mag stemmen.","exDe":"Jeder Bürger darf wählen."},{"de":"der Zivilist (im Ggs. zu Militär/Polizei)","ex":"De agenten waren in burger gekleed.","exDe":"Die Polizisten waren in Zivil gekleidet."},{"de":"der Burger / das Hamburger-Bratling (umgangssprachlich)","ex":"Ik bestelde een burger met friet.","exDe":"Ich bestellte einen Burger mit Pommes."}],"usage":"Staatsbürger/Einwohner; 'in burger' = in Zivil; umgangssprachlich auch Hamburger.","genus":"de","plural":"burgers"},"bk_1423":{"lemma":"gemeente","displayNl":"de gemeente","pos":"substantief","meanings":[{"de":"die Gemeinde (Verwaltungseinheit)","ex":"Ik ga naar de gemeente voor een paspoort.","exDe":"Ich gehe zur Gemeinde für einen Reisepass."},{"de":"die Kommune / der Ort","ex":"Onze gemeente heeft vijftigduizend inwoners.","exDe":"Unsere Kommune hat fünfzigtausend Einwohner."},{"de":"die (Kirchen-)Gemeinde","ex":"De hele gemeente kwam naar de dienst.","exDe":"Die ganze Gemeinde kam zum Gottesdienst."}],"usage":"Kommunale Verwaltung/Behörde; auch geografischer Ort oder Kirchengemeinde. Plural auch 'gemeentes'.","genus":"de","plural":"gemeenten"},"bk_1424":{"lemma":"gemeentehuis","displayNl":"het gemeentehuis","pos":"substantief","meanings":[{"de":"das Rathaus","ex":"Het gemeentehuis is op het plein.","exDe":"Das Rathaus ist am Platz."}],"usage":"Sitz der Gemeindeverwaltung; in großen Städten oft 'stadhuis'.","genus":"het","plural":"gemeentehuizen","illustratable":true},"bk_1425":{"lemma":"identiteitskaart","displayNl":"de identiteitskaart","pos":"substantief","meanings":[{"de":"der Personalausweis / die Identitätskarte","ex":"Neem je identiteitskaart mee.","exDe":"Nimm deinen Personalausweis mit."}],"usage":"Amtliches Ausweisdokument; kurz oft 'ID-kaart'.","genus":"de","plural":"identiteitskaarten","illustratable":true},"bk_1426":{"lemma":"rijbewijs","displayNl":"het rijbewijs","pos":"substantief","meanings":[{"de":"der Führerschein","ex":"Ik heb mijn rijbewijs gehaald.","exDe":"Ich habe meinen Führerschein gemacht."}],"usage":"Fahrerlaubnis-Dokument; 'je rijbewijs halen' = den Führerschein machen.","genus":"het","plural":"rijbewijzen","illustratable":true},"bk_1427":{"lemma":"formulier","displayNl":"het formulier","pos":"substantief","meanings":[{"de":"das Formular","ex":"Vul het formulier volledig in.","exDe":"Füllen Sie das Formular vollständig aus."},{"de":"das Antragsformular, der Vordruck","ex":"Je moet een formulier invullen om je aan te melden.","exDe":"Du musst einen Vordruck ausfüllen, um dich anzumelden."}],"usage":"Neutrum (het). Konkretes Dokument mit auszufüllenden Feldern.","genus":"het","plural":"formulieren","illustratable":true},"bk_1428":{"lemma":"regering","displayNl":"de regering","pos":"substantief","meanings":[{"de":"die Regierung","ex":"De regering neemt een besluit.","exDe":"Die Regierung trifft eine Entscheidung."},{"de":"die Amtszeit, die Herrschaft (eines Monarchen)","ex":"Onder de regering van koning Willem groeide de handel.","exDe":"Unter der Herrschaft von König Willem wuchs der Handel."}],"usage":"Femininum-ähnlich, Artikel de. Abstrakter Begriff für Staatsführung/Kabinett.","genus":"de","plural":"regeringen"},"bk_1429":{"lemma":"minister","displayNl":"de minister","pos":"substantief","meanings":[{"de":"der Minister, die Ministerin","ex":"De minister houdt een toespraak.","exDe":"Der Minister hält eine Rede."}],"usage":"Artikel de. Regierungsmitglied; Plural meist ministers (auch ministeries für Ministerien nicht verwechseln).","genus":"de","plural":"ministers","illustratable":true},"bk_1430":{"lemma":"politiek","displayNl":"de politiek","pos":"substantief","meanings":[{"de":"die Politik (das politische Geschehen)","ex":"Hij is geïnteresseerd in politiek.","exDe":"Er interessiert sich für Politik."},{"de":"die Politik, die Strategie, das Vorgehen (in einer Sache)","ex":"Dat is niet handig als politiek.","exDe":"Das ist keine kluge Strategie."}],"usage":"Als Substantiv Artikel de, meist ohne Plural. Kann auch Adjektiv sein (politiek = politisch); hier substantivische Grundform.","genus":"de"},"bk_1431":{"lemma":"partij","displayNl":"de partij","pos":"substantief","meanings":[{"de":"die Partei (politisch)","ex":"Welke partij steun jij?","exDe":"Welche Partei unterstützt du?"},{"de":"die Partei, die Seite (in einem Streit/Vertrag)","ex":"Beide partijen zijn het eens geworden.","exDe":"Beide Parteien haben sich geeinigt."},{"de":"die Partie (Spiel, z. B. Schach oder Tennis)","ex":"Ze speelden een spannende partij schaak.","exDe":"Sie spielten eine spannende Partie Schach."},{"de":"die Partie, die Ladung, der Posten (Warenmenge)","ex":"Er is een nieuwe partij appels binnengekomen.","exDe":"Eine neue Ladung Äpfel ist eingetroffen."}],"usage":"Artikel de, Plural partijen. Stark polysem: politisch, juristisch, Spiel, Warenpartie.","genus":"de","plural":"partijen"},"bk_1432":{"lemma":"verkiezing","displayNl":"de verkiezing","pos":"substantief","meanings":[{"de":"die Wahl (Abstimmung)","ex":"De verkiezing is volgende maand.","exDe":"Die Wahl ist nächsten Monat."},{"de":"die Vorliebe, die Präferenz (bij verkiezing = vorzugsweise)","ex":"Bij verkiezing neem ik de trein.","exDe":"Vorzugsweise nehme ich den Zug."}],"usage":"Artikel de, oft im Plural verkiezingen (die Wahlen). Abstrakter Vorgang der Abstimmung.","genus":"de","plural":"verkiezingen"},"bk_1434":{"lemma":"stem","displayNl":"de stem","pos":"substantief","meanings":[{"de":"die Stimme (Klang, Sprechstimme)","ex":"Ze heeft een mooie, warme stem.","exDe":"Sie hat eine schöne, warme Stimme."},{"de":"die Stimme (bei einer Wahl/Abstimmung)","ex":"Elke stem telt.","exDe":"Jede Stimme zählt."}],"usage":"Artikel de, Plural stemmen. Homonymie: Sprechstimme und Wahlstimme.","genus":"de","plural":"stemmen"},"bk_1437":{"lemma":"burgemeester","displayNl":"de burgemeester","pos":"substantief","meanings":[{"de":"der Bürgermeister, die Bürgermeisterin","ex":"De burgemeester woont de opening bij.","exDe":"Der Bürgermeister wohnt der Eröffnung bei."}],"usage":"Artikel de, Plural burgemeesters. Oberhaupt einer Gemeinde; in NL nicht gewählt, sondern ernannt.","genus":"de","plural":"burgemeesters","illustratable":true},"bk_1438":{"lemma":"discussie","displayNl":"de discussie","pos":"substantief","meanings":[{"de":"die Diskussion","ex":"De discussie ging over belasting.","exDe":"Die Diskussion ging um Steuern."},{"de":"die Debatte, die Auseinandersetzung, der Streit","ex":"Er ontstond een felle discussie tussen de buren.","exDe":"Es entstand ein heftiger Streit zwischen den Nachbarn."}],"usage":"Abstraktes Substantiv. 'in discussie zijn' = im Gespraech/in der Debatte sein; 'ter discussie staan' = zur Debatte stehen.","genus":"de","plural":"discussies"},"bk_1441":{"lemma":"organisatie","displayNl":"de organisatie","pos":"substantief","meanings":[{"de":"die Organisation, die Einrichtung, der Verband","ex":"De organisatie helpt arme gezinnen.","exDe":"Die Organisation hilft armen Familien."},{"de":"die Organisation, die Planung (das Organisieren)","ex":"De organisatie van het feest kostte veel tijd.","exDe":"Die Organisation des Festes kostete viel Zeit."}],"usage":"Sowohl die Institution/der Verein als auch der Vorgang des Organisierens.","genus":"de","plural":"organisaties"},"bk_1442":{"lemma":"geldig","displayNl":"geldig","pos":"adjectief","meanings":[{"de":"gueltig, wirksam","ex":"Dit ticket is nog geldig.","exDe":"Dieses Ticket ist noch gueltig."},{"de":"stichhaltig, triftig (Argument, Grund)","ex":"Dat is een geldig argument.","exDe":"Das ist ein stichhaltiges Argument."}],"usage":"Attributiv 'een geldige reden'; Gegenteil 'ongeldig'. Substantiv: 'geldigheid' = Gueltigkeit."},"bk_1443":{"lemma":"recht","displayNl":"het recht","pos":"substantief","meanings":[{"de":"das Recht, der Anspruch","ex":"Ken je rechten als werknemer.","exDe":"Kenne deine Rechte als Arbeitnehmer."},{"de":"das Recht, die Rechtswissenschaft, Jura","ex":"Zij studeert rechten in Utrecht.","exDe":"Sie studiert Jura in Utrecht."},{"de":"die Gebuehr, die Abgabe (meist Plural)","ex":"Je moet leges en rechten betalen.","exDe":"Du musst Verwaltungsgebuehren und Abgaben zahlen."}],"usage":"Eingabe war Plural 'de rechten' -> Grundform Singular 'het recht'. 'rechten studeren' = Jura studieren; 'recht hebben op' = Anspruch haben auf.","genus":"het","plural":"rechten"},"bk_1444":{"lemma":"schroevendraaier","displayNl":"de schroevendraaier","pos":"substantief","meanings":[{"de":"der Schraubenzieher, der Schraubendreher","ex":"Geef mij de schroevendraaier even.","exDe":"Gib mir kurz den Schraubenzieher."}],"usage":"Werkzeug. Varianten: kruiskopschroevendraaier (Kreuzschlitz), platte schroevendraaier (Schlitz).","genus":"de","plural":"schroevendraaiers","illustratable":true},"bk_1445":{"lemma":"boormachine","displayNl":"de boormachine","pos":"substantief","meanings":[{"de":"die Bohrmaschine, der Bohrer (Werkzeug)","ex":"De boormachine is heel krachtig.","exDe":"Die Bohrmaschine ist sehr kraeftig."}],"usage":"Elektrowerkzeug; 'accuboormachine' = Akkuschrauber, 'klopboormachine' = Schlagbohrmaschine.","genus":"de","plural":"boormachines","illustratable":true},"bk_1446":{"lemma":"zaag","displayNl":"de zaag","pos":"substantief","meanings":[{"de":"die Saege","ex":"Met de zaag zaag ik het hout.","exDe":"Mit der Saege saege ich das Holz."}],"usage":"Werkzeug; Verb 'zagen' = saegen. Zusammensetzungen: handzaag (Handsaege), kettingzaag (Kettensaege).","genus":"de","plural":"zagen","illustratable":true},"bk_1447":{"lemma":"tang","displayNl":"de tang","pos":"substantief","meanings":[{"de":"die Zange","ex":"Ik knip de draad met een tang.","exDe":"Ich schneide den Draht mit einer Zange."}],"usage":"Werkzeug; Zusammensetzungen: nijptang (Kneifzange), buigtang (Rundzange), waterpomptang (Wasserpumpenzange).","genus":"de","plural":"tangen","illustratable":true},"bk_1448":{"lemma":"moer","displayNl":"de moer","pos":"substantief","meanings":[{"de":"Mutter (Schraubenmutter)","ex":"Draai de moer goed vast.","exDe":"Dreh die Mutter gut fest."},{"de":"Bodensatz, Schlamm","ex":"Op de bodem van het vat zit een laag moer.","exDe":"Am Boden des Fasses liegt eine Schicht Bodensatz."}],"usage":"Nicht mit 'moeder' (Mutter im Sinne von Elternteil) verwechseln: 'de moer' ist ausschließlich die Schraubenmutter.","genus":"de","plural":"moeren","illustratable":true},"bk_1449":{"lemma":"boor","displayNl":"de boor","pos":"substantief","meanings":[{"de":"Bohrer (Bohreinsatz, Bohrspitze)","ex":"Deze boor is voor beton.","exDe":"Dieser Bohrer ist für Beton."}],"usage":"Meint den Bohreinsatz; die Bohrmaschine heißt 'de boormachine'.","genus":"de","plural":"boren","illustratable":true},"bk_1450":{"lemma":"meetlat","displayNl":"de meetlat","pos":"substantief","meanings":[{"de":"Lineal, Messlatte","ex":"De meetlat is dertig centimeter lang.","exDe":"Das Lineal ist dreißig Zentimeter lang."},{"de":"Maßstab, Bewertungsmaßstab (übertragen)","ex":"Dat legt de lat hoog als meetlat voor de rest.","exDe":"Das setzt einen hohen Maßstab für den Rest."}],"usage":"Konkret ein Lineal/eine Messlatte; im übertragenen Sinn ein Vergleichs- oder Bewertungsmaßstab.","genus":"de","plural":"meetlatten","illustratable":true},"bk_1451":{"lemma":"meetlint","displayNl":"het meetlint","pos":"substantief","meanings":[{"de":"Maßband (flexibles Bandmaß)","ex":"Rol het meetlint helemaal uit.","exDe":"Roll das Maßband ganz aus."}],"usage":"Flexibles Band zum Messen; das aufrollbare Rollmaßband heißt oft 'de rolmaat'.","genus":"het","plural":"meetlinten","illustratable":true},"bk_1452":{"lemma":"gereedschapskist","displayNl":"de gereedschapskist","pos":"substantief","meanings":[{"de":"Werkzeugkasten, Werkzeugkiste","ex":"De gereedschapskist is zwaar.","exDe":"Der Werkzeugkasten ist schwer."}],"usage":"Tragbarer Kasten zur Aufbewahrung von Werkzeug.","genus":"de","plural":"gereedschapskisten","illustratable":true},"bk_1453":{"lemma":"werkbank","displayNl":"de werkbank","pos":"substantief","meanings":[{"de":"Werkbank","ex":"Hij werkt aan de werkbank.","exDe":"Er arbeitet an der Werkbank."}],"usage":"Stabiler Arbeitstisch, oft mit Schraubstock, zum Handwerken.","genus":"de","plural":"werkbanken","illustratable":true},"bk_1454":{"lemma":"kwast","displayNl":"de kwast","pos":"substantief","meanings":[{"de":"Pinsel (zum Streichen/Malen)","ex":"De kwast zit vol verf.","exDe":"Der Pinsel ist voller Farbe."},{"de":"Quaste, Troddel","ex":"Aan het gordijn hangt een gouden kwast.","exDe":"An der Gardine hängt eine goldene Quaste."}],"usage":"Vor allem der Malerpinsel; daneben auch eine dekorative Quaste/Troddel.","genus":"de","plural":"kwasten","illustratable":true},"bk_1455":{"lemma":"ladder","displayNl":"de ladder","pos":"substantief","meanings":[{"de":"Leiter (zum Hinaufsteigen)","ex":"Ik klim op de ladder.","exDe":"Ich klettere auf die Leiter."},{"de":"Laufmasche (in Strumpf/Strumpfhose)","ex":"Er zit een ladder in mijn panty.","exDe":"In meiner Strumpfhose ist eine Laufmasche."}],"usage":"Konkret die Steigleiter; im Textil-Kontext eine Laufmasche in Strümpfen.","genus":"de","plural":"ladders","illustratable":true},"bk_1456":{"lemma":"schep","displayNl":"de schep","pos":"substantief","meanings":[{"de":"die Schaufel, die Schippe","ex":"Met de schep graaf ik een gat in de tuin.","exDe":"Mit der Schaufel grabe ich ein Loch im Garten."},{"de":"eine Schaufel voll, eine Portion (Löffel/Kelle)","ex":"Doe nog een schep suiker in de koffie.","exDe":"Gib noch eine Schaufel Zucker in den Kaffee."}],"usage":"Konkretes Werkzeug; auch als Mengenangabe 'een schep + Stoff'. Plural: scheppen.","genus":"de","plural":"scheppen","illustratable":true},"bk_1457":{"lemma":"balk","displayNl":"de balk","pos":"substantief","meanings":[{"de":"der Balken (Bauholz, tragendes Element)","ex":"De houten balk draagt het hele dak.","exDe":"Der hölzerne Balken trägt das ganze Dach."},{"de":"das Notensystem, die Notenlinie (Musik)","ex":"Hij schreef de noten op de balk.","exDe":"Er schrieb die Noten auf das Notensystem."}],"usage":"Meist tragender Bau-Balken; in der Musik das Fünfliniensystem. Plural: balken.","genus":"de","plural":"balken","illustratable":true},"bk_1458":{"lemma":"staal","displayNl":"het staal","pos":"substantief","meanings":[{"de":"der Stahl (Werkstoff)","ex":"Staal is heel sterk en buigt bijna niet.","exDe":"Stahl ist sehr stark und biegt sich kaum."},{"de":"die Probe, das Muster (z. B. Stoff-, Farbprobe)","ex":"De verkoper liet een staal van de stof zien.","exDe":"Der Verkäufer zeigte eine Probe des Stoffes."}],"usage":"Als Werkstoff unzählbar (het staal). In der Bedeutung 'Probe/Muster' zählbar, Plural: stalen.","genus":"het","illustratable":true},"bk_1459":{"lemma":"plastic","displayNl":"het plastic","pos":"substantief","meanings":[{"de":"das Plastik, der Kunststoff","ex":"De buis is helemaal van plastic gemaakt.","exDe":"Das Rohr ist ganz aus Plastik gemacht."}],"usage":"Werkstoff, meist unzählbar (het plastic). Als Adjektiv auch 'plastic' = aus Plastik.","genus":"het","illustratable":true},"bk_1460":{"lemma":"beton","displayNl":"het beton","pos":"substantief","meanings":[{"de":"der Beton","ex":"De vloer is van glad, grijs beton.","exDe":"Der Boden ist aus glattem, grauem Beton."}],"usage":"Baustoff, unzählbar (het beton). Zusammensetzungen z. B. gewapend beton (Stahlbeton).","genus":"het","illustratable":true},"bk_1461":{"lemma":"tegel","displayNl":"de tegel","pos":"substantief","meanings":[{"de":"die Fliese, die Kachel","ex":"Eén tegel in de badkamer is kapot.","exDe":"Eine Fliese im Badezimmer ist kaputt."},{"de":"die (Boden-)Platte, der Gehwegstein","ex":"De stoep ligt vol met grijze tegels.","exDe":"Der Gehweg ist voller grauer Gehwegplatten."}],"usage":"Wand-/Bodenfliese (Badezimmer) oder Gehwegplatte draußen. Plural: tegels.","genus":"de","plural":"tegels","illustratable":true},"bk_1463":{"lemma":"draad","displayNl":"de draad","pos":"substantief","meanings":[{"de":"der Draht (aus Metall)","ex":"De koperen draad is te dun voor de lamp.","exDe":"Der Kupferdraht ist zu dünn für die Lampe."},{"de":"der Faden (zum Nähen, aus Garn)","ex":"Ik trek een draad door de naald.","exDe":"Ich ziehe einen Faden durch die Nadel."},{"de":"der (rote) Faden, der Zusammenhang (übertragen)","ex":"Ik ben in het verhaal de draad kwijt.","exDe":"Ich habe in der Geschichte den Faden verloren."}],"usage":"Metall-Draht oder Näh-Faden; übertragen 'de draad kwijt zijn' = den Faden verlieren. Plural: draden.","genus":"de","plural":"draden","illustratable":true},"bk_1464":{"lemma":"touw","displayNl":"het touw","pos":"substantief","meanings":[{"de":"das Seil, das Tau, der Strick","ex":"Bind het touw goed om de doos vast.","exDe":"Bind das Seil gut um die Kiste fest."}],"usage":"Dickes Seil/Tau aus gedrehten Fasern. Redewendung 'ergens geen touw aan vast kunnen knopen' = nicht schlau daraus werden. Plural: touwen.","genus":"het","plural":"touwen","illustratable":true},"bk_1465":{"lemma":"tape","displayNl":"de tape","pos":"substantief","meanings":[{"de":"das Klebeband, das Tape","ex":"Plak het gat dicht met tape.","exDe":"Kleb das Loch mit Klebeband zu."},{"de":"das Band, die Kassette (Tonband/Videoband)","ex":"Hij speelde een oude tape af.","exDe":"Er spielte ein altes Band ab."}],"usage":"Uitspraak als in het Engels: 'teep'. Meestal het plakband; ook een geluids- of videoband. Werkwoord: tapen (met tape vastplakken).","genus":"de","plural":"tapes","illustratable":true},"bk_1466":{"lemma":"boren","displayNl":"boren","pos":"werkwoord","meanings":[{"de":"bohren","ex":"Ik ga een gat in de muur boren.","exDe":"Ich werde ein Loch in die Wand bohren."},{"de":"(sich) bohren, eindringen","ex":"De worm boort zich door de aarde.","exDe":"Der Wurm bohrt sich durch die Erde."}],"usage":"Regelmatig werkwoord. Vaak met 'een gat boren'. Zelfstandig naamwoord: de boor (Bohrer), de boormachine (Bohrmaschine).","conjugation":{"presens":{"ik":"boor","jij":"boort","hij":"boort","wij":"boren"},"imperfectum":{"ik":"boorde","wij":"boorden"},"perfectum":{"aux":"hebben","participle":"geboord"}},"illustratable":true},"bk_1467":{"lemma":"zagen","displayNl":"zagen","pos":"werkwoord","meanings":[{"de":"sägen","ex":"Kun jij deze plank zagen?","exDe":"Kannst du dieses Brett sägen?"},{"de":"(umgangssprachlich) nörgeln, herumjammern","ex":"Hou op met zagen over het weer!","exDe":"Hör auf, über das Wetter zu jammern!"}],"usage":"Regelmatig werkwoord. Zelfstandig naamwoord: de zaag (Säge, meervoud: zagen). Informele betekenis 'zeuren' is heel gangbaar.","conjugation":{"presens":{"ik":"zaag","jij":"zaagt","hij":"zaagt","wij":"zagen"},"imperfectum":{"ik":"zaagde","wij":"zaagden"},"perfectum":{"aux":"hebben","participle":"gezaagd"}},"illustratable":true},"bk_1468":{"lemma":"schroeven","displayNl":"schroeven","pos":"werkwoord","meanings":[{"de":"schrauben, anschrauben","ex":"Ik schroef de plank aan de muur.","exDe":"Ich schraube das Brett an die Wand."}],"usage":"Regelmatig werkwoord. Zelfstandig naamwoord: de schroef (Schraube, meervoud: schroeven), de schroevendraaier (Schraubenzieher). Vaak met 'vast': vastschroeven.","conjugation":{"presens":{"ik":"schroef","jij":"schroeft","hij":"schroeft","wij":"schroeven"},"imperfectum":{"ik":"schroefde","wij":"schroefden"},"perfectum":{"aux":"hebben","participle":"geschroefd"}},"illustratable":true},"bk_1469":{"lemma":"lijmen","displayNl":"lijmen","pos":"werkwoord","meanings":[{"de":"kleben, leimen","ex":"We lijmen de twee stukken aan elkaar.","exDe":"Wir kleben die zwei Stücke aneinander."}],"usage":"Regelmatig werkwoord. Zelfstandig naamwoord: de lijm (Leim/Klebstoff). Voor plakband gebruik je eerder 'plakken'.","conjugation":{"presens":{"ik":"lijm","jij":"lijmt","hij":"lijmt","wij":"lijmen"},"imperfectum":{"ik":"lijmde","wij":"lijmden"},"perfectum":{"aux":"hebben","participle":"gelijmd"}},"illustratable":true},"bk_1470":{"lemma":"meten","displayNl":"meten","pos":"werkwoord","meanings":[{"de":"messen","ex":"Meet eerst voordat je zaagt.","exDe":"Miss zuerst, bevor du sägst."},{"de":"(sich) messen, vergleichen","ex":"Hij kan zich niet met haar meten.","exDe":"Er kann sich nicht mit ihr messen."}],"usage":"Onregelmatig werkwoord: verleden tijd 'mat/maten', voltooid deelwoord 'gemeten'. Zelfstandig naamwoord: de meting (Messung), de meter (Meter/Messgerät).","conjugation":{"presens":{"ik":"meet","jij":"meet","hij":"meet","wij":"meten"},"imperfectum":{"ik":"mat","wij":"maten"},"perfectum":{"aux":"hebben","participle":"gemeten"}},"illustratable":true},"bk_1471":{"lemma":"graven","displayNl":"graven","pos":"werkwoord","meanings":[{"de":"graben","ex":"We graven een gat voor de paal.","exDe":"Wir graben ein Loch für den Pfahl."}],"usage":"Onregelmatig werkwoord: verleden tijd 'groef/groeven', voltooid deelwoord 'gegraven'. Let op: 'graven' is ook het meervoud van 'graf' (Grab).","conjugation":{"presens":{"ik":"graaf","jij":"graaft","hij":"graaft","wij":"graven"},"imperfectum":{"ik":"groef","wij":"groeven"},"perfectum":{"aux":"hebben","participle":"gegraven"}},"illustratable":true},"bk_1472":{"lemma":"knippen","displayNl":"knippen","pos":"werkwoord","meanings":[{"de":"schneiden (mit der Schere)","ex":"Knip de draad op maat.","exDe":"Schneide den Draht auf Maß."},{"de":"(die Haare) schneiden","ex":"De kapper knipt mijn haar.","exDe":"Der Friseur schneidet meine Haare."},{"de":"schnippen, blinzeln (met de ogen knipperen/vingers)","ex":"Ze knipte met haar vingers.","exDe":"Sie schnippte mit den Fingern."}],"usage":"Regelmatig werkwoord; specifiek 'met een schaar snijden'. Zelfstandig naamwoord: de knip (het knippen), de knipbeurt (Haarschnitt). Voor snijden met een mes gebruik je 'snijden'.","conjugation":{"presens":{"ik":"knip","jij":"knipt","hij":"knipt","wij":"knippen"},"imperfectum":{"ik":"knipte","wij":"knipten"},"perfectum":{"aux":"hebben","participle":"geknipt"}},"illustratable":true},"bk_1473":{"lemma":"klus","displayNl":"de klus","pos":"substantief","meanings":[{"de":"die Arbeit, die Aufgabe","ex":"Dat is een grote klus.","exDe":"Das ist eine große Aufgabe."},{"de":"der Job, die (handwerkliche) Arbeit","ex":"Hij verdient wat bij met kleine klussen.","exDe":"Er verdient sich mit kleinen Jobs etwas dazu."},{"de":"die Reparaturarbeit, das Werkeln (klusje)","ex":"In het weekend doe ik graag klusjes in huis.","exDe":"Am Wochenende werkle ich gern im Haus herum."}],"usage":"Alltäglich; oft für eine abgegrenzte (handwerkliche) Aufgabe. Verkleinerung 'klusje' = kleine Erledigung; Verb 'klussen' = werkeln/basteln.","genus":"de","plural":"klussen"},"bk_1474":{"lemma":"elektricien","displayNl":"de elektricien","pos":"substantief","meanings":[{"de":"der Elektriker, die Elektrikerin","ex":"De elektricien legt nieuwe kabels aan.","exDe":"Der Elektriker verlegt neue Kabel."}],"usage":"Berufsbezeichnung. Betonung auf der letzten Silbe (-cien). Plural 'elektriciens'.","genus":"de","plural":"elektriciens","illustratable":true},"bk_1475":{"lemma":"bouwplaats","displayNl":"de bouwplaats","pos":"substantief","meanings":[{"de":"die Baustelle","ex":"Op de bouwplaats is het druk.","exDe":"Auf der Baustelle ist viel los."}],"usage":"Zusammensetzung: bouw (Bau) + plaats (Platz). Auch 'bouwterrein' geläufig.","genus":"de","plural":"bouwplaatsen","illustratable":true},"bk_1476":{"lemma":"werkplaats","displayNl":"de werkplaats","pos":"substantief","meanings":[{"de":"die Werkstatt","ex":"In de werkplaats staat veel gereedschap.","exDe":"In der Werkstatt steht viel Werkzeug."}],"usage":"Zusammensetzung: werk (Arbeit) + plaats (Platz). Raum zum Reparieren/Herstellen; auch Auto-/Fahrradwerkstatt.","genus":"de","plural":"werkplaatsen","illustratable":true},"bk_1477":{"lemma":"buis","displayNl":"de buis","pos":"substantief","meanings":[{"de":"das Rohr, die Röhre","ex":"De buis is verstopt.","exDe":"Das Rohr ist verstopft."},{"de":"der Fernseher, die Glotze (umgangssprachlich: de buis)","ex":"Hij hangt de hele avond voor de buis.","exDe":"Er hängt den ganzen Abend vor der Glotze."}],"usage":"Grundbedeutung: Rohr/Röhre (Wasser, Heizung). Umgangssprachlich 'de buis' = Fernseher. Plural 'buizen'.","genus":"de","plural":"buizen","illustratable":true},"bk_1478":{"lemma":"haak","displayNl":"de haak","pos":"substantief","meanings":[{"de":"der Haken","ex":"Hang de jas aan de haak.","exDe":"Häng die Jacke an den Haken."},{"de":"der Angelhaken","ex":"De vis zit aan de haak.","exDe":"Der Fisch hängt am Haken."},{"de":"die Gabel/der Hörer (Telefon: van de haak, op de haak)","ex":"De telefoon ligt van de haak.","exDe":"Der Telefonhörer ist abgenommen."}],"usage":"Grundbedeutung: Haken zum Aufhängen. Redewendungen: 'aan de haak slaan' (an Land ziehen), 'van de haak' (aus dem Schneider / Hörer abgenommen). Plural 'haken'.","genus":"de","plural":"haken","illustratable":true},"bk_1479":{"lemma":"helm","displayNl":"de helm","pos":"substantief","meanings":[{"de":"der Helm (Schutzhelm)","ex":"Op de bouwplaats draag je een helm.","exDe":"Auf der Baustelle trägst du einen Helm."},{"de":"der Fahrrad-/Motorradhelm","ex":"Zet je helm op als je gaat fietsen.","exDe":"Setz deinen Helm auf, wenn du Rad fährst."}],"usage":"Schutzhelm allgemein: Bau-, Fahrrad-, Motorrad-, Ritterhelm. Plural 'helmen'. (Homonym 'helm' = Strandhafer, selten.)","genus":"de","plural":"helmen","illustratable":true},"bk_1480":{"lemma":"zaklamp","displayNl":"de zaklamp","pos":"substantief","meanings":[{"de":"die Taschenlampe","ex":"Onder de trap heb ik een zaklamp nodig.","exDe":"Unter der Treppe brauche ich eine Taschenlampe."}],"usage":"Zusammensetzung: zak (Tasche) + lamp (Lampe). Plural 'zaklampen'.","genus":"de","plural":"zaklampen","illustratable":true},"bk_1481":{"lemma":"stang","displayNl":"de stang","pos":"substantief","meanings":[{"de":"die Stange (langer Metall-/Holzstab)","ex":"De stang is van metaal.","exDe":"Die Stange ist aus Metall."},{"de":"die Stange/das Oberrohr (waagerechtes Rohr am Herrenfahrrad)","ex":"Ze zat bij hem achterop, hij op de stang.","exDe":"Sie saß bei ihm hinten drauf, er auf der Stange."},{"de":"die Gebissstange, das Gebiss (beim Pferd)","ex":"Het paard bijt op de stang.","exDe":"Das Pferd beißt auf die Gebissstange."}],"usage":"Alltäglich für einen geraden Stab aus Metall oder Holz. 'Op de stang' = auf dem Fahrradrohr mitfahren.","genus":"de","plural":"stangen","illustratable":true},"bk_1482":{"lemma":"stevig","displayNl":"stevig","pos":"adjectief","meanings":[{"de":"fest, stabil, robust","ex":"De tafel is nu weer stevig.","exDe":"Der Tisch ist jetzt wieder stabil."},{"de":"kräftig, stämmig (von Körperbau)","ex":"Hij is een stevige man.","exDe":"Er ist ein kräftiger Mann."},{"de":"ordentlich, kräftig, tüchtig (als Adverb: stevig doorwerken, stevig regenen)","ex":"Het regent stevig vandaag.","exDe":"Es regnet heute kräftig."}],"usage":"Sehr gebräuchlich: für Gegenstände (stabil/fest), Menschen (kräftig) und als Verstärker (stevig = ordentlich)."},"bk_1483":{"lemma":"los","displayNl":"los","pos":"adjectief","meanings":[{"de":"locker, lose, nicht befestigt","ex":"De schroef zit los.","exDe":"Die Schraube ist locker."},{"de":"lose, einzeln, unverpackt","ex":"Ik koop de appels los, niet in een zak.","exDe":"Ich kaufe die Äpfel lose, nicht in einer Tüte."},{"de":"los!, auf geht's! (als Ausruf)","ex":"Klaar? Af! Los!","exDe":"Fertig? Los! Auf geht's!"}],"usage":"Gegenteil von 'vast'. 'Losgaan' = losgehen/abgehen; 'iets los hebben' = etwas locker/im Griff haben."},"bk_1484":{"lemma":"glad","displayNl":"glad","pos":"adjectief","meanings":[{"de":"glatt (Oberfläche ohne Unebenheiten)","ex":"Het hout voelt heel glad.","exDe":"Das Holz fühlt sich sehr glatt an."},{"de":"rutschig, schlüpfrig","ex":"Pas op, de weg is glad door het ijs.","exDe":"Vorsicht, die Straße ist glatt durch das Eis."},{"de":"glatt, völlig (als Verstärker: glad vergeten)","ex":"Ik was het glad vergeten.","exDe":"Ich hatte es glatt vergessen."}],"usage":"Beschreibt eine glatte Oberfläche, aber auch rutschige Straßen im Winter. Übertragen 'een gladde jongen' = ein aalglatter Typ."},"bk_1485":{"lemma":"recht","displayNl":"recht","pos":"adjectief","meanings":[{"de":"gerade (nicht krumm)","ex":"Zaag de plank helemaal recht.","exDe":"Säge das Brett ganz gerade."},{"de":"aufrecht, senkrecht","ex":"Ga eens recht zitten.","exDe":"Setz dich mal aufrecht hin."},{"de":"direkt, geradewegs (als Adverb)","ex":"Loop maar recht naar de kerk.","exDe":"Geh einfach geradewegs zur Kirche."}],"usage":"Als Adjektiv/Adverb 'gerade/aufrecht/direkt'. Achtung Homonym: 'het recht' = das Recht/Gesetz und der Anspruch (z. B. recht hebben op).","notes":"Homonym: het recht (Substantiv, het) = Recht/Gesetz, Anspruch."},"bk_1486":{"lemma":"scheef","displayNl":"scheef","pos":"adjectief","meanings":[{"de":"schief, schräg (nicht gerade)","ex":"Het schilderij hangt scheef.","exDe":"Das Bild hängt schief."},{"de":"schief, verkehrt (übertragen: eine schiefe Situation/ein schiefes Verhältnis)","ex":"De verhoudingen zijn scheef gegroeid.","exDe":"Die Verhältnisse sind schief geworden."}],"usage":"Gegenteil von 'recht'. 'Scheef hangen' = schief hängen; 'iets scheef opvatten' = etwas falsch auffassen."},"bk_1487":{"lemma":"tot de volgende keer","displayNl":"tot de volgende keer","pos":"uitdrukking","meanings":[{"de":"bis zum nächsten Mal","ex":"Bedankt en tot de volgende keer.","exDe":"Danke und bis zum nächsten Mal."}],"usage":"Freundliche Abschiedsformel, wenn man sich wiedersieht. Kürzer: 'tot de volgende'."},"bk_1488":{"lemma":"het gaat wel","displayNl":"het gaat wel","pos":"uitdrukking","meanings":[{"de":"es geht so, es geht schon (zurückhaltende Antwort auf 'Wie geht's?')","ex":"Hoe voel je je? – Het gaat wel.","exDe":"Wie fühlst du dich? – Es geht so."}],"usage":"Typische, leicht understatement-hafte Antwort: nicht super, aber okay. Wörtlich 'zijn/gaan', hier feste Wendung."},"bk_1489":{"lemma":"leuk je te ontmoeten","displayNl":"leuk je te ontmoeten","pos":"uitdrukking","meanings":[{"de":"schön, dich kennenzulernen","ex":"Leuk je te ontmoeten, ik ben Tom.","exDe":"Schön, dich kennenzulernen, ich bin Tom."}],"usage":"Informelle Begrüßungsfloskel beim ersten Kennenlernen (Duzen). Formeller: 'prettig kennis te maken'.","notes":"Feste Wendung; 'ontmoeten' = treffen/kennenlernen."},"bk_1490":{"lemma":"prettig kennis te maken","displayNl":"prettig kennis te maken","pos":"uitdrukking","meanings":[{"de":"angenehm, Sie kennenzulernen","ex":"Prettig kennis te maken, meneer De Vries.","exDe":"Angenehm, Sie kennenzulernen, Herr De Vries."},{"de":"freut mich (bei erster Vorstellung)","ex":"Prettig kennis te maken! – Insgelijks.","exDe":"Freut mich! – Ebenfalls."}],"usage":"Höfliche, eher formelle Kennenlern-Floskel (Siezen/Geschäftskontext). 'kennis maken met' = jemanden kennenlernen.","notes":"Formeller als 'leuk je te ontmoeten'."},"bk_1491":{"lemma":"sorry hoor","displayNl":"sorry hoor","pos":"uitdrukking","meanings":[{"de":"tut mir leid; sorry","ex":"Sorry hoor, dat wist ik niet.","exDe":"Tut mir leid, das wusste ich nicht."},{"de":"na, entschuldige mal (leicht abwehrend/ironisch)","ex":"Sorry hoor, maar dat is echt niet mijn schuld.","exDe":"Entschuldige mal, aber das ist echt nicht meine Schuld."}],"usage":"'hoor' ist eine abmildernde niederländische Partikel; verleiht der Entschuldigung einen lockeren, gesprochenen Ton.","notes":"Umgangssprachlich; Ton kann je nach Kontext entschuldigend oder leicht schnippisch sein."},"bk_1492":{"lemma":"het maakt niet uit","displayNl":"het maakt niet uit","pos":"uitdrukking","meanings":[{"de":"es macht nichts; es ist egal","ex":"Koffie of thee? Het maakt niet uit.","exDe":"Kaffee oder Tee? Es ist egal."},{"de":"das spielt keine Rolle","ex":"Het maakt niet uit hoe laat je komt.","exDe":"Es spielt keine Rolle, wann du kommst."}],"usage":"Vom trennbaren Verb 'uitmaken' (ausmachen, eine Rolle spielen). Häufige Alltagswendung zur Zustimmung/Gleichgültigkeit.","notes":"Verbkern 'uitmaken'; hier als feste Wendung eingetragen."},"bk_1493":{"lemma":"geen dank","displayNl":"geen dank","pos":"uitdrukking","meanings":[{"de":"keine Ursache; gern geschehen","ex":"Bedankt! – Geen dank hoor.","exDe":"Danke! – Keine Ursache."},{"de":"nichts zu danken","ex":"Geen dank, dat doe ik graag.","exDe":"Nichts zu danken, das mache ich gern."}],"usage":"Antwort auf 'bedankt/dank je'. Synonyme: 'graag gedaan', 'alsjeblieft'.","notes":"Feste Höflichkeitsformel."},"bk_1494":{"lemma":"beterschap","displayNl":"beterschap","pos":"uitdrukking","meanings":[{"de":"gute Besserung","ex":"Wat vervelend dat je ziek bent, beterschap!","exDe":"Wie ärgerlich, dass du krank bist, gute Besserung!"}],"usage":"Wunsch an eine kranke Person. Grammatisch ein Substantiv (het), im Alltag aber fast ausschließlich als feste Wunschformel gebraucht.","notes":"Formal ein het-Substantiv, hier als Grußformel/uitdrukking eingetragen."},"bk_1495":{"lemma":"wel thuis","displayNl":"wel thuis","pos":"uitdrukking","meanings":[{"de":"komm gut nach Hause","ex":"Doei, wel thuis!","exDe":"Tschüss, komm gut nach Hause!"},{"de":"gute Heimfahrt","ex":"Bedankt voor de avond, wel thuis!","exDe":"Danke für den Abend, gute Heimfahrt!"}],"usage":"Abschiedswunsch beim Weggehen; Kurzform von 'kom wel thuis' / 'kom veilig thuis'.","notes":"Feste Abschiedsfloskel."},"bk_1496":{"lemma":"succes ermee","displayNl":"succes ermee","pos":"uitdrukking","meanings":[{"de":"viel Erfolg damit","ex":"Morgen je examen? Succes ermee!","exDe":"Morgen deine Prüfung? Viel Erfolg damit!"},{"de":"viel Glück dabei","ex":"Nieuwe baan? Succes ermee!","exDe":"Neuer Job? Viel Glück dabei!"}],"usage":"'ermee' = 'damit' (Verweis auf eine zuvor genannte Aufgabe/Sache). Ermutigende Alltagsfloskel.","notes":"Pronominaladverb 'ermee' bezieht sich auf die anstehende Sache."},"bk_1497":{"lemma":"mag ik je iets vragen","displayNl":"mag ik je iets vragen?","pos":"uitdrukking","meanings":[{"de":"darf ich dich etwas fragen","ex":"Mag ik je iets vragen over het werk?","exDe":"Darf ich dich etwas zur Arbeit fragen?"},{"de":"darf ich Sie etwas fragen (höflich)","ex":"Mag ik u iets vragen, meneer?","exDe":"Darf ich Sie etwas fragen, mein Herr?"}],"usage":"Höfliche Einleitung, um eine Frage zu stellen. Wörtlich 'darf ich dir etwas fragen'. Formell mit 'u' statt 'je'."},"bk_1498":{"lemma":"mag ik erlangs","displayNl":"mag ik erlangs?","pos":"uitdrukking","meanings":[{"de":"darf ich vorbei (an dir vorbeikommen)","ex":"Sorry, mag ik erlangs?","exDe":"Entschuldigung, darf ich vorbei?"}],"usage":"Höfliche Bitte, um an jemandem in einem engen Raum vorbeizukommen. 'erlangs' = 'daran vorbei'. Alltäglich in Zug, Supermarkt, Menschenmenge."},"bk_1499":{"lemma":"wat zei je","displayNl":"wat zei je?","pos":"uitdrukking","meanings":[{"de":"was hast du gesagt","ex":"Wat zei je? Ik verstond je niet.","exDe":"Was hast du gesagt? Ich habe dich nicht verstanden."}],"usage":"Nachfrage bei Unverstandenem; Imperfekt von 'zeggen' (zei). Formeller: 'Wat zei u?' oder 'Wat zei je?' informell."},"bk_1500":{"lemma":"kun je dat herhalen","displayNl":"kun je dat herhalen?","pos":"uitdrukking","meanings":[{"de":"kannst du das wiederholen","ex":"Kun je dat herhalen, alsjeblieft?","exDe":"Kannst du das bitte wiederholen?"},{"de":"können Sie das wiederholen (höflich)","ex":"Kunt u dat herhalen, alstublieft?","exDe":"Können Sie das bitte wiederholen?"}],"usage":"Bitte um Wiederholung. Kernverb 'herhalen' (wiederholen). Höflich mit 'kunt u'."},"bk_1501":{"lemma":"een beetje langzamer graag","displayNl":"een beetje langzamer graag","pos":"uitdrukking","meanings":[{"de":"ein bisschen langsamer bitte","ex":"Een beetje langzamer graag, ik leer nog.","exDe":"Ein bisschen langsamer bitte, ich lerne noch."}],"usage":"Bitte, langsamer zu sprechen. 'graag' hier = 'bitte'. 'langzamer' = Komparativ von 'langzaam'."},"bk_1502":{"lemma":"hoe zeg je dat in het Nederlands","displayNl":"hoe zeg je dat in het Nederlands?","pos":"uitdrukking","meanings":[{"de":"wie sagt man das auf Niederländisch","ex":"Hoe zeg je dat in het Nederlands?","exDe":"Wie sagt man das auf Niederländisch?"}],"usage":"Frage nach der niederländischen Bezeichnung. 'in het Nederlands' = 'auf Niederländisch'. Sehr nützlich als Lernender."},"bk_1503":{"lemma":"wat betekent dat","displayNl":"wat betekent dat?","pos":"uitdrukking","meanings":[{"de":"was bedeutet das","ex":"Wat betekent dat woord precies?","exDe":"Was bedeutet dieses Wort genau?"}],"usage":"Frage nach der Bedeutung. Kernverb 'betekenen' (bedeuten). Auch 'Wat betekent dit?' für Näheres."},"bk_1504":{"lemma":"ik heb geen idee","displayNl":"ik heb geen idee","pos":"uitdrukking","meanings":[{"de":"ich habe keine Ahnung","ex":"Hoe laat komt hij? Ik heb geen idee.","exDe":"Wann kommt er? Ich habe keine Ahnung."}],"usage":"Ausdruck von Nichtwissen. 'idee' (het idee) = Idee/Ahnung. Umgangssprachlich sehr häufig."},"bk_1505":{"lemma":"even geduld","displayNl":"even geduld","pos":"uitdrukking","meanings":[{"de":"einen Moment Geduld; Moment mal, bitte kurz warten","ex":"Even geduld, ik ben zo klaar.","exDe":"Einen Moment Geduld, ich bin gleich fertig."},{"de":"nur etwas Geduld (aufmunternd)","ex":"Even geduld nog, het komt goed.","exDe":"Nur noch etwas Geduld, es wird gut."}],"usage":"Höfliche Bitte um kurzes Warten; wörtl. 'etwas Geduld'. 'geduld' = het geduld (Geduld)."},"bk_1506":{"lemma":"een ogenblikje","displayNl":"een ogenblikje","pos":"uitdrukking","meanings":[{"de":"einen Augenblick, einen Moment (bitte)","ex":"Een ogenblikje, ik pak mijn jas.","exDe":"Einen Augenblick, ich hole meine Jacke."},{"de":"kurz warten Sie / warte kurz","ex":"Een ogenblikje geduld, ik verbind u door.","exDe":"Einen Augenblick Geduld, ich verbinde Sie weiter."}],"usage":"Set-Phrase 'einen Augenblick (bitte)'; Diminutiv zu het ogenblik (der Augenblick)."},"bk_1507":{"lemma":"komen","displayNl":"komen","pos":"werkwoord","meanings":[{"de":"kommen","ex":"Hij komt morgen naar Utrecht.","exDe":"Er kommt morgen nach Utrecht."},{"de":"(eraan) komen — gleich da sein, sich nähern, sofort kommen","ex":"Momentje, ik kom eraan!","exDe":"Moment, ich komme sofort!"},{"de":"komen uit — stammen aus, herkommen","ex":"Ik kom uit Duitsland.","exDe":"Ich komme aus Deutschland."}],"usage":"Roheingabe 'ik kom eraan' → Infinitiv komen. 'eraan komen' = gleich da sein / sich nähern.","conjugation":{"presens":{"ik":"kom","jij":"komt","hij":"komt","wij":"komen"},"imperfectum":{"ik":"kwam","wij":"kwamen"},"perfectum":{"aux":"zijn","participle":"gekomen"}}},"bk_1508":{"lemma":"denken","displayNl":"denken","pos":"werkwoord","meanings":[{"de":"denken, nachdenken","ex":"Ik moet even nadenken, laat me denken.","exDe":"Ich muss kurz nachdenken, lass mich überlegen."},{"de":"glauben, meinen, annehmen (ik denk dat = ich denke/glaube, dass)","ex":"Ik denk dat het gaat regenen.","exDe":"Ich denke, dass es regnen wird."},{"de":"denken aan — an etwas/jemanden denken","ex":"Ik denk vaak aan mijn familie.","exDe":"Ich denke oft an meine Familie."}],"usage":"Roheingabe 'ik denk dat' → Infinitiv denken. Mit 'dat' = glauben/meinen.","conjugation":{"presens":{"ik":"denk","jij":"denkt","hij":"denkt","wij":"denken"},"imperfectum":{"ik":"dacht","wij":"dachten"},"perfectum":{"aux":"hebben","participle":"gedacht"}}},"bk_1509":{"lemma":"geloven","displayNl":"geloven","pos":"werkwoord","meanings":[{"de":"glauben, meinen, annehmen","ex":"Ik geloof dat hij gelijk heeft.","exDe":"Ich glaube, dass er recht hat."},{"de":"jemandem glauben, für wahr halten","ex":"Ik geloof je niet.","exDe":"Ich glaube dir nicht."},{"de":"geloven in — an etwas glauben (Glaube, Überzeugung)","ex":"Zij gelooft in God.","exDe":"Sie glaubt an Gott."}],"usage":"Roheingabe 'ik geloof dat' → Infinitiv geloven. Mit 'dat' = glauben/meinen.","conjugation":{"presens":{"ik":"geloof","jij":"gelooft","hij":"gelooft","wij":"geloven"},"imperfectum":{"ik":"geloofde","wij":"geloofden"},"perfectum":{"aux":"hebben","participle":"geloofd"}}},"bk_1510":{"lemma":"vinden","displayNl":"vinden","pos":"werkwoord","meanings":[{"de":"finden, meinen (eine Meinung haben: ik vind dat = ich finde, dass)","ex":"Ik vind dat we moeten wachten.","exDe":"Ich finde, dass wir warten sollten."},{"de":"finden, auffinden, entdecken","ex":"Ik heb mijn sleutels gevonden.","exDe":"Ich habe meine Schlüssel gefunden."},{"de":"etwas/jemanden (als) ... finden (bewerten)","ex":"Ik vind deze film heel leuk.","exDe":"Ich finde diesen Film sehr schön."}],"usage":"Roheingabe 'ik vind dat' → Infinitiv vinden. Mit 'dat'/Objekt = meinen/finden (Meinung); daneben finden (auffinden).","conjugation":{"presens":{"ik":"vind","jij":"vindt","hij":"vindt","wij":"vinden"},"imperfectum":{"ik":"vond","wij":"vonden"},"perfectum":{"aux":"hebben","participle":"gevonden"}}},"bk_1511":{"lemma":"volgens mij","displayNl":"volgens mij","pos":"uitdrukking","meanings":[{"de":"meiner Meinung nach, meiner Ansicht nach","ex":"Volgens mij is de winkel gesloten.","exDe":"Meiner Ansicht nach ist der Laden geschlossen."},{"de":"ich glaube / ich denke (Vermutung)","ex":"Volgens mij hebben we elkaar al eens ontmoet.","exDe":"Ich glaube, wir haben uns schon einmal getroffen."}],"usage":"Feste Wendung zur Meinungsäußerung; 'volgens' = laut/gemäß + Personalpronomen."},"bk_1512":{"lemma":"wat vind je","displayNl":"wat vind je","pos":"uitdrukking","meanings":[{"de":"was meinst du?, was hältst du davon?","ex":"Wat vind je van dit idee?","exDe":"Was meinst du zu dieser Idee?"},{"de":"wie gefällt dir ...? (Bewertung erfragen)","ex":"Wat vind je van mijn nieuwe jas?","exDe":"Wie findest du meine neue Jacke?"}],"usage":"Frage nach der Meinung; wörtl. 'was findest du'. Formell: 'wat vindt u'."},"bk_1513":{"lemma":"dat klopt","displayNl":"dat klopt","pos":"uitdrukking","meanings":[{"de":"das stimmt / das ist richtig","ex":"Je hebt om drie uur afgesproken, dat klopt.","exDe":"Du hast dich um drei Uhr verabredet, das stimmt."},{"de":"das haut hin / das passt (Zahlen, Rechnung)","ex":"Ik heb het geld geteld, dat klopt.","exDe":"Ich habe das Geld gezählt, es stimmt."}],"usage":"Feststehende Bestätigungsformel; 'kloppen' = stimmen/zutreffen. Sehr gebräuchlich als kurze Zustimmung."},"bk_1514":{"lemma":"klopt dat","displayNl":"klopt dat?","pos":"uitdrukking","meanings":[{"de":"stimmt das? / ist das richtig?","ex":"De trein vertrekt om acht uur, klopt dat?","exDe":"Der Zug fährt um acht ab, stimmt das?"}],"usage":"Rückfrage zur Bestätigung, umgestellte Form von 'dat klopt'. Verb 'kloppen' im Sinne von zutreffen."},"bk_1515":{"lemma":"dat klopt niet","displayNl":"dat klopt niet","pos":"uitdrukking","meanings":[{"de":"das stimmt nicht / das ist nicht richtig","ex":"Nee, dat klopt niet, het is anders.","exDe":"Nein, das stimmt nicht, es ist anders."}],"usage":"Verneinte Feststellung; Widerspruch zu einer Aussage oder Angabe."},"bk_1516":{"lemma":"dat is waar","displayNl":"dat is waar","pos":"uitdrukking","meanings":[{"de":"das ist wahr / das stimmt (zustimmend)","ex":"Het regent veel hier, dat is waar.","exDe":"Es regnet hier viel, das ist wahr."},{"de":"ach ja, richtig! (plötzliche Erinnerung)","ex":"O, dat is waar ook, ik moet nog bellen.","exDe":"Ach, das ist wahr, ich muss noch anrufen."}],"usage":"Zustimmung; 'waar' = wahr. Mit 'ook' oft als 'ach ja, richtig!' beim Sich-Erinnern."},"bk_1517":{"lemma":"gelijk hebben","displayNl":"je hebt gelijk","pos":"uitdrukking","meanings":[{"de":"du hast recht / recht haben","ex":"Je hebt gelijk, ik was het vergeten.","exDe":"Du hast recht, ich hatte es vergessen."}],"usage":"Wendung 'gelijk hebben' = recht haben; hier in der du-Form. Zustimmung, dass jemand richtig liegt."},"bk_1518":{"lemma":"dat is een goed idee","displayNl":"dat is een goed idee","pos":"uitdrukking","meanings":[{"de":"das ist eine gute Idee","ex":"Samen koken? Dat is een goed idee.","exDe":"Zusammen kochen? Das ist eine gute Idee."}],"usage":"Zustimmender Vorschlag-Kommentar; 'idee' ist het-Wort (het idee), Plural 'ideeën'."},"bk_1519":{"lemma":"ik weet het niet zeker","displayNl":"ik weet het niet zeker","pos":"uitdrukking","meanings":[{"de":"ich bin mir nicht sicher","ex":"Komt hij mee? Ik weet het niet zeker.","exDe":"Kommt er mit? Ich bin mir nicht sicher."}],"usage":"Unsicherheit ausdrücken; wörtlich 'ich weiß es nicht sicher'. 'zeker' = sicher, gewiss."},"bk_1520":{"lemma":"daarna","displayNl":"daarna","pos":"bijwoord","meanings":[{"de":"danach / anschließend (zeitlich)","ex":"Ik douch, en daarna ontbijt ik.","exDe":"Ich dusche, und danach frühstücke ich."},{"de":"darauf / im Anschluss (Reihenfolge)","ex":"Eerst het voorgerecht, daarna het hoofdgerecht.","exDe":"Zuerst die Vorspeise, danach das Hauptgericht."}],"usage":"Temporales Pronominaladverb (daar + na). Leitet die nächste Handlung ein; löst im Hauptsatz Inversion aus (daarna ontbijt ik)."},"bk_1521":{"lemma":"op dit moment","displayNl":"op dit moment","pos":"uitdrukking","meanings":[{"de":"im Moment, momentan, gerade jetzt","ex":"Op dit moment ben ik druk.","exDe":"Im Moment bin ich beschäftigt."},{"de":"zurzeit, aktuell (im aktuellen Zeitraum)","ex":"Op dit moment werk ik in Utrecht.","exDe":"Zurzeit arbeite ich in Utrecht."}],"usage":"Feste Zeitangabe; steht meist am Satzanfang oder -ende. Betont den gegenwärtigen Augenblick."},"bk_1522":{"lemma":"de hele tijd","displayNl":"de hele tijd","pos":"uitdrukking","meanings":[{"de":"die ganze Zeit, ununterbrochen, dauernd","ex":"Hij praat de hele tijd.","exDe":"Er redet die ganze Zeit."},{"de":"immerzu, ständig (mit leicht genervtem Unterton)","ex":"Ze klaagt de hele tijd over het weer.","exDe":"Sie beschwert sich ständig über das Wetter."}],"usage":"Adverbiale Zeitbestimmung; drückt Dauer oder ständige Wiederholung aus."},"bk_1523":{"lemma":"geen zorgen","displayNl":"geen zorgen","pos":"uitdrukking","meanings":[{"de":"keine Sorge, mach dir keine Sorgen","ex":"Geen zorgen, het komt goed.","exDe":"Keine Sorge, das wird schon."},{"de":"kein Problem, kein Stress (beruhigend)","ex":"Geen zorgen, ik regel het wel.","exDe":"Kein Problem, ich kümmere mich darum."}],"usage":"Beruhigende Formel, oft allein oder am Satzanfang. Umgangssprachliche Kurzform von 'maak je geen zorgen'."},"bk_1524":{"lemma":"het komt goed","displayNl":"het komt goed","pos":"uitdrukking","meanings":[{"de":"das wird schon, das renkt sich ein","ex":"Rustig maar, het komt goed.","exDe":"Ganz ruhig, das wird schon."},{"de":"es wird gut ausgehen, keine Sorge","ex":"Maak je niet druk, het komt goed.","exDe":"Reg dich nicht auf, es wird gut ausgehen."}],"usage":"Trost- und Zuspruchsformel. Feste Wendung mit unpersönlichem 'het' und dem Verb 'komen' im Sinne von 'gut werden'."},"bk_1525":{"lemma":"je best doen","displayNl":"doe je best","pos":"uitdrukking","meanings":[{"de":"gib dein Bestes, streng dich an","ex":"Doe je best op het examen!","exDe":"Gib dein Bestes bei der Prüfung!"},{"de":"sich Mühe geben (auch als Rückmeldung: 'ik doe mijn best')","ex":"Ik doe mijn best om op tijd te zijn.","exDe":"Ich gebe mein Bestes, um pünktlich zu sein."}],"usage":"Wendung 'je best doen' (sein Bestes tun); Possessiv passt sich der Person an (mijn/je/zijn best). 'Doe je best' ist die aufmunternde Imperativform."},"bk_1526":{"lemma":"dat kan gebeuren","displayNl":"dat kan gebeuren","pos":"uitdrukking","meanings":[{"de":"das kann passieren, das kommt vor","ex":"Je hebt een fout gemaakt, dat kan gebeuren.","exDe":"Du hast einen Fehler gemacht, das kann passieren."},{"de":"kein Wunder, das ist normal (beschwichtigend)","ex":"Je bent de bus gemist? Dat kan gebeuren.","exDe":"Du hast den Bus verpasst? Das kann passieren."}],"usage":"Beschwichtigende Formel, um einen Fehler oder ein Missgeschick zu relativieren."},"bk_1527":{"lemma":"dat geeft niet","displayNl":"dat geeft niet","pos":"uitdrukking","meanings":[{"de":"das macht nichts, macht nichts","ex":"Ik ben je pen kwijt. – Dat geeft niet.","exDe":"Ich habe deinen Stift verloren. – Das macht nichts."},{"de":"ist nicht schlimm, kein Problem (Reaktion auf Entschuldigung)","ex":"Sorry dat ik te laat ben. – Dat geeft niet.","exDe":"Entschuldige die Verspätung. – Ist nicht schlimm."}],"usage":"Standardreaktion auf eine Entschuldigung; 'geven' hier idiomatisch im Sinne von 'schaden/ausmachen'. Häufige Alltagsformel."},"bk_1528":{"lemma":"laat maar","displayNl":"laat maar","pos":"uitdrukking","meanings":[{"de":"lass mal gut sein, vergiss es","ex":"Wat zei je? – Laat maar, niet belangrijk.","exDe":"Was hast du gesagt? – Lass mal gut sein, nicht wichtig."},{"de":"schon gut, lass nur (etwas nicht weiter verfolgen)","ex":"Zal ik je helpen? – Laat maar, het lukt wel.","exDe":"Soll ich dir helfen? – Lass nur, es geht schon."}],"usage":"Umgangssprachliche Abwiegel-Formel aus 'laten' + Modalpartikel 'maar'. Signalisiert, dass etwas nicht weiter wichtig ist."},"bk_1529":{"lemma":"even kijken","displayNl":"even kijken","pos":"uitdrukking","meanings":[{"de":"mal sehen; lass mich kurz schauen","ex":"Even kijken waar ik het heb gelegd.","exDe":"Mal sehen, wo ich es hingelegt habe."},{"de":"kurz nachsehen / nachschauen","ex":"Ik ga even kijken of hij thuis is.","exDe":"Ich gehe kurz nachsehen, ob er zu Hause ist."}],"usage":"Häufige Alltagsfloskel; 'even' (mal kurz) + 'kijken' (schauen). Als kurzes Innehalten beim Überlegen oder als Ankündigung, kurz nachzusehen."},"bk_1530":{"lemma":"we zullen zien","displayNl":"we zullen zien","pos":"uitdrukking","meanings":[{"de":"wir werden sehen; abwarten","ex":"Komt het goed? We zullen zien.","exDe":"Wird es gut? Wir werden sehen."},{"de":"mal abwarten (Ausgang noch offen)","ex":"Misschien lukt het, we zullen zien.","exDe":"Vielleicht klappt es, wir werden sehen."}],"usage":"Vertröstende Floskel bei ungewissem Ausgang; drückt Zurückhaltung/Offenheit aus."},"bk_1531":{"lemma":"dat hoop ik","displayNl":"dat hoop ik","pos":"uitdrukking","meanings":[{"de":"das hoffe ich","ex":"Zie ik je morgen? Dat hoop ik!","exDe":"Sehe ich dich morgen? Das hoffe ich!"}],"usage":"Reaktionsfloskel, drückt Zuversicht/Wunsch aus. Verstärkbar: 'dat hoop ik wel'."},"bk_1532":{"lemma":"wat jammer","displayNl":"wat jammer","pos":"uitdrukking","meanings":[{"de":"wie schade","ex":"Kun je niet komen? Wat jammer!","exDe":"Du kannst nicht kommen? Wie schade!"}],"usage":"Ausruf des Bedauerns; 'jammer' (schade) mit verstärkendem 'wat'. Auch: 'wat jammer nou'."},"bk_1533":{"lemma":"wat vervelend","displayNl":"wat vervelend","pos":"uitdrukking","meanings":[{"de":"wie ärgerlich; wie unangenehm","ex":"Je trein is weg? Wat vervelend.","exDe":"Dein Zug ist weg? Wie ärgerlich."},{"de":"wie lästig / wie dumm (gelaufen)","ex":"Wat vervelend dat je ziek bent.","exDe":"Wie lästig, dass du krank bist."}],"usage":"Mitfühlender Ausruf bei einer unangenehmen Situation des Gegenübers. 'vervelend' = lästig/unangenehm."},"bk_1534":{"lemma":"wat erg","displayNl":"wat erg","pos":"uitdrukking","meanings":[{"de":"wie schlimm; wie furchtbar","ex":"Ze is ziek? Wat erg.","exDe":"Sie ist krank? Wie schlimm."}],"usage":"Starker Ausdruck des Mitgefühls/Entsetzens bei ernsteren Nachrichten (stärker als 'wat jammer')."},"bk_1535":{"lemma":"gelukkig maar","displayNl":"gelukkig maar","pos":"uitdrukking","meanings":[{"de":"zum Glück; ein Glück","ex":"De trein was er nog, gelukkig maar.","exDe":"Der Zug war noch da, zum Glück."},{"de":"gut, dass (erleichterte Reaktion)","ex":"Niemand raakte gewond, gelukkig maar.","exDe":"Niemand wurde verletzt, ein Glück."}],"usage":"Erleichterungsfloskel am Satzende oder als eigenständige Reaktion; 'maar' verstärkt hier die Erleichterung."},"bk_1536":{"lemma":"echt waar","displayNl":"echt waar","pos":"uitdrukking","meanings":[{"de":"wirklich wahr; tatsächlich","ex":"Het is echt waar, ik heb hem gezien.","exDe":"Es ist wirklich wahr, ich habe ihn gesehen."},{"de":"echt?; wirklich? (ungläubige Nachfrage)","ex":"Ik verhuis naar Spanje. – Echt waar?","exDe":"Ich ziehe nach Spanien. – Wirklich wahr?"}],"usage":"Doppelfunktion: bekräftigend ('das stimmt wirklich') oder als ungläubige Rückfrage ('echt?'). Tonabhängig."},"bk_1537":{"lemma":"geen idee","displayNl":"geen idee","pos":"uitdrukking","meanings":[{"de":"keine Ahnung","ex":"Waar is Tom? – Geen idee.","exDe":"Wo ist Tom? – Keine Ahnung."}],"usage":"Feste Wendung als kurze Antwort, wenn man etwas nicht weiß; entspricht dem deutschen \"keine Ahnung\"."},"bk_1538":{"lemma":"dat weet ik zeker","displayNl":"dat weet ik zeker","pos":"uitdrukking","meanings":[{"de":"das weiß ich sicher","ex":"Hij komt niet, dat weet ik zeker.","exDe":"Er kommt nicht, das weiß ich sicher."},{"de":"da bin ich mir ganz sicher","ex":"Dat weet ik zeker, ik heb het zelf gezien.","exDe":"Da bin ich mir ganz sicher, ich habe es selbst gesehen."}],"usage":"Betont die eigene Gewissheit über eine Aussage; \"zeker\" steht am Satzende."},"bk_1539":{"lemma":"bijvoorbeeld","displayNl":"bijvoorbeeld","pos":"bijwoord","meanings":[{"de":"zum Beispiel","ex":"Neem iets mee, bijvoorbeeld brood.","exDe":"Bring etwas mit, zum Beispiel Brot."},{"de":"etwa, beispielsweise","ex":"Je kunt het op verschillende manieren doen, bijvoorbeeld zo.","exDe":"Du kannst es auf verschiedene Arten machen, beispielsweise so."}],"usage":"Häufig abgekürzt \"bijv.\"; leitet ein Beispiel ein."},"bk_1540":{"lemma":"doe de groeten","displayNl":"doe de groeten","pos":"uitdrukking","meanings":[{"de":"grüß schön","ex":"Doe de groeten aan je familie.","exDe":"Grüß schön deine Familie."},{"de":"richte Grüße aus","ex":"Doe de groeten aan Anna van mij.","exDe":"Richte Anna schöne Grüße von mir aus."}],"usage":"Feste Grußformel; das Ziel wird mit \"aan\" angeschlossen, der Absender mit \"van\"."},"bk_1541":{"lemma":"kan het wat zachter","displayNl":"kan het wat zachter","pos":"uitdrukking","meanings":[{"de":"geht es etwas leiser","ex":"Kan het wat zachter, ik wil slapen.","exDe":"Geht es etwas leiser, ich möchte schlafen."},{"de":"könntest du es leiser machen","ex":"Kan het wat zachter? De baby slaapt.","exDe":"Könntest du es leiser machen? Das Baby schläft."}],"usage":"Höfliche Bitte, die Lautstärke zu senken; \"zachter\" = leiser."},"bk_1542":{"lemma":"zeg het maar","displayNl":"zeg het maar","pos":"uitdrukking","meanings":[{"de":"sag ruhig Bescheid","ex":"Als je iets nodig hebt, zeg het maar.","exDe":"Wenn du etwas brauchst, sag ruhig Bescheid."},{"de":"was darf es sein?, sag was du möchtest","ex":"Zeg het maar, wat wil je drinken?","exDe":"Sag ruhig, was möchtest du trinken?"}],"usage":"Ermunternde Wendung; \"maar\" macht die Aufforderung freundlich und unverbindlich. Auch als Bedien-Floskel im Laden/Café."},"bk_1543":{"lemma":"doe maar","displayNl":"doe maar","pos":"uitdrukking","meanings":[{"de":"mach ruhig","ex":"Mag ik het raam openen? – Doe maar.","exDe":"Darf ich das Fenster öffnen? – Mach ruhig."},{"de":"ich nehme (bei Bestellung)","ex":"Doe maar een koffie, alsjeblieft.","exDe":"Ich nehme einen Kaffee, bitte."}],"usage":"Sehr gebräuchliche Alltagsfloskel: gibt Erlaubnis (\"nur zu\") oder gibt beim Bestellen die Wahl an."},"bk_1544":{"lemma":"menigte","displayNl":"de menigte","pos":"substantief","meanings":[{"de":"die Menschenmenge","ex":"Er staat een menigte op straat.","exDe":"Eine Menge steht auf der Straße."},{"de":"die Menge, die große Anzahl","ex":"Een menigte mensen wachtte op de trein.","exDe":"Eine Menge Menschen wartete auf den Zug."}],"usage":"Bezeichnet vor allem eine große Ansammlung von Menschen; Plural auch \"menigtes\".","genus":"de","plural":"menigten","illustratable":true},"bk_1545":{"lemma":"familielid","displayNl":"het familielid","pos":"substantief","meanings":[{"de":"das Familienmitglied","ex":"Elk familielid krijgt een cadeau.","exDe":"Jedes Familienmitglied bekommt ein Geschenk."},{"de":"der/die Angehörige","ex":"Alleen familieleden mogen op bezoek komen.","exDe":"Nur Angehörige dürfen zu Besuch kommen."}],"usage":"Zusammensetzung uit 'familie' + 'lid'; Plural onregelmatig 'familieleden'.","genus":"het","plural":"familieleden"},"bk_1546":{"lemma":"verwant","displayNl":"de verwant","pos":"substantief","meanings":[{"de":"der/die Verwandte","ex":"Hij is een verre verwant.","exDe":"Er ist ein entfernter Verwandter."},{"de":"der Angehörige (durch Blutsverwandtschaft)","ex":"Zij is mijn enige nog levende verwant.","exDe":"Sie ist meine einzige noch lebende Verwandte."}],"usage":"Auch als Adjektief 'verwant' (verwandt); hier substantivisch für eine verwandte Person.","genus":"de","plural":"verwanten"},"bk_1547":{"lemma":"voorouder","displayNl":"de voorouder","pos":"substantief","meanings":[{"de":"der Vorfahr / die Vorfahrin","ex":"Mijn voorouders kwamen uit Friesland.","exDe":"Meine Vorfahren kamen aus Friesland."},{"de":"der Ahn","ex":"Deze foto toont een verre voorouder.","exDe":"Dieses Foto zeigt einen entfernten Ahn."}],"usage":"Roheintrag stand im Plural 'voorouders'; Grundform Singular = 'voorouder'. Meist im Plural gebruikt.","genus":"de","plural":"voorouders"},"bk_1548":{"lemma":"generatie","displayNl":"de generatie","pos":"substantief","meanings":[{"de":"die Generation (Altersgruppe)","ex":"De jonge generatie denkt anders.","exDe":"Die junge Generation denkt anders."},{"de":"die Generation (Familienstufe)","ex":"Drie generaties zaten aan tafel.","exDe":"Drei Generationen saßen am Tisch."},{"de":"die Generation (Produkt-/Technikstufe)","ex":"Dit is de nieuwste generatie telefoons.","exDe":"Das ist die neueste Generation von Telefonen."}],"usage":"Gebruikelijk in samenstellingen zoals 'generatiekloof'.","genus":"de","plural":"generaties"},"bk_1549":{"lemma":"peetouder","displayNl":"de peetouder","pos":"substantief","meanings":[{"de":"der Pate / die Patin (Patenelternteil)","ex":"Zij is de peetouder van het kind.","exDe":"Sie ist die Patin des Kindes."}],"usage":"Genderneutraler Oberbegriff; geslachtsspecifiek 'peetvader' / 'peetmoeder'.","genus":"de","plural":"peetouders"},"bk_1550":{"lemma":"petekind","displayNl":"het petekind","pos":"substantief","meanings":[{"de":"das Patenkind","ex":"Mijn petekind is net geboren.","exDe":"Mein Patenkind ist gerade geboren."}],"usage":"Plural onregelmatig 'petekinderen' (net als 'kind' → 'kinderen').","genus":"het","plural":"petekinderen"},"bk_1551":{"lemma":"weduwe","displayNl":"de weduwe","pos":"substantief","meanings":[{"de":"die Witwe","ex":"De weduwe woont alleen.","exDe":"Die Witwe wohnt allein."}],"usage":"Vrouwelijke vorm; mannelijk 'weduwnaar'. Plural 'weduwen' (ook 'weduwes').","genus":"de","plural":"weduwen"},"bk_1552":{"lemma":"weduwnaar","displayNl":"de weduwnaar","pos":"substantief","meanings":[{"de":"der Witwer","ex":"De weduwnaar mist zijn vrouw.","exDe":"Der Witwer vermisst seine Frau."}],"usage":"Mannelijke vorm van 'weduwe'. Plural 'weduwnaars' (ook 'weduwnaren').","genus":"de","plural":"weduwnaars"},"bk_1553":{"lemma":"pleeggezin","displayNl":"het pleeggezin","pos":"substantief","meanings":[{"de":"die Pflegefamilie","ex":"Het kind woont sinds een jaar in een pleeggezin.","exDe":"Das Kind wohnt seit einem Jahr in einer Pflegefamilie."}],"usage":"Familie, die ein Kind vorübergehend aufnimmt (pleeg- = Pflege-). Vgl. pleegouder, pleegkind.","genus":"het","plural":"pleeggezinnen"},"bk_1554":{"lemma":"alleenstaande","displayNl":"de alleenstaande","pos":"substantief","meanings":[{"de":"der/die Alleinstehende, der Single (allein lebende Person, ohne Partner)","ex":"Een alleenstaande betaalt vaak meer belasting.","exDe":"Ein Alleinstehender zahlt oft mehr Steuern."},{"de":"der/die Alleinerziehende (Kurzform, meist 'alleenstaande ouder/moeder')","ex":"Als alleenstaande moeder combineert ze werk en gezin.","exDe":"Als alleinerziehende Mutter verbindet sie Beruf und Familie."}],"usage":"Nominalisiertes Adjektiv (alleenstaand). Als Substantiv de-Wort, Plural alleenstaanden.","genus":"de","plural":"alleenstaanden"},"bk_1555":{"lemma":"vertrouweling","displayNl":"de vertrouweling","pos":"substantief","meanings":[{"de":"der/die Vertraute, die Vertrauensperson (jemand, dem man Geheimnisse anvertraut)","ex":"Zij is al jaren zijn naaste vertrouweling.","exDe":"Sie ist seit Jahren seine engste Vertraute."}],"usage":"Person, der man völlig vertraut. Nicht 'Vertrautheit' (dat is vertrouwdheid).","genus":"de","plural":"vertrouwelingen"},"bk_1556":{"lemma":"bekende","displayNl":"de bekende","pos":"substantief","meanings":[{"de":"der/die Bekannte (jemand, den man kennt, aber kein enger Freund)","ex":"Ik kwam op straat een oude bekende tegen.","exDe":"Ich traf auf der Straße einen alten Bekannten."},{"de":"eine bekannte/prominente Person (bes. 'bekende Nederlander', BN'er)","ex":"Op het gala waren veel bekenden aanwezig.","exDe":"Auf der Gala waren viele Prominente anwesend."}],"usage":"Nominalisiertes Adjektiv (bekend). Plural bekenden.","genus":"de","plural":"bekenden"},"bk_1557":{"lemma":"metgezel","displayNl":"de metgezel","pos":"substantief","meanings":[{"de":"der Begleiter, der Gefährte (Person oder Tier, das jemanden begleitet)","ex":"De hond is zijn trouwe metgezel op elke wandeling.","exDe":"Der Hund ist sein treuer Begleiter auf jedem Spaziergang."}],"usage":"Etwas gehoben/literarisch. Weibliche Form: metgezellin.","genus":"de","plural":"metgezellen"},"bk_1558":{"lemma":"tegenstander","displayNl":"de tegenstander","pos":"substantief","meanings":[{"de":"der Gegner, der Kontrahent (im Sport/Wettkampf)","ex":"Onze tegenstander speelt vandaag heel agressief.","exDe":"Unser Gegner spielt heute sehr aggressiv."},{"de":"der Gegner, der Widersacher (jemand, der gegen eine Idee/Sache ist)","ex":"Hij is een fel tegenstander van het nieuwe plan.","exDe":"Er ist ein entschiedener Gegner des neuen Plans."}],"usage":"Gegenteil: voorstander (Befürworter). Plural tegenstanders.","genus":"de","plural":"tegenstanders"},"bk_1559":{"lemma":"bondgenoot","displayNl":"de bondgenoot","pos":"substantief","meanings":[{"de":"der Verbündete, der Bundesgenosse, der Alliierte","ex":"In de oorlog was het land een belangrijke bondgenoot.","exDe":"Im Krieg war das Land ein wichtiger Verbündeter."}],"usage":"Plural bondgenoten (mit -en, kurzer o). Politisch/militärisch, aber auch übertragen.","genus":"de","plural":"bondgenoten"},"bk_1560":{"lemma":"leeftijdsgenoot","displayNl":"de leeftijdsgenoot","pos":"substantief","meanings":[{"de":"der/die Gleichaltrige, der Altersgenosse","ex":"Kinderen leren veel van hun leeftijdsgenoten.","exDe":"Kinder lernen viel von ihren Gleichaltrigen."}],"usage":"Zusammensetzung leeftijd + -genoot. Plural leeftijdsgenoten.","genus":"de","plural":"leeftijdsgenoten"},"bk_1561":{"lemma":"medemens","displayNl":"de medemens","pos":"substantief","meanings":[{"de":"der Mitmensch","ex":"We moeten onze medemens helpen.","exDe":"Wir müssen unserem Mitmenschen helfen."},{"de":"der Nächste (Mitbürger)","ex":"Respect voor je medemens is belangrijk.","exDe":"Respekt vor dem Nächsten ist wichtig."}],"usage":"Meist im Singular oder generisch verwendet; betont die soziale Verbundenheit zwischen Menschen.","genus":"de","plural":"medemensen"},"bk_1562":{"lemma":"omgang","displayNl":"de omgang","pos":"substantief","meanings":[{"de":"der Umgang, das Miteinander","ex":"De omgang met collega's is prettig.","exDe":"Der Umgang mit Kollegen ist angenehm."},{"de":"der Umgang (Beziehung/Kontakt)","ex":"Ze heeft veel omgang met kunstenaars.","exDe":"Sie hat viel Umgang mit Künstlern."}],"usage":"Abstraktes Nomen für zwischenmenschlichen Kontakt; oft mit 'met'. Plural selten.","genus":"de","plural":"omgangen"},"bk_1563":{"lemma":"band","displayNl":"de band","pos":"substantief","meanings":[{"de":"die Bindung, das Band (enge Verbindung)","ex":"Ze hebben een sterke band.","exDe":"Sie haben eine starke Bindung."},{"de":"der Reifen","ex":"De band van mijn fiets is lek.","exDe":"Der Reifen meines Fahrrads ist platt."},{"de":"die Band (Musikgruppe)","ex":"De band speelt vanavond in het café.","exDe":"Die Band spielt heute Abend im Café."},{"de":"das Band, der Streifen (Tonband, Fließband)","ex":"De koffers gaan over de lopende band.","exDe":"Die Koffer laufen über das Fließband."}],"usage":"Stark polysem: (1) emotionale Bindung, (2) Reifen, (3) Musikband, (4) Band/Förderband. Plural stets 'banden'.","genus":"de","plural":"banden"},"bk_1564":{"lemma":"vertrouwen","displayNl":"het vertrouwen","pos":"substantief","meanings":[{"de":"das Vertrauen","ex":"Vertrouwen is de basis van vriendschap.","exDe":"Vertrauen ist die Basis der Freundschaft."},{"de":"die Zuversicht, das Zutrauen","ex":"Ik heb er alle vertrouwen in dat het lukt.","exDe":"Ich habe alle Zuversicht, dass es klappt."}],"usage":"Abstraktes het-Nomen, meist ohne Plural. Gleichlautend mit dem Verb 'vertrouwen' (vertrauen).","genus":"het"},"bk_1565":{"lemma":"ruzie","displayNl":"de ruzie","pos":"substantief","meanings":[{"de":"der Streit, der Zank","ex":"Ze hadden een korte ruzie.","exDe":"Sie hatten einen kurzen Streit."},{"de":"der Krach (Auseinandersetzung)","ex":"Hij maakt vaak ruzie met zijn broer.","exDe":"Er streitet sich oft mit seinem Bruder."}],"usage":"Häufig in festen Wendungen: 'ruzie maken' (Streit anfangen), 'ruzie hebben' (Streit haben).","genus":"de","plural":"ruzies","illustratable":true},"bk_1566":{"lemma":"verzoening","displayNl":"de verzoening","pos":"substantief","meanings":[{"de":"die Versöhnung","ex":"Na de ruzie kwam de verzoening.","exDe":"Nach dem Streit kam die Versöhnung."},{"de":"die Aussöhnung (Beilegung eines Konflikts)","ex":"De twee landen streven naar verzoening.","exDe":"Die beiden Länder streben eine Aussöhnung an."}],"usage":"Abstraktes Nomen zum Verb 'verzoenen' (sich versöhnen); Gegenstück zu 'ruzie'.","genus":"de","plural":"verzoeningen"},"bk_1567":{"lemma":"scheiding","displayNl":"de scheiding","pos":"substantief","meanings":[{"de":"die Scheidung","ex":"Hun scheiding was verdrietig.","exDe":"Ihre Scheidung war traurig."},{"de":"die Trennung, die Teilung","ex":"De scheiding tussen werk en privé is belangrijk.","exDe":"Die Trennung zwischen Arbeit und Privatleben ist wichtig."},{"de":"der Scheitel (im Haar)","ex":"Hij draagt zijn haar met een scheiding aan de zijkant.","exDe":"Er trägt sein Haar mit einem Seitenscheitel."}],"usage":"Polysem: Ehescheidung, allgemeine Trennung/Teilung sowie Haarscheitel. Zum Verb 'scheiden'.","genus":"de","plural":"scheidingen"},"bk_1568":{"lemma":"verloving","displayNl":"de verloving","pos":"substantief","meanings":[{"de":"die Verlobung","ex":"We vieren hun verloving.","exDe":"Wir feiern ihre Verlobung."}],"usage":"Abstraktes Nomen zum Verb 'zich verloven' (sich verloben); Vorstufe zur Hochzeit ('huwelijk').","genus":"de","plural":"verlovingen"},"bk_1570":{"lemma":"zorg","displayNl":"de zorg","pos":"substantief","meanings":[{"de":"die Fürsorge, die Pflege, die Betreuung","ex":"Ouders geven veel zorg aan hun kinderen.","exDe":"Eltern geben ihren Kindern viel Fürsorge."},{"de":"die Sorge, die Besorgnis","ex":"Ik maak me zorgen over zijn gezondheid.","exDe":"Ich mache mir Sorgen um seine Gesundheit."},{"de":"das Gesundheitswesen, die Pflege(branche)","ex":"Zij werkt in de zorg.","exDe":"Sie arbeitet im Gesundheitswesen."}],"usage":"de-Wort; Plural 'zorgen' meist in der Bedeutung 'Sorgen'. In fester Wendung 'zich zorgen maken' = sich Sorgen machen.","genus":"de","plural":"zorgen"},"bk_1571":{"lemma":"steun","displayNl":"de steun","pos":"substantief","meanings":[{"de":"die Unterstützung, der Rückhalt, der Beistand","ex":"Ik krijg steun van mijn familie.","exDe":"Ich bekomme Unterstützung von meiner Familie."},{"de":"die Stütze, der Halt (physisch)","ex":"De oude muur heeft een extra steun nodig.","exDe":"Die alte Mauer braucht eine zusätzliche Stütze."}],"usage":"de-Wort; überwiegend abstrakt (Unterstützung), seltener konkret als physische Stütze. Meist im Singular.","genus":"de","plural":"steunen"},"bk_1572":{"lemma":"eenzaamheid","displayNl":"de eenzaamheid","pos":"substantief","meanings":[{"de":"die Einsamkeit","ex":"Eenzaamheid is soms zwaar.","exDe":"Einsamkeit ist manchmal schwer."}],"usage":"de-Wort auf -heid; abstrakt, kein Plural.","genus":"de"},"bk_1573":{"lemma":"gemeenschap","displayNl":"de gemeenschap","pos":"substantief","meanings":[{"de":"die Gemeinschaft, die Gemeinde","ex":"De gemeenschap helpt elkaar.","exDe":"Die Gemeinschaft hilft einander."},{"de":"der Geschlechtsverkehr (in 'gemeenschap hebben')","ex":"Zij hadden gemeenschap.","exDe":"Sie hatten Geschlechtsverkehr."}],"usage":"de-Wort; Grundbedeutung Gemeinschaft. In fester Wendung 'gemeenschap hebben' = Geschlechtsverkehr haben.","genus":"de","plural":"gemeenschappen"},"bk_1574":{"lemma":"samenleving","displayNl":"de samenleving","pos":"substantief","meanings":[{"de":"die Gesellschaft (soziales Gemeinwesen)","ex":"Onze samenleving verandert snel.","exDe":"Unsere Gesellschaft verändert sich schnell."}],"usage":"de-Wort; meint die Gesellschaft im Sinne des Zusammenlebens der Menschen, nicht die Firma (= bedrijf/onderneming).","genus":"de","plural":"samenlevingen"},"bk_1575":{"lemma":"indruk","displayNl":"de indruk","pos":"substantief","meanings":[{"de":"der Eindruck (Wirkung auf jemanden)","ex":"Hij maakt een goede indruk.","exDe":"Er macht einen guten Eindruck."},{"de":"der Eindruck, die Vorstellung (subjektive Wahrnehmung)","ex":"Ik heb de indruk dat het gaat regenen.","exDe":"Ich habe den Eindruck, dass es regnen wird."}],"usage":"de-Wort; feste Wendungen 'indruk maken' (Eindruck machen) und 'de indruk hebben dat' (den Eindruck haben, dass).","genus":"de","plural":"indrukken"},"bk_1576":{"lemma":"gedrag","displayNl":"het gedrag","pos":"substantief","meanings":[{"de":"das Verhalten, das Benehmen","ex":"Zijn gedrag is beleefd.","exDe":"Sein Verhalten ist höflich."}],"usage":"het-Wort; abstrakt, normalerweise ohne Plural (fachsprachlich 'gedragingen').","genus":"het"},"bk_1577":{"lemma":"houding","displayNl":"de houding","pos":"substantief","meanings":[{"de":"die Haltung, die Einstellung (mental)","ex":"Haar houding is positief.","exDe":"Ihre Haltung ist positiv."},{"de":"die Körperhaltung, die Pose (physisch)","ex":"Zit rechtop, let op je houding.","exDe":"Sitz aufrecht, achte auf deine Körperhaltung."}],"usage":"de-Wort; sowohl innere Einstellung als auch körperliche Haltung. Grundbedeutung überwiegend abstrakt.","genus":"de","plural":"houdingen"},"bk_1578":{"lemma":"rol","displayNl":"de rol","pos":"substantief","meanings":[{"de":"Rolle (Funktion, Aufgabe, Part)","ex":"Zij speelt een grote rol in het gezin.","exDe":"Sie spielt eine große Rolle in der Familie."},{"de":"Rolle (aufgerollter Gegenstand, z. B. Papier, Klebeband)","ex":"Ik koop een rol keukenpapier.","exDe":"Ich kaufe eine Rolle Küchenpapier."},{"de":"Theater-/Filmrolle","ex":"Hij kreeg de hoofdrol in de film.","exDe":"Er bekam die Hauptrolle im Film."},{"de":"Rolle, Purzelbaum (Turnen)","ex":"De kinderen maken een rol op de mat.","exDe":"Die Kinder machen eine Rolle auf der Matte."}],"usage":"Zentrale Bedeutung „Funktion/Aufgabe\"; daneben konkret als aufgerollter Gegenstand und als Turn-/Theaterrolle. Wegen dieser Mehrdeutigkeit nicht eindeutig bildlich.","genus":"de","plural":"rollen"},"bk_1579":{"lemma":"gezin","displayNl":"het gezin","pos":"substantief","meanings":[{"de":"Familie (Haushalt, Kernfamilie: Eltern und Kinder)","ex":"Het gezin eet samen.","exDe":"Die Familie isst zusammen."},{"de":"Haushalt (als soziale Einheit)","ex":"Ze komt uit een groot gezin.","exDe":"Sie kommt aus einer großen Familie."}],"usage":"„Gezin\" meint speziell die zusammenlebende Kernfamilie/den Haushalt; „familie\" umfasst dagegen die weitere Verwandtschaft.","genus":"het","plural":"gezinnen","illustratable":true},"bk_1580":{"lemma":"verantwoordelijkheid","displayNl":"de verantwoordelijkheid","pos":"substantief","meanings":[{"de":"Verantwortung (moralische/rechtliche Verpflichtung)","ex":"Ouders dragen veel verantwoordelijkheid.","exDe":"Eltern tragen viel Verantwortung."},{"de":"Zuständigkeit, Verantwortungsbereich","ex":"De veiligheid is de verantwoordelijkheid van de manager.","exDe":"Die Sicherheit ist die Zuständigkeit des Managers."}],"usage":"Abstraktes Nomen; „verantwoordelijkheid dragen/nemen\" = Verantwortung tragen/übernehmen.","genus":"de","plural":"verantwoordelijkheden"},"bk_1582":{"lemma":"respect","displayNl":"het respect","pos":"substantief","meanings":[{"de":"Respekt, Achtung","ex":"Respect is belangrijk in een relatie.","exDe":"Respekt ist wichtig in einer Beziehung."},{"de":"Wertschätzung, Anerkennung","ex":"Ik heb veel respect voor haar werk.","exDe":"Ich habe großen Respekt vor ihrer Arbeit."}],"usage":"Meist unzählbar (kein Plural); „respect hebben voor\" = Respekt haben vor.","genus":"het"},"bk_1583":{"lemma":"eerlijkheid","displayNl":"de eerlijkheid","pos":"substantief","meanings":[{"de":"Ehrlichkeit, Aufrichtigkeit","ex":"Eerlijkheid duurt het langst.","exDe":"Ehrlichkeit währt am längsten."},{"de":"Fairness, Gerechtigkeit","ex":"De scheidsrechter zorgde voor eerlijkheid in het spel.","exDe":"Der Schiedsrichter sorgte für Fairness im Spiel."}],"usage":"Abstraktes, meist unzählbares Nomen; „in alle eerlijkheid\" = ganz ehrlich gesagt.","genus":"de"},"bk_1584":{"lemma":"jeugd","displayNl":"de jeugd","pos":"substantief","meanings":[{"de":"Jugend (Lebensabschnitt)","ex":"Zijn jeugd was gelukkig.","exDe":"Seine Jugend war glücklich."},{"de":"Jugend (junge Menschen als Gruppe)","ex":"De jeugd van tegenwoordig sport veel.","exDe":"Die Jugend von heute treibt viel Sport."}],"usage":"Meist unzählbar; einmal als Lebensphase, einmal kollektiv für junge Menschen.","genus":"de"},"bk_1585":{"lemma":"senior","displayNl":"de senior","pos":"substantief","meanings":[{"de":"Senior, ältere Person","ex":"De senioren krijgen korting.","exDe":"Die Senioren bekommen Rabatt."},{"de":"Senior (Erwachsenen-/Altersklasse im Sport)","ex":"Hij speelt nu bij de senioren.","exDe":"Er spielt jetzt bei den Senioren."}],"usage":"Höfliche Bezeichnung für ältere Menschen; im Sport die Erwachsenenklasse (Gegenteil: junioren).","genus":"de","plural":"senioren","illustratable":true},"bk_1586":{"lemma":"bejaarde","displayNl":"de bejaarde","pos":"substantief","meanings":[{"de":"Betagter, alter/hochbetagter Mensch","ex":"De bejaarde krijgt hulp thuis.","exDe":"Der Betagte bekommt Hilfe zu Hause."},{"de":"Senior(in), Hochaltrige(r) (substantiviertes Adjektiv)","ex":"Veel bejaarden wonen in een verzorgingshuis.","exDe":"Viele Betagte wohnen in einem Pflegeheim."}],"usage":"Substantiviertes Adjektiv für einen hochbetagten Menschen; etwas förmlicher/älter als „senior\", betont hohes Alter.","genus":"de","plural":"bejaarden","illustratable":true},"bk_1587":{"lemma":"mentor","displayNl":"de mentor","pos":"substantief","meanings":[{"de":"der Mentor","ex":"Mijn mentor geeft goede raad.","exDe":"Mein Mentor gibt guten Rat."},{"de":"die Betreuungsperson (Studium/Ausbildung)","ex":"Elke student krijgt een eigen mentor.","exDe":"Jeder Student bekommt einen eigenen Mentor."}],"usage":"Persönlicher Ratgeber/Begleiter; im Bildungskontext auch Klassen-/Studienbetreuer.","genus":"de","plural":"mentoren"},"bk_1589":{"lemma":"vrijgezel","displayNl":"de vrijgezel","pos":"substantief","meanings":[{"de":"der Junggeselle / die unverheiratete Person","ex":"Hij blijft graag vrijgezel.","exDe":"Er bleibt gern Junggeselle."},{"de":"der/die Single (ohne Partner)","ex":"Als vrijgezel heeft ze veel vrijheid.","exDe":"Als Single hat sie viel Freiheit."}],"usage":"Bezeichnet eine ledige/partnerlose Person; oft auch attributiv als Zustand ('vrijgezel zijn').","genus":"de","plural":"vrijgezellen"},"bk_1590":{"lemma":"huisvriend","displayNl":"de huisvriend","pos":"substantief","meanings":[{"de":"der Hausfreund (enger Freund der Familie)","ex":"Hij is al jaren onze huisvriend.","exDe":"Er ist seit Jahren unser Hausfreund."}],"usage":"Guter Freund, der in der Familie ein und aus geht.","genus":"de","plural":"huisvrienden"},"bk_1592":{"lemma":"gastheer","displayNl":"de gastheer","pos":"substantief","meanings":[{"de":"der Gastgeber","ex":"De gastheer verwelkomt iedereen.","exDe":"Der Gastgeber begrüßt alle."},{"de":"der Wirt (Restaurant/Empfang)","ex":"De gastheer wijst ons onze tafel.","exDe":"Der Wirt zeigt uns unseren Tisch."},{"de":"der Wirt (Biologie, Parasit/Organismus)","ex":"De teek zoekt een gastheer.","exDe":"Die Zecke sucht einen Wirt."}],"usage":"Männliche Person, die Gäste empfängt; in der Biologie zudem 'Wirtsorganismus'.","genus":"de","plural":"gastheren"},"bk_1593":{"lemma":"gastvrouw","displayNl":"de gastvrouw","pos":"substantief","meanings":[{"de":"die Gastgeberin","ex":"De gastvrouw schenkt koffie in.","exDe":"Die Gastgeberin schenkt Kaffee ein."},{"de":"die Hostess / Empfangsdame","ex":"De gastvrouw begeleidt de bezoekers.","exDe":"Die Hostess begleitet die Besucher."}],"usage":"Weibliche Person, die Gäste empfängt oder betreut.","genus":"de","plural":"gastvrouwen"},"bk_1594":{"lemma":"nakomeling","displayNl":"de nakomeling","pos":"substantief","meanings":[{"de":"der Nachkomme / die Nachkommin","ex":"Zij is een nakomeling van boeren.","exDe":"Sie ist eine Nachkommin von Bauern."},{"de":"der Abkömmling / das Nachkommen (auch Tiere)","ex":"Deze hond heeft veel nakomelingen.","exDe":"Dieser Hund hat viele Nachkommen."}],"usage":"Direkter Nachfahre in der Abstammungslinie, bei Menschen und Tieren.","genus":"de","plural":"nakomelingen"},"bk_1595":{"lemma":"stamboom","displayNl":"de stamboom","pos":"substantief","meanings":[{"de":"der Stammbaum (Familie)","ex":"Onze stamboom is heel oud.","exDe":"Unser Stammbaum ist sehr alt."},{"de":"der Stammbaum / die Ahnentafel (auch Tierzucht)","ex":"De fokker toont de stamboom van de pup.","exDe":"Der Züchter zeigt den Stammbaum des Welpen."}],"usage":"Grafische Darstellung der Abstammung; für Menschen wie für Zuchttiere.","genus":"de","plural":"stambomen","illustratable":true},"bk_1597":{"lemma":"gescheiden","displayNl":"gescheiden","pos":"adjectief","meanings":[{"de":"geschieden (Ehe)","ex":"Mijn ouders zijn gescheiden.","exDe":"Meine Eltern sind geschieden."},{"de":"getrennt / voneinander getrennt","ex":"We houden ons afval gescheiden.","exDe":"Wir halten unseren Müll getrennt."},{"de":"getrennt lebend / separiert","ex":"Ze leven al een jaar gescheiden.","exDe":"Sie leben schon ein Jahr getrennt."}],"usage":"Adjektiv/Partizip zu 'scheiden'; meist im Ehe-Sinn (geschieden), daneben allgemein 'getrennt/separiert'."},"bk_1598":{"lemma":"verloofd","displayNl":"verloofd","pos":"adjectief","meanings":[{"de":"verlobt","ex":"Ze zijn sinds kort verloofd.","exDe":"Sie sind seit Kurzem verlobt."},{"de":"versprochen (an jdn. gebunden)","ex":"Hij is verloofd met een studiegenote.","exDe":"Er ist mit einer Kommilitonin verlobt."}],"usage":"Prädikativ mit 'zijn'; 'verloofd zijn/raken met iemand'. Als Substantiv: 'de verloofde' = der/die Verlobte."},"bk_1599":{"lemma":"zwanger","displayNl":"zwanger","pos":"adjectief","meanings":[{"de":"schwanger","ex":"Mijn zus is zwanger.","exDe":"Meine Schwester ist schwanger."},{"de":"schwanger (mit Zeitangabe)","ex":"Ze is vijf maanden zwanger.","exDe":"Sie ist im fünften Monat schwanger."}],"usage":"Prädikativ mit 'zijn/raken'; 'zwanger van/worden van iemand'. Nur auf Menschen/Tiere bezogen.","illustratable":true},"bk_1600":{"lemma":"opvoeden","displayNl":"opvoeden","pos":"werkwoord","meanings":[{"de":"erziehen","ex":"Ze voeden hun kinderen goed op.","exDe":"Sie erziehen ihre Kinder gut."},{"de":"großziehen","ex":"Ze heeft haar kinderen alleen opgevoed.","exDe":"Sie hat ihre Kinder allein großgezogen."}],"usage":"Trennbares Verb (op|voeden): 'ik voed mijn kind streng op'. Perfekt met 'hebben': 'opgevoed'.","conjugation":{"presens":{"ik":"voed op","jij":"voedt op","hij":"voedt op","wij":"voeden op"},"imperfectum":{"ik":"voedde op","wij":"voedden op"},"perfectum":{"aux":"hebben","participle":"opgevoed"}},"illustratable":true},"bk_1601":{"lemma":"vertrouwen","displayNl":"vertrouwen","pos":"werkwoord","meanings":[{"de":"vertrauen","ex":"Ik vertrouw mijn vrienden.","exDe":"Ich vertraue meinen Freunden."},{"de":"sich verlassen auf","ex":"Je kunt op hem vertrouwen.","exDe":"Du kannst dich auf ihn verlassen."},{"de":"anvertrauen","ex":"Ik vertrouw je dit geheim toe.","exDe":"Ich vertraue dir dieses Geheimnis an."},{"de":"das Vertrauen (Substantiv, het)","ex":"Hij heeft mijn vertrouwen gewonnen.","exDe":"Er hat mein Vertrauen gewonnen."}],"usage":"Verb: 'iemand vertrouwen' (mit Akk.) oder 'op iemand/iets vertrouwen'; 'iemand iets toevertrouwen'. Auch Substantiv 'het vertrouwen'.","conjugation":{"presens":{"ik":"vertrouw","jij":"vertrouwt","hij":"vertrouwt","wij":"vertrouwen"},"imperfectum":{"ik":"vertrouwde","wij":"vertrouwden"},"perfectum":{"aux":"hebben","participle":"vertrouwd"}}},"bk_1602":{"lemma":"roddelen","displayNl":"roddelen","pos":"werkwoord","meanings":[{"de":"tratschen, klatschen","ex":"De buren roddelen graag.","exDe":"Die Nachbarn tratschen gern."},{"de":"lästern (über jdn.)","ex":"Ze roddelen over hun collega.","exDe":"Sie lästern über ihre Kollegin."}],"usage":"Intransitiv: 'over iemand roddelen'. Perfekt met 'hebben': 'geroddeld'. Substantiv: 'de roddel' = der Klatsch.","conjugation":{"presens":{"ik":"roddel","jij":"roddelt","hij":"roddelt","wij":"roddelen"},"imperfectum":{"ik":"roddelde","wij":"roddelden"},"perfectum":{"aux":"hebben","participle":"geroddeld"}},"illustratable":true},"bk_1603":{"lemma":"steunen","displayNl":"steunen","pos":"werkwoord","meanings":[{"de":"unterstützen, beistehen","ex":"We steunen elkaar altijd.","exDe":"Wir unterstützen uns immer."},{"de":"stützen, abstützen","ex":"Hij steunde op zijn wandelstok.","exDe":"Er stützte sich auf seinen Gehstock."},{"de":"stöhnen, ächzen (vor Schmerz)","ex":"De zieke man steunde van de pijn.","exDe":"Der kranke Mann stöhnte vor Schmerz."}],"usage":"Bedeutung 1/2 met 'hebben': 'gesteund'; 'iemand/iets steunen' oder 'op iets steunen'. Homonym: 'steunen' = stöhnen.","conjugation":{"presens":{"ik":"steun","jij":"steunt","hij":"steunt","wij":"steunen"},"imperfectum":{"ik":"steunde","wij":"steunden"},"perfectum":{"aux":"hebben","participle":"gesteund"}}},"bk_1605":{"lemma":"verzorgen","displayNl":"verzorgen","pos":"werkwoord","meanings":[{"de":"versorgen, pflegen","ex":"Zij verzorgt haar oude moeder.","exDe":"Sie versorgt ihre alte Mutter."},{"de":"sich kümmern um, erledigen (Aufgabe)","ex":"Hij verzorgt de catering voor het feest.","exDe":"Er kümmert sich um das Catering für das Fest."}],"usage":"Untrennbar, met 'hebben': 'verzorgd'. 'iemand/iets verzorgen'. Partizip 'verzorgd' auch adjektivisch = gepflegt.","conjugation":{"presens":{"ik":"verzorg","jij":"verzorgt","hij":"verzorgt","wij":"verzorgen"},"imperfectum":{"ik":"verzorgde","wij":"verzorgden"},"perfectum":{"aux":"hebben","participle":"verzorgd"}},"illustratable":true},"bk_1606":{"lemma":"omgeving","displayNl":"de omgeving","pos":"substantief","meanings":[{"de":"Umgebung, Gegend","ex":"We verkennen de omgeving van de stad.","exDe":"Wir erkunden die Umgebung der Stadt."},{"de":"Umfeld (soziales)","ex":"Zijn omgeving steunt hem.","exDe":"Sein Umfeld unterstützt ihn."},{"de":"Nähe, Umkreis","ex":"In de omgeving is geen station.","exDe":"In der Nähe gibt es keinen Bahnhof."}],"usage":"'de omgeving', Plural 'omgevingen'. 'in de omgeving van' = in der Nähe von. Auch: Arbeits-/Lernumgebung.","genus":"de","plural":"omgevingen"},"bk_1607":{"lemma":"kameraad","displayNl":"de kameraad","pos":"substantief","meanings":[{"de":"Kamerad, Gefährte","ex":"Hij is een oude kameraad uit het leger.","exDe":"Er ist ein alter Kamerad aus der Armee."},{"de":"Kumpel, guter Freund","ex":"We zijn al jaren goede kameraden.","exDe":"Wir sind schon seit Jahren gute Kumpel."}],"usage":"Etwas formeller/kameradschaftlicher als 'vriend'; oft im Kontext von Verbundenheit (Arbeit, Sport, Militär).","genus":"de","plural":"kameraden"},"bk_1608":{"lemma":"maat","displayNl":"de maat","pos":"substantief","meanings":[{"de":"Kumpel, Kamerad","ex":"Hij is een goede maat van me.","exDe":"Er ist ein guter Kumpel von mir."},{"de":"Größe, Maß (z. B. Kleider-, Schuhgröße)","ex":"Welke maat schönen heb jij?","exDe":"Welche Schuhgröße hast du?"},{"de":"Takt (Musik)","ex":"De dansers bewegen op de maat van de muziek.","exDe":"Die Tänzer bewegen sich im Takt der Musik."},{"de":"Maß, Ausmaß","ex":"Alles met mate is gezond.","exDe":"Alles in Maßen ist gesund."}],"usage":"Stark polysem: 'maat' = Kumpel, aber auch Größe/Maß und musikalischer Takt; Bedeutung ergibt sich aus dem Kontext.","genus":"de","plural":"maten"},"bk_1609":{"lemma":"buurjongen","displayNl":"de buurjongen","pos":"substantief","meanings":[{"de":"Nachbarsjunge","ex":"De buurjongen wast onze auto in de vakantie.","exDe":"Der Nachbarsjunge wäscht in den Ferien unser Auto."}],"usage":"Zusammensetzung buur- (Nachbar) + jongen (Junge); weibliches Pendant: 'de buurmeisje/het buurmeisje' bzw. 'buurmeid'.","genus":"de","plural":"buurjongens","illustratable":true},"bk_1610":{"lemma":"beleefd","displayNl":"beleefd","pos":"adjectief","meanings":[{"de":"höflich, zuvorkommend","ex":"Hij is altijd beleefd tegen ouderen.","exDe":"Er ist immer höflich zu Älteren."},{"de":"höflich (Adverb), auf höfliche Weise","ex":"Ze vroeg heel beleefd om hulp.","exDe":"Sie bat ganz höflich um Hilfe."}],"usage":"Gegenteil: 'onbeleefd' (unhöflich). Komparativ 'beleefder', Superlativ 'beleefdst'."},"bk_1611":{"lemma":"trouw","displayNl":"trouw","pos":"adjectief","meanings":[{"de":"treu, loyal","ex":"Een hond is een trouwe vriend.","exDe":"Ein Hund ist ein treuer Freund."},{"de":"Treue, Loyalität (als Substantiv, de trouw)","ex":"Hij beloofde haar eeuwige trouw.","exDe":"Er versprach ihr ewige Treue."},{"de":"treu (Adverb), regelmäßig, verlässlich","ex":"Ze bezoekt haar oma trouw elke week.","exDe":"Sie besucht ihre Oma treu jede Woche."}],"usage":"Adjektiv ('trouwe vriend') und Substantiv 'de trouw' (Treue); nicht verwechseln mit dem Verb 'trouwen' (heiraten)."},"bk_1612":{"lemma":"voorhoofd","displayNl":"het voorhoofd","pos":"substantief","meanings":[{"de":"Stirn","ex":"Ze legde een koele hand op mijn voorhoofd.","exDe":"Sie legte eine kühle Hand auf meine Stirn."}],"usage":"Körperteil; het-Wort. Feste Wendung: 'het zweet stond op zijn voorhoofd' (der Schweiß stand ihm auf der Stirn).","genus":"het","plural":"voorhoofden","illustratable":true},"bk_1613":{"lemma":"elleboog","displayNl":"de elleboog","pos":"substantief","meanings":[{"de":"Ellenbogen","ex":"Hij stootte zijn elleboog tegen de tafel.","exDe":"Er stieß sich den Ellenbogen am Tisch."}],"usage":"Körperteil; de-Wort, Plural 'ellebogen'. Bildlich: 'ellebogenwerk' = Ellenbogenmentalität.","genus":"de","plural":"ellebogen","illustratable":true},"bk_1614":{"lemma":"enkel","displayNl":"de enkel","pos":"substantief","meanings":[{"de":"Knöchel, Fußgelenk","ex":"Ik heb mijn enkel verzwikt tijdens het hardlopen.","exDe":"Ich habe mir beim Joggen den Knöchel verstaucht."},{"de":"einzig, nur, bloß (als Wort 'enkel' in anderer Wortart – Adjektiv/Adverb)","ex":"Er was nog enkel één kaartje over.","exDe":"Es war nur noch eine einzige Karte übrig."}],"usage":"Als Substantiv 'de enkel' = Knöchel (Plural 'enkels'). Homonym: 'enkel' auch als Adjektiv/Adverb = einzig/nur (v. a. belgisch-niederländisch) sowie 'enkel(e)' = einige.","genus":"de","plural":"enkels","illustratable":true},"bk_1615":{"lemma":"heup","displayNl":"de heup","pos":"substantief","meanings":[{"de":"die Hüfte","ex":"Oma heeft een nieuwe heup gekregen.","exDe":"Oma hat eine neue Hüfte bekommen."},{"de":"die Hüftpartie (seitlicher Körperbereich)","ex":"Ze zette haar handen in haar zij, op haar heupen.","exDe":"Sie stemmte die Hände in die Seiten, auf ihre Hüften."}],"usage":"Körperteil; oft im medizinischen Kontext (heupoperatie, kunstheup).","genus":"de","plural":"heupen","illustratable":true},"bk_1616":{"lemma":"pols","displayNl":"de pols","pos":"substantief","meanings":[{"de":"das Handgelenk","ex":"Mijn pols is gezwollen na de val.","exDe":"Mein Handgelenk ist nach dem Sturz geschwollen."},{"de":"der Puls (Herzschlag am Handgelenk)","ex":"De verpleegkundige voelde mijn pols.","exDe":"Die Krankenpflegerin fühlte meinen Puls."},{"de":"die Stange, der Sprungstab (beim Stabhochsprung)","ex":"Met een lange pols sprong hij over de lat.","exDe":"Mit einer langen Stange sprang er über die Latte."}],"usage":"Homonym: Handgelenk, Puls und Sprungstab; häufigste Bedeutungen Handgelenk/Puls.","genus":"de","plural":"polsen","illustratable":true},"bk_1617":{"lemma":"long","displayNl":"de long","pos":"substantief","meanings":[{"de":"die Lunge","ex":"Roken is slecht voor je longen.","exDe":"Rauchen ist schlecht für die Lunge."},{"de":"die Lunge als Atemkraft/Atem","ex":"De duiker had sterke longen en bleef lang onder water.","exDe":"Der Taucher hatte eine starke Lunge und blieb lange unter Wasser."}],"usage":"Meist im Plural (longen) verwendet, wenn beide Lungenflügel gemeint sind.","genus":"de","plural":"longen","illustratable":true},"bk_1618":{"lemma":"maag","displayNl":"de maag","pos":"substantief","meanings":[{"de":"der Magen","ex":"Mijn maag is van streek.","exDe":"Mein Magen ist verstimmt."},{"de":"der Magen (als Hunger-/Sättigungsgefühl)","ex":"Op een lege maag kan ik niet werken.","exDe":"Auf leeren Magen kann ich nicht arbeiten."}],"usage":"Plural magen mit Umlautwechsel aa->a; oft in Wendungen (op een lege maag, van streek).","genus":"de","plural":"magen","illustratable":true},"bk_1619":{"lemma":"bot","displayNl":"het bot","pos":"substantief","meanings":[{"de":"der Knochen","ex":"Melk is goed voor je botten.","exDe":"Milch ist gut für die Knochen."},{"de":"die Flunder, der Butt (Plattfisch)","ex":"De visser ving een bot in de Noordzee.","exDe":"Der Fischer fing eine Flunder in der Nordsee."}],"usage":"Homonym: het bot = Knochen (Plural botten); de bot = Plattfisch. Auch Adjektiv bot = stumpf/schroff (eigenes Lemma).","genus":"het","plural":"botten","illustratable":true},"bk_1620":{"lemma":"spier","displayNl":"de spier","pos":"substantief","meanings":[{"de":"der Muskel","ex":"Mijn spieren doen pijn na het sporten.","exDe":"Meine Muskeln tun nach dem Sport weh."}],"usage":"Körperteil; oft im Plural (spieren) und in Wendung geen spier vertrekken = keine Miene verziehen.","genus":"de","plural":"spieren","illustratable":true},"bk_1621":{"lemma":"hersenen","displayNl":"de hersenen","pos":"substantief","meanings":[{"de":"das Gehirn, die Hirnmasse","ex":"De hersenen sturen het hele lichaam aan.","exDe":"Das Gehirn steuert den ganzen Körper."},{"de":"der Verstand, die Denkfähigkeit","ex":"Gebruik je hersenen voordat je iets zegt.","exDe":"Benutze deinen Verstand, bevor du etwas sagst."}],"usage":"Plurale tantum: steht immer im Plural (de hersenen); Alternative Einzahl het brein.","genus":"de","plural":"hersenen","illustratable":true},"bk_1622":{"lemma":"rib","displayNl":"de rib","pos":"substantief","meanings":[{"de":"die Rippe","ex":"Hij heeft bij het voetballen een rib gebroken.","exDe":"Er hat sich beim Fußball eine Rippe gebrochen."},{"de":"die Kante (einer Form/eines Körpers, z. B. Würfelkante)","ex":"Een kubus heeft twaalf ribben.","exDe":"Ein Würfel hat zwölf Kanten."}],"usage":"Körperteil (Plural ribben); übertragen geometrische Kante eines Körpers.","genus":"de","plural":"ribben","illustratable":true},"bk_1623":{"lemma":"blaar","displayNl":"de blaar","pos":"substantief","meanings":[{"de":"die Blase (auf der Haut)","ex":"Ik heb een blaar op mijn voet van het lopen.","exDe":"Ich habe vom Laufen eine Blase am Fuß."},{"de":"die Brandblase","ex":"Door de hete pan kreeg hij een blaar op zijn hand.","exDe":"Durch die heiße Pfanne bekam er eine Brandblase an der Hand."}],"usage":"Hautblase durch Reibung, Verbrennung o. Ä.; 'een blaar krijgen/hebben'.","genus":"de","plural":"blaren","illustratable":true},"bk_1624":{"lemma":"blauwe plek","displayNl":"de blauwe plek","pos":"substantief","meanings":[{"de":"der blaue Fleck, das Hämatom","ex":"Ik heb een blauwe plek op mijn arm van de val.","exDe":"Ich habe von dem Sturz einen blauen Fleck am Arm."}],"usage":"Bluterguss durch Stoß/Sturz; wörtlich 'blauer Fleck', feste Wortverbindung.","genus":"de","plural":"blauwe plekken","illustratable":true},"bk_1625":{"lemma":"allergie","displayNl":"de allergie","pos":"substantief","meanings":[{"de":"die Allergie","ex":"Ik heb een allergie voor noten.","exDe":"Ich habe eine Allergie gegen Nüsse."},{"de":"die Überempfindlichkeit, starke Abneigung (übertragen)","ex":"Hij heeft een allergie voor bureaucratie.","exDe":"Er hat eine Allergie gegen Bürokratie."}],"usage":"'een allergie voor iets hebben' = allergisch gegen etwas sein; auch übertragen für starke Abneigung.","genus":"de","plural":"allergieën"},"bk_1626":{"lemma":"infectie","displayNl":"de infectie","pos":"substantief","meanings":[{"de":"die Infektion","ex":"De wond heeft een infectie.","exDe":"Die Wunde hat eine Infektion."},{"de":"die Ansteckung (mit einem Erreger)","ex":"Er is een infectie met het virus vastgesteld.","exDe":"Es wurde eine Infektion mit dem Virus festgestellt."}],"usage":"Ansteckung/Wundinfektion; 'een infectie oplopen/hebben'.","genus":"de","plural":"infecties"},"bk_1627":{"lemma":"ontsteking","displayNl":"de ontsteking","pos":"substantief","meanings":[{"de":"die Entzündung (medizinisch)","ex":"Hij heeft een ontsteking in zijn oor.","exDe":"Er hat eine Entzündung im Ohr."},{"de":"die Zündung, das Entzünden (Feuer/Motor)","ex":"De ontsteking van de motor werkt niet.","exDe":"Die Zündung des Motors funktioniert nicht."}],"usage":"Medizinisch: Entzündung ('oorontsteking', 'blaasontsteking'); technisch: Zündung.","genus":"de","plural":"ontstekingen"},"bk_1628":{"lemma":"misselijkheid","displayNl":"de misselijkheid","pos":"substantief","meanings":[{"de":"die Übelkeit, das Unwohlsein","ex":"De misselijkheid gaat niet weg.","exDe":"Die Übelkeit geht nicht weg."}],"usage":"Gefühl der Übelkeit; meist ohne Plural. Adjektiv 'misselijk' = übel/unwohl.","genus":"de"},"bk_1629":{"lemma":"diarree","displayNl":"de diarree","pos":"substantief","meanings":[{"de":"der Durchfall, die Diarrhö","ex":"Het kind heeft diarree.","exDe":"Das Kind hat Durchfall."}],"usage":"Medizinisch, meist ohne Artikel/Plural: 'diarree hebben'.","genus":"de"},"bk_1630":{"lemma":"jeuk","displayNl":"de jeuk","pos":"substantief","meanings":[{"de":"der Juckreiz, das Jucken","ex":"Ik heb jeuk op mijn rug.","exDe":"Ich habe Juckreiz am Rücken."}],"usage":"Sinnesempfindung; meist ohne Plural: 'jeuk hebben/krijgen'. Verb 'jeuken' = jucken.","genus":"de"},"bk_1631":{"lemma":"uitslag","displayNl":"de uitslag","pos":"substantief","meanings":[{"de":"der (Haut-)Ausschlag","ex":"Zij heeft rode uitslag op haar huid.","exDe":"Sie hat einen roten Ausschlag auf der Haut."},{"de":"das Ergebnis, der Ausgang (Wahl, Spiel)","ex":"De uitslag van de verkiezingen komt vanavond.","exDe":"Das Ergebnis der Wahl kommt heute Abend."}],"usage":"Medizinisch 'Hautausschlag', aber ebenso häufig 'Ergebnis/Ausgang' einer Wahl, Prüfung oder eines Spiels.","genus":"de","plural":"uitslagen"},"bk_1632":{"lemma":"duizeligheid","displayNl":"de duizeligheid","pos":"substantief","meanings":[{"de":"der Schwindel, die Benommenheit","ex":"De duizeligheid maakt lopen lastig.","exDe":"Der Schwindel macht das Gehen schwierig."}],"usage":"Meist unzählbar; abstraktes Körpergefühl.","genus":"de"},"bk_1633":{"lemma":"vermoeidheid","displayNl":"de vermoeidheid","pos":"substantief","meanings":[{"de":"die Müdigkeit, die Erschöpfung","ex":"Door de vermoeidheid kon ik niet meer werken.","exDe":"Wegen der Müdigkeit konnte ich nicht mehr arbeiten."}],"usage":"Meist unzählbar; abstrakter Zustand.","genus":"de"},"bk_1634":{"lemma":"breuk","displayNl":"de breuk","pos":"substantief","meanings":[{"de":"der Bruch, die Fraktur (Knochen)","ex":"De breuk in zijn been moet in het gips.","exDe":"Der Bruch in seinem Bein muss in den Gips."},{"de":"der Bruch, der Riss, das Zerwürfnis (Beziehung)","ex":"Er ontstond een breuk tussen de twee vrienden.","exDe":"Zwischen den beiden Freunden entstand ein Bruch."},{"de":"der Bruch (Mathematik)","ex":"Een half is een breuk.","exDe":"Ein Halb ist ein Bruch."}],"usage":"Medizinisch Knochenbruch; übertragen Zerwürfnis; in der Mathematik der Bruch (Zähler/Nenner).","genus":"de","plural":"breuken"},"bk_1635":{"lemma":"kater","displayNl":"de kater","pos":"substantief","meanings":[{"de":"der Kater (Katzenjammer nach Alkohol)","ex":"Na het feest had ik een flinke kater.","exDe":"Nach der Party hatte ich einen ordentlichen Kater."},{"de":"der Kater (männliche Katze)","ex":"Onze kater slaapt de hele dag.","exDe":"Unser Kater schläft den ganzen Tag."}],"usage":"Homonym: 'Kater' als Alkoholnachwirkung UND als männliche Katze. Illustration zeigt eindeutig das Tier.","genus":"de","plural":"katers","illustratable":true},"bk_1636":{"lemma":"specialist","displayNl":"de specialist","pos":"substantief","meanings":[{"de":"der Facharzt, der (medizinische) Spezialist","ex":"De huisarts stuurt mij naar een specialist.","exDe":"Der Hausarzt schickt mich zu einem Facharzt."},{"de":"der Experte, der Fachmann (allgemein)","ex":"Hij is een specialist in oude talen.","exDe":"Er ist ein Experte für alte Sprachen."}],"usage":"Im medizinischen Kontext 'Facharzt', allgemein jede Person mit Spezialwissen.","genus":"de","plural":"specialisten","illustratable":true},"bk_1637":{"lemma":"verpleegkundige","displayNl":"de verpleegkundige","pos":"substantief","meanings":[{"de":"die Pflegekraft, der/die Krankenpfleger(in)","ex":"De verpleegkundige helpt de patiënt.","exDe":"Die Pflegekraft hilft dem Patienten."}],"usage":"Geschlechtsneutrale Berufsbezeichnung; als Substantiv dekliniert (Plural verpleegkundigen).","genus":"de","plural":"verpleegkundigen","illustratable":true},"bk_1638":{"lemma":"apotheker","displayNl":"de apotheker","pos":"substantief","meanings":[{"de":"der Apotheker, die Apothekerin","ex":"De apotheker geeft mij advies over de tabletten.","exDe":"Der Apotheker gibt mir einen Rat zu den Tabletten."}],"usage":"Person, die eine Apotheke führt und Medikamente abgibt.","genus":"de","plural":"apothekers","illustratable":true},"bk_1639":{"lemma":"kliniek","displayNl":"de kliniek","pos":"substantief","meanings":[{"de":"die Klinik","ex":"De kliniek is nieuw.","exDe":"Die Klinik ist neu."},{"de":"das Krankenhaus (spezialisiertes)","ex":"Hij werkt in een privékliniek.","exDe":"Er arbeitet in einer Privatklinik."}],"usage":"Medizinische Einrichtung, oft spezialisiert (z. B. oogkliniek, privékliniek).","genus":"de","plural":"klinieken","illustratable":true},"bk_1641":{"lemma":"zalf","displayNl":"de zalf","pos":"substantief","meanings":[{"de":"die Salbe","ex":"Smeer de zalf op de wond.","exDe":"Trage die Salbe auf die Wunde auf."},{"de":"die Creme (medizinisch/pflegend)","ex":"Deze zalf helpt tegen jeuk.","exDe":"Diese Salbe hilft gegen Juckreiz."}],"usage":"Streichfähiges Heilmittel; wird op de huid/wond aufgetragen (smeren).","genus":"de","plural":"zalven","illustratable":true},"bk_1642":{"lemma":"verband","displayNl":"het verband","pos":"substantief","meanings":[{"de":"der Verband (Wundverband)","ex":"De verpleegster legt een verband aan.","exDe":"Die Krankenschwester legt einen Verband an."},{"de":"der Zusammenhang / die Verbindung","ex":"Er is een verband tussen roken en kanker.","exDe":"Es gibt einen Zusammenhang zwischen Rauchen und Krebs."},{"de":"in verband met = im Zusammenhang mit / wegen","ex":"De weg is dicht in verband met werkzaamheden.","exDe":"Die Straße ist wegen Bauarbeiten gesperrt."}],"usage":"Konkret: Mullbinde für Wunden (een verband aanleggen). Abstrakt: Zusammenhang; feste Wendung 'in verband met'.","genus":"het","plural":"verbanden","illustratable":true},"bk_1643":{"lemma":"spuit","displayNl":"de spuit","pos":"substantief","meanings":[{"de":"die Spritze","ex":"Ik ben bang voor de spuit.","exDe":"Ich habe Angst vor der Spritze."},{"de":"das Spritzgerät / der Schlauch (zum Spritzen)","ex":"De tuinman gebruikt een spuit voor de planten.","exDe":"Der Gärtner benutzt eine Spritze für die Pflanzen."}],"usage":"Meist medizinisch (injectiespuit); auch Geräte zum Sprühen/Spritzen.","genus":"de","plural":"spuiten","illustratable":true},"bk_1644":{"lemma":"injectie","displayNl":"de injectie","pos":"substantief","meanings":[{"de":"die Injektion / die Spritze (Vorgang)","ex":"De arts geeft een injectie.","exDe":"Der Arzt gibt eine Injektion."},{"de":"die Einspritzung (technisch)","ex":"De motor werkt met directe injectie.","exDe":"Der Motor arbeitet mit Direkteinspritzung."}],"usage":"Verabreichung eines Medikaments per Nadel (een injectie geven/krijgen); technisch auch Einspritzung.","genus":"de","plural":"injecties","illustratable":true},"bk_1645":{"lemma":"vaccinatie","displayNl":"de vaccinatie","pos":"substantief","meanings":[{"de":"die Impfung","ex":"De vaccinatie is gratis.","exDe":"Die Impfung ist kostenlos."}],"usage":"Schutzimpfung gegen Krankheiten (zich laten vaccineren; een vaccinatie halen).","genus":"de","plural":"vaccinaties","illustratable":true},"bk_1646":{"lemma":"operatie","displayNl":"de operatie","pos":"substantief","meanings":[{"de":"die Operation (medizinisch)","ex":"De operatie is morgen.","exDe":"Die Operation ist morgen."},{"de":"die Operation / der Einsatz (Aktion, z. B. militärisch/polizeilich)","ex":"De politie voerde een grote operatie uit.","exDe":"Die Polizei führte eine große Operation durch."}],"usage":"Meist chirurgischer Eingriff (een operatie ondergaan); auch geplante Aktion/Einsatz.","genus":"de","plural":"operaties","illustratable":true},"bk_1647":{"lemma":"behandeling","displayNl":"de behandeling","pos":"substantief","meanings":[{"de":"die Behandlung (medizinisch/therapeutisch)","ex":"De behandeling duurt lang.","exDe":"Die Behandlung dauert lange."},{"de":"die Behandlung / der Umgang (mit Personen)","ex":"Iedere gast krijgt een vriendelijke behandeling.","exDe":"Jeder Gast bekommt eine freundliche Behandlung."},{"de":"die Bearbeitung / Erörterung (eines Themas)","ex":"De behandeling van het wetsvoorstel begint vandaag.","exDe":"Die Beratung des Gesetzentwurfs beginnt heute."}],"usage":"Abstraktes Nomen zu 'behandelen': medizinische Therapie, Umgang mit Menschen, sowie Bearbeitung/Erörterung.","genus":"de","plural":"behandelingen"},"bk_1649":{"lemma":"diagnose","displayNl":"de diagnose","pos":"substantief","meanings":[{"de":"die Diagnose","ex":"De dokter stelt een diagnose.","exDe":"Der Arzt stellt eine Diagnose."},{"de":"die Befundung, ärztliche Beurteilung","ex":"De diagnose was moeilijk te stellen.","exDe":"Die Diagnose war schwer zu stellen."}],"usage":"Medizinischer Fachbegriff; 'een diagnose stellen' = eine Diagnose stellen.","genus":"de","plural":"diagnoses"},"bk_1650":{"lemma":"thermometer","displayNl":"de thermometer","pos":"substantief","meanings":[{"de":"das Thermometer","ex":"Ik meet de koorts met een thermometer.","exDe":"Ich messe das Fieber mit einem Thermometer."},{"de":"das Thermometer (zur Lufttemperatur)","ex":"De thermometer wijst dertig graden aan.","exDe":"Das Thermometer zeigt dreißig Grad an."}],"usage":"Sowohl medizinisches Fieberthermometer als auch Wetterthermometer.","genus":"de","plural":"thermometers","illustratable":true},"bk_1651":{"lemma":"rolstoel","displayNl":"de rolstoel","pos":"substantief","meanings":[{"de":"der Rollstuhl","ex":"Opa zit in een rolstoel.","exDe":"Opa sitzt in einem Rollstuhl."}],"usage":"'in een rolstoel zitten' = im Rollstuhl sitzen.","genus":"de","plural":"rolstoelen","illustratable":true},"bk_1652":{"lemma":"kruk","displayNl":"de kruk","pos":"substantief","meanings":[{"de":"die Krücke, Gehstütze","ex":"Na de operatie loopt hij met krukken.","exDe":"Nach der Operation läuft er mit Krücken."},{"de":"der Hocker, Barhocker","ex":"Ze zit op een kruk aan de bar.","exDe":"Sie sitzt auf einem Hocker an der Bar."},{"de":"die Kurbel","ex":"Hij draait de kruk van de lier.","exDe":"Er dreht die Kurbel der Winde."}],"usage":"Der Roheintrag 'de krukken' ist der Plural; Grundform ist der Singular 'de kruk'. Homonym: Gehstütze, Hocker und Kurbel.","genus":"de","plural":"krukken","illustratable":true},"bk_1653":{"lemma":"verzekering","displayNl":"de verzekering","pos":"substantief","meanings":[{"de":"die Versicherung (Vertrag/Police)","ex":"Ik heb een goede verzekering.","exDe":"Ich habe eine gute Versicherung."},{"de":"die Versicherung, Zusicherung (Beteuerung)","ex":"Hij gaf mij de verzekering dat alles goed zou komen.","exDe":"Er gab mir die Versicherung, dass alles gut werden würde."}],"usage":"Meist im Sinne von Versicherungsvertrag (zorgverzekering, autoverzekering); seltener 'Zusicherung/Beteuerung'.","genus":"de","plural":"verzekeringen"},"bk_1654":{"lemma":"gips","displayNl":"het gips","pos":"substantief","meanings":[{"de":"der Gips (Gipsverband)","ex":"Zijn arm zit in het gips.","exDe":"Sein Arm ist im Gips."},{"de":"der Gips (Material/Baustoff)","ex":"De beeldhouwer werkt met gips.","exDe":"Der Bildhauer arbeitet mit Gips."}],"usage":"Meist Stoffbezeichnung ohne Plural; 'in het gips zitten' = im Gips sein.","genus":"het","illustratable":true},"bk_1655":{"lemma":"bloeddruk","displayNl":"de bloeddruk","pos":"substantief","meanings":[{"de":"der Blutdruck","ex":"De dokter meet mijn bloeddruk.","exDe":"Der Arzt misst meinen Blutdruck."},{"de":"der Blutdruck (hoch/niedrig, Gesundheitszustand)","ex":"Zij heeft een hoge bloeddruk.","exDe":"Sie hat einen hohen Blutdruck."}],"usage":"Meist ohne Plural; 'hoge/lage bloeddruk' = hoher/niedriger Blutdruck.","genus":"de"},"bk_1656":{"lemma":"gewond","displayNl":"gewond","pos":"adjectief","meanings":[{"de":"verletzt","ex":"De man is gewond.","exDe":"Der Mann ist verletzt."},{"de":"verwundet (im Kampf/Unfall)","ex":"Er raakten drie mensen gewond bij het ongeluk.","exDe":"Bei dem Unfall wurden drei Menschen verletzt."}],"usage":"Prädikativ und attributiv ('een gewonde soldaat'); 'gewond raken' = verletzt werden."},"bk_1657":{"lemma":"misselijk","displayNl":"misselijk","pos":"adjectief","meanings":[{"de":"übel, unwohl (Übelkeit empfindend)","ex":"Ik voel me misselijk.","exDe":"Mir ist übel."},{"de":"widerlich, gemein, ekelhaft (übertragen)","ex":"Dat was een misselijke opmerking.","exDe":"Das war eine gemeine Bemerkung."}],"usage":"Zustandsadjektiv; oft mit 'zich voelen' (sich fühlen) oder unpersönlich 'het maakt me misselijk'."},"bk_1658":{"lemma":"duizelig","displayNl":"duizelig","pos":"adjectief","meanings":[{"de":"schwindelig, benommen","ex":"Ik ben een beetje duizelig.","exDe":"Mir ist ein bisschen schwindelig."}],"usage":"Zustandsadjektiv, meist prädikativ mit 'zijn' oder 'worden' (duizelig worden = schwindelig werden)."},"bk_1659":{"lemma":"besmettelijk","displayNl":"besmettelijk","pos":"adjectief","meanings":[{"de":"ansteckend (Krankheit)","ex":"De griep is besmettelijk.","exDe":"Die Grippe ist ansteckend."},{"de":"ansteckend (übertragen, z. B. Gefühle/Lachen)","ex":"Zijn lach is besmettelijk.","exDe":"Sein Lachen ist ansteckend."}],"usage":"Adjektiv; oft prädikativ. Verwandtes Verb: besmetten (anstecken)."},"bk_1660":{"lemma":"ontspanning","displayNl":"de ontspanning","pos":"substantief","meanings":[{"de":"Entspannung, Erholung, Ausspannen","ex":"Yoga geeft mij ontspanning.","exDe":"Yoga gibt mir Entspannung."},{"de":"Entspannung, Nachlassen von Spannung (auch politisch)","ex":"Er is een periode van ontspanning tussen de twee landen.","exDe":"Es gibt eine Phase der Entspannung zwischen den beiden Ländern."}],"usage":"Meist unzählbar; Gegenteil: spanning (Spannung). Verwandtes Verb: ontspannen.","genus":"de"},"bk_1661":{"lemma":"energie","displayNl":"de energie","pos":"substantief","meanings":[{"de":"Energie, Tatkraft, Schwung","ex":"Ik heb vandaag veel energie.","exDe":"Ich habe heute viel Energie."},{"de":"Energie (Strom, Kraft; Physik/Versorgung)","ex":"Zonnepanelen leveren schone energie.","exDe":"Solarmodule liefern saubere Energie."}],"usage":"Meist unzählbar; Plural 'energieën' selten und fachsprachlich.","genus":"de","plural":"energieën"},"bk_1662":{"lemma":"gewicht","displayNl":"het gewicht","pos":"substantief","meanings":[{"de":"Gewicht (eines Körpers/Objekts), Körpergewicht","ex":"Ik let op mijn gewicht.","exDe":"Ich achte auf mein Gewicht."},{"de":"Gewicht (schwerer Gegenstand, z. B. Hantel oder Waagengewicht)","ex":"Hij tilt zware gewichten in de sportschool.","exDe":"Er hebt schwere Gewichte im Fitnessstudio."},{"de":"Gewicht, Bedeutung, Wichtigkeit (übertragen)","ex":"Zijn mening heeft veel gewicht.","exDe":"Seine Meinung hat viel Gewicht."}],"usage":"Neutrum; für schwere Objekte zählbar (gewichten), für das Maß meist unzählbar.","genus":"het","plural":"gewichten","illustratable":true},"bk_1664":{"lemma":"voeding","displayNl":"de voeding","pos":"substantief","meanings":[{"de":"Ernährung, Nahrung, Kost","ex":"Gezonde voeding is belangrijk.","exDe":"Gesunde Ernährung ist wichtig."},{"de":"Nahrung, Fütterung (z. B. eines Babys)","ex":"De baby krijgt om de drie uur een voeding.","exDe":"Das Baby bekommt alle drei Stunden eine Mahlzeit."},{"de":"Stromversorgung, Speisung (Technik)","ex":"De voeding van de computer is kapot.","exDe":"Das Netzteil des Computers ist kaputt."}],"usage":"Meist unzählbar in der Bedeutung Ernährung; zählbar bei Baby-Mahlzeit oder Netzteil. Verwandtes Verb: voeden.","genus":"de","plural":"voedingen","illustratable":true},"bk_1665":{"lemma":"genezen","displayNl":"genezen","pos":"werkwoord","meanings":[{"de":"heilen, wieder gesund werden (intransitiv, von Wunde/Person)","ex":"De wond geneest langzaam.","exDe":"Die Wunde heilt langsam."},{"de":"heilen, kurieren (transitiv, jemanden gesund machen)","ex":"De dokter heeft hem van zijn ziekte genezen.","exDe":"Der Arzt hat ihn von seiner Krankheit geheilt."}],"usage":"Starkes Verb (genezen – genas – genezen). Intransitiv (gesund werden) mit 'zijn'; transitiv (jemanden heilen) mit 'hebben'.","conjugation":{"presens":{"ik":"genees","jij":"geneest","hij":"geneest","wij":"genezen"},"imperfectum":{"ik":"genas","wij":"genazen"},"perfectum":{"aux":"zijn","participle":"genezen"}}},"bk_1666":{"lemma":"overgeven","displayNl":"overgeven","pos":"werkwoord","meanings":[{"de":"sich übergeben, erbrechen","ex":"Hij moest overgeven.","exDe":"Er musste sich übergeben."},{"de":"übergeben, aushändigen","ex":"Zij gaf het pakketje over aan de buurman.","exDe":"Sie übergab das Päckchen dem Nachbarn."},{"de":"sich ergeben, kapitulieren","ex":"Het leger moest zich overgeven.","exDe":"Die Armee musste sich ergeben."}],"usage":"Trennbares Verb (geven over), starkes Grundverb geven. Reflexiv 'zich overgeven' = sich ergeben.","conjugation":{"presens":{"ik":"geef over","jij":"geeft over","hij":"geeft over","wij":"geven over"},"imperfectum":{"ik":"gaf over","wij":"gaven over"},"perfectum":{"aux":"hebben","participle":"overgegeven"}}},"bk_1667":{"lemma":"onderzoeken","displayNl":"onderzoeken","pos":"werkwoord","meanings":[{"de":"untersuchen (medizinisch)","ex":"De dokter onderzoekt mijn keel.","exDe":"Der Arzt untersucht meinen Hals."},{"de":"erforschen, prüfen","ex":"De wetenschappers onderzoeken het virus.","exDe":"Die Wissenschaftler erforschen das Virus."},{"de":"ermitteln, nachforschen","ex":"De politie onderzoekt de zaak.","exDe":"Die Polizei ermittelt in dem Fall."}],"usage":"Untrennbar (Betonung auf zoeken), Partizip ohne ge-: onderzocht.","conjugation":{"presens":{"ik":"onderzoek","jij":"onderzoekt","hij":"onderzoekt","wij":"onderzoeken"},"imperfectum":{"ik":"onderzocht","wij":"onderzochten"},"perfectum":{"aux":"hebben","participle":"onderzocht"}},"illustratable":true},"bk_1668":{"lemma":"bewegen","displayNl":"bewegen","pos":"werkwoord","meanings":[{"de":"sich bewegen, in Bewegung sein","ex":"Je moet elke dag bewegen.","exDe":"Du musst dich jeden Tag bewegen."},{"de":"bewegen, verschieben","ex":"Kun je die stoel even bewegen?","exDe":"Kannst du den Stuhl kurz bewegen?"},{"de":"innerlich bewegen, rühren","ex":"Haar verhaal bewoog iedereen.","exDe":"Ihre Geschichte rührte alle."}],"usage":"Starkes Verb (bewoog, bewogen). Bei Ortsveränderung mit 'zijn' möglich.","conjugation":{"presens":{"ik":"beweeg","jij":"beweegt","hij":"beweegt","wij":"bewegen"},"imperfectum":{"ik":"bewoog","wij":"bewogen"},"perfectum":{"aux":"hebben","participle":"bewogen"}}},"bk_1669":{"lemma":"deodorant","displayNl":"de deodorant","pos":"substantief","meanings":[{"de":"das Deo, Deodorant","ex":"Ik gebruik elke dag deodorant.","exDe":"Ich benutze jeden Tag Deo."}],"usage":"de-Wort; Kurzform 'deo' umgangssprachlich.","genus":"de","plural":"deodorants","illustratable":true},"bk_1670":{"lemma":"wasbak","displayNl":"de wasbak","pos":"substantief","meanings":[{"de":"das Waschbecken","ex":"Ik was mijn handen bij de wasbak.","exDe":"Ich wasche meine Hände am Waschbecken."}],"usage":"de-Wort; Synonym 'wastafel'.","genus":"de","plural":"wasbakken","illustratable":true},"bk_1671":{"lemma":"hygiëne","displayNl":"de hygiëne","pos":"substantief","meanings":[{"de":"die Hygiene, Sauberkeit","ex":"Goede hygiëne voorkomt ziektes.","exDe":"Gute Hygiene verhindert Krankheiten."}],"usage":"de-Wort, meist ohne Plural (nicht zählbar). Trema auf ë.","genus":"de"},"bk_1672":{"lemma":"scheren","displayNl":"scheren","pos":"werkwoord","meanings":[{"de":"rasieren, sich rasieren","ex":"Hij scheert zich elke dag.","exDe":"Er rasiert sich jeden Tag."},{"de":"scheren (Schafe), abschneiden","ex":"De boer scheert de schapen in het voorjaar.","exDe":"Der Bauer schert die Schafe im Frühjahr."},{"de":"dicht entlangstreichen, dahingleiten","ex":"De meeuwen scheren over het water.","exDe":"Die Möwen streichen dicht über das Wasser."}],"usage":"Starkes Verb (schoor, geschoren). Reflexiv 'zich scheren' = sich rasieren.","conjugation":{"presens":{"ik":"scheer","jij":"scheert","hij":"scheert","wij":"scheren"},"imperfectum":{"ik":"schoor","wij":"schoren"},"perfectum":{"aux":"hebben","participle":"geschoren"}},"illustratable":true},"bk_1673":{"lemma":"afdrogen","displayNl":"afdrogen","pos":"werkwoord","meanings":[{"de":"abtrocknen, sich abtrocknen","ex":"Ik droog me af met een handdoek.","exDe":"Ich trockne mich mit einem Handtuch ab."},{"de":"abtrocknen (Geschirr)","ex":"Wil jij de borden afdrogen?","exDe":"Willst du die Teller abtrocknen?"}],"usage":"Trennbares Verb (drogen af), schwach. Reflexiv 'zich afdrogen'.","conjugation":{"presens":{"ik":"droog af","jij":"droogt af","hij":"droogt af","wij":"drogen af"},"imperfectum":{"ik":"droogde af","wij":"droogden af"},"perfectum":{"aux":"hebben","participle":"afgedroogd"}},"illustratable":true},"bk_1674":{"lemma":"wenkbrauw","displayNl":"de wenkbrauw","pos":"substantief","meanings":[{"de":"die Augenbraue","ex":"Zij heeft dunne wenkbrauwen.","exDe":"Sie hat dünne Augenbrauen."},{"de":"die Augenbraue (als Ausdrucksmittel: eine Augenbraue hochziehen)","ex":"Hij trok verbaasd een wenkbrauw op.","exDe":"Er zog überrascht eine Augenbraue hoch."}],"usage":"Körperteil; Standardwort für die Augenbraue. Plural wenkbrauwen sehr gebräuchlich.","genus":"de","plural":"wenkbrauwen","illustratable":true},"bk_1675":{"lemma":"wimper","displayNl":"de wimper","pos":"substantief","meanings":[{"de":"die Wimper","ex":"Er zit een wimper in mijn oog.","exDe":"Es ist eine Wimper in meinem Auge."},{"de":"die Wimper (Redewendung: zonder met de ogen te knipperen / ohne mit der Wimper zu zucken)","ex":"Ze loog zonder met haar ogen te knipperen.","exDe":"Sie log, ohne mit der Wimper zu zucken."}],"usage":"Körperteil; einzelne Wimper. Plural wimpers gebräuchlich (Mascara enz.).","genus":"de","plural":"wimpers","illustratable":true},"bk_1676":{"lemma":"prikken","displayNl":"prikken","pos":"werkwoord","meanings":[{"de":"stechen, piksen (mit einer Nadel oder einem spitzen Gegenstand)","ex":"Ik prik mijn vinger aan een naald.","exDe":"Ich steche mir mit einer Nadel in den Finger."},{"de":"aufspießen, aufpicken","ex":"Ze prikt een stukje kaas met een prikker.","exDe":"Sie spießt ein Stückchen Käse mit einem Spießchen auf."},{"de":"prickeln, kribbeln (auf der Haut/Zunge)","ex":"De koolzuur prikt op mijn tong.","exDe":"Die Kohlensäure prickelt auf meiner Zunge."}],"usage":"Rohform \"de vinger prikken\" auf Infinitiv prikken reduziert. Regelmäßiges Verb, Hilfsverb hebben.","conjugation":{"presens":{"ik":"prik","jij":"prikt","hij":"prikt","wij":"prikken"},"imperfectum":{"ik":"prikte","wij":"prikten"},"perfectum":{"aux":"hebben","participle":"geprikt"}},"illustratable":true},"bk_1677":{"lemma":"patiëntenkaart","displayNl":"de patiëntenkaart","pos":"substantief","meanings":[{"de":"die Versichertenkarte, die Patientenkarte","ex":"Neem je patiëntenkaart mee.","exDe":"Nimm deine Versichertenkarte mit."}],"usage":"Zusammengesetztes Substantiv (patiënt + kaart), genus de. Bei Arztbesuch vorzuzeigende Karte.","genus":"de","plural":"patiëntenkaarten","illustratable":true},"bk_1678":{"lemma":"spreekkamer","displayNl":"de spreekkamer","pos":"substantief","meanings":[{"de":"das Sprechzimmer, das Behandlungszimmer","ex":"De dokter wacht in de spreekkamer.","exDe":"Der Arzt wartet im Sprechzimmer."}],"usage":"Zusammengesetztes Substantiv (spreken + kamer), genus de. Raum, in dem der Arzt Patienten empfängt.","genus":"de","plural":"spreekkamers","illustratable":true},"bk_1679":{"lemma":"spoedeisende hulp","displayNl":"de spoedeisende hulp","pos":"substantief","meanings":[{"de":"die Notaufnahme (Abk. SEH)","ex":"We gaan naar de spoedeisende hulp.","exDe":"Wir gehen in die Notaufnahme."},{"de":"die Notfallversorgung, die dringende Hilfe","ex":"Bij een ongeluk is spoedeisende hulp nodig.","exDe":"Bei einem Unfall ist dringende Hilfe nötig."}],"usage":"Feste Fügung (Adjektiv spoedeisend + hulp), funktioniert als Substantiv, genus de; oft abgekürzt SEH. Kein gebräuchlicher Plural.","genus":"de","illustratable":true},"bk_1680":{"lemma":"bloedonderzoek","displayNl":"het bloedonderzoek","pos":"substantief","meanings":[{"de":"die Blutuntersuchung, der Bluttest","ex":"Morgen heb ik een bloedonderzoek.","exDe":"Morgen habe ich eine Blutuntersuchung."}],"usage":"Zusammengesetztes Substantiv (bloed + onderzoek), genus het. Laboruntersuchung des Blutes.","genus":"het","plural":"bloedonderzoeken","illustratable":true},"bk_1681":{"lemma":"trekken","displayNl":"trekken","pos":"werkwoord","meanings":[{"de":"ziehen (herausziehen, z. B. einen Zahn)","ex":"De tandarts moet de tand trekken.","exDe":"Der Zahnarzt muss den Zahn ziehen."},{"de":"ziehen, zerren (an etwas)","ex":"Trek hard aan het touw.","exDe":"Zieh fest an dem Seil."},{"de":"(los)ziehen, umherziehen, wandern","ex":"We trekken door de bergen.","exDe":"Wir ziehen durch die Berge."},{"de":"ziehen (Tee), durchziehen lassen","ex":"Laat de thee even trekken.","exDe":"Lass den Tee kurz ziehen."}],"usage":"Rohform \"de tand trekken\" auf Infinitiv trekken reduziert. Starkes Verb: trekken - trok - getrokken; Hilfsverb hebben (bei Ortswechsel/Reisen auch zijn).","conjugation":{"presens":{"ik":"trek","jij":"trekt","hij":"trekt","wij":"trekken"},"imperfectum":{"ik":"trok","wij":"trokken"},"perfectum":{"aux":"hebben","participle":"getrokken"}},"illustratable":true},"bk_1814":{"lemma":"bewegwijzering","displayNl":"de bewegwijzering","pos":"substantief","meanings":[{"de":"die Beschilderung, die Wegweisung (Gesamtheit der Wegweiser/Hinweißchilder)","ex":"De bewegwijzering op de snelweg is heel duidelijk.","exDe":"Die Beschilderung auf der Autobahn ist sehr deutlich."},{"de":"das Wegleitsystem, die Ausschilderung (in Gebäuden/auf Gelände)","ex":"Dankzij de bewegwijzering vond ik snel de uitgang.","exDe":"Dank der Ausschilderung fand ich schnell den Ausgang."}],"usage":"Sammelbegriff für die gesamte Schilder-/Wegweisung; oft im Singular für das ganze System.","genus":"de","plural":"bewegwijzeringen","illustratable":true},"bk_1815":{"lemma":"wegwerkzaamheden","displayNl":"de wegwerkzaamheden","pos":"substantief","meanings":[{"de":"die Bauarbeiten, die Straßenarbeiten (an einer Straße)","ex":"Door de wegwerkzaamheden staat er een lange file.","exDe":"Wegen der Bauarbeiten gibt es einen langen Stau."},{"de":"die Straßenbaustelle (als Ereignis/Zustand im Verkehr)","ex":"Er zijn wegwerkzaamheden tot volgende maand.","exDe":"Es gibt Straßenarbeiten bis nächsten Monat."}],"usage":"Plurale tantum, nur im Plural gebräuchlich; steht für Straßenbauarbeiten.","genus":"de","plural":"wegwerkzaamheden","illustratable":true},"bk_1816":{"lemma":"verkeersdrempel","displayNl":"de verkeersdrempel","pos":"substantief","meanings":[{"de":"die Bodenschwelle, der Bremsschwelle, die Verkehrsberuhigungsschwelle","ex":"Rij langzaam over de verkeersdrempel.","exDe":"Fahr langsam über die Bodenschwelle."}],"usage":"Konkrete bauliche Erhöhung auf der Fahrbahn zum Tempolimit.","genus":"de","plural":"verkeersdrempels","illustratable":true},"bk_1817":{"lemma":"vluchtstrook","displayNl":"de vluchtstrook","pos":"substantief","meanings":[{"de":"der Standstreifen, die Standspur (auf der Autobahn)","ex":"Stop alleen op de vluchtstrook bij pech.","exDe":"Halte nur bei einer Panne auf dem Standstreifen."}],"usage":"Der äußere Streifen der Autobahn, nur für Notfälle.","genus":"de","plural":"vluchtstroken","illustratable":true},"bk_1818":{"lemma":"afrit","displayNl":"de afrit","pos":"substantief","meanings":[{"de":"die Ausfahrt, die Abfahrt (von der Autobahn)","ex":"Neem de volgende afrit richting het centrum.","exDe":"Nimm die nächste Ausfahrt in Richtung Zentrum."}],"usage":"Ausfahrtsstraße, die von der Autobahn wegführt (Gegenstück zu oprit).","genus":"de","plural":"afritten","illustratable":true},"bk_1819":{"lemma":"oprit","displayNl":"de oprit","pos":"substantief","meanings":[{"de":"die Auffahrt (auf die Autobahn), die Einfahrt","ex":"De oprit naar de snelweg is hier dichtbij.","exDe":"Die Auffahrt zur Autobahn ist hier in der Nähe."},{"de":"die Einfahrt, die Zufahrt (zu einem Haus oder Grundstück)","ex":"De auto staat op de oprit voor het huis.","exDe":"Das Auto steht in der Einfahrt vor dem Haus."}],"usage":"Zwei Bedeutungen: Autobahnauffahrt und private Hauseinfahrt.","genus":"de","plural":"opritten","illustratable":true},"bk_1820":{"lemma":"viaduct","displayNl":"het viaduct","pos":"substantief","meanings":[{"de":"die Überführung, das Viadukt, die Brücke (über Straße oder Tal)","ex":"De trein rijdt over het viaduct.","exDe":"Der Zug fährt über die Überführung."}],"usage":"Standard-Genus ist het viaduct (regional auch de); Straßen-/Bahnüberführung.","genus":"het","plural":"viaducten","illustratable":true},"bk_1821":{"lemma":"bestrating","displayNl":"de bestrating","pos":"substantief","meanings":[{"de":"das Pflaster, der Straßenbelag (die gepflasterte Fläche)","ex":"De oude bestrating van de straat is heel mooi.","exDe":"Das alte Pflaster der Straße ist sehr schön."},{"de":"die Pflasterung (das Pflastern als Belag/Arbeit)","ex":"De bestrating van het plein wordt vernieuwd.","exDe":"Die Pflasterung des Platzes wird erneuert."}],"usage":"Bezeichnet den gepflasterten Belag; Sammelbegriff für die Pflasterung einer Fläche.","genus":"de","plural":"bestratingen","illustratable":true},"bk_1822":{"lemma":"lantaarnpaal","displayNl":"de lantaarnpaal","pos":"substantief","meanings":[{"de":"der Laternenpfahl, der Straßenlaternenmast","ex":"De lantaarnpaal geeft weinig licht.","exDe":"Der Laternenpfahl gibt wenig Licht."},{"de":"die Straßenlaterne (als Lichtquelle)","ex":"Hij leunde tegen de lantaarnpaal.","exDe":"Er lehnte sich gegen die Straßenlaterne."}],"usage":"Alltäglich; -paal betont den Mast, das ganze Objekt heißt oft auch 'straatlantaarn'.","genus":"de","plural":"lantaarnpalen","illustratable":true},"bk_1823":{"lemma":"straatverlichting","displayNl":"de straatverlichting","pos":"substantief","meanings":[{"de":"die Straßenbeleuchtung (Anlage/Beleuchtung einer Straße)","ex":"De straatverlichting gaat 's avonds aan.","exDe":"Die Straßenbeleuchtung geht abends an."},{"de":"das Straßenlicht (das von den Lampen erzeugte Licht)","ex":"Bij het uitvallen van de straatverlichting werd het aardedonker.","exDe":"Beim Ausfall der Straßenbeleuchtung wurde es stockdunkel."}],"usage":"Meist unzählbar; Sammelbegriff für die gesamte Beleuchtungsanlage einer Straße.","genus":"de","illustratable":true},"bk_1824":{"lemma":"voetganger","displayNl":"de voetganger","pos":"substantief","meanings":[{"de":"der Fußgänger, die Fußgängerin","ex":"De voetganger heeft hier voorrang.","exDe":"Der Fußgänger hat hier Vorfahrt."}],"usage":"Verkehrsteilnehmer zu Fuß; oft in 'voetgangersoversteekplaats' (Fußgängerüberweg).","genus":"de","plural":"voetgangers","illustratable":true},"bk_1826":{"lemma":"rijbewijs","displayNl":"het rijbewijs","pos":"substantief","meanings":[{"de":"der Führerschein (Dokument)","ex":"Zonder rijbewijs mag je niet rijden.","exDe":"Ohne Führerschein darfst du nicht fahren."},{"de":"die Fahrerlaubnis (Berechtigung zu fahren)","ex":"Ze haalde vorige week haar rijbewijs.","exDe":"Sie machte letzte Woche ihren Führerschein."}],"usage":"KORREKTUR: het rijbewijs (nicht 'de'). Diminutiv unüblich; Plural rijbewijzen.","genus":"het","plural":"rijbewijzen","illustratable":true},"bk_1827":{"lemma":"bestuurder","displayNl":"de bestuurder","pos":"substantief","meanings":[{"de":"der Fahrer, der Fahrzeugführer (einer eines Fahrzeugs)","ex":"De bestuurder let goed op.","exDe":"Der Fahrer passt gut auf."},{"de":"das Vorstandsmitglied, der Geschäftsführer, der Verwalter (einer Organisation)","ex":"De bestuurders van de stichting vergaderen vandaag.","exDe":"Die Vorstandsmitglieder der Stiftung tagen heute."},{"de":"der Machthaber, der Regierende (eines Landes/einer Stadt)","ex":"De lokale bestuurders namen een besluit.","exDe":"Die lokalen Verwaltungsleiter fassten einen Beschluss."}],"usage":"Zwei Hauptbedeutungen: Fahrzeugführer vs. Führungskraft/Vorstand. Kontext entscheidet.","genus":"de","plural":"bestuurders","illustratable":true},"bk_1828":{"lemma":"inrit","displayNl":"de inrit","pos":"substantief","meanings":[{"de":"die Einfahrt, die Zufahrt (zu einem Grundstück/Parkplatz)","ex":"Parkeer niet voor de inrit.","exDe":"Parke nicht vor der Einfahrt."},{"de":"die Auffahrt (Weg vom Tor zum Haus)","ex":"De auto stond op de inrit.","exDe":"Das Auto stand auf der Auffahrt."}],"usage":"Gegenstück: 'uitrit' (Ausfahrt). Oft auf Schildern 'inrit vrijhouden'.","genus":"de","plural":"inritten","illustratable":true},"bk_1829":{"lemma":"wandeling","displayNl":"de wandeling","pos":"substantief","meanings":[{"de":"der Spaziergang, die Wanderung","ex":"We maken een wandeling door de stad.","exDe":"Wir machen einen Spaziergang durch die Stadt."},{"de":"der Rundgang, die Tour (zu Fuß)","ex":"De gids leidde ons op een wandeling langs de grachten.","exDe":"Der Führer leitete uns auf einem Rundgang entlang der Grachten."}],"usage":"'een wandeling maken' = spazieren gehen. Verb dazu: wandelen.","genus":"de","plural":"wandelingen","illustratable":true},"bk_1830":{"lemma":"plattegrond","displayNl":"de plattegrond","pos":"substantief","meanings":[{"de":"der Stadtplan, die Karte (Übersichtskarte)","ex":"Ik zoek de weg op de plattegrond.","exDe":"Ich suche den Weg auf dem Stadtplan."},{"de":"der Grundriss (eines Gebäudes/einer Wohnung, von oben)","ex":"Op de plattegrond zie je waar de keuken ligt.","exDe":"Auf dem Grundriss sieht man, wo die Küche liegt."}],"usage":"Wörtlich 'flacher Grund' = Draufsicht. Stadtplan vs. Gebäudegrundriss je nach Kontext.","genus":"de","plural":"plattegronden","illustratable":true},"bk_1831":{"lemma":"wegwijzer","displayNl":"de wegwijzer","pos":"substantief","meanings":[{"de":"der Wegweiser (Schild)","ex":"De wegwijzer wijst naar het centrum.","exDe":"Der Wegweiser zeigt zum Zentrum."},{"de":"der Ratgeber, die Orientierungshilfe (übertragen)","ex":"Dit boek is een handige wegwijzer voor beginners.","exDe":"Dieses Buch ist ein praktischer Ratgeber für Anfänger."}],"usage":"Konkretes Schild oder übertragen eine Orientierungshilfe/ein Ratgeber.","genus":"de","plural":"wegwijzers","illustratable":true},"bk_1832":{"lemma":"begane grond","displayNl":"de begane grond","pos":"substantief","meanings":[{"de":"das Erdgeschoss","ex":"De winkel is op de begane grond.","exDe":"Das Geschäft ist im Erdgeschoss."}],"usage":"Feststehende Fügung für die ebenerdige Etage; meist ohne Plural.","genus":"de"},"bk_1833":{"lemma":"verdieping","displayNl":"de verdieping","pos":"substantief","meanings":[{"de":"das Stockwerk, die Etage","ex":"Ons kantoor is op de derde verdieping.","exDe":"Unser Büro ist im dritten Stockwerk."},{"de":"die Vertiefung, das Vertiefen (übertragen, z. B. von Wissen oder Gefühl)","ex":"De cursus biedt verdieping van je kennis.","exDe":"Der Kurs bietet eine Vertiefung deines Wissens."}],"usage":"Konkret die Etage eines Gebäudes oder übertragen die inhaltliche Vertiefung.","genus":"de","plural":"verdiepingen"},"bk_1834":{"lemma":"wolkenkrabber","displayNl":"de wolkenkrabber","pos":"substantief","meanings":[{"de":"der Wolkenkratzer","ex":"In het centrum staat een wolkenkrabber.","exDe":"Im Zentrum steht ein Wolkenkratzer."}],"usage":"Sehr hohes Hochhaus in einer Großstadt.","genus":"de","plural":"wolkenkrabbers","illustratable":true},"bk_1835":{"lemma":"rondweg","displayNl":"de rondweg","pos":"substantief","meanings":[{"de":"die Umgehungsstraße, der Ring","ex":"De rondweg gaat om de stad heen.","exDe":"Die Umgehungsstraße führt um die Stadt."}],"usage":"Straße, die um einen Ort herumführt statt hindurch.","genus":"de","plural":"rondwegen","illustratable":true},"bk_1836":{"lemma":"invalshoek","displayNl":"de invalshoek","pos":"substantief","meanings":[{"de":"der Blickwinkel, die Perspektive, der Ansatz (übertragen)","ex":"Vanuit een andere invalshoek zie je het probleem beter.","exDe":"Aus einem anderen Blickwinkel siehst du das Problem besser."},{"de":"der Einfallswinkel (Physik)","ex":"De invalshoek van het licht bepaalt de schaduw.","exDe":"Der Einfallswinkel des Lichts bestimmt den Schatten."}],"usage":"Übertragen ein Blickwinkel oder Ansatz, fachsprachlich der physikalische Einfallswinkel. Fuer die Zufahrtsstraße einer Stadt ist 'invalsweg' gebräuchlicher.","genus":"de","plural":"invalshoeken"},"bk_1837":{"lemma":"spitsuur","displayNl":"het spitsuur","pos":"substantief","meanings":[{"de":"die Stoßzeit, der Berufsverkehr, die Rushhour","ex":"Vermijd het spitsuur als het kan.","exDe":"Vermeide die Stoßzeit, wenn es geht."}],"usage":"Het-Wort (het spitsuur); die Zeit mit dem dichtesten Verkehr, morgens und abends.","genus":"het","plural":"spitsuren","illustratable":true},"bk_1838":{"lemma":"tolweg","displayNl":"de tolweg","pos":"substantief","meanings":[{"de":"die Mautstraße, der gebührenpflichtige Weg","ex":"De tolweg kost extra geld.","exDe":"Die Mautstraße kostet extra Geld."}],"usage":"Straße, für deren Benutzung man eine Gebühr (Maut) zahlen muss.","genus":"de","plural":"tolwegen","illustratable":true},"bk_1839":{"lemma":"knooppunt","displayNl":"het knooppunt","pos":"substantief","meanings":[{"de":"das Autobahnkreuz, der Verkehrsknotenpunkt","ex":"Bij het knooppunt ga je naar het zuiden.","exDe":"Am Autobahnkreuz fährst du nach Süden."},{"de":"der Knotenpunkt (allgemein), zentraler Verbindungspunkt","ex":"Utrecht is een belangrijk knooppunt in het spoornet.","exDe":"Utrecht ist ein wichtiger Knotenpunkt im Schienennetz."},{"de":"der (nummerierte) Fahrrad-Knotenpunkt (NL-Radwegenetz)","ex":"We fietsen van knooppunt 12 naar knooppunt 15.","exDe":"Wir radeln von Knotenpunkt 12 zu Knotenpunkt 15."}],"usage":"Neutrum (het). Im NL-Radwegenetz sind knooppunten nummerierte Wegpunkte zur Routenplanung.","genus":"het","plural":"knooppunten","notes":"Roh-Eintrag 'de knooppunt' war falsch: korrektes Genus ist 'het'.","illustratable":true},"bk_1840":{"lemma":"verkeersopstopping","displayNl":"de verkeersopstopping","pos":"substantief","meanings":[{"de":"der Verkehrsstau, die Verkehrsstockung","ex":"Er is een verkeersopstopping in het centrum.","exDe":"Es gibt einen Verkehrsstau im Zentrum."}],"usage":"Utrum (de). Synonym zum kürzeren 'de file', das im Alltag häufiger ist.","genus":"de","plural":"verkeersopstoppingen","illustratable":true},"bk_1841":{"lemma":"bezienswaardigheid","displayNl":"de bezienswaardigheid","pos":"substantief","meanings":[{"de":"die Sehenswürdigkeit","ex":"De stad heeft veel bezienswaardigheden.","exDe":"Die Stadt hat viele Sehenswürdigkeiten."}],"usage":"Utrum (de). Nomina auf -heid sind immer 'de'; Plural auf -heden.","genus":"de","plural":"bezienswaardigheden","illustratable":true},"bk_1842":{"lemma":"voorstad","displayNl":"de voorstad","pos":"substantief","meanings":[{"de":"der Vorort, die Vorstadt","ex":"Zij wonen in een rustige voorstad.","exDe":"Sie wohnen in einem ruhigen Vorort."}],"usage":"Utrum (de). Plural mit Umlautung des Stammvokals wie bei 'stad → steden': voorsteden.","genus":"de","plural":"voorsteden","illustratable":true},"bk_1843":{"lemma":"bebouwde kom","displayNl":"de bebouwde kom","pos":"substantief","meanings":[{"de":"die geschlossene Ortschaft, das bebaute (Innerorts-)Gebiet","ex":"In de bebouwde kom rij je langzamer.","exDe":"In der geschlossenen Ortschaft fährst du langsamer."}],"usage":"Feste Nominalphrase; Utrum (de kom). Verkehrsrechtlicher Begriff für das Ortsinnere; meist nur im Singular gebräuchlich.","genus":"de","illustratable":true},"bk_1844":{"lemma":"verkeersader","displayNl":"de verkeersader","pos":"substantief","meanings":[{"de":"die Verkehrsader, die Hauptverkehrsstraße","ex":"Deze straat is een belangrijke verkeersader.","exDe":"Diese Straße ist eine wichtige Verkehrsader."}],"usage":"Utrum (de). Bildlicher Begriff (ader = Ader) für eine tragende Hauptverkehrsstraße; Plural verkeersaders (auch: verkeersaderen).","genus":"de","plural":"verkeersaders","illustratable":true},"bk_1845":{"lemma":"laadpaal","displayNl":"de laadpaal","pos":"substantief","meanings":[{"de":"die Ladesäule, die Ladestation (für E-Autos)","ex":"De auto staat bij de laadpaal.","exDe":"Das Auto steht an der Ladesäule."}],"usage":"Utrum (de). Plural laadpalen. In den Niederlanden sehr verbreitet im Straßenbild.","genus":"de","plural":"laadpalen","illustratable":true},"bk_1846":{"lemma":"fietsenstalling","displayNl":"de fietsenstalling","pos":"substantief","meanings":[{"de":"der Fahrradabstellplatz, das Fahrradparkhaus, der Fahrradunterstand","ex":"Ik zet mijn fiets in de fietsenstalling.","exDe":"Ich stelle mein Fahrrad im Fahrradabstellplatz ab."}],"usage":"Utrum (de); Nomina auf -ing sind 'de'. Plural fietsenstallingen. Typisch niederländisch, oft riesige überdachte Anlagen an Bahnhöfen.","genus":"de","plural":"fietsenstallingen","illustratable":true},"bk_1847":{"lemma":"wegversmalling","displayNl":"de wegversmalling","pos":"substantief","meanings":[{"de":"die Fahrbahnverengung","ex":"Let op de wegversmalling verderop.","exDe":"Achte auf die Fahrbahnverengung weiter vorne."},{"de":"die Verengung der Straße (Engstelle)","ex":"Bij de wegversmalling moet je voorrang verlenen.","exDe":"An der Engstelle musst du Vorfahrt gewähren."}],"usage":"Verkehrssprache/Beschilderung; oft mit Verkehrszeichen und Vorrangregelung verbunden.","genus":"de","plural":"wegversmallingen","illustratable":true},"bk_1848":{"lemma":"doodlopende weg","displayNl":"de doodlopende weg","pos":"substantief","meanings":[{"de":"die Sackgasse (Straße ohne Durchfahrt)","ex":"Dit is een doodlopende weg.","exDe":"Das ist eine Sackgasse."},{"de":"die Sackgasse (übertragen: aussichtslose Situation)","ex":"Deze onderhandelingen zijn een doodlopende weg.","exDe":"Diese Verhandlungen sind eine Sackgasse."}],"usage":"Feste Wortverbindung (Adjektiv 'doodlopend' + 'weg'); wörtlich Verkehrsschild, oft auch bildlich.","genus":"de","plural":"doodlopende wegen","illustratable":true},"bk_1849":{"lemma":"eenrichtingsweg","displayNl":"de eenrichtingsweg","pos":"substantief","meanings":[{"de":"die Einbahnstraße","ex":"Je mag hier niet in, het is een eenrichtingsweg.","exDe":"Du darfst hier nicht rein, es ist eine Einbahnstraße."},{"de":"die Einbahnstraße (übertragen: einseitiger Vorgang)","ex":"Communicatie mag geen eenrichtingsweg zijn.","exDe":"Kommunikation darf keine Einbahnstraße sein."}],"usage":"Verkehr; auch bildlich für einseitige Beziehungen. Synonym: eenrichtingsverkeer.","genus":"de","plural":"eenrichtingswegen","illustratable":true},"bk_1850":{"lemma":"sollicitatiebrief","displayNl":"de sollicitatiebrief","pos":"substantief","meanings":[{"de":"das Bewerbungsschreiben, der Bewerbungsbrief","ex":"Ik schrijf een sollicitatiebrief.","exDe":"Ich schreibe ein Bewerbungsschreiben."},{"de":"das Anschreiben (bei einer Bewerbung)","ex":"Voeg je cv bij de sollicitatiebrief.","exDe":"Füge deinen Lebenslauf dem Anschreiben bei."}],"usage":"Bewerbungskontext; wird zusammen mit dem cv (Lebenslauf) verschickt.","genus":"de","plural":"sollicitatiebrieven","illustratable":true},"bk_1851":{"lemma":"vacature","displayNl":"de vacature","pos":"substantief","meanings":[{"de":"die Stellenausschreibung, die offene Stelle","ex":"Er is een nieuwe vacature.","exDe":"Es gibt eine neue Stellenausschreibung."},{"de":"die freie Stelle (Vakanz)","ex":"De vacature is inmiddels vervuld.","exDe":"Die freie Stelle ist inzwischen besetzt."}],"usage":"Arbeitsmarkt; 'een vacature vervullen/openstellen'.","genus":"de","plural":"vacatures"},"bk_1852":{"lemma":"proeftijd","displayNl":"de proeftijd","pos":"substantief","meanings":[{"de":"die Probezeit (im Arbeitsvertrag)","ex":"De proeftijd duurt twee maanden.","exDe":"Die Probezeit dauert zwei Monate."},{"de":"die Bewährungszeit (allgemein: Erprobungsphase)","ex":"Na de proeftijd kreeg hij een vast contract.","exDe":"Nach der Probezeit bekam er einen festen Vertrag."}],"usage":"Arbeitsrecht; abstrakter Zeitraum, nicht bildlich.","genus":"de","plural":"proeftijden"},"bk_1853":{"lemma":"arbeidscontract","displayNl":"het arbeidscontract","pos":"substantief","meanings":[{"de":"der Arbeitsvertrag","ex":"Lees het arbeidscontract goed.","exDe":"Lies den Arbeitsvertrag genau."},{"de":"der Anstellungsvertrag","ex":"Ik heb een arbeidscontract voor bepaalde tijd.","exDe":"Ich habe einen befristeten Anstellungsvertrag."}],"usage":"Arbeitsrecht; Synonym arbeidsovereenkomst. het-Wort.","genus":"het","plural":"arbeidscontracten","illustratable":true},"bk_1854":{"lemma":"opzegtermijn","displayNl":"de opzegtermijn","pos":"substantief","meanings":[{"de":"die Kündigungsfrist","ex":"Mijn opzegtermijn is een maand.","exDe":"Meine Kündigungsfrist ist ein Monat."},{"de":"die Kündigungsfrist (auch bei Verträgen/Abos)","ex":"Het abonnement heeft een opzegtermijn van drie maanden.","exDe":"Das Abonnement hat eine Kündigungsfrist von drei Monaten."}],"usage":"Arbeits- und Vertragsrecht; abstrakter Zeitraum, nicht bildlich.","genus":"de","plural":"opzegtermijnen"},"bk_1855":{"lemma":"ontslaan","displayNl":"ontslaan","pos":"werkwoord","meanings":[{"de":"entlassen, kündigen (jdn aus einer Anstellung)","ex":"Het bedrijf moest twintig werknemers ontslaan.","exDe":"Die Firma musste zwanzig Mitarbeiter entlassen."},{"de":"entlassen, entbinden (aus einer Verpflichtung oder Aufgabe)","ex":"Hij werd van zijn functie ontslagen.","exDe":"Er wurde von seiner Funktion entbunden."},{"de":"entlassen (aus dem Krankenhaus)","ex":"De patiënt werd na een week uit het ziekenhuis ontslagen.","exDe":"Der Patient wurde nach einer Woche aus dem Krankenhaus entlassen."}],"usage":"Unregelmäßiges Verb (ontslaan – ontsloeg – ontslagen), nicht trennbar, Hilfsverb hebben. Oft im Passiv: 'ontslagen worden' = entlassen werden. Vgl. 'opzeggen', wenn der Arbeitnehmer selbst kündigt.","conjugation":{"presens":{"ik":"ontsla","jij":"ontslaat","hij":"ontslaat","wij":"ontslaan"},"imperfectum":{"ik":"ontsloeg","wij":"ontsloegen"},"perfectum":{"aux":"hebben","participle":"ontslagen"}},"illustratable":true},"bk_1856":{"lemma":"ontslag","displayNl":"het ontslag","pos":"substantief","meanings":[{"de":"die Entlassung, die Kündigung (durch den Arbeitgeber)","ex":"Hij kreeg zijn ontslag na de reorganisatie.","exDe":"Er bekam seine Kündigung nach der Umstrukturierung."},{"de":"die Kündigung (durch den Arbeitnehmer selbst)","ex":"Ze nam ontslag omdat ze een betere baan had gevonden.","exDe":"Sie kündigte, weil sie eine bessere Stelle gefunden hatte."}],"usage":"'ontslag krijgen/nemen': krijgen = entlassen werden, nemen = selbst kündigen. Verb dazu: 'ontslaan'.","genus":"het","plural":"ontslagen"},"bk_1857":{"lemma":"opzeggen","displayNl":"opzeggen","pos":"werkwoord","meanings":[{"de":"kündigen (Vertrag, Abo, Mitgliedschaft, Stelle)","ex":"Ik wil mijn abonnement opzeggen.","exDe":"Ich möchte mein Abo kündigen."},{"de":"aufsagen, vortragen (auswendig)","ex":"De leerling moest het gedicht uit het hoofd opzeggen.","exDe":"Der Schüler musste das Gedicht auswendig aufsagen."}],"usage":"Trennbares Verb (zeg ... op), Hilfsverb hebben. Für das Kündigen einer Stelle durch den Arbeitnehmer üblich; der Arbeitgeber 'ontslaat'.","conjugation":{"presens":{"ik":"zeg op","jij":"zegt op","hij":"zegt op","wij":"zeggen op"},"imperfectum":{"ik":"zegde op","wij":"zegden op"},"perfectum":{"aux":"hebben","participle":"opgezegd"}}},"bk_1859":{"lemma":"verantwoordelijk","displayNl":"verantwoordelijk","pos":"adjectief","meanings":[{"de":"verantwortlich, zuständig (für etwas)","ex":"Zij is verantwoordelijk voor de planning.","exDe":"Sie ist für die Planung verantwortlich."},{"de":"verantwortlich, schuld (an etwas)","ex":"Wie is verantwoordelijk voor deze fout?","exDe":"Wer ist für diesen Fehler verantwortlich?"},{"de":"verantwortungsvoll, verantwortungsbewusst","ex":"Dat is een verantwoordelijke baan.","exDe":"Das ist eine verantwortungsvolle Stelle."}],"usage":"Meist mit 'voor': 'verantwoordelijk zijn voor'. Substantiv: 'de verantwoordelijkheid' (die Verantwortung)."},"bk_1860":{"lemma":"deadline","displayNl":"de deadline","pos":"substantief","meanings":[{"de":"die Frist, der Abgabetermin, die Deadline","ex":"We moeten de deadline halen.","exDe":"Wir müssen die Frist einhalten."}],"usage":"Englisches Lehnwort, im Niederländischen gängig. Auch 'uiterste datum' als Alternative. 'de deadline halen' = die Frist einhalten.","genus":"de","plural":"deadlines"},"bk_1861":{"lemma":"project","displayNl":"het project","pos":"substantief","meanings":[{"de":"das Projekt (Vorhaben, geplante Aufgabe)","ex":"Het project loopt goed.","exDe":"Das Projekt läuft gut."}],"usage":"Aussprache 'proJECT' mit Betonung auf der zweiten Silbe. Plural 'projecten'.","genus":"het","plural":"projecten"},"bk_1862":{"lemma":"doelstelling","displayNl":"de doelstelling","pos":"substantief","meanings":[{"de":"das Ziel, die Zielsetzung (angestrebtes Ergebnis)","ex":"We halen onze doelstelling voor dit kwartaal.","exDe":"Wir erreichen unser Ziel für dieses Quartal."}],"usage":"Formeller/geschäftlicher als das allgemeine 'doel' (das Ziel); betont die bewusst gesetzte Zielvorgabe.","genus":"de","plural":"doelstellingen"},"bk_1863":{"lemma":"omzet","displayNl":"de omzet","pos":"substantief","meanings":[{"de":"der Umsatz (Verkaufserlös eines Unternehmens)","ex":"De omzet stijgt dit jaar met tien procent.","exDe":"Der Umsatz steigt dieses Jahr um zehn Prozent."}],"usage":"Wirtschaftsbegriff; nicht mit 'winst' (Gewinn) verwechseln – omzet ist der Bruttoerlös vor Kosten. Verb 'omzetten' bedeutet dagegen umsetzen/umwandeln.","genus":"de","plural":"omzetten"},"bk_1864":{"lemma":"winst","displayNl":"de winst","pos":"substantief","meanings":[{"de":"der Gewinn (finanziell), der Profit","ex":"Het bedrijf maakt dit jaar veel winst.","exDe":"Die Firma macht dieses Jahr viel Gewinn."},{"de":"der Gewinn, der Vorteil, der Zugewinn","ex":"Dat is pure winst voor ons team.","exDe":"Das ist reiner Gewinn für unser Team."},{"de":"der Sieg (in Spiel/Wettkampf)","ex":"De winst ging naar de gastploeg.","exDe":"Der Sieg ging an die Gastmannschaft."}],"usage":"Substantiv (de-Wort). Gegenteil im Finanzsinn: 'het verlies' (Verlust). Häufig 'winst maken' (Gewinn machen).","genus":"de","plural":"winsten"},"bk_1865":{"lemma":"kosten","displayNl":"de kosten","pos":"substantief","meanings":[{"de":"die Kosten, die Ausgaben","ex":"De kosten van de reparatie zijn te hoog.","exDe":"Die Kosten der Reparatur sind zu hoch."},{"de":"der Aufwand, die Unkosten","ex":"Wij vergoeden alle gemaakte kosten.","exDe":"Wir erstatten alle entstandenen Kosten."}],"usage":"Plurale tantum im Sinne von 'Kosten' (immer Plural). Der Singular 'de kost' bedeutet dagegen 'Nahrung/Lebensunterhalt' und ist ein eigenes Wort. Häufig 'kosten besparen', 'ten koste van'.","genus":"de","plural":"kosten"},"bk_1866":{"lemma":"budget","displayNl":"het budget","pos":"substantief","meanings":[{"de":"das Budget, der Etat, der finanzielle Rahmen","ex":"Ons budget voor dit project is beperkt.","exDe":"Unser Budget für dieses Projekt ist begrenzt."}],"usage":"Substantiv (het-Wort). Häufig 'binnen het budget blijven' (im Budget bleiben), 'het budget overschrijden' (das Budget überschreiten).","genus":"het","plural":"budgetten"},"bk_1867":{"lemma":"begroting","displayNl":"de begroting","pos":"substantief","meanings":[{"de":"der Haushaltsplan, der Etat (öffentlich/betrieblich)","ex":"De begroting voor volgend jaar is goedgekeurd.","exDe":"Der Haushaltsplan für nächstes Jahr ist genehmigt."},{"de":"der Kostenvoranschlag, die Kalkulation","ex":"De aannemer stuurt me een begroting voor de verbouwing.","exDe":"Der Bauunternehmer schickt mir einen Kostenvoranschlag für den Umbau."}],"usage":"Substantiv (de-Wort). Von 'begroten' (veranschlagen, budgetieren). In der Politik 'de Rijksbegroting' (der Staatshaushalt).","genus":"de","plural":"begrotingen"},"bk_1868":{"lemma":"belasting","displayNl":"de belasting","pos":"substantief","meanings":[{"de":"die Steuer, die Abgabe","ex":"Iedereen moet belasting betalen.","exDe":"Jeder muss Steuern zahlen."},{"de":"die Belastung, die Last (physisch/psychisch)","ex":"De belasting op zijn rug was te zwaar.","exDe":"Die Belastung auf seinem Rücken war zu schwer."}],"usage":"Substantiv (de-Wort). Im Steuersinn oft im Plural 'belastingen'. Die niederländische Steuerbehörde heißt 'de Belastingdienst'.","genus":"de","plural":"belastingen"},"bk_1869":{"lemma":"pensioen","displayNl":"het pensioen","pos":"substantief","meanings":[{"de":"die Rente, die Pension, das Ruhegehalt","ex":"Hij gaat volgend jaar met pensioen.","exDe":"Er geht nächstes Jahr in Rente."},{"de":"die Altersvorsorge, die Rentenversicherung","ex":"Ik bouw pensioen op via mijn werkgever.","exDe":"Ich baue über meinen Arbeitgeber eine Altersvorsorge auf."}],"usage":"Substantiv (het-Wort). Feste Wendung 'met pensioen gaan' (in Rente gehen). 'pensioen opbouwen' (Altersvorsorge aufbauen).","genus":"het","plural":"pensioenen"},"bk_1870":{"lemma":"vakbond","displayNl":"de vakbond","pos":"substantief","meanings":[{"de":"die Gewerkschaft","ex":"Zij is lid van de vakbond.","exDe":"Sie ist Mitglied der Gewerkschaft."}],"usage":"Substantiv (de-Wort). Zusammensetzung aus 'vak' (Fach/Beruf) + 'bond' (Bund). Große NL-Gewerkschaft: 'de FNV'.","genus":"de","plural":"vakbonden"},"bk_1871":{"lemma":"staking","displayNl":"de staking","pos":"substantief","meanings":[{"de":"der Streik, der Ausstand","ex":"Vandaag is er een staking bij de spoorwegen.","exDe":"Heute gibt es einen Streik bei der Bahn."},{"de":"die Einstellung, das Aussetzen (einer Tätigkeit)","ex":"De staking van de vijandelijkheden werd afgekondigd.","exDe":"Die Einstellung der Feindseligkeiten wurde verkündet."}],"usage":"Substantiv (de-Wort). Von 'staken' (streiken; einstellen). Häufig 'het werk staken', 'in staking gaan' (in den Streik treten).","genus":"de","plural":"stakingen","illustratable":true},"bk_1872":{"lemma":"werkloosheid","displayNl":"de werkloosheid","pos":"substantief","meanings":[{"de":"die Arbeitslosigkeit","ex":"De werkloosheid daalt al maanden.","exDe":"Die Arbeitslosigkeit sinkt schon seit Monaten."},{"de":"die Erwerbslosigkeit (Zustand ohne Arbeit)","ex":"Door de crisis nam de werkloosheid sterk toe.","exDe":"Durch die Krise nahm die Arbeitslosigkeit stark zu."}],"usage":"Abstraktes de-Wort ohne gebräuchlichen Plural; bezeichnet den gesellschaftlichen Zustand bzw. die Quote.","genus":"de"},"bk_1873":{"lemma":"werkloos","displayNl":"werkloos","pos":"adjectief","meanings":[{"de":"arbeitslos, ohne Arbeit","ex":"Hij is al een jaar werkloos.","exDe":"Er ist seit einem Jahr arbeitslos."},{"de":"untätig, tatenlos (bildlich)","ex":"Ze zag werkloos toe hoe het misging.","exDe":"Sie sah tatenlos zu, wie es schieflief."}],"usage":"Adjektiv; attributiv 'de werkloze jongeren'. Substantiviert 'de werkloze' = der/die Arbeitslose."},"bk_1874":{"lemma":"zelfstandige","displayNl":"de zelfstandige","pos":"substantief","meanings":[{"de":"der/die Selbstständige, Freiberufler(in)","ex":"Als zelfstandige werk ik thuis.","exDe":"Als Selbstständiger arbeite ich zu Hause."},{"de":"der/die Gewerbetreibende (Unternehmer ohne Anstellung)","ex":"Veel zelfstandigen hebben last van de nieuwe regels.","exDe":"Viele Selbstständige leiden unter den neuen Regeln."}],"usage":"Substantiviertes Adjektiv (van 'zelfstandig' = selbstständig/unabhängig); oft 'zzp'er' im Niederländischen.","genus":"de","plural":"zelfstandigen"},"bk_1875":{"lemma":"thuiswerken","displayNl":"het thuiswerken","pos":"substantief","meanings":[{"de":"das Arbeiten von zu Hause, Homeoffice","ex":"Thuiswerken bevalt mij goed.","exDe":"Homeoffice gefällt mir gut."},{"de":"die Heim-/Telearbeit","ex":"Sinds de pandemie is thuiswerken heel gewoon.","exDe":"Seit der Pandemie ist Homeoffice ganz normal."}],"usage":"Substantivierter Infinitiv (het-Wort), kein Plural. Als Verb 'thuiswerken' (trennbar: ik werk thuis) ebenfalls gebräuchlich.","genus":"het","illustratable":true},"bk_1876":{"lemma":"deeltijd","displayNl":"de deeltijd","pos":"substantief","meanings":[{"de":"die Teilzeit","ex":"Ik werk in deeltijd.","exDe":"Ich arbeite in Teilzeit."},{"de":"die Teilzeitbeschäftigung","ex":"Na de geboorte ging ze in deeltijd werken.","exDe":"Nach der Geburt ging sie in Teilzeit arbeiten."}],"usage":"Meist unzählbar in Wendungen 'in deeltijd (werken)'; oft attributiv als 'deeltijdbaan' (Teilzeitstelle).","genus":"de"},"bk_1877":{"lemma":"voltijd","displayNl":"de voltijd","pos":"substantief","meanings":[{"de":"die Vollzeit","ex":"Zij werkt voltijd.","exDe":"Sie arbeitet in Vollzeit."},{"de":"die Vollzeitbeschäftigung","ex":"Hij zoekt een baan in voltijd.","exDe":"Er sucht eine Stelle in Vollzeit."}],"usage":"Meist unzählbar; adverbial 'voltijd werken' oder attributiv 'voltijdbaan'. Gegenstück zu 'deeltijd'.","genus":"de"},"bk_1879":{"lemma":"samenwerken","displayNl":"samenwerken","pos":"werkwoord","meanings":[{"de":"zusammenarbeiten","ex":"We werken graag samen.","exDe":"Wir arbeiten gerne zusammen."},{"de":"kooperieren, gemeinsam an etwas arbeiten","ex":"De twee bedrijven werken samen aan een nieuw project.","exDe":"Die beiden Firmen kooperieren an einem neuen Projekt."}],"usage":"Trennbares Verb (werken ... samen). Konstruktion 'samenwerken met/aan'.","conjugation":{"presens":{"ik":"werk samen","jij":"werkt samen","hij":"werkt samen","wij":"werken samen"},"imperfectum":{"ik":"werkte samen","wij":"werkten samen"},"perfectum":{"aux":"hebben","participle":"samengewerkt"}},"illustratable":true},"bk_1880":{"lemma":"presentatie","displayNl":"de presentatie","pos":"substantief","meanings":[{"de":"die Präsentation, der Vortrag","ex":"Ik geef morgen een presentatie.","exDe":"Ich halte morgen eine Präsentation."},{"de":"die Aufmachung, Darbietung (z. B. eines Produkts)","ex":"De presentatie van het gerecht was prachtig.","exDe":"Die Präsentation des Gerichts war wunderschön."},{"de":"die Vorstellung, Enthüllung (offizielle Vorstellung)","ex":"De presentatie van het nieuwe boek is volgende week.","exDe":"Die Vorstellung des neuen Buches ist nächste Woche."}],"usage":"de-Wort, Plural 'presentaties'. 'een presentatie geven/houden' = eine Präsentation halten.","genus":"de","plural":"presentaties","illustratable":true},"bk_1881":{"lemma":"presenteren","displayNl":"presenteren","pos":"werkwoord","meanings":[{"de":"präsentieren, vorstellen","ex":"Zij presenteert het nieuwe plan aan het team.","exDe":"Sie präsentiert dem Team den neuen Plan."},{"de":"moderieren (Sendung/Show)","ex":"Hij presenteert al jaren dit tv-programma.","exDe":"Er moderiert diese Fernsehsendung schon seit Jahren."}],"usage":"Regelmäßig, Hilfsverb hebben. Fremdwort auf -eren; Partizip gepresenteerd. Auch: sich zeigen — 'zich presenteren'.","conjugation":{"presens":{"ik":"presenteer","jij":"presenteert","hij":"presenteert","wij":"presenteren"},"imperfectum":{"ik":"presenteerde","wij":"presenteerden"},"perfectum":{"aux":"hebben","participle":"gepresenteerd"}},"illustratable":true},"bk_1882":{"lemma":"bespreking","displayNl":"de bespreking","pos":"substantief","meanings":[{"de":"die Besprechung, das Meeting","ex":"De bespreking is naar morgen verplaatst.","exDe":"Die Besprechung wurde auf morgen verschoben."},{"de":"die Rezension, die Kritik (Buch/Film)","ex":"De bespreking van het boek stond in de krant.","exDe":"Die Rezension des Buches stand in der Zeitung."}],"usage":"de-Wort, Plural besprekingen. Von 'bespreken' (besprechen). Zweite Bedeutung häufig in Zusammensetzungen: boekbespreking, filmbespreking.","genus":"de","plural":"besprekingen"},"bk_1883":{"lemma":"overleg","displayNl":"het overleg","pos":"substantief","meanings":[{"de":"die Absprache, die Beratung, die Rücksprache","ex":"Na overleg met het team beslissen we.","exDe":"Nach Absprache mit dem Team entscheiden wir."},{"de":"die Besprechung, das (regelmäßige) Meeting","ex":"Elke maandag hebben we werkoverleg.","exDe":"Jeden Montag haben wir eine Arbeitsbesprechung."}],"usage":"het-Wort. Plural overleggen ist selten; meist Singular ('in overleg met', 'na overleg'). Von 'overleggen' (sich beraten).","genus":"het","plural":"overleggen"},"bk_1884":{"lemma":"overleggen","displayNl":"overleggen","pos":"werkwoord","meanings":[{"de":"sich absprechen, sich beraten (met)","ex":"Ik overleg eerst met mijn baas.","exDe":"Ich spreche mich zuerst mit meinem Chef ab."},{"de":"vorlegen, einreichen (Dokumente, formell)","ex":"U moet een geldig paspoort overleggen.","exDe":"Sie müssen einen gültigen Pass vorlegen."}],"usage":"Regelmäßig, Hilfsverb hebben. Homonym: untrennbar overléggen = sich beraten (Betonung auf -leg-); trennbar óverleggen = vorlegen (ik leg over). Partizip overgelegd bei der trennbaren Vorlege-Bedeutung.","conjugation":{"presens":{"ik":"overleg","jij":"overlegt","hij":"overlegt","wij":"overleggen"},"imperfectum":{"ik":"overlegde","wij":"overlegden"},"perfectum":{"aux":"hebben","participle":"overlegd"}}},"bk_1885":{"lemma":"beslissing","displayNl":"de beslissing","pos":"substantief","meanings":[{"de":"die Entscheidung","ex":"De beslissing valt vandaag.","exDe":"Die Entscheidung fällt heute."},{"de":"der Entschluss, der Beschluss","ex":"Het was een moeilijke beslissing om te verhuizen.","exDe":"Es war ein schwerer Entschluss, umzuziehen."}],"usage":"de-Wort, Plural beslissingen. Von 'beslissen'. Häufig: een beslissing nemen (eine Entscheidung treffen).","genus":"de","plural":"beslissingen"},"bk_1886":{"lemma":"beslissen","displayNl":"beslissen","pos":"werkwoord","meanings":[{"de":"entscheiden, beschließen","ex":"De baas beslist erover.","exDe":"Der Chef entscheidet darüber."},{"de":"entscheiden (Ausgang/Wettkampf)","ex":"Een laat doelpunt besliste de wedstrijd.","exDe":"Ein spätes Tor entschied das Spiel."}],"usage":"Regelmäßig, Hilfsverb hebben; Stamm beslis, Partizip beslist ('t kofschip → -te/-t). Konstruktion: beslissen over iets, beslissen om te + Infinitiv.","conjugation":{"presens":{"ik":"beslis","jij":"beslist","hij":"beslist","wij":"beslissen"},"imperfectum":{"ik":"besliste","wij":"beslisten"},"perfectum":{"aux":"hebben","participle":"beslist"}}},"bk_1887":{"lemma":"feedback","displayNl":"de feedback","pos":"substantief","meanings":[{"de":"das Feedback, die Rückmeldung","ex":"Ik krijg altijd goede feedback van mijn collega's.","exDe":"Ich bekomme von meinen Kollegen immer gutes Feedback."}],"usage":"de-Wort, englisches Lehnwort; meist ohne Plural (unzählbar). Häufig: feedback geven/krijgen (Feedback geben/bekommen).","genus":"de"},"bk_1888":{"lemma":"beoordeling","displayNl":"de beoordeling","pos":"substantief","meanings":[{"de":"die Beurteilung, die Bewertung","ex":"Mijn beoordeling was dit jaar positief.","exDe":"Meine Beurteilung war dieses Jahr positiv."},{"de":"die Note, die Einschätzung","ex":"De docent gaf een strenge beoordeling.","exDe":"Der Lehrer gab eine strenge Bewertung."}],"usage":"de-Wort, Plural beoordelingen. Von 'beoordelen' (beurteilen). Kontext: Arbeit (functioneringsgesprek), Schule, Rezensionen.","genus":"de","plural":"beoordelingen"},"bk_1889":{"lemma":"motivatie","displayNl":"de motivatie","pos":"substantief","meanings":[{"de":"die Motivation, der Antrieb","ex":"Zijn motivatie is groot.","exDe":"Seine Motivation ist groß."},{"de":"die Begründung, das Motiv (einer Entscheidung)","ex":"De motivatie van het besluit staat in de brief.","exDe":"Die Begründung der Entscheidung steht im Brief."}],"usage":"Abstraktes Nomen; 'motivatie hebben/vinden voor iets'.","genus":"de","plural":"motivaties"},"bk_1890":{"lemma":"stage","displayNl":"de stage","pos":"substantief","meanings":[{"de":"das Praktikum","ex":"Ik loop stage bij een bank.","exDe":"Ich mache ein Praktikum bei einer Bank."}],"usage":"Aussprache franz. ['staːʒə]. Feste Wendung 'stage lopen' = ein Praktikum machen.","genus":"de","plural":"stages"},"bk_1891":{"lemma":"stagiair","displayNl":"de stagiair","pos":"substantief","meanings":[{"de":"der Praktikant","ex":"De stagiair leert snel.","exDe":"Der Praktikant lernt schnell."}],"usage":"Weibliche Form: 'stagiaire'. Aus dem Französischen.","genus":"de","plural":"stagiairs","illustratable":true},"bk_1892":{"lemma":"sfeer","displayNl":"de sfeer","pos":"substantief","meanings":[{"de":"die Atmosphäre, die Stimmung","ex":"De sfeer op kantoor is goed.","exDe":"Die Atmosphäre im Büro ist gut."},{"de":"die Sphäre, der Bereich","ex":"Dat ligt in de politieke sfeer.","exDe":"Das liegt im politischen Bereich."}],"usage":"Häufig 'een gezellige/goede sfeer'. Plural 'sferen'.","genus":"de","plural":"sferen"},"bk_1893":{"lemma":"werkdruk","displayNl":"de werkdruk","pos":"substantief","meanings":[{"de":"der Arbeitsdruck, die Arbeitsbelastung","ex":"De werkdruk is hoog.","exDe":"Der Arbeitsdruck ist hoch."}],"usage":"Meist ohne Plural. 'hoge/lage werkdruk'.","genus":"de"},"bk_1894":{"lemma":"oplossing","displayNl":"de oplossing","pos":"substantief","meanings":[{"de":"die Lösung (eines Problems)","ex":"We zoeken een oplossing.","exDe":"Wir suchen eine Lösung."},{"de":"die Lösung (Chemie, Flüssigkeit)","ex":"Een oplossing van zout in water.","exDe":"Eine Lösung von Salz in Wasser."}],"usage":"Von 'oplossen'. 'een oplossing vinden/bedenken'.","genus":"de","plural":"oplossingen"},"bk_1895":{"lemma":"oplossen","displayNl":"oplossen","pos":"werkwoord","meanings":[{"de":"lösen (ein Problem)","ex":"Zij lost het probleem op.","exDe":"Sie löst das Problem."},{"de":"sich auflösen (in Flüssigkeit)","ex":"De suiker lost op in de thee.","exDe":"Der Zucker löst sich im Tee auf."},{"de":"sich auflösen, verschwinden","ex":"De mist loste langzaam op.","exDe":"Der Nebel löste sich langsam auf."}],"usage":"Trennbares Verb (op|lossen). Aufgelöst: 'ik los ... op'. Perfekt mit 'hebben' (transitiv) bzw. 'zijn' (intransitiv, sich auflösen).","conjugation":{"presens":{"ik":"los op","jij":"lost op","hij":"lost op","wij":"lossen op"},"imperfectum":{"ik":"loste op","wij":"losten op"},"perfectum":{"aux":"hebben","participle":"opgelost"}}},"bk_1896":{"lemma":"probleem","displayNl":"het probleem","pos":"substantief","meanings":[{"de":"das Problem, die Schwierigkeit","ex":"Er is een probleem met de order.","exDe":"Es gibt ein Problem mit der Bestellung."},{"de":"die (mathematische) Aufgabe, das Problem","ex":"Dit is een lastig wiskundig probleem.","exDe":"Das ist eine schwierige mathematische Aufgabe."}],"usage":"Onzijdig: 'het probleem'. Plural 'problemen'. 'een probleem oplossen'.","genus":"het","plural":"problemen"},"bk_1897":{"lemma":"verbeteren","displayNl":"verbeteren","pos":"werkwoord","meanings":[{"de":"verbessern","ex":"We willen de dienst verbeteren.","exDe":"Wir wollen den Service verbessern."},{"de":"korrigieren, ausbessern","ex":"De leraar verbetert de fouten in mijn tekst.","exDe":"Der Lehrer korrigiert die Fehler in meinem Text."}],"usage":"Regelmäßiges Verb. Auch reflexiv: 'zich verbeteren' (sich verbessern).","conjugation":{"presens":{"ik":"verbeter","jij":"verbetert","hij":"verbetert","wij":"verbeteren"},"imperfectum":{"ik":"verbeterde","wij":"verbeterden"},"perfectum":{"aux":"hebben","participle":"verbeterd"}}},"bk_1898":{"lemma":"leidinggevende","displayNl":"de leidinggevende","pos":"substantief","meanings":[{"de":"die Führungskraft, der/die Vorgesetzte","ex":"De leidinggevende maakt het plan.","exDe":"Die Führungskraft macht den Plan."}],"usage":"Substantiviertes Partizip; geschlechtsneutral. Plural 'leidinggevenden'.","genus":"de","plural":"leidinggevenden"},"bk_1899":{"lemma":"leidinggeven","displayNl":"leidinggeven","pos":"werkwoord","meanings":[{"de":"leiten, führen","ex":"Zij geeft leiding aan het team.","exDe":"Sie leitet das Team."}],"usage":"Trennbares Verb (leiding|geven), oft als 'leiding geven aan iets/iemand'. Unregelmäßig (geven).","conjugation":{"presens":{"ik":"geef leiding","jij":"geeft leiding","hij":"geeft leiding","wij":"geven leiding"},"imperfectum":{"ik":"gaf leiding","wij":"gaven leiding"},"perfectum":{"aux":"hebben","participle":"leidinggegeven"}}},"bk_1900":{"lemma":"klantenservice","displayNl":"de klantenservice","pos":"substantief","meanings":[{"de":"der Kundendienst, der Kundenservice","ex":"Bel de klantenservice.","exDe":"Ruf den Kundendienst an."}],"usage":"Auch 'klantendienst'. Bezeichnet Abteilung und Dienstleistung.","genus":"de","plural":"klantenservices"},"bk_1901":{"lemma":"aanbieding","displayNl":"de aanbieding","pos":"substantief","meanings":[{"de":"das Sonderangebot, das Angebot (im Laden)","ex":"De koffie is deze week in de aanbieding.","exDe":"Der Kaffee ist diese Woche im Angebot."},{"de":"das Angebot, die Offerte (geschäftlich)","ex":"We sturen een aanbieding.","exDe":"Wir schicken ein Angebot."}],"usage":"Feste Wendung 'in de aanbieding zijn' = im Angebot sein. Verwandt mit 'aanbod'.","genus":"de","plural":"aanbiedingen"},"bk_1902":{"lemma":"onderhandeling","displayNl":"de onderhandeling","pos":"substantief","meanings":[{"de":"die Verhandlung","ex":"De onderhandeling duurt lang.","exDe":"Die Verhandlung dauert lange."}],"usage":"Oft im Plural 'onderhandelingen' (Verhandlungen).","genus":"de","plural":"onderhandelingen"},"bk_1903":{"lemma":"onderhandelen","displayNl":"onderhandelen","pos":"werkwoord","meanings":[{"de":"verhandeln","ex":"Wij onderhandelen over de prijs.","exDe":"Wir verhandeln über den Preis."}],"usage":"Regelmäßig, untrennbar (Betonung 'onder-'). Konstruktion 'onderhandelen over iets / met iemand'.","conjugation":{"presens":{"ik":"onderhandel","jij":"onderhandelt","hij":"onderhandelt","wij":"onderhandelen"},"imperfectum":{"ik":"onderhandelde","wij":"onderhandelden"},"perfectum":{"aux":"hebben","participle":"onderhandeld"}}},"bk_1904":{"lemma":"afspraak","displayNl":"de afspraak","pos":"substantief","meanings":[{"de":"die Vereinbarung, die Abmachung","ex":"We houden ons aan de afspraken.","exDe":"Wir halten uns an die Vereinbarungen."},{"de":"der Termin, die Verabredung","ex":"Ik heb morgen een afspraak bij de dokter.","exDe":"Ich habe morgen einen Termin beim Arzt."}],"usage":"Eingabe war Plural 'afspraken' -> Singular 'afspraak'. Wendung 'een afspraak maken' = einen Termin ausmachen / etwas vereinbaren.","genus":"de","plural":"afspraken"},"bk_1905":{"lemma":"zelfstandig naamwoord","displayNl":"het zelfstandig naamwoord","pos":"substantief","meanings":[{"de":"das Substantiv, das Nomen","ex":"\"Huis\" is een zelfstandig naamwoord.","exDe":"\"Haus\" ist ein Substantiv."}],"usage":"Grammatischer Fachbegriff. Bezeichnet ein Hauptwort (Ding, Person, Begriff). Immer het-Wort; Plural: zelfstandige naamwoorden.","genus":"het","plural":"zelfstandige naamwoorden"},"bk_1906":{"lemma":"bijvoeglijk naamwoord","displayNl":"het bijvoeglijk naamwoord","pos":"substantief","meanings":[{"de":"das Adjektiv, das Eigenschaftswort","ex":"\"Mooi\" is een bijvoeglijk naamwoord.","exDe":"\"Schön\" ist ein Adjektiv."}],"usage":"Grammatischer Fachbegriff für ein Wort, das ein Substantiv näher beschreibt. het-Wort; Plural: bijvoeglijke naamwoorden.","genus":"het","plural":"bijvoeglijke naamwoorden"},"bk_1907":{"lemma":"lidwoord","displayNl":"het lidwoord","pos":"substantief","meanings":[{"de":"der Artikel (Grammatik)","ex":"Het lidwoord staat voor het zelfstandig naamwoord.","exDe":"Der Artikel steht vor dem Substantiv."}],"usage":"Grammatischer Fachbegriff. Im Niederländischen: bepaald lidwoord (de/het) und onbepaald lidwoord (een). het-Wort; Plural: lidwoorden.","genus":"het","plural":"lidwoorden"},"bk_1908":{"lemma":"betekenis","displayNl":"de betekenis","pos":"substantief","meanings":[{"de":"die Bedeutung (eines Wortes, Zeichens)","ex":"Wat is de betekenis van dit woord?","exDe":"Was ist die Bedeutung dieses Wortes?"},{"de":"die Bedeutung, die Wichtigkeit (Bedeutsamkeit)","ex":"Dit besluit is van grote betekenis voor het land.","exDe":"Diese Entscheidung ist von großer Bedeutung für das Land."}],"usage":"de-Wort; Plural: betekenissen. Doppelt -ss- im Plural. Verwendet für Wortbedeutung ebenso wie für Bedeutsamkeit/Tragweite (van betekenis zijn).","genus":"de","plural":"betekenissen"},"bk_1909":{"lemma":"vertaling","displayNl":"de vertaling","pos":"substantief","meanings":[{"de":"die Übersetzung (Ergebnis)","ex":"De vertaling van dit boek is niet goed.","exDe":"Die Übersetzung dieses Buches ist nicht gut."},{"de":"die Übersetzung, das Übersetzen (Tätigkeit)","ex":"De vertaling van de tekst kostte veel tijd.","exDe":"Das Übersetzen des Textes kostete viel Zeit."}],"usage":"de-Wort; Plural: vertalingen. Bezeichnet sowohl das übersetzte Ergebnis als auch den Vorgang des Übersetzens.","genus":"de","plural":"vertalingen"},"bk_1910":{"lemma":"uitspraak","displayNl":"de uitspraak","pos":"substantief","meanings":[{"de":"die Aussprache (Art, Wörter zu artikulieren)","ex":"Je uitspraak van het Nederlands is heel goed.","exDe":"Deine Aussprache des Niederländischen ist sehr gut."},{"de":"die Äußerung, die Aussage (Ausspruch)","ex":"Dat was een opmerkelijke uitspraak van de minister.","exDe":"Das war eine bemerkenswerte Äußerung des Ministers."},{"de":"das Urteil, die Entscheidung (juristisch)","ex":"De rechter deed vandaag uitspraak in de zaak.","exDe":"Der Richter fällte heute das Urteil in dem Fall."}],"usage":"de-Wort; Plural: uitspraken. Mehrdeutig: Aussprache (Phonetik), Äußerung/Ausspruch, sowie richterliches Urteil (uitspraak doen).","genus":"de","plural":"uitspraken"},"bk_1911":{"lemma":"uitspreken","displayNl":"uitspreken","pos":"werkwoord","meanings":[{"de":"aussprechen, artikulieren","ex":"Hoe spreek je dit woord uit?","exDe":"Wie spricht man dieses Wort aus?"},{"de":"aussprechen, äußern (eine Meinung, einen Wunsch)","ex":"Zij sprak haar dank uit tegenover het team.","exDe":"Sie sprach dem Team ihren Dank aus."},{"de":"(ein Urteil) verkünden, fällen","ex":"De rechter sprak het vonnis uit.","exDe":"Der Richter verkündete das Urteil."}],"usage":"Trennbares Verb (uit + spreken), stark. In Hauptsätzen trennt sich das Präfix: \"ik spreek het woord uit\". Perfekt mit hebben; Partizip uitgesproken.","conjugation":{"presens":{"ik":"spreek uit","jij":"spreekt uit","hij":"spreekt uit","wij":"spreken uit"},"imperfectum":{"ik":"sprak uit","wij":"spraken uit"},"perfectum":{"aux":"hebben","participle":"uitgesproken"}}},"bk_1912":{"lemma":"spelling","displayNl":"de spelling","pos":"substantief","meanings":[{"de":"die Rechtschreibung, die Orthografie","ex":"Let op de spelling van dit woord.","exDe":"Achte auf die Rechtschreibung dieses Wortes."},{"de":"die Schreibweise (eines bestimmten Wortes)","ex":"Er zijn twee spellingen van dit woord.","exDe":"Es gibt zwei Schreibweisen dieses Wortes."}],"usage":"de-Wort; Plural: spellingen. Bezeichnet das Regelsystem der Rechtschreibung sowie die konkrete Schreibweise eines Wortes.","genus":"de","plural":"spellingen"},"bk_1913":{"lemma":"klank","displayNl":"de klank","pos":"substantief","meanings":[{"de":"der Laut (Sprachlaut)","ex":"Deze klank is moeilijk uit te spreken.","exDe":"Dieser Laut ist schwer auszusprechen."},{"de":"der Klang, der Ton","ex":"De klank van de piano is warm.","exDe":"Der Klang des Klaviers ist warm."}],"usage":"Sprachlaut oder Klang; Plural klanken.","genus":"de","plural":"klanken"},"bk_1914":{"lemma":"onderwerp","displayNl":"het onderwerp","pos":"substantief","meanings":[{"de":"das Thema, der Gegenstand","ex":"Wat is het onderwerp van de les?","exDe":"Was ist das Thema der Stunde?"},{"de":"das Subjekt (Grammatik)","ex":"In deze zin is 'de hond' het onderwerp.","exDe":"In diesem Satz ist 'der Hund' das Subjekt."}],"usage":"Thema/Gegenstand; grammatisch = Subjekt.","genus":"het","plural":"onderwerpen"},"bk_1915":{"lemma":"mening","displayNl":"de mening","pos":"substantief","meanings":[{"de":"die Meinung, die Ansicht","ex":"Wat is jouw mening hierover?","exDe":"Was ist deine Meinung dazu?"}],"usage":"Vaak: naar mijn mening = meiner Meinung nach.","genus":"de","plural":"meningen"},"bk_1916":{"lemma":"onderwijs","displayNl":"het onderwijs","pos":"substantief","meanings":[{"de":"die Bildung, das Unterrichtswesen, der Unterricht","ex":"Het onderwijs in Nederland is goed.","exDe":"Die Bildung in den Niederlanden ist gut."}],"usage":"Unzählbar; kein gebräuchlicher Plural.","genus":"het"},"bk_1917":{"lemma":"verslag","displayNl":"het verslag","pos":"substantief","meanings":[{"de":"der Bericht, das Protokoll","ex":"Ik schrijf een verslag over het boek.","exDe":"Ich schreibe einen Bericht über das Buch."}],"usage":"verslag doen van = berichten über.","genus":"het","plural":"verslagen"},"bk_1918":{"lemma":"samenvatting","displayNl":"de samenvatting","pos":"substantief","meanings":[{"de":"die Zusammenfassung","ex":"Maak een korte samenvatting van de tekst.","exDe":"Mach eine kurze Zusammenfassung des Textes."}],"usage":"Zu samenvatten gehörig.","genus":"de","plural":"samenvattingen"},"bk_1919":{"lemma":"samenvatten","displayNl":"samenvatten","pos":"werkwoord","meanings":[{"de":"zusammenfassen","ex":"Kun je de tekst kort samenvatten?","exDe":"Kannst du den Text kurz zusammenfassen?"}],"usage":"Trennbares Verb (vatten ... samen).","conjugation":{"presens":{"ik":"vat samen","jij":"vat samen","hij":"vat samen","wij":"vatten samen"},"imperfectum":{"ik":"vatte samen","wij":"vatten samen"},"perfectum":{"aux":"hebben","participle":"samengevat"}}},"bk_1920":{"lemma":"aandacht","displayNl":"de aandacht","pos":"substantief","meanings":[{"de":"die Aufmerksamkeit","ex":"Geef aandacht aan de les.","exDe":"Schenke dem Unterricht Aufmerksamkeit."}],"usage":"Unzählbar; aandacht besteden aan = Aufmerksamkeit widmen.","genus":"de"},"bk_1921":{"lemma":"vooruitgang","displayNl":"de vooruitgang","pos":"substantief","meanings":[{"de":"der Fortschritt","ex":"Ik maak veel vooruitgang met mijn Nederlands.","exDe":"Ich mache viele Fortschritte mit meinem Niederländisch."},{"de":"die Besserung, das Vorankommen","ex":"De patiënt boekt langzaam vooruitgang.","exDe":"Der Patient macht langsam Fortschritte (Besserung)."}],"usage":"Abstraktes Substantiv; oft 'vooruitgang maken/boeken' = Fortschritte machen. Plural selten gebräuchlich.","genus":"de","plural":"vooruitgangen"},"bk_1922":{"lemma":"resultaat","displayNl":"het resultaat","pos":"substantief","meanings":[{"de":"das Ergebnis, das Resultat","ex":"Het resultaat van de test is heel goed.","exDe":"Das Ergebnis des Tests ist sehr gut."},{"de":"der Erfolg, die Wirkung (met resultaat = erfolgreich)","ex":"Hij heeft hard gewerkt, en met resultaat.","exDe":"Er hat hart gearbeitet, und mit Erfolg."}],"usage":"Neutrum (het); Plural resultaten. Häufig in Prüfungs-/Arbeits- und Sportkontext.","genus":"het","plural":"resultaten"},"bk_1923":{"lemma":"docent","displayNl":"de docent","pos":"substantief","meanings":[{"de":"der Dozent, der Lehrer (an weiterführender Schule/Hochschule)","ex":"De docent geeft les op de universiteit.","exDe":"Der Dozent unterrichtet an der Universität."},{"de":"die Lehrkraft, der/die Lehrende","ex":"Onze docent Engels is heel geduldig.","exDe":"Unsere Englischlehrkraft ist sehr geduldig."}],"usage":"Person; weibliche Form 'docente' gebräuchlich. Plural docenten. Höher als 'leraar' (Grundschule).","genus":"de","plural":"docenten","illustratable":true},"bk_1924":{"lemma":"slagen","displayNl":"slagen","pos":"werkwoord","meanings":[{"de":"bestehen (eine Prüfung/einen Test)","ex":"Ik hoop te slagen voor de toets.","exDe":"Ich hoffe, den Test zu bestehen."},{"de":"gelingen, Erfolg haben, glücken","ex":"De operatie is volledig geslaagd.","exDe":"Die Operation ist voll und ganz gelungen."}],"usage":"Regelmäßiges Verb mit Hilfsverb 'zijn'. 'slagen voor' = bestehen für/in. Nicht mit 'slaan' (schlagen) verwechseln.","conjugation":{"presens":{"ik":"slaag","jij":"slaagt","hij":"slaagt","wij":"slagen"},"imperfectum":{"ik":"slaagde","wij":"slaagden"},"perfectum":{"aux":"zijn","participle":"geslaagd"}}},"bk_1925":{"lemma":"zakken","displayNl":"zakken","pos":"werkwoord","meanings":[{"de":"durchfallen (bei einer Prüfung)","ex":"Hij is gezakt voor het examen.","exDe":"Er ist durch die Prüfung gefallen."},{"de":"sinken, fallen, sich senken (Wasser, Preise, Temperatur)","ex":"Het water in de rivier zakt langzaam.","exDe":"Das Wasser im Fluss sinkt langsam."},{"de":"herunterrutschen, absacken","ex":"Zijn broek zakte steeds af.","exDe":"Seine Hose rutschte immer wieder herunter."}],"usage":"Regelmäßiges Verb, Hilfsverb 'zijn'. Gegenteil von 'slagen' im Prüfungskontext. Homonym zum Plural von 'zak' (Sack/Tasche), aber hier Verb.","conjugation":{"presens":{"ik":"zak","jij":"zakt","hij":"zakt","wij":"zakken"},"imperfectum":{"ik":"zakte","wij":"zakten"},"perfectum":{"aux":"zijn","participle":"gezakt"}}},"bk_1926":{"lemma":"inschrijven","displayNl":"inschrijven","pos":"werkwoord","meanings":[{"de":"sich einschreiben, sich anmelden, sich registrieren (zich inschrijven)","ex":"Ik wil me inschrijven voor de cursus.","exDe":"Ich möchte mich für den Kurs einschreiben."},{"de":"jemanden/etwas eintragen, registrieren","ex":"De ambtenaar schreef de baby in bij de gemeente.","exDe":"Der Beamte trug das Baby bei der Gemeinde ein."}],"usage":"Trennbares Verb (in|schrijven), Hilfsverb 'hebben'. Oft reflexiv: 'zich inschrijven voor'. Gegenteil: uitschrijven.","conjugation":{"presens":{"ik":"schrijf in","jij":"schrijft in","hij":"schrijft in","wij":"schrijven in"},"imperfectum":{"ik":"schreef in","wij":"schreven in"},"perfectum":{"aux":"hebben","participle":"ingeschreven"}}},"bk_1928":{"lemma":"gedicht","displayNl":"het gedicht","pos":"substantief","meanings":[{"de":"das Gedicht","ex":"Ik leer een gedicht uit mijn hoofd.","exDe":"Ich lerne ein Gedicht auswendig."},{"de":"das Poem, der Vers (literarisch)","ex":"Zij schreef een mooi gedicht over de zee.","exDe":"Sie schrieb ein schönes Gedicht über das Meer."}],"usage":"Neutrum (het); Plural gedichten. Verwandt mit 'dichten' (dichten) und 'dichter' (Dichter).","genus":"het","plural":"gedichten"},"bk_1929":{"lemma":"aanwezig","displayNl":"aanwezig","pos":"adjectief","meanings":[{"de":"anwesend, zugegen","ex":"Alle leerlingen zijn aanwezig.","exDe":"Alle Schüler sind anwesend."},{"de":"vorhanden, verfügbar","ex":"Is er nog koffie aanwezig?","exDe":"Ist noch Kaffee vorhanden?"}],"usage":"Adjektiv; Gegenteil 'afwezig' (abwesend). Substantiv 'aanwezigheid' = Anwesenheit/Vorhandensein."},"bk_1930":{"lemma":"afwezig","displayNl":"afwezig","pos":"adjectief","meanings":[{"de":"abwesend, nicht anwesend","ex":"Twee kinderen zijn vandaag afwezig.","exDe":"Zwei Kinder sind heute abwesend."},{"de":"geistesabwesend, zerstreut","ex":"Hij keek me afwezig aan.","exDe":"Er sah mich geistesabwesend an."}],"usage":"Prädikativ und attributiv; Gegenteil van 'aanwezig'. Auch übertragen für Unaufmerksamkeit."},"bk_1931":{"lemma":"kennismaking","displayNl":"de kennismaking","pos":"substantief","meanings":[{"de":"das Kennenlernen, erste Begegnung","ex":"De eerste les is bedoeld voor de kennismaking.","exDe":"Die erste Stunde ist für das Kennenlernen gedacht."},{"de":"erster Kontakt mit einer Sache, Einführung","ex":"Dit boek is een goede kennismaking met de Nederlandse cultuur.","exDe":"Dieses Buch ist eine gute Einführung in die niederländische Kultur."}],"usage":"Oft in 'ter kennismaking' (zum Kennenlernen). Von 'kennismaken met iemand/iets'.","genus":"de","plural":"kennismakingen"},"bk_1932":{"lemma":"nadenken","displayNl":"nadenken","pos":"werkwoord","meanings":[{"de":"nachdenken","ex":"Ik moet even nadenken.","exDe":"Ich muss kurz nachdenken."},{"de":"überlegen, sich Gedanken machen (nadenken over)","ex":"We moeten goed nadenken over onze toekomst.","exDe":"Wir müssen gut über unsere Zukunft nachdenken."}],"usage":"Trennbares Verb (na + denken); 'nadenken over iets'. Onregelmatig: denken → dacht.","conjugation":{"presens":{"ik":"denk na","jij":"denkt na","hij":"denkt na","wij":"denken na"},"imperfectum":{"ik":"dacht na","wij":"dachten na"},"perfectum":{"aux":"hebben","participle":"nagedacht"}}},"bk_1933":{"lemma":"middelbare school","displayNl":"de middelbare school","pos":"substantief","meanings":[{"de":"die weiterführende Schule (Sekundarstufe, ca. 12-18 Jahre)","ex":"Zij gaat na de zomer naar de middelbare school.","exDe":"Sie geht nach dem Sommer auf die weiterführende Schule."}],"usage":"Niederländisches Schulsystem: folgt op de basisschool; umfasst vmbo/havo/vwo.","genus":"de","plural":"middelbare scholen","illustratable":true},"bk_1934":{"lemma":"conciërge","displayNl":"de conciërge","pos":"substantief","meanings":[{"de":"der Hausmeister, Pförtner","ex":"De conciërge opent elke ochtend de deuren van de school.","exDe":"Der Hausmeister öffnet jeden Morgen die Türen der Schule."},{"de":"der Concierge (in Hotel oder Wohngebäude)","ex":"De conciërge van het hotel riep een taxi voor ons.","exDe":"Der Concierge des Hotels rief uns ein Taxi."}],"usage":"Uit het Frans; in Schulen/Gebäuden Hausmeister, in Hotels Concierge.","genus":"de","plural":"conciërges","illustratable":true},"bk_1935":{"lemma":"kantine","displayNl":"de kantine","pos":"substantief","meanings":[{"de":"die Kantine, Mensa","ex":"Tussen de middag eten we in de kantine.","exDe":"Mittags essen wir in der Kantine."}],"usage":"Speiseraum in Schule, Betrieb oder Sportverein. In sportclub oft ook der Vereinsraum.","genus":"de","plural":"kantines","illustratable":true},"bk_1936":{"lemma":"aula","displayNl":"de aula","pos":"substantief","meanings":[{"de":"die Aula, Festsaal (in Schule oder Universität)","ex":"De diploma-uitreiking vindt plaats in de aula.","exDe":"Die Zeugnisübergabe findet in der Aula statt."}],"usage":"Großer Versammlungssaal einer Schule/Universität. Plural mit apostrof-s: aula's.","genus":"de","plural":"aula's","illustratable":true},"bk_1937":{"lemma":"concentreren","displayNl":"concentreren","pos":"werkwoord","meanings":[{"de":"sich konzentrieren (zich concentreren)","ex":"Ik kan me in de bibliotheek goed concentreren.","exDe":"In der Bibliothek kann ich mich gut konzentrieren."},{"de":"konzentrieren, bündeln (zusammenführen)","ex":"We concentreren onze aandacht op het examen.","exDe":"Wir konzentrieren unsere Aufmerksamkeit auf die Prüfung."}],"usage":"Meist reflexiv 'zich concentreren op iets'. Regelmatig zwak werkwoord.","conjugation":{"presens":{"ik":"concentreer","jij":"concentreert","hij":"concentreert","wij":"concentreren"},"imperfectum":{"ik":"concentreerde","wij":"concentreerden"},"perfectum":{"aux":"hebben","participle":"geconcentreerd"}}},"bk_1938":{"lemma":"gemotiveerd","displayNl":"gemotiveerd","pos":"adjectief","meanings":[{"de":"motiviert","ex":"De leerlingen zijn erg gemotiveerd voor het examen.","exDe":"Die Schüler sind sehr motiviert für die Prüfung."},{"de":"begründet, gut untermauert","ex":"Zij gaf een goed gemotiveerd antwoord.","exDe":"Sie gab eine gut begründete Antwort."}],"usage":"Prädikativ und attributiv (een gemotiveerde leerling). Steigerung: gemotiveerder, meest gemotiveerd.","notes":"Voltooid deelwoord van 'motiveren', wordt als adjectief gebruikt."},"bk_1939":{"lemma":"deelnemer","displayNl":"de deelnemer","pos":"substantief","meanings":[{"de":"der Teilnehmer","ex":"Elke deelnemer aan de cursus krijgt een boek.","exDe":"Jeder Teilnehmer am Kurs bekommt ein Buch."},{"de":"der Wettkampfteilnehmer, Starter","ex":"De deelnemer met het hoogste aantal punten wint.","exDe":"Der Teilnehmer mit der höchsten Punktzahl gewinnt."}],"usage":"Vrouwelijke vorm: deelneemster. Vaak met 'aan' (deelnemer aan iets).","genus":"de","plural":"deelnemers"},"bk_1940":{"lemma":"niveau","displayNl":"het niveau","pos":"substantief","meanings":[{"de":"das Niveau, der Leistungsstand","ex":"Wat is jouw niveau in het Nederlands?","exDe":"Was ist dein Niveau im Niederländischen?"},{"de":"die Ebene, die Höhe (Stufe)","ex":"Het water staat op hetzelfde niveau als de dijk.","exDe":"Das Wasser steht auf demselben Niveau wie der Deich."}],"usage":"Frans leenwoord, uitspraak [ni-voo]. Plural 'niveaus'.","genus":"het","plural":"niveaus"},"bk_1941":{"lemma":"moedertaal","displayNl":"de moedertaal","pos":"substantief","meanings":[{"de":"die Muttersprache","ex":"Duits is mijn moedertaal.","exDe":"Deutsch ist meine Muttersprache."}],"usage":"Samenstelling moeder + taal. Plural moedertalen.","genus":"de","plural":"moedertalen"},"bk_1942":{"lemma":"vreemde taal","displayNl":"de vreemde taal","pos":"substantief","meanings":[{"de":"die Fremdsprache","ex":"Nederlands is voor mij een vreemde taal.","exDe":"Niederländisch ist für mich eine Fremdsprache."}],"usage":"Vaste woordgroep (adjectief 'vreemd' + 'taal'). Plural: vreemde talen. Vergelijk 'moedertaal'.","genus":"de","plural":"vreemde talen","notes":"Kernwoord is 'taal' (de-woord); 'vreemde' is de verbogen adjectiefvorm."},"bk_1943":{"lemma":"dictee","displayNl":"het dictee","pos":"substantief","meanings":[{"de":"das Diktat","ex":"We maken vandaag een dictee in de klas.","exDe":"Wir schreiben heute ein Diktat in der Klasse."}],"usage":"Het-woord (niet 'de dictee'). Plural dictees. Vaak met werkwoord 'maken' of 'geven'.","genus":"het","plural":"dictees","notes":"Input 'de dictee' korrigiert zu 'het dictee'.","illustratable":true},"bk_1944":{"lemma":"aantekening","displayNl":"de aantekening","pos":"substantief","meanings":[{"de":"die Notiz, die Aufzeichnung","ex":"Ik maak aantekeningen tijdens de les.","exDe":"Ich mache Notizen während des Unterrichts."},{"de":"der Vermerk, die Anmerkung (offiziell)","ex":"Er staat een aantekening in mijn dossier.","exDe":"In meiner Akte steht ein Vermerk."}],"usage":"Meestal in het meervoud gebruikt: aantekeningen maken. Van het werkwoord 'aantekenen'.","genus":"de","plural":"aantekeningen","illustratable":true},"bk_1945":{"lemma":"winkelier","displayNl":"de winkelier","pos":"substantief","meanings":[{"de":"der Ladenbesitzer, der Einzelhändler","ex":"De winkelier helpt mij bij het uitzoeken.","exDe":"Der Ladenbesitzer hilft mir bei der Auswahl."}],"usage":"Vrouwelijke vorm: winkelierster. Plural winkeliers.","genus":"de","plural":"winkeliers","illustratable":true},"bk_1946":{"lemma":"etalage","displayNl":"de etalage","pos":"substantief","meanings":[{"de":"das Schaufenster","ex":"De etalage van de kledingwinkel is prachtig versierd.","exDe":"Das Schaufenster des Kleidungsgeschäfts ist wunderschön dekoriert."},{"de":"die Auslage (dekorierte Warenpräsentation)","ex":"Zij zet de nieuwe schönen in de etalage.","exDe":"Sie stellt die neuen Schuhe in die Auslage."}],"usage":"Alltäglich; das Fenster/die Auslage eines Geschäfts zur Straße hin.","genus":"de","plural":"etalages","illustratable":true},"bk_1947":{"lemma":"bankrekening","displayNl":"de bankrekening","pos":"substantief","meanings":[{"de":"das Bankkonto","ex":"Ik open een bankrekening bij een Nederlandse bank.","exDe":"Ich eröffne ein Bankkonto bei einer niederländischen Bank."},{"de":"das Girokonto / die Kontoverbindung","ex":"Mijn salaris wordt op mijn bankrekening gestort.","exDe":"Mein Gehalt wird auf mein Bankkonto überwiesen."}],"usage":"Finanzieller Fachbegriff; das Konto einer Person bei einer Bank.","genus":"de","plural":"bankrekeningen"},"bk_1948":{"lemma":"oorbel","displayNl":"de oorbel","pos":"substantief","meanings":[{"de":"der Ohrring","ex":"Zij draagt vandaag zilveren oorbellen.","exDe":"Sie trägt heute silberne Ohrringe."}],"usage":"Schmuckstück, das am Ohr getragen wird; meist im Plural (oorbellen) als Paar.","genus":"de","plural":"oorbellen","illustratable":true},"bk_1949":{"lemma":"portefeuille","displayNl":"de portefeuille","pos":"substantief","meanings":[{"de":"die Brieftasche / das Portemonnaie","ex":"Mijn portefeuille zit vol met pasjes en bonnetjes.","exDe":"Meine Brieftasche ist voll mit Karten und Belegen."},{"de":"das Portfolio / der Geschäftsbereich (Politik/Finanzen)","ex":"De minister beheert de portefeuille onderwijs.","exDe":"Der Minister verwaltet das Ressort Bildung."}],"usage":"Konkret: Brieftasche; übertragen: politisches Ressort oder Anlage-/Aktienportfolio.","genus":"de","plural":"portefeuilles","illustratable":true},"bk_1950":{"lemma":"goud","displayNl":"het goud","pos":"substantief","meanings":[{"de":"das Gold (Edelmetall)","ex":"De ring is van goud.","exDe":"Der Ring ist aus Gold."},{"de":"das Gold (Goldmedaille, Sieg)","ex":"De zwemster won goud op de Olympische Spelen.","exDe":"Die Schwimmerin gewann Gold bei den Olympischen Spielen."}],"usage":"Stoffname (unzählbar); für die Adjektivform 'aus Gold' benutzt man 'gouden'. Übertragen auch für Goldmedaille.","genus":"het","notes":"Im Input als 'golden' angegeben; das niederländische Wort 'goud' ist jedoch ein Substantiv (het goud). Die attributive Adjektivform lautet 'gouden'.","illustratable":true},"bk_1951":{"lemma":"zilver","displayNl":"het zilver","pos":"substantief","meanings":[{"de":"das Silber (Edelmetall)","ex":"De ketting is van zilver.","exDe":"Die Kette ist aus Silber."},{"de":"das Silber (Silbermedaille, zweiter Platz)","ex":"Het team behaalde zilver op het toernooi.","exDe":"Das Team holte Silber beim Turnier."}],"usage":"Stoffname (unzählbar); die attributive Adjektivform ist 'zilveren'. Übertragen auch für Silbermedaille oder Tafelsilber.","genus":"het","notes":"Im Input als 'silbern' angegeben; das niederländische Wort 'zilver' ist ein Substantiv (het zilver). Die attributive Adjektivform lautet 'zilveren'.","illustratable":true},"bk_1952":{"lemma":"stof","displayNl":"de stof","pos":"substantief","meanings":[{"de":"der Stoff / das Gewebe (Textil)","ex":"De stof van deze jurk is heerlijk zacht.","exDe":"Der Stoff dieses Kleides ist herrlich weich."},{"de":"der Staub","ex":"Er ligt veel stof op de kast.","exDe":"Auf dem Schrank liegt viel Staub."},{"de":"der Stoff / die Substanz (Materie, Chemie)","ex":"Water is een kleurloze stof.","exDe":"Wasser ist eine farblose Substanz."},{"de":"der Stoff / das Thema (Lernstoff)","ex":"We moeten veel stof leren voor het examen.","exDe":"Wir müssen viel Stoff für die Prüfung lernen."}],"usage":"Homonym: Textilgewebe, Staub, chemische Substanz und Lern-/Themenstoff. 'de stof' (Textil/Substanz) hat Plural 'stoffen'; in der Bedeutung Staub unzählbar (het stof).","genus":"de","plural":"stoffen","notes":"Achtung: als 'Staub' ist es 'het stof' (unzählbar), in den anderen Bedeutungen 'de stof' mit Plural 'stoffen'.","illustratable":true},"bk_1953":{"lemma":"katoen","displayNl":"het katoen","pos":"substantief","meanings":[{"de":"die Baumwolle (Stoff/Faser)","ex":"Het shirt is van katoen.","exDe":"Das Hemd ist aus Baumwolle."},{"de":"das Baumwollgewebe","ex":"Zij koopt een meter wit katoen voor een blouse.","exDe":"Sie kauft einen Meter weiße Baumwolle für eine Bluse."}],"usage":"Stoffname (meist unzählbar, het katoen); attributiv 'katoenen'. Bezeichnet die Faser und den daraus gewebten Stoff.","genus":"het","notes":"Redensart 'hem katoen geven' (Gas geben) ist umgangssprachlich und selten.","illustratable":true},"bk_1954":{"lemma":"wol","displayNl":"de wol","pos":"substantief","meanings":[{"de":"die Wolle","ex":"De trui is van wol.","exDe":"Der Pullover ist aus Wolle."},{"de":"die Wolle (Faser/Garn zum Stricken)","ex":"Zij koopt wol om een sjaal te breien.","exDe":"Sie kauft Wolle, um einen Schal zu stricken."}],"usage":"Stoffbezeichnung, meist unzählbar; Plural 'wollen' nur für Sorten.","genus":"de","plural":"wollen","illustratable":true},"bk_1955":{"lemma":"leer","displayNl":"het leer","pos":"substantief","meanings":[{"de":"das Leder","ex":"De tas is van leer.","exDe":"Die Tasche ist aus Leder."},{"de":"die Lehre, Doktrin (als 'de leer')","ex":"Hij bestudeert de leer van Spinoza.","exDe":"Er studiert die Lehre Spinozas."}],"usage":"'het leer' = Leder (unzählbar); homonym 'de leer' = Lehre/Doktrin (anderes Genus).","genus":"het","illustratable":true},"bk_1956":{"lemma":"mode","displayNl":"de mode","pos":"substantief","meanings":[{"de":"die Mode","ex":"Zij houdt van mode.","exDe":"Sie mag Mode."},{"de":"der Trend, die Modeerscheinung","ex":"Wijde broeken zijn nu weer in de mode.","exDe":"Weite Hosen sind jetzt wieder in Mode."}],"usage":"Meist unzählbar für 'Mode' als Ganzes; Plural 'modes' für einzelne Modeerscheinungen.","genus":"de","plural":"modes"},"bk_1957":{"lemma":"ouderwets","displayNl":"ouderwets","pos":"adjectief","meanings":[{"de":"altmodisch, veraltet","ex":"Die broek is ouderwets.","exDe":"Diese Hose ist altmodisch."},{"de":"altmodisch, gemütlich-traditionell (positiv, wie früher)","ex":"We hadden een ouderwets gezellige avond.","exDe":"Wir hatten einen richtig gemütlichen Abend wie früher."}],"usage":"Attributiv 'een ouderwetse jas'; adverbial oft verstärkend positiv ('ouderwets lekker')."},"bk_1958":{"lemma":"winkeltijd","displayNl":"de winkeltijd","pos":"substantief","meanings":[{"de":"die Öffnungszeit (eines Geschäfts)","ex":"Wat zijn de winkeltijden?","exDe":"Wie sind die Öffnungszeiten?"},{"de":"die Ladenöffnungszeit","ex":"De winkeltijden zijn op zondag beperkt.","exDe":"Die Ladenöffnungszeiten sind sonntags eingeschränkt."}],"usage":"Meist im Plural 'winkeltijden' gebräuchlich.","genus":"de","plural":"winkeltijden"},"bk_1959":{"lemma":"schap","displayNl":"het schap","pos":"substantief","meanings":[{"de":"das Regal, das Regalbrett (im Geschäft/Vorratsraum)","ex":"Het brood ligt in het schap.","exDe":"Das Brot liegt im Regal."},{"de":"das Regalfach, die Ablage","ex":"De schappen in de supermarkt zijn goed gevuld.","exDe":"Die Regale im Supermarkt sind gut gefüllt."}],"usage":"Auch 'de schap' regional möglich; Standard 'het schap'.","genus":"het","plural":"schappen","illustratable":true},"bk_1960":{"lemma":"voorraad","displayNl":"de voorraad","pos":"substantief","meanings":[{"de":"der Vorrat, die Reserve","ex":"De voorraad is op.","exDe":"Der Vorrat ist aus."},{"de":"der Lagerbestand, das Warenlager","ex":"We hebben nog een grote voorraad op magazijn.","exDe":"Wir haben noch einen großen Lagerbestand im Magazin."}],"usage":"'op voorraad' = auf Lager, vorrätig; Plural 'voorraden'.","genus":"de","plural":"voorraden","illustratable":true},"bk_1961":{"lemma":"uitverkocht","displayNl":"uitverkocht","pos":"adjectief","meanings":[{"de":"ausverkauft","ex":"De schönen zijn uitverkocht.","exDe":"Die Schuhe sind ausverkauft."},{"de":"ausverkauft, restlos vergriffen (Vorstellung/Konzert)","ex":"Het concert was al weken uitverkocht.","exDe":"Das Konzert war schon seit Wochen ausverkauft."}],"usage":"Prädikativ gebraucht; als Partizip zu 'uitverkopen'."},"bk_1962":{"lemma":"bezorgen","displayNl":"bezorgen","pos":"werkwoord","meanings":[{"de":"liefern, zustellen","ex":"Ze bezorgen het pakket morgen.","exDe":"Sie liefern das Paket morgen."},{"de":"bereiten, verschaffen (jemandem etwas)","ex":"Dat bezorgt me veel zorgen.","exDe":"Das bereitet mir viele Sorgen."}],"usage":"Regelmäßiges Verb ohne 'ge-' im Partizip (untrennbares Präfix be-). Häufig im Kontext Paketzustellung / Online-Handel.","conjugation":{"presens":{"ik":"bezorg","jij":"bezorgt","hij":"bezorgt","wij":"bezorgen"},"imperfectum":{"ik":"bezorgde","wij":"bezorgden"},"perfectum":{"aux":"hebben","participle":"bezorgd"}},"illustratable":true},"bk_1963":{"lemma":"webshop","displayNl":"de webshop","pos":"substantief","meanings":[{"de":"der Onlineshop, der Webshop","ex":"Deze webshop is goedkoop.","exDe":"Dieser Onlineshop ist günstig."}],"usage":"'de'-Wort, Plural auf -s. Entlehnung aus dem Englischen; gebräuchlich für einen Internet-Verkaufsladen.","genus":"de","plural":"webshops","illustratable":true},"bk_1964":{"lemma":"garantie","displayNl":"de garantie","pos":"substantief","meanings":[{"de":"die Garantie, die Gewährleistung","ex":"De telefoon heeft twee jaar garantie.","exDe":"Das Telefon hat zwei Jahre Garantie."},{"de":"die Zusicherung, das Versprechen","ex":"Er is geen garantie dat het lukt.","exDe":"Es gibt keine Garantie, dass es klappt."}],"usage":"'de'-Wort, Plural garanties. Abstrakter Begriff aus Handel und Recht.","genus":"de","plural":"garanties"},"bk_1965":{"lemma":"kwaliteit","displayNl":"de kwaliteit","pos":"substantief","meanings":[{"de":"die Qualität, die Güte","ex":"De kwaliteit van dit hout is goed.","exDe":"Die Qualität dieses Holzes ist gut."},{"de":"die (gute) Eigenschaft, die Fähigkeit","ex":"Geduld is een van zijn kwaliteiten.","exDe":"Geduld ist eine seiner Qualitäten."}],"usage":"'de'-Wort. Im Plural oft im Sinne von 'positive Eigenschaften/Talente'.","genus":"de","plural":"kwaliteiten"},"bk_1966":{"lemma":"reclame","displayNl":"de reclame","pos":"substantief","meanings":[{"de":"die Werbung, die Reklame","ex":"Ik zie veel reclame op tv.","exDe":"Ich sehe viel Werbung im Fernsehen."},{"de":"die Werbeanzeige, der Werbespot","ex":"Tijdens de film kwam er een reclame.","exDe":"Während des Films kam eine Werbung."},{"de":"das Sonderangebot, die Aktion (in reclame)","ex":"De kaas is deze week in de reclame.","exDe":"Der Käse ist diese Woche im Angebot."}],"usage":"'de'-Wort. 'in de reclame (zijn)' bedeutet 'im Angebot sein'.","genus":"de","plural":"reclames","illustratable":true},"bk_1967":{"lemma":"uitgeven","displayNl":"uitgeven","pos":"werkwoord","meanings":[{"de":"ausgeben (Geld)","ex":"Ik geef veel geld uit aan boeken.","exDe":"Ich gebe viel Geld für Bücher aus."},{"de":"herausgeben, verlegen, veröffentlichen","ex":"De uitgeverij geeft dit boek volgend jaar uit.","exDe":"Der Verlag gibt dieses Buch nächstes Jahr heraus."},{"de":"ausstellen, herausgeben (z. B. ein Dokument)","ex":"De gemeente geeft een nieuw paspoort uit.","exDe":"Die Gemeinde stellt einen neuen Pass aus."}],"usage":"Trennbares, unregelmäßiges Verb (uit + geven). Ursprung 'het geld uitgeven' → Infinitiv 'uitgeven'. Partikel 'uit' wird im Hauptsatz nach hinten gestellt.","conjugation":{"presens":{"ik":"geef uit","jij":"geeft uit","hij":"geeft uit","wij":"geven uit"},"imperfectum":{"ik":"gaf uit","wij":"gaven uit"},"perfectum":{"aux":"hebben","participle":"uitgegeven"}},"illustratable":true},"bk_1968":{"lemma":"schuld","displayNl":"de schuld","pos":"substantief","meanings":[{"de":"die Schuld (Verschulden, Verantwortung für etwas Schlechtes)","ex":"Het is niet mijn schuld.","exDe":"Es ist nicht meine Schuld."},{"de":"die Schulden (geliehenes Geld, das man zurückzahlen muss)","ex":"Hij heeft veel schulden bij de bank.","exDe":"Er hat viele Schulden bei der Bank."},{"de":"die Schuld (moralisch/religiös)","ex":"Vergeef ons onze schulden.","exDe":"Vergib uns unsere Schuld."}],"usage":"'de'-Wort. Im Sinne 'Verschulden' meist Singular; im finanziellen Sinn meist Plural 'schulden'.","genus":"de","plural":"schulden"},"bk_1969":{"lemma":"lenen","displayNl":"lenen","pos":"werkwoord","meanings":[{"de":"(sich) leihen, borgen (von jemandem nehmen)","ex":"Mag ik geld van je lenen?","exDe":"Darf ich mir Geld von dir leihen?"},{"de":"verleihen, ausleihen (jemandem geben)","ex":"Ik leen mijn fiets aan mijn broer.","exDe":"Ich leihe meinem Bruder mein Fahrrad."}],"usage":"Regelmäßiges Verb. 'lenen' deckt beide Richtungen ab: 'lenen van' = sich leihen von, 'lenen aan' = verleihen an.","conjugation":{"presens":{"ik":"leen","jij":"leent","hij":"leent","wij":"lenen"},"imperfectum":{"ik":"leende","wij":"leenden"},"perfectum":{"aux":"hebben","participle":"geleend"}}},"bk_1970":{"lemma":"munt","displayNl":"de munt","pos":"substantief","meanings":[{"de":"Münze","ex":"Ik gooi een munt in de fontein.","exDe":"Ich werfe eine Münze in den Brunnen."},{"de":"Währung","ex":"De euro is een munt.","exDe":"Der Euro ist eine Währung."},{"de":"Minze (Pflanze)","ex":"Ik zet thee met verse munt.","exDe":"Ich mache Tee mit frischer Minze."}],"usage":"'de munt' bezeichnet meist eine Geldmünze, im übertragenen Sinn auch eine Währung; das Homonym 'munt' ist zudem die Pflanze Minze.","genus":"de","plural":"munten","illustratable":true},"bk_1971":{"lemma":"wisselkoers","displayNl":"de wisselkoers","pos":"substantief","meanings":[{"de":"Wechselkurs","ex":"De wisselkoers van de euro is vandaag hoog.","exDe":"Der Wechselkurs des Euro ist heute hoch."}],"usage":"Fachbegriff aus dem Finanzwesen: das Umtauschverhältnis zwischen zwei Währungen.","genus":"de","plural":"wisselkoersen"},"bk_1972":{"lemma":"overmaken","displayNl":"overmaken","pos":"werkwoord","meanings":[{"de":"überweisen (Geld)","ex":"Ik maak het geld naar je rekening over.","exDe":"Ich überweise das Geld auf dein Konto."},{"de":"übertragen, weitergeben","ex":"Zij maakt haar liefde voor muziek op haar kinderen over.","exDe":"Sie überträgt ihre Liebe zur Musik auf ihre Kinder."}],"usage":"Trennbares Verb (over|maken): am häufigsten für das Überweisen von Geld, seltener übertragen im Sinne von 'weitergeben'.","conjugation":{"presens":{"ik":"maak over","jij":"maakt over","hij":"maakt over","wij":"maken over"},"imperfectum":{"ik":"maakte over","wij":"maakten over"},"perfectum":{"aux":"hebben","participle":"overgemaakt"}}},"bk_1973":{"lemma":"overschrijving","displayNl":"de overschrijving","pos":"substantief","meanings":[{"de":"Überweisung (Bank)","ex":"De overschrijving is gelukt.","exDe":"Die Überweisung war erfolgreich."}],"usage":"Bankbegriff: das Überweisen eines Geldbetrags von einem Konto auf ein anderes.","genus":"de","plural":"overschrijvingen"},"bk_1974":{"lemma":"saldo","displayNl":"het saldo","pos":"substantief","meanings":[{"de":"Kontostand, Saldo","ex":"Mijn saldo is deze maand laag.","exDe":"Mein Kontostand ist diesen Monat niedrig."}],"usage":"Der verfügbare Betrag auf einem Konto beziehungsweise die Differenz aus Einnahmen und Ausgaben.","genus":"het","plural":"saldo's"},"bk_1975":{"lemma":"kortingsbon","displayNl":"de kortingsbon","pos":"substantief","meanings":[{"de":"Rabattgutschein, Coupon","ex":"Met deze kortingsbon krijg je tien procent korting.","exDe":"Mit diesem Rabattgutschein bekommst du zehn Prozent Rabatt."}],"usage":"Ein Gutschein, der beim Einkauf einen Preisnachlass gewährt.","genus":"de","plural":"kortingsbonnen","illustratable":true},"bk_1976":{"lemma":"cadeaubon","displayNl":"de cadeaubon","pos":"substantief","meanings":[{"de":"Geschenkgutschein","ex":"Voor haar verjaardag krijgt ze een cadeaubon.","exDe":"Zu ihrem Geburtstag bekommt sie einen Geschenkgutschein."}],"usage":"Ein Gutschein über einen bestimmten Wert, der als Geschenk verschenkt und später eingelöst wird.","genus":"de","plural":"cadeaubonnen","illustratable":true},"bk_1977":{"lemma":"verpakking","displayNl":"de verpakking","pos":"substantief","meanings":[{"de":"Verpackung","ex":"De verpakking van het cadeau is prachtig.","exDe":"Die Verpackung des Geschenks ist wunderschön."},{"de":"Umhüllung, Packung","ex":"Gooi de lege verpakking in de bak.","exDe":"Wirf die leere Packung in den Behälter."}],"usage":"Das Material, in das eine Ware eingepackt ist, oder die einzelne Packung selbst.","genus":"de","plural":"verpakkingen","illustratable":true},"bk_1978":{"lemma":"assortiment","displayNl":"het assortiment","pos":"substantief","meanings":[{"de":"das Sortiment","ex":"De winkel heeft een groot assortiment kazen.","exDe":"Das Geschäft hat ein großes Sortiment an Käse."},{"de":"die Auswahl (an Waren)","ex":"Het assortiment wisselt per seizoen.","exDe":"Die Auswahl wechselt je nach Saison."}],"usage":"Neutrales Handels-/Ladenwort; oft mit 'aan' oder Genitiv: 'een assortiment aan producten'.","genus":"het","plural":"assortimenten","illustratable":true},"bk_1979":{"lemma":"wachtrij","displayNl":"de wachtrij","pos":"substantief","meanings":[{"de":"die Warteschlange","ex":"De wachtrij bij de kassa is lang.","exDe":"Die Warteschlange an der Kasse ist lang."},{"de":"die Warteschlange (Computer/System)","ex":"Je staat vierde in de wachtrij.","exDe":"Du bist Vierter in der Warteschlange."}],"usage":"Sowohl konkret (Menschen in Reihe) als auch übertragen (Druckerauftrag, Telefon-Hotline, Datenstruktur).","genus":"de","plural":"wachtrijen","illustratable":true},"bk_1980":{"lemma":"bijzin","displayNl":"de bijzin","pos":"substantief","meanings":[{"de":"der Nebensatz (Grammatik)","ex":"In een bijzin staat de persoonsvorm meestal achteraan.","exDe":"In einem Nebensatz steht das finite Verb meist am Ende."},{"de":"der Gliedsatz","ex":"De bijzin begint met het voegwoord 'omdat'.","exDe":"Der Gliedsatz beginnt mit der Konjunktion 'weil'."}],"usage":"Grammatischer Fachbegriff; Gegenstück zur 'hoofdzin' (Hauptsatz). Hinweis: DE-Wert und Beispielsatz der Rohdaten ('Umtausch/de ruil') gehörten nicht zu diesem Lemma und wurden korrigiert.","genus":"de","plural":"bijzinnen"},"bk_1981":{"lemma":"terugbetalen","displayNl":"terugbetalen","pos":"werkwoord","meanings":[{"de":"zurückzahlen","ex":"Ik betaal je het geleende geld volgende week terug.","exDe":"Ich zahle dir das geliehene Geld nächste Woche zurück."},{"de":"zurückerstatten (Betrag)","ex":"De winkel betaalt het aankoopbedrag terug.","exDe":"Das Geschäft erstattet den Kaufbetrag zurück."}],"usage":"Trennbares Verb (terug + betalen): 'ik betaal ... terug', im Nebensatz/Infinitiv zusammen 'terugbetalen', Partizip 'terugbetaald'.","conjugation":{"presens":{"ik":"betaal terug","jij":"betaalt terug","hij":"betaalt terug","wij":"betalen terug"},"imperfectum":{"ik":"betaalde terug","wij":"betaalden terug"},"perfectum":{"aux":"hebben","participle":"terugbetaald"}}},"bk_1982":{"lemma":"kruidenier","displayNl":"de kruidenier","pos":"substantief","meanings":[{"de":"der Lebensmittelhändler (Krämer, Kolonialwarenhändler)","ex":"De kruidenier weegt de koffiebonen af.","exDe":"Der Lebensmittelhändler wiegt die Kaffeebohnen ab."},{"de":"der Lebensmittelladen (kleiner Tante-Emma-Laden)","ex":"Op de hoek zit een ouderwetse kruidenier.","exDe":"An der Ecke gibt es einen altmodischen Lebensmittelladen."}],"usage":"Bezeichnet sowohl die Person als auch (umgangssprachlich) den kleinen Laden; etwas altmodisch, klassisch niederländisch.","genus":"de","plural":"kruideniers","illustratable":true},"bk_1983":{"lemma":"groenteboer","displayNl":"de groenteboer","pos":"substantief","meanings":[{"de":"der Gemüsehändler","ex":"De groenteboer legt verse tomaten in de kist.","exDe":"Der Gemüsehändler legt frische Tomaten in die Kiste."},{"de":"der Gemüseladen / Gemüsestand","ex":"Ik haal mijn groente altijd bij de groenteboer.","exDe":"Ich hole mein Gemüse immer beim Gemüsehändler."}],"usage":"Person oder (umgangssprachlich) der Laden/Marktstand; typisch für niederländische Wochenmärkte.","genus":"de","plural":"groenteboeren","illustratable":true},"bk_1984":{"lemma":"drogist","displayNl":"de drogist","pos":"substantief","meanings":[{"de":"der Drogist (Person)","ex":"De drogist adviseert me over een goede zonnebrand.","exDe":"Der Drogist berät mich zu einem guten Sonnenschutz."},{"de":"die Drogerie (das Geschäft)","ex":"Ik koop tandpasta en zeep bij de drogist.","exDe":"Ich kaufe Zahnpasta und Seife in der Drogerie."}],"usage":"Bezeichnet Person und (umgangssprachlich) das Geschäft; Drogerie verkauft Hygiene-, Pflege- und frei verkäufliche Gesundheitsprodukte.","genus":"de","plural":"drogisten","illustratable":true},"bk_1985":{"lemma":"warenhuis","displayNl":"het warenhuis","pos":"substantief","meanings":[{"de":"das Kaufhaus","ex":"In het warenhuis kun je kleding, speelgoed en meubels kopen.","exDe":"Im Kaufhaus kann man Kleidung, Spielzeug und Möbel kaufen."},{"de":"das Warenhaus","ex":"Het oude warenhuis heeft meerdere verdiepingen.","exDe":"Das alte Warenhaus hat mehrere Stockwerke."}],"usage":"Großes mehrstöckiges Geschäft mit breitem Sortiment; nicht zu verwechseln mit 'supermarkt' (nur Lebensmittel).","genus":"het","plural":"warenhuizen","illustratable":true},"bk_1986":{"lemma":"kraam","displayNl":"de kraam","pos":"substantief","meanings":[{"de":"der Marktstand, die Verkaufsbude","ex":"Bij de kraam op de markt verkopen ze verse kaas.","exDe":"An dem Marktstand auf dem Markt verkaufen sie frischen Käse."},{"de":"Stand (auf Kirmes/Jahrmarkt)","ex":"Op de kermis staat een kraam met oliebollen.","exDe":"Auf der Kirmes steht eine Bude mit Ölkugeln."}],"usage":"Alltäglich für Verkaufsstand auf Markt/Kirmes. Redewendung 'de hele kraam' = der ganze Kram/das ganze Zeug.","genus":"de","plural":"kramen","illustratable":true},"bk_1987":{"lemma":"afdingen","displayNl":"afdingen","pos":"werkwoord","meanings":[{"de":"(den Preis) herunterhandeln, feilschen","ex":"Op de markt kun je vaak een paar euro afdingen.","exDe":"Auf dem Markt kann man oft ein paar Euro herunterhandeln."},{"de":"etwas in Frage stellen, schmälern (bei 'afdingen op')","ex":"Ik wil niets afdingen op zijn prestatie.","exDe":"Ich will seine Leistung in keiner Weise schmälern."}],"usage":"Trennbares Verb (af + dingen), stark gebeugt. Für Verhandeln über Preise; übertragen 'afdingen op iets' = etwas relativieren/schmälern.","conjugation":{"presens":{"ik":"ding af","jij":"dingt af","hij":"dingt af","wij":"dingen af"},"imperfectum":{"ik":"dong af","wij":"dongen af"},"perfectum":{"aux":"hebben","participle":"afgedongen"}},"illustratable":true},"bk_1988":{"lemma":"aanbetaling","displayNl":"de aanbetaling","pos":"substantief","meanings":[{"de":"die Anzahlung","ex":"Bij de bestelling betaal je een aanbetaling van tien procent.","exDe":"Bei der Bestellung zahlst du eine Anzahlung von zehn Prozent."}],"usage":"Kaufmännisch/finanziell: erste Teilzahlung beim Kauf, Rest folgt später.","genus":"de","plural":"aanbetalingen"},"bk_1989":{"lemma":"in de aanbieding","displayNl":"in de aanbieding","pos":"uitdrukking","meanings":[{"de":"im Angebot, im Sonderangebot","ex":"Deze trui is deze week in de aanbieding.","exDe":"Dieser Pullover ist diese Woche im Angebot."}],"usage":"Feste Wendung im Einzelhandel für reduzierte Ware. Vergleiche 'in de reclame' (belgisches/regionales NL)."},"bk_1990":{"lemma":"winkelmedewerker","displayNl":"de winkelmedewerker","pos":"substantief","meanings":[{"de":"der/die Verkaufsmitarbeiter(in), Ladenangestellte(r)","ex":"De winkelmedewerker helpt de klant bij het zoeken naar de juiste maat.","exDe":"Der Verkaufsmitarbeiter hilft dem Kunden bei der Suche nach der richtigen Größe."}],"usage":"Neutrale Berufsbezeichnung für Angestellte im Einzelhandel, geschlechtsneutral verwendbar.","genus":"de","plural":"winkelmedewerkers","illustratable":true},"bk_1991":{"lemma":"strik","displayNl":"de strik","pos":"substantief","meanings":[{"de":"die Schleife (aus Band, z. B. auf Geschenk)","ex":"Op het cadeau zit een grote rode strik.","exDe":"Auf dem Geschenk ist eine große rote Schleife."},{"de":"die Fliege (Kleidungsstück am Hals)","ex":"Bij zijn smoking draagt hij een zwarte strik.","exDe":"Zu seinem Smoking trägt er eine schwarze Fliege."},{"de":"die Schlinge, Falle (zum Fangen von Tieren)","ex":"De stroper zette een strik voor konijnen.","exDe":"Der Wilderer stellte eine Schlinge für Kaninchen auf."}],"usage":"Grundbedeutung Zierschleife; auch Fliege (Kleidung) und Fang-Schlinge. Wendung 'iemand in de strik lokken' = jemanden in die Falle locken.","genus":"de","plural":"strikken","illustratable":true},"bk_1992":{"lemma":"knoop","displayNl":"de knoop","pos":"substantief","meanings":[{"de":"der Knopf (an Kleidung)","ex":"Er mist een knoop aan mijn overhemd.","exDe":"An meinem Hemd fehlt ein Knopf."},{"de":"der Knoten (in Seil, Faden, Schnur)","ex":"Ik krijg de knoop in het touw niet los.","exDe":"Ich bekomme den Knoten im Seil nicht auf."},{"de":"der Knotenpunkt, das Verkehrsdrehkreuz","ex":"Utrecht is een belangrijke knoop in het spoornet.","exDe":"Utrecht ist ein wichtiger Knotenpunkt im Schienennetz."}],"usage":"Konkret Knopf/Knoten; auch Verkehrsknotenpunkt. Wendung 'de knoop doorhakken' = eine Entscheidung treffen (den Knoten durchschlagen).","genus":"de","plural":"knopen","illustratable":true},"bk_1993":{"lemma":"rits","displayNl":"de rits","pos":"substantief","meanings":[{"de":"der Reißverschluss","ex":"De rits van mijn jas is kapot.","exDe":"Der Reißverschluss meiner Jacke ist kaputt."},{"de":"eine ganze Reihe/Menge (umgangssprachlich, 'een rits')","ex":"Hij stelde een rits vragen achter elkaar.","exDe":"Er stellte eine ganze Reihe Fragen hintereinander."}],"usage":"Meist konkret der Reißverschluss; umgangssprachlich 'een rits' = eine lange Reihe. Verb 'ritsen' = im Reißverschlussverfahren einfädeln (Verkehr).","genus":"de","plural":"ritsen","illustratable":true},"bk_1994":{"lemma":"gebergte","displayNl":"het gebergte","pos":"substantief","meanings":[{"de":"das Gebirge","ex":"Het gebergte ligt in het zuiden van het land.","exDe":"Das Gebirge liegt im Süden des Landes."},{"de":"das Bergmassiv, die Bergkette","ex":"We maakten een wandeling door het besneeuwde gebergte.","exDe":"Wir machten eine Wanderung durch das verschneite Gebirge."}],"usage":"Sammelbegriff für eine zusammenhängende Bergkette; het-Wort, Plural gebergten selten.","genus":"het","plural":"gebergten","illustratable":true},"bk_1995":{"lemma":"gletsjer","displayNl":"de gletsjer","pos":"substantief","meanings":[{"de":"der Gletscher","ex":"De gletsjer wordt elk jaar kleiner.","exDe":"Der Gletscher wird jedes Jahr kleiner."},{"de":"das Gletschereis (als Eismasse)","ex":"Blauw ijs glinstert in de spleten van de gletsjer.","exDe":"Blaues Eis glitzert in den Spalten des Gletschers."}],"usage":"de-Wort; bezeichnet die langsam fließende Eismasse im Hochgebirge.","genus":"de","plural":"gletsjers","illustratable":true},"bk_1996":{"lemma":"vulkaan","displayNl":"de vulkaan","pos":"substantief","meanings":[{"de":"der Vulkan","ex":"De vulkaan is al jaren rustig.","exDe":"Der Vulkan ist seit Jahren ruhig."},{"de":"der Vulkan (bildlich: Quelle heftiger Ausbrüche/Emotionen)","ex":"Van binnen was hij een vulkaan van woede.","exDe":"Innerlich war er ein Vulkan aus Wut."}],"usage":"de-Wort, Plural vulkanen; wörtlich Feuerberg, auch bildlich für aufgestaute Heftigkeit.","genus":"de","plural":"vulkanen","illustratable":true},"bk_1997":{"lemma":"aardbeving","displayNl":"de aardbeving","pos":"substantief","meanings":[{"de":"das Erdbeben","ex":"De aardbeving was heel zwaar.","exDe":"Das Erdbeben war sehr stark."},{"de":"das Erdbeben (bildlich: erschütterndes, umwälzendes Ereignis)","ex":"Het nieuws was een politieke aardbeving.","exDe":"Die Nachricht war ein politisches Erdbeben."}],"usage":"de-Wort, Plural aardbevingen; wörtlich Erschütterung des Bodens, auch bildlich.","genus":"de","plural":"aardbevingen","illustratable":true},"bk_1998":{"lemma":"overstroming","displayNl":"de overstroming","pos":"substantief","meanings":[{"de":"die Überschwemmung, die Überflutung","ex":"Na de regen kwam er een overstroming.","exDe":"Nach dem Regen kam eine Überschwemmung."},{"de":"das Hochwasser","ex":"De overstroming zette de hele polder onder water.","exDe":"Das Hochwasser setzte den ganzen Polder unter Wasser."}],"usage":"de-Wort, Plural overstromingen; das Über-die-Ufer-Treten von Wasser.","genus":"de","plural":"overstromingen","illustratable":true},"bk_1999":{"lemma":"droogte","displayNl":"de droogte","pos":"substantief","meanings":[{"de":"die Dürre, die Trockenheit","ex":"De droogte duurt al weken.","exDe":"Die Dürre dauert schon Wochen."},{"de":"die Trockenheit (Zustand, Mangel an Feuchtigkeit)","ex":"Door de droogte staat de rivier heel laag.","exDe":"Wegen der Trockenheit steht der Fluss sehr niedrig."}],"usage":"de-Wort, Plural droogtes; anhaltender Regenmangel bzw. Trockenheit.","genus":"de","plural":"droogtes","illustratable":true},"bk_2000":{"lemma":"opwarming","displayNl":"de opwarming","pos":"substantief","meanings":[{"de":"die Erwärmung","ex":"De opwarming van de aarde gaat door.","exDe":"Die Erwärmung der Erde geht weiter."},{"de":"das Aufwärmen (von Speisen)","ex":"De opwarming van het eten duurt maar een minuut.","exDe":"Das Aufwärmen des Essens dauert nur eine Minute."},{"de":"das Aufwärmen, das Warmlaufen (Sport)","ex":"Voor de wedstrijd deden we een korte opwarming.","exDe":"Vor dem Wettkampf machten wir ein kurzes Aufwärmen."}],"usage":"de-Wort; meist Erwärmung (Klima), auch Aufwärmen von Essen oder im Sport.","genus":"de","plural":"opwarmingen"},"bk_2001":{"lemma":"klimaatverandering","displayNl":"de klimaatverandering","pos":"substantief","meanings":[{"de":"der Klimawandel, die Klimaveränderung","ex":"Klimaatverandering raakt iedereen.","exDe":"Der Klimawandel betrifft alle."},{"de":"die Klimaveränderung (langfristiger Wandel des Klimas)","ex":"Wetenschappers waarschuwen al lang voor klimaatverandering.","exDe":"Wissenschaftler warnen schon lange vor dem Klimawandel."}],"usage":"de-Wort; abstrakter Begriff für den langfristigen Wandel des globalen Klimas.","genus":"de","plural":"klimaatveranderingen"},"bk_2002":{"lemma":"uitstoot","displayNl":"de uitstoot","pos":"substantief","meanings":[{"de":"der Ausstoß, die Emission (von Abgasen/Schadstoffen)","ex":"De uitstoot van CO2 moet omlaag.","exDe":"Der CO2-Ausstoß muss sinken."},{"de":"das Ausstoßen, der Auswurf (allgemein)","ex":"De uitstoot van fijnstof is schadelijk voor de longen.","exDe":"Der Ausstoß von Feinstaub ist schädlich für die Lunge."}],"usage":"Meist als Stoffname ohne Plural; oft in Zusammensetzungen wie CO2-uitstoot.","genus":"de","illustratable":true},"bk_2003":{"lemma":"duurzaamheid","displayNl":"de duurzaamheid","pos":"substantief","meanings":[{"de":"die Nachhaltigkeit","ex":"Duurzaamheid is heel belangrijk voor de toekomst.","exDe":"Nachhaltigkeit ist sehr wichtig für die Zukunft."},{"de":"die Haltbarkeit, Langlebigkeit (eines Produkts)","ex":"De duurzaamheid van deze schönen is uitstekend.","exDe":"Die Haltbarkeit dieser Schuhe ist hervorragend."}],"usage":"Abstraktes Nomen, in der Regel ohne Plural.","genus":"de"},"bk_2004":{"lemma":"grondstof","displayNl":"de grondstof","pos":"substantief","meanings":[{"de":"der Rohstoff","ex":"Olie is een belangrijke grondstof.","exDe":"Öl ist ein wichtiger Rohstoff."},{"de":"der Ausgangsstoff, das Grundmaterial","ex":"Meel is de grondstof voor brood.","exDe":"Mehl ist der Ausgangsstoff für Brot."}],"usage":"Oberbegriff/Kategorie; häufiger im Plural grondstoffen.","genus":"de","plural":"grondstoffen"},"bk_2005":{"lemma":"brandstof","displayNl":"de brandstof","pos":"substantief","meanings":[{"de":"der Kraftstoff, der Treibstoff","ex":"De auto rijdt op fossiele brandstof.","exDe":"Das Auto fährt mit fossilem Kraftstoff."},{"de":"der Brennstoff (zum Heizen/Verbrennen)","ex":"Hout is een goedkope brandstof voor de kachel.","exDe":"Holz ist ein günstiger Brennstoff für den Ofen."}],"usage":"","genus":"de","plural":"brandstoffen","illustratable":true},"bk_2006":{"lemma":"windmolen","displayNl":"de windmolen","pos":"substantief","meanings":[{"de":"das Windrad, die Windkraftanlage","ex":"De windmolen maakt stroom.","exDe":"Das Windrad erzeugt Strom."},{"de":"die (traditionelle) Windmühle","ex":"In Nederland staan veel oude windmolens.","exDe":"In den Niederlanden stehen viele alte Windmühlen."}],"usage":"Bezeichnet sowohl die moderne Windkraftanlage als auch die historische Mühle.","genus":"de","plural":"windmolens","illustratable":true},"bk_2007":{"lemma":"zonnepaneel","displayNl":"het zonnepaneel","pos":"substantief","meanings":[{"de":"das Solarpanel, das Solarmodul, die Fotovoltaikanlage","ex":"Op het dak liggen zonnepanelen.","exDe":"Auf dem Dach liegen Solarpanele."}],"usage":"Häufig im Plural zonnepanelen.","genus":"het","plural":"zonnepanelen","illustratable":true},"bk_2008":{"lemma":"recycling","displayNl":"de recycling","pos":"substantief","meanings":[{"de":"das Recycling, die Wiederverwertung","ex":"Recycling is goed voor het milieu.","exDe":"Recycling ist gut für die Umwelt."}],"usage":"Leenwoord uit het Engels; abstract, meestal zonder meervoud.","genus":"de"},"bk_2009":{"lemma":"biodiversiteit","displayNl":"de biodiversiteit","pos":"substantief","meanings":[{"de":"die Biodiversität, die Artenvielfalt","ex":"Biodiversiteit neemt helaas af.","exDe":"Die Biodiversität nimmt leider ab."}],"usage":"Abstraktes Fachnomen, ohne Plural.","genus":"de"},"bk_2010":{"lemma":"ecosysteem","displayNl":"het ecosysteem","pos":"substantief","meanings":[{"de":"das Ökosystem","ex":"Het ecosysteem van de Waddenzee is heel kwetsbaar.","exDe":"Das Ökosystem des Wattenmeeres ist sehr empfindlich."}],"usage":"Fachbegriff aus Biologie/Umwelt; bezeichnet das Zusammenspiel von Lebewesen und ihrer Umgebung. Wird auch übertragen benutzt (z. B. 'ecosysteem van apps').","genus":"het","plural":"ecosystemen"},"bk_2011":{"lemma":"soort","displayNl":"de soort","pos":"substantief","meanings":[{"de":"die Art (biologische Art)","ex":"Deze vogelsoort is bijna verdwenen.","exDe":"Diese Vogelart ist fast verschwunden."},{"de":"die Sorte / der Typ","ex":"Wat voor soort kaas wil je?","exDe":"Was für eine Sorte Käse möchtest du?"}],"usage":"Kann 'de' oder (in der Bedeutung 'Typ') auch 'het' sein: 'het soort werk'. In biologischem Sinn immer 'de soort'. In 'een soort ...' (eine Art von) abschwächend gebraucht.","genus":"de","plural":"soorten"},"bk_2012":{"lemma":"reservaat","displayNl":"het reservaat","pos":"substantief","meanings":[{"de":"das Naturschutzgebiet / Reservat","ex":"De wilde dieren leven beschermd in een reservaat.","exDe":"Die wilden Tiere leben geschützt in einem Schutzgebiet."},{"de":"das Reservat (für Ureinwohner)","ex":"Veel indianen wonen in een reservaat.","exDe":"Viele Indianer wohnen in einem Reservat."}],"usage":"Meist für Naturschutzgebiete; kann auch das den Ureinwohnern zugewiesene Reservat bezeichnen.","genus":"het","plural":"reservaten","illustratable":true},"bk_2013":{"lemma":"begroeiing","displayNl":"de begroeiing","pos":"substantief","meanings":[{"de":"der Bewuchs / die Vegetation","ex":"De begroeiing langs de sloot is dicht en groen.","exDe":"Der Bewuchs entlang des Grabens ist dicht und grün."}],"usage":"Meist unzählbar gebraucht (die Gesamtheit der wachsenden Pflanzen an einem Ort); Plural 'begroeiingen' selten.","genus":"de","plural":"begroeiingen","illustratable":true},"bk_2014":{"lemma":"bodem","displayNl":"de bodem","pos":"substantief","meanings":[{"de":"der Boden / das Erdreich","ex":"De bodem is hier heel vruchtbaar.","exDe":"Der Boden ist hier sehr fruchtbar."},{"de":"der Boden / Grund (eines Gefäßes)","ex":"Er zit nog een laagje thee op de bodem van het kopje.","exDe":"Auf dem Boden der Tasse ist noch eine Schicht Tee."},{"de":"der Grund (eines Gewässers)","ex":"Het anker rustte op de bodem van de zee.","exDe":"Der Anker lag auf dem Grund des Meeres."}],"usage":"Grundbedeutung: unterste Fläche. Erdreich (landbouwgrond), Innenfläche eines Behälters oder Grund eines Gewässers. Redewendung: 'de bodem bereiken' = den Tiefpunkt erreichen.","genus":"de","plural":"bodems","illustratable":true},"bk_2015":{"lemma":"neerslag","displayNl":"de neerslag","pos":"substantief","meanings":[{"de":"der Niederschlag (Regen, Schnee, Hagel)","ex":"Er valt vandaag veel neerslag.","exDe":"Heute fällt viel Niederschlag."},{"de":"(Chemie) der Niederschlag / Bodensatz","ex":"Onderin de buis ontstond een witte neerslag.","exDe":"Unten im Reagenzglas bildete sich ein weißer Niederschlag."}],"usage":"Meist unzählbar (Wetter); in der Chemie das ausgefällte Sediment. Übertragen: 'de neerslag van iets' = der Niederschlag/Ausdruck von etwas.","genus":"de","illustratable":true},"bk_2016":{"lemma":"temperatuurdaling","displayNl":"de temperatuurdaling","pos":"substantief","meanings":[{"de":"der Temperaturrückgang / Temperatursturz","ex":"Vannacht komt er een sterke temperatuurdaling.","exDe":"Heute Nacht kommt es zu einem starken Temperaturrückgang."}],"usage":"Zusammengesetztes Wort aus 'temperatuur' + 'daling' (Rückgang); Gegenstück: 'temperatuurstijging'. Häufig in Wetterberichten.","genus":"de","plural":"temperatuurdalingen"},"bk_2017":{"lemma":"windstoot","displayNl":"de windstoot","pos":"substantief","meanings":[{"de":"die Windböe","ex":"Een harde windstoot brak de tak van de boom.","exDe":"Eine starke Windböe brach den Ast vom Baum."}],"usage":"Plötzlicher, kurzer heftiger Windstoß; Synonym 'windvlaag'. Plural mit langem o: 'windstoten'.","genus":"de","plural":"windstoten","illustratable":true},"bk_2018":{"lemma":"hittegolf","displayNl":"de hittegolf","pos":"substantief","meanings":[{"de":"die Hitzewelle","ex":"In juli kwam er een hittegolf over het land.","exDe":"Im Juli zog eine Hitzewelle über das Land."},{"de":"die Hitzewoge (spürbarer Schwall heißer Luft)","ex":"Bij het openen van de oven voelde ze een hittegolf.","exDe":"Beim Öffnen des Ofens spürte sie eine Woge heißer Luft."}],"usage":"Meteorologisch: mehrere aufeinanderfolgende Tage mit hohen Temperaturen (in NL amtlich ab fünf Sommertagen, davon drei Tropentage).","genus":"de","plural":"hittegolven","illustratable":true},"bk_2019":{"lemma":"ijzel","displayNl":"de ijzel","pos":"substantief","meanings":[{"de":"das Glatteis (durch gefrierenden Regen entstehende Eisschicht)","ex":"Door de ijzel was de weg spekglad.","exDe":"Durch das Glatteis war die Straße spiegelglatt."}],"usage":"Stoffname (kein Plural). Meint speziell die glasige Eisschicht durch gefrierenden Regen/Niederschlag; das allgemeine Glatteis-Phänomen heißt auch 'gladheid'.","genus":"de","illustratable":true},"bk_2020":{"lemma":"luchtvochtigheid","displayNl":"de luchtvochtigheid","pos":"substantief","meanings":[{"de":"die Luftfeuchtigkeit","ex":"De luchtvochtigheid is vandaag erg hoog.","exDe":"Die Luftfeuchtigkeit ist heute sehr hoch."}],"usage":"Abstrakter meteorologischer Messwert (Anteil Wasserdampf in der Luft); üblicherweise ohne Plural.","genus":"de"},"bk_2021":{"lemma":"zeespiegel","displayNl":"de zeespiegel","pos":"substantief","meanings":[{"de":"der Meeresspiegel (Bezugshöhe des Meeres)","ex":"De zeespiegel stijgt door de klimaatverandering.","exDe":"Der Meeresspiegel steigt durch den Klimawandel."},{"de":"die Meeresoberfläche","ex":"De maan weerspiegelde in de gladde zeespiegel.","exDe":"Der Mond spiegelte sich in der glatten Meeresoberfläche."}],"usage":"In den Niederlanden zentraler Begriff (NAP als Referenzhöhe); gebräuchlich in 'stijgende zeespiegel'.","genus":"de","plural":"zeespiegels","illustratable":true},"bk_2022":{"lemma":"kringloop","displayNl":"de kringloop","pos":"substantief","meanings":[{"de":"der Kreislauf (natürlicher/ökologischer Zyklus)","ex":"Water zit in een natuurlijke kringloop.","exDe":"Wasser befindet sich in einem natürlichen Kreislauf."},{"de":"der Secondhand-/Gebrauchtwarenladen (Kurzform von 'kringloopwinkel')","ex":"Die kast heb ik bij de kringloop gekocht.","exDe":"Diesen Schrank habe ich im Secondhandladen gekauft."}],"usage":"Grundbedeutung: geschlossener Zyklus (waterkringloop, kringloop van het leven). Umgangssprachlich verkürzt für 'kringloopwinkel' (Gebrauchtwarenladen).","genus":"de","plural":"kringlopen"},"bk_2024":{"lemma":"horizon","displayNl":"de horizon","pos":"substantief","meanings":[{"de":"der Horizont (Grenzlinie zwischen Himmel und Erde/Meer)","ex":"De zon zakt langzaam achter de horizon.","exDe":"Die Sonne sinkt langsam hinter den Horizont."},{"de":"der Horizont (übertragen: geistiger Blickwinkel, Zukunftsaussicht)","ex":"Reizen verbreedt je horizon.","exDe":"Reisen erweitert deinen Horizont."}],"usage":"Konkret (Sichtlinie) und übertragen (Wissens-/Zukunftshorizont); Plural 'horizonnen' selten, auch 'horizons'.","genus":"de","plural":"horizonnen","illustratable":true},"bk_2025":{"lemma":"schemering","displayNl":"de schemering","pos":"substantief","meanings":[{"de":"die Dämmerung (bes. Abenddämmerung, Zwielicht)","ex":"In de schemering wordt het buiten rustig.","exDe":"In der Dämmerung wird es draußen ruhig."},{"de":"das Halbdunkel / Zwielicht (in einem Raum)","ex":"We zaten in de schemering van de woonkamer.","exDe":"Wir saßen im Halbdunkel des Wohnzimmers."}],"usage":"Meist die Abenddämmerung, kann aber auch Morgendämmerung meinen; auch übertragen für gedämpftes Licht.","genus":"de","plural":"schemeringen","illustratable":true},"bk_2026":{"lemma":"dageraad","displayNl":"de dageraad","pos":"substantief","meanings":[{"de":"die Morgendämmerung / das Tagesanbruch","ex":"Bij dageraad worden de vogels wakker.","exDe":"Bei Tagesanbruch werden die Vögel wach."},{"de":"der Anbruch / Beginn (übertragen, z. B. einer neuen Ära)","ex":"Dit was de dageraad van een nieuw tijdperk.","exDe":"Dies war der Anbruch einer neuen Ära."}],"usage":"Gehobenes Wort für den ersten Tageslichtschein; übertragen für den Beginn von etwas Neuem. Ohne gebräuchlichen Plural.","genus":"de","illustratable":true},"bk_2027":{"lemma":"vruchtbaar","displayNl":"vruchtbaar","pos":"adjectief","meanings":[{"de":"fruchtbar (Boden, Land)","ex":"De grond in het dal is vruchtbaar.","exDe":"Der Boden im Tal ist fruchtbar."},{"de":"fruchtbar, ertragreich, produktiv (übertragen)","ex":"Het was een vruchtbaar gesprek.","exDe":"Es war ein fruchtbares Gespräch."},{"de":"fruchtbar, zeugungsfähig","ex":"Het paar bleek heel vruchtbaar.","exDe":"Das Paar erwies sich als sehr fruchtbar."}],"usage":"Adjektiv; sowohl wörtlich (Boden, Erde) als auch übertragen (Zusammenarbeit, Diskussion)."},"bk_2028":{"lemma":"vervuild","displayNl":"vervuild","pos":"adjectief","meanings":[{"de":"verschmutzt, verunreinigt","ex":"De rivier is helaas vervuild.","exDe":"Der Fluss ist leider verschmutzt."},{"de":"verschmutzt (Luft, Umwelt)","ex":"De lucht in de grote stad is vervuild.","exDe":"Die Luft in der Großstadt ist verschmutzt."}],"usage":"Partizip von 'vervuilen', wird meist als Adjektiv (Zustand) gebraucht."},"bk_2029":{"lemma":"wisselvallig","displayNl":"wisselvallig","pos":"adjectief","meanings":[{"de":"wechselhaft, unbeständig (Wetter)","ex":"Het weer is deze week wisselvallig.","exDe":"Das Wetter ist diese Woche wechselhaft."},{"de":"unbeständig, launisch (übertragen)","ex":"Zijn humeur is nogal wisselvallig.","exDe":"Seine Laune ist ziemlich unbeständig."}],"usage":"Typisches Wetter-Adjektiv; auch für Stimmungen/Ergebnisse."},"bk_2030":{"lemma":"guur","displayNl":"guur","pos":"adjectief","meanings":[{"de":"rau, ungemütlich, nasskalt (Wetter)","ex":"Het is buiten guur en koud.","exDe":"Draußen ist es rau und kalt."},{"de":"rau, unwirtlich (Wind, Klima)","ex":"Een gure noordenwind waait over het land.","exDe":"Ein rauer Nordwind weht über das Land."}],"usage":"Fast nur für Wetter/Wind: kalt, windig und feucht zugleich."},"bk_2031":{"lemma":"broeierig","displayNl":"broeierig","pos":"adjectief","meanings":[{"de":"schwül, drückend (Wetter)","ex":"Voor het onweer is het broeierig.","exDe":"Vor dem Gewitter ist es schwül."},{"de":"spannungsgeladen, brütend, aufgeheizt (Stimmung, übertragen)","ex":"Er hing een broeierige sfeer in de zaal.","exDe":"Es herrschte eine spannungsgeladene Stimmung im Saal."}],"usage":"Für schwüle Hitze vor dem Gewitter; übertragen für geladene Atmosphäre."},"bk_2032":{"lemma":"overstromen","displayNl":"overstromen","pos":"werkwoord","meanings":[{"de":"über die Ufer treten, überlaufen (intransitiv)","ex":"De rivier kan bij hevige regen overstromen.","exDe":"Der Fluss kann bei starkem Regen über die Ufer treten."},{"de":"überschwemmen, überfluten (transitiv)","ex":"Het water overstroomde de lager gelegen velden.","exDe":"Das Wasser überschwemmte die tiefer gelegenen Felder."},{"de":"überschwemmen, überhäufen (übertragen)","ex":"We worden overstroomd met aanvragen.","exDe":"Wir werden mit Anfragen überschwemmt."}],"usage":"Intransitiv trennbar (het water stroomt over, is overgestroomd); transitiv/übertragen untrennbar (overstroomt, overstroomd). Beispiel unten zeigt die trennbare Grundbedeutung.","illustratable":true},"bk_2033":{"lemma":"verwarmen","displayNl":"verwarmen","pos":"werkwoord","meanings":[{"de":"erwärmen, aufwärmen","ex":"De zon verwarmt het water in het meer.","exDe":"Die Sonne erwärmt das Wasser im See."},{"de":"heizen, beheizen","ex":"We verwarmen het huis met een warmtepomp.","exDe":"Wir heizen das Haus mit einer Wärmepumpe."}],"usage":"Untrennbares Verb (ver-): ik verwarm, verwarmde, heb verwarmd."},"bk_2034":{"lemma":"afkoelen","displayNl":"afkoelen","pos":"werkwoord","meanings":[{"de":"abkühlen, kühler werden (intransitiv)","ex":"'s Avonds koelt het snel af.","exDe":"Abends kühlt es schnell ab."},{"de":"abkühlen lassen, kühlen (transitiv)","ex":"Laat de soep even afkoelen.","exDe":"Lass die Suppe kurz abkühlen."},{"de":"abkühlen, sich abschwächen (übertragen, Gefühle/Beziehung)","ex":"Na de ruzie is hun relatie afgekoeld.","exDe":"Nach dem Streit ist ihre Beziehung abgekühlt."}],"usage":"Trennbar (af-): het koelt af, koelde af, is afgekoeld (intransitiv, zijn); transitiv mit 'hebben' möglich."},"bk_2035":{"lemma":"vervuilen","displayNl":"vervuilen","pos":"werkwoord","meanings":[{"de":"verschmutzen, verunreinigen","ex":"Fabrieken vervuilen soms het water.","exDe":"Fabriken verschmutzen manchmal das Wasser."},{"de":"verunreinigen, dreckig machen (allgemein)","ex":"Plastic afval vervuilt het strand.","exDe":"Plastikmüll verschmutzt den Strand."}],"usage":"Regelmäßiges Verb, Hilfsverb hebben. Beschreibt Verschmutzung von Umwelt (Wasser, Luft, Boden). Verwandt: de vervuiling = die Verschmutzung.","conjugation":{"presens":{"ik":"vervuil","jij":"vervuilt","hij":"vervuilt","wij":"vervuilen"},"imperfectum":{"ik":"vervuilde","wij":"vervuilden"},"perfectum":{"aux":"hebben","participle":"vervuild"}},"illustratable":true},"bk_2036":{"lemma":"verdampen","displayNl":"verdampen","pos":"werkwoord","meanings":[{"de":"verdampfen, verdunsten","ex":"Bij warmte verdampt het water snel.","exDe":"Bei Wärme verdampft das Wasser schnell."},{"de":"sich verflüchtigen, verschwinden (bildlich)","ex":"Al zijn goede voornemens verdampten in één dag.","exDe":"Alle seine guten Vorsätze verflüchtigten sich an einem Tag."}],"usage":"Regelmäßiges Verb. Beim Übergang eines Zustands (Flüssigkeit zu Dampf) Hilfsverb zijn: 'het water is verdampt'. Verwandt: de verdamping = die Verdunstung.","conjugation":{"presens":{"ik":"verdamp","jij":"verdampt","hij":"verdampt","wij":"verdampen"},"imperfectum":{"ik":"verdampte","wij":"verdampten"},"perfectum":{"aux":"zijn","participle":"verdampt"}},"illustratable":true},"bk_2037":{"lemma":"besparen","displayNl":"besparen","pos":"werkwoord","meanings":[{"de":"sparen, einsparen","ex":"We proberen energie te besparen.","exDe":"Wir versuchen, Energie zu sparen."},{"de":"ersparen (jemandem etwas)","ex":"Dat wil ik je besparen.","exDe":"Das möchte ich dir ersparen."}],"usage":"Regelmäßiges Verb, Hilfsverb hebben. 'energie/geld besparen' = Energie/Geld einsparen. 'iemand iets besparen' = jemandem etwas ersparen. Unterschied zu 'sparen' (Geld zurücklegen).","conjugation":{"presens":{"ik":"bespaar","jij":"bespaart","hij":"bespaart","wij":"besparen"},"imperfectum":{"ik":"bespaarde","wij":"bespaarden"},"perfectum":{"aux":"hebben","participle":"bespaard"}}},"bk_2038":{"lemma":"verandering","displayNl":"de verandering","pos":"substantief","meanings":[{"de":"die Veränderung, Wandel","ex":"De verandering van het klimaat is duidelijk.","exDe":"Die Veränderung des Klimas ist deutlich."},{"de":"die Änderung, Umstellung","ex":"Er komt een grote verandering in mijn leven.","exDe":"In meinem Leben kommt eine große Veränderung."}],"usage":"Abstraktes Substantiv, de-Wort. Zum Verb 'veranderen' = (sich) verändern. 'klimaatverandering' = Klimawandel.","genus":"de","plural":"veranderingen"},"bk_2039":{"lemma":"flamingo","displayNl":"de flamingo","pos":"substantief","meanings":[{"de":"der Flamingo","ex":"De flamingo is roze van kleur.","exDe":"Der Flamingo ist rosa."}],"usage":"de-Wort, Plural mit Apostroph: flamingo's. Rosafarbener Wasservogel, steht oft auf einem Bein.","genus":"de","plural":"flamingo's","illustratable":true},"bk_2040":{"lemma":"kameel","displayNl":"de kameel","pos":"substantief","meanings":[{"de":"das Kamel","ex":"De kameel kan lang zonder water.","exDe":"Das Kamel kann lange ohne Wasser."}],"usage":"de-Wort, Plural: kamelen. Wüstentier mit einem oder zwei Höckern.","genus":"de","plural":"kamelen","illustratable":true},"bk_2041":{"lemma":"neushoorn","displayNl":"de neushoorn","pos":"substantief","meanings":[{"de":"das Nashorn","ex":"De neushoorn heeft een dikke huid.","exDe":"Das Nashorn hat eine dicke Haut."}],"usage":"de-Wort, Plural: neushoorns. Wörtlich 'Nasenhorn'. Großes Säugetier mit einem oder zwei Hörnern auf der Nase.","genus":"de","plural":"neushoorns","illustratable":true},"bk_2042":{"lemma":"nijlpaard","displayNl":"het nijlpaard","pos":"substantief","meanings":[{"de":"das Nilpferd, Flusspferd","ex":"Het nijlpaard ligt graag in het water.","exDe":"Das Nilpferd liegt gern im Wasser."}],"usage":"het-Wort, Plural: nijlpaarden. Wörtlich 'Nilpferd'. Großes, plumpes Säugetier, das viel Zeit im Wasser verbringt.","genus":"het","plural":"nijlpaarden","illustratable":true},"bk_2043":{"lemma":"krokodil","displayNl":"de krokodil","pos":"substantief","meanings":[{"de":"das Krokodil","ex":"De krokodil wacht bij de rivier.","exDe":"Das Krokodil wartet am Fluss."}],"usage":"Reptil; auch bildlich für gefährliche Ruhe ('krokodillentranen' = Krokodilstränen).","genus":"de","plural":"krokodillen","illustratable":true},"bk_2044":{"lemma":"hagedis","displayNl":"de hagedis","pos":"substantief","meanings":[{"de":"die Eidechse","ex":"De hagedis ligt in de zon.","exDe":"Die Eidechse liegt in der Sonne."}],"usage":"Kleines Reptil.","genus":"de","plural":"hagedissen","illustratable":true},"bk_2045":{"lemma":"pad","displayNl":"de pad","pos":"substantief","meanings":[{"de":"die Kröte","ex":"De pad zit onder een steen.","exDe":"Die Kröte sitzt unter einem Stein."},{"de":"der Weg, der Pfad","ex":"We volgen het pad door het bos.","exDe":"Wir folgen dem Pfad durch den Wald."}],"usage":"Homonym: 'de pad' = die Kröte; 'het pad' = der Pfad/Weg. Genus unterscheidet die Bedeutungen.","genus":"de","plural":"padden","illustratable":true},"bk_2046":{"lemma":"das","displayNl":"de das","pos":"substantief","meanings":[{"de":"der Dachs","ex":"De das leeft onder de grond.","exDe":"Der Dachs lebt unter der Erde."},{"de":"der Schal, das Halstuch","ex":"Ze draagt een warme das om haar nek.","exDe":"Sie trägt einen warmen Schal um den Hals."},{"de":"die Krawatte","ex":"Hij doet een das om voor het feest.","exDe":"Er bindet sich für die Feier eine Krawatte um."}],"usage":"Homonym: das Tier (Dachs) sowie Kleidungsstück (Schal/Krawatte). Kontext entscheidet.","genus":"de","plural":"dassen","illustratable":true},"bk_2047":{"lemma":"everzwijn","displayNl":"het everzwijn","pos":"substantief","meanings":[{"de":"das Wildschwein","ex":"Het everzwijn zoekt eten in het bos.","exDe":"Das Wildschwein sucht Futter im Wald."}],"usage":"Wildtier; auch kurz 'zwijn' oder 'wild zwijn'.","genus":"het","plural":"everzwijnen","illustratable":true},"bk_2048":{"lemma":"ree","displayNl":"de ree","pos":"substantief","meanings":[{"de":"das Reh","ex":"De ree schrikt van het geluid.","exDe":"Das Reh erschrickt vor dem Geräusch."}],"usage":"Wildtier; männliches Tier = 'reebok', junges = 'reekalf'.","genus":"de","plural":"reeën","illustratable":true},"bk_2049":{"lemma":"haas","displayNl":"de haas","pos":"substantief","meanings":[{"de":"der Hase","ex":"De haas rent heel snel weg.","exDe":"Der Hase rennt sehr schnell weg."},{"de":"das Filet, die Lende (Fleisch)","ex":"We eten vanavond varkenshaas.","exDe":"Wir essen heute Abend Schweinefilet."}],"usage":"Tier; kulinarisch auch 'haas'/'varkenshaas' = Filet/Lende. Redewendung 'daar zit de haas' = da liegt der Hund begraben.","genus":"de","plural":"hazen","illustratable":true},"bk_2050":{"lemma":"bever","displayNl":"de bever","pos":"substantief","meanings":[{"de":"der Biber","ex":"De bever bouwt een dam in de rivier.","exDe":"Der Biber baut einen Damm im Fluss."}],"usage":"Nagetier; baut Dämme.","genus":"de","plural":"bevers","illustratable":true},"bk_2051":{"lemma":"otter","displayNl":"de otter","pos":"substantief","meanings":[{"de":"der Otter, der Fischotter","ex":"De otter zwemt langs de oever.","exDe":"Der Otter schwimmt am Ufer entlang."}],"usage":"Gängiges Wort für das semiaquatische Marderraubtier; oft 'otter' allein oder verstärkend 'visotter'.","genus":"de","plural":"otters","illustratable":true},"bk_2052":{"lemma":"spreeuw","displayNl":"de spreeuw","pos":"substantief","meanings":[{"de":"der Star (Vogel)","ex":"De spreeuw vliegt in een grote groep.","exDe":"Der Star fliegt in einer großen Gruppe."}],"usage":"Der bekannte Singvogel; große Schwärme heißen 'spreeuwenwolk'. Nicht mit 'ster' (Stern/Star-Person) verwechseln.","genus":"de","plural":"spreeuwen","illustratable":true},"bk_2053":{"lemma":"merel","displayNl":"de merel","pos":"substantief","meanings":[{"de":"die Amsel","ex":"De merel zingt vroeg in de ochtend.","exDe":"Die Amsel singt früh am Morgen."}],"usage":"Sehr verbreiteter Garten-Singvogel; das Männchen tiefschwarz mit orangegelbem Schnabel, das Weibchen braun.","genus":"de","plural":"merels","illustratable":true},"bk_2054":{"lemma":"mus","displayNl":"de mus","pos":"substantief","meanings":[{"de":"der Spatz, der Sperling","ex":"De mus zoekt kruimels op straat.","exDe":"Der Spatz sucht Krümel auf der Straße."}],"usage":"Kleiner, häufiger Stadtvogel (huismus = Haussperling); alltäglich und redensartlich ('beter een mus in de hand').","genus":"de","plural":"mussen","illustratable":true},"bk_2055":{"lemma":"specht","displayNl":"de specht","pos":"substantief","meanings":[{"de":"der Specht","ex":"De specht klopt op de boom.","exDe":"Der Specht klopft an den Baum."}],"usage":"Baumkletternder Vogel, der mit dem Schnabel gegen Stämme hämmert; oft 'bonte specht' (Buntspecht), 'groene specht'.","genus":"de","plural":"spechten","illustratable":true},"bk_2056":{"lemma":"reiger","displayNl":"de reiger","pos":"substantief","meanings":[{"de":"der Reiher","ex":"De reiger staat stil in het water.","exDe":"Der Reiher steht still im Wasser."}],"usage":"Großer Wasservogel; in NL besonders der 'blauwe reiger' (Graureiher), oft reglos an Grachten wartend.","genus":"de","plural":"reigers","illustratable":true},"bk_2057":{"lemma":"ooievaar","displayNl":"de ooievaar","pos":"substantief","meanings":[{"de":"der Storch","ex":"De ooievaar bouwt zijn nest op het dak.","exDe":"Der Storch baut sein Nest auf dem Dach."}],"usage":"Großer Zugvogel mit rotem Schnabel; kulturelles Symbol für Geburt/Babys. Plural auch 'ooievaren'.","genus":"de","plural":"ooievaars","notes":"Plural gebräuchlich 'ooievaars', formeller auch 'ooievaren'.","illustratable":true},"bk_2058":{"lemma":"adelaar","displayNl":"de adelaar","pos":"substantief","meanings":[{"de":"der Adler","ex":"De adelaar vliegt hoog in de lucht.","exDe":"Der Adler fliegt hoch am Himmel."},{"de":"der Adler (als Wappen-/Symboltier)","ex":"De adelaar staat als symbool op het wapen.","exDe":"Der Adler steht als Symbol auf dem Wappen."}],"usage":"Großer Greifvogel; auch häufiges Wappen-/Symboltier. Plural auch 'adelaren'.","genus":"de","plural":"adelaars","notes":"Plural gebräuchlich 'adelaars', formeller auch 'adelaren'.","illustratable":true},"bk_2059":{"lemma":"valk","displayNl":"de valk","pos":"substantief","meanings":[{"de":"der Falke (Greifvogel)","ex":"De valk jaagt op kleine vogels.","exDe":"Der Falke jagt kleine Vögel."},{"de":"der Falkner-Vogel / abgerichteter Beizvogel","ex":"De valkenier laat zijn valk vliegen.","exDe":"Der Falkner lässt seinen Falken fliegen."}],"usage":"Greifvogel der Familie der Falken; ook figuurlijk voor iemand met scherpe blik ('havik of valk' in de politiek).","genus":"de","plural":"valken","illustratable":true},"bk_2060":{"lemma":"kwal","displayNl":"de kwal","pos":"substantief","meanings":[{"de":"die Qualle (Meerestier)","ex":"In de zee drijft een kwal.","exDe":"Im Meer treibt eine Qualle."},{"de":"(umgangssprachlich, abwertend) unangenehmer Mensch, Ekel","ex":"Wat een kwal is die vent.","exDe":"Was für ein widerlicher Kerl das ist."}],"usage":"Nesseltier; umgangssprachlich als Schimpfwort für einen unsympathischen Menschen.","genus":"de","plural":"kwallen","illustratable":true},"bk_2061":{"lemma":"inktvis","displayNl":"de inktvis","pos":"substantief","meanings":[{"de":"der Tintenfisch / Kalmar / Krake (Kopffüßer)","ex":"De inktvis heeft veel armen.","exDe":"Der Tintenfisch hat viele Arme."},{"de":"Tintenfisch als Speise (Calamari)","ex":"We aten gebakken inktvis in het restaurant.","exDe":"Wir aßen gebratenen Tintenfisch im Restaurant."}],"usage":"Sammelbegriff für Kopffüßer (octopus, inktvis, pijlinktvis); ook culinair als gerecht.","genus":"de","plural":"inktvissen","illustratable":true},"bk_2062":{"lemma":"garnaal","displayNl":"de garnaal","pos":"substantief","meanings":[{"de":"die Garnele / Krabbe (Krebstier)","ex":"De garnaal is klein en roze.","exDe":"Die Garnele ist klein und rosa."},{"de":"Garnele als Speise (Hollandse garnalen)","ex":"Ik hou van broodjes met verse garnalen.","exDe":"Ich mag Brötchen mit frischen Garnelen."}],"usage":"Klein Krebsdier; in Nederland vooral de grijze 'Hollandse garnaal' als delicatesse.","genus":"de","plural":"garnalen","illustratable":true},"bk_2063":{"lemma":"zeester","displayNl":"de zeester","pos":"substantief","meanings":[{"de":"der Seestern (Stachelhäuter)","ex":"De zeester ligt op het strand.","exDe":"Der Seestern liegt am Strand."}],"usage":"Stekelhuidig zeedier met meestal vijf armen, vaak in getijdenpoelen.","genus":"de","plural":"zeesterren","illustratable":true},"bk_2064":{"lemma":"mossel","displayNl":"de mossel","pos":"substantief","meanings":[{"de":"die Muschel / Miesmuschel (Meerestier)","ex":"De mossel zit op een steen.","exDe":"Die Muschel sitzt auf einem Stein."},{"de":"Muscheln als Speise (Zeeuwse mosselen)","ex":"In de herfst eten we mosselen met friet.","exDe":"Im Herbst essen wir Muscheln mit Pommes."}],"usage":"Tweekleppig weekdier; 'mosselen met friet' is een populair Nederlands/Belgisch gerecht.","genus":"de","plural":"mosselen","illustratable":true},"bk_2065":{"lemma":"sprinkhaan","displayNl":"de sprinkhaan","pos":"substantief","meanings":[{"de":"die Heuschrecke / der Grashüpfer (Insekt)","ex":"De sprinkhaan springt ver weg.","exDe":"Die Heuschrecke springt weit weg."}],"usage":"Springend insect met lange achterpoten, veelal groen, in graslanden.","genus":"de","plural":"sprinkhanen","illustratable":true},"bk_2066":{"lemma":"libel","displayNl":"de libel","pos":"substantief","meanings":[{"de":"die Libelle (Insekt)","ex":"De libel vliegt boven het water.","exDe":"Die Libelle fliegt über dem Wasser."}],"usage":"Slank vliegend insect met twee paar doorzichtige vleugels, vaak bij water.","genus":"de","plural":"libellen","illustratable":true},"bk_2067":{"lemma":"rups","displayNl":"de rups","pos":"substantief","meanings":[{"de":"die Raupe","ex":"De rups wordt later een vlinder.","exDe":"Die Raupe wird später ein Schmetterling."}],"usage":"Larvenstadium von Schmetterlingen und Motten; wird zum Verpuppen benutzt.","genus":"de","plural":"rupsen","illustratable":true},"bk_2068":{"lemma":"teek","displayNl":"de teek","pos":"substantief","meanings":[{"de":"die Zecke","ex":"Pas op voor een teek in het bos.","exDe":"Pass auf eine Zecke im Wald auf."}],"usage":"Blutsaugendes Spinnentier; Warnung vor Zecken im Wald und hohen Gras.","genus":"de","plural":"teken","illustratable":true},"bk_2069":{"lemma":"lieveheersbeestje","displayNl":"het lieveheersbeestje","pos":"substantief","meanings":[{"de":"der Marienkäfer","ex":"Het lieveheersbeestje heeft rode vleugels.","exDe":"Der Marienkäfer hat rote Flügel."}],"usage":"Kleiner roter Käfer mit schwarzen Punkten; gilt als Glücksbringer.","genus":"het","plural":"lieveheersbeestjes","illustratable":true},"bk_2070":{"lemma":"berk","displayNl":"de berk","pos":"substantief","meanings":[{"de":"die Birke","ex":"De berk heeft een witte stam.","exDe":"Die Birke hat einen weißen Stamm."}],"usage":"Laubbaum mit charakteristisch weißer, schwarz gefleckter Rinde.","genus":"de","plural":"berken","illustratable":true},"bk_2071":{"lemma":"beuk","displayNl":"de beuk","pos":"substantief","meanings":[{"de":"die Buche","ex":"De beuk staat midden in het bos.","exDe":"Die Buche steht mitten im Wald."}],"usage":"Großer Laubbaum mit glatter grauer Rinde und dichter Krone.","genus":"de","plural":"beuken","illustratable":true},"bk_2072":{"lemma":"wilg","displayNl":"de wilg","pos":"substantief","meanings":[{"de":"die Weide (Baum)","ex":"De wilg staat langs het water.","exDe":"Die Weide steht am Wasser."}],"usage":"Baum mit langen, schmalen Blättern, wächst gern am Wasser; oft als Kopfweide.","genus":"de","plural":"wilgen","illustratable":true},"bk_2073":{"lemma":"spar","displayNl":"de spar","pos":"substantief","meanings":[{"de":"die Fichte","ex":"Met kerst zetten wij een spar neer.","exDe":"Zu Weihnachten stellen wir eine Fichte auf."},{"de":"der Nadelbaum (allgemein, Tannenbaum)","ex":"In het bos groeien veel sparren.","exDe":"Im Wald wachsen viele Fichten."}],"usage":"Immergrüner Nadelbaum mit kegelförmiger Krone; oft als Weihnachtsbaum.","genus":"de","plural":"sparren","illustratable":true},"bk_2074":{"lemma":"esdoorn","displayNl":"de esdoorn","pos":"substantief","meanings":[{"de":"der Ahorn","ex":"De esdoorn heeft mooie bladeren.","exDe":"Der Ahorn hat schöne Blätter."}],"usage":"Laubbaum mit charakteristischen handförmig gelappten Blättern; im Herbst rot-orange.","genus":"de","plural":"esdoorns","illustratable":true},"bk_2075":{"lemma":"klimop","displayNl":"de klimop","pos":"substantief","meanings":[{"de":"der Efeu","ex":"De klimop groeit tegen de muur.","exDe":"Der Efeu wächst an der Wand."}],"usage":"Klimmpflanze; meist unzählbar, kaum im Plural gebräuchlich.","genus":"de","illustratable":true},"bk_2076":{"lemma":"mos","displayNl":"het mos","pos":"substantief","meanings":[{"de":"das Moos","ex":"Op de steen groeit groen mos.","exDe":"Auf dem Stein wächst grünes Moos."}],"usage":"Meist unzählbar; Plural 'mossen' nur für Moosarten.","genus":"het","plural":"mossen","illustratable":true},"bk_2077":{"lemma":"varen","displayNl":"de varen","pos":"substantief","meanings":[{"de":"der Farn","ex":"In het bos staan veel varens.","exDe":"Im Wald stehen viele Farne."}],"usage":"Substantief 'de varen' (Pflanze) nicht mit dem Verb 'varen' (fahren) verwechseln.","genus":"de","plural":"varens","illustratable":true},"bk_2078":{"lemma":"paddenstoel","displayNl":"de paddenstoel","pos":"substantief","meanings":[{"de":"der Pilz","ex":"Onder de boom groeit een paddenstoel.","exDe":"Unter dem Baum wächst ein Pilz."},{"de":"der Giftpilz / Fliegenpilz (typische Bilderbuchform)","ex":"De rode paddenstoel met witte stippen is giftig.","exDe":"Der rote Pilz mit weißen Punkten ist giftig."}],"usage":"'Paddenstoel' meint bes. den oberirdischen Fruchtkörper; Speisepilz oft 'champignon'.","genus":"de","plural":"paddenstoelen","illustratable":true},"bk_2079":{"lemma":"riet","displayNl":"het riet","pos":"substantief","meanings":[{"de":"das Schilf / das Reet","ex":"Langs de sloot groeit riet.","exDe":"Am Graben wächst Schilf."},{"de":"das Rohr (Material für Reetdächer, Rohrblätter)","ex":"Het dak is bedekt met riet.","exDe":"Das Dach ist mit Reet gedeckt."}],"usage":"Meist unzählbar (Sammelbegriff); als Dachmaterial 'rieten dak'.","genus":"het","illustratable":true},"bk_2080":{"lemma":"distel","displayNl":"de distel","pos":"substantief","meanings":[{"de":"die Distel","ex":"De distel heeft scherpe stekels.","exDe":"Die Distel hat scharfe Stacheln."}],"usage":"Plural 'distels'.","genus":"de","plural":"distels","illustratable":true},"bk_2081":{"lemma":"brandnetel","displayNl":"de brandnetel","pos":"substantief","meanings":[{"de":"die Brennnessel","ex":"Pas op, de brandnetel prikt.","exDe":"Vorsicht, die Brennnessel brennt."}],"usage":"Plural 'brandnetels'; die Pflanze 'prikt' (brennt) bei Berührung.","genus":"de","plural":"brandnetels","illustratable":true},"bk_2082":{"lemma":"klaver","displayNl":"de klaver","pos":"substantief","meanings":[{"de":"der Klee (Pflanze)","ex":"In de wei groeit veel klaver.","exDe":"Auf der Weide wächst viel Klee."},{"de":"Kreuz (Spielkartenfarbe; meist 'klaveren')","ex":"Hij speelde de klaveren aas uit.","exDe":"Er spielte das Kreuz-Ass aus."}],"usage":"Als Pflanze meist unzählbar; die Kartenfarbe heißt 'klaveren'.","genus":"de","plural":"klavers","illustratable":true},"bk_2083":{"lemma":"knop","displayNl":"de knop","pos":"substantief","meanings":[{"de":"die Knospe","ex":"Aan de tak zit een kleine knop die bijna openbarst.","exDe":"Am Zweig sitzt eine kleine Knospe, die fast aufplatzt."},{"de":"der Knopf, der Schalter (zum Drücken)","ex":"Druk op de rode knop om te starten.","exDe":"Drücke auf den roten Knopf, um zu starten."},{"de":"der Knopf (am Kleidungsstück)","ex":"Er zit een knop los aan mijn jas.","exDe":"An meiner Jacke ist ein Knopf lose."}],"usage":"Homonym: botanisch die Knospe, technisch der Druckknopf/Schalter und der Kleidungsknopf; Plural stets 'knoppen'.","genus":"de","plural":"knoppen","illustratable":true},"bk_2084":{"lemma":"bloembol","displayNl":"de bloembol","pos":"substantief","meanings":[{"de":"die Blumenzwiebel","ex":"Ik plant een bloembol in de herfst, zodat hij in het voorjaar bloeit.","exDe":"Ich pflanze eine Blumenzwiebel im Herbst, damit sie im Frühjahr blüht."}],"usage":"Zusammensetzung bloem + bol; typisch niederländisch (Tulpen), Plural 'bloembollen'.","genus":"de","plural":"bloembollen","illustratable":true},"bk_2085":{"lemma":"steel","displayNl":"de steel","pos":"substantief","meanings":[{"de":"der Stiel, der Stängel (einer Pflanze)","ex":"De bloem heeft een lange, groene steel.","exDe":"Die Blume hat einen langen, grünen Stiel."},{"de":"der Stiel, der Griff (eines Werkzeugs, z. B. Besen, Pfanne)","ex":"De steel van de bezem is gebroken.","exDe":"Der Stiel des Besens ist gebrochen."}],"usage":"Botanisch der Blütenstängel, im Alltag auch der Griff eines Werkzeugs; Plural 'stelen'.","genus":"de","plural":"stelen","illustratable":true},"bk_2086":{"lemma":"blaadje","displayNl":"het blaadje","pos":"substantief","meanings":[{"de":"das Blütenblatt, das kleine Blatt","ex":"Er valt een blaadje van de roos op de tafel.","exDe":"Ein Blütenblatt fällt von der Rose auf den Tisch."},{"de":"das Blättchen, das kleine Blatt Papier","ex":"Ze schreef een berichtje op een blaadje.","exDe":"Sie schrieb eine kurze Nachricht auf ein Blättchen."}],"usage":"Diminutiv von 'blad'; bezeichnet ein kleines Pflanzenblatt/Blütenblatt oder ein kleines Blatt Papier; Plural 'blaadjes'.","genus":"het","plural":"blaadjes","illustratable":true},"bk_2087":{"lemma":"doorn","displayNl":"de doorn","pos":"substantief","meanings":[{"de":"der Dorn, der Stachel","ex":"De roos heeft scherpe doornen aan de steel.","exDe":"Die Rose hat scharfe Dornen am Stiel."}],"usage":"Spitzer Auswuchs an Pflanzen (Rose, Brombeere); Plural 'doornen' (auch 'dorens'). Redewendung: 'een doorn in het oog'.","genus":"de","plural":"doornen","illustratable":true},"bk_2088":{"lemma":"schors","displayNl":"de schors","pos":"substantief","meanings":[{"de":"die Rinde, die Borke","ex":"De schors van de oude eik is ruw en gebarsten.","exDe":"Die Rinde der alten Eiche ist rau und rissig."}],"usage":"Äußere Schicht eines Baumstamms; Plural 'schorsen' selten. Nicht verwechseln mit 'schort' (Schürze).","genus":"de","plural":"schorsen","illustratable":true},"bk_2089":{"lemma":"tak","displayNl":"de tak","pos":"substantief","meanings":[{"de":"der Zweig, der Ast","ex":"De takken bewegen zachtjes in de wind.","exDe":"Die Zweige bewegen sich sanft im Wind."},{"de":"der Zweig, der Bereich (übertragen, z. B. Wirtschaftszweig)","ex":"Hij werkt in een specialistische tak van de industrie.","exDe":"Er arbeitet in einem spezialisierten Zweig der Industrie."}],"usage":"Eingabe war Plural 'takken' → Grundform Singular 'tak'; Plural 'takken'. Übertragen auch Branche/Zweig.","genus":"de","plural":"takken","illustratable":true},"bk_2090":{"lemma":"prooi","displayNl":"de prooi","pos":"substantief","meanings":[{"de":"die Beute (eines Jägers/Raubtiers)","ex":"De vos besluipt zijn prooi in het hoge gras.","exDe":"Der Fuchs beschleicht seine Beute im hohen Gras."},{"de":"das Opfer (übertragen, jemandem/etwas ausgeliefert sein)","ex":"Hij werd een gemakkelijke prooi voor oplichters.","exDe":"Er wurde eine leichte Beute für Betrüger."}],"usage":"Das erbeutete/gejagte Tier; übertragen 'ten prooi vallen aan' (jemandem/etwas zum Opfer fallen). Plural 'prooien'.","genus":"de","plural":"prooien","illustratable":true},"bk_2091":{"lemma":"roofdier","displayNl":"het roofdier","pos":"substantief","meanings":[{"de":"das Raubtier","ex":"De leeuw is een gevaarlijk roofdier.","exDe":"Der Löwe ist ein gefährliches Raubtier."},{"de":"der Räuber (Tier, das andere Tiere jagt)","ex":"De vos is een sluw roofdier in het bos.","exDe":"Der Fuchs ist ein schlauer Räuber im Wald."}],"usage":"Gängiger Sammelbegriff für fleischfressende, jagende Tiere; Betonung auf 'roof-'.","genus":"het","plural":"roofdieren","illustratable":true},"bk_2092":{"lemma":"zoogdier","displayNl":"het zoogdier","pos":"substantief","meanings":[{"de":"das Säugetier","ex":"De walvis is een groot zoogdier.","exDe":"Der Wal ist ein großes Säugetier."}],"usage":"Biologischer Oberbegriff; 'zoog-' von 'zogen' (säugen).","genus":"het","plural":"zoogdieren","illustratable":true},"bk_2093":{"lemma":"insect","displayNl":"het insect","pos":"substantief","meanings":[{"de":"das Insekt","ex":"Een bij is een nuttig insect.","exDe":"Eine Biene ist ein nützliches Insekt."},{"de":"das Ungeziefer / Krabbeltier (umgangssprachlich für kleines lästiges Insekt)","ex":"Er zit een insect op mijn arm.","exDe":"Da sitzt ein Insekt auf meinem Arm."}],"usage":"Neutraler Oberbegriff für Kerbtiere; Betonung auf zweiter Silbe.","genus":"het","plural":"insecten","illustratable":true},"bk_2094":{"lemma":"gewei","displayNl":"het gewei","pos":"substantief","meanings":[{"de":"das Geweih","ex":"Het hert heeft een groot gewei.","exDe":"Der Hirsch hat ein großes Geweih."}],"usage":"Bezeichnet nur das knöcherne Geweih von Hirschartigen (nicht Hörner).","genus":"het","plural":"geweien","illustratable":true},"bk_2095":{"lemma":"snor","displayNl":"de snor","pos":"substantief","meanings":[{"de":"der Schnurrbart (des Menschen)","ex":"Mijn opa heeft een grote grijze snor.","exDe":"Mein Opa hat einen großen grauen Schnurrbart."},{"de":"die Schnurrhaare / Tasthaare (eines Tieres, oft 'snorharen')","ex":"De kat heeft lange snorharen.","exDe":"Die Katze hat lange Schnurrhaare."}],"usage":"Primär der menschliche Schnurrbart; für Tiere meist 'snorharen'. Redewendung: 'iets in de snor spelen' = etwas ergaunern.","genus":"de","plural":"snorren","illustratable":true},"bk_2096":{"lemma":"kieuw","displayNl":"de kieuw","pos":"substantief","meanings":[{"de":"die Kieme","ex":"De vis ademt met zijn kieuwen.","exDe":"Der Fisch atmet mit seinen Kiemen."}],"usage":"Meist im Plural 'kieuwen'; Atmungsorgan von Fischen und Amphibienlarven.","genus":"de","plural":"kieuwen","illustratable":true},"bk_2097":{"lemma":"schub","displayNl":"de schub","pos":"substantief","meanings":[{"de":"die Schuppe (von Fisch, Reptil)","ex":"De vis heeft glimmende schubben.","exDe":"Der Fisch hat glänzende Schuppen."}],"usage":"Meist im Plural 'schubben'; bei Fischen, Schlangen, Reptilien. Nicht Hautschuppen des Menschen (das ist 'roos'/'huidschilfers').","genus":"de","plural":"schubben","illustratable":true},"bk_2098":{"lemma":"hoef","displayNl":"de hoef","pos":"substantief","meanings":[{"de":"der Huf","ex":"Het paard heeft harde hoeven.","exDe":"Das Pferd hat harte Hufe."}],"usage":"Bei Pferden, Rindern u. a. Huftieren; Plural 'hoeven'. Nicht zu verwechseln mit 'hof' (Hof).","genus":"de","plural":"hoeven","illustratable":true},"bk_2099":{"lemma":"manen","displayNl":"de manen","pos":"substantief","meanings":[{"de":"die Mähne","ex":"De leeuw schudt zijn dichte manen.","exDe":"Der Löwe schüttelt seine dichte Mähne."},{"de":"die Monde (Plural von 'maan')","ex":"De planeet Jupiter heeft veel manen.","exDe":"Der Planet Jupiter hat viele Monde."}],"usage":"'Manen' im Sinne von Mähne wird nur im Plural gebraucht (plurale tantum); daneben ist 'manen' auch der Plural von 'de maan' (der Mond).","genus":"de","plural":"manen","illustratable":true},"bk_2100":{"lemma":"winterslaap","displayNl":"de winterslaap","pos":"substantief","meanings":[{"de":"der Winterschlaf","ex":"De egel houdt een lange winterslaap in het bladafval.","exDe":"Der Igel hält einen langen Winterschlaf im Laub."},{"de":"die Winterruhe (übertragen: Phase der Untätigkeit)","ex":"Na Kerst ligt het dorp in een soort winterslaap.","exDe":"Nach Weihnachten liegt das Dorf in einer Art Winterruhe."}],"usage":"Feste Wendung 'een winterslaap houden' = Winterschlaf halten.","genus":"de","plural":"winterslapen","illustratable":true},"bk_2101":{"lemma":"trekvogel","displayNl":"de trekvogel","pos":"substantief","meanings":[{"de":"der Zugvogel","ex":"In de herfst vliegen de trekvogels in grote zwermen naar het zuiden.","exDe":"Im Herbst fliegen die Zugvögel in großen Schwärmen nach Süden."}],"usage":"","genus":"de","plural":"trekvogels","illustratable":true},"bk_2102":{"lemma":"zelden","displayNl":"zelden","pos":"bijwoord","meanings":[{"de":"selten","ex":"Hij komt zelden te laat op zijn werk.","exDe":"Er kommt selten zu spät zur Arbeit."},{"de":"kaum, nur ausnahmsweise","ex":"Zo'n mooie zonsondergang zie je zelden.","exDe":"Einen so schönen Sonnenuntergang sieht man selten."}],"usage":"Häufigkeitsadverb; oft am Satzanfang mit Inversion: 'Zelden zie ik hem.'"},"bk_2103":{"lemma":"af en toe","displayNl":"af en toe","pos":"uitdrukking","meanings":[{"de":"ab und zu, gelegentlich","ex":"Af en toe eet ik nog een stukje vlees.","exDe":"Ab und zu esse ich noch ein Stückchen Fleisch."},{"de":"hin und wieder, von Zeit zu Zeit","ex":"We zien elkaar af en toe in de stad.","exDe":"Wir sehen uns hin und wieder in der Stadt."}],"usage":"Feste adverbiale Wendung; steht meist am Satzanfang (mit Inversion) oder im Mittelfeld."},"bk_2104":{"lemma":"vaak genoeg","displayNl":"vaak genoeg","pos":"uitdrukking","meanings":[{"de":"oft genug","ex":"Ik heb het je nu vaak genoeg gezegd.","exDe":"Ich habe es dir jetzt oft genug gesagt."},{"de":"häufig genug (ausreichend häufig)","ex":"Deze bus rijdt vaak genoeg voor mij.","exDe":"Dieser Bus fährt oft genug für mich."}],"usage":"Kombination aus dem Häufigkeitsadverb 'vaak' und dem Gradpartikel 'genoeg'; 'genoeg' folgt dem Bezugswort."},"bk_2105":{"lemma":"ondertussen","displayNl":"ondertussen","pos":"bijwoord","meanings":[{"de":"inzwischen, unterdessen","ex":"Ondertussen kook ik alvast het eten.","exDe":"Inzwischen koche ich schon mal das Essen."},{"de":"mittlerweile (im Verlauf der Zeit)","ex":"Hij woont hier ondertussen al tien jaar.","exDe":"Er wohnt mittlerweile schon zehn Jahre hier."}],"usage":"Zeitadverb; oft am Satzanfang mit Inversion. Umgangssprachlich auch 'nebenbei, gleichzeitig'."},"bk_2106":{"lemma":"tegenwoordig","displayNl":"tegenwoordig","pos":"bijwoord","meanings":[{"de":"heutzutage, heute (im Gegensatz zu früher)","ex":"Tegenwoordig werk ik meestal online van huis.","exDe":"Heutzutage arbeite ich meistens online von zu Hause."},{"de":"gegenwärtig, jetzig (als Adjektiv)","ex":"De tegenwoordige tijd van 'lopen' is 'ik loop'.","exDe":"Die Gegenwartsform von 'lopen' ist 'ik loop'."}],"usage":"Als Adverb 'heutzutage'; als attributives Adjektiv 'gegenwärtig, jetzig' (z. B. 'de tegenwoordige tijd' = das Präsens)."},"bk_2107":{"lemma":"onlangs","displayNl":"onlangs","pos":"bijwoord","meanings":[{"de":"kürzlich","ex":"Ik zag hem onlangs nog op straat.","exDe":"Ich habe ihn kürzlich noch auf der Straße gesehen."},{"de":"neulich / vor kurzem","ex":"Onlangs las ik een interessant boek.","exDe":"Neulich habe ich ein interessantes Buch gelesen."}],"usage":"Temporaladverb für einen kurz zurückliegenden Zeitpunkt; steht meist mit einer Vergangenheitsform. Synonym: kortgeleden.","notes":"Bezieht sich immer auf die Vergangenheit (nicht auf die Zukunft)."},"bk_2108":{"lemma":"binnenkort","displayNl":"binnenkort","pos":"bijwoord","meanings":[{"de":"bald / in Kürze","ex":"We verhuizen binnenkort naar Utrecht.","exDe":"Wir ziehen bald nach Utrecht um."},{"de":"demnächst","ex":"De nieuwe film komt binnenkort uit.","exDe":"Der neue Film kommt demnächst heraus."}],"usage":"Temporaladverb für die nahe Zukunft; steht meist mit Präsens (das im Niederländischen Zukünftiges ausdrückt). Synonym: spoedig, gauw.","notes":"Gegenstück zu 'onlangs' (Vergangenheit)."},"bk_2109":{"lemma":"voortaan","displayNl":"voortaan","pos":"bijwoord","meanings":[{"de":"künftig / von nun an","ex":"Voortaan kom ik altijd op tijd.","exDe":"Von nun an komme ich immer pünktlich."},{"de":"fortan","ex":"Voortaan doen we het anders.","exDe":"Fortan machen wir es anders."}],"usage":"Adverb, das eine ab jetzt geltende, dauerhafte Änderung markiert; oft am Satzanfang. Synonym: van nu af aan."},"bk_2110":{"lemma":"middernacht","displayNl":"de middernacht","pos":"substantief","meanings":[{"de":"Mitternacht (24:00 Uhr)","ex":"Om middernacht sla de klok twaalf keer.","exDe":"Um Mitternacht schlägt die Uhr zwölf Mal."},{"de":"tiefe Nacht","ex":"Ver na middernacht was ze nog wakker.","exDe":"Weit nach Mitternacht war sie noch wach."}],"usage":"Zeitpunkt-Substantiv; fast immer in der festen Wendung 'om middernacht'. Plural sehr selten.","genus":"de","plural":"middernachten","notes":"Korrektes Genus ist 'de middernacht' (Eingabe 'het' ist falsch).","illustratable":true},"bk_2111":{"lemma":"middaguur","displayNl":"het middaguur","pos":"substantief","meanings":[{"de":"Mittag / Mittagsstunde (12 Uhr)","ex":"We ontmoeten elkaar rond het middaguur.","exDe":"Wir treffen uns gegen Mittag."},{"de":"Hochmittag","ex":"Op het middaguur staat de zon het hoogst.","exDe":"Am Hochmittag steht die Sonne am höchsten."}],"usage":"Gehobenes Substantiv für die Zeit um 12 Uhr mittags; oft 'rond/op het middaguur'. Alltagssprachlicher: 'de middag', 'twaalf uur'.","genus":"het","plural":"middaguren","notes":"'uur' ist het-Wort, daher 'het middaguur'.","illustratable":true},"bk_2113":{"lemma":"decennium","displayNl":"het decennium","pos":"substantief","meanings":[{"de":"Jahrzehnt (zehn Jahre)","ex":"Een decennium is tien jaar.","exDe":"Ein Jahrzehnt sind zehn Jahre."},{"de":"Dekade","ex":"In het afgelopen decennium veranderde er veel.","exDe":"Im vergangenen Jahrzehnt hat sich viel verändert."}],"usage":"Formelles Substantiv (lateinischen Ursprungs); Plural 'decennia'. Umgangssprachlich oft 'tien jaar'.","genus":"het","plural":"decennia","notes":"Plural 'decennia' (auch 'decenniën'), nicht 'decenniums'."},"bk_2115":{"lemma":"toekomst","displayNl":"de toekomst","pos":"substantief","meanings":[{"de":"Zukunft","ex":"In de toekomst wil ik veel reizen.","exDe":"In der Zukunft möchte ich viel reisen."},{"de":"Perspektive / Aussichten","ex":"Dat is een baan met toekomst.","exDe":"Das ist ein Job mit Zukunft."}],"usage":"Abstraktes Substantiv, meist im Singular; feste Wendung 'in de toekomst'. Gegenstück zu 'het verleden'.","genus":"de","notes":"Plural 'toekomsten' existiert, ist aber selten."},"bk_2116":{"lemma":"verleden","displayNl":"het verleden","pos":"substantief","meanings":[{"de":"Vergangenheit","ex":"Denk niet te veel aan het verleden.","exDe":"Denk nicht zu viel an die Vergangenheit."},{"de":"Vorgeschichte (einer Person)","ex":"Hij heeft een bewogen verleden.","exDe":"Er hat eine bewegte Vergangenheit."}],"usage":"Abstraktes Substantiv, meist Singular mit Artikel 'het'. Als Adjektiv bedeutet 'verleden' auch 'vergangen/letzt' (z. B. 'verleden week' = letzte Woche).","genus":"het","notes":"Gegenstück zu 'de toekomst'; Plural kaum gebräuchlich."},"bk_2117":{"lemma":"heden","displayNl":"het heden","pos":"substantief","meanings":[{"de":"die Gegenwart","ex":"Leef in het heden en niet in het verleden.","exDe":"Lebe in der Gegenwart und nicht in der Vergangenheit."}],"usage":"Abstraktes Substantiv (het), meist ohne Plural; bezeichnet die gegenwaertige Zeit. Gegensatz: het verleden (Vergangenheit), de toekomst (Zukunft). 'heden' existiert auch als gehobenes Adverb = 'heute'.","genus":"het"},"bk_2118":{"lemma":"aantal","displayNl":"het aantal","pos":"substantief","meanings":[{"de":"die Anzahl, die Zahl","ex":"Het aantal gasten is dit jaar groot.","exDe":"Die Anzahl der Gaeste ist dieses Jahr gross."}],"usage":"het aantal + Substantiv im Plural; das Verb steht meist im Singular ('het aantal is'). 'een aantal' = 'einige/eine Reihe von'.","genus":"het","plural":"aantallen"},"bk_2119":{"lemma":"rest","displayNl":"de rest","pos":"substantief","meanings":[{"de":"der Rest, der uebrige Teil","ex":"De rest van het geld komt later.","exDe":"Der Rest des Geldes kommt spaeter."},{"de":"die Uebrigen, die restlichen Personen","ex":"De rest van de groep wacht buiten.","exDe":"Der Rest der Gruppe wartet draußen."},{"de":"der Ueberrest, das Ueberbleibsel (Plural: resten)","ex":"Er lagen nog resten van het oude kasteel.","exDe":"Es lagen noch Ueberreste des alten Schlosses da."}],"usage":"de rest = der verbleibende Teil (Singular). Der Plural 'resten' meint konkrete Ueberreste/Reste.","genus":"de","plural":"resten"},"bk_2120":{"lemma":"hoeveelheid","displayNl":"de hoeveelheid","pos":"substantief","meanings":[{"de":"die Menge, die Quantitaet","ex":"Een grote hoeveelheid water stroomde weg.","exDe":"Eine grosse Menge Wasser floss weg."}],"usage":"de hoeveelheid (Endung -heid ist immer de). Bezeichnet Quantitaet, oft mit unzaehlbaren Stoffen; Gegensatzpaar mit 'kwaliteit' (Qualitaet).","genus":"de","plural":"hoeveelheden"},"bk_2121":{"lemma":"dozijn","displayNl":"het dozijn","pos":"substantief","meanings":[{"de":"das Dutzend (zwoelf Stück)","ex":"Ik koop een dozijn eieren op de markt.","exDe":"Ich kaufe ein Dutzend Eier auf dem Markt."}],"usage":"KORREKTUR: 'het dozijn' (Neutrum), nicht 'de'. Nach Zahlwort oft ohne -en: 'twee dozijn'. Bedeutet zwoelf Stück.","genus":"het","plural":"dozijnen"},"bk_2122":{"lemma":"pond","displayNl":"het pond","pos":"substantief","meanings":[{"de":"das Pfund (Gewicht, 500 Gramm)","ex":"Een pond is vijfhonderd gram.","exDe":"Ein Pfund sind fuenfhundert Gramm."},{"de":"das Pfund (Waehrung, z. B. britisches Pfund)","ex":"In Londen betaalde ik tien pond voor de lunch.","exDe":"In London zahlte ich zehn Pfund für das Mittagessen."}],"usage":"het pond; nach Zahlwort meist ohne Plural-Endung ('drie pond kaas'). Doppeldeutig als Gewichts- und als Waehrungseinheit.","genus":"het","plural":"ponden"},"bk_2123":{"lemma":"procent","displayNl":"het procent","pos":"substantief","meanings":[{"de":"das Prozent","ex":"Er is tien procent korting op alles.","exDe":"Es gibt zehn Prozent Rabatt auf alles."}],"usage":"het procent; nach Zahlwort ohne Plural-Endung ('tien procent'). Zeichen: %. Verwandt: het percentage (der Prozentsatz).","genus":"het","plural":"procenten"},"bk_2124":{"lemma":"lengte","displayNl":"de lengte","pos":"substantief","meanings":[{"de":"die Laenge (Abmessung)","ex":"De lengte van de tafel is twee meter.","exDe":"Die Laenge des Tisches ist zwei Meter."},{"de":"die Koerpergroesse","ex":"Wat is jouw lengte in centimeters?","exDe":"Wie gross bist du in Zentimetern?"},{"de":"der Laengengrad (geografisch)","ex":"De stad ligt op vijf graden oosterlengte.","exDe":"Die Stadt liegt auf fuenf Grad oestlicher Laenge."}],"usage":"de lengte; Plural 'lengtes' (auch 'lengten'). Neben der Abmessung auch für Koerpergroesse und geografische Laenge (oosterlengte/westerlengte).","genus":"de","plural":"lengtes"},"bk_2125":{"lemma":"breedte","displayNl":"de breedte","pos":"substantief","meanings":[{"de":"die Breite","ex":"De breedte van de deur is een meter.","exDe":"Die Breite der Tür ist ein Meter."},{"de":"der Breitengrad","ex":"Amsterdam ligt op een noordelijke breedte.","exDe":"Amsterdam liegt auf einem nördlichen Breitengrad."}],"usage":"Maßangabe für die horizontale Ausdehnung; auch geografisch (geografische breedte = Breitengrad).","genus":"de","plural":"breedtes"},"bk_2126":{"lemma":"hoogte","displayNl":"de hoogte","pos":"substantief","meanings":[{"de":"die Höhe","ex":"De hoogte van de berg is indrukwekkend.","exDe":"Die Höhe des Berges ist beeindruckend."},{"de":"die Anhöhe, der Hügel","ex":"We stonden op een hoogte en keken uit over de stad.","exDe":"Wir standen auf einer Anhöhe und blickten über die Stadt."},{"de":"der Kenntnisstand (in de uitdrukking 'op de hoogte')","ex":"Ik houd je op de hoogte van het nieuws.","exDe":"Ich halte dich über die Neuigkeiten auf dem Laufenden."}],"usage":"Vertikale Ausdehnung; auch 'Anhöhe'. Feste Wendung 'op de hoogte zijn/houden' = informiert sein/halten.","genus":"de","plural":"hoogtes"},"bk_2127":{"lemma":"dubbel","displayNl":"dubbel","pos":"adjectief","meanings":[{"de":"doppelt, zweifach","ex":"Ik betaal een dubbele prijs.","exDe":"Ich zahle einen doppelten Preis."},{"de":"zwiespältig, gemischt (Gefühl)","ex":"Ik heb een dubbel gevoel bij dit besluit.","exDe":"Ich habe ein zwiespältiges Gefühl bei dieser Entscheidung."}],"usage":"Attributiv 'dubbele' (dubbele prijs). Auch adverbial 'dubbel zo veel' = doppelt so viel. Übertragen: 'dubbel gevoel'."},"bk_2128":{"lemma":"hooguit","displayNl":"hooguit","pos":"bijwoord","meanings":[{"de":"höchstens, allenfalls","ex":"Het kost hooguit tien euro.","exDe":"Es kostet höchstens zehn Euro."}],"usage":"Setzt eine obere Grenze; Synonym 'op zijn hoogst', Gegenteil 'minstens'."},"bk_2129":{"lemma":"hardloper","displayNl":"de hardloper","pos":"substantief","meanings":[{"de":"der Läufer (Sport)","ex":"Hij is een snelle hardloper.","exDe":"Er ist ein schneller Läufer."},{"de":"der Verkaufsschlager, das gut laufende Produkt","ex":"Dit boek is een echte hardloper in de winkel.","exDe":"Dieses Buch ist ein echter Verkaufsschlager im Laden."}],"usage":"Person, die Laufsport betreibt; übertragen ein gut verkäuflicher Artikel. Weibliche Form 'hardloopster'.","genus":"de","plural":"hardlopers","illustratable":true},"bk_2130":{"lemma":"orkest","displayNl":"het orkest","pos":"substantief","meanings":[{"de":"das Orchester","ex":"Het orkest speelt een prachtige symfonie.","exDe":"Das Orchester spielt eine wunderschöne Sinfonie."}],"usage":"Großes Ensemble von Musikern; auch 'symfonieorkest'.","genus":"het","plural":"orkesten","illustratable":true},"bk_2131":{"lemma":"bordspel","displayNl":"het bordspel","pos":"substantief","meanings":[{"de":"das Brettspiel","ex":"Dit bordspel is heel leuk om samen te spelen.","exDe":"Dieses Brettspiel macht zusammen sehr viel Spaß."}],"usage":"Gesellschaftsspiel mit Spielbrett (z. B. Ganzenbord, Mens-erger-je-niet).","genus":"het","plural":"bordspellen","illustratable":true},"bk_2132":{"lemma":"verzamelen","displayNl":"verzamelen","pos":"werkwoord","meanings":[{"de":"sammeln","ex":"Hij verzamelt oude postzegels.","exDe":"Er sammelt alte Briefmarken."},{"de":"sich versammeln, zusammenkommen","ex":"De deelnemers verzamelen zich op het plein.","exDe":"Die Teilnehmer versammeln sich auf dem Platz."},{"de":"anhäufen, ansammeln","ex":"Ze verzamelde moed om te spreken.","exDe":"Sie sammelte Mut, um zu sprechen."}],"usage":"Regelmäßiges Verb. Reflexiv 'zich verzamelen' = sich versammeln. Verwandt: 'verzameling' (Sammlung).","conjugation":{"presens":{"ik":"verzamel","jij":"verzamelt","hij":"verzamelt","wij":"verzamelen"},"imperfectum":{"ik":"verzamelde","wij":"verzamelden"},"perfectum":{"aux":"hebben","participle":"verzameld"}},"illustratable":true},"bk_2133":{"lemma":"ontspannen","displayNl":"ontspannen","pos":"werkwoord","meanings":[{"de":"(sich) entspannen, ausspannen","ex":"Ik wil in de vakantie ontspannen.","exDe":"Ich möchte im Urlaub entspannen."},{"de":"entspannt, gelöst (als Adjektiv/Partizip)","ex":"Hij zit ontspannen in zijn stoel.","exDe":"Er sitzt entspannt in seinem Sessel."}],"usage":"Untrennbares Verb (Präfix ont-); reflexiv 'zich ontspannen' oder intransitiv. Partizip = ontspannen, Hilfsverb hebben.","conjugation":{"presens":{"ik":"ontspan","jij":"ontspant","hij":"ontspant","wij":"ontspannen"},"imperfectum":{"ik":"ontspande","wij":"ontspanden"},"perfectum":{"aux":"hebben","participle":"ontspannen"}},"notes":"Homograf mit dem Adjektiv 'ontspannen' (= entspannt).","illustratable":true},"bk_2134":{"lemma":"genieten","displayNl":"genieten","pos":"werkwoord","meanings":[{"de":"genießen, sich erfreuen (an etwas)","ex":"Wij genieten van het mooie weer.","exDe":"Wir genießen das schöne Wetter."},{"de":"in den Genuss von etwas kommen, etwas erhalten","ex":"Zij geniet een goede opleiding.","exDe":"Sie genießt eine gute Ausbildung."}],"usage":"Starkes Verb (genieten - genoot - genoten), Hilfsverb hebben. Meist mit Präposition 'van': 'genieten van iets'.","conjugation":{"presens":{"ik":"geniet","jij":"geniet","hij":"geniet","wij":"genieten"},"imperfectum":{"ik":"genoot","wij":"genoten"},"perfectum":{"aux":"hebben","participle":"genoten"}}},"bk_2135":{"lemma":"uitzicht","displayNl":"het uitzicht","pos":"substantief","meanings":[{"de":"die Aussicht, der Ausblick (Blick auf etwas)","ex":"Vanaf de berg is het uitzicht mooi.","exDe":"Vom Berg aus ist die Aussicht schön."},{"de":"die Aussicht, Chance (auf etwas Zukünftiges, figurativ)","ex":"Er is uitzicht op een goede baan.","exDe":"Es gibt Aussicht auf eine gute Stelle."}],"usage":"het-Wort; 'uitzicht op' = Aussicht/Blick auf etwas.","genus":"het","plural":"uitzichten","illustratable":true},"bk_2136":{"lemma":"weersvoorspelling","displayNl":"de weersvoorspelling","pos":"substantief","meanings":[{"de":"die Wettervorhersage, der Wetterbericht","ex":"De weersvoorspelling belooft zon.","exDe":"Die Wettervorhersage verspricht Sonne."}],"usage":"de-Wort; Fugen-s (weer + s + voorspelling).","genus":"de","plural":"weersvoorspellingen"},"bk_2137":{"lemma":"reisverzekering","displayNl":"de reisverzekering","pos":"substantief","meanings":[{"de":"die Reiseversicherung","ex":"Wij sluiten een reisverzekering af.","exDe":"Wir schließen eine Reiseversicherung ab."}],"usage":"de-Wort; oft mit 'afsluiten' (abschließen).","genus":"de","plural":"reisverzekeringen"},"bk_2138":{"lemma":"aankomst","displayNl":"de aankomst","pos":"substantief","meanings":[{"de":"die Ankunft","ex":"De aankomst is om acht uur.","exDe":"Die Ankunft ist um acht Uhr."}],"usage":"de-Wort; Gegenteil von 'vertrek'. Zu 'aankomen' (ankommen).","genus":"de","plural":"aankomsten"},"bk_2139":{"lemma":"vertrek","displayNl":"het vertrek","pos":"substantief","meanings":[{"de":"die Abfahrt, der Aufbruch, die Abreise","ex":"Het vertrek is om zeven uur.","exDe":"Die Abfahrt ist um sieben Uhr."},{"de":"der Raum, das Zimmer, das Gemach","ex":"Het huis heeft vijf vertrekken.","exDe":"Das Haus hat fünf Räume."}],"usage":"het-Wort. Homonym: 1) Abfahrt (zu 'vertrekken'); 2) Raum/Zimmer.","genus":"het","plural":"vertrekken","notes":"In der Bedeutung 'Abfahrt' meist ohne Plural; im Plural 'vertrekken' üblich für Räume."},"bk_2140":{"lemma":"rondleiding","displayNl":"de rondleiding","pos":"substantief","meanings":[{"de":"die Führung, der Rundgang (geführte Tour)","ex":"Wij doen mee aan een rondleiding.","exDe":"Wir nehmen an einer Führung teil."}],"usage":"de-Wort; oft 'een rondleiding doen/geven/volgen'.","genus":"de","plural":"rondleidingen","illustratable":true},"bk_2141":{"lemma":"tocht","displayNl":"de tocht","pos":"substantief","meanings":[{"de":"der Ausflug, die Tour, die Wanderung","ex":"Wij maken een tocht door de bergen.","exDe":"Wir machen eine Tour durch die Berge."},{"de":"der Zug (Fahrt/Reise über Strecke)","ex":"De tocht met de boot duurde drie uur.","exDe":"Die Fahrt mit dem Boot dauerte drei Stunden."},{"de":"der Durchzug, die Zugluft","ex":"Doe het raam dicht, er is tocht.","exDe":"Mach das Fenster zu, es zieht."}],"usage":"Alltäglich für eine (längere) Wander- oder Reisetour; im Kontext von Räumen auch 'Zugluft'.","genus":"de","plural":"tochten","illustratable":true},"bk_2142":{"lemma":"avontuur","displayNl":"het avontuur","pos":"substantief","meanings":[{"de":"das Abenteuer","ex":"De reis was een echt avontuur.","exDe":"Die Reise war ein echtes Abenteuer."},{"de":"das (Liebes-)Abenteuer, die Affäre","ex":"Hij had een avontuur met een collega.","exDe":"Er hatte eine Affäre mit einer Kollegin."}],"usage":"Für ein aufregendes Erlebnis; im übertragenen Sinn auch eine kurze Liebesaffäre.","genus":"het","plural":"avonturen"},"bk_2143":{"lemma":"accommodatie","displayNl":"de accommodatie","pos":"substantief","meanings":[{"de":"die Unterkunft","ex":"Wij zoeken een goedkope accommodatie.","exDe":"Wir suchen eine günstige Unterkunft."},{"de":"die Einrichtungen, die Anlage (z. B. Sport)","ex":"De camping heeft moderne accommodatie.","exDe":"Der Campingplatz hat moderne Einrichtungen."}],"usage":"Formeller Sammelbegriff für Übernachtungsmöglichkeiten oder Einrichtungen; in Reise- und Buchungskontexten.","genus":"de","plural":"accommodaties"},"bk_2144":{"lemma":"bungalow","displayNl":"de bungalow","pos":"substantief","meanings":[{"de":"der Bungalow (ebenerdiges Ferienhaus)","ex":"Wij huren een bungalow aan zee.","exDe":"Wir mieten einen Bungalow am Meer."}],"usage":"Ebenerdiges, freistehendes Haus, oft als Ferienunterkunft.","genus":"de","plural":"bungalows","illustratable":true},"bk_2145":{"lemma":"kamperen","displayNl":"kamperen","pos":"werkwoord","meanings":[{"de":"campen, zelten","ex":"Wij gaan kamperen in Frankrijk.","exDe":"Wir gehen in Frankreich campen."}],"usage":"Regelmäßiges Verb; im Freien in Zelt oder Wohnwagen übernachten.","conjugation":{"presens":{"ik":"kampeer","jij":"kampeert","hij":"kampeert","wij":"kamperen"},"imperfectum":{"ik":"kampeerde","wij":"kampeerden"},"perfectum":{"aux":"hebben","participle":"gekampeerd"}},"illustratable":true},"bk_2146":{"lemma":"zeilen","displayNl":"zeilen","pos":"werkwoord","meanings":[{"de":"segeln","ex":"In de zomer gaan wij zeilen.","exDe":"Im Sommer gehen wir segeln."}],"usage":"Regelmäßiges Verb; mit einem Segelboot fahren. Hilfsverb 'hebben' (bei Richtungsangabe auch 'zijn').","conjugation":{"presens":{"ik":"zeil","jij":"zeilt","hij":"zeilt","wij":"zeilen"},"imperfectum":{"ik":"zeilde","wij":"zeilden"},"perfectum":{"aux":"hebben","participle":"gezeild"}},"illustratable":true},"bk_2147":{"lemma":"surfen","displayNl":"surfen","pos":"werkwoord","meanings":[{"de":"surfen (auf Wellen/Wasser)","ex":"Hij leert surfen op zee.","exDe":"Er lernt am Meer surfen."},{"de":"im Internet surfen","ex":"Zij surft de hele avond op internet.","exDe":"Sie surft den ganzen Abend im Internet."}],"usage":"Regelmäßiges Verb; auf Wellen surfen oder im Internet surfen. Hilfsverb 'hebben' (bei Richtung auch 'zijn').","conjugation":{"presens":{"ik":"surf","jij":"surft","hij":"surft","wij":"surfen"},"imperfectum":{"ik":"surfte","wij":"surften"},"perfectum":{"aux":"hebben","participle":"gesurft"}},"illustratable":true},"bk_2148":{"lemma":"duiken","displayNl":"duiken","pos":"werkwoord","meanings":[{"de":"tauchen","ex":"Wij gaan duiken in de zee.","exDe":"Wir gehen im Meer tauchen."},{"de":"sich ducken, hechten (schnelle Bewegung nach unten)","ex":"De keeper dook naar de bal.","exDe":"Der Torwart hechtete zum Ball."}],"usage":"Unregelmäßiges (starkes) Verb: dook/doken, gedoken. Hilfsverb 'hebben' (als Tätigkeit) bzw. 'zijn' (bei Bewegung/Richtung).","conjugation":{"presens":{"ik":"duik","jij":"duikt","hij":"duikt","wij":"duiken"},"imperfectum":{"ik":"dook","wij":"doken"},"perfectum":{"aux":"hebben","participle":"gedoken"}},"illustratable":true},"bk_2149":{"lemma":"klimmen","displayNl":"klimmen","pos":"werkwoord","meanings":[{"de":"klettern, steigen","ex":"Hij klimt graag in de bergen.","exDe":"Er klettert gerne in den Bergen."},{"de":"(hinauf)steigen, hochklettern","ex":"De kat klimt in de boom.","exDe":"Die Katze klettert auf den Baum."},{"de":"ansteigen, steigen (Werte/Preise)","ex":"De temperatuur klimt naar dertig graden.","exDe":"Die Temperatur steigt auf dreißig Grad."}],"usage":"Sterk werkwoord (klimmen-klom-geklommen). Perfectum met 'zijn' bij verplaatsing/richting ('hij is in de boom geklommen'), met 'hebben' bij de activiteit ('ik heb de hele dag geklommen').","conjugation":{"presens":{"ik":"klim","jij":"klimt","hij":"klimt","wij":"klimmen"},"imperfectum":{"ik":"klom","wij":"klommen"},"perfectum":{"aux":"zijn","participle":"geklommen"}},"illustratable":true},"bk_2150":{"lemma":"wielrenner","displayNl":"de wielrenner","pos":"substantief","meanings":[{"de":"der Radrennfahrer, Radprofi","ex":"De wielrenner rijdt heel snel.","exDe":"Der Radrennfahrer fährt sehr schnell."}],"usage":"Vrouwelijke vorm: wielrenster.","genus":"de","plural":"wielrenners","illustratable":true},"bk_2151":{"lemma":"zwemmer","displayNl":"de zwemmer","pos":"substantief","meanings":[{"de":"der Schwimmer","ex":"Hij is een goede zwemmer.","exDe":"Er ist ein guter Schwimmer."}],"usage":"Vrouwelijke vorm: zwemster.","genus":"de","plural":"zwemmers","illustratable":true},"bk_2152":{"lemma":"scheidsrechter","displayNl":"de scheidsrechter","pos":"substantief","meanings":[{"de":"der Schiedsrichter","ex":"De scheidsrechter fluit voor de rust.","exDe":"Der Schiedsrichter pfeift zur Halbzeit."}],"usage":"Informeel ook 'de scheids'.","genus":"de","plural":"scheidsrechters","illustratable":true},"bk_2153":{"lemma":"stadion","displayNl":"het stadion","pos":"substantief","meanings":[{"de":"das Stadion","ex":"Het stadion is helemaal vol.","exDe":"Das Stadion ist ganz voll."}],"usage":"Plural 'stadions', formeel ook 'stadia'.","genus":"het","plural":"stadions","illustratable":true},"bk_2154":{"lemma":"supporter","displayNl":"de supporter","pos":"substantief","meanings":[{"de":"der Fan, Anhänger (Sport)","ex":"De supporters zingen luid.","exDe":"Die Fans singen laut."}],"usage":"Sport-context; algemener 'fan' voor idolen/muziek.","genus":"de","plural":"supporters","illustratable":true},"bk_2155":{"lemma":"kampioenschap","displayNl":"het kampioenschap","pos":"substantief","meanings":[{"de":"die Meisterschaft (Wettbewerb/Titel)","ex":"Ons team wint het kampioenschap.","exDe":"Unsere Mannschaft gewinnt die Meisterschaft."},{"de":"die Meisterschaft, das Turnier (Veranstaltung)","ex":"Het wereldkampioenschap wordt in Nederland gehouden.","exDe":"Die Weltmeisterschaft wird in den Niederlanden ausgetragen."}],"usage":"Samenstellingen: wereldkampioenschap (WK), Europees kampioenschap (EK).","genus":"het","plural":"kampioenschappen"},"bk_2156":{"lemma":"medaille","displayNl":"de medaille","pos":"substantief","meanings":[{"de":"die Medaille","ex":"Zij wint een gouden medaille.","exDe":"Sie gewinnt eine goldene Medaille."}],"usage":"Uitspraak ongeveer 'me-da-je'.","genus":"de","plural":"medailles","illustratable":true},"bk_2157":{"lemma":"wandelaar","displayNl":"de wandelaar","pos":"substantief","meanings":[{"de":"der Wanderer / die Wandererin","ex":"De wandelaar rust even uit op een bankje.","exDe":"Der Wanderer ruht sich kurz auf einer Bank aus."},{"de":"der Spaziergänger (jemand, der zu Fuß unterwegs ist)","ex":"Op het strand zie je veel wandelaars.","exDe":"Am Strand sieht man viele Spaziergänger."}],"usage":"Personenbezeichnung; feminin oft 'wandelaarster'. Plural auf -s.","genus":"de","plural":"wandelaars","illustratable":true},"bk_2158":{"lemma":"tentoonstelling","displayNl":"de tentoonstelling","pos":"substantief","meanings":[{"de":"die Ausstellung","ex":"Wij bezoeken een tentoonstelling in het museum.","exDe":"Wir besuchen eine Ausstellung im Museum."},{"de":"die Schau / die Präsentation (öffentlich gezeigte Sammlung)","ex":"De tentoonstelling over moderne kunst duurt tot september.","exDe":"Die Schau über moderne Kunst läuft bis September."}],"usage":"Vom Verb 'tentoonstellen'. Plural -en.","genus":"de","plural":"tentoonstellingen","illustratable":true},"bk_2159":{"lemma":"voorstelling","displayNl":"de voorstelling","pos":"substantief","meanings":[{"de":"die Vorstellung / die Aufführung (Theater, Film, Zirkus)","ex":"De voorstelling begint om acht uur.","exDe":"Die Vorstellung beginnt um acht Uhr."},{"de":"die Vorstellung / das gedankliche Bild (Konzept im Kopf)","ex":"Ik heb geen voorstelling van hoe groot het is.","exDe":"Ich habe keine Vorstellung davon, wie groß es ist."}],"usage":"Zwei Kernbedeutungen: Aufführung (konkret) und mentale Vorstellung (abstrakt). Plural -en.","genus":"de","plural":"voorstellingen","illustratable":true},"bk_2160":{"lemma":"vrijetijdsbesteding","displayNl":"de vrijetijdsbesteding","pos":"substantief","meanings":[{"de":"die Freizeitgestaltung / die Freizeitbeschäftigung","ex":"Sport is een gezonde vrijetijdsbesteding.","exDe":"Sport ist eine gesunde Freizeitbeschäftigung."},{"de":"die Freizeitaktivität (Art, wie man freie Zeit verbringt)","ex":"Lezen is zijn favoriete vrijetijdsbesteding.","exDe":"Lesen ist seine liebste Freizeitaktivität."}],"usage":"Zusammensetzung: vrije tijd + besteding. Plural -en, im Deutschen meist Singular.","genus":"de","plural":"vrijetijdsbestedingen"},"bk_2161":{"lemma":"reisgenoot","displayNl":"de reisgenoot","pos":"substantief","meanings":[{"de":"der Reisebegleiter / die Reisebegleiterin","ex":"Mijn reisgenoot is heel aardig.","exDe":"Mein Reisebegleiter ist sehr nett."},{"de":"der Mitreisende / der Reisegefährte","ex":"We werden onderweg goede reisgenoten.","exDe":"Wir wurden unterwegs gute Reisegefährten."}],"usage":"Zusammensetzung reis + genoot; Plural mit Vokaldehnung 'reisgenoten'. Feminin 'reisgenote'.","genus":"de","plural":"reisgenoten","illustratable":true},"bk_2162":{"lemma":"dagtrip","displayNl":"de dagtrip","pos":"substantief","meanings":[{"de":"der Tagesausflug","ex":"Wij maken een dagtrip naar de kust.","exDe":"Wir machen einen Tagesausflug an die Küste."},{"de":"der Tagestrip / die Tagestour","ex":"Een dagtrip naar Amsterdam is zo geboekt.","exDe":"Ein Tagestrip nach Amsterdam ist schnell gebucht."}],"usage":"Zusammensetzung dag + trip; Plural auf -s. Synonym 'dagje uit'.","genus":"de","plural":"dagtrips","illustratable":true},"bk_2163":{"lemma":"route","displayNl":"de route","pos":"substantief","meanings":[{"de":"die Route / der Weg (geplante Strecke)","ex":"Wij kiezen een mooie route door de bergen.","exDe":"Wir wählen eine schöne Route durch die Berge."},{"de":"die Strecke / die Linie (fester Verkehrsweg)","ex":"Deze bus rijdt een andere route dan gisteren.","exDe":"Dieser Bus fährt eine andere Strecke als gestern."}],"usage":"Aus dem Französischen; Plural -s. Uitspraak met Franse 'oe'-klank.","genus":"de","plural":"routes","illustratable":true},"bk_2164":{"lemma":"souvenir","displayNl":"het souvenir","pos":"substantief","meanings":[{"de":"das Souvenir / das Andenken (Reise-Mitbringsel)","ex":"Ik koop een souvenir voor mijn moeder.","exDe":"Ich kaufe ein Souvenir für meine Mutter."},{"de":"das Erinnerungsstück","ex":"Deze schelp is een souvenir van onze vakantie.","exDe":"Diese Muschel ist ein Erinnerungsstück aus unserem Urlaub."}],"usage":"Aus dem Französischen; genus 'het', Plural -s. Synonym 'aandenken'.","genus":"het","plural":"souvenirs","illustratable":true},"bk_2165":{"lemma":"ansichtkaart","displayNl":"de ansichtkaart","pos":"substantief","meanings":[{"de":"die Postkarte","ex":"Ik stuur een ansichtkaart naar huis.","exDe":"Ich schicke eine Postkarte nach Hause."},{"de":"die Ansichtskarte","ex":"Op de ansichtkaart staat een foto van Amsterdam.","exDe":"Auf der Ansichtskarte ist ein Foto von Amsterdam."}],"usage":"Karte mit Bild auf der Vorderseite, die man verschickt; Alltagswort im Reisekontext.","genus":"de","plural":"ansichtkaarten","illustratable":true},"bk_2166":{"lemma":"zonvakantie","displayNl":"de zonvakantie","pos":"substantief","meanings":[{"de":"der Strandurlaub","ex":"Wij houden van een zonvakantie aan zee.","exDe":"Wir mögen einen Strandurlaub am Meer."},{"de":"der Sonnenurlaub / Badeurlaub","ex":"Zij boeken elk jaar een zonvakantie in Spanje.","exDe":"Sie buchen jedes Jahr einen Sonnenurlaub in Spanien."}],"usage":"Urlaub, dessen Ziel Sonne, Strand und Meer sind; typisches Reisebüro-Wort.","genus":"de","plural":"zonvakanties","illustratable":true},"bk_2167":{"lemma":"sociale media","displayNl":"de sociale media","pos":"substantief","meanings":[{"de":"die sozialen Medien / Social Media","ex":"Zij is veel op sociale media.","exDe":"Sie ist viel in den sozialen Medien."},{"de":"soziale Netzwerke","ex":"Veel bedrijven gebruiken sociale media voor reclame.","exDe":"Viele Firmen nutzen soziale Netzwerke für Werbung."}],"usage":"Plattformen wie Instagram, Facebook, TikTok; wird im Niederländischen als Plural verwendet.","genus":"de","notes":"Fast immer im Plural gebraucht (Singular theoretisch 'sociaal medium', selten). Abstrakter Sammelbegriff."},"bk_2168":{"lemma":"plaatsen","displayNl":"plaatsen","pos":"werkwoord","meanings":[{"de":"posten / veröffentlichen (einen Beitrag)","ex":"Ik ga een bericht plaatsen op Instagram.","exDe":"Ich poste einen Beitrag auf Instagram."},{"de":"platzieren / stellen / setzen","ex":"Hij plaatst de stoel bij het raam.","exDe":"Er stellt den Stuhl ans Fenster."},{"de":"aufstellen / anbringen","ex":"De gemeente plaatst een nieuwe bank in het park.","exDe":"Die Gemeinde stellt eine neue Bank im Park auf."}],"usage":"Regelmäßiges Verb; im Social-Media-Kontext 'een bericht plaatsen' = einen Beitrag posten.","conjugation":{"presens":{"ik":"plaats","jij":"plaatst","hij":"plaatst","wij":"plaatsen"},"imperfectum":{"ik":"plaatste","wij":"plaatsten"},"perfectum":{"aux":"hebben","participle":"geplaatst"}}},"bk_2169":{"lemma":"volger","displayNl":"de volger","pos":"substantief","meanings":[{"de":"der Follower / Abonnent (Social Media)","ex":"Zij heeft veel volgers op Instagram.","exDe":"Sie hat viele Follower auf Instagram."},{"de":"der Anhänger / Nachfolger","ex":"De leider had trouwe volgers.","exDe":"Der Anführer hatte treue Anhänger."}],"usage":"Person, die jemandem folgt, besonders in sozialen Medien.","genus":"de","plural":"volgers"},"bk_2170":{"lemma":"gegevens","displayNl":"de gegevens","pos":"substantief","meanings":[{"de":"die Daten","ex":"Bescherm je persoonlijke gegevens.","exDe":"Schütze deine persönlichen Daten."},{"de":"die Angaben / Informationen","ex":"Vul hier je gegevens in.","exDe":"Trage hier deine Angaben ein."}],"usage":"Sammelbegriff für Informationen, oft persönliche Daten oder Formularangaben.","genus":"de","notes":"In der Bedeutung 'Daten/Angaben' als Plural gebraucht; Singular 'het gegeven' bedeutet 'die gegebene Tatsache'."},"bk_2171":{"lemma":"privacy","displayNl":"de privacy","pos":"substantief","meanings":[{"de":"die Privatsphäre","ex":"Privacy is heel belangrijk.","exDe":"Privatsphäre ist sehr wichtig."},{"de":"der Datenschutz","ex":"Deze app respecteert je privacy.","exDe":"Diese App respektiert deinen Datenschutz."}],"usage":"Schutz des persönlichen und privaten Bereichs; Alltags- und Digitalkontext.","genus":"de","notes":"Englisches Lehnwort, im Niederländischen üblich; kein Plural."},"bk_2172":{"lemma":"beveiliging","displayNl":"de beveiliging","pos":"substantief","meanings":[{"de":"die Sicherheit / Absicherung (technisch)","ex":"De beveiliging van de site is goed.","exDe":"Die Sicherheit der Seite ist gut."},{"de":"der Sicherheitsdienst / das Sicherheitspersonal","ex":"De beveiliging staat bij de ingang.","exDe":"Der Sicherheitsdienst steht am Eingang."},{"de":"die Sicherung / der Schutzmechanismus","ex":"Er zit een beveiliging op het slot.","exDe":"Am Schloss ist eine Sicherung angebracht."}],"usage":"Maßnahmen oder Personen zum Schutz; digital (Datensicherheit) wie physisch (Wachdienst).","genus":"de","plural":"beveiligingen"},"bk_2173":{"lemma":"virus","displayNl":"het virus","pos":"substantief","meanings":[{"de":"der Virus (Computervirus, Schadsoftware)","ex":"Er zit een virus op mijn computer.","exDe":"Auf meinem Computer ist ein Virus."},{"de":"der Virus (Krankheitserreger)","ex":"Het virus verspreidt zich snel onder de kinderen.","exDe":"Der Virus verbreitet sich schnell unter den Kindern."}],"usage":"Neutrum: het virus. Plural virussen. Sowohl Computervirus als auch biologischer Krankheitserreger.","genus":"het","plural":"virussen"},"bk_2174":{"lemma":"spam","displayNl":"de spam","pos":"substantief","meanings":[{"de":"der Spam (unerwünschte Werbe-/Massenmails)","ex":"Ik krijg veel spam in mijn mail.","exDe":"Ich bekomme viel Spam in meiner Mail."},{"de":"der Spam (unerwünschte Nachrichten allgemein)","ex":"De chat stond vol met spam.","exDe":"Der Chat war voller Spam."}],"usage":"de-Wort, unzählbar (kein regulärer Plural). Unerwünschte Massen-E-Mails/-Nachrichten.","genus":"de"},"bk_2175":{"lemma":"reclamemail","displayNl":"de reclamemail","pos":"substantief","meanings":[{"de":"die Werbe-Mail","ex":"Ik verwijder elke reclamemail meteen.","exDe":"Ich lösche jede Werbe-Mail sofort."}],"usage":"de-Wort. Plural reclamemails. Werbe-E-Mail eines Unternehmens.","genus":"de","plural":"reclamemails"},"bk_2176":{"lemma":"zoekopdracht","displayNl":"de zoekopdracht","pos":"substantief","meanings":[{"de":"die Suchanfrage","ex":"De zoekopdracht gaf veel resultaten.","exDe":"Die Suchanfrage lieferte viele Ergebnisse."}],"usage":"de-Wort. Plural zoekopdrachten. Eingegebene Suche in Suchmaschine/Datenbank.","genus":"de","plural":"zoekopdrachten"},"bk_2178":{"lemma":"geheugen","displayNl":"het geheugen","pos":"substantief","meanings":[{"de":"das Gedächtnis (Erinnerungsvermögen)","ex":"Zij heeft een goed geheugen voor namen.","exDe":"Sie hat ein gutes Gedächtnis für Namen."},{"de":"der Speicher (Computer)","ex":"Het geheugen van mijn telefoon is bijna vol.","exDe":"Der Speicher meines Telefons ist fast voll."}],"usage":"Neutrum: het geheugen. Plural geheugens. Menschliches Gedächtnis wie auch Computerspeicher.","genus":"het","plural":"geheugens"},"bk_2179":{"lemma":"opslag","displayNl":"de opslag","pos":"substantief","meanings":[{"de":"der Speicherplatz / die Speicherung (Daten)","ex":"Ik heb meer opslag nodig voor mijn foto's.","exDe":"Ich brauche mehr Speicherplatz für meine Fotos."},{"de":"die Lagerung / das Lager (Waren)","ex":"De meubels staan in de opslag.","exDe":"Die Möbel stehen im Lager."},{"de":"die Gehaltserhöhung","ex":"Hij heeft om opslag gevraagd.","exDe":"Er hat um eine Gehaltserhöhung gebeten."}],"usage":"de-Wort, meist unzählbar. Mehrere Bedeutungen: (Daten-/Waren-)Speicherung und Gehaltserhöhung.","genus":"de"},"bk_2180":{"lemma":"cloud","displayNl":"de cloud","pos":"substantief","meanings":[{"de":"die Cloud (Online-Speicher)","ex":"Mijn foto's staan in de cloud.","exDe":"Meine Fotos sind in der Cloud."}],"usage":"de-Wort. Plural clouds. Online-Speicher im Internet (Cloud-Computing).","genus":"de","plural":"clouds"},"bk_2181":{"lemma":"back-up","displayNl":"de back-up","pos":"substantief","meanings":[{"de":"die Sicherung / das Back-up (Sicherungskopie)","ex":"Maak elke week een back-up van je bestanden.","exDe":"Mach jede Woche ein Back-up deiner Dateien."},{"de":"die Unterstützung / der Ersatz (Person, die einspringt)","ex":"Er is altijd een back-up als iemand ziek wordt.","exDe":"Es gibt immer einen Ersatz, wenn jemand krank wird."}],"usage":"de-Wort, mit Bindestrich geschrieben. Plural back-ups. Sicherungskopie von Daten; auch Unterstützung/Ersatz.","genus":"de","plural":"back-ups"},"bk_2182":{"lemma":"toestel","displayNl":"het toestel","pos":"substantief","meanings":[{"de":"das Gerät, der Apparat","ex":"Dit toestel is nieuw op de markt.","exDe":"Dieses Gerät ist neu auf dem Markt."},{"de":"der Telefonapparat, die Nebenstelle (Durchwahl)","ex":"U kunt hem bereiken op toestel 214.","exDe":"Sie können ihn unter der Nebenstelle 214 erreichen."},{"de":"das Turngerät","ex":"De turnster stapte op het toestel.","exDe":"Die Turnerin stieg auf das Turngerät."}],"usage":"Gebruikelijk woord voor een (elektronisch) apparaat; 'toestel' betekent in telefooncontext ook de doorkiesnummer/nevenaansluiting.","genus":"het","plural":"toestellen","illustratable":true},"bk_2183":{"lemma":"software","displayNl":"de software","pos":"substantief","meanings":[{"de":"die Software","ex":"De software moet worden bijgewerkt.","exDe":"Die Software muss aktualisiert werden."},{"de":"das Programm, die Programme (Gesamtheit)","ex":"Deze software werkt niet op mijn laptop.","exDe":"Diese Software läuft nicht auf meinem Laptop."}],"usage":"Niet-telbaar leenwoord; de-woord. Meestal geen meervoud.","genus":"de"},"bk_2184":{"lemma":"hardware","displayNl":"de hardware","pos":"substantief","meanings":[{"de":"die Hardware (physische Computerkomponenten)","ex":"De hardware is verouderd.","exDe":"Die Hardware ist veraltet."},{"de":"die Geräteausstattung, die physische Technik","ex":"We hebben nieuwe hardware nodig voor de server.","exDe":"Wir brauchen neue Hardware für den Server."}],"usage":"Niet-telbaar leenwoord voor de fysieke onderdelen van een computer; de-woord, meestal geen meervoud.","genus":"de","illustratable":true},"bk_2185":{"lemma":"systeem","displayNl":"het systeem","pos":"substantief","meanings":[{"de":"das System (technische/organisierte Gesamtheit)","ex":"Het systeem is vastgelopen.","exDe":"Das System ist abgestürzt."},{"de":"das System, die Methode, die feste Ordnung","ex":"Hij werkt volgens een vast systeem.","exDe":"Er arbeitet nach einem festen System."}],"usage":"Het-woord; zowel technisch (computer, netwerk) als abstract (methode, ordening).","genus":"het","plural":"systemen"},"bk_2186":{"lemma":"storing","displayNl":"de storing","pos":"substantief","meanings":[{"de":"die Störung, der Ausfall (technisch)","ex":"Er is een storing in het netwerk.","exDe":"Es gibt eine Störung im Netzwerk."},{"de":"die Störung, die Unterbrechung (Empfang, Signal)","ex":"Door de storing viel de radio uit.","exDe":"Durch die Störung fiel das Radio aus."}],"usage":"De-woord; gebruikelijk voor een technisch defect of onderbreking van een dienst.","genus":"de","plural":"storingen"},"bk_2187":{"lemma":"bijwerken","displayNl":"bijwerken","pos":"werkwoord","meanings":[{"de":"aktualisieren, auf den neuesten Stand bringen","ex":"Ik moet de app bijwerken.","exDe":"Ich muss die App aktualisieren."},{"de":"nachbessern, ergänzen (z. B. Notizen, Farbe)","ex":"Ze werkt haar aantekeningen elke avond bij.","exDe":"Sie ergänzt ihre Notizen jeden Abend."}],"usage":"Scheidbaar werkwoord (bij|werken): 'ik werk het bestand bij'. Vaak gebruikt voor software, gegevens en administratie.","conjugation":{"presens":{"ik":"werk bij","jij":"werkt bij","hij":"werkt bij","wij":"werken bij"},"imperfectum":{"ik":"werkte bij","wij":"werkten bij"},"perfectum":{"aux":"hebben","participle":"bijgewerkt"}}},"bk_2188":{"lemma":"verwijderen","displayNl":"verwijderen","pos":"werkwoord","meanings":[{"de":"löschen, entfernen (Daten, Dateien)","ex":"Ik ga oude foto's verwijderen.","exDe":"Ich lösche alte Fotos."},{"de":"entfernen, wegnehmen (allgemein)","ex":"De dokter verwijderde de splinter uit mijn hand.","exDe":"Der Arzt entfernte den Splitter aus meiner Hand."}],"usage":"Niet-scheidbaar werkwoord; formeler dan 'weghalen'. Standaardterm voor het wissen van digitale bestanden.","conjugation":{"presens":{"ik":"verwijder","jij":"verwijdert","hij":"verwijdert","wij":"verwijderen"},"imperfectum":{"ik":"verwijderde","wij":"verwijderden"},"perfectum":{"aux":"hebben","participle":"verwijderd"}}},"bk_2189":{"lemma":"wissen","displayNl":"wissen","pos":"werkwoord","meanings":[{"de":"löschen (Daten, Aufnahme, Tafel)","ex":"Wis dit bestand maar.","exDe":"Lösche diese Datei ruhig."},{"de":"abwischen, auswischen","ex":"Hij wist het bord na de les.","exDe":"Er wischt die Tafel nach dem Unterricht ab."}],"usage":"Niet-scheidbaar werkwoord; gebruikt voor het uitwissen van gegevens én het schoonvegen van een oppervlak.","conjugation":{"presens":{"ik":"wis","jij":"wist","hij":"wist","wij":"wissen"},"imperfectum":{"ik":"wiste","wij":"wisten"},"perfectum":{"aux":"hebben","participle":"gewist"}}},"bk_2190":{"lemma":"kopiëren","displayNl":"kopiëren","pos":"werkwoord","meanings":[{"de":"kopieren (Text/Datei)","ex":"Kun je dit bestand even kopiëren?","exDe":"Kannst du diese Datei kurz kopieren?"},{"de":"nachahmen, nachmachen","ex":"Kinderen kopiëren vaak het gedrag van hun ouders.","exDe":"Kinder ahmen oft das Verhalten ihrer Eltern nach."}],"usage":"Regelmäßiges Verb; Trema in kopiëren/kopieert erhält getrennte Vokale. Digital (Datei/Text) wie auch übertragen (nachahmen).","conjugation":{"presens":{"ik":"kopieer","jij":"kopieert","hij":"kopieert","wij":"kopiëren"},"imperfectum":{"ik":"kopieerde","wij":"kopieerden"},"perfectum":{"aux":"hebben","participle":"gekopieerd"}}},"bk_2191":{"lemma":"plakken","displayNl":"plakken","pos":"werkwoord","meanings":[{"de":"einfügen (digital, aus der Zwischenablage)","ex":"Plak de link maar hier in het bericht.","exDe":"Füge den Link einfach hier in die Nachricht ein."},{"de":"kleben, festkleben","ex":"Ze plakt een postzegel op de envelop.","exDe":"Sie klebt eine Briefmarke auf den Umschlag."}],"usage":"Regelmäßig. Konkret 'kleben' und im Computerkontext 'einfügen' (kopiëren en plakken = kopieren und einfügen).","conjugation":{"presens":{"ik":"plak","jij":"plakt","hij":"plakt","wij":"plakken"},"imperfectum":{"ik":"plakte","wij":"plakten"},"perfectum":{"aux":"hebben","participle":"geplakt"}},"illustratable":true},"bk_2192":{"lemma":"verbinden","displayNl":"verbinden","pos":"werkwoord","meanings":[{"de":"verbinden (Geräte, Netzwerk)","ex":"Ik verbind mijn telefoon met de tv.","exDe":"Ich verbinde mein Handy mit dem Fernseher."},{"de":"verbinden, verbünden (Menschen/Dinge zusammenfügen)","ex":"Deze brug verbindt de twee dorpen.","exDe":"Diese Brücke verbindet die beiden Dörfer."},{"de":"verbinden (eine Wunde)","ex":"De dokter verbindt de wond met een verband.","exDe":"Der Arzt verbindet die Wunde mit einem Verband."}],"usage":"Starkes Verb: verbinden - verbond - verbonden. Nicht trennbar. Konstruktion 'verbinden met' = verbinden mit.","conjugation":{"presens":{"ik":"verbind","jij":"verbindt","hij":"verbindt","wij":"verbinden"},"imperfectum":{"ik":"verbond","wij":"verbonden"},"perfectum":{"aux":"hebben","participle":"verbonden"}}},"bk_2193":{"lemma":"aansluiten","displayNl":"aansluiten","pos":"werkwoord","meanings":[{"de":"anschließen (Gerät/Kabel)","ex":"Sluit de printer aan op de laptop.","exDe":"Schließe den Drucker an den Laptop an."},{"de":"sich anschließen, beitreten","ex":"Ik wil me graag bij jullie groep aansluiten.","exDe":"Ich möchte mich gern eurer Gruppe anschließen."},{"de":"anschließen, passen zu, übergehen in","ex":"Deze cursus sluit goed aan bij mijn niveau.","exDe":"Dieser Kurs schließt gut an mein Niveau an."}],"usage":"Trennbar (aan|sluiten), starkes Verb: sluiten - sloot - gesloten. 'aansluiten op' für Geräte, 'zich aansluiten bij' für Gruppen.","conjugation":{"presens":{"ik":"sluit aan","jij":"sluit aan","hij":"sluit aan","wij":"sluiten aan"},"imperfectum":{"ik":"sloot aan","wij":"sloten aan"},"perfectum":{"aux":"hebben","participle":"aangesloten"}}},"bk_2194":{"lemma":"instellen","displayNl":"instellen","pos":"werkwoord","meanings":[{"de":"einstellen, einrichten (Gerät)","ex":"Ik moet mijn nieuwe telefoon nog instellen.","exDe":"Ich muss mein neues Handy noch einrichten."},{"de":"festlegen, einführen, einsetzen (Untersuchung/Regelung)","ex":"De school stelt nieuwe regels in.","exDe":"Die Schule führt neue Regeln ein."}],"usage":"Trennbar (in|stellen), regelmäßig. Technisch (Gerät konfigurieren) und formell (etwas einführen/einsetzen).","conjugation":{"presens":{"ik":"stel in","jij":"stelt in","hij":"stelt in","wij":"stellen in"},"imperfectum":{"ik":"stelde in","wij":"stelden in"},"perfectum":{"aux":"hebben","participle":"ingesteld"}}},"bk_2195":{"lemma":"aanpassen","displayNl":"aanpassen","pos":"werkwoord","meanings":[{"de":"anpassen, ändern","ex":"Je kunt de instellingen makkelijk aanpassen.","exDe":"Du kannst die Einstellungen leicht anpassen."},{"de":"sich anpassen, sich einfügen","ex":"Hij past zich snel aan een nieuwe situatie aan.","exDe":"Er passt sich schnell an eine neue Situation an."},{"de":"anprobieren (Kleidung)","ex":"Mag ik deze broek even aanpassen?","exDe":"Darf ich diese Hose kurz anprobieren?"}],"usage":"Trennbar (aan|passen), regelmäßig. Reflexiv 'zich aanpassen' = sich anpassen.","conjugation":{"presens":{"ik":"pas aan","jij":"past aan","hij":"past aan","wij":"passen aan"},"imperfectum":{"ik":"paste aan","wij":"pasten aan"},"perfectum":{"aux":"hebben","participle":"aangepast"}}},"bk_2196":{"lemma":"reageren","displayNl":"reageren","pos":"werkwoord","meanings":[{"de":"reagieren","ex":"Hij reageert rustig op de kritiek.","exDe":"Er reagiert ruhig auf die Kritik."},{"de":"kommentieren, antworten (auf einen Beitrag)","ex":"Veel mensen reageren op het bericht.","exDe":"Viele Leute kommentieren den Beitrag."}],"usage":"Regelmäßig. Konstruktion 'reageren op' = reagieren auf / antworten auf.","conjugation":{"presens":{"ik":"reageer","jij":"reageert","hij":"reageert","wij":"reageren"},"imperfectum":{"ik":"reageerde","wij":"reageerden"},"perfectum":{"aux":"hebben","participle":"gereageerd"}}},"bk_2197":{"lemma":"opnemen","displayNl":"opnemen","pos":"werkwoord","meanings":[{"de":"aufnehmen (Video/Audio)","ex":"Ik neem het programma op.","exDe":"Ich nehme die Sendung auf."},{"de":"(das Telefon) abnehmen, rangehen","ex":"Neem je telefoon eens op!","exDe":"Geh doch mal ans Telefon!"},{"de":"aufnehmen (in Gruppe/Krankenhaus)","ex":"Ze nemen hem op in het ziekenhuis.","exDe":"Sie nehmen ihn im Krankenhaus auf."},{"de":"abheben (Geld)","ex":"Ik neem wat geld op bij de pinautomaat.","exDe":"Ich hebe etwas Geld am Geldautomaten ab."}],"usage":"Trennbar (op|nemen), starkes Verb: nemen - nam - genomen. Sehr polysem: aufnehmen, ans Telefon gehen, (Geld) abheben.","conjugation":{"presens":{"ik":"neem op","jij":"neemt op","hij":"neemt op","wij":"nemen op"},"imperfectum":{"ik":"nam op","wij":"namen op"},"perfectum":{"aux":"hebben","participle":"opgenomen"}}},"bk_2198":{"lemma":"publiceren","displayNl":"publiceren","pos":"werkwoord","meanings":[{"de":"veröffentlichen (in Druck/Medien herausgeben)","ex":"De krant publiceert het artikel morgen.","exDe":"Die Zeitung veröffentlicht den Artikel morgen."},{"de":"publizieren, (wissenschaftlich) erscheinen lassen","ex":"De onderzoeker wil zijn resultaten publiceren in een tijdschrift.","exDe":"Der Forscher möchte seine Ergebnisse in einer Fachzeitschrift publizieren."}],"usage":"Regelmäßiges Verb; kein trennbares Präfix. Objekt meist Text/Werk (artikel, boek, foto).","conjugation":{"presens":{"ik":"publiceer","jij":"publiceert","hij":"publiceert","wij":"publiceren"},"imperfectum":{"ik":"publiceerde","wij":"publiceerden"},"perfectum":{"aux":"hebben","participle":"gepubliceerd"}}},"bk_2199":{"lemma":"vastlopen","displayNl":"vastlopen","pos":"werkwoord","meanings":[{"de":"abstürzen, sich aufhängen (Computer/Technik)","ex":"Mijn computer is vastgelopen.","exDe":"Mein Computer ist abgestürzt."},{"de":"steckenbleiben, festfahren (auch übertragen: nicht weiterkommen)","ex":"De onderhandelingen zijn helemaal vastgelopen.","exDe":"Die Verhandlungen sind völlig festgefahren."},{"de":"sich festfahren (im Verkehr/Schlamm steckenbleiben)","ex":"De auto liep vast in de modder.","exDe":"Das Auto fuhr sich im Schlamm fest."}],"usage":"Trennbares Verb (vast + lopen); Perfekt mit zijn (Zustandsänderung). Unregelmäßig: lopen → liep, gelopen.","conjugation":{"presens":{"ik":"loop vast","jij":"loopt vast","hij":"loopt vast","wij":"lopen vast"},"imperfectum":{"ik":"liep vast","wij":"liepen vast"},"perfectum":{"aux":"zijn","participle":"vastgelopen"}}},"bk_2200":{"lemma":"opstarten","displayNl":"opstarten","pos":"werkwoord","meanings":[{"de":"starten, hochfahren (Computer/Programm)","ex":"Start de computer opnieuw op.","exDe":"Starte den Computer neu."},{"de":"in Gang setzen, anlaufen lassen (Projekt/Prozess)","ex":"We willen volgend jaar een nieuw project opstarten.","exDe":"Wir wollen nächstes Jahr ein neues Projekt in Gang setzen."}],"usage":"Trennbares Verb (op + starten). Roheintrag \"opnieuw opstarten\" = neu starten; opnieuw ist ein zusätzliches Adverb, Kopf-Lemma ist opstarten.","conjugation":{"presens":{"ik":"start op","jij":"start op","hij":"start op","wij":"starten op"},"imperfectum":{"ik":"startte op","wij":"startten op"},"perfectum":{"aux":"hebben","participle":"opgestart"}}},"bk_2201":{"lemma":"journalist","displayNl":"de journalist","pos":"substantief","meanings":[{"de":"der Journalist (Person, die für Presse/Medien berichtet)","ex":"De journalist schrijft over politiek.","exDe":"Der Journalist schreibt über Politik."}],"usage":"Personenbezeichnung; weibliche Form journaliste. Plural journalisten.","genus":"de","plural":"journalisten","illustratable":true},"bk_2202":{"lemma":"interview","displayNl":"het interview","pos":"substantief","meanings":[{"de":"das Interview (Befragung durch Journalisten/Medien)","ex":"Het interview duurde een uur.","exDe":"Das Interview dauerte eine Stunde."},{"de":"das Vorstellungsgespräch, Bewerbungsgespräch (Kontext Arbeit)","ex":"Ik heb morgen een interview voor een nieuwe baan.","exDe":"Ich habe morgen ein Vorstellungsgespräch für eine neue Stelle."}],"usage":"Sächlich (het); Plural interviews mit -s. Verb: iemand interviewen.","genus":"het","plural":"interviews","illustratable":true},"bk_2203":{"lemma":"uitzending","displayNl":"de uitzending","pos":"substantief","meanings":[{"de":"die Sendung, Ausstrahlung (Radio/Fernsehen)","ex":"De uitzending begint om acht uur.","exDe":"Die Sendung beginnt um acht Uhr."},{"de":"die Übertragung (live gesendetes Ereignis)","ex":"De wedstrijd was een rechtstreekse uitzending.","exDe":"Das Spiel war eine Live-Übertragung."},{"de":"die Entsendung (z. B. von Soldaten/Personal ins Ausland)","ex":"Zijn uitzending naar het buitenland duurde zes maanden.","exDe":"Seine Entsendung ins Ausland dauerte sechs Monate."}],"usage":"Von uitzenden abgeleitet. Häufig live uitzending, rechtstreekse uitzending. Plural uitzendingen.","genus":"de","plural":"uitzendingen"},"bk_2204":{"lemma":"kijker","displayNl":"de kijker","pos":"substantief","meanings":[{"de":"der Zuschauer, der Zuseher (Person, die fernsieht/zuschaut)","ex":"De kijkers vonden de film mooi.","exDe":"Die Zuschauer fanden den Film schön."},{"de":"der Betrachter (Person, die etwas ansieht)","ex":"De kijker ziet meteen wat er op het schilderij gebeurt.","exDe":"Der Betrachter erkennt sofort, was auf dem Gemälde geschieht."},{"de":"das Fernglas (meist verrekijker; kijker verkürzt)","ex":"Met een kijker kun je de vogels van dichtbij zien.","exDe":"Mit einem Fernglas kann man die Vögel aus der Nähe sehen."}],"usage":"Von kijken abgeleitet. Meist Zuschauer/Betrachter; als Gerät kurz für verrekijker. Plural kijkers.","genus":"de","plural":"kijkers","illustratable":true},"bk_2205":{"lemma":"luisteraar","displayNl":"de luisteraar","pos":"substantief","meanings":[{"de":"der Zuhörer, der Hörer (Person, die Radio/Musik/Vortrag hört)","ex":"De luisteraars bellen naar de radio.","exDe":"Die Hörer rufen beim Radio an."}],"usage":"Von luisteren abgeleitet. Plural luisteraars. Weibliche Form luisteraarster (selten).","genus":"de","plural":"luisteraars","illustratable":true},"bk_2206":{"lemma":"lezer","displayNl":"de lezer","pos":"substantief","meanings":[{"de":"der Leser (Person, die liest)","ex":"De lezers sturen veel brieven naar de redactie.","exDe":"Die Leser schicken viele Briefe an die Redaktion."},{"de":"das Lesegerät (z. B. Kartenleser, E-Reader)","ex":"Ik lees mijn boeken op een digitale lezer.","exDe":"Ich lese meine Bücher auf einem digitalen Lesegerät."}],"usage":"Meist die Person, die liest; im technischen Kontext auch ein Lesegerät. Plural: lezers.","genus":"de","plural":"lezers","illustratable":true},"bk_2207":{"lemma":"ondertiteling","displayNl":"de ondertiteling","pos":"substantief","meanings":[{"de":"die Untertitelung; der Untertitel (bei Film/TV)","ex":"Ik kijk de film met Nederlandse ondertiteling.","exDe":"Ich schaue den Film mit niederländischen Untertiteln."}],"usage":"Bezeichnet das eingeblendete Text-Zusatzmaterial bei Film/TV. Meist im Singular; Plural: ondertitelingen.","genus":"de","plural":"ondertitelingen"},"bk_2208":{"lemma":"reportage","displayNl":"de reportage","pos":"substantief","meanings":[{"de":"die Reportage (journalistischer Bericht)","ex":"De reportage over de haven was heel interessant.","exDe":"Die Reportage über den Hafen war sehr interessant."}],"usage":"Journalistischer Beitrag in Presse, Radio oder TV. Plural: reportages.","genus":"de","plural":"reportages"},"bk_2209":{"lemma":"beeldscherm","displayNl":"het beeldscherm","pos":"substantief","meanings":[{"de":"der Bildschirm, der Monitor","ex":"Het beeldscherm op mijn bureau is heel groot.","exDe":"Der Monitor auf meinem Schreibtisch ist sehr groß."}],"usage":"Anzeigefläche von Computer, Fernseher oder Gerät. Plural: beeldschermen.","genus":"het","plural":"beeldschermen","illustratable":true},"bk_2210":{"lemma":"webcam","displayNl":"de webcam","pos":"substantief","meanings":[{"de":"die Webcam","ex":"Zet je webcam even aan tijdens de vergadering.","exDe":"Schalte während der Besprechung kurz deine Webcam an."}],"usage":"Kleine Kamera für Video über Computer/Internet. Plural: webcams.","genus":"de","plural":"webcams","illustratable":true},"bk_2211":{"lemma":"videobel","displayNl":"de videobel","pos":"substantief","meanings":[{"de":"der Videoanruf, das Videotelefonat","ex":"Wij hebben elke week een videobel met het team.","exDe":"Wir haben jede Woche einen Videoanruf mit dem Team."}],"usage":"Umgangssprachliches Substantiv zu videobellen (per Video telefonieren). Plural: videobellen.","genus":"de","plural":"videobellen","illustratable":true},"bk_2212":{"lemma":"bedienen","displayNl":"bedienen","pos":"werkwoord","meanings":[{"de":"bedienen (ein Gerät/eine Maschine handhaben)","ex":"Hij kan het toetsenbord heel goed bedienen.","exDe":"Er kann die Tastatur sehr gut bedienen."},{"de":"bedienen (Gäste/Kunden versorgen)","ex":"De ober bedient de gasten op het terras.","exDe":"Der Kellner bedient die Gäste auf der Terrasse."},{"de":"sich einer Sache bedienen; benutzen (zich bedienen van)","ex":"Zij bedient zich van moeilijke woorden.","exDe":"Sie bedient sich schwieriger Wörter."}],"usage":"Ursprüngliche Phrase 'het toetsenbord bedienen' auf den Infinitiv 'bedienen' reduziert. Regelmäßiges Verb, Hilfsverb hebben.","conjugation":{"presens":{"ik":"bedien","jij":"bedient","hij":"bedient","wij":"bedienen"},"imperfectum":{"ik":"bediende","wij":"bedienden"},"perfectum":{"aux":"hebben","participle":"bediend"}},"illustratable":true},"bk_2213":{"lemma":"connectie","displayNl":"de connectie","pos":"substantief","meanings":[{"de":"die Verbindung (technisch, z. B. Netzwerk/Internet)","ex":"De connectie viel plotseling weg.","exDe":"Die Verbindung brach plötzlich ab."},{"de":"die Beziehung, der Kontakt (Personen mit Einfluss)","ex":"Zij heeft goede connecties in de politiek.","exDe":"Sie hat gute Beziehungen in der Politik."}],"usage":"Technische Verbindung oder nützlicher Kontakt/Beziehung. Plural: connecties.","genus":"de","plural":"connecties"},"bk_2214":{"lemma":"betrouwbaar","displayNl":"betrouwbaar","pos":"adjectief","meanings":[{"de":"zuverlässig","ex":"Deze website is betrouwbaar.","exDe":"Diese Webseite ist zuverlässig."},{"de":"vertrauenswürdig, verlässlich","ex":"Hij is een betrouwbare collega.","exDe":"Er ist ein vertrauenswürdiger Kollege."}],"usage":"Prädikativ und attributiv (een betrouwbare bron). Steigerung: betrouwbaarder, betrouwbaarst."},"bk_2215":{"lemma":"praktisch","displayNl":"praktisch","pos":"adjectief","meanings":[{"de":"praktisch, nützlich, zweckmäßig","ex":"Deze app is heel praktisch.","exDe":"Diese App ist sehr praktisch."},{"de":"praktisch, so gut wie, nahezu (adverbial)","ex":"Het werk is praktisch af.","exDe":"Die Arbeit ist praktisch fertig."}],"usage":"Als Adjektiv (een praktische oplossing) und als Adverb im Sinne von 'nahezu'. Gegensatz: theoretisch."},"bk_2216":{"lemma":"ingewikkeld","displayNl":"ingewikkeld","pos":"adjectief","meanings":[{"de":"kompliziert, verwickelt","ex":"Het programma is een beetje ingewikkeld.","exDe":"Das Programm ist etwas kompliziert."},{"de":"komplex, verworren","ex":"Het is een ingewikkelde situatie.","exDe":"Es ist eine komplizierte Situation."}],"usage":"Ursprünglich Partizip von 'inwikkelen'. Gegensatz: eenvoudig, simpel. Steigerung: ingewikkelder."},"bk_2217":{"lemma":"beschikbaar","displayNl":"beschikbaar","pos":"adjectief","meanings":[{"de":"verfügbar, vorhanden","ex":"De update is nu beschikbaar.","exDe":"Das Update ist jetzt verfügbar."},{"de":"erhältlich, frei (Person/Zeit)","ex":"Ben je morgen beschikbaar?","exDe":"Bist du morgen verfügbar?"}],"usage":"Prädikativ häufig (beschikbaar zijn), auch attributiv (de beschikbare plaatsen). Verb: beschikken over."},"bk_2218":{"lemma":"veilig","displayNl":"veilig","pos":"adjectief","meanings":[{"de":"sicher, ungefährlich","ex":"Dit wachtwoord is heel veilig.","exDe":"Dieses Passwort ist sehr sicher."},{"de":"geborgen, in Sicherheit","ex":"Ik voel me hier veilig.","exDe":"Ich fühle mich hier sicher."}],"usage":"Gegensatz: gevaarlijk, onveilig. Substantiv: de veiligheid. Adverb: veilig thuiskomen."},"bk_2219":{"lemma":"waardering","displayNl":"de waardering","pos":"substantief","meanings":[{"de":"Wertschätzung, Anerkennung","ex":"Ik toon mijn waardering.","exDe":"Ich zeige meine Wertschätzung."},{"de":"Bewertung, Benotung","ex":"De film kreeg een hoge waardering.","exDe":"Der Film bekam eine hohe Bewertung."}],"usage":"Von 'waarderen'. Oft im Singular als Wertschätzung; im Plural eher Bewertungen.","genus":"de","plural":"waarderingen"},"bk_2220":{"lemma":"vooroordeel","displayNl":"het vooroordeel","pos":"substantief","meanings":[{"de":"Vorurteil","ex":"Hij heeft veel vooroordelen.","exDe":"Er hat viele Vorurteile."}],"usage":"Zusammensetzung voor + oordeel (Urteil). Plural mit Umlaut der Betonung: vooroordelen.","genus":"het","plural":"vooroordelen"},"bk_2221":{"lemma":"overtuiging","displayNl":"de overtuiging","pos":"substantief","meanings":[{"de":"Überzeugung, feste Meinung","ex":"Dat is mijn overtuiging.","exDe":"Das ist meine Überzeugung."},{"de":"Überzeugtheit, innere Gewissheit","ex":"Hij sprak met veel overtuiging.","exDe":"Er sprach mit großer Überzeugung."}],"usage":"Von 'overtuigen'. Feste Wendung: naar mijn overtuiging (meiner Überzeugung nach).","genus":"de","plural":"overtuigingen"},"bk_2222":{"lemma":"zelfvertrouwen","displayNl":"het zelfvertrouwen","pos":"substantief","meanings":[{"de":"das Selbstvertrauen","ex":"Hij heeft veel zelfvertrouwen.","exDe":"Er hat viel Selbstvertrauen."},{"de":"das Selbstbewusstsein","ex":"Door de training kreeg ze meer zelfvertrouwen.","exDe":"Durch das Training bekam sie mehr Selbstbewusstsein."}],"usage":"Onzijdig, doorgaans ontelbaar (geen meervoud). Vaste combinaties: 'zelfvertrouwen hebben/krijgen/verliezen'.","genus":"het"},"bk_2223":{"lemma":"geduld","displayNl":"het geduld","pos":"substantief","meanings":[{"de":"die Geduld","ex":"Mijn geduld is op.","exDe":"Meine Geduld ist zu Ende."},{"de":"die Ausdauer / Nachsicht","ex":"Met een beetje geduld lukt het wel.","exDe":"Mit etwas Geduld klappt es schon."}],"usage":"Onzijdig, ontelbaar (geen meervoud). Vaste uitdrukkingen: 'geduld hebben', 'geduld oefenen', 'mijn geduld is op'.","genus":"het"},"bk_2224":{"lemma":"teleurstelling","displayNl":"de teleurstelling","pos":"substantief","meanings":[{"de":"die Enttäuschung","ex":"Het was een grote teleurstelling.","exDe":"Es war eine große Enttäuschung."},{"de":"die Enttäuschende Erfahrung / der Reinfall","ex":"De reis werd één grote teleurstelling.","exDe":"Die Reise wurde eine einzige Enttäuschung."}],"usage":"De-woord, meervoud 'teleurstellingen'. Zowel het gevoel als de teleurstellende gebeurtenis.","genus":"de","plural":"teleurstellingen"},"bk_2225":{"lemma":"woede","displayNl":"de woede","pos":"substantief","meanings":[{"de":"die Wut","ex":"Zijn woede was groot.","exDe":"Seine Wut war groß."},{"de":"der Zorn / die Rage","ex":"In blinde woede sloeg hij op tafel.","exDe":"In blinder Wut schlug er auf den Tisch."}],"usage":"De-woord, doorgaans ontelbaar (geen gangbaar meervoud). Vaste combinaties: 'in woede ontsteken', 'blinde woede'.","genus":"de"},"bk_2226":{"lemma":"verdriet","displayNl":"het verdriet","pos":"substantief","meanings":[{"de":"die Trauer","ex":"Zij deelt haar verdriet.","exDe":"Sie teilt ihre Trauer."},{"de":"der Kummer / das Leid","ex":"Het kind huilde van verdriet.","exDe":"Das Kind weinte vor Kummer."}],"usage":"Onzijdig, meestal ontelbaar (geen gangbaar meervoud). Vaste combinaties: 'verdriet hebben', 'verdriet doen'.","genus":"het"},"bk_2227":{"lemma":"jaloezie","displayNl":"de jaloezie","pos":"substantief","meanings":[{"de":"die Eifersucht","ex":"Jaloezie is een sterk gevoel.","exDe":"Eifersucht ist ein starkes Gefühl."},{"de":"der Neid","ex":"Uit jaloezie gunde hij haar het succes niet.","exDe":"Aus Neid gönnte er ihr den Erfolg nicht."},{"de":"die Jalousie / das Rollo (Sonnenschutz)","ex":"Ze liet de jaloezie voor het raam zakken.","exDe":"Sie ließ die Jalousie vor dem Fenster herunter."}],"usage":"De-woord. Als gevoel (afgunst/eifersucht) meestal ontelbaar; als raambedekking telbaar, meervoud 'jaloezieën'.","genus":"de","plural":"jaloezieën"},"bk_2228":{"lemma":"schaamte","displayNl":"de schaamte","pos":"substantief","meanings":[{"de":"die Scham","ex":"Hij voelde diepe schaamte.","exDe":"Er fühlte tiefe Scham."},{"de":"das Schamgefühl / die Peinlichkeit","ex":"Uit schaamte durfde ze niemand aan te kijken.","exDe":"Aus Scham traute sie sich niemanden anzusehen."}],"usage":"De-woord, ontelbaar (geen meervoud). Vaste combinaties: 'schaamte voelen', 'valse schaamte', 'uit schaamte'.","genus":"de"},"bk_2229":{"lemma":"trots","displayNl":"de trots","pos":"substantief","meanings":[{"de":"der Stolz","ex":"Haar trots is groot.","exDe":"Ihr Stolz ist groß."},{"de":"der Hochmut / die Überheblichkeit (negativ)","ex":"Zijn trots stond een verontschuldiging in de weg.","exDe":"Sein Stolz stand einer Entschuldigung im Weg."}],"usage":"Als zelfstandig naamwoord de-woord, ontelbaar. 'trots' is vaker een bijvoeglijk naamwoord ('trots zijn op iets' = stolz sein auf etwas).","genus":"de"},"bk_2230":{"lemma":"medelijden","displayNl":"het medelijden","pos":"substantief","meanings":[{"de":"das Mitleid","ex":"Ik heb medelijden met hem.","exDe":"Ich habe Mitleid mit ihm."},{"de":"das Mitgefühl, das Erbarmen","ex":"Ze toonde medelijden met de zwervers.","exDe":"Sie zeigte Mitgefühl mit den Obdachlosen."}],"usage":"Unzählbar; meist mit 'medelijden hebben met' (Mitleid haben mit).","genus":"het"},"bk_2231":{"lemma":"bewondering","displayNl":"de bewondering","pos":"substantief","meanings":[{"de":"die Bewunderung","ex":"Zijn bewondering is oprecht.","exDe":"Seine Bewunderung ist aufrichtig."},{"de":"die Anerkennung, das Staunen","ex":"Ik kijk met bewondering naar haar werk.","exDe":"Ich betrachte ihre Arbeit mit Bewunderung."}],"usage":"Meist unzählbar; 'bewondering hebben voor' = bewundern.","genus":"de"},"bk_2232":{"lemma":"frustratie","displayNl":"de frustratie","pos":"substantief","meanings":[{"de":"die Frustration, der Frust","ex":"Ik voel veel frustratie.","exDe":"Ich fühle viel Frustration."},{"de":"der Ärger, die Enttäuschung","ex":"Zijn frustraties over het werk namen toe.","exDe":"Sein Ärger über die Arbeit nahm zu."}],"usage":"Sowohl abstrakt (Gefühl) als auch konkret im Plural (einzelne Ärgernisse).","genus":"de","plural":"frustraties"},"bk_2233":{"lemma":"vriendelijkheid","displayNl":"de vriendelijkheid","pos":"substantief","meanings":[{"de":"die Freundlichkeit","ex":"Bedankt voor je vriendelijkheid.","exDe":"Danke für deine Freundlichkeit."},{"de":"die Nettigkeit, die Gefälligkeit","ex":"Ze overlaadde ons met vriendelijkheden.","exDe":"Sie überhäufte uns mit Nettigkeiten."}],"usage":"Abstrakt meist Singular; Plural = einzelne freundliche Gesten/Worte.","genus":"de","plural":"vriendelijkheden"},"bk_2234":{"lemma":"optimistisch","displayNl":"optimistisch","pos":"adjectief","meanings":[{"de":"optimistisch, zuversichtlich","ex":"Zij is heel optimistisch.","exDe":"Sie ist sehr optimistisch."},{"de":"hoffnungsvoll, positiv gestimmt","ex":"We zijn optimistisch over de toekomst.","exDe":"Wir sind optimistisch, was die Zukunft angeht."}],"usage":"Attributiv gebeugt: een optimistische kijk."},"bk_2235":{"lemma":"pessimistisch","displayNl":"pessimistisch","pos":"adjectief","meanings":[{"de":"pessimistisch","ex":"Hij is te pessimistisch.","exDe":"Er ist zu pessimistisch."},{"de":"schwarzseherisch, negativ gestimmt","ex":"Ze heeft een pessimistische kijk op het leven.","exDe":"Sie hat eine pessimistische Sicht auf das Leben."}],"usage":"Gegenteil von optimistisch; attributiv gebeugt: pessimistische verwachtingen."},"bk_2236":{"lemma":"gevoelig","displayNl":"gevoelig","pos":"adjectief","meanings":[{"de":"sensibel, feinfühlig (Person)","ex":"Zij is een gevoelig persoon.","exDe":"Sie ist eine sensible Person."},{"de":"empfindlich (körperlich/technisch)","ex":"Mijn huid is gevoelig voor de zon.","exDe":"Meine Haut ist empfindlich gegenüber der Sonne."},{"de":"heikel, delikat (Thema)","ex":"Dat is een gevoelig onderwerp.","exDe":"Das ist ein heikles Thema."}],"usage":"'gevoelig voor' = empfindlich/anfällig für; attributiv: een gevoelige snaar."},"bk_2237":{"lemma":"koppig","displayNl":"koppig","pos":"adjectief","meanings":[{"de":"stur, dickköpfig","ex":"Hij is te koppig om te luisteren.","exDe":"Er ist zu stur, um zuzuhören."},{"de":"eigensinnig, halsstarrig","ex":"Ze bleef koppig bij haar mening.","exDe":"Sie blieb eigensinnig bei ihrer Meinung."}],"usage":"Beschreibt Charakter; attributiv gebeugt: een koppig kind."},"bk_2238":{"lemma":"onbetrouwbaar","displayNl":"onbetrouwbaar","pos":"adjectief","meanings":[{"de":"unzuverlässig","ex":"Die man is onbetrouwbaar.","exDe":"Dieser Mann ist unzuverlässig."},{"de":"nicht vertrauenswürdig","ex":"De informatie op die website is onbetrouwbaar.","exDe":"Die Informationen auf dieser Website sind nicht vertrauenswürdig."}],"usage":"Charaktereigenschaft/Bewertung; Steigerung: onbetrouwbaarder, onbetrouwbaarst. Attributiv: een onbetrouwbare man."},"bk_2239":{"lemma":"behulpzaam","displayNl":"behulpzaam","pos":"adjectief","meanings":[{"de":"hilfsbereit","ex":"De buren zijn heel behulpzaam.","exDe":"Die Nachbarn sind sehr hilfsbereit."},{"de":"behilflich","ex":"Kunt u mij behulpzaam zijn?","exDe":"Können Sie mir behilflich sein?"}],"usage":"Positive Charaktereigenschaft; Steigerung: behulpzamer, behulpzaamst. Attributiv: een behulpzame collega."},"bk_2240":{"lemma":"ambitieus","displayNl":"ambitieus","pos":"adjectief","meanings":[{"de":"ehrgeizig","ex":"Hij is een ambitieuze jongen.","exDe":"Er ist ein ehrgeiziger Junge."},{"de":"anspruchsvoll (Plan/Ziel)","ex":"Het is een ambitieus project.","exDe":"Es ist ein anspruchsvolles Projekt."}],"usage":"Über Personen (strebsam) und über Vorhaben (hochgesteckt); attributiv: ambitieuze plannen. Steigerung: ambitieuzer, ambitieust."},"bk_2241":{"lemma":"creatief","displayNl":"creatief","pos":"adjectief","meanings":[{"de":"kreativ","ex":"Zij is heel creatief.","exDe":"Sie ist sehr kreativ."},{"de":"einfallsreich/schöpferisch","ex":"Dat is een creatieve oplossing.","exDe":"Das ist eine einfallsreiche Lösung."}],"usage":"Personen und Ideen/Lösungen; attributiv: een creatieve oplossing. Steigerung: creatiever, creatiefst."},"bk_2242":{"lemma":"flexibel","displayNl":"flexibel","pos":"adjectief","meanings":[{"de":"flexibel (anpassungsfähig)","ex":"Wij zijn flexibel met de tijd.","exDe":"Wir sind flexibel mit der Zeit."},{"de":"biegsam/elastisch","ex":"De draad is heel flexibel.","exDe":"Der Draht ist sehr biegsam."}],"usage":"Übertragen (anpassungsfähig, Personen/Zeiten) und konkret (biegsames Material); attributiv: flexibele werktijden. Steigerung: flexibeler, flexibelst."},"bk_2243":{"lemma":"spontaan","displayNl":"spontaan","pos":"adjectief","meanings":[{"de":"spontan","ex":"Hij is heel spontaan.","exDe":"Er ist sehr spontan."},{"de":"unüberlegt/aus dem Moment heraus","ex":"We besloten spontaan om naar zee te gaan.","exDe":"Wir beschlossen spontan, ans Meer zu fahren."}],"usage":"Als Eigenschaft und als Adverb (spontaan iets doen). Steigerung: spontaner, spontaanst."},"bk_2244":{"lemma":"verstandig","displayNl":"verstandig","pos":"adjectief","meanings":[{"de":"vernünftig","ex":"Dat is een verstandige keuze.","exDe":"Das ist eine vernünftige Wahl."},{"de":"klug/besonnen","ex":"Het lijkt me verstandig om nu te stoppen.","exDe":"Es scheint mir klug, jetzt aufzuhören."}],"usage":"Über Entscheidungen und Personen; oft 'het is verstandig om ...'. Steigerung: verstandiger, verstandigst."},"bk_2245":{"lemma":"arrogant","displayNl":"arrogant","pos":"adjectief","meanings":[{"de":"arrogant","ex":"Ik vind hem nogal arrogant.","exDe":"Ich finde ihn ziemlich arrogant."},{"de":"überheblich/hochmütig","ex":"Zijn arrogante houding stoort mij.","exDe":"Seine überhebliche Haltung stört mich."}],"usage":"Negative Charaktereigenschaft; attributiv: een arrogante houding. Steigerung: arroganter, arrogantst."},"bk_2246":{"lemma":"bescheiden","displayNl":"bescheiden","pos":"adjectief","meanings":[{"de":"bescheiden, zurückhaltend","ex":"Zij is een bescheiden vrouw.","exDe":"Sie ist eine bescheidene Frau."},{"de":"gering, mäßig (bescheidenes Maß)","ex":"Ze verdienen een bescheiden inkomen.","exDe":"Sie verdienen ein bescheidenes Einkommen."}],"usage":"Charaktereigenschaft; auch im Sinne von 'gering/mäßig'. Steigerung: bescheidener, bescheidenst."},"bk_2247":{"lemma":"humeurig","displayNl":"humeurig","pos":"adjectief","meanings":[{"de":"launisch, schlecht gelaunt","ex":"Hij is vandaag erg humeurig.","exDe":"Er ist heute sehr launisch."}],"usage":"Beschreibt wechselhafte oder schlechte Stimmung. Steigerung: humeuriger, humeurigst."},"bk_2248":{"lemma":"chagrijnig","displayNl":"chagrijnig","pos":"adjectief","meanings":[{"de":"mürrisch, missmutig, grantig","ex":"Zij is 's ochtends chagrijnig.","exDe":"Sie ist morgens mürrisch."}],"usage":"Umgangssprachlich häufig; beschreibt schlecht gelaunte, verdrießliche Stimmung. Steigerung: chagrijniger, chagrijnigst."},"bk_2249":{"lemma":"opgewekt","displayNl":"opgewekt","pos":"adjectief","meanings":[{"de":"gut gelaunt, fröhlich, munter","ex":"Hij is altijd opgewekt.","exDe":"Er ist immer gut gelaunt."},{"de":"erzeugt, erweckt (Partizip von opwekken, z. B. Strom)","ex":"De opgewekte energie komt van zonnepanelen.","exDe":"Die erzeugte Energie kommt von Solarzellen."}],"usage":"Als Adjektiv 'fröhlich/munter'; formgleich mit dem Partizip von 'opwekken' (erzeugen/erwecken). Steigerung: opgewekter, opgewektst."},"bk_2250":{"lemma":"somber","displayNl":"somber","pos":"adjectief","meanings":[{"de":"düster, trübsinnig, niedergeschlagen","ex":"Zij voelt zich somber.","exDe":"Sie fühlt sich trübsinnig."},{"de":"trüb, düster (Wetter/Atmosphäre)","ex":"Het was een sombere, grijze dag.","exDe":"Es war ein trüber, grauer Tag."}],"usage":"Sowohl für Stimmung als auch für Wetter/Atmosphäre. Steigerung: somberder, somberst."},"bk_2251":{"lemma":"verward","displayNl":"verward","pos":"adjectief","meanings":[{"de":"verwirrt, durcheinander (geistig)","ex":"Ik ben helemaal verward.","exDe":"Ich bin völlig verwirrt."},{"de":"verheddert, verwickelt (Fäden/Haare)","ex":"De draden zaten helemaal verward.","exDe":"Die Fäden waren völlig verheddert."}],"usage":"Als Adjektiv 'verwirrt/durcheinander'; formgleich mit dem Partizip von 'verwarren'. Steigerung: verwarder, verwardst."},"bk_2252":{"lemma":"wanhopig","displayNl":"wanhopig","pos":"adjectief","meanings":[{"de":"verzweifelt","ex":"Hij was bijna wanhopig.","exDe":"Er war fast verzweifelt."},{"de":"verzweifelt, hektisch-bemüht (adverbial)","ex":"Ze zocht wanhopig naar haar sleutels.","exDe":"Sie suchte verzweifelt nach ihren Schlüsseln."}],"usage":"Beschreibt Verzweiflung; auch adverbial ('wanhopig zoeken'). Steigerung: wanhopiger, wanhopigst."},"bk_2253":{"lemma":"geschokt","displayNl":"geschokt","pos":"adjectief","meanings":[{"de":"schockiert, erschüttert","ex":"Wij waren geschokt door het nieuws.","exDe":"Wir waren schockiert über die Nachricht."}],"usage":"Als Adjektiv 'schockiert'; formgleich mit dem Partizip von 'schokken'. Meist mit 'door' (durch/über etwas). Steigerung: geschokter, geschoktst."},"bk_2254":{"lemma":"onder de indruk","displayNl":"onder de indruk","pos":"uitdrukking","meanings":[{"de":"beeindruckt","ex":"Ik ben onder de indruk van jou.","exDe":"Ich bin von dir beeindruckt."},{"de":"angetan (von etwas)","ex":"We waren erg onder de indruk van het concert.","exDe":"Wir waren sehr angetan von dem Konzert."}],"usage":"Feste Wendung mit 'zijn' + 'van': onder de indruk zijn van iets/iemand."},"bk_2255":{"lemma":"beschaamd","displayNl":"beschaamd","pos":"adjectief","meanings":[{"de":"beschämt","ex":"Zij voelde zich beschaamd.","exDe":"Sie fühlte sich beschämt."},{"de":"verlegen, schamvoll","ex":"Hij keek beschaamd naar de grond.","exDe":"Er blickte verlegen zu Boden."},{"de":"enttäuscht (im gehobenen Sinn: 'beschaamd worden' – enttäuscht/getäuscht werden)","ex":"Haar vertrouwen werd niet beschaamd.","exDe":"Ihr Vertrauen wurde nicht enttäuscht."}],"usage":"Prädikativ ('zich beschaamd voelen') und attributiv ('een beschaamde blik')."},"bk_2256":{"lemma":"verontwaardigd","displayNl":"verontwaardigd","pos":"adjectief","meanings":[{"de":"empört, entrüstet","ex":"Hij reageerde verontwaardigd.","exDe":"Er reagierte empört."},{"de":"aufgebracht, ungehalten","ex":"Ze schreef een verontwaardigde brief aan de krant.","exDe":"Sie schrieb einen empörten Brief an die Zeitung."}],"usage":"Oft mit 'over' (verontwaardigd over iets). Attributiv und prädikativ."},"bk_2257":{"lemma":"onverschillig","displayNl":"onverschillig","pos":"adjectief","meanings":[{"de":"gleichgültig, teilnahmslos","ex":"Zij is onverschillig over politiek.","exDe":"Sie ist gleichgültig gegenüber Politik."},{"de":"egal, belanglos ('het is mij onverschillig')","ex":"Het is mij onverschillig wie er wint.","exDe":"Es ist mir gleichgültig, wer gewinnt."}],"usage":"Mit 'over' oder 'voor' für die Sache; unpersönlich 'het is mij onverschillig'."},"bk_2258":{"lemma":"tolerant","displayNl":"tolerant","pos":"adjectief","meanings":[{"de":"tolerant, duldsam","ex":"Wij zijn een tolerante familie.","exDe":"Wir sind eine tolerante Familie."},{"de":"nachsichtig, aufgeschlossen (gegenüber anderen Meinungen/Lebensweisen)","ex":"Amsterdam staat bekend als een tolerante stad.","exDe":"Amsterdam ist als tolerante Stadt bekannt."}],"usage":"Oft mit 'tegenover' (tolerant tegenover anderen)."},"bk_2259":{"lemma":"egoïstisch","displayNl":"egoïstisch","pos":"adjectief","meanings":[{"de":"egoistisch, selbstsüchtig","ex":"Dat gedrag is egoïstisch.","exDe":"Dieses Verhalten ist egoistisch."},{"de":"eigennützig, auf den eigenen Vorteil bedacht","ex":"Hij denkt alleen aan zichzelf, echt egoïstisch.","exDe":"Er denkt nur an sich selbst, wirklich egoistisch."}],"usage":"Attributiv und prädikativ; Trema auf ï beachten (egoïstisch)."},"bk_2260":{"lemma":"moedig","displayNl":"moedig","pos":"adjectief","meanings":[{"de":"mutig, tapfer","ex":"Zij was heel moedig.","exDe":"Sie war sehr mutig."},{"de":"beherzt, kühn","ex":"Het was een moedig besluit om te vertrekken.","exDe":"Es war eine mutige Entscheidung, zu gehen."}],"usage":"Attributiv ('een moedige daad') und prädikativ ('moedig zijn')."},"bk_2261":{"lemma":"laf","displayNl":"laf","pos":"adjectief","meanings":[{"de":"feige","ex":"Dat was een laffe daad.","exDe":"Das war eine feige Tat."},{"de":"fad, geschmacklos (von Essen/Getränken)","ex":"De soep smaakt een beetje laf.","exDe":"Die Suppe schmeckt ein bisschen fad."}],"usage":"Flexion: 'een laffe daad' (Verdopplung des f). Zweite Bedeutung nur bei Speisen/Getränken."},"bk_2262":{"lemma":"beoordelen","displayNl":"beoordelen","pos":"werkwoord","meanings":[{"de":"beurteilen, bewerten","ex":"Je moet mensen niet te snel beoordelen.","exDe":"Man soll Menschen nicht zu schnell beurteilen."},{"de":"benoten, einschätzen (z. B. Leistung)","ex":"De docent moet vijftig toetsen beoordelen.","exDe":"Der Lehrer muss fünfzig Tests benoten."}],"usage":"Regelmäßig, Hilfsverb hebben; untrennbares be-. Objekt = bewertete Person/Sache.","conjugation":{"presens":{"ik":"beoordeel","jij":"beoordeelt","hij":"beoordeelt","wij":"beoordelen"},"imperfectum":{"ik":"beoordeelde","wij":"beoordeelden"},"perfectum":{"aux":"hebben","participle":"beoordeeld"}}},"bk_2263":{"lemma":"waarderen","displayNl":"waarderen","pos":"werkwoord","meanings":[{"de":"wertschätzen, zu schätzen wissen","ex":"Ik waardeer jouw hulp echt.","exDe":"Ich schätze deine Hilfe wirklich."},{"de":"(finanziell) bewerten, einschätzen","ex":"Het huis wordt op vier ton gewaardeerd.","exDe":"Das Haus wird auf vierhunderttausend geschätzt."}],"usage":"Regelmäßig, Hilfsverb hebben. Drückt Wertschätzung/Anerkennung aus.","conjugation":{"presens":{"ik":"waardeer","jij":"waardeert","hij":"waardeert","wij":"waarderen"},"imperfectum":{"ik":"waardeerde","wij":"waardeerden"},"perfectum":{"aux":"hebben","participle":"gewaardeerd"}}},"bk_2264":{"lemma":"bewonderen","displayNl":"bewonderen","pos":"werkwoord","meanings":[{"de":"bewundern","ex":"Ik bewonder haar moed.","exDe":"Ich bewundere ihren Mut."},{"de":"staunend betrachten","ex":"We bewonderden het uitzicht vanaf de toren.","exDe":"Wir bewunderten die Aussicht vom Turm."}],"usage":"Regelmäßig, Hilfsverb hebben; untrennbares be-. Objekt = bewunderte Person/Sache.","conjugation":{"presens":{"ik":"bewonder","jij":"bewondert","hij":"bewondert","wij":"bewonderen"},"imperfectum":{"ik":"bewonderde","wij":"bewonderden"},"perfectum":{"aux":"hebben","participle":"bewonderd"}}},"bk_2265":{"lemma":"haten","displayNl":"haten","pos":"werkwoord","meanings":[{"de":"hassen","ex":"Ik haat het om te wachten.","exDe":"Ich hasse es zu warten."},{"de":"verabscheuen, nicht ausstehen können","ex":"Zij haat spinnen.","exDe":"Sie verabscheut Spinnen."}],"usage":"Regelmäßig, Hilfsverb hebben; Stamm auf -t, daher imperfectum haatte(n). Oft haten om te + infinitief.","conjugation":{"presens":{"ik":"haat","jij":"haat","hij":"haat","wij":"haten"},"imperfectum":{"ik":"haatte","wij":"haatten"},"perfectum":{"aux":"hebben","participle":"gehaat"}}},"bk_2266":{"lemma":"irriteren","displayNl":"irriteren","pos":"werkwoord","meanings":[{"de":"ärgern, nerven, irritieren","ex":"Dat geluid irriteert mij.","exDe":"Dieses Geräusch ärgert mich."},{"de":"sich ärgern (reflexiv: zich irriteren aan)","ex":"Ik irriteer me aan zijn gedrag.","exDe":"Ich ärgere mich über sein Verhalten."},{"de":"reizen (Haut/Schleimhaut)","ex":"De rook irriteert mijn ogen.","exDe":"Der Rauch reizt meine Augen."}],"usage":"Regelmäßig, Hilfsverb hebben. Transitiv (iets irriteert mij) sowie reflexiv (zich irriteren aan).","conjugation":{"presens":{"ik":"irriteer","jij":"irriteert","hij":"irriteert","wij":"irriteren"},"imperfectum":{"ik":"irriteerde","wij":"irriteerden"},"perfectum":{"aux":"hebben","participle":"geïrriteerd"}}},"bk_2267":{"lemma":"zich schamen","displayNl":"zich schamen","pos":"werkwoord","meanings":[{"de":"sich schämen","ex":"Ik schaam me voor mijn fout.","exDe":"Ich schäme mich für meinen Fehler."},{"de":"sich (für jemanden) genieren","ex":"Hij schaamde zich voor zijn ouders.","exDe":"Er genierte sich für seine Eltern."}],"usage":"Reflexives Verb (zich schamen voor/over), Hilfsverb hebben, regelmäßig.","conjugation":{"presens":{"ik":"schaam me","jij":"schaamt je","hij":"schaamt zich","wij":"schamen ons"},"imperfectum":{"ik":"schaamde me","wij":"schaamden ons"},"perfectum":{"aux":"hebben","participle":"geschaamd"}}},"bk_2268":{"lemma":"verbazen","displayNl":"verbazen","pos":"werkwoord","meanings":[{"de":"erstaunen, verwundern","ex":"Dat verbaast mij niet.","exDe":"Das wundert mich nicht."},{"de":"sich wundern, erstaunt sein (reflexiv: zich verbazen over)","ex":"Ik verbaas me over zijn geduld.","exDe":"Ich wundere mich über seine Geduld."}],"usage":"Regelmäßig, Hilfsverb hebben; untrennbares ver-. Transitiv (iets verbaast mij) und reflexiv (zich verbazen over).","conjugation":{"presens":{"ik":"verbaas","jij":"verbaast","hij":"verbaast","wij":"verbazen"},"imperfectum":{"ik":"verbaasde","wij":"verbaasden"},"perfectum":{"aux":"hebben","participle":"verbaasd"}}},"bk_2269":{"lemma":"zich ergeren","displayNl":"zich ergeren","pos":"werkwoord","meanings":[{"de":"sich ärgern (über etwas)","ex":"Ik erger me aan zijn gedrag.","exDe":"Ich ärgere mich über sein Verhalten."},{"de":"genervt/verärgert sein","ex":"Zij ergert zich groen en geel aan het lawaai.","exDe":"Sie ärgert sich schwarz über den Lärm."}],"usage":"Reflexives Verb (zich ergeren aan), Hilfsverb hebben, regelmäßig.","conjugation":{"presens":{"ik":"erger me","jij":"ergert je","hij":"ergert zich","wij":"ergeren ons"},"imperfectum":{"ik":"ergerde me","wij":"ergerden ons"},"perfectum":{"aux":"hebben","participle":"geërgerd"}}},"bk_2270":{"lemma":"blij verrast","displayNl":"blij verrast","pos":"uitdrukking","meanings":[{"de":"angenehm überrascht, freudig überrascht","ex":"Ik was blij verrast door het cadeau.","exDe":"Ich war angenehm überrascht von dem Geschenk."},{"de":"erfreut (über etwas Unerwartetes)","ex":"Ze keek blij verrast op toen hij binnenkwam.","exDe":"Sie blickte freudig überrascht auf, als er hereinkam."}],"usage":"Feste Wendung aus 'blij' (froh) + Partizip 'verrast' (überrascht). Beschreibt eine positive Reaktion auf etwas Unerwartetes; kein eigenes Einzel-Lemma."},"bk_2271":{"lemma":"in de war","displayNl":"in de war","pos":"uitdrukking","meanings":[{"de":"durcheinander, verwirrt (geistig)","ex":"Ik ben helemaal in de war.","exDe":"Ich bin völlig durcheinander."},{"de":"verheddert, verknotet (Haare, Fäden, Kabel)","ex":"De draadjes zitten helemaal in de war.","exDe":"Die Fäden sind völlig verheddert."},{"de":"durcheinandergebracht, in Unordnung","ex":"Door de verhuizing is alles in de war.","exDe":"Durch den Umzug ist alles durcheinandergeraten."}],"usage":"Idiom mit 'de war' (Wirrwarr). Meist 'in de war zijn' (verwirrt sein) oder 'iets in de war brengen/schoppen' (etwas durcheinanderbringen). Kein einzeln flektierbares Lemma."},"bk_2272":{"lemma":"afkeer","displayNl":"de afkeer","pos":"substantief","meanings":[{"de":"die Abneigung, der Widerwille","ex":"Zij heeft een afkeer van spinnen.","exDe":"Sie hat eine Abneigung gegen Spinnen."},{"de":"der Ekel, die Aversion","ex":"Hij voelde een diepe afkeer bij die aanblik.","exDe":"Er empfand tiefen Ekel bei diesem Anblick."}],"usage":"de-Wort, meist im Singular; Plural 'afkeren' selten. Typische Konstruktion 'een afkeer van/tegen iets hebben'. Abstrakt, daher nicht illustrierbar.","genus":"de","plural":"afkeren"},"bk_2273":{"lemma":"nieuwsgierigheid","displayNl":"de nieuwsgierigheid","pos":"substantief","meanings":[{"de":"die Neugier, die Neugierde","ex":"Zijn nieuwsgierigheid was groot.","exDe":"Seine Neugier war groß."},{"de":"das Interesse, die Wissbegier","ex":"Uit pure nieuwsgierigheid opende ze de doos.","exDe":"Aus reiner Neugier öffnete sie die Schachtel."}],"usage":"de-Wort, abstraktes Nomen (auf -heid), praktisch nur im Singular. Nicht bildlich darstellbar.","genus":"de"},"bk_2274":{"lemma":"herinneren","displayNl":"herinneren","pos":"werkwoord","meanings":[{"de":"sich erinnern (zich herinneren)","ex":"Ik herinner me die dag nog goed.","exDe":"Ich erinnere mich noch gut an den Tag."},{"de":"erinnern an, in Erinnerung rufen (iemand herinneren aan)","ex":"Mag ik je herinneren aan de afspraak?","exDe":"Darf ich dich an den Termin erinnern?"}],"usage":"Regelmäßiges Verb, oft reflexiv 'zich herinneren' (sich erinnern) mit 'me/je/zich'. Abstrakter mentaler Vorgang, nicht illustrierbar.","conjugation":{"presens":{"ik":"herinner","jij":"herinnert","hij":"herinnert","wij":"herinneren"},"imperfectum":{"ik":"herinnerde","wij":"herinnerden"},"perfectum":{"aux":"hebben","participle":"herinnerd"}}},"bk_2275":{"lemma":"bedanken","displayNl":"bedanken","pos":"werkwoord","meanings":[{"de":"danken, sich bedanken","ex":"Ik wil de leraar bedanken voor zijn hulp.","exDe":"Ich möchte dem Lehrer für seine Hilfe danken."},{"de":"(zich bedanken voor) dankend ablehnen, absagen","ex":"Hij bedankte voor de uitnodiging.","exDe":"Er lehnte die Einladung dankend ab."}],"usage":"Regelmäßiges Verb; häufig 'iemand bedanken voor iets' oder reflexiv 'zich bedanken voor' (dankend ablehnen). Abstrakter sozialer Akt.","conjugation":{"presens":{"ik":"bedank","jij":"bedankt","hij":"bedankt","wij":"bedanken"},"imperfectum":{"ik":"bedankte","wij":"bedankten"},"perfectum":{"aux":"hebben","participle":"bedankt"}}},"bk_2276":{"lemma":"bedoelen","displayNl":"bedoelen","pos":"werkwoord","meanings":[{"de":"meinen, sagen wollen","ex":"Wat bedoel je precies?","exDe":"Was meinst du genau?"},{"de":"beabsichtigen, bezwecken","ex":"Zo had ik het niet bedoeld.","exDe":"So hatte ich es nicht gemeint."}],"usage":"Regelmäßiges Verb. 'Wat bedoel je?' = Was meinst du?; 'iets goed/verkeerd bedoelen' = etwas gut/falsch meinen. Abstrakt, nicht illustrierbar.","conjugation":{"presens":{"ik":"bedoel","jij":"bedoelt","hij":"bedoelt","wij":"bedoelen"},"imperfectum":{"ik":"bedoelde","wij":"bedoelden"},"perfectum":{"aux":"hebben","participle":"bedoeld"}}},"bk_2277":{"lemma":"beloven","displayNl":"beloven","pos":"werkwoord","meanings":[{"de":"versprechen, zusagen","ex":"Ik beloof het je.","exDe":"Ich verspreche es dir."},{"de":"verheißen, erwarten lassen (in Aussicht stellen)","ex":"Het belooft een mooie dag te worden.","exDe":"Es verspricht ein schöner Tag zu werden."}],"usage":"Regelmäßiges Verb. 'iemand iets beloven' = jemandem etwas versprechen; unpersönlich 'het belooft ...' = es verspricht/lässt erwarten. Abstrakt, nicht illustrierbar.","conjugation":{"presens":{"ik":"beloof","jij":"belooft","hij":"belooft","wij":"beloven"},"imperfectum":{"ik":"beloofde","wij":"beloofden"},"perfectum":{"aux":"hebben","participle":"beloofd"}}},"bk_2278":{"lemma":"besluiten","displayNl":"besluiten","pos":"werkwoord","meanings":[{"de":"beschließen, sich entschließen","ex":"Wij besluiten te blijven.","exDe":"Wir beschließen zu bleiben."},{"de":"beenden, abschließen (eine Sitzung/Rede)","ex":"De voorzitter besluit de vergadering.","exDe":"Der Vorsitzende beendet die Sitzung."}],"usage":"Stark konjugiertes Verb (besluiten - besloot - besloten). Häufig mit 'te' + Infinitiv oder 'tot' (tot iets besluiten).","conjugation":{"presens":{"ik":"besluit","jij":"besluit","hij":"besluit","wij":"besluiten"},"imperfectum":{"ik":"besloot","wij":"besloten"},"perfectum":{"aux":"hebben","participle":"besloten"}}},"bk_2279":{"lemma":"bespreken","displayNl":"bespreken","pos":"werkwoord","meanings":[{"de":"besprechen, erörtern","ex":"Wij bespreken het plan.","exDe":"Wir besprechen den Plan."},{"de":"reservieren, buchen (Plätze/Karten)","ex":"Ik wil twee plaatsen bespreken.","exDe":"Ich möchte zwei Plätze reservieren."}],"usage":"Stark konjugiert (bespreken - besprak - besproken). Kein 'ge-' im Partizip wegen Vorsilbe 'be-'.","conjugation":{"presens":{"ik":"bespreek","jij":"bespreekt","hij":"bespreekt","wij":"bespreken"},"imperfectum":{"ik":"besprak","wij":"bespraken"},"perfectum":{"aux":"hebben","participle":"besproken"}}},"bk_2280":{"lemma":"herkennen","displayNl":"herkennen","pos":"werkwoord","meanings":[{"de":"erkennen, wiedererkennen","ex":"Ik herken haar stem.","exDe":"Ich erkenne ihre Stimme."},{"de":"(sich) wiederfinden in, nachvollziehen","ex":"Ik herken me daar helemaal in.","exDe":"Ich finde mich darin völlig wieder."}],"usage":"Schwach konjugiert. Kein 'ge-' im Partizip wegen unbetonter Vorsilbe 'her-'. Reflexiv 'zich herkennen in' = sich wiederfinden in.","conjugation":{"presens":{"ik":"herken","jij":"herkent","hij":"herkent","wij":"herkennen"},"imperfectum":{"ik":"herkende","wij":"herkenden"},"perfectum":{"aux":"hebben","participle":"herkend"}}},"bk_2281":{"lemma":"verwachten","displayNl":"verwachten","pos":"werkwoord","meanings":[{"de":"erwarten, rechnen mit","ex":"Ik verwacht bezoek.","exDe":"Ich erwarte Besuch."},{"de":"(ein Baby) erwarten","ex":"Ze verwacht haar eerste kind.","exDe":"Sie erwartet ihr erstes Kind."}],"usage":"Schwach; Stamm endet auf 't', daher Imperfekt mit doppeltem 't' (verwachtte). Kein 'ge-' im Partizip wegen 'ver-'.","conjugation":{"presens":{"ik":"verwacht","jij":"verwacht","hij":"verwacht","wij":"verwachten"},"imperfectum":{"ik":"verwachtte","wij":"verwachtten"},"perfectum":{"aux":"hebben","participle":"verwacht"}}},"bk_2282":{"lemma":"voorstellen","displayNl":"voorstellen","pos":"werkwoord","meanings":[{"de":"vorschlagen","ex":"Ik stel voor om samen te gaan.","exDe":"Ich schlage vor, zusammen zu gehen."},{"de":"(jemanden) vorstellen, bekannt machen","ex":"Mag ik je mijn broer voorstellen?","exDe":"Darf ich dir meinen Bruder vorstellen?"},{"de":"sich etwas vorstellen (zich voorstellen)","ex":"Dat kan ik me goed voorstellen.","exDe":"Das kann ich mir gut vorstellen."}],"usage":"Trennbares Verb (voor + stellen), schwach konjugiert. Partizip 'voorgesteld' mit 'ge-' zwischen Vorsilbe und Stamm. Reflexiv 'zich voorstellen' = sich vorstellen.","conjugation":{"presens":{"ik":"stel voor","jij":"stelt voor","hij":"stelt voor","wij":"stellen voor"},"imperfectum":{"ik":"stelde voor","wij":"stelden voor"},"perfectum":{"aux":"hebben","participle":"voorgesteld"}}},"bk_2283":{"lemma":"afspreken","displayNl":"afspreken","pos":"werkwoord","meanings":[{"de":"sich verabreden, ausmachen","ex":"Wij spreken af om zes uur af.","exDe":"Wir verabreden uns für sechs Uhr."},{"de":"vereinbaren, abmachen","ex":"We hebben een prijs afgesproken.","exDe":"Wir haben einen Preis vereinbart."}],"usage":"Trennbares Verb (af + spreken), stark konjugiert (sprak - gesproken). Partizip 'afgesproken'.","conjugation":{"presens":{"ik":"spreek af","jij":"spreekt af","hij":"spreekt af","wij":"spreken af"},"imperfectum":{"ik":"sprak af","wij":"spraken af"},"perfectum":{"aux":"hebben","participle":"afgesproken"}}},"bk_2284":{"lemma":"opletten","displayNl":"opletten","pos":"werkwoord","meanings":[{"de":"aufpassen, achtgeben","ex":"Let goed op!","exDe":"Pass gut auf!"},{"de":"aufmerksam sein (im Unterricht)","ex":"De leerlingen letten niet op.","exDe":"Die Schüler passen nicht auf."}],"usage":"Trennbares Verb (op + letten), schwach. Stamm 'let' endet auf 't', daher kein zusätzliches '-t' bei jij/hij (jij let op). Partizip 'opgelet'.","conjugation":{"presens":{"ik":"let op","jij":"let op","hij":"let op","wij":"letten op"},"imperfectum":{"ik":"lette op","wij":"letten op"},"perfectum":{"aux":"hebben","participle":"opgelet"}}},"bk_2285":{"lemma":"zorgen","displayNl":"zorgen","pos":"werkwoord","meanings":[{"de":"sorgen für, sich kümmern um (zorgen voor)","ex":"Ik zorg voor de kinderen.","exDe":"Ich sorge für die Kinder."},{"de":"dafür sorgen, dass (zorgen dat)","ex":"Zorg dat je op tijd bent.","exDe":"Sorge dafür, dass du pünktlich bist."},{"de":"sich Sorgen machen (zich zorgen maken)","ex":"Maak je geen zorgen.","exDe":"Mach dir keine Sorgen."}],"usage":"Schwach konjugiert. Feste Verbindungen: 'zorgen voor' (sorgen für), 'zorgen dat' (dafür sorgen dass), 'zich zorgen maken' (sich Sorgen machen).","conjugation":{"presens":{"ik":"zorg","jij":"zorgt","hij":"zorgt","wij":"zorgen"},"imperfectum":{"ik":"zorgde","wij":"zorgden"},"perfectum":{"aux":"hebben","participle":"gezorgd"}}},"bk_2286":{"lemma":"vergelijken","displayNl":"vergelijken","pos":"werkwoord","meanings":[{"de":"vergleichen","ex":"Ik vergelijk de prijzen van de twee winkels.","exDe":"Ich vergleiche die Preise der beiden Geschäfte."},{"de":"gegenüberstellen, in Beziehung setzen","ex":"Je kunt appels niet met peren vergelijken.","exDe":"Man kann Äpfel nicht mit Birnen vergleichen."}],"usage":"Starkes Verb: vergelijken – vergeleek – vergeleken. Konstruktion 'iets met iets vergelijken'.","conjugation":{"presens":{"ik":"vergelijk","jij":"vergelijkt","hij":"vergelijkt","wij":"vergelijken"},"imperfectum":{"ik":"vergeleek","wij":"vergeleken"},"perfectum":{"aux":"hebben","participle":"vergeleken"}}},"bk_2287":{"lemma":"bewaren","displayNl":"bewaren","pos":"werkwoord","meanings":[{"de":"aufbewahren, aufheben, lagern","ex":"Ik bewaar de oude foto's in een doos.","exDe":"Ich bewahre die alten Fotos in einer Kiste auf."},{"de":"bewahren, behalten (Geheimnis, Ruhe)","ex":"Kun je een geheim bewaren?","exDe":"Kannst du ein Geheimnis bewahren?"},{"de":"frisch halten (Lebensmittel)","ex":"Deze kaas kun je in de koelkast bewaren.","exDe":"Diesen Käse kannst du im Kühlschrank aufbewahren."}],"usage":"Schwaches Verb. 'de rust bewaren' = die Ruhe bewahren.","conjugation":{"presens":{"ik":"bewaar","jij":"bewaart","hij":"bewaart","wij":"bewaren"},"imperfectum":{"ik":"bewaarde","wij":"bewaarden"},"perfectum":{"aux":"hebben","participle":"bewaard"}}},"bk_2288":{"lemma":"legen","displayNl":"legen","pos":"werkwoord","meanings":[{"de":"leeren, ausleeren","ex":"Ik leeg de prullenbak elke avond.","exDe":"Ich leere den Mülleimer jeden Abend."},{"de":"austrinken, leer machen (Glas)","ex":"Hij leegde zijn glas in één keer.","exDe":"Er leerte sein Glas in einem Zug."}],"usage":"Schwaches Verb; Stamm 'leeg'. NICHT verwechseln mit 'leggen' (legen/hinlegen).","conjugation":{"presens":{"ik":"leeg","jij":"leegt","hij":"leegt","wij":"legen"},"imperfectum":{"ik":"leegde","wij":"leegden"},"perfectum":{"aux":"hebben","participle":"geleegd"}},"illustratable":true},"bk_2289":{"lemma":"mislukken","displayNl":"mislukken","pos":"werkwoord","meanings":[{"de":"misslingen, scheitern, danebengehen","ex":"De taart is helemaal mislukt.","exDe":"Der Kuchen ist völlig misslungen."},{"de":"fehlschlagen (Plan, Versuch)","ex":"Zijn poging om te stoppen met roken mislukte.","exDe":"Sein Versuch, mit dem Rauchen aufzuhören, schlug fehl."}],"usage":"Schwaches Verb, Perfekt mit 'zijn' (Zustandsänderung). Meist unpersönlich/ohne Subjekt-Handelnden.","conjugation":{"presens":{"ik":"misluk","jij":"mislukt","hij":"mislukt","wij":"mislukken"},"imperfectum":{"ik":"mislukte","wij":"mislukten"},"perfectum":{"aux":"zijn","participle":"mislukt"}}},"bk_2290":{"lemma":"klagen","displayNl":"klagen","pos":"werkwoord","meanings":[{"de":"sich beschweren, klagen (über)","ex":"Hij klaagt de hele dag over het weer.","exDe":"Er beschwert sich den ganzen Tag über das Wetter."},{"de":"jammern, wehklagen","ex":"Ze klaagde van de pijn.","exDe":"Sie jammerte vor Schmerz."}],"usage":"Schwaches Verb. 'klagen over iets' = sich über etwas beschweren.","conjugation":{"presens":{"ik":"klaag","jij":"klaagt","hij":"klaagt","wij":"klagen"},"imperfectum":{"ik":"klaagde","wij":"klaagden"},"perfectum":{"aux":"hebben","participle":"geklaagd"}}},"bk_2291":{"lemma":"waarschuwen","displayNl":"waarschuwen","pos":"werkwoord","meanings":[{"de":"warnen, verwarnen","ex":"Ik waarschuw je: dat is gevaarlijk.","exDe":"Ich warne dich: das ist gefährlich."},{"de":"benachrichtigen, alarmieren (Hilfe rufen)","ex":"Waarschuw meteen de politie!","exDe":"Verständige sofort die Polizei!"}],"usage":"Schwaches Verb. 'iemand waarschuwen voor iets' = jemanden vor etwas warnen.","conjugation":{"presens":{"ik":"waarschuw","jij":"waarschuwt","hij":"waarschuwt","wij":"waarschuwen"},"imperfectum":{"ik":"waarschuwde","wij":"waarschuwden"},"perfectum":{"aux":"hebben","participle":"gewaarschuwd"}}},"bk_2292":{"lemma":"weigeren","displayNl":"weigeren","pos":"werkwoord","meanings":[{"de":"sich weigern, ablehnen, verweigern","ex":"Zij weigert te helpen.","exDe":"Sie weigert sich zu helfen."},{"de":"versagen, nicht funktionieren (Motor, Gerät)","ex":"De motor weigerde in de kou.","exDe":"Der Motor versagte in der Kälte."}],"usage":"Schwaches Verb. 'weigeren te + Infinitiv' = sich weigern, etwas zu tun.","conjugation":{"presens":{"ik":"weiger","jij":"weigert","hij":"weigert","wij":"weigeren"},"imperfectum":{"ik":"weigerde","wij":"weigerden"},"perfectum":{"aux":"hebben","participle":"geweigerd"}}},"bk_2294":{"lemma":"verbieden","displayNl":"verbieden","pos":"werkwoord","meanings":[{"de":"verbieten, untersagen","ex":"De wet verbiedt dat.","exDe":"Das Gesetz verbietet das."},{"de":"jemandem etwas verbieten","ex":"Mijn ouders verbieden me om laat thuis te komen.","exDe":"Meine Eltern verbieten mir, spät nach Hause zu kommen."}],"usage":"Starkes Verb: verbieden – verbood – verboden. Gegenteil von 'toestaan/toelaten'.","conjugation":{"presens":{"ik":"verbied","jij":"verbiedt","hij":"verbiedt","wij":"verbieden"},"imperfectum":{"ik":"verbood","wij":"verboden"},"perfectum":{"aux":"hebben","participle":"verboden"}}},"bk_2295":{"lemma":"aanraden","displayNl":"aanraden","pos":"werkwoord","meanings":[{"de":"empfehlen","ex":"Ik raad je dit boek aan.","exDe":"Ich empfehle dir dieses Buch."},{"de":"raten (zu etwas), anraten","ex":"De dokter raadt meer rust aan.","exDe":"Der Arzt rät zu mehr Ruhe."}],"usage":"Trennbares Verb (aan + raden). Konstruktion: iemand iets aanraden. Im Nebensatz zusammen: '...dat ik je dit aanraad.'","conjugation":{"presens":{"ik":"raad aan","jij":"raadt aan","hij":"raadt aan","wij":"raden aan"},"imperfectum":{"ik":"raadde aan","wij":"raadden aan"},"perfectum":{"aux":"hebben","participle":"aangeraden"}}},"bk_2296":{"lemma":"bezet","displayNl":"bezet","pos":"adjectief","meanings":[{"de":"besetzt (Platz, Toilette)","ex":"Deze plek is bezet.","exDe":"Dieser Platz ist besetzt."},{"de":"besetzt (Telefonleitung)","ex":"De lijn is bezet, ik bel later terug.","exDe":"Die Leitung ist besetzt, ich rufe später zurück."},{"de":"beschäftigt, ausgelastet","ex":"Volgende week ben ik helemaal bezet.","exDe":"Nächste Woche bin ich völlig ausgebucht."}],"usage":"Ursprünglich Partizip von 'bezetten', wird prädikativ als Adjektiv verwendet. Gegenteil: 'vrij'."},"bk_2297":{"lemma":"vals","displayNl":"vals","pos":"adjectief","meanings":[{"de":"falsch, gefälscht, unecht","ex":"Het geld is vals.","exDe":"Das Geld ist gefälscht."},{"de":"falsch, unrein (Musik/Ton)","ex":"Hij zingt vals.","exDe":"Er singt falsch."},{"de":"gemein, hinterhältig, bissig","ex":"Pas op, dat is een valse hond.","exDe":"Vorsicht, das ist ein bissiger Hund."}],"usage":"Attributiv flektiert 'valse' (de valse sleutel / het valse alarm). Adverbial 'vals' (vals spelen = betrügen/falsch spielen)."},"bk_2298":{"lemma":"smal","displayNl":"smal","pos":"adjectief","meanings":[{"de":"schmal, eng","ex":"Het pad is heel smal.","exDe":"Der Weg ist sehr schmal."}],"usage":"Attributiv flektiert 'smalle' (de smalle straat). Gegenteil: 'breed'. Nicht mit 'dun' (dünn) verwechseln."},"bk_2299":{"lemma":"nergens","displayNl":"nergens","pos":"bijwoord","meanings":[{"de":"nirgendwo, nirgends","ex":"Ik kan mijn sleutels nergens vinden.","exDe":"Ich kann meine Schlüssel nirgendwo finden."},{"de":"nichts (in Verbindung mit Präposition: nergens over/aan)","ex":"Hij denkt nergens aan.","exDe":"Er denkt an nichts."}],"usage":"Negatives Ortsadverb. In Kombination mit Präposition getrennt oder als 'nergens ... over/aan': 'nergens over praten' = über nichts reden. Gegenteil: 'overal'."},"bk_2300":{"lemma":"bijzonder","displayNl":"bijzonder","pos":"adjectief","meanings":[{"de":"besondere(r/s), außergewöhnlich","ex":"Het is een bijzonder huis.","exDe":"Es ist ein besonderes Haus."},{"de":"besonders, ausgesprochen (als Verstärkung)","ex":"Het was een bijzonder mooie dag.","exDe":"Es war ein besonders schöner Tag."}],"usage":"Als Adjektiv attributiv flektiert 'bijzondere'. Als Gradadverb vor Adjektiven verstärkend ('bijzonder aardig'). 'in het bijzonder' = insbesondere."},"bk_2301":{"lemma":"vooral","displayNl":"vooral","pos":"bijwoord","meanings":[{"de":"vor allem, besonders, hauptsächlich","ex":"Ik hou van fruit, vooral appels.","exDe":"Ich mag Obst, vor allem Äpfel."},{"de":"unbedingt, ja (in Aufforderungen/Ratschlägen)","ex":"Doe vooral rustig aan!","exDe":"Lass es ja ruhig angehen!"}],"usage":"Fokusadverb zur Hervorhebung. In Imperativen verstärkt es den Rat/die Aufforderung ('vooral niet doen' = auf keinen Fall tun)."},"bk_2302":{"lemma":"eigenlijk","displayNl":"eigenlijk","pos":"bijwoord","meanings":[{"de":"eigentlich, im Grunde","ex":"Eigenlijk heb ik geen tijd.","exDe":"Eigentlich habe ich keine Zeit."},{"de":"eigentlich (nach dem tatsächlichen Sachverhalt fragend)","ex":"Hoe heet jij eigenlijk?","exDe":"Wie heißt du eigentlich?"}],"usage":"Modales Satzadverb, drückt Einschränkung oder beiläufige Nachfrage aus. Attributives Adjektiv 'eigenlijke' = eigentlich/tatsächlich (de eigenlijke reden)."},"bk_2303":{"lemma":"hoewel","displayNl":"hoewel","pos":"voegwoord","meanings":[{"de":"obwohl","ex":"Hij gaat naar buiten, hoewel het regent.","exDe":"Er geht nach draußen, obwohl es regnet."},{"de":"obgleich, wenngleich","ex":"Hoewel ze moe was, bleef ze doorwerken.","exDe":"Obwohl sie müde war, arbeitete sie weiter."}],"usage":"Onderschikkend voegwoord dat een tegenstelling/toegeving inleidt; de persoonsvorm gaat naar het einde van de bijzin."},"bk_2304":{"lemma":"terwijl","displayNl":"terwijl","pos":"voegwoord","meanings":[{"de":"während (gleichzeitig)","ex":"Ik lees een boek terwijl zij kookt.","exDe":"Ich lese ein Buch, während sie kocht."},{"de":"wohingegen, während (gegensätzlich)","ex":"Hij is rustig, terwijl zijn broer heel druk is.","exDe":"Er ist ruhig, wohingegen sein Bruder sehr lebhaft ist."}],"usage":"Onderschikkend voegwoord: temporeel (gelijktijdigheid) of tegenstellend (contrast tussen twee situaties)."},"bk_2305":{"lemma":"voordat","displayNl":"voordat","pos":"voegwoord","meanings":[{"de":"bevor, ehe","ex":"Bel me voordat je vertrekt.","exDe":"Ruf mich an, bevor du losfährst."}],"usage":"Onderschikkend tijdvoegwoord; leidt de handeling in die later plaatsvindt. Vaak verkort tot 'voor'."},"bk_2306":{"lemma":"nadat","displayNl":"nadat","pos":"voegwoord","meanings":[{"de":"nachdem","ex":"Nadat we hadden gegeten, gingen we weg.","exDe":"Nachdem wir gegessen hatten, gingen wir weg."}],"usage":"Onderschikkend tijdvoegwoord; de bijzin beschrijft wat eerder gebeurde."},"bk_2307":{"lemma":"zodat","displayNl":"zodat","pos":"voegwoord","meanings":[{"de":"sodass, so dass (Folge)","ex":"Het regende hard, zodat de straat onderliep.","exDe":"Es regnete stark, sodass die Straße überschwemmt wurde."},{"de":"damit (Zweck)","ex":"Ik leer elke dag, zodat ik voor het examen slaag.","exDe":"Ich lerne jeden Tag, damit ich die Prüfung bestehe."}],"usage":"Onderschikkend voegwoord van doel of gevolg."},"bk_2308":{"lemma":"sinds","displayNl":"sinds","pos":"voorzetsel","meanings":[{"de":"seit (Präposition)","ex":"Ik woon hier sinds mei.","exDe":"Ich wohne hier seit Mai."},{"de":"seit(dem) (Konjunktion)","ex":"Sinds hij hier woont, is hij gelukkiger.","exDe":"Seitdem er hier wohnt, ist er glücklicher."}],"usage":"Geeft een beginpunt in de tijd aan. Als voorzetsel voor een tijdstip, als voegwoord voor een hele bijzin."},"bk_2309":{"lemma":"tijdens","displayNl":"tijdens","pos":"voorzetsel","meanings":[{"de":"während (Präposition), im Verlauf von","ex":"Tijdens de vergadering ging zijn telefoon af.","exDe":"Während der Besprechung klingelte sein Telefon."}],"usage":"Voorzetsel dat een gebeurtenis of periode aanduidt waarin iets plaatsvindt; wordt gevolgd door een zelfstandig naamwoord, niet door een bijzin."},"bk_2310":{"lemma":"trouwens","displayNl":"trouwens","pos":"bijwoord","meanings":[{"de":"übrigens","ex":"Trouwens, hij heeft gisteren nog gebeld.","exDe":"Übrigens hat er gestern noch angerufen."},{"de":"im Übrigen, nebenbei bemerkt","ex":"Dat is trouwens niet mijn schuld.","exDe":"Das ist im Übrigen nicht meine Schuld."}],"usage":"Bijwoord/tussenwerpsel om iets terloops toe te voegen aan het gesprek."},"bk_2311":{"lemma":"tenminste","displayNl":"tenminste","pos":"bijwoord","meanings":[{"de":"wenigstens, zumindest","ex":"Blijf tenminste even.","exDe":"Bleib wenigstens kurz."},{"de":"immerhin, jedenfalls","ex":"Hij heeft tenminste zijn best gedaan.","exDe":"Er hat sich immerhin bemüht."},{"de":"zumindest (einschränkend: soweit ich weiß)","ex":"Ze komt vanavond, tenminste, dat zei ze.","exDe":"Sie kommt heute Abend, zumindest hat sie das gesagt."}],"usage":"Adverb; grenzt ein oder nennt eine Mindestgröße. Nicht verwechseln mit 'ten minste' (getrennt, veraltet)."},"bk_2312":{"lemma":"handig","displayNl":"handig","pos":"adjectief","meanings":[{"de":"praktisch, handlich, nützlich","ex":"Dat is een handig ding.","exDe":"Das ist ein praktisches Ding."},{"de":"geschickt, gewandt (von Personen)","ex":"Hij is erg handig met zijn handen.","exDe":"Er ist sehr geschickt mit seinen Händen."},{"de":"clever, schlau (Vorgehen)","ex":"Dat was een handige zet.","exDe":"Das war ein cleverer Schachzug."}],"usage":"Adjektiv/Adverb; steigerbar handig/handiger/handigst."},"bk_2313":{"lemma":"duidelijk","displayNl":"duidelijk","pos":"adjectief","meanings":[{"de":"deutlich, klar, verständlich","ex":"De uitleg is duidelijk.","exDe":"Die Erklärung ist deutlich."},{"de":"offensichtlich, eindeutig","ex":"Het is duidelijk dat hij liegt.","exDe":"Es ist offensichtlich, dass er lügt."}],"usage":"Adjektiv/Adverb; Steigerung duidelijk/duidelijker/duidelijkst."},"bk_2314":{"lemma":"voldoende","displayNl":"voldoende","pos":"adjectief","meanings":[{"de":"genügend, ausreichend, genug","ex":"Er is voldoende water.","exDe":"Es gibt genügend Wasser."},{"de":"ausreichend (Schulnote), die Vier (befriedigend/ausreichend)","ex":"Ze haalde een voldoende voor het examen.","exDe":"Sie bekam eine ausreichende Note in der Prüfung."}],"usage":"Meist Adjektiv/Adverb (unveränderlich); als Substantiv 'een voldoende' = ausreichende Schulnote (het/de voldoende, Plural voldoendes)."},"bk_2315":{"lemma":"verschillend","displayNl":"verschillend","pos":"adjectief","meanings":[{"de":"verschieden, unterschiedlich, verschiedenartig","ex":"De kleuren zijn verschillend.","exDe":"Die Farben sind verschieden."},{"de":"verschiedene, mehrere (attributiv, unbestimmte Menge)","ex":"Ik heb verschillende boeken gelezen.","exDe":"Ich habe verschiedene Bücher gelesen."}],"usage":"Adjektiv; attributiv oft im Sinne von 'mehrere'."},"bk_2316":{"lemma":"rechtbank","displayNl":"de rechtbank","pos":"substantief","meanings":[{"de":"das Gericht, das Gerichtsgebäude (erste Instanz)","ex":"De zaak dient morgen bij de rechtbank.","exDe":"Der Fall wird morgen vor Gericht verhandelt."},{"de":"das Gericht als Institution / der Richterstuhl","ex":"De rechtbank sprak hem vrij.","exDe":"Das Gericht sprach ihn frei."}],"usage":"Neutrales Standardwort für das (erstinstanzliche) Gericht; höhere Instanz = 'gerechtshof'.","genus":"de","plural":"rechtbanken","illustratable":true},"bk_2317":{"lemma":"rechtszaak","displayNl":"de rechtszaak","pos":"substantief","meanings":[{"de":"der Prozess, das Gerichtsverfahren, die Rechtssache","ex":"De rechtszaak duurde drie dagen.","exDe":"Der Prozess dauerte drei Tage."},{"de":"der Rechtsstreit, der Fall (vor Gericht)","ex":"Ze begon een rechtszaak tegen haar werkgever.","exDe":"Sie strengte einen Prozess gegen ihren Arbeitgeber an."}],"usage":"Bezeichnet das Verfahren/den Fall; das Gebäude ist 'rechtbank'.","genus":"de","plural":"rechtszaken","illustratable":true},"bk_2318":{"lemma":"misdaad","displayNl":"de misdaad","pos":"substantief","meanings":[{"de":"das Verbrechen, die Straftat","ex":"De politie onderzoekt de misdaad.","exDe":"Die Polizei untersucht das Verbrechen."},{"de":"die Kriminalität (als Phaenomen, ohne Plural)","ex":"De misdaad in de grote stad neemt toe.","exDe":"Die Kriminalitaet in der Grossstadt nimmt zu."}],"usage":"Konkrete Einzeltat = Plural 'misdaden'; im Sinne von Kriminalitaet unzaehlbar.","genus":"de","plural":"misdaden"},"bk_2319":{"lemma":"dader","displayNl":"de dader","pos":"substantief","meanings":[{"de":"der Täter","ex":"De dader werd snel gevonden.","exDe":"Der Täter wurde schnell gefunden."},{"de":"der Urheber, der Verursacher","ex":"De dader van de brand is nog onbekend.","exDe":"Der Verursacher des Brandes ist noch unbekannt."}],"usage":"Person, die eine Straftat begeht; Gegenstück zu 'slachtoffer' (Opfer).","genus":"de","plural":"daders"},"bk_2320":{"lemma":"slachtoffer","displayNl":"het slachtoffer","pos":"substantief","meanings":[{"de":"das Opfer (einer Straftat)","ex":"Het slachtoffer deed aangifte.","exDe":"Das Opfer erstattete Anzeige."},{"de":"das Opfer, der Betroffene (eines Unglücks/einer Katastrophe)","ex":"De aardbeving eiste veel slachtoffers.","exDe":"Das Erdbeben forderte viele Opfer."}],"usage":"Person, die durch eine Tat, einen Unfall oder eine Katastrophe geschädigt wird.","genus":"het","plural":"slachtoffers"},"bk_2321":{"lemma":"getuige","displayNl":"de getuige","pos":"substantief","meanings":[{"de":"der Zeuge (einer Tat/eines Vorfalls)","ex":"De getuige vertelde wat hij zag.","exDe":"Der Zeuge erzählte, was er sah."},{"de":"der Trauzeuge (bei einer Hochzeit)","ex":"Zij was getuige op mijn bruiloft.","exDe":"Sie war Trauzeugin auf meiner Hochzeit."}],"usage":"Auch in der Wendung 'getuige zijn van' (Zeuge von etwas sein) und als Präposition 'getuige' (wie ... zeigt).","genus":"de","plural":"getuigen"},"bk_2323":{"lemma":"onschuldig","displayNl":"onschuldig","pos":"adjectief","meanings":[{"de":"unschuldig (nicht schuldig)","ex":"Hij is onschuldig aan de misdaad.","exDe":"Er ist unschuldig an dem Verbrechen."},{"de":"harmlos, arglos, naiv","ex":"Het was maar een onschuldige opmerking.","exDe":"Es war nur eine harmlose Bemerkung."}],"usage":"Gegenteil von 'schuldig' (schuldig); im übertragenen Sinn auch 'harmlos/arglos'."},"bk_2324":{"lemma":"aangifte","displayNl":"de aangifte","pos":"substantief","meanings":[{"de":"die Anzeige (bei der Polizei)","ex":"Ik doe aangifte van diefstal.","exDe":"Ich erstatte Anzeige wegen Diebstahls."},{"de":"die (Steuer-)Erklärung, Anmeldung","ex":"De aangifte inkomstenbelasting moet voor 1 mei binnen zijn.","exDe":"Die Einkommensteuererklärung muss vor dem 1. Mai eingereicht sein."}],"usage":"Feste Wendung 'aangifte doen' (Anzeige erstatten); auch amtliche Meldung/Erklärung, z. B. 'belastingaangifte'.","genus":"de","plural":"aangiften"},"bk_2325":{"lemma":"diefstal","displayNl":"de diefstal","pos":"substantief","meanings":[{"de":"der Diebstahl","ex":"De diefstal gebeurde 's nachts.","exDe":"Der Diebstahl geschah nachts."}],"usage":"Straftat des Stehlens; verwandt mit 'stelen' (stehlen) und 'dief' (Dieb).","genus":"de","plural":"diefstallen","illustratable":true},"bk_2326":{"lemma":"toegestaan","displayNl":"toegestaan","pos":"adjectief","meanings":[{"de":"erlaubt, gestattet, zulässig","ex":"Parkeren is hier toegestaan.","exDe":"Parken ist hier erlaubt."}],"usage":"Partizip/Adjektiv zu 'toestaan' (erlauben, gestatten); Gegenteil von 'verboden' (verboten)."},"bk_2327":{"lemma":"gelijkheid","displayNl":"de gelijkheid","pos":"substantief","meanings":[{"de":"die Gleichheit","ex":"Gelijkheid geldt voor iedereen.","exDe":"Gleichheit gilt für alle."},{"de":"die Gleichberechtigung","ex":"Zij strijdt voor gelijkheid tussen mannen en vrouwen.","exDe":"Sie kämpft für die Gleichberechtigung von Männern und Frauen."}],"usage":"Abstrakter Begriff; verwandt mit 'gelijk' (gleich); meist ohne Plural gebraucht.","genus":"de"},"bk_2328":{"lemma":"plicht","displayNl":"de plicht","pos":"substantief","meanings":[{"de":"die Pflicht","ex":"Belasting betalen is een plicht.","exDe":"Steuern zahlen ist eine Pflicht."},{"de":"die Verpflichtung","ex":"Hij voelt de plicht om zijn ouders te helpen.","exDe":"Er fühlt die Verpflichtung, seinen Eltern zu helfen."}],"usage":"Abstrakter Begriff (moralische/rechtliche Verpflichtung). Feste Wendung: 'zijn plicht doen'.","genus":"de","plural":"plichten"},"bk_2329":{"lemma":"aanvraag","displayNl":"de aanvraag","pos":"substantief","meanings":[{"de":"der Antrag","ex":"Ik dien een aanvraag in.","exDe":"Ich reiche einen Antrag ein."},{"de":"die Anforderung / Bestellung","ex":"Op aanvraag sturen wij de brochure toe.","exDe":"Auf Anfrage senden wir die Broschüre zu."}],"usage":"Verwaltungssprache. Kollokationen: 'een aanvraag indienen/doen'.","genus":"de","plural":"aanvragen"},"bk_2330":{"lemma":"aanvragen","displayNl":"aanvragen","pos":"werkwoord","meanings":[{"de":"beantragen","ex":"Je kunt online een paspoort aanvragen.","exDe":"Du kannst online einen Reisepass beantragen."},{"de":"anfordern / anfragen","ex":"Zij vroeg meer informatie aan bij de gemeente.","exDe":"Sie forderte mehr Informationen bei der Gemeinde an."}],"usage":"Trennbares Verb (aan|vragen); unregelmäßig im Präteritum (vroeg aan). In Nebensätzen zusammen: '...dat ik het aanvraag'.","conjugation":{"presens":{"ik":"vraag aan","jij":"vraagt aan","hij":"vraagt aan","wij":"vragen aan"},"imperfectum":{"ik":"vroeg aan","wij":"vroegen aan"},"perfectum":{"aux":"hebben","participle":"aangevraagd"}}},"bk_2331":{"lemma":"vergunning","displayNl":"de vergunning","pos":"substantief","meanings":[{"de":"die Genehmigung","ex":"Voor de verbouwing heb je een vergunning nodig.","exDe":"Für den Umbau brauchst du eine Genehmigung."},{"de":"die Erlaubnis / Lizenz","ex":"Het café heeft een vergunning om alcohol te verkopen.","exDe":"Das Café hat eine Lizenz, um Alkohol zu verkaufen."}],"usage":"Behördlicher Begriff. Kollokation: 'een vergunning aanvragen/krijgen'.","genus":"de","plural":"vergunningen"},"bk_2332":{"lemma":"ambtenaar","displayNl":"de ambtenaar","pos":"substantief","meanings":[{"de":"der Beamte / die Beamtin","ex":"De ambtenaar helpt mij met de aanvraag.","exDe":"Der Beamte hilft mir mit dem Antrag."}],"usage":"Person im öffentlichen Dienst. Weibliche Form auch 'ambtenaar'; Plural 'ambtenaren' (unregelmäßig).","genus":"de","plural":"ambtenaren","illustratable":true},"bk_2333":{"lemma":"overheid","displayNl":"de overheid","pos":"substantief","meanings":[{"de":"der Staat / die (staatliche) Obrigkeit","ex":"De overheid maakt nieuwe regels.","exDe":"Der Staat macht neue Regeln."},{"de":"die Behörde(n) / die öffentliche Hand","ex":"De lokale overheid investeert in scholen.","exDe":"Die lokale Behörde investiert in Schulen."}],"usage":"Meist ohne Plural gebraucht ('de overheid'); Plural 'overheden' nur bei verschiedenen Verwaltungsebenen. Abstrakter Sammelbegriff, oft mit Singularverb.","genus":"de","plural":"overheden"},"bk_2334":{"lemma":"aangifte","displayNl":"de aangifte belasting","pos":"substantief","meanings":[{"de":"die Steuererklärung","ex":"De aangifte belasting is voor mei klaar.","exDe":"Die Steuererklärung ist vor Mai fertig."},{"de":"die Anzeige / Meldung (bei der Polizei)","ex":"Zij deed aangifte van diefstal bij de politie.","exDe":"Sie erstattete Anzeige wegen Diebstahls bei der Polizei."}],"usage":"Gängiger ist 'belastingaangifte' (ein Wort) oder 'aangifte doen'. Grundwort 'aangifte' bedeutet allgemein Meldung/Anzeige; mit 'belasting' die Steuererklärung. Plural 'aangiften' oder 'aangiftes'.","genus":"de","plural":"aangiften"},"bk_2335":{"lemma":"uitkering","displayNl":"de uitkering","pos":"substantief","meanings":[{"de":"die Sozialleistung / staatliche Unterstützung","ex":"Zij ontvangt een uitkering van de gemeente.","exDe":"Sie erhält eine Sozialleistung von der Gemeinde."},{"de":"die Auszahlung / Zahlung (z. B. Versicherung, Dividende)","ex":"De verzekering deed een uitkering na de schade.","exDe":"Die Versicherung leistete eine Auszahlung nach dem Schaden."}],"usage":"Sozialrechtlicher Begriff ('in de uitkering zitten' = von Sozialhilfe leben); daneben allgemein Geldauszahlung.","genus":"de","plural":"uitkeringen"},"bk_2336":{"lemma":"subsidie","displayNl":"de subsidie","pos":"substantief","meanings":[{"de":"der Zuschuss","ex":"We kregen subsidie voor het project.","exDe":"Wir bekamen einen Zuschuss für das Projekt."},{"de":"die Subvention / Fördermittel","ex":"De overheid verstrekt subsidie aan boeren.","exDe":"Die Regierung gewährt Landwirten Subventionen."},{"de":"die Förderung / der Förderbeitrag","ex":"Zonder subsidie kan het theater niet bestaan.","exDe":"Ohne Förderung kann das Theater nicht bestehen."}],"usage":"Finanz-/Verwaltungsbegriff; oft 'subsidie krijgen/aanvragen/verstrekken'. Abstrakt, kein klares Bildmotiv.","genus":"de","plural":"subsidies"},"bk_2337":{"lemma":"verplicht","displayNl":"verplicht","pos":"adjectief","meanings":[{"de":"verpflichtend / obligatorisch / Pflicht-","ex":"Deze cursus is verplicht.","exDe":"Dieser Kurs ist verpflichtend."},{"de":"verpflichtet / gezwungen (zu etw.)","ex":"Je bent verplicht om je te legitimeren.","exDe":"Du bist verpflichtet, dich auszuweisen."}],"usage":"Adjektiv/Partizip; prädikativ 'verplicht zijn (om) te ...' = verpflichtet sein zu. Attributiv unflektiert vor het-Wort, sonst 'verplichte'. Abstraktes Funktionswort."},"bk_2338":{"lemma":"inschrijving","displayNl":"de inschrijving","pos":"substantief","meanings":[{"de":"die Anmeldung","ex":"De inschrijving is gratis.","exDe":"Die Anmeldung ist kostenlos."},{"de":"die Einschreibung / Registrierung","ex":"De inschrijving in het bevolkingsregister is verplicht.","exDe":"Die Eintragung ins Einwohnerregister ist verpflichtend."},{"de":"die Immatrikulation (Uni)","ex":"De inschrijving voor de universiteit sluit in augustus.","exDe":"Die Immatrikulation an der Universität endet im August."}],"usage":"Nomen zu 'inschrijven'. Verwaltungs-/Verfahrensbegriff; abstrakt, kein eindeutiges Bildmotiv.","genus":"de","plural":"inschrijvingen"},"bk_2339":{"lemma":"verhuizing","displayNl":"de verhuizing","pos":"substantief","meanings":[{"de":"der Umzug (Wohnungswechsel)","ex":"Na de verhuizing geef ik mijn adres door.","exDe":"Nach dem Umzug gebe ich meine Adresse durch."},{"de":"das Umziehen / der Transport der Möbel","ex":"De verhuizing duurde de hele dag.","exDe":"Der Umzug dauerte den ganzen Tag."}],"usage":"Nomen zu 'verhuizen'. Konkret als Umzugsszene darstellbar (Wagen, Kartons, Hebebalken).","genus":"de","plural":"verhuizingen","illustratable":true},"bk_2340":{"lemma":"nationaliteit","displayNl":"de nationaliteit","pos":"substantief","meanings":[{"de":"die Staatsangehörigkeit","ex":"Wat is uw nationaliteit?","exDe":"Was ist Ihre Staatsangehörigkeit?"},{"de":"die Nationalität","ex":"Zij heeft de dubbele nationaliteit.","exDe":"Sie hat die doppelte Staatsangehörigkeit."}],"usage":"Formaler/behördlicher Begriff. Abstrakt, kein eindeutig darstellbares Bildmotiv.","genus":"de","plural":"nationaliteiten"},"bk_2341":{"lemma":"premier","displayNl":"de premier","pos":"substantief","meanings":[{"de":"der Ministerpräsident","ex":"De premier bezoekt Duitsland.","exDe":"Der Ministerpräsident besucht Deutschland."},{"de":"der Premierminister / Regierungschef","ex":"De premier gaf een persconferentie.","exDe":"Der Premierminister gab eine Pressekonferenz."}],"usage":"Politisches Amt/Titel. Abstraktes Rollenwort - würde nur als generische Person dargestellt, daher nicht illustriert.","genus":"de","plural":"premiers"},"bk_2342":{"lemma":"politicus","displayNl":"de politicus","pos":"substantief","meanings":[{"de":"der Politiker","ex":"De politicus beantwoordt vragen.","exDe":"Der Politiker beantwortet Fragen."},{"de":"die Politikerin (weiblich: politica)","ex":"Zij is een bekende politica geworden.","exDe":"Sie ist eine bekannte Politikerin geworden."}],"usage":"Plural 'politici', weibliche Form 'politica'. Abstraktes Rollenwort ohne eindeutiges Bildmotiv.","genus":"de","plural":"politici"},"bk_2343":{"lemma":"kiezer","displayNl":"de kiezer","pos":"substantief","meanings":[{"de":"der Wähler (bei Wahlen)","ex":"De kiezers gaan naar het stembureau.","exDe":"Die Wähler gehen zum Wahllokal."},{"de":"die Wählerin / der Stimmberechtigte","ex":"Veel kiezers zijn nog onbeslist.","exDe":"Viele Wähler sind noch unentschlossen."}],"usage":"Nomen zu 'kiezen'. Konkret als Wähler am Wahllokal/an der Urne darstellbar.","genus":"de","plural":"kiezers","illustratable":true},"bk_2344":{"lemma":"stembureau","displayNl":"het stembureau","pos":"substantief","meanings":[{"de":"das Wahllokal","ex":"Het stembureau in de school opent om half acht.","exDe":"Das Wahllokal in der Schule öffnet um halb acht."},{"de":"der Wahlvorstand (das Wahlkomitee im Lokal)","ex":"Het stembureau telt na sluiting alle stemmen.","exDe":"Der Wahlvorstand zählt nach Schließung alle Stimmen."}],"usage":"Neutrum: het stembureau, Plural stembureaus. Meist der physische Ort, wo man wählt; kann auch das Wahlkomitee bezeichnen.","genus":"het","plural":"stembureaus","illustratable":true},"bk_2345":{"lemma":"democratie","displayNl":"de democratie","pos":"substantief","meanings":[{"de":"die Demokratie (Staats-/Regierungsform)","ex":"Nederland is een parlementaire democratie.","exDe":"Die Niederlande sind eine parlamentarische Demokratie."},{"de":"die Demokratie (demokratisches Prinzip, Mitbestimmung)","ex":"In een democratie telt elke stem.","exDe":"In einer Demokratie zählt jede Stimme."}],"usage":"de-Wort, Plural democratieën. Abstrakter Begriff für Staatsform und demokratisches Prinzip.","genus":"de","plural":"democratieën"},"bk_2346":{"lemma":"parlement","displayNl":"het parlement","pos":"substantief","meanings":[{"de":"das Parlament (Volksvertretung, Institution)","ex":"Het parlement stemt vandaag over de nieuwe wet.","exDe":"Das Parlament stimmt heute über das neue Gesetz ab."},{"de":"das Parlament (Parlamentsgebäude)","ex":"Toeristen maken foto's voor het parlement.","exDe":"Touristen machen Fotos vor dem Parlament."}],"usage":"Neutrum: het parlement, Plural parlementen. Bezeichnet die gesetzgebende Vertretung sowie das Gebäude.","genus":"het","plural":"parlementen","illustratable":true},"bk_2347":{"lemma":"macht","displayNl":"de macht","pos":"substantief","meanings":[{"de":"die Macht (Herrschaftsgewalt, Einfluss)","ex":"De regering heeft veel macht.","exDe":"Die Regierung hat viel Macht."},{"de":"die Macht / Großmacht (mächtiger Staat)","ex":"De grote mogendheden zijn machtige machten in de wereld.","exDe":"Die Großmächte sind mächtige Mächte in der Welt."},{"de":"die Kraft, das Vermögen (etwas zu tun)","ex":"Het staat niet in mijn macht om dat te veranderen.","exDe":"Es steht nicht in meiner Macht, das zu ändern."}],"usage":"de-Wort, Plural machten. Von Herrschaftsgewalt über einen Machtstaat bis zur Fähigkeit/Kraft; abstrakt.","genus":"de","plural":"machten"},"bk_2348":{"lemma":"besluit","displayNl":"het besluit","pos":"substantief","meanings":[{"de":"der Beschluss, die Entscheidung","ex":"Het besluit over de nieuwe school valt vandaag.","exDe":"Die Entscheidung über die neue Schule fällt heute."},{"de":"der Schluss, das Ende (tot besluit = zum Schluss)","ex":"Tot besluit bedankte hij alle gasten.","exDe":"Zum Schluss bedankte er sich bei allen Gästen."}],"usage":"Neutrum: het besluit, Plural besluiten. Meist offizieller Beschluss/Entscheidung; in festen Wendungen auch 'Schluss/Abschluss'.","genus":"het","plural":"besluiten"},"bk_2349":{"lemma":"gemeenteraad","displayNl":"de gemeenteraad","pos":"substantief","meanings":[{"de":"der Gemeinderat, der Stadtrat (kommunales Vertretungsgremium)","ex":"De gemeenteraad vergadert vanavond over het nieuwe park.","exDe":"Der Gemeinderat tagt heute Abend über den neuen Park."}],"usage":"de-Wort, Plural gemeenteraden. Das gewählte Gremium einer niederländischen Gemeinde; abstrakte Institution.","genus":"de","plural":"gemeenteraden"},"bk_2350":{"lemma":"beleid","displayNl":"het beleid","pos":"substantief","meanings":[{"de":"die Politik, das Vorgehen, die Strategie (Handlungslinie)","ex":"Het nieuwe beleid van de gemeente geldt vanaf januari.","exDe":"Die neue Politik der Gemeinde gilt ab Januar."},{"de":"die Umsicht, das Bedacht (met beleid = mit Bedacht)","ex":"Ze pakte de moeilijke situatie met beleid aan.","exDe":"Sie ging die schwierige Situation mit Bedacht an."}],"usage":"Neutrum: het beleid, meist unzählbar (kein gebräuchlicher Plural). 'Politik' im Sinne von Handlungslinie/Strategie, nicht 'politiek' als Fach; auch 'Umsicht'.","genus":"het"},"bk_2351":{"lemma":"aannemen","displayNl":"aannemen","pos":"werkwoord","meanings":[{"de":"verabschieden, annehmen (Gesetz, Antrag, Vorschlag)","ex":"De Tweede Kamer wil de wet snel aannemen.","exDe":"Die Zweite Kammer will das Gesetz schnell verabschieden."},{"de":"annehmen, akzeptieren (Angebot, Paket, Einladung)","ex":"Wil je het pakket voor de buren aannemen?","exDe":"Willst du das Paket für die Nachbarn annehmen?"},{"de":"annehmen, vermuten, voraussetzen","ex":"Ik neem aan dat je morgen komt.","exDe":"Ich nehme an, dass du morgen kommst."},{"de":"einstellen (jemanden für eine Stelle)","ex":"Het bedrijf neemt dit jaar tien nieuwe mensen aan.","exDe":"Die Firma stellt dieses Jahr zehn neue Leute ein."}],"usage":"Trennbares, stark gebeugtes Verb (aan + nemen). Das Rohlemma 'de wet aannemen' ist eine Phrase; Kopf ist das Verb aannemen. Hilfsverb hebben, Partizip aangenomen.","conjugation":{"presens":{"ik":"neem aan","jij":"neemt aan","hij":"neemt aan","wij":"nemen aan"},"imperfectum":{"ik":"nam aan","wij":"namen aan"},"perfectum":{"aux":"hebben","participle":"aangenomen"}}},"bk_2352":{"lemma":"protest","displayNl":"het protest","pos":"substantief","meanings":[{"de":"der Protest, die Protestaktion","ex":"Het protest tegen de plannen was vreedzaam.","exDe":"Der Protest gegen die Pläne war friedlich."},{"de":"der Einspruch, der Widerspruch (formeller Einwand)","ex":"Hij tekende protest aan tegen de beslissing.","exDe":"Er legte Einspruch gegen die Entscheidung ein."}],"usage":"'het protest', mv. 'protesten'. Vaste combinatie: 'protest aantekenen tegen' (Einspruch einlegen).","genus":"het","plural":"protesten","illustratable":true},"bk_2353":{"lemma":"demonstratie","displayNl":"de demonstratie","pos":"substantief","meanings":[{"de":"die Demonstration, der Protestmarsch","ex":"Duizenden mensen liepen mee in de demonstratie.","exDe":"Tausende Menschen liefen bei der Demonstration mit."},{"de":"die Vorführung, die Demonstration (etwas vorführen/zeigen)","ex":"De verkoper gaf een demonstratie van het apparaat.","exDe":"Der Verkäufer gab eine Vorführung des Geräts."}],"usage":"'de demonstratie', mv. 'demonstraties'. Beide Bedeutungen (Protestmarsch en 'iets tonen') gangbaar.","genus":"de","plural":"demonstraties","illustratable":true},"bk_2354":{"lemma":"demonstreren","displayNl":"demonstreren","pos":"werkwoord","meanings":[{"de":"demonstrieren, protestieren (auf die Straße gehen)","ex":"Ze demonstreren voor het klimaat.","exDe":"Sie demonstrieren für das Klima."},{"de":"vorführen, zeigen, demonstrieren (etwas veranschaulichen)","ex":"De docent demonstreert hoe het experiment werkt.","exDe":"Der Lehrer demonstriert, wie das Experiment funktioniert."}],"usage":"Regelmäßig, Hilfsverb 'hebben': 'heeft gedemonstreerd'. 'demonstreren voor/tegen' = protestieren; 'iets demonstreren' = vorführen.","conjugation":{"presens":{"ik":"demonstreer","jij":"demonstreert","hij":"demonstreert","wij":"demonstreren"},"imperfectum":{"ik":"demonstreerde","wij":"demonstreerden"},"perfectum":{"aux":"hebben","participle":"gedemonstreerd"}},"illustratable":true},"bk_2355":{"lemma":"vrijheid van meningsuiting","displayNl":"de vrijheid van meningsuiting","pos":"uitdrukking","meanings":[{"de":"die Meinungsfreiheit, die freie Meinungsäußerung","ex":"Vrijheid van meningsuiting is een grondrecht.","exDe":"Meinungsfreiheit ist ein Grundrecht."}],"usage":"Feste Fügung (grondrecht). Kern 'vrijheid' is de-woord; kein Plural. Vgl. 'meningsuiting' = Meinungsäußerung.","genus":"de"},"bk_2356":{"lemma":"debat","displayNl":"het debat","pos":"substantief","meanings":[{"de":"die Debatte, die Diskussion (geordnete Auseinandersetzung)","ex":"Het debat in de Tweede Kamer was fel.","exDe":"Die Debatte im Parlament war heftig."}],"usage":"'het debat', mv. 'debatten' (Doppel-t). Vaak: 'een debat voeren over' (eine Debatte führen über).","genus":"het","plural":"debatten"},"bk_2357":{"lemma":"maatschappij","displayNl":"de maatschappij","pos":"substantief","meanings":[{"de":"die Gesellschaft (Gemeinschaft der Menschen)","ex":"De maatschappij verandert snel.","exDe":"Die Gesellschaft verändert sich schnell."},{"de":"die Gesellschaft, das Unternehmen (Firma, bes. in Zusammensetzungen)","ex":"Hij werkt bij een grote verzekeringsmaatschappij.","exDe":"Er arbeitet bei einer großen Versicherungsgesellschaft."}],"usage":"'de maatschappij', mv. 'maatschappijen'. Bedeutung 'Unternehmen' vooral in samenstellingen: verzekerings-, luchtvaart-, spoorwegmaatschappij.","genus":"de","plural":"maatschappijen"},"bk_2358":{"lemma":"integratie","displayNl":"de integratie","pos":"substantief","meanings":[{"de":"die Integration, die Eingliederung (in die Gesellschaft)","ex":"Integratie kost tijd en geduld.","exDe":"Integration braucht Zeit und Geduld."}],"usage":"'de integratie'. Plural 'integraties' zeldzaam. Vgl. werkwoord 'integreren'.","genus":"de","plural":"integraties"},"bk_2359":{"lemma":"inburgering","displayNl":"de inburgering","pos":"substantief","meanings":[{"de":"die Einbürgerung, die Eingliederung von Zuwanderern (NL: verpflichtender Prozess mit Sprach- und Landeskunde)","ex":"Ik volg een cursus inburgering.","exDe":"Ich mache einen Einbürgerungskurs."}],"usage":"'de inburgering', normaal geen meervoud. NL-Fachbegriff: inburgeringscursus/-examen; werkwoord 'inburgeren'.","genus":"de"},"bk_2360":{"lemma":"vluchteling","displayNl":"de vluchteling","pos":"substantief","meanings":[{"de":"der Flüchtling; die geflüchtete Person","ex":"De vluchteling zoekt een veilig land.","exDe":"Der Flüchtling sucht ein sicheres Land."},{"de":"der/die Geflüchtete (Person auf der Flucht vor Krieg, Verfolgung oder Not)","ex":"Veel vluchtelingen komen met kleine boten aan.","exDe":"Viele Flüchtlinge kommen mit kleinen Booten an."}],"usage":"Neutraler Begriff für eine Person auf der Flucht; im behördlichen Kontext oft von 'asielzoeker' (noch im Verfahren) und 'statushouder' (anerkannt) unterschieden.","genus":"de","plural":"vluchtelingen","illustratable":true},"bk_2361":{"lemma":"asielzoeker","displayNl":"de asielzoeker","pos":"substantief","meanings":[{"de":"der Asylbewerber, die asylsuchende Person","ex":"De asielzoeker wacht op een besluit.","exDe":"Der Asylbewerber wartet auf eine Entscheidung."},{"de":"Person, die (noch im Verfahren) einen Asylantrag gestellt hat","ex":"De asielzoeker verblijft in een opvangcentrum.","exDe":"Der Asylbewerber wohnt in einem Aufnahmezentrum."}],"usage":"Rechtlich-behoerdlicher Status: jemand, dessen Asylantrag noch laeuft; nach Anerkennung 'statushouder', vor dem Antrag oft 'vluchteling'.","genus":"de","plural":"asielzoekers"},"bk_2362":{"lemma":"asiel","displayNl":"het asiel","pos":"substantief","meanings":[{"de":"das Asyl (Schutz für Verfolgte)","ex":"Hij vraagt asiel aan.","exDe":"Er beantragt Asyl."},{"de":"das Tierheim (dieren-asiel)","ex":"We haalden een kat uit het asiel.","exDe":"Wir holten eine Katze aus dem Tierheim."}],"usage":"'Asiel aanvragen/verlenen' = Asyl beantragen/gewähren; als Kurzform von 'dierenasiel' auch das Tierheim.","genus":"het"},"bk_2363":{"lemma":"migratie","displayNl":"de migratie","pos":"substantief","meanings":[{"de":"die Migration; die Wanderung von Menschen","ex":"Migratie is een politiek thema.","exDe":"Migration ist ein politisches Thema."},{"de":"die Wanderung (von Tieren); der Zug","ex":"De migratie van de vogels begint in de herfst.","exDe":"Der Vogelzug beginnt im Herbst."},{"de":"die Migration (Umzug/Übertragung von Daten, IT)","ex":"De migratie naar het nieuwe systeem duurde een week.","exDe":"Die Migration auf das neue System dauerte eine Woche."}],"usage":"Uebergreifend für Wanderungsbewegungen: Menschen, Tiere und (technisch) Daten/Systeme.","genus":"de","plural":"migraties"},"bk_2364":{"lemma":"discriminatie","displayNl":"de discriminatie","pos":"substantief","meanings":[{"de":"die Diskriminierung; Benachteiligung aufgrund von Merkmalen","ex":"Discriminatie is bij wet verboden.","exDe":"Diskriminierung ist gesetzlich verboten."},{"de":"die Ungleichbehandlung (z. B. wegen Herkunft, Geschlecht, Religion)","ex":"Zij ervoer discriminatie op de arbeidsmarkt.","exDe":"Sie erlebte Diskriminierung auf dem Arbeitsmarkt."}],"usage":"Meist negativ konnotiert; oft mit Praeposition 'op grond van' (aufgrund von) verwendet.","genus":"de","plural":"discriminaties"},"bk_2365":{"lemma":"gelijke behandeling","displayNl":"de gelijke behandeling","pos":"substantief","meanings":[{"de":"die Gleichbehandlung; der gleiche/faire Umgang mit allen","ex":"Iedereen heeft recht op gelijke behandeling.","exDe":"Jeder hat ein Recht auf Gleichbehandlung."}],"usage":"Feste Fuegung (Adjektiv 'gelijk' + 'behandeling', de-woord); zentraler Begriff im Antidiskriminierungsrecht.","genus":"de"},"bk_2366":{"lemma":"solidariteit","displayNl":"de solidariteit","pos":"substantief","meanings":[{"de":"die Solidarität; der Zusammenhalt und die gegenseitige Unterstützung","ex":"Solidariteit houdt de samenleving sterk.","exDe":"Solidarität hält die Gesellschaft stark."},{"de":"die Verbundenheit, das Einstehen füreinander","ex":"Uit solidariteit met de stakers legde iedereen het werk neer.","exDe":"Aus Solidarität mit den Streikenden legten alle die Arbeit nieder."}],"usage":"Abstraktum, in der Regel ohne Plural; haeufig 'solidariteit met' (Solidaritaet mit).","genus":"de"},"bk_2367":{"lemma":"norm","displayNl":"de norm","pos":"substantief","meanings":[{"de":"die Norm; die (soziale) Regel, der Maßstab für Verhalten","ex":"Elke cultuur heeft eigen normen.","exDe":"Jede Kultur hat eigene Normen."},{"de":"der Standard, der Richtwert; die festgelegte Grenze","ex":"De uitstoot ligt boven de wettelijke norm.","exDe":"Der Ausstoß liegt über der gesetzlichen Norm."}],"usage":"Oft in der Wendung 'normen en waarden' (Normen und Werte); zweite Bedeutung als technischer/gesetzlicher Richtwert.","genus":"de","plural":"normen"},"bk_2368":{"lemma":"waarde","displayNl":"de waarde","pos":"substantief","meanings":[{"de":"der Wert (ideeller/moralischer Wert)","ex":"Respect is een belangrijke waarde.","exDe":"Respekt ist ein wichtiger Wert."},{"de":"der Wert (finanzieller/materieller Wert)","ex":"De waarde van het huis is de laatste jaren gestegen.","exDe":"Der Wert des Hauses ist in den letzten Jahren gestiegen."}],"usage":"de-Wort, Plural 'waarden'. Im moralischen Sinn oft im Plural ('normen en waarden').","genus":"de","plural":"waarden"},"bk_2369":{"lemma":"tolerantie","displayNl":"de tolerantie","pos":"substantief","meanings":[{"de":"die Toleranz","ex":"Tolerantie is nodig in een diverse stad.","exDe":"Toleranz ist in einer vielfältigen Stadt nötig."}],"usage":"de-Wort, meist unzählbar. Abstrakter Begriff.","genus":"de"},"bk_2370":{"lemma":"bevolking","displayNl":"de bevolking","pos":"substantief","meanings":[{"de":"die Bevölkerung","ex":"De bevolking van de stad groeit langzaam.","exDe":"Die Bevölkerung der Stadt wächst langsam."}],"usage":"de-Wort, Kollektivbegriff, meist im Singular verwendet.","genus":"de","plural":"bevolkingen"},"bk_2371":{"lemma":"vereniging","displayNl":"de vereniging","pos":"substantief","meanings":[{"de":"der Verein, der Verband","ex":"Hij is lid van een sportvereniging.","exDe":"Er ist Mitglied in einem Sportverein."},{"de":"die Vereinigung, der Zusammenschluss","ex":"De vereniging van de twee partijen leidde tot een grotere beweging.","exDe":"Die Vereinigung der beiden Parteien führte zu einer größeren Bewegung."}],"usage":"de-Wort. Häufigste Bedeutung 'Verein' (Organisation); daneben 'Vereinigung/Zusammenschluss'.","genus":"de","plural":"verenigingen"},"bk_2372":{"lemma":"lidmaatschap","displayNl":"het lidmaatschap","pos":"substantief","meanings":[{"de":"die Mitgliedschaft","ex":"Het lidmaatschap kost tien euro per maand.","exDe":"Die Mitgliedschaft kostet zehn Euro pro Monat."}],"usage":"het-Wort, Plural 'lidmaatschappen'. Abstrakter Begriff.","genus":"het","plural":"lidmaatschappen"},"bk_2373":{"lemma":"vrijwilliger","displayNl":"de vrijwilliger","pos":"substantief","meanings":[{"de":"der/die Freiwillige, ehrenamtliche(r) Helfer(in)","ex":"De vrijwilliger helpt elke week in de bibliotheek.","exDe":"Der Freiwillige hilft jede Woche in der Bibliothek."}],"usage":"de-Wort. Person, die unbezahlt/ehrenamtlich hilft. Weibliche Form: 'vrijwilligster'.","genus":"de","plural":"vrijwilligers","illustratable":true},"bk_2374":{"lemma":"vrijwilligerswerk","displayNl":"het vrijwilligerswerk","pos":"substantief","meanings":[{"de":"die ehrenamtliche Arbeit, Freiwilligenarbeit","ex":"Zij doet vrijwilligerswerk bij het bejaardenhuis.","exDe":"Sie leistet ehrenamtliche Arbeit im Altenheim."}],"usage":"het-Wort, unzählbar (kein Plural). Oft mit 'doen': 'vrijwilligerswerk doen'.","genus":"het","illustratable":true},"bk_2375":{"lemma":"instantie","displayNl":"de instantie","pos":"substantief","meanings":[{"de":"die Behörde, die (zuständige) Stelle","ex":"Neem contact op met de juiste instantie.","exDe":"Nehmen Sie Kontakt mit der richtigen Behörde auf."},{"de":"die Instanz (Stufe, z. B. juristisch)","ex":"Het hoger beroep gaat naar een hogere instantie.","exDe":"Die Berufung geht an eine höhere Instanz."}],"usage":"de-Wort, Plural 'instanties'. Auch in der Wendung 'in eerste instantie' (zunächst).","genus":"de","plural":"instanties"},"bk_2376":{"lemma":"bezwaar","displayNl":"het bezwaar","pos":"substantief","meanings":[{"de":"der Einspruch, der Widerspruch","ex":"U kunt bezwaar maken tegen het besluit.","exDe":"Sie können Einspruch gegen die Entscheidung einlegen."},{"de":"der Einwand, das Bedenken","ex":"Ik heb geen bezwaar tegen dit voorstel.","exDe":"Ich habe keinen Einwand gegen diesen Vorschlag."}],"usage":"Amts-/Rechtssprache; 'bezwaar maken tegen' = Einspruch einlegen gegen. 'geen bezwaar' = kein Einwand/Problem.","genus":"het","plural":"bezwaren"},"bk_2377":{"lemma":"bewijsstuk","displayNl":"het bewijsstuk","pos":"substantief","meanings":[{"de":"der Nachweis, das Belegstück","ex":"Voeg een bewijsstuk toe aan de aanvraag.","exDe":"Fügen Sie einen Nachweis zum Antrag hinzu."},{"de":"das Beweißtück (vor Gericht)","ex":"Het mes is een belangrijk bewijsstuk in de rechtszaak.","exDe":"Das Messer ist ein wichtiges Beweißtück im Prozess."}],"usage":"Zusammengesetzt aus 'bewijs' + 'stuk'; formell, in Behörden- und Gerichtskontexten.","genus":"het","plural":"bewijsstukken"},"bk_2378":{"lemma":"geldigheid","displayNl":"de geldigheid","pos":"substantief","meanings":[{"de":"die Gültigkeit","ex":"De geldigheid van het paspoort is tien jaar.","exDe":"Die Gültigkeit des Reisepasses beträgt zehn Jahre."}],"usage":"Meist im Singular; zu 'geldig' (gültig). Häufig: 'geldigheidsduur' = Gültigkeitsdauer.","genus":"de","plural":"geldigheden"},"bk_2379":{"lemma":"verlengen","displayNl":"verlengen","pos":"werkwoord","meanings":[{"de":"verlängern (zeitlich, z. B. Dokument/Vertrag)","ex":"Ik moet mijn rijbewijs verlengen.","exDe":"Ich muss meinen Führerschein verlängern."},{"de":"verlängern (räumlich, länger machen)","ex":"Ze verlengen de tunnel met honderd meter.","exDe":"Sie verlängern den Tunnel um hundert Meter."}],"usage":"Regelmäßiges Verb; nicht trennbar. Perfekt mit 'hebben', Partizip 'verlengd'.","conjugation":{"presens":{"ik":"verleng","jij":"verlengt","hij":"verlengt","wij":"verlengen"},"imperfectum":{"ik":"verlengde","wij":"verlengden"},"perfectum":{"aux":"hebben","participle":"verlengd"}}},"bk_2380":{"lemma":"termijn","displayNl":"de termijn","pos":"substantief","meanings":[{"de":"die Frist, der Zeitraum","ex":"De termijn eindigt op vrijdag.","exDe":"Die Frist endet am Freitag."},{"de":"die Rate (Teilzahlung)","ex":"We betalen de auto in twaalf termijnen.","exDe":"Wir zahlen das Auto in zwölf Raten."}],"usage":"Formell/administrativ. 'op korte/lange termijn' = kurz-/langfristig; 'in termijnen betalen' = in Raten zahlen.","genus":"de","plural":"termijnen"},"bk_2381":{"lemma":"goedkeuren","displayNl":"goedkeuren","pos":"werkwoord","meanings":[{"de":"genehmigen, billigen","ex":"De gemeente keurt de plannen goed.","exDe":"Die Gemeinde genehmigt die Pläne."},{"de":"gutheißen, für in Ordnung befinden","ex":"De arts keurde hem goed voor de operatie.","exDe":"Der Arzt befand ihn für die Operation für tauglich."}],"usage":"Trennbares Verb (goed + keuren): 'ik keur ... goed'. Perfekt mit 'hebben', Partizip 'goedgekeurd'. Gegenteil: 'afkeuren'.","conjugation":{"presens":{"ik":"keur goed","jij":"keurt goed","hij":"keurt goed","wij":"keuren goed"},"imperfectum":{"ik":"keurde goed","wij":"keurden goed"},"perfectum":{"aux":"hebben","participle":"goedgekeurd"}}},"bk_2382":{"lemma":"afwijzen","displayNl":"afwijzen","pos":"werkwoord","meanings":[{"de":"ablehnen (Antrag, Vorschlag)","ex":"Ze wijzen mijn aanvraag af.","exDe":"Sie lehnen meinen Antrag ab."},{"de":"abweisen, zurückweisen (eine Person)","ex":"Hij werd door haar afgewezen.","exDe":"Er wurde von ihr abgewiesen."}],"usage":"Trennbares Verb (af + wijzen); Stamm 'wijzen' ist stark/unregelmäßig. Perfekt mit 'hebben', Partizip 'afgewezen'. Gegenteil: 'toewijzen/goedkeuren'.","conjugation":{"presens":{"ik":"wijs af","jij":"wijst af","hij":"wijst af","wij":"wijzen af"},"imperfectum":{"ik":"wees af","wij":"wezen af"},"perfectum":{"aux":"hebben","participle":"afgewezen"}}},"bk_2383":{"lemma":"goedkeuring","displayNl":"de goedkeuring","pos":"substantief","meanings":[{"de":"die Genehmigung, die Zustimmung","ex":"We wachten op de goedkeuring.","exDe":"Wir warten auf die Genehmigung."},{"de":"die Billigung, der Beifall","ex":"Zijn plan kreeg de goedkeuring van iedereen.","exDe":"Sein Plan fand die Billigung aller."}],"usage":"Zu 'goedkeuren'. Formell; 'ter goedkeuring' = zur Genehmigung. Gegenteil: 'afkeuring'.","genus":"de","plural":"goedkeuringen"},"bk_2384":{"lemma":"regeling","displayNl":"de regeling","pos":"substantief","meanings":[{"de":"die Regelung, die Vorschrift","ex":"Er komt een nieuwe regeling voor huurders.","exDe":"Es gibt eine neue Regelung für Mieter."},{"de":"die Vereinbarung, die Abmachung","ex":"We hebben een goede regeling getroffen.","exDe":"Wir haben eine gute Vereinbarung getroffen."},{"de":"die Anordnung, das Ordnen (Vorgang)","ex":"De regeling van het verkeer kostte veel tijd.","exDe":"Die Regelung des Verkehrs kostete viel Zeit."}],"usage":"Formell/verwaltungssprachlich; oft im Kontext von Recht, Verwaltung, Versicherungen oder Vereinbarungen.","genus":"de","plural":"regelingen"},"bk_2385":{"lemma":"wetgeving","displayNl":"de wetgeving","pos":"substantief","meanings":[{"de":"die Gesetzgebung, die Gesetze","ex":"De wetgeving verandert regelmatig.","exDe":"Die Gesetzgebung ändert sich regelmäßig."},{"de":"der Gesetzgebungsprozess","ex":"De wetgeving over privacy duurde jaren.","exDe":"Die Gesetzgebung zum Datenschutz dauerte Jahre."}],"usage":"Meist im Singular; Sammelbegriff für die Gesamtheit der Gesetze eines Bereichs.","genus":"de","plural":"wetgevingen"},"bk_2386":{"lemma":"rechtsstaat","displayNl":"de rechtsstaat","pos":"substantief","meanings":[{"de":"der Rechtsstaat","ex":"In een rechtsstaat geldt de wet voor iedereen.","exDe":"In einem Rechtsstaat gilt das Gesetz für alle."}],"usage":"Politisch-juristischer Fachbegriff.","genus":"de","plural":"rechtsstaten"},"bk_2387":{"lemma":"grondwet","displayNl":"de grondwet","pos":"substantief","meanings":[{"de":"die Verfassung (das Grundgesetz)","ex":"De grondwet beschermt onze rechten.","exDe":"Die Verfassung schützt unsere Rechte."}],"usage":"Bezeichnet in NL die Verfassung; wird oft mit dem deutschen \"Grundgesetz\" gleichgesetzt, meint aber allgemein die Verfassung.","genus":"de","plural":"grondwetten"},"bk_2388":{"lemma":"recht op onderwijs","displayNl":"het recht op onderwijs","pos":"uitdrukking","meanings":[{"de":"das Recht auf Bildung","ex":"Elk kind heeft recht op onderwijs.","exDe":"Jedes Kind hat ein Recht auf Bildung."}],"usage":"Feste Fügung aus dem Bereich der Grund- und Menschenrechte; Kopf ist \"het recht\".","genus":"het"},"bk_2389":{"lemma":"mensenrechten","displayNl":"de mensenrechten","pos":"substantief","meanings":[{"de":"die Menschenrechte","ex":"De mensenrechten gelden overal.","exDe":"Die Menschenrechte gelten überall."}],"usage":"Fast ausschließlich im Plural gebraucht; Singular \"het mensenrecht\" ist selten.","genus":"het","plural":"mensenrechten"},"bk_2390":{"lemma":"aansprakelijkheid","displayNl":"de aansprakelijkheid","pos":"substantief","meanings":[{"de":"die Haftung","ex":"De eigenaar draagt de aansprakelijkheid.","exDe":"Der Eigentümer trägt die Haftung."},{"de":"die Verantwortlichkeit, die Zurechenbarkeit","ex":"Zijn aansprakelijkheid voor de fout stond vast.","exDe":"Seine Verantwortlichkeit für den Fehler stand fest."}],"usage":"Juristischer Begriff, besonders im Vertrags-, Schadens- und Versicherungsrecht.","genus":"de","plural":"aansprakelijkheden"},"bk_2391":{"lemma":"vrijwaring","displayNl":"de vrijwaring","pos":"substantief","meanings":[{"de":"die Freistellung (von Haftung/Ansprüchen)","ex":"Het contract regelt de vrijwaring.","exDe":"Der Vertrag regelt die Freistellung."},{"de":"die Gewährleistung (Schutz gegen Ansprüche Dritter)","ex":"De verkoper biedt vrijwaring tegen claims.","exDe":"Der Verkäufer bietet Gewährleistung gegen Ansprüche."},{"de":"die Streitverkündung (Prozessrecht)","ex":"Hij riep de leverancier in vrijwaring op.","exDe":"Er verkündete dem Lieferanten den Streit."}],"usage":"Juristischer Fachbegriff (Vertrags- und Prozessrecht).","genus":"de","plural":"vrijwaringen"},"bk_2393":{"lemma":"bemiddeling","displayNl":"de bemiddeling","pos":"substantief","meanings":[{"de":"die Vermittlung (Schlichtung, Mediation zwischen Parteien)","ex":"De bemiddeling voorkwam een rechtszaak.","exDe":"Die Vermittlung verhinderte einen Prozess."},{"de":"die Vermittlung (Herstellen eines Kontakts, z. B. Job- oder Wohnungsvermittlung)","ex":"Dankzij de bemiddeling van het uitzendbureau vond ze snel werk.","exDe":"Dank der Vermittlung der Zeitarbeitsfirma fand sie schnell Arbeit."}],"usage":"Abstraktes Substantiv aus dem Rechts- und Verwaltungsbereich; oft in Zusammensetzungen wie arbeidsbemiddeling.","genus":"de","plural":"bemiddelingen"},"bk_2394":{"lemma":"vonnis","displayNl":"het vonnis","pos":"substantief","meanings":[{"de":"das Urteil (gerichtliche Entscheidung, meist eines Einzelrichters)","ex":"Het vonnis wordt volgende week uitgesproken.","exDe":"Das Urteil wird nächste Woche verkündet."}],"usage":"Juristischer Begriff: Entscheidung eines Gerichts erster Instanz; das Urteil eines höheren Gerichts heißt 'arrest'.","genus":"het","plural":"vonnissen"},"bk_2395":{"lemma":"veroordelen","displayNl":"veroordelen","pos":"werkwoord","meanings":[{"de":"verurteilen (gerichtlich für schuldig erklären und bestrafen)","ex":"De rechter veroordeelt de dader tot een gevangenisstraf.","exDe":"Der Richter verurteilt den Täter zu einer Gefängnisstrafe."},{"de":"verurteilen (moralisch missbilligen, scharf kritisieren)","ex":"Veel mensen veroordelen zijn gedrag.","exDe":"Viele Menschen verurteilen sein Verhalten."}],"usage":"Untrennbares Verb (Präfix ver-); Partizip ohne ge-.","conjugation":{"presens":{"ik":"veroordeel","jij":"veroordeelt","hij":"veroordeelt","wij":"veroordelen"},"imperfectum":{"ik":"veroordeelde","wij":"veroordeelden"},"perfectum":{"aux":"hebben","participle":"veroordeeld"}}},"bk_2396":{"lemma":"vrijspreken","displayNl":"vrijspreken","pos":"werkwoord","meanings":[{"de":"freisprechen (gerichtlich für nicht schuldig erklären)","ex":"De rechter sprak hem vrij bij gebrek aan bewijs.","exDe":"Der Richter sprach ihn mangels Beweisen frei."}],"usage":"Trennbares Verb (vrij + spreken); im Hauptsatz getrennt: 'spreekt ... vrij'. Unregelmäßig (sterk): sprak, vrijgesproken.","conjugation":{"presens":{"ik":"spreek vrij","jij":"spreekt vrij","hij":"spreekt vrij","wij":"spreken vrij"},"imperfectum":{"ik":"sprak vrij","wij":"spraken vrij"},"perfectum":{"aux":"hebben","participle":"vrijgesproken"}}},"bk_2397":{"lemma":"openbare orde","displayNl":"de openbare orde","pos":"uitdrukking","meanings":[{"de":"die öffentliche Ordnung (öffentliche Ruhe und Sicherheit)","ex":"De politie bewaakt de openbare orde tijdens de demonstratie.","exDe":"Die Polizei wacht während der Demonstration über die öffentliche Ordnung."}],"usage":"Feste Wortverbindung aus Verwaltung/Recht; wird fast nur im Singular mit Artikel 'de' verwendet.","genus":"de"},"bk_2398":{"lemma":"belastingdienst","displayNl":"de belastingdienst","pos":"substantief","meanings":[{"de":"das Finanzamt / die Steuerbehörde","ex":"De Belastingdienst controleert mijn aangifte.","exDe":"Das Finanzamt prüft meine Steuererklärung."}],"usage":"In den Niederlanden meist als Eigenname der nationalen Steuerbehörde ('de Belastingdienst', großgeschrieben).","genus":"de","plural":"belastingdiensten"},"bk_2399":{"lemma":"staatsburgerschap","displayNl":"het staatsburgerschap","pos":"substantief","meanings":[{"de":"die Staatsbürgerschaft / Staatsangehörigkeit","ex":"Zij vraagt het Nederlandse staatsburgerschap aan.","exDe":"Sie beantragt die niederländische Staatsbürgerschaft."}],"usage":"Abstraktes Substantiv, praktisch nur im Singular; Synonym: nationaliteit.","genus":"het"},"bk_2400":{"lemma":"verblijfsvergunning","displayNl":"de verblijfsvergunning","pos":"substantief","meanings":[{"de":"die Aufenthaltsgenehmigung / der Aufenthaltstitel","ex":"Zonder verblijfsvergunning mag hij niet werken.","exDe":"Ohne Aufenthaltsgenehmigung darf er nicht arbeiten."}],"usage":"Verwaltungsbegriff für die behördliche Erlaubnis, sich im Land aufzuhalten.","genus":"de","plural":"verblijfsvergunningen"},"bk_2401":{"lemma":"ministerie","displayNl":"het ministerie","pos":"substantief","meanings":[{"de":"das Ministerium","ex":"Het ministerie publiceert de nieuwe regels.","exDe":"Das Ministerium veröffentlicht die neuen Regeln."},{"de":"die Staatsanwaltschaft (Openbaar Ministerie)","ex":"Het Openbaar Ministerie eist een gevangenisstraf.","exDe":"Die Staatsanwaltschaft fordert eine Gefängnisstrafe."}],"usage":"Behörde/Regierungsressort; die Wendung 'Openbaar Ministerie' (OM) bezeichnet die Staatsanwaltschaft.","genus":"het","plural":"ministeries"},"bk_2402":{"lemma":"provincie","displayNl":"de provincie","pos":"substantief","meanings":[{"de":"die Provinz","ex":"Elke provincie heeft een eigen bestuur.","exDe":"Jede Provinz hat eine eigene Verwaltung."}],"usage":"Verwaltungseinheit zwischen Staat und Gemeinde; die Niederlande haben zwölf provincies.","genus":"de","plural":"provincies"},"bk_2403":{"lemma":"bestuur","displayNl":"het bestuur","pos":"substantief","meanings":[{"de":"die Verwaltung, die Regierung","ex":"Het bestuur beslist over het budget.","exDe":"Die Verwaltung entscheidet über das Budget."},{"de":"der Vorstand, die Leitung","ex":"Zij zit in het bestuur van de vereniging.","exDe":"Sie sitzt im Vorstand des Vereins."}],"usage":"Sowohl die (öffentliche) Verwaltung/Regierung als auch das Leitungsgremium einer Organisation.","genus":"het","plural":"besturen"},"bk_2404":{"lemma":"coalitie","displayNl":"de coalitie","pos":"substantief","meanings":[{"de":"die Koalition","ex":"De coalitie bestaat uit drie partijen.","exDe":"Die Koalition besteht aus drei Parteien."}],"usage":"Bündnis von Parteien, das gemeinsam die Regierung bildet (Gegenteil: oppositie).","genus":"de","plural":"coalities"},"bk_2405":{"lemma":"oppositie","displayNl":"de oppositie","pos":"substantief","meanings":[{"de":"die Opposition (Politik)","ex":"De oppositie is tegen het plan.","exDe":"Die Opposition ist gegen den Plan."},{"de":"der Widerstand, der Gegensatz","ex":"Zijn voorstel stuitte op felle oppositie.","exDe":"Sein Vorschlag stieß auf heftigen Widerstand."}],"usage":"Politisch die Nicht-Regierungsparteien; allgemeiner auch Widerstand gegen etwas.","genus":"de","plural":"opposities"},"bk_2406":{"lemma":"meerderheid","displayNl":"de meerderheid","pos":"substantief","meanings":[{"de":"die Mehrheit","ex":"De wet kreeg een ruime meerderheid.","exDe":"Das Gesetz bekam eine breite Mehrheit."}],"usage":"Der größere Teil; auch 'de meerderheid van' + Substantiv (die Mehrheit der ...).","genus":"de","plural":"meerderheden"},"bk_2407":{"lemma":"minderheid","displayNl":"de minderheid","pos":"substantief","meanings":[{"de":"die Minderheit","ex":"De minderheid stemde tegen.","exDe":"Die Minderheit stimmte dagegen."}],"usage":"Der kleinere Teil; auch für Bevölkerungsgruppen ('etnische minderheden').","genus":"de","plural":"minderheden"},"bk_2408":{"lemma":"campagne","displayNl":"de campagne","pos":"substantief","meanings":[{"de":"die Kampagne","ex":"De campagne begint voor de verkiezing.","exDe":"Die Kampagne beginnt vor der Wahl."},{"de":"der Feldzug (militärisch)","ex":"De campagne in het noorden duurde maanden.","exDe":"Der Feldzug im Norden dauerte Monate."}],"usage":"Organisierte Aktion (Wahl-, Werbe-, Spendenkampagne); historisch/militärisch auch Feldzug.","genus":"de","plural":"campagnes"},"bk_2409":{"lemma":"toespraak","displayNl":"de toespraak","pos":"substantief","meanings":[{"de":"die Rede, die Ansprache","ex":"Zijn toespraak duurde tien minuten.","exDe":"Seine Rede dauerte zehn Minuten."},{"de":"die Rede (öffentlicher Vortrag, feierlicher Anlass)","ex":"De burgemeester hield een toespraak bij de opening.","exDe":"Der Bürgermeister hielt eine Ansprache bei der Eröffnung."}],"usage":"Formelle mündliche Rede vor Publikum; 'een toespraak houden' = eine Rede halten.","genus":"de","plural":"toespraken"},"bk_2410":{"lemma":"belastingaanslag","displayNl":"de belastingaanslag","pos":"substantief","meanings":[{"de":"der Steuerbescheid, die Steuerveranlagung","ex":"De belastingaanslag kwam vandaag binnen.","exDe":"Der Steuerbescheid kam heute an."}],"usage":"Amtlicher Bescheid der Steuerbehörde (Belastingdienst) über die festgesetzte Steuer.","genus":"de","plural":"belastingaanslagen"},"bk_2411":{"lemma":"gelijkwaardigheid","displayNl":"de gelijkwaardigheid","pos":"substantief","meanings":[{"de":"die Gleichwertigkeit, die Gleichrangigkeit","ex":"Gelijkwaardigheid van mannen en vrouwen is een doel.","exDe":"Die Gleichwertigkeit von Männern und Frauen ist ein Ziel."}],"usage":"Abstraktes Substantiv (Zustand gleichen Werts/Rangs); meist ohne Plural.","genus":"de"},"bk_2412":{"lemma":"correspondentie","displayNl":"de correspondentie","pos":"substantief","meanings":[{"de":"der Schriftverkehr, der Briefwechsel","ex":"Bewaar alle correspondentie met de gemeente.","exDe":"Bewahren Sie den gesamten Schriftverkehr mit der Gemeinde auf."},{"de":"die Übereinstimmung, die Entsprechung","ex":"Er is een duidelijke correspondentie tussen de twee lijsten.","exDe":"Es gibt eine klare Entsprechung zwischen den beiden Listen."}],"usage":"Meist Schriftverkehr (Briefe/E-Mails); seltener 'Entsprechung/Übereinstimmung'.","genus":"de","plural":"correspondenties"},"bk_2413":{"lemma":"bout","displayNl":"de bout","pos":"substantief","meanings":[{"de":"der Bolzen, die Schraube (mit Gewinde)","ex":"De bout past niet in het gat.","exDe":"Der Bolzen passt nicht ins Loch."},{"de":"die Keule (Geflügelschenkel, z. B. Hähnchenkeule)","ex":"Hij at een gebakken bout van de kip.","exDe":"Er aß eine gebratene Keule vom Hähnchen."}],"usage":"Technisch: Bolzen/Schraube. Auch 'kippenbout' = Hähnchenkeule. Plural 'bouten'.","genus":"de","plural":"bouten","illustratable":true},"bk_2414":{"lemma":"moersleutel","displayNl":"de moersleutel","pos":"substantief","meanings":[{"de":"der Schraubenschlüssel, der Maulschlüssel (für Muttern)","ex":"Ik gebruik een moersleutel voor de moer.","exDe":"Ich benutze einen Schraubenschlüssel für die Mutter."}],"usage":"Werkzeug zum Lösen/Anziehen von Muttern ('moer'). Plural 'moersleutels'.","genus":"de","plural":"moersleutels","illustratable":true},"bk_2415":{"lemma":"schroefsleutel","displayNl":"de schroefsleutel","pos":"substantief","meanings":[{"de":"der Maulschlüssel, der (verstellbare) Schraubenschlüssel","ex":"De schroefsleutel ligt in de kist.","exDe":"Der Maulschlüssel liegt in der Kiste."}],"usage":"Oberbegriff/Variante für Schraubenschlüssel, oft der verstellbare Typ. Plural 'schroefsleutels'.","genus":"de","plural":"schroefsleutels","illustratable":true},"bk_2416":{"lemma":"vijl","displayNl":"de vijl","pos":"substantief","meanings":[{"de":"die Feile (Werkzeug zum Glätten/Abtragen)","ex":"Met de vijl maak ik de rand glad.","exDe":"Mit der Feile mache ich die Kante glatt."},{"de":"die Nagelfeile","ex":"Ze pakt een vijl om haar nagels bij te werken.","exDe":"Sie nimmt eine Feile, um ihre Nägel zu bearbeiten."}],"usage":"Werkzeug mit gehauener Oberfläche; auch 'nagelvijl' = Nagelfeile. Plural 'vijlen'.","genus":"de","plural":"vijlen","illustratable":true},"bk_2417":{"lemma":"beitel","displayNl":"de beitel","pos":"substantief","meanings":[{"de":"der Meißel (Werkzeug zum Bearbeiten von Holz, Stein oder Metall)","ex":"Hij bewerkt het hout met een beitel.","exDe":"Er bearbeitet das Holz mit einem Meißel."},{"de":"der Stechbeitel, das Stemmeisen (in der Holzbearbeitung)","ex":"De timmerman sloeg met de hamer op de beitel.","exDe":"Der Zimmermann schlug mit dem Hammer auf den Stechbeitel."}],"usage":"Sammelbegriff für Meißel/Stechbeisen aller Art; wird meist mit een hamer benutzt.","genus":"de","plural":"beitels","illustratable":true},"bk_2418":{"lemma":"schaaf","displayNl":"de schaaf","pos":"substantief","meanings":[{"de":"der Hobel (Werkzeug zum Glaetten von Holz)","ex":"De schaaf maakt het hout glad.","exDe":"Der Hobel macht das Holz glatt."},{"de":"die Reibe, der Hobel (in der Küche, z. B. Käse-/Gemuesehobel)","ex":"Ze snijdt de kaas met een schaaf.","exDe":"Sie schneidet den Käse mit einem Hobel."}],"usage":"Bezeichnet sowohl den Tischler-Hobel als auch den Küchen-/Käsehobel (kaasschaaf).","genus":"de","plural":"schaven","illustratable":true},"bk_2419":{"lemma":"waterpas","displayNl":"de waterpas","pos":"substantief","meanings":[{"de":"die Wasserwaage (Messwerkzeug zur Pruefung der Waagerechten)","ex":"Controleer het met de waterpas.","exDe":"Pruefe es mit der Wasserwaage."}],"usage":"Auch als Adverb/Adjektiv 'waterpas' = waagerecht (Iets ligt waterpas); als Substantiv das Werkzeug.","genus":"de","plural":"waterpassen","illustratable":true},"bk_2420":{"lemma":"duimstok","displayNl":"de duimstok","pos":"substantief","meanings":[{"de":"der Zollstock, der Gliedermassstab","ex":"Ik meet de plank met de duimstok.","exDe":"Ich messe das Brett mit dem Zollstock."}],"usage":"Klappbarer Gliedermassstab des Handwerkers; ausgeklappt zeigt er die Zentimeterskala.","genus":"de","plural":"duimstokken","illustratable":true},"bk_2421":{"lemma":"bankschroef","displayNl":"de bankschroef","pos":"substantief","meanings":[{"de":"der Schraubstock (an der Werkbank montierte Spannvorrichtung)","ex":"Zet de plank in de bankschroef.","exDe":"Spann das Brett in den Schraubstock."}],"usage":"Fest an der Werkbank montiert; haelt Werkstuecke zum Bearbeiten fest.","genus":"de","plural":"bankschroeven","illustratable":true},"bk_2422":{"lemma":"klem","displayNl":"de klem","pos":"substantief","meanings":[{"de":"die Klemme, die Zwinge, die Klammer (haelt Teile zusammen)","ex":"De klem houdt de delen bij elkaar.","exDe":"Die Klemme haelt die Teile zusammen."},{"de":"die Klemme, die Zwangslage (bildlich: in de klem zitten)","ex":"Door de schulden zit hij flink in de klem.","exDe":"Wegen der Schulden steckt er ganz schön in der Klemme."}],"usage":"Konkret das Spann-/Klemmwerkzeug; uebertragen 'in de klem zitten' = in der Klemme sitzen.","genus":"de","plural":"klemmen","illustratable":true},"bk_2423":{"lemma":"hijskraan","displayNl":"de hijskraan","pos":"substantief","meanings":[{"de":"der Kran, der Hebekran (zum Heben schwerer Lasten)","ex":"De hijskraan tilt de balken omhoog.","exDe":"Der Kran hebt die Balken hoch."}],"usage":"Bau- oder Hafenkran; 'hijsen' = hochziehen/hieven.","genus":"de","plural":"hijskranen","illustratable":true},"bk_2424":{"lemma":"schuurmachine","displayNl":"de schuurmachine","pos":"substantief","meanings":[{"de":"die Schleifmaschine, der Schleifer (elektrisches Werkzeug zum Glaetten)","ex":"Met de schuurmachine gaat het snel.","exDe":"Mit der Schleifmaschine geht es schnell."}],"usage":"Elektrisches Handwerkzeug zum Schleifen von Holz oder Metall; 'schuren' = schleifen.","genus":"de","plural":"schuurmachines","illustratable":true}};
